# ──────────────────────────────────────────────
# 响应式屏幕辅助：任意对话框可直接调用
# ──────────────────────────────────────────────
def _screen_info():
    """返回 (screen_w, screen_h, is_mobile, is_tablet, scale) 供对话框使用"""
    sc = QApplication.primaryScreen().availableGeometry()
    sw, sh = sc.width(), sc.height()
    is_mobile = sw < 600 or min(sw, sh) < 480
    is_tablet = (not is_mobile) and sw < 900
    scale = max(0.50, min(1.0, sw / 1400.0)) if not is_mobile else max(0.45, min(0.85, sw / 700.0))
    return sw, sh, is_mobile, is_tablet, scale

def _responsive_dlg_size(dlg, preferred_w=680, preferred_h=860):
    """自动调整对话框大小：手机全屏，平板近全屏，桌面按比例"""
    sw, sh, is_mobile, is_tablet, _ = _screen_info()
    if is_mobile:
        dlg.resize(sw, sh)
        try: dlg.setWindowState(Qt.WindowMaximized)
        except Exception: pass
    elif is_tablet:
        dlg.resize(min(preferred_w, int(sw * 0.97)), min(preferred_h, int(sh * 0.96)))
    else:
        dlg.resize(min(preferred_w, int(sw * 0.65)), min(preferred_h, int(sh * 0.92)))


# ── 全局响应式系统 ────────────────────────────────────────────────────────────
# 运行时缓存，避免重复计算
_RESPONSIVE_CACHE: dict = {}

def _get_ui_scale() -> float:
    """
    计算全局UI缩放比例。
    - 手机（宽<600px）：0.70~0.90
    - 平板（宽600~900px）：0.85~1.0
    - 桌面：1.0
    同时考虑物理DPI（高密度屏）。
    """
    if "scale" in _RESPONSIVE_CACHE:
        return _RESPONSIVE_CACHE["scale"]
    try:
        sc = QApplication.primaryScreen()
        geom = sc.availableGeometry()
        sw, sh = geom.width(), geom.height()
        dpi = sc.logicalDotsPerInch()
        # 取短边判断是否手机
        short = min(sw, sh)
        if short < 480 or sw < 540:          # 手机
            scale = max(0.68, min(0.88, sw / 680.0))
        elif sw < 900:                          # 平板
            scale = max(0.85, min(0.98, sw / 920.0))
        else:                                   # 桌面
            scale = 1.0
        # 高DPI屏（>160 DPI 且系统未自动缩放）额外修正
        if dpi > 160 and scale == 1.0:
            scale = min(1.0, scale * (dpi / 96.0) * 0.6 + 0.4)
        _RESPONSIVE_CACHE["scale"] = round(scale, 3)
        _RESPONSIVE_CACHE["sw"] = sw
        _RESPONSIVE_CACHE["sh"] = sh
        _RESPONSIVE_CACHE["is_mobile"] = short < 480 or sw < 540
        _RESPONSIVE_CACHE["is_tablet"] = (not _RESPONSIVE_CACHE["is_mobile"]) and sw < 900
    except Exception:
        _RESPONSIVE_CACHE["scale"] = 1.0
        _RESPONSIVE_CACHE["sw"] = 1280
        _RESPONSIVE_CACHE["sh"] = 800
        _RESPONSIVE_CACHE["is_mobile"] = False
        _RESPONSIVE_CACHE["is_tablet"] = False
    return _RESPONSIVE_CACHE["scale"]

def _sc(px: int) -> int:
    """缩放像素值（整数），供 setFixedSize / setMinimumWidth 等调用"""
    return max(1, int(round(px * _get_ui_scale())))


def _apply_global_stylesheet(app):
    """
    根据屏幕尺寸向 QApplication 注入全局样式，统一调整：
    - 所有按钮/标签/输入框的字体大小
    - 按钮最小高度（触屏友好）
    - 滚动条宽度
    """
    scale = _get_ui_scale()
    is_mobile = _RESPONSIVE_CACHE.get("is_mobile", False)
    is_tablet = _RESPONSIVE_CACHE.get("is_tablet", False)
    if not (is_mobile or is_tablet):
        return  # 桌面不注入全局样式，保持原样

    btn_h   = _sc(36) if is_mobile else _sc(32)
    fs_btn  = _sc(13) if is_mobile else _sc(12)
    fs_lbl  = _sc(12) if is_mobile else _sc(11)
    fs_inp  = _sc(12) if is_mobile else _sc(11)
    scroll_w = _sc(14) if is_mobile else _sc(10)
    tab_h   = _sc(38) if is_mobile else _sc(32)
    chk_sz  = _sc(18) if is_mobile else _sc(16)
    sb_arr  = _sc(14) if is_mobile else _sc(12)

    qss = f"""
QWidget {{
    font-size: {fs_lbl}px;
}}
QPushButton {{
    font-size: {fs_btn}px;
    min-height: {btn_h}px;
    padding: {_sc(4)}px {_sc(6)}px;
}}
QLabel {{
    font-size: {fs_lbl}px;
}}
QLineEdit, QTextEdit, QPlainTextEdit {{
    font-size: {fs_inp}px;
    min-height: {_sc(28)}px;
}}
QComboBox {{
    font-size: {fs_inp}px;
    min-height: {_sc(28)}px;
}}
QSpinBox, QDoubleSpinBox {{
    font-size: {fs_inp}px;
    min-height: {_sc(28)}px;
}}
QTabBar::tab {{
    font-size: {fs_lbl}px;
    min-height: {tab_h}px;
    min-width: {_sc(50)}px;
    padding: {_sc(4)}px {_sc(8)}px;
}}
QCheckBox, QRadioButton {{
    font-size: {fs_lbl}px;
    spacing: {_sc(5)}px;
}}
QCheckBox::indicator, QRadioButton::indicator {{
    width: {chk_sz}px;
    height: {chk_sz}px;
}}
QScrollBar:vertical {{
    width: {scroll_w}px;
}}
QScrollBar:horizontal {{
    height: {scroll_w}px;
}}
QScrollBar::sub-line, QScrollBar::add-line {{
    height: {sb_arr}px;
    width: {sb_arr}px;
}}
QHeaderView::section {{
    font-size: {fs_lbl}px;
    padding: {_sc(3)}px;
    min-height: {_sc(26)}px;
}}
QTableWidget QTableWidgetItem {{
    font-size: {fs_lbl}px;
}}
QGroupBox {{
    font-size: {fs_lbl}px;
    margin-top: {_sc(8)}px;
}}
QGroupBox::title {{
    font-size: {fs_lbl}px;
}}
QListWidget {{
    font-size: {fs_lbl}px;
}}
QMenuBar {{
    font-size: {fs_lbl}px;
}}
QMenu {{
    font-size: {fs_lbl}px;
}}
QToolButton {{
    font-size: {fs_btn}px;
    min-height: {btn_h}px;
}}
"""
    app.setStyleSheet(app.styleSheet() + qss)

def _auto_size_dialog(dlg, preferred_w=700, preferred_h=900):
    """
    在任意 QDialog 创建时调用，自动适配屏幕尺寸。
    手机：全屏/最大化
    平板：97% × 96%
    桌面：preferred 尺寸（不超过屏幕65%×92%）
    """
    sw = _RESPONSIVE_CACHE.get("sw", 1280)
    sh = _RESPONSIVE_CACHE.get("sh", 800)
    is_mobile = _RESPONSIVE_CACHE.get("is_mobile", False)
    is_tablet = _RESPONSIVE_CACHE.get("is_tablet", False)
    if is_mobile:
        dlg.setMinimumSize(sw, sh)
        dlg.resize(sw, sh)
        try:
            dlg.setWindowState(Qt.WindowMaximized)
        except Exception:
            pass
    elif is_tablet:
        w = min(preferred_w, int(sw * 0.97))
        h = min(preferred_h, int(sh * 0.96))
        dlg.resize(w, h)
    else:
        w = min(preferred_w, int(sw * 0.68))
        h = min(preferred_h, int(sh * 0.92))
        dlg.resize(w, h)

_ORIG_QDIALOG_INIT = None

def _patch_qdialog_for_mobile():
    """
    在手机/平板模式下，monkey-patch QDialog.__init__ 使所有对话框
    自动最大化/全屏，无需逐个修改。
    """
    is_mobile = _RESPONSIVE_CACHE.get("is_mobile", False)
    is_tablet = _RESPONSIVE_CACHE.get("is_tablet", False)
    if not (is_mobile or is_tablet):
        return
    import PySide6.QtWidgets as _qw
    orig_init = _qw.QDialog.__init__
    sw = _RESPONSIVE_CACHE.get("sw", 1280)
    sh = _RESPONSIVE_CACHE.get("sh", 800)

    def _patched_init(self, parent=None, flags=Qt.WindowFlags()):
        try:
            orig_init(self, parent, flags)
        except TypeError:
            orig_init(self, parent)
        if is_mobile:
            try:
                self.resize(sw, sh)
                self.setWindowState(Qt.WindowMaximized)
            except Exception:
                pass
        elif is_tablet:
            try:
                self.resize(int(sw * 0.97), int(sh * 0.96))
            except Exception:
                pass

    _qw.QDialog.__init__ = _patched_init



