# ── Scrapling 自适应爬虫模块（无需API密钥，直接抓取彩票官网数据）──────────────
# ══════════════════════════════════════════════════════════════════════════════

def _ensure_scrapling():
    """确保 scrapling[fetchers] 已安装，否则尝试自动安装"""
    try:
        from scrapling.fetchers import Fetcher
        return True
    except ImportError:
        pass
    try:
        import subprocess, sys
        subprocess.check_call(
            [sys.executable, "-m", "pip", "install", "scrapling[fetchers]",
             "--break-system-packages", "-q"],
            timeout=120
        )
        from scrapling.fetchers import Fetcher
        return True
    except Exception as e:
        logger.warning(f"Scrapling 安装失败: {e}")
        return False


def build_prediction_from_history(game_type, records, n_preds=8):
    """基于极速API本地历史数据生成预测参考（替代爬网站，永不网络出错）。
    返回结构与原 fetch_prediction_reference 兼容：
      {recent_records, hot_nums, cold_nums, high_omission, advice_nums,
       freq_map, omission_map, multi_predictions, source}
    """
    import re as _re
    from collections import Counter
    if not records:
        return {}
    all_nums = []
    for rec in records:
        ns = str(rec.get("开奖号码", "")).replace("+", " ")
        nums = [int(x) for x in _re.findall(r"\d+", ns)]
        if nums:
            all_nums.append(nums)
    if not all_nums:
        return {"recent_records": records, "source": "极速API历史"}

    flat = [n for row in all_nums for n in row]
    freq = Counter(flat)
    sorted_by_freq = sorted(freq, key=lambda x: -freq[x])
    hot_n = min(10, max(1, len(sorted_by_freq) // 3))
    hot_nums = sorted_by_freq[:hot_n]
    cold_nums = sorted_by_freq[-hot_n:]

    # 当前遗漏（从最近期向前数第一次出现的位置）
    last_appeared = {}
    for i, row in enumerate(all_nums):
        for n in row:
            if n not in last_appeared:
                last_appeared[n] = i
    omission = {n: last_appeared.get(n, len(all_nums)) for n in freq}
    high_omission = sorted(omission, key=lambda x: -omission[x])[:10]
    advice_nums = sorted(set(hot_nums[:5] + high_omission[:5]))

    # 复用已有多算法预测（纯计算）
    try:
        multi = ScraplingLotteryFetcher._algo_predict_multiple(game_type, all_nums, n_groups=n_preds)
    except Exception:
        multi = []

    # 第三方预测网站只在智能预测页异步抓取；失败不影响本地预测
    try:
        ScraplingLotteryFetcher._score_records = records
        site_predictions = ScraplingLotteryFetcher.fetch_prediction_sites(game_type)
    except Exception:
        site_predictions = []

    # 综合推荐：本地模型50% + 第三方来源30% + 冷热遗漏20%
    try:
        score = Counter()
        for n in advice_nums:
            score[n] += 0.20
        for pred in multi:
            for n in pred.get("main", []):
                score[n] += 0.50 / max(1, len(multi))
        for sp in site_predictions:
            w = float(sp.get("weight", 0.5) or 0.5)
            nums = [x for x in sp.get("numbers", []) if isinstance(x, int) and x != 0]
            for n in nums:
                score[n] += 0.30 * w / max(1, len(site_predictions))
        integrated_nums = [n for n, _ in score.most_common(20)]
    except Exception:
        integrated_nums = advice_nums

    return {
        "recent_records": records,
        "hot_nums": hot_nums,
        "cold_nums": cold_nums,
        "high_omission": high_omission,
        "advice_nums": advice_nums,
        "freq_map": dict(freq),
        "omission_map": omission,
        "multi_predictions": multi,
        "site_predictions": site_predictions,
        "integrated_nums": integrated_nums,
        "source": "极速API历史数据（本地训练50%）+ 第三方网站评分30% + 冷热遗漏20%",
    }


class ScraplingLotteryFetcher:
    """
    基于 Scrapling 框架的彩票历史数据爬虫。
    无需 API 密钥，直接抓取中国福彩/体彩官网及备用源。

    数据源优先级（每种彩票）：
      1. 中国福利彩票官网 cwl.gov.cn   (福彩：双色球/3D/七乐彩/快乐8)
      2. 中国体育彩票官网 sporttery.cn  (体彩：大乐透/七星彩/排列三/五)
      3. 中彩网 zhcw.com               (通用备用)
      4. 500彩票 kaijiang.500.com       (通用备用)
      5. 腾讯新闻彩票 API               (额外备用)
    """

    # 各彩票在各数据源的参数配置
    _CWL_NAME_MAP = {
        "双色球": "ssq",
        "3D":    "3d",
        "七乐彩": "7lc",
        "快乐8":  "kl8",
    }

    _SPORTTERY_GAMENO_MAP = {
        "大乐透": "85",
        "七星彩": "qxc",
        "排列三": "pl3",
        "排列五": "pl5",
    }

    _500_CODE_MAP = {
        "双色球": "ssq",
        "3D":    "3d",
        "七乐彩": "7lc",
        "快乐8":  "kl8",
        "大乐透": "dlt",
        "七星彩": "qxc",
        "排列三": "pl3",
        "排列五": "pl5",
    }

    _ZHCW_CODE_MAP = {
        "双色球": "ssq",
        "3D":    "3d",
        "七乐彩": "qlc",
        "快乐8":  "kl8",
        "大乐透": "dlt",
        "七星彩": "qxc",
        "排列三": "pl3",
        "排列五": "pl5",
    }

    @classmethod
    def _get_fetcher(cls):
        """获取 Scrapling Fetcher 实例（自适应降级）"""
        try:
            from scrapling.fetchers import Fetcher
            return Fetcher
        except ImportError:
            if _ensure_scrapling():
                from scrapling.fetchers import Fetcher
                return Fetcher
            return None

    @classmethod
    def _scrapling_get(cls, url: str, headers: dict = None, params: dict = None,
                       timeout: int = 8, impersonate: str = "chrome") -> str:
        """使用 Scrapling Fetcher 发起 GET 请求，返回响应文本"""
        Fetcher = cls._get_fetcher()
        if Fetcher is None:
            # 最终降级到 requests
            import requests as _r
            h = {
                "User-Agent": "Mozilla/5.0 (Linux; Android 14; Pixel 8) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Mobile Safari/537.36",
                "Accept": "application/json,*/*",
                "Accept-Language": "zh-CN,zh;q=0.9",
            }
            if headers: h.update(headers)
            resp = _r.get(url, params=params, headers=h, timeout=timeout)
            return resp.text if resp.status_code == 200 else ""

        extra_headers = {
            "Accept": "application/json, text/plain, */*",
            "Accept-Language": "zh-CN,zh;q=0.9,en;q=0.8",
            "Cache-Control": "no-cache",
        }
        if headers:
            extra_headers.update(headers)

        full_url = url
        if params:
            from urllib.parse import urlencode
            full_url = url + ("&" if "?" in url else "?") + urlencode(params)

        resp = Fetcher.get(
            full_url,
            headers=extra_headers,
            timeout=timeout,
            stealthy_headers=True,
            impersonate=impersonate,
        )
        if resp and resp.status in (200, 201):
            return resp.text or ""
        return ""

    @classmethod
    def fetch_cwl(cls, game_type: str, count: int = 50) -> list:
        """
        抓取中国福利彩票官网 cwl.gov.cn JSON 接口。
        支持：双色球、3D、七乐彩、快乐8
        返回标准化记录列表。
        """
        import json, re
        name = cls._CWL_NAME_MAP.get(game_type)
        if not name:
            return []

        urls = [
            f"https://www.cwl.gov.cn/cwl_admin/front/cwlkj/search/kjxx/findDrawNotice?name={name}&issueCount={count}&issueStart=&issueEnd=&dayStart=&dayEnd=",
            f"https://www.cwl.gov.cn/cwl_admin/front/cwlkj/search/kjxx/findDynamicNotice?name={name}&issueCount={count}",
        ]
        hdrs = {
            "Referer": f"https://www.cwl.gov.cn/kjxx/{name}/kjgg/",
            "Origin":  "https://www.cwl.gov.cn",
        }

        for url in urls:
            try:
                text = cls._scrapling_get(url, headers=hdrs, timeout=8)
                if not text:
                    continue
                data = json.loads(text)
                items = data.get("result", data.get("list", data.get("data", [])))
                if not isinstance(items, list) or not items:
                    continue

                records = []
                for item in items:
                    # CWL API 字段：code=期号, date=日期, red=红球(逗号分隔), blue=蓝球, sales=销售额
                    issue    = str(item.get("code", item.get("issueno", item.get("期号", ""))))
                    date_str = str(item.get("date", item.get("opendate", "")))[:10]
                    reds_raw = item.get("red", item.get("reds", item.get("number", "")))
                    blue_raw = item.get("blue", item.get("refernumber", ""))
                    # 兼容不同格式（reds 可能是 "01,02,03,04,05,06" 或空格分隔）
                    if isinstance(reds_raw, list):
                        reds = " ".join(str(x) for x in reds_raw)
                    else:
                        reds = str(reds_raw).replace(",", " ").strip()
                    blue = str(blue_raw).replace(",", " ").strip() if blue_raw else ""
                    # 合并号码
                    if blue and blue not in ("", "0", "null", "None"):
                        nums = f"{reds}+{blue}"
                    else:
                        nums = reds
                    sales = str(item.get("sales", item.get("saleamount", "")))
                    if issue and nums:
                        records.append({
                            "期号": issue,
                            "开奖日期": date_str,
                            "开奖号码": nums,
                            "参考号码": blue,
                            "销售额": sales,
                            "来源": "cwl.gov.cn(Scrapling)",
                        })
                if records:
                    logger.info(f"ScraplingFetcher.fetch_cwl {game_type}: {len(records)}期 from {url[:60]}")
                    return records
            except Exception as e:
                logger.debug(f"ScraplingFetcher.fetch_cwl {game_type} {url[:60]}: {e}")
        return []

    @classmethod
    def fetch_sporttery(cls, game_type: str, count: int = 50) -> list:
        """
        抓取中国体育彩票官网 sporttery.cn JSON 接口。
        支持：大乐透、七星彩、排列三、排列五
        """
        import json
        gameno = cls._SPORTTERY_GAMENO_MAP.get(game_type)
        if not gameno:
            return []

        page_size = min(count, 30)
        urls = [
            f"https://webapi.sporttery.cn/gateway/lottery/getHistoryPageListV1.qry?gameNo={gameno}&provinceId=0&pageSize={page_size}&isVerify=1&pageNo=1",
            f"https://webapi.sporttery.cn/gateway/lottery/getHistoryPageListV1.qry?gameNo={gameno}&pageSize={page_size}&pageNo=1",
        ]
        hdrs = {
            "Referer": "https://www.sporttery.cn/",
            "Origin":  "https://www.sporttery.cn",
        }

        for url in urls:
            try:
                text = cls._scrapling_get(url, headers=hdrs, timeout=8)
                if not text:
                    continue
                data = json.loads(text)
                items = (data.get("value", {}).get("list", []) or
                         data.get("data", {}).get("list", []) or
                         data.get("list", []))
                if not items:
                    continue

                records = []
                for item in items[:count]:
                    issue    = str(item.get("lotteryDrawNum", item.get("issueNo", "")))
                    date_str = str(item.get("lotteryDrawTime", item.get("drawDate", "")))[:10]
                    raw      = item.get("lotteryDrawResult", item.get("drawResult", ""))
                    nums     = str(raw).replace(",", " ").strip() if raw else ""
                    # 体彩大乐透：前5个是前区，后2个是后区，用+分隔更直观
                    if game_type == "大乐透" and nums:
                        parts = nums.split()
                        if len(parts) == 7:
                            nums = " ".join(parts[:5]) + "+" + " ".join(parts[5:])
                    sale = str(item.get("totalSaleAmount", item.get("saleAmount", "")))
                    if issue and nums:
                        records.append({
                            "期号": issue,
                            "开奖日期": date_str,
                            "开奖号码": nums,
                            "销售额": sale,
                            "来源": "sporttery.cn(Scrapling)",
                        })
                if records:
                    logger.info(f"ScraplingFetcher.fetch_sporttery {game_type}: {len(records)}期 from {url[:60]}")
                    return records
            except Exception as e:
                logger.debug(f"ScraplingFetcher.fetch_sporttery {game_type} {url[:60]}: {e}")
        return []

    @classmethod
    def fetch_500(cls, game_type: str, count: int = 50) -> list:
        """
        抓取 500彩票 kaijiang.500.com 静态JSON文件。
        兼容所有数字彩票。
        """
        import json
        from datetime import datetime as _dt
        code = cls._500_CODE_MAP.get(game_type)
        if not code:
            return []

        cur_year = _dt.now().year
        urls = [
            f"https://kaijiang.500.com/static/{code}/{cur_year}.json",
            f"https://kaijiang.500.com/static/{code}/{cur_year - 1}.json",
            f"https://datachart.500.com/{code}/history/newinc/history.php?limit={count}&json=1",
        ]
        hdrs = {
            "Referer": f"https://kaijiang.500.com/{code}.shtml",
        }

        for url in urls:
            try:
                text = cls._scrapling_get(url, headers=hdrs, timeout=15)
                if not text:
                    continue
                try:
                    data = json.loads(text.lstrip("\ufeff").strip())
                except Exception:
                    continue
                items = data.get("list", data.get("data", data if isinstance(data, list) else []))
                if not isinstance(items, list) or not items:
                    continue

                records = []
                for item in (items[:count] if isinstance(items, list) else []):
                    if not isinstance(item, dict):
                        continue
                    issue    = str(item.get("issue", item.get("期号", item.get("no", ""))))
                    date_str = str(item.get("date", item.get("开奖日期", item.get("time", ""))))[:10]
                    nums     = str(item.get("result", item.get("开奖号码", item.get("winning", "")))).replace(",", " ").strip()
                    if issue and nums and nums not in ("None", "null", ""):
                        records.append({
                            "期号": issue,
                            "开奖日期": date_str,
                            "开奖号码": nums,
                            "来源": "kaijiang.500.com(Scrapling)",
                        })
                if records:
                    logger.info(f"ScraplingFetcher.fetch_500 {game_type}: {len(records)}期 from {url[:60]}")
                    return records
            except Exception as e:
                logger.debug(f"ScraplingFetcher.fetch_500 {game_type} {url[:60]}: {e}")
        return []

