    @classmethod
    def fetch(cls, game_type: str, count: int = 50) -> list:
        """已禁用：不再使用第三方开奖数据源。"""
        return []

    @classmethod
    def fetch_prediction_sites(cls, game_type: str) -> list:
        """
        抓取第三方预测网站（只用于“智能预测推荐”的网站预测汇总，不用于开奖更新）。
        V74: 多网站 + 来源评分 + 模型排行榜 + 动态融合权重版。
        - 多源：中彩网/500/新浪爱彩/澳客/一定牛/一起彩/彩吧助手/彩经网等公开页。
        - 只抓预测、推荐、胆码、复式、胆拖、专家类公开内容。
        - 自动过滤开奖、走势图、遗漏表、杀码/杀号等干扰内容。
        - 每个来源返回 score_30/score_50/score_100 和 weight，供综合预测加权。
        """
        import re as _re
        import html as _html
        import time as _time
        from urllib.parse import urljoin as _urljoin, quote as _quote

        def _http_get(url: str, timeout: int = 4) -> str:
            try:
                import requests as _requests
                headers = {
                    "User-Agent": "Mozilla/5.0 (Linux; Android 14) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0 Mobile Safari/537.36",
                    "Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",
                    "Accept-Language": "zh-CN,zh;q=0.9",
                    "Connection": "close",
                    "Cache-Control": "no-cache",
                }
                r = _requests.get(url, headers=headers, timeout=timeout)
                if getattr(r, "encoding", None) in (None, "ISO-8859-1"):
                    r.encoding = r.apparent_encoding or "utf-8"
                return r.text if r.status_code == 200 else ""
            except Exception as e:
                logger.debug(f"第三方预测抓取失败 {url}: {e}")
                return ""

        def _strip_tags(text: str) -> str:
            text = _re.sub(r"<script[\s\S]*?</script>|<style[\s\S]*?</style>|<noscript[\s\S]*?</noscript>", " ", text, flags=_re.I)
            text = _re.sub(r"<br\s*/?>|</p>|</div>|</li>|</tr>", "\n", text, flags=_re.I)
            text = _re.sub(r"<[^>]+>", " ", text)
            return _html.unescape(text)

        def _game_alias(gt: str):
            return {
                "双色球": ["双色球", "ssq", "shuangseqiu"],
                "大乐透": ["大乐透", "dlt", "daletou"],
                "快乐8":  ["快乐8", "快乐八", "kl8", "kuaile8"],
                "七乐彩": ["七乐彩", "qlc", "qilecai"],
                "3D":    ["福彩3D", "3D", "fc3d"],
                "排列三": ["排列三", "pl3"],
                "排列五": ["排列五", "pl5"],
                "七星彩": ["七星彩", "qxc"],
            }.get(gt, [gt])

        def _game_limits(gt: str):
            if gt == "双色球": return 1, 33, 6, 16, 1, True
            if gt == "大乐透": return 1, 35, 5, 12, 2, True
            if gt == "快乐8":  return 1, 80, 10, 0, 0, False
            if gt == "七乐彩": return 1, 30, 7, 0, 0, False
            if gt in ("3D", "排列三"): return 0, 9, 3, 0, 0, False
            if gt == "排列五": return 0, 9, 5, 0, 0, False
            if gt == "七星彩": return 0, 14, 7, 0, 0, False
            return 1, 80, 10, 0, 0, False

        def _valid_nums(nums, lo, hi, max_keep=30):
            out = []
            for n in nums:
                try: n = int(n)
                except Exception: continue
                if lo <= n <= hi and n not in out:
                    out.append(n)
                if len(out) >= max_keep:
                    break
            return out

        def _extract_links(list_html: str, base_url: str, limit: int = 10) -> list:
            links = []
            for href, title in _re.findall(r'<a[^>]+href=["\']([^"\']+)["\'][^>]*>([\s\S]*?)</a>', list_html, flags=_re.I):
                title_txt = _strip_tags(title).strip()
                if not title_txt:
                    continue
                if not _re.search(r"预测|推荐|胆码|定胆|复式|胆拖|精选|专家|杀号定胆|心水|单挑|杀号", title_txt):
                    continue
                if _re.search(r"开奖|走势图|遗漏|查询|尾数分布|统计表|直播|回看|试机号|开机号|规则|奖池", title_txt):
                    continue
                full = _urljoin(base_url, href)
                if full not in [u for u, _ in links]:
                    links.append((full, title_txt[:36]))
                if len(links) >= limit:
                    break
            return links

        def _extract_prediction_numbers(text: str, gt: str) -> list:
            lo, hi, main_need, sub_hi, sub_need, has_sub = _game_limits(gt)
            clean = _strip_tags(text)
            clean = clean.replace("，", ",").replace("；", ";").replace("＋", "+").replace("｜", "|")
            # 删除期号/日期/时间/金额/浏览量，避免干扰
            clean = _re.sub(r"20\d{5,8}|\d{4}[-/]\d{1,2}[-/]\d{1,2}|\d{1,2}:\d{1,2}(:\d{1,2})?|\d+元|阅读\d+|浏览\d+", " ", clean)
            # 把“第1注/第2组/5+2/→3注”这类说明清除
            clean = _re.sub(r"第\s*\d+\s*(?:注|组|期|位|张)|\d+\s*[+＋]\s*\d+|[→=]\s*\d+\s*注", " ", clean)
            key_pat = r".{0,18}(?:推荐|预测|号码|胆码|定胆|复式|胆拖|精选|前区|后区|红球|蓝球|单挑|杀号定胆|胆码推荐).{0,110}"
            snippets = _re.findall(key_pat, clean)
            if not snippets:
                snippets = [clean[:1800]]
            candidates = []
            for sn in snippets[:18]:
                # 纯杀号/杀码不要参与；“杀号定胆”保留胆码部分
                if _re.search(r"杀码|杀号|排除", sn) and not _re.search(r"杀号定胆|杀码定胆|定胆", sn):
                    continue
                # 主副区优先按关键词区分
                if has_sub:
                    main_nums = []
                    sub_nums = []
                    m1 = _re.search(r"(?:红球|前区|前区号码|红码)[：:\s]*([\d\s,，、\-+|]+)", sn)
                    m2 = _re.search(r"(?:蓝球|后区|后区号码|蓝码)[：:\s]*([\d\s,，、\-+|]+)", sn)
                    if m1:
                        main_nums = _valid_nums(_re.findall(r"(?<!\d)\d{1,2}(?!\d)", m1.group(1)), lo, hi, 18)
                    if m2:
                        sub_nums = _valid_nums(_re.findall(r"(?<!\d)\d{1,2}(?!\d)", m2.group(1)), 1, sub_hi, 8)
                    if not main_nums:
                        nums = [int(x) for x in _re.findall(r"(?<!\d)\d{1,2}(?!\d)", sn)]
                        main_nums = _valid_nums(nums, lo, hi, 18)
                        sub_nums = _valid_nums(nums, 1, sub_hi, 8)
                    if len(main_nums) >= min(main_need, 5):
                        candidates.append((main_nums, sub_nums))
                elif gt in ("3D", "排列三", "排列五", "七星彩"):
                    compact = _re.findall(r"(?<!\d)\d{3,8}(?!\d)", sn)
                    for ck in compact:
                        if gt in ("3D", "排列三") and len(ck) == 3:
                            candidates.append(([int(ch) for ch in ck], []))
                        elif gt == "排列五" and len(ck) == 5:
                            candidates.append(([int(ch) for ch in ck], []))
                        elif gt == "七星彩":
                            if len(ck) == 7:
                                candidates.append(([int(ch) for ch in ck], []))
                            elif len(ck) == 8:
                                head = [int(ch) for ch in ck[:6]]; tail = int(ck[6:])
                                if 0 <= tail <= 14:
                                    candidates.append((head + [tail], []))
                    nums = [int(x) for x in _re.findall(r"(?<!\d)\d{1,2}(?!\d)", sn)]
                    need = 7 if gt == "七星彩" else (5 if gt == "排列五" else 3)
                    if gt == "七星彩":
                        # 七星彩彩票：前6位只能是0-9，第7位可以是0-14，不能把10-14放进前6位。
                        if len(nums) >= 7:
                            q = nums[:7]
                            if all(0 <= x <= 9 for x in q[:6]) and 0 <= q[6] <= 14:
                                candidates.append((q, []))
                    else:
                        nums2 = _valid_nums(nums, lo, hi, 12)
                        if len(nums2) >= need:
                            candidates.append((nums2[:need], []))
                else:
                    nums = [int(x) for x in _re.findall(r"(?<!\d)\d{1,2}(?!\d)", sn)]
                    nums2 = _valid_nums(nums, lo, hi, 30)
                    need = 10 if gt == "快乐8" else main_need
                    if len(nums2) >= min(need, 5):
                        candidates.append((nums2, []))
            if not candidates:
                return []
            candidates.sort(key=lambda x: (len(x[0]), len(x[1])), reverse=True)
            best_main, best_sub = candidates[0]
            return best_main + ([0] + best_sub if has_sub and best_sub else [])

        def _site_score(nums: list, gt: str, n: int = 30) -> float:
            # 用最近历史的平均重合度估算来源质量；真正历史命中率会随着后续保存日志逐步校准。
            try:
                records = getattr(cls, "_score_records", []) or []
                if not nums or not records: return 0.50
                lo, hi, main_need, sub_hi, sub_need, has_sub = _game_limits(gt)
                if has_sub and 0 in nums:
                    z = nums.index(0); main_nums = set(nums[:z]); sub_nums = set(nums[z+1:])
                else:
                    main_nums = set(nums); sub_nums = set()
                vals = []
                for rec in records[:n]:
                    raw = str(rec.get("开奖号码", "")).replace("+", " ").replace("|", " ")
                    draw = [int(x) for x in _re.findall(r"\d+", raw)]
                    if not draw: continue
                    if gt == "双色球" and len(draw) >= 7:
                        dm, ds = set(draw[:6]), set(draw[6:7]); denom = 7
                        hit = len(main_nums & dm) + len(sub_nums & ds)
                    elif gt == "大乐透" and len(draw) >= 7:
                        dm, ds = set(draw[:5]), set(draw[5:7]); denom = 7
                        hit = len(main_nums & dm) + len(sub_nums & ds)
                    elif gt in ("3D", "排列三", "排列五", "七星彩"):
                        pred = list(nums); denom = min(len(pred), len(draw)) or 1
                        hit = sum(1 for a,b in zip(pred, draw) if int(a) == int(b))
                    else:
                        dm = set(draw); denom = max(1, min(len(main_nums), len(dm)))
                        hit = len(main_nums & dm)
                    vals.append(hit / max(1, denom))
                if not vals: return 0.50
                # 映射到 0.3~1.0，避免一个源完全失权
                avg = sum(vals) / len(vals)
                return max(0.30, min(1.00, 0.35 + avg * 2.2))
            except Exception:
                return 0.50

        def _start_pages(gt: str) -> list:
            ydniu = {"双色球":"ssq", "大乐透":"dlt", "快乐8":"kl8", "七乐彩":"qlc", "3D":"fc3d", "排列三":"pl3", "排列五":"pl5", "七星彩":"qxc"}
            yiqi = {"快乐8":"klb", "双色球":"ssq", "大乐透":"dlt", "七乐彩":"qlc", "3D":"fc3d", "排列三":"pl3", "排列五":"pl5", "七星彩":"qxc"}
            code500 = {"双色球":"ssq", "大乐透":"dlt", "快乐8":"kl8", "七乐彩":"qlc", "3D":"sd", "排列三":"pl3", "排列五":"pl5", "七星彩":"qxc"}
            aliases = _game_alias(gt)
            q = _quote(aliases[0] + " 预测 推荐")
            pages = []
            if gt in ydniu: pages.append(("一定牛", f"https://www.ydniu.com/info/{ydniu[gt]}/cpyc/"))
            if gt in yiqi: pages.append(("一起彩", f"https://www.yiqicai.com/{yiqi[gt]}/"))
            if gt in code500:
                pages.append(("500彩票网", f"https://datachart.500.com/{code500[gt]}/"))
                pages.append(("500彩票搜索", f"https://www.500.com/search/?q={q}"))
            pages.extend([
                ("中彩网搜索", f"https://www.zhcw.com/search/index?keyword={q}"),
                ("新浪爱彩搜索", f"https://lottery.sina.com.cn/search?keyword={q}"),
                ("澳客搜索", f"https://www.okooo.com/search/?q={q}"),
                ("彩吧助手搜索", f"https://www.55125.cn/search/?keyword={q}"),
                ("彩经网搜索", f"https://www.cjcp.com.cn/search?keyword={q}"),
            ])
            return pages[:9]

        results, seen_urls = [], set()
        start_pages = _start_pages(game_type)
        for site_name, url in start_pages:
            if len(results) >= 10:
                break
            html = _http_get(url, timeout=4)
            if not html:
                continue
            nums = _extract_prediction_numbers(html, game_type)
            if nums:
                s30 = _site_score(nums, game_type, 30); s50 = _site_score(nums, game_type, 50); s100 = _site_score(nums, game_type, 100)
                results.append({"source": f"{site_name}列表页", "numbers": nums, "type": "pred", "score_30": round(s30,3), "score_50": round(s50,3), "score_100": round(s100,3), "weight": round((s30+s50+s100)/3,3)})
            links = _extract_links(html, url, limit=8)
            for article_url, title in links[:5]:
                if len(results) >= 10:
                    break
                if article_url in seen_urls:
                    continue
                seen_urls.add(article_url)
                art_html = _http_get(article_url, timeout=4)
                if not art_html:
                    continue
                nums = _extract_prediction_numbers(art_html, game_type)
                if not nums:
                    continue
                s30 = _site_score(nums, game_type, 30); s50 = _site_score(nums, game_type, 50); s100 = _site_score(nums, game_type, 100)
                results.append({"source": f"{site_name}: {title[:18]}", "numbers": nums, "type": "pred", "score_30": round(s30,3), "score_50": round(s50,3), "score_100": round(s100,3), "weight": round((s30+s50+s100)/3,3)})
                _time.sleep(0.03)

        # 去重并保存抓取日志，后续可以用于真实历史命中率校准
        dedup, seen = [], set()
        for r in results:
            key = (tuple(r.get("numbers", [])), r.get("source", "")[:8])
            if key and key not in seen:
                seen.add(key); dedup.append(r)
        try:
            old = []
            if SITE_PREDICTION_LOG_FILE.exists():
                old = json.loads(SITE_PREDICTION_LOG_FILE.read_text(encoding="utf-8"))
                if not isinstance(old, list): old = []
            old.append({"time": datetime.now().strftime("%Y-%m-%d %H:%M:%S"), "game": game_type, "items": dedup[:10]})
            SITE_PREDICTION_LOG_FILE.write_text(json.dumps(old[-300:], ensure_ascii=False, indent=2), encoding="utf-8")
        except Exception:
            pass
        return dedup[:10]

    @classmethod
    def _algo_predict_multiple(cls, game_type: str, all_nums: list, n_groups: int = 5) -> list:
        """
        基于历史开奖数据，用多种算法生成n_groups组预测号码。
        返回: [{"algo": ..., "numbers": ..., "sub": ...}, ...]
        """
        import random as _rnd
        from collections import Counter
        predictions = []
        if not all_nums:
            return predictions

        flat = [n for row in all_nums for n in row]
        freq = Counter(flat)
        total_balls = len(flat) / max(1, len(all_nums))

        # 各玩法主/副区配置
        game_cfg = {
            "双色球": {"main_max": 33, "main_n": 6, "sub_max": 16, "sub_n": 1, "has_sub": True},
            "大乐透": {"main_max": 35, "main_n": 5, "sub_max": 12, "sub_n": 2, "has_sub": True},
            "快乐8":  {"main_max": 80, "main_n": 20,"sub_max": 0,  "sub_n": 0, "has_sub": False},
            "七乐彩": {"main_max": 30, "main_n": 7, "sub_max": 0,  "sub_n": 0, "has_sub": False},
            "七星彩": {"main_max": 9,  "main_n": 7, "sub_max": 0,  "sub_n": 0, "has_sub": False},
            "3D":    {"main_max": 9,  "main_n": 3, "sub_max": 0,  "sub_n": 0, "has_sub": False},
            "排列三": {"main_max": 9,  "main_n": 3, "sub_max": 0,  "sub_n": 0, "has_sub": False},
            "排列五": {"main_max": 9,  "main_n": 5, "sub_max": 0,  "sub_n": 0, "has_sub": False},
        }
        cfg = game_cfg.get(game_type, {"main_max": 33, "main_n": 6, "sub_max": 16, "sub_n": 1, "has_sub": True})
        main_max = cfg["main_max"]
        main_n   = cfg["main_n"]
        all_main = list(range(1, main_max + 1))

        # 各号遗漏期数
        last_app = {}
        for i, row in enumerate(all_nums):
            for n in row:
                if n not in last_app:
                    last_app[n] = i
        omit = {n: last_app.get(n, len(all_nums)) for n in all_main}

        sorted_by_freq = sorted(all_main, key=lambda x: -freq.get(x, 0))
        sorted_by_omit = sorted(all_main, key=lambda x: -omit.get(x, 0))

        def pick_main(pool, n, weights=None):
            pool = [x for x in pool if 1 <= x <= main_max]
            if not pool: pool = all_main[:]
            if weights:
                w = [weights.get(x, 1) for x in pool]
                tot = sum(w) or 1
                w = [x/tot for x in w]
                chosen = []
                p2 = pool[:]
                w2 = w[:]
                for _ in range(min(n, len(p2))):
                    r = _rnd.random()
                    cum = 0
                    for idx, wi in enumerate(w2):
                        cum += wi
                        if r <= cum:
                            chosen.append(p2[idx])
                            p2.pop(idx); w2.pop(idx)
                            s = sum(w2) or 1
                            w2 = [x/s for x in w2]
                            break
                return sorted(chosen)
            return sorted(_rnd.sample(pool, min(n, len(pool))))

        algos = [
            ("热号优先", lambda: pick_main(sorted_by_freq[:main_n*3], main_n,
                                           {x: freq.get(x, 1) for x in all_main})),
            ("遗漏回补", lambda: pick_main(sorted_by_omit[:main_n*3], main_n,
                                           {x: omit.get(x, 1) for x in all_main})),
            ("冷热均衡", lambda: pick_main(
                sorted_by_freq[:main_n*2] + sorted_by_omit[:main_n], main_n)),
            ("频率权重随机", lambda: pick_main(all_main, main_n,
                                              {x: freq.get(x, 1)**1.5 for x in all_main})),
            ("近5期热号", lambda: pick_main(
                sorted({n for row in all_nums[:5] for n in row}), main_n,
                {x: freq.get(x,1) for x in all_main})),
            ("遗漏+热号综合", lambda: pick_main(all_main, main_n,
                                              {x: (omit.get(x,0)*0.6 + freq.get(x,0)*0.4) for x in all_main})),
            ("奇偶平衡", lambda: (lambda p: pick_main(
                [x for x in all_main if x % 2 == 1][:main_n//2+1] +
                [x for x in all_main if x % 2 == 0][:main_n//2+1], main_n))("")),
            ("跨度中值", lambda: pick_main(
                list(range(max(1,main_max//4), min(main_max, main_max*3//4)+1)), main_n,
                {x: freq.get(x,1) for x in all_main})),
        ]

        sub_pool = list(range(1, cfg["sub_max"] + 1)) if cfg["has_sub"] else []
        sub_freq = Counter(n for row in all_nums for n in row if n > main_max)

        for i in range(min(n_groups, len(algos))):
            try:
                algo_name, algo_fn = algos[i]
                main_nums = algo_fn()
                result = {"algo": algo_name, "main": main_nums}
                if cfg["has_sub"] and sub_pool:
                    sub_sorted = sorted(sub_pool, key=lambda x: -sub_freq.get(x, 0))
                    result["sub"] = sorted(_rnd.sample(
                        sub_sorted[:max(cfg["sub_n"]*3, len(sub_pool))],
                        min(cfg["sub_n"], len(sub_pool))
                    ))
                predictions.append(result)
            except Exception:
                pass

        # 额外组数：使用混合策略补足
        while len(predictions) < n_groups:
            try:
                w = {x: (freq.get(x, 0) * 0.5 + omit.get(x, 0) * 0.5 + _rnd.uniform(0.1, 0.5))
                     for x in all_main}
                main_nums = pick_main(all_main, main_n, w)
                result = {"algo": f"混合策略#{len(predictions)+1}", "main": main_nums}
                if cfg["has_sub"] and sub_pool:
                    result["sub"] = sorted(_rnd.sample(sub_pool, min(cfg["sub_n"], len(sub_pool))))
                predictions.append(result)
            except Exception:
                break

        return predictions

    @classmethod
    def fetch_prediction_reference(cls, game_type: str, n_preds: int = 8) -> dict:
        """
        获取彩票预测参考数据（多算法 + 多来源，增强版）。
        返回 {recent_records, hot_nums, cold_nums, omission_nums, advice,
               multi_predictions, site_predictions}
        n_preds: 生成预测组数（默认8组）
        """
        records = cls.fetch(game_type, count=50)
        if not records:
            return {}

        import re
        # 解析号码
        all_nums = []
        for rec in records:
            nums_str = str(rec.get("开奖号码", "")).replace("+", " ")
            nums = [int(x) for x in re.findall(r"\d+", nums_str)]
            all_nums.append(nums)

        if not all_nums:
            return {"recent_records": records}

        from collections import Counter
        flat = [n for row in all_nums for n in row]
        freq = Counter(flat)
        sorted_by_freq = sorted(freq, key=lambda x: -freq[x])

        hot_n  = min(10, len(sorted_by_freq) // 3)
        cold_n = min(10, len(sorted_by_freq) // 3)
        hot_nums  = sorted_by_freq[:hot_n]
        cold_nums = sorted_by_freq[-cold_n:]

        # 计算当前遗漏
        last_appeared = {}
        for i, row in enumerate(all_nums):
            for n in row:
                if n not in last_appeared:
                    last_appeared[n] = i
        omission = {n: last_appeared.get(n, len(all_nums)) for n in freq}
        high_omission = sorted(omission, key=lambda x: -omission[x])[:10]

        # 基础建议号码
        advice_nums = sorted(set(hot_nums[:5] + high_omission[:5]))

        # ── 多算法预测（n_preds组）──────────────────────────────────
        multi_predictions = cls._algo_predict_multiple(game_type, all_nums, n_groups=n_preds)

        # ── 抓取网站预测（后台异步，收集到列表）────────────────────
        site_predictions = cls.fetch_prediction_sites(game_type)

        # ── 趋势分析 ────────────────────────────────────────────────
        trend_stats = {}
        if all_nums and len(all_nums[0]) >= 3:
            recent5  = all_nums[:5]
            recent10 = all_nums[:10]
            sums5  = [sum(r) for r in recent5]
            sums10 = [sum(r) for r in recent10]
            odds5  = [sum(1 for x in r if x % 2 == 1) for r in recent5]
            trend_stats = {
                "avg_sum_5":  round(sum(sums5)  / len(sums5),  1) if sums5  else 0,
                "avg_sum_10": round(sum(sums10) / len(sums10), 1) if sums10 else 0,
                "avg_odd_5":  round(sum(odds5)  / len(odds5),  1) if odds5  else 0,
                "span_avg_5": round(sum(max(r) - min(r) for r in recent5) / len(recent5), 1) if recent5 else 0,
            }

        return {
            "recent_records":   records,
            "hot_nums":         hot_nums,
            "cold_nums":        cold_nums,
            "high_omission":    high_omission,
            "omission_map":     omission,
            "freq_map":         dict(freq),
            "advice_nums":      advice_nums,
            "multi_predictions": multi_predictions,
            "site_predictions":  site_predictions,
            "trend_stats":       trend_stats,
            "source":           records[0].get("来源", "Scrapling") if records else "",
        }


