class SportsFetchWorker(QThread):
    """通用竞技彩异步爬取Worker - 所有网络请求必须在此线程中执行，禁止在主线程直接调用网络"""
    finished   = Signal(list)     # 返回 matches/results 列表
    error      = Signal(str)      # 返回错误信息
    progress   = Signal(str)      # 进度提示

    def __init__(self, task_func, *args, **kwargs):
        super().__init__()
        self._func   = task_func
        self._args   = args
        self._kwargs = kwargs

    def run(self):
        try:
            result = self._func(*self._args, **self._kwargs)
            self.finished.emit(result if result else [])
        except Exception as e:
            self.error.emit(str(e))


class PredictWorker(QThread):
    """异步预测Worker - 预测包含H2H网络爬取，必须在后台线程"""
    finished = Signal(list)
    error    = Signal(str)

    def __init__(self, predict_func, matches, game_type):
        super().__init__()
        self._predict  = predict_func
        self._matches  = matches
        self._game     = game_type

    def run(self):
        try:
            result = self._predict(self._matches, self._game)
            self.finished.emit(result if result else [])
        except Exception as e:
            self.error.emit(str(e))


class DataUpdateThread(QThread):
    """数据更新线程 - 使用极速API获取彩票开奖数据"""
    update_finished = Signal(bool, str)
    update_progress = Signal(int, int)

    def __init__(self, game_type, api_key, update_count=50, start=0):
        super().__init__()
        self.game_type    = game_type
        self.api_key      = api_key      # 极速API appkey
        self.update_count = update_count
        self.start        = start

    def run(self):
        import requests
        try:
            id_map = JISUAPI_CONFIG["lottery_id_map"]
            caid   = id_map.get(self.game_type)
            if not caid:
                self.update_finished.emit(False, f"不支持的彩票类型: {self.game_type}")
                return
            # 极速API历史开奖接口
            url  = JISUAPI_CONFIG["base_url"] + JISUAPI_CONFIG["lottery_history"]
            resp = requests.get(url, params={"appkey": self.api_key, "caipiaoid": caid, "issueno": ""},
                                 timeout=15)
            data = resp.json()
            if str(data.get("status")) != "0":
                msg = data.get("msg","极速API请求失败")
                self.update_finished.emit(False, f"极速API错误: {msg}")
                return
            items = data["result"].get("list", [])
            results = []
            for item in items[:self.update_count]:
                issue = str(item.get("issueno", ""))
                date  = str(item.get("opendate", ""))
                nums  = str(item.get("number", ""))
                refn  = str(item.get("refernumber", ""))
                # 构建奖级信息
                prize_info = []
                for p in _normalize_jisu_prize_list(item.get("prize")):
                    prize_info.append({
                        "等级":   p.get("prizename", p.get("等级", "")),
                        "注数":   p.get("num", p.get("注数", "")),
                        "单注":   p.get("singlebonus", p.get("单注", "")),
                        "条件":   p.get("require", p.get("条件", "")),
                    })
                results.append({
                    "期号": issue, "开奖日期": date,
                    "开奖号码": nums, "参考号码": refn,
                    "销售额": str(item.get("saleamount", "")),
                    "奖级": prize_info,
                    "来源": "jisuapi",
                })
                self.update_progress.emit(len(results), min(len(items), self.update_count))
            self.update_finished.emit(True, json.dumps(results, ensure_ascii=False))
        except Exception as e:
            logger.error(f"DataUpdateThread error: {e}")
            self.update_finished.emit(False, str(e))




