class BacktestThread(QThread):
    """V43: 后台运行全历史回测，避免阻塞 UI。
    通过信号把进度/结果回传主线程；回测本身在 app.backtest_full_history 内
    用 _backtest_lock + _backtesting 标志保证与其它回测互斥、不被并发污染。"""
    progress = Signal(int, int)        # (已完成期数, 总期数)
    finished_result = Signal(dict)     # 回测结果
    failed = Signal(str)

    def __init__(self, app, game, periods):
        super().__init__()
        self.app = app
        self.game = game
        self.periods = periods

    def run(self):
        try:
            def _cb(done, total):
                self.progress.emit(int(done), int(total))
            res = self.app.backtest_full_history(self.game, self.periods, progress_cb=_cb)
            self.finished_result.emit(res or {})
        except Exception as e:
            self.failed.emit(str(e))


class NumberButton(QPushButton):
    """自定义数字按钮，支持圆形样式和遗漏期数显示，新增杀号样式"""

    # 默认尺寸，可通过 set_btn_size() 全局修改
    _BTN_SIZE = 34
    _BORDER_RADIUS = 17

    @classmethod
    def set_btn_size(cls, size: int):
        """全局设置按钮尺寸（在批量创建前调用）"""
        cls._BTN_SIZE = size
        cls._BORDER_RADIUS = size // 2

    @staticmethod
    def _build_style(bg: str = "#F0F0F0", fg: str = "black",
                     checked_bg: str = "#FFD700", checked_fg: str = "white") -> str:
        """根据颜色参数生成按钮QSS，避免在多处重复硬编码字符串。"""
        r = NumberButton._BORDER_RADIUS
        sz = NumberButton._BTN_SIZE
        fs = max(9, sz // 3)
        return (
            f"QPushButton {{"
            f"  border-radius: {r}px; border: 2px solid #8f8f91;"
            f"  font-weight: bold; font-size: {fs}px;"
            f"  background-color: {bg}; color: {fg}; }}"
            f"QPushButton:checked {{"
            f"  background-color: {checked_bg}; color: {checked_fg}; }}"
            f"QPushButton:hover {{ border: 2px solid #FF6B6B; }}"
        )

    def __init__(self, text, cold_hot_type="default", omission=0, frequency=0, probability=0, is_dan=False, is_tuo=False, is_kill=False, parent=None):
        super().__init__(text, parent)
        sz = self._BTN_SIZE
        self.setFixedSize(sz, sz)
        self.setCheckable(True)
        self.is_dan = is_dan
        self.is_tuo = is_tuo
        self.is_kill = is_kill
        self.probability = probability

        self.setStyleSheet(self._build_style())

        # 小标签位置根据按钮尺寸动态计算
        lbl_w = sz // 2 - 1
        lbl_h = max(8, sz // 4)
        lbl_fs = max(6, sz // 6)

        self.frequency_label = QLabel(self)
        self.frequency_label.setAlignment(Qt.AlignCenter)
        self.frequency_label.setGeometry(0, 0, lbl_w, lbl_h)
        self.frequency_label.setStyleSheet(f"font-size: {lbl_fs}px; color: #555; background-color: rgba(255,255,255,0);")

        self.prob_label = QLabel(self)
        self.prob_label.setAlignment(Qt.AlignCenter)
        self.prob_label.setGeometry(lbl_w, 0, lbl_w, lbl_h)
        self.prob_label.setStyleSheet(f"font-size: {lbl_fs}px; color: #555; background-color: rgba(255,255,255,0);")

        self.omission_label = QLabel(self)
        self.omission_label.setAlignment(Qt.AlignCenter)
        self.omission_label.setGeometry(0, sz - lbl_h - 1, sz, lbl_h)
        self.omission_label.setStyleSheet(f"font-size: {lbl_fs}px; color: #555; background-color: rgba(255,255,255,0);")

        self.frequency_label.raise_()
        self.prob_label.raise_()
        self.omission_label.raise_()

        self.set_omission(omission)
        self.set_frequency(frequency)
        self.set_probability(probability)
        self.update_color(cold_hot_type)

    def update_color(self, cold_hot_type):
        colors = {
            "hot": "#E74C3C",
            "warm": "#3498DB",
            "cold": "#2ECC71",
            "default": "#F0F0F0"
        }
        checked_bg = colors.get(cold_hot_type, "#F0F0F0")
        self.setStyleSheet(self._build_style(checked_bg=checked_bg))

    def set_omission(self, omission):
        fs = max(6, self._BTN_SIZE // 6)
        self.omission_label.setText(f"漏:{omission}")
        if omission > 20:
            self.omission_label.setStyleSheet(f"font-size: {fs}px; color: #E74C3C; font-weight: bold; background-color: rgba(255,255,255,0);")
        elif omission > 10:
            self.omission_label.setStyleSheet(f"font-size: {fs}px; color: #F39C12; background-color: rgba(255,255,255,0);")
        else:
            self.omission_label.setStyleSheet(f"font-size: {fs}px; color: #555; background-color: rgba(255,255,255,0);")

    def set_frequency(self, frequency):
        fs = max(6, self._BTN_SIZE // 6)
        self.frequency_label.setText(f"{frequency}")
        if frequency > 10:
            self.frequency_label.setStyleSheet(f"font-size: {fs}px; color: #27AE60; font-weight: bold; background-color: rgba(255,255,255,0);")
        elif frequency > 5:
            self.frequency_label.setStyleSheet(f"font-size: {fs}px; color: #27AE60; background-color: rgba(255,255,255,0);")
        else:
            self.frequency_label.setStyleSheet(f"font-size: {fs}px; color: #555; background-color: rgba(255,255,255,0);")

    def set_probability(self, probability):
        fs = max(6, self._BTN_SIZE // 6)
        prob_text = f"{probability:.1%}" if probability > 0 else "-"
        self.prob_label.setText(prob_text)
        if probability > 0.1:
            self.prob_label.setStyleSheet(f"font-size: {fs}px; color: #E74C3C; font-weight: bold; background-color: rgba(255,255,255,0);")
        elif probability > 0.05:
            self.prob_label.setStyleSheet(f"font-size: {fs}px; color: #F39C12; background-color: rgba(255,255,255,0);")
        else:
            self.prob_label.setStyleSheet(f"font-size: {fs}px; color: #555; background-color: rgba(255,255,255,0);")

    def set_dan(self, is_dan):
        self.is_dan = is_dan
        if is_dan:
            self.setStyleSheet(self._build_style(bg="#FFD700", fg="black", checked_bg="#FFD700", checked_fg="black"))

    def set_tuo(self, is_tuo):
        self.is_tuo = is_tuo
        if is_tuo:
            self.setStyleSheet(self._build_style(bg="#87CEEB", fg="black", checked_bg="#87CEEB", checked_fg="black"))

    def set_kill(self, is_kill):
        """设置杀号样式：灰色背景，数字带删除线，禁用点击。"""
        self.is_kill = is_kill
        if is_kill:
            self.setChecked(False)  # 取消选中
            self.setEnabled(False)  # 禁止点击
            self.setStyleSheet(
                "QPushButton{"
                "border-radius:18px;border:2px solid #888;"
                "background:#cccccc;color:#999999;"
                "font-size:11px;font-weight:bold;"
                "text-decoration:line-through;"
                "}"
            )
        else:
            self.setEnabled(True)   # 恢复可点击
            self.update_color("default")

class HistoryCompareDialog(QDialog):
    """历史开奖比对对话框（支持按区域/位置比对，匹配号码红色高亮）"""
    def __init__(self, parent=None, game_type="双色球", selected_numbers=None, structured_numbers=None):
        super().__init__(parent)
        self.parent = parent
        self.game_type = game_type
        self.selected_numbers = selected_numbers or []  # 扁平列表（备用）
        self.structured_numbers = structured_numbers    # 结构化数据，如 {"red":[...], "blue":[...]} 或 {"pos1":[...], ...}
        self.setWindowTitle(f"{game_type} - 历史开奖比对")
        self.setFixedSize(500, 800)
        self.init_ui()

    def init_ui(self):
        layout = QVBoxLayout()
        self.issue_list = QListWidget()
        layout.addWidget(QLabel("选择期号:"))
        layout.addWidget(self.issue_list)

        self.detail_text = QTextEdit()
        self.detail_text.setReadOnly(True)
        layout.addWidget(QLabel("比对结果:"))
        layout.addWidget(self.detail_text)

        compare_btn = QPushButton("比对当前期号")
        compare_btn.clicked.connect(self.perform_comparison)
        layout.addWidget(compare_btn)

        self.setLayout(layout)
        self.load_history_issues()

    def load_history_issues(self):
        if self.game_type in self.parent.history_data:
            records = self.parent.history_data[self.game_type]
            for rec in records[:50]:  # 最近50期
                self.issue_list.addItem(f"{rec.get('期号','')} - {rec.get('开奖日期','')}")

    def perform_comparison(self):
        selected = self.issue_list.currentItem()
        if not selected:
            QMessageBox.warning(self, "错误", "请先选择期号")
            return
        issue_text = selected.text().split(" - ")[0]
        # 查找该期记录
        for rec in self.parent.history_data.get(self.game_type, []):
            if rec.get("期号") == issue_text:
                self.compare_numbers_with_record(rec)
                return
        self.detail_text.setText("未找到对应期号数据")

    @staticmethod
    def _positional_html(draw_numbers: list, structured: dict, pos_names: list) -> str:
        """通用按位比对HTML生成（3D、七星彩、排列五等按位玩法共用）。"""
        n = len(pos_names)
        html = "开奖号码: "
        for i, name in enumerate(pos_names):
            draw_pos = draw_numbers[i] if i < len(draw_numbers) else None
            bet_set = set(structured.get(f"pos{i+1}", []))
            if draw_pos is not None:
                if draw_pos in bet_set:
                    html += f"<span style='color:red; font-weight:bold;'>{draw_pos} </span>"
                else:
                    html += f"{draw_pos} "
            else:
                html += "- "
        html += "</p><p><b>您选择的位置:</b><br>"
        for i, name in enumerate(pos_names):
            html += f"{name}: {', '.join(map(str, structured.get(f'pos{i+1}',[])))}<br>"
        html += "</p><p>"
        for i, name in enumerate(pos_names):
            draw_pos = draw_numbers[i] if i < len(draw_numbers) else None
            bet_set = set(structured.get(f"pos{i+1}", []))
            if draw_pos is not None:
                html += f"{name}: {'✓' if draw_pos in bet_set else '✗'}<br>"
            else:
                html += f"{name}: 无开奖<br>"
        html += "</p>"
        return html

    def compare_numbers_with_record(self, record):
        draw_numbers_str = record.get("开奖号码", "")
        draw_numbers = parse_draw_numbers(draw_numbers_str)
        game_type = self.game_type

        if self.structured_numbers is not None:
            # 使用结构化数据进行区域化比对，生成HTML格式文本，匹配的号码用红色显示
            result_html = "<html><body>"
            result_html += f"<p><b>开奖号码:</b> "
            if game_type == "双色球":
                # 开奖号码：前6红球，第7蓝球
                draw_red = draw_numbers[:6] if len(draw_numbers) >= 6 else []
                draw_blue = draw_numbers[6] if len(draw_numbers) >= 7 else None
                bet_red = set(self.structured_numbers.get("red", []))
                bet_blue = set(self.structured_numbers.get("blue", []))
                # 红球
                for num in draw_red:
                    if num in bet_red:
                        result_html += f"<span style='color:red; font-weight:bold;'>{num} </span>"
                    else:
                        result_html += f"{num} "
                if draw_blue is not None:
                    result_html += f"+ "
                    if draw_blue in bet_blue:
                        result_html += f"<span style='color:red; font-weight:bold;'>{draw_blue}</span>"
                    else:
                        result_html += f"{draw_blue}"
                result_html += "</p>"
                # 显示您的选择
                result_html += f"<p><b>您选择的红球:</b> {', '.join(map(str, self.structured_numbers.get('red',[])))}<br>"
                result_html += f"<b>您选择的蓝球:</b> {', '.join(map(str, self.structured_numbers.get('blue',[])))}</p>"
                result_html += f"<p>红球匹配个数: {len(bet_red & set(draw_red))}</p>"
                result_html += f"<p>蓝球匹配: {'✓' if draw_blue in bet_blue else '✗'}</p>"

            elif game_type == "大乐透":
                draw_front = draw_numbers[:5] if len(draw_numbers) >= 5 else []
                draw_back = draw_numbers[5:7] if len(draw_numbers) >= 7 else []
                bet_front = set(self.structured_numbers.get("front", []))
                bet_back = set(self.structured_numbers.get("back", []))
                result_html += f"前区: "
                for num in draw_front:
                    if num in bet_front:
                        result_html += f"<span style='color:red; font-weight:bold;'>{num} </span>"
                    else:
                        result_html += f"{num} "
                result_html += f" 后区: "
                for num in draw_back:
                    if num in bet_back:
                        result_html += f"<span style='color:red; font-weight:bold;'>{num} </span>"
                    else:
                        result_html += f"{num} "
                result_html += "</p>"
                result_html += f"<p><b>您选择的前区:</b> {', '.join(map(str, self.structured_numbers.get('front',[])))}<br>"
                result_html += f"<b>您选择的后区:</b> {', '.join(map(str, self.structured_numbers.get('back',[])))}</p>"
                result_html += f"<p>前区匹配个数: {len(bet_front & set(draw_front))}</p>"
                result_html += f"<p>后区匹配个数: {len(bet_back & set(draw_back))}</p>"

            elif game_type in ["3D", "排列三"]:
                pos_names = ["百位", "十位", "个位"]
                result_html += self._positional_html(draw_numbers, self.structured_numbers, pos_names)

            elif game_type == "七星彩":
                pos_names = [f"第{i}位" for i in range(1, 8)]
                result_html += self._positional_html(draw_numbers, self.structured_numbers, pos_names)

            elif game_type == "排列五":
                pos_names = ["万位", "千位", "百位", "十位", "个位"]
                result_html += self._positional_html(draw_numbers, self.structured_numbers, pos_names)

            elif game_type in ["快乐8", "七乐彩"]:
                draw_set = set(draw_numbers)
                bet_set = set(self.structured_numbers.get("main", []))
                match = len(bet_set & draw_set)
                result_html += f"开奖号码: "
                for num in draw_numbers:
                    if num in bet_set:
                        result_html += f"<span style='color:red; font-weight:bold;'>{num} </span>"
                    else:
                        result_html += f"{num} "
                result_html += "</p>"
                result_html += f"<p><b>您选择的号码:</b> {', '.join(map(str, self.structured_numbers.get('main',[])))}</p>"
                result_html += f"<p>匹配个数: {match}</p>"
            else:
                # 降级处理
                bet_numbers = self.selected_numbers
                match = len(set(bet_numbers) & set(draw_numbers))
                result_html += f"开奖号码: {' '.join(map(str, draw_numbers))}</p>"
                result_html += f"<p><b>您选择的号码:</b> {' '.join(map(str, bet_numbers))}</p>"
                result_html += f"<p>匹配个数: {match}</p>"

            result_html += "</body></html>"
            self.detail_text.setHtml(result_html)
        else:
            # 旧方式：扁平列表比对，也尝试红色高亮
            bet_numbers = self.selected_numbers
            bet_set = set(bet_numbers)
            result_html = "<html><body>"
            result_html += f"<p><b>开奖号码:</b> "
            for num in draw_numbers:
                if num in bet_set:
                    result_html += f"<span style='color:red; font-weight:bold;'>{num} </span>"
                else:
                    result_html += f"{num} "
            result_html += "</p>"
            result_html += f"<p><b>您选择的号码:</b> {' '.join(map(str, bet_numbers))}</p>"
            match = len(bet_set & set(draw_numbers))
            result_html += f"<p>匹配个数: {match}</p>"
            result_html += "</body></html>"
            self.detail_text.setHtml(result_html)

class LotteryAnalysisDialog(QDialog):
    """彩票分析对话框"""
    def __init__(self, parent=None, game_type="双色球", selected_numbers=None):
        super().__init__(parent)
        self.game_type = game_type
        self.selected_numbers = selected_numbers or []
        self.setWindowTitle(f"{game_type} - 开奖记录与号码分析")
        self.setGeometry(100, 100, 800, 800)
        self.init_ui()

    def init_ui(self):
        layout = QVBoxLayout()
        self.history_table = QTableWidget()
        self.history_table.setColumnCount(5)
        self.history_table.setHorizontalHeaderLabels(["期号", "开奖日期", "开奖号码", "匹配个数", "详情"])
        layout.addWidget(self.history_table)

        self.analysis_text = QTextEdit()
        self.analysis_text.setReadOnly(True)
        layout.addWidget(self.analysis_text)

        self.setLayout(layout)
        self.load_history_data()
        self.analyze_number_match()

    def load_history_data(self):
        if self.game_type in self.parent().history_data:
            records = self.parent().history_data[self.game_type][:50]
            self.history_table.setRowCount(len(records))
            for row, rec in enumerate(records):
                self.history_table.setItem(row, 0, QTableWidgetItem(str(rec.get("期号", ""))))
                self.history_table.setItem(row, 1, QTableWidgetItem(str(rec.get("开奖日期", ""))))
                self.history_table.setItem(row, 2, QTableWidgetItem(str(rec.get("开奖号码", ""))))
                match = len(set(self.selected_numbers) & set(parse_draw_numbers(rec.get("开奖号码", ""))))
                self.history_table.setItem(row, 3, QTableWidgetItem(str(match)))
                self.history_table.setItem(row, 4, QTableWidgetItem("查看"))

    def analyze_number_match(self):
        freq = Counter(self.selected_numbers)
        analysis = f"您选择的号码: {self.selected_numbers}\n"
        analysis += f"号码个数: {len(self.selected_numbers)}\n"
        analysis += f"频率分析: {dict(freq)}\n"
        self.analysis_text.setText(analysis)

class BetPredictionDialog(QDialog):
    """预测号码投注选项对话框（单组）"""
    def __init__(self, parent, game, prediction_data):
        super().__init__(parent)
        self.parent = parent
        self.game = game
        self.prediction_data = prediction_data  # 单组结构化预测数据
        self.setWindowTitle("预测号码投注选项")
        self.setFixedSize(400, 400)
        self.init_ui()

    def init_ui(self):
        layout = QVBoxLayout()

        # 显示预测号码
        self.info_label = QLabel()
        self.info_label.setText(f"游戏: {self.game}\n预测号码: {self.prediction_data}")
        self.info_label.setWordWrap(True)
        layout.addWidget(self.info_label)

        # 投注方式选择
        layout.addWidget(QLabel("选择投注方式:"))
        self.bet_type_group = QButtonGroup(self)
        self.single_radio = QRadioButton("单式投注")
        self.complex_radio = QRadioButton("复式投注")
        self.dantuo_radio = QRadioButton("胆拖投注")
        self.single_radio.setChecked(True)
        layout.addWidget(self.single_radio)
        layout.addWidget(self.complex_radio)
        layout.addWidget(self.dantuo_radio)
        self.bet_type_group.addButton(self.single_radio, 1)
        self.bet_type_group.addButton(self.complex_radio, 2)
        self.bet_type_group.addButton(self.dantuo_radio, 3)

        # 份数选择
        self.copies_layout = QHBoxLayout()
        self.copies_layout.addWidget(QLabel("份数 (1-100):"))
        self.copies_spin = QSpinBox()
        self.copies_spin.setRange(1, 100)
        self.copies_spin.setValue(1)
        self.copies_layout.addWidget(self.copies_spin)
        layout.addLayout(self.copies_layout)

        # 胆码个数输入（仅胆拖时可见）
        self.dan_layout = QHBoxLayout()
        self.dan_layout.addWidget(QLabel("胆码个数:"))
        self.dan_spin = QSpinBox()
        self.dan_spin.setRange(1, 5)  # 根据游戏动态调整
        self.dan_layout.addWidget(self.dan_spin)
        layout.addLayout(self.dan_layout)
        self.dan_layout.setEnabled(False)

        # 大乐透追加选项
        self.additional_check = QCheckBox("追加投注 (仅大乐透)")
        if self.game == "大乐透":
            layout.addWidget(self.additional_check)

        # 按钮
        btn_layout = QHBoxLayout()
        confirm_btn = QPushButton("确认投注")
        cancel_btn = QPushButton("取消")
        btn_layout.addWidget(confirm_btn)
        btn_layout.addWidget(cancel_btn)
        layout.addLayout(btn_layout)

        confirm_btn.clicked.connect(self.confirm)
        cancel_btn.clicked.connect(self.reject)

        # 信号连接
        self.dantuo_radio.toggled.connect(self.on_bet_type_changed)
        self.complex_radio.toggled.connect(self.on_bet_type_changed)
        self.single_radio.toggled.connect(self.on_bet_type_changed)

        self.setLayout(layout)

    def on_bet_type_changed(self):
        if self.dantuo_radio.isChecked():
            self.dan_layout.setEnabled(True)
        else:
            self.dan_layout.setEnabled(False)

    def confirm(self):
        bet_type = "单式"
        if self.complex_radio.isChecked():
            bet_type = "复式"
        elif self.dantuo_radio.isChecked():
            bet_type = "胆拖"
        copies = self.copies_spin.value()
        dan_count = self.dan_spin.value() if bet_type == "胆拖" else 0
        additional = self.additional_check.isChecked() if self.game == "大乐透" else False

        # 根据投注方式生成投注记录
        self.parent.add_prediction_bet(self.game, self.prediction_data, bet_type, copies, dan_count, additional)
        self.accept()

class MultiPredictionBetDialog(QDialog):
    """多组预测号码投注对话框，支持选择多组，并选择投注方式"""
    def __init__(self, parent, game, predictions):
        super().__init__(parent)
        self.parent = parent
        self.game = game
        self.predictions = predictions  # 列表，每个元素是预测字典
        self.setWindowTitle(f"{game} - 多组预测投注")
        self.setMinimumSize(500, 500)
        self.init_ui()

    def init_ui(self):
        layout = QVBoxLayout()

        # 预测组列表
        self.list_widget = QListWidget()
        self.list_widget.setSelectionMode(QAbstractItemView.NoSelection)  # 使用复选框，不启用行选择
        for i, pred in enumerate(self.predictions):
            item_text = self.format_prediction(pred, i+1)
            item = QListWidgetItem(item_text)
            item.setFlags(item.flags() | Qt.ItemIsUserCheckable)
            item.setCheckState(Qt.Unchecked)
            self.list_widget.addItem(item)
        layout.addWidget(QLabel("请选择要投注的预测组:"))
        layout.addWidget(self.list_widget)

        # 全选/取消按钮
        btn_layout = QHBoxLayout()
        select_all_btn = QPushButton("全选")
        select_all_btn.clicked.connect(self.select_all)
        deselect_all_btn = QPushButton("取消全选")
        deselect_all_btn.clicked.connect(self.deselect_all)
        btn_layout.addWidget(select_all_btn)
        btn_layout.addWidget(deselect_all_btn)
        layout.addLayout(btn_layout)

        # 投注方式
        group = QGroupBox("投注方式")
        group_layout = QVBoxLayout()
        self.bet_type_combo = QComboBox()
        self.bet_type_combo.addItems(["单式投注（每注独立）", "复式投注（合并号码池）", "胆拖投注（需设置胆码）"])
        group_layout.addWidget(self.bet_type_combo)

        # 胆码个数输入（仅胆拖时显示）
        self.dan_layout = QHBoxLayout()
        self.dan_layout.addWidget(QLabel("胆码个数:"))
        self.dan_spin = QSpinBox()
        self.dan_spin.setRange(1, 5)
        self.dan_layout.addWidget(self.dan_spin)
        group_layout.addLayout(self.dan_layout)
        self.dan_layout.setEnabled(False)

        # 大乐透追加
        self.additional_check = QCheckBox("追加投注 (仅大乐透)")
        if self.game == "大乐透":
            group_layout.addWidget(self.additional_check)

        group.setLayout(group_layout)
        layout.addWidget(group)

        # 连接信号
        self.bet_type_combo.currentIndexChanged.connect(self.on_bet_type_changed)

        # 统计信息
        self.info_label = QLabel("注数: 0, 金额: ¥0.00")
        layout.addWidget(self.info_label)

        # 按钮
        btn_layout2 = QHBoxLayout()
        calc_btn = QPushButton("计算注数")
        calc_btn.clicked.connect(self.calculate)
        confirm_btn = QPushButton("确认投注")
        confirm_btn.clicked.connect(self.confirm)
        cancel_btn = QPushButton("取消")
        btn_layout2.addWidget(calc_btn)
        btn_layout2.addWidget(confirm_btn)
        btn_layout2.addWidget(cancel_btn)
        layout.addLayout(btn_layout2)

        self.setLayout(layout)

    def format_prediction(self, pred, idx):
        if self.game == "双色球":
            return f"第{idx}组: 红球 {', '.join(map(str, pred['red']))} 蓝球 {pred['blue']}"
        elif self.game == "大乐透":
            return f"第{idx}组: 前区 {', '.join(map(str, pred['front']))} 后区 {', '.join(map(str, pred['back']))}"
        elif self.game in ["快乐8", "七乐彩"]:
            return f"第{idx}组: 号码 {', '.join(map(str, pred['main']))}"
        else:
            return f"第{idx}组: 号码 {', '.join(map(str, pred['pos']))}"

    def select_all(self):
        for i in range(self.list_widget.count()):
            item = self.list_widget.item(i)
            item.setCheckState(Qt.Checked)

    def deselect_all(self):
        for i in range(self.list_widget.count()):
            item = self.list_widget.item(i)
            item.setCheckState(Qt.Unchecked)

    def on_bet_type_changed(self):
        if self.bet_type_combo.currentText() == "胆拖投注（需设置胆码）":
            self.dan_layout.setEnabled(True)
        else:
            self.dan_layout.setEnabled(False)

    def get_selected_predictions(self):
        selected = []
        for i in range(self.list_widget.count()):
            item = self.list_widget.item(i)
            if item.checkState() == Qt.Checked:
                selected.append(self.predictions[i])
        return selected

    def calculate(self):
        selected = self.get_selected_predictions()
        if not selected:
            QMessageBox.warning(self, "错误", "请至少选择一组预测号码")
            return
        bet_type = self.bet_type_combo.currentText()
        additional = self.additional_check.isChecked() if self.game == "大乐透" else False
        dan_count = self.dan_spin.value() if "胆拖" in bet_type else 0

        # 计算注数和金额
        bets, amount = self.parent.calculate_multi_prediction_bet(self.game, selected, bet_type, dan_count, additional)
        self.info_label.setText(f"注数: {bets}, 金额: ¥{amount:.2f}")

    def confirm(self):
        selected = self.get_selected_predictions()
        if not selected:
            QMessageBox.warning(self, "错误", "请至少选择一组预测号码")
            return
        bet_type = self.bet_type_combo.currentText()
        additional = self.additional_check.isChecked() if self.game == "大乐透" else False
        dan_count = self.dan_spin.value() if "胆拖" in bet_type else 0

        # 执行投注
        self.parent.add_multi_prediction_bet(self.game, selected, bet_type, dan_count, additional)
        self.accept()

# ========== 缩水投注对话框（增强版） ==========
class SelfSelectDantuoDialog(QDialog):
    """自选号码页胆拖参数弹窗（可视化点击标记胆/拖）。

    用户在号码盘上已选好号码后触发此弹窗。弹窗中展示所有已选号码，
    用户点击号码即可切换"胆码/拖码"状态，最终一次性生成所有组合，
    无需任何逐步询问。

    参数 required: 每注需要的主号码数（快乐8选几就填几，SSQ=6, DLT=5）
    """
    def __init__(self, parent, game_type: str,
                 main_selected: list, aux_selected: list,
                 required: int = None):
        super().__init__(parent)
        self.game_type     = game_type
        self.main_selected = list(main_selected)
        self.aux_selected  = list(aux_selected)
        self._is_dan: dict[int, bool] = {n: False for n in self.main_selected}

        # 根据游戏类型决定标签和上限
        is_ssq = game_type == "双色球"
        is_dlt = game_type == "大乐透"
        _MAIN_NEED = {"双色球": 6, "大乐透": 5, "七乐彩": 7,
                      "快乐8": required or 10}
        _MAX_DAN   = {"双色球": 5, "大乐透": 4, "七乐彩": 6,
                      "快乐8": (required or 10) - 1}
        self._main_label = "红球" if is_ssq else ("前区" if is_dlt else "号码")
        self._aux_label  = "蓝球" if is_ssq else ("后区" if is_dlt else "")
        self._main_need  = required if required else _MAIN_NEED.get(game_type, 6)
        self._max_dan    = _MAX_DAN.get(game_type, self._main_need - 1)
        # 快乐8等无辅助区游戏，注数计算不乘辅助
        self._has_aux    = game_type in ("双色球", "大乐透")

        self.setWindowTitle(f"{game_type} 胆拖参数设置")
        self.setMinimumWidth(420)
        self._build_ui()

    def _build_ui(self):
        layout = QVBoxLayout(self)

        # ── 说明文字 ──
        tip = QLabel(f"点击号码切换 胆/拖 状态（最多 {self._max_dan} 个胆码）")
        tip.setStyleSheet("color: #555; font-size: 12px;")
        layout.addWidget(tip)

        # ── 主号码按钮区 ──
        main_box = QGroupBox(self._main_label)
        main_grid = QGridLayout(main_box)
        main_grid.setSpacing(6)
        self._main_btns: dict[int, QPushButton] = {}
        for col, num in enumerate(self.main_selected):
            btn = QPushButton(str(num))
            btn.setFixedSize(40, 40)
            btn.setCheckable(True)
            btn.setStyleSheet(self._style_tuo())
            btn.clicked.connect(lambda checked, n=num: self._toggle_dan(n))
            main_grid.addWidget(btn, 0, col)
            self._main_btns[num] = btn
        layout.addWidget(main_box)

        # ── 辅助号码展示 ──
        aux_box = QGroupBox(self._aux_label)
        aux_layout = QVBoxLayout(aux_box)
        aux_layout.addWidget(QLabel(
            f"{'蓝球' if self.game_type == '双色球' else '后区'}（{len(self.aux_selected)} 个）: "
            + ", ".join(map(str, self.aux_selected))
        ))
        layout.addWidget(aux_box)

        # ── 参数行 ──
        param_row = QHBoxLayout()
        param_row.addWidget(QLabel("份数:"))
        self.copies_spin = QSpinBox()
        self.copies_spin.setRange(1, 100)
        self.copies_spin.setValue(1)
        self.copies_spin.valueChanged.connect(self._update_preview)
        param_row.addWidget(self.copies_spin)
        param_row.addStretch()

        self.additional_check = None
        if self.game_type == "大乐透":
            self.additional_check = QCheckBox("追加投注（+1元/注）")
            self.additional_check.toggled.connect(self._update_preview)
            param_row.addWidget(self.additional_check)
        layout.addLayout(param_row)

        # ── 胆/拖 实时状态 ──
        self.split_label = QLabel()
        self.split_label.setStyleSheet("font-size: 12px; color: #333;")
        self.split_label.setWordWrap(True)
        layout.addWidget(self.split_label)

        # ── 注数预估 ──
        self.preview_label = QLabel()
        self.preview_label.setStyleSheet("font-size: 13px; font-weight: bold; color: #1a6e2a; padding: 4px 0;")
        layout.addWidget(self.preview_label)

        # ── 按钮 ──
        btn_row = QHBoxLayout()
        self.ok_btn = QPushButton("✔ 确认生成")
        self.ok_btn.setDefault(True)
        self.ok_btn.clicked.connect(self._on_confirm)
        cancel_btn = QPushButton("取消")
        cancel_btn.clicked.connect(self.reject)
        btn_row.addWidget(self.ok_btn)
        btn_row.addWidget(cancel_btn)
        layout.addLayout(btn_row)

        self._update_preview()

    @staticmethod
    def _style_dan() -> str:
        return ("QPushButton{border-radius:20px;border:2px solid #cc6600;"
                "background:#FFD700;color:#333;font-weight:bold;font-size:14px;}"
                "QPushButton:hover{border-color:#FF4500;}")

    @staticmethod
    def _style_tuo() -> str:
        return ("QPushButton{border-radius:20px;border:2px solid #888;"
                "background:#e0f0ff;color:#333;font-weight:bold;font-size:14px;}"
                "QPushButton:hover{border-color:#3399ff;}")

    def _toggle_dan(self, num: int):
        currently_dan = self._is_dan[num]
        # 如果要设为胆但已达上限，提示
        if not currently_dan:
            current_dan_count = sum(1 for v in self._is_dan.values() if v)
            if current_dan_count >= self._max_dan:
                QMessageBox.warning(self, "超出限制",
                    f"{self._main_label}胆码最多 {self._max_dan} 个")
                self._main_btns[num].setChecked(False)
                return
        self._is_dan[num] = not currently_dan
        self._main_btns[num].setStyleSheet(
            self._style_dan() if self._is_dan[num] else self._style_tuo()
        )
        self._update_preview()

    def _update_preview(self):
        dan_nums = [n for n in self.main_selected if self._is_dan[n]]
        tuo_nums = [n for n in self.main_selected if not self._is_dan[n]]
        dan_count = len(dan_nums)
        tuo_count = len(tuo_nums)
        need_tuo  = self._main_need - dan_count

        dan_str = ", ".join(map(str, dan_nums)) if dan_nums else "（未设置）"
        tuo_str = ", ".join(map(str, tuo_nums)) if tuo_nums else "（无）"
        self.split_label.setText(
            f"🟡 胆码（{dan_count}个）: {dan_str}\n"
            f"🔵 拖码（{tuo_count}个）: {tuo_str}"
        )

        if dan_count == 0:
            self.preview_label.setText("请先点击号码设置至少 1 个胆码")
            self.ok_btn.setEnabled(False)
            return
        if tuo_count < need_tuo:
            self.preview_label.setText(f"⚠️ 拖码不足：需要 {need_tuo} 个，当前只有 {tuo_count} 个")
            self.ok_btn.setEnabled(False)
            return

        try:
            if self._has_aux and self.aux_selected:
                is_ssq = self.game_type == "双色球"
                bets_per = math.comb(tuo_count, need_tuo) * (
                    len(self.aux_selected) if is_ssq
                    else math.comb(len(self.aux_selected), 2)
                )
            else:
                bets_per = math.comb(tuo_count, need_tuo)
        except Exception:
            bets_per = 0

        copies = self.copies_spin.value()
        additional = bool(self.additional_check and self.additional_check.isChecked())
        price = 3.0 if additional else 2.0
        total = bets_per * copies
        self.preview_label.setText(
            f"每份 {bets_per} 注 × {copies} 份 = 共 {total} 注    ¥{total * price:.2f}"
        )
        self.ok_btn.setEnabled(True)

    def _on_confirm(self):
        dan_nums = [n for n in self.main_selected if self._is_dan[n]]
        tuo_nums = [n for n in self.main_selected if not self._is_dan[n]]
        dan_count = len(dan_nums)
        need_tuo  = self._main_need - dan_count

        if dan_count == 0:
            QMessageBox.warning(self, "错误", "请至少设置 1 个胆码（点击黄色高亮的号码）")
            return
        if len(tuo_nums) < need_tuo:
            QMessageBox.warning(self, "错误",
                f"拖码不足：需要 {need_tuo} 个，当前只有 {len(tuo_nums)} 个\n"
                f"请减少胆码个数或在号码盘中多选几个号码")
            return
        self.accept()

    def get_params(self) -> dict:
        additional = bool(self.additional_check and self.additional_check.isChecked())
        dan_nums = [n for n in self.main_selected if self._is_dan[n]]
        tuo_nums = [n for n in self.main_selected if not self._is_dan[n]]
        return {
            "dan_nums":   dan_nums,
            "tuo_nums":   tuo_nums,
            "aux":        self.aux_selected,
            "copies":     self.copies_spin.value(),
            "additional": additional,
        }


class DantuoConfigDialog(QDialog):
    """胆拖投注一次性参数配置弹窗（双色球 / 大乐透）。
    不再逐份询问，而是在生成前统一收集所有参数。
    """
    def __init__(self, parent, game_type: str):
        super().__init__(parent)
        self.game_type = game_type
        self.setWindowTitle(f"{game_type} 胆拖投注配置")
        self.setFixedWidth(360)
        self._build_ui()

    def _build_ui(self):
        layout = QVBoxLayout(self)
        form = QGridLayout()
        row = 0

        def _spin(lo, hi, default):
            s = QSpinBox()
            s.setRange(lo, hi)
            s.setValue(default)
            return s

        # 份数
        form.addWidget(QLabel("生成份数:"), row, 0)
        self.copies_spin = _spin(1, 100, 1)
        form.addWidget(self.copies_spin, row, 1)
        row += 1

        if self.game_type == "双色球":
            form.addWidget(QLabel("红球胆码个数 (1–5):"), row, 0)
            self.dan_spin = _spin(1, 5, 1)
            form.addWidget(self.dan_spin, row, 1)
            row += 1

            form.addWidget(QLabel("红球拖码个数:"), row, 0)
            self.tuo_spin = _spin(1, 27, 6)       # 最小值会动态更新
            form.addWidget(self.tuo_spin, row, 1)
            row += 1

            form.addWidget(QLabel("蓝球个数 (1–16):"), row, 0)
            self.blue_spin = _spin(1, 16, 1)
            form.addWidget(self.blue_spin, row, 1)
            row += 1

            # 胆码变化时，实时更新拖码最小值和注数预估
            self.dan_spin.valueChanged.connect(self._update_ssq_constraints)
            self.tuo_spin.valueChanged.connect(self._update_preview)
            self.blue_spin.valueChanged.connect(self._update_preview)
            self.copies_spin.valueChanged.connect(self._update_preview)

        elif self.game_type == "大乐透":
            form.addWidget(QLabel("前区胆码个数 (1–4):"), row, 0)
            self.dan_spin = _spin(1, 4, 1)
            form.addWidget(self.dan_spin, row, 1)
            row += 1

            form.addWidget(QLabel("前区拖码个数:"), row, 0)
            self.tuo_spin = _spin(1, 30, 5)
            form.addWidget(self.tuo_spin, row, 1)
            row += 1

            form.addWidget(QLabel("后区个数 (2–12):"), row, 0)
            self.blue_spin = _spin(2, 12, 2)
            form.addWidget(self.blue_spin, row, 1)
            row += 1

            self.dan_spin.valueChanged.connect(self._update_dlt_constraints)
            self.tuo_spin.valueChanged.connect(self._update_preview)
            self.blue_spin.valueChanged.connect(self._update_preview)
            self.copies_spin.valueChanged.connect(self._update_preview)

        layout.addLayout(form)

        # 注数预估标签
        self.preview_label = QLabel()
        self.preview_label.setStyleSheet("color: #555; font-size: 12px;")
        layout.addWidget(self.preview_label)

        # 追加投注（仅大乐透）
        self.additional_check = QCheckBox("追加投注（每注 +1 元）")
        if self.game_type == "大乐透":
            layout.addWidget(self.additional_check)

        btn_row = QHBoxLayout()
        ok_btn = QPushButton("确认生成")
        ok_btn.setDefault(True)
        ok_btn.clicked.connect(self.accept)
        cancel_btn = QPushButton("取消")
        cancel_btn.clicked.connect(self.reject)
        btn_row.addWidget(ok_btn)
        btn_row.addWidget(cancel_btn)
        layout.addLayout(btn_row)

        # 触发一次初始化
        if self.game_type == "双色球":
            self._update_ssq_constraints()
        else:
            self._update_dlt_constraints()

    # ── 双色球约束 ──
    def _update_ssq_constraints(self):
        dan = self.dan_spin.value()
        min_tuo = 6 - dan + 1          # 至少要让拖码能补足6个
        max_tuo = 33 - dan
        self.tuo_spin.setMinimum(min_tuo)
        self.tuo_spin.setMaximum(max_tuo)
        if self.tuo_spin.value() < min_tuo:
            self.tuo_spin.setValue(min_tuo)
        self._update_preview()

    # ── 大乐透约束 ──
    def _update_dlt_constraints(self):
        dan = self.dan_spin.value()
        min_tuo = 5 - dan + 1
        max_tuo = 35 - dan
        self.tuo_spin.setMinimum(min_tuo)
        self.tuo_spin.setMaximum(max_tuo)
        if self.tuo_spin.value() < min_tuo:
            self.tuo_spin.setValue(min_tuo)
        self._update_preview()

    # ── 注数预估 ──
    def _update_preview(self):
        try:
            copies = self.copies_spin.value()
            dan    = self.dan_spin.value()
            tuo    = self.tuo_spin.value()
            blue   = self.blue_spin.value()
            if self.game_type == "双色球":
                need_tuo = 6 - dan
                if tuo < need_tuo:
                    self.preview_label.setText("⚠️ 拖码数量不足")
                    return
                bets_per = math.comb(tuo, need_tuo) * blue
            else:  # 大乐透
                need_tuo = 5 - dan
                if tuo < need_tuo:
                    self.preview_label.setText("⚠️ 拖码数量不足")
                    return
                bets_per = math.comb(tuo, need_tuo) * math.comb(blue, 2)
            additional = getattr(self, 'additional_check', None)
            price = 3.0 if (additional and additional.isChecked()) else 2.0
            total_bets   = bets_per * copies
            total_amount = total_bets * price
            self.preview_label.setText(
                f"每份 {bets_per} 注 × {copies} 份 = 共 {total_bets} 注  ¥{total_amount:.2f}"
            )
        except Exception:
            self.preview_label.setText("")

    # ── 读取结果 ──
    def get_params(self) -> dict:
        return {
            "copies":     self.copies_spin.value(),
            "dan":        self.dan_spin.value(),
            "tuo":        self.tuo_spin.value(),
            "blue":       self.blue_spin.value(),
            "additional": self.additional_check.isChecked() if self.game_type == "大乐透" else False,
        }






# ═════════════════════════════════════════════════════════════════════════════
#  DragonPhoenixPredictDialog — 龙头凤尾预测 + 集合覆盖分析（全玩法）
#  龙头 = 每期最小号码；凤尾 = 每期最大号码
#  集合运算：交集/并集/差集/补集 对多种预测结果进行覆盖筛选
# ═════════════════════════════════════════════════════════════════════════════

# 快乐8 选胆“近热分区”策略参数（可按需调整）：
#   KL8_RECENT_WINDOW —— 统计最近多少期的热度（建议 30~50）
#   KL8_ZONES         —— 把 1-80 均分成多少个区段做均衡选胆（建议 4 或 8）
KL8_RECENT_WINDOW = 50
KL8_ZONES = 8


class MultiDanRotationDialog(QDialog):
    """多胆轮流投注：在固定若干个"胆码"基础上，让其余号码按不同策略轮流补足成多注。
    胆码数支持：双色球1~5、大乐透1~4、快乐8 1~9。
    胆码/补码来源策略：热温冷号轮流、龙头凤尾轮流、号码头出组合统计。
    """
    CFG = {
        "双色球": {"main_max": 33, "main_n": 6,  "max_dan": 5, "sub_max": 16, "sub_n": 1, "has_sub": True},
        "大乐透": {"main_max": 35, "main_n": 5,  "max_dan": 4, "sub_max": 12, "sub_n": 2, "has_sub": True},
        "快乐8":  {"main_max": 80, "main_n": 10, "max_dan": 9, "sub_max": 0,  "sub_n": 0, "has_sub": False},
        "七乐彩": {"main_max": 30, "main_n": 7,  "max_dan": 6, "sub_max": 0,  "sub_n": 0, "has_sub": False},
        # 位置型玩法：多胆轮流里按“每位号码池”生成。dan=每位保留的胆码数，tuo=每位补充拖码数。
        "3D":    {"main_max": 9, "main_n": 3, "max_dan": 3, "sub_max": 0, "sub_n": 0, "has_sub": False, "positional": True, "pos_count": 3, "pos_ranges": [(0, 9), (0, 9), (0, 9)]},
        "排列三": {"main_max": 9, "main_n": 3, "max_dan": 3, "sub_max": 0, "sub_n": 0, "has_sub": False, "positional": True, "pos_count": 3, "pos_ranges": [(0, 9), (0, 9), (0, 9)]},
        "排列五": {"main_max": 9, "main_n": 5, "max_dan": 5, "sub_max": 0, "sub_n": 0, "has_sub": False, "positional": True, "pos_count": 5, "pos_ranges": [(0, 9), (0, 9), (0, 9), (0, 9), (0, 9)]},
        "七星彩": {"main_max": 9, "main_n": 7, "max_dan": 7, "sub_max": 0, "sub_n": 0, "has_sub": False, "positional": True, "pos_count": 7, "pos_ranges": [(0, 9), (0, 9), (0, 9), (0, 9), (0, 9), (0, 9), (0, 14)]},
    }

    def __init__(self, parent, game_type="双色球"):
        super().__init__(parent)
        self.app = parent
        if game_type not in self.CFG:
            game_type = "双色球"
        self.game_type = game_type
        self.cfg = self.CFG[game_type]
        self._is_positional_game = bool(self.cfg.get("positional"))
        self.records = sorted(parent.history_data.get(game_type, []),
                              key=lambda x: str(x.get("期号", "")), reverse=True)
        self._tickets = []   # 生成的注 ticket dict 列表
        self._last_generate_meta = {}
        # 轮流游标：每次点【生成】都从上一次结束的位置继续轮换，
        # 这样连续点击不会再得到完全相同的号码，又保持“轮流/顺序”语义。
        self._rotation_cursor = 0
        sc = QApplication.primaryScreen().availableGeometry()
        self.resize(min(720, int(sc.width()*0.97)), min(900, int(sc.height()*0.95)))
        self.setWindowTitle(f"🎯 {game_type} 多胆轮流")
        self._build_ui()

    def _pos_fmt(self, n, pos_index=None):
        """位置型玩法显示格式：3D/排列三/排列五每位不补0；七星彩第7位允许0-14，也不补0。"""
        try:
            return str(int(n))
        except Exception:
            return str(n)

    def _pos_num_html(self, n, hit=False):
        txt = self._pos_fmt(n)
        if hit:
            return f"<span style='color:red;font-weight:bold'>{txt}</span>"
        return txt

    # ---------- 统计辅助 ----------
    def _all_main_rows(self):
        """返回每期主区号码列表（按期，最近在前）。带缓存避免重复遍历。"""
        if getattr(self, "_rows_cache", None) is not None:
            return self._rows_cache
        rows = []
        for r in self.records:
            nums = parse_draw_numbers(str(r.get("开奖号码", "")))
            if self._is_positional_game:
                pc = int(self.cfg.get("pos_count", self.cfg["main_n"]))
                if len(nums) >= pc:
                    rows.append(nums[:pc])
            elif self.game_type == "快乐8":
                rows.append(nums[:20])
            else:
                mn = self.cfg["main_n"]
                rows.append(nums[:mn])
        self._rows_cache = [r for r in rows if r]
        return self._rows_cache

    def _freq_omit(self, window=0):
        """返回 (freq dict, omit dict)。window>0 时只统计最近 window 期。"""
        from collections import Counter
        rows = self._all_main_rows()
        if window and window > 0:
            rows = rows[:window]
        mx = self.cfg["main_max"]
        flat = [n for row in rows for n in row if 1 <= n <= mx]
        freq = Counter(flat)
        omit = {}
        for n in range(1, mx+1):
            m = 0
            for row in rows:
                if n in row: break
                m += 1
            omit[n] = m
        return freq, omit

    def _hot_warm_cold(self, window=0):
        """按出现频次三等分热/温/冷，各返回号码列表（频次高→热）。window>0 时只看最近 window 期。"""
        freq, _ = self._freq_omit(window)
        mx = self.cfg["main_max"]
        ordered = sorted(range(1, mx+1), key=lambda x: -freq.get(x, 0))
        k = max(1, mx // 3)
        hot = ordered[:k]
        warm = ordered[k:2*k]
        cold = ordered[2*k:]
        return hot, warm, cold

    def _dragon_phoenix(self):
        """龙头(每期最小号)、凤尾(每期最大号)的历史按频次排序列表。"""
        from collections import Counter
        rows = self._all_main_rows()
        dragons = [min(r) for r in rows if r]
        phoenix = [max(r) for r in rows if r]
        d_ord = [n for n, _ in Counter(dragons).most_common()]
        p_ord = [n for n, _ in Counter(phoenix).most_common()]
        return d_ord, p_ord

    def _head_combo_stat(self):
        """号码头出组合统计：统计每期最小两个号码(头号组合)共同出现的频次，
        返回按频次排序的号码列表（常作为头部出现的号码）。"""
        from collections import Counter
        rows = self._all_main_rows()
        cnt = Counter()
        for r in rows:
            if len(r) >= 2:
                sr = sorted(r)
                cnt[sr[0]] += 1
                cnt[sr[1]] += 1
        return [n for n, _ in cnt.most_common()]

    def _cooccur_with(self, base):
        """全历史同出分析：返回与号码 base 在同一期共同出现次数最多的号码排序列表。带缓存。"""
        from collections import Counter
        if not hasattr(self, "_cooccur_cache"):
            self._cooccur_cache = {}
        if base in self._cooccur_cache:
            return self._cooccur_cache[base]
        c = Counter()
        for row in self._all_main_rows():
            if base in row:
                for x in row:
                    if x != base:
                        c[x] += 1
        res = [n for n, _ in c.most_common()]
        self._cooccur_cache[base] = res
        return res

    def _top_cooccur_group(self, k):
        """挑选历史同出最紧密的 k 个号码作为一组胆码（用频次最高号做种子，取其同出最多的 k-1 个）。"""
        freq, _ = self._freq_omit()
        if not freq:
            return list(range(1, k+1))
        seed = max(freq, key=lambda x: freq[x])
        partners = self._cooccur_with(seed)
        group = [seed] + partners[:max(0, k-1)]
        return sorted(set(group))[:k]

    def _kl8_recent_freq(self, window):
        """快乐8：统计最近 window 期里每个号码(1-80)的出现次数（近期热度）。"""
        from collections import Counter
        rows = self._all_main_rows()          # 最近在前
        if window and window > 0:
            rows = rows[:window]
        c = Counter()
        for row in rows:
            for n in row:
                if 1 <= n <= 80:
                    c[n] += 1
        return c

    def _kl8_zone_hot_dan(self, n_dan, gi, jitter, window=None, zones_count=None):
        """快乐8选胆：近期热度 + 分区均衡。
        把 1-80 均分成 zones_count 个区，每区按最近 window 期热度排序，
        然后跨区轮流取最热号，保证胆码既“近期热”又“分散在各区段”。
        gi/jitter 用于轮换，保证每组、每次点击都不同。"""
        main_max = 80
        window = int(window or KL8_RECENT_WINDOW)
        zones_count = max(1, int(zones_count or KL8_ZONES))
        recent = self._kl8_recent_freq(window)
        zone_size = (main_max + zones_count - 1) // zones_count
        zone_lists = []
        for z in range(zones_count):
            lo = z * zone_size + 1
            hi = min(main_max, (z + 1) * zone_size)
            if lo > main_max:
                break
            nums = list(range(lo, hi + 1))
            nums.sort(key=lambda x: (-recent.get(x, 0), x))   # 区内按近期热度降序
            if nums:                                          # 区内按 组+抖动 轮换，避免每组取同一个
                off = (gi + jitter) % len(nums)
                nums = nums[off:] + nums[:off]
            zone_lists.append(nums)
        Z = len(zone_lists)
        if Z == 0:
            return sorted(range(1, n_dan + 1))
        zstart = (gi + jitter) % Z                            # 轮换起始区
        zorder = list(range(zstart, Z)) + list(range(0, zstart))
        dan, idx = [], [0] * Z
        while len(dan) < n_dan:
            progressed = False
            for z in zorder:
                if len(dan) >= n_dan:
                    break
                zl = zone_lists[z]
                while idx[z] < len(zl) and zl[idx[z]] in dan:
                    idx[z] += 1
                if idx[z] < len(zl):
                    dan.append(zl[idx[z]]); idx[z] += 1; progressed = True
            if not progressed:
                break
        c = 1                                                 # 兜底补足
        while len(dan) < n_dan and c <= main_max:
            if c not in dan:
                dan.append(c)
            c += 1
        return sorted(dan[:n_dan])

    # ---------- UI ----------
    def _build_ui(self):
        lay = QVBoxLayout(self); lay.setSpacing(6)
        title = QLabel(f"🎯 {self.game_type} 多胆轮流")
        title.setStyleSheet("font-size:14px;font-weight:bold;color:white;padding:6px;"
            "background:qlineargradient(x1:0,y1:0,x2:1,y2:0,stop:0 #8E44AD,stop:1 #E74C3C);border-radius:5px;")
        title.setAlignment(Qt.AlignCenter); lay.addWidget(title)

        if not self.records:
            lay.addWidget(QLabel("⚠ 无历史数据，请先在首页【🔁 全量更新到最新】"))
            close_btn = QPushButton("关闭"); close_btn.clicked.connect(self.accept)
            lay.addWidget(close_btn); return

        from PySide6.QtWidgets import QFormLayout
        form = QFormLayout()
        self._dan_spin = QSpinBox()
        self._dan_spin.setRange(1, self.cfg["max_dan"])
        self._dan_spin.setValue(1 if self._is_positional_game else min(2, self.cfg["max_dan"]))
        dan_label = "每位胆码个数" if self._is_positional_game else f"胆码个数（1~{self.cfg['max_dan']}）"
        form.addRow(dan_label + ":", self._dan_spin)

        # V44/V52: 拖码个数可选。位置型表示每一位额外拖码数。
        self._tuo_spin = QSpinBox()
        tuo_label = "每位拖码个数" if self._is_positional_game else "拖码个数"
        form.addRow(tuo_label + ":", self._tuo_spin)
        self._dan_spin.valueChanged.connect(self._sync_tuo_range)

        self._mode_cb = QComboBox()
        self._mode_cb.addItems(["热温冷号轮流", "龙头凤尾轮流", "号码头出组合统计"])
        form.addRow("胆码来源策略:", self._mode_cb)

        # 近期窗口：用最近多少期统计热度（影响所有玩法的热温冷/频次排序；快乐8“近热分区”也用它）。
        self._window_cb = QComboBox()
        for _lbl, _val in [("全部历史", 0), ("最近30期", 30), ("最近50期", 50), ("最近100期", 100)]:
            self._window_cb.addItem(_lbl, _val)
        # 快乐8 默认最近50期更贴合短线；其余玩法默认全部历史，保持原有行为。
        self._window_cb.setCurrentIndex(2 if self.game_type == "快乐8" else 0)
        form.addRow("热度统计窗口:", self._window_cb)

        # 分区数：仅快乐8“近热分区”使用（把 1-80 均分成若干区做均衡选胆）。
        if self.game_type == "快乐8":
            self._zones_cb = QComboBox()
            for _z in (4, 6, 8, 10):
                self._zones_cb.addItem(f"{_z}区", _z)
            self._zones_cb.setCurrentIndex(2)   # 默认 8 区
            form.addRow("快乐8选胆分区:", self._zones_cb)

        # V50: 套餐票不再硬编码，直接读取程序原有 SSQPackageDialog / DLTPackageDialog 的套餐定义。
        # 普通模式仍按原来的“组数”生成；套餐模式下“轮流生成组数”表示套餐张数。
        self._package_cb = QComboBox()
        self._package_cb.addItem("普通多胆轮流", "normal")
        if not self._is_positional_game:
            if self.game_type == "双色球":
                for pkg_name in SSQPackageDialog._SSQ_PACKAGES.keys():
                    self._package_cb.addItem(pkg_name, pkg_name)
            elif self.game_type == "大乐透":
                for pkg_name in DLTPackageDialog._DLT_PACKAGES.keys():
                    self._package_cb.addItem(pkg_name, pkg_name)
            form.addRow("套餐票模式:", self._package_cb)

        # V47: 指定开奖历史下拉框。选中某期后，生成结果会按该期开奖结果逐组对比命中个数。
        self._history_cb = QComboBox()
        self._history_cb.setMinimumHeight(32)
        for idx, rec in enumerate(self.records[:300]):
            issue = str(rec.get("期号", ""))
            date_s = str(rec.get("开奖日期", ""))[:10]
            nums_s = str(rec.get("开奖号码", ""))
            label = f"{issue} {date_s}  {nums_s}".strip()
            self._history_cb.addItem(label, idx)
        self._history_cb.currentIndexChanged.connect(self._refresh_output_compare)
        form.addRow("开奖历史对比:", self._history_cb)

        self._cnt_spin = QSpinBox(); self._cnt_spin.setRange(1, 200); self._cnt_spin.setValue(10)
        form.addRow("轮流生成组数/套餐张数:", self._cnt_spin)
        lay.addLayout(form)
        self._sync_tuo_range()

        gen_btn = QPushButton("🎲 生成多胆轮流号码")
        gen_btn.setStyleSheet("background:#27AE60;color:white;font-weight:bold;padding:9px;font-size:14px;border-radius:5px;")
        gen_btn.clicked.connect(self._generate)
        lay.addWidget(gen_btn)

        self._out = QTextEdit(); self._out.setReadOnly(True)
        self._out.setFont(QFont("Courier New", 10))
        lay.addWidget(self._out, 1)

        row = QHBoxLayout()
        copy_btn = QPushButton("📋 复制号码")
        copy_btn.setStyleSheet("background:#2980B9;color:white;font-weight:bold;padding:7px;")
        copy_btn.clicked.connect(self._copy_numbers)
        bet_btn = QPushButton("💰 全部投注")
        bet_btn.setStyleSheet("background:#E67E22;color:white;font-weight:bold;padding:7px;")
        bet_btn.clicked.connect(self._bet_all)
        close_btn = QPushButton("关闭"); close_btn.clicked.connect(self.accept)
        row.addWidget(copy_btn); row.addWidget(bet_btn); row.addStretch(); row.addWidget(close_btn)
        lay.addLayout(row)

    def _sync_tuo_range(self, *args):
        """根据胆码数自动限制拖码数量。单式条件：胆码 + 拖码 = 主区应选数。"""
        if not hasattr(self, "_tuo_spin"):
            return
        dan = self._dan_spin.value()
        old = self._tuo_spin.value()
        if self._is_positional_game:
            # 位置型：每位数字池 = 胆 + 拖；每位最多10个数字，七星彩最后一位最多15个。
            max_digit_pool = max((hi - lo + 1) for lo, hi in self.cfg.get("pos_ranges", [(0, 9)]))
            min_tuo = 0
            max_tuo = max(0, max_digit_pool - dan)
            self._tuo_spin.setRange(min_tuo, max_tuo)
            default_tuo = min(max_tuo, 1)
            self._tuo_spin.setValue(old if min_tuo <= old <= max_tuo else default_tuo)
            return
        main_n = 10 if self.game_type == "快乐8" else self.cfg["main_n"]
        min_tuo = max(1, main_n - dan)
        max_tuo = max(min_tuo, self.cfg["main_max"] - dan)
        self._tuo_spin.setRange(min_tuo, max_tuo)
        # 默认给用户一个比单式多一点的拖码池；双色球2胆默认4拖刚好单式。
        default_tuo = min(max_tuo, max(min_tuo, main_n - dan))
        self._tuo_spin.setValue(old if min_tuo <= old <= max_tuo else default_tuo)

    # ---------- 历史对比 ----------
    def _history_compare_text(self, main_pool, sub=None, limit=30):
        """返回最近历史对比摘要：最大主区重号、完全相同主区是否出现。"""
        pool = set(main_pool or [])
        if not pool:
            return "历史: 无"
        best_issue, best_hit, best_nums = "", -1, []
        exact_issue = ""
        for r in self.records[:limit]:
            nums = parse_draw_numbers(str(r.get("开奖号码", "")))
            if self.game_type == "快乐8":
                row = nums[:20]
            else:
                row = nums[:self.cfg["main_n"]]
            hit_nums = sorted(pool & set(row))
            if len(hit_nums) > best_hit:
                best_issue = str(r.get("期号", ""))
                best_hit = len(hit_nums)
                best_nums = hit_nums
            # 只有生成结果本身就是单式时才判断完全相同
            if len(pool) == (10 if self.game_type == "快乐8" else self.cfg["main_n"]) and set(row) == pool:
                exact_issue = str(r.get("期号", ""))
                break
        if best_hit < 0:
            return f"历史{limit}期: 无可比对数据"
        hit_s = " ".join(f"{x:02d}" for x in best_nums) if best_nums else "无"
        exact_s = f"；主区同号:{exact_issue}" if exact_issue else "；主区同号:未见"
        return f"历史{limit}期最高重号:{best_hit}个({best_issue}) {hit_s}{exact_s}"

    def _h(self, text):
        """HTML转义，供QTextEdit红色命中号码显示使用。"""
        import html
        return html.escape(str(text), quote=False)

    def _num_html(self, n, hit=False, width=2):
        """格式化号码；命中号码显示红色加粗。"""
        try:
            text = f"{int(n):0{width}d}"
        except Exception:
            text = str(n)
        if hit:
            return f'<span style="color:#E60000;font-weight:bold;">{self._h(text)}</span>'
        return self._h(text)

    def _num_list_html(self, nums, hit_set=None, sep=" ", width=2):
        nums = list(nums or [])
        if not nums:
            return "无"
        hit_set = set(hit_set or [])
        return sep.join(self._num_html(x, x in hit_set, width) for x in nums)

    def _set_out_html_lines(self, lines):
        """把带<span>的行写入结果框；普通文字需调用 _h 后再放入。"""
        self._out.setHtml('<pre style="font-family:Courier New,monospace;font-size:10pt;white-space:pre-wrap;">' + "\n".join(lines) + '</pre>')

    def _history_compare_html(self, main_pool, sub=None, limit=30):
        """最近历史对比摘要：命中的重号用红色显示。"""
        pool = set(main_pool or [])
        if not pool:
            return "历史: 无"
        best_issue, best_hit, best_nums = "", -1, []
        exact_issue = ""
        for r in self.records[:limit]:
            nums = parse_draw_numbers(str(r.get("开奖号码", "")))
            if self.game_type == "快乐8":
                row = nums[:20]
            else:
                row = nums[:self.cfg["main_n"]]
            hit_nums = sorted(pool & set(row))
            if len(hit_nums) > best_hit:
                best_issue = str(r.get("期号", ""))
                best_hit = len(hit_nums)
                best_nums = hit_nums
            if len(pool) == (10 if self.game_type == "快乐8" else self.cfg["main_n"]) and set(row) == pool:
                exact_issue = str(r.get("期号", ""))
                break
        if best_hit < 0:
            return f"历史{limit}期: 无可比对数据"
        hit_s = self._num_list_html(best_nums, set(best_nums)) if best_nums else "无"
        exact_s = f"；主区同号:{self._h(exact_issue)}" if exact_issue else "；主区同号:未见"
        return f"历史{limit}期最高重号:{best_hit}个({self._h(best_issue)}) {hit_s}{exact_s}"

    def _selected_compare_html(self, ticket):
        """按下拉选中的开奖期对比；命中号码用红色显示。"""
        rec = self._selected_history_record()
        if not rec:
            return "选期对比: 无历史记录"
        draw_main, draw_sub = self._draw_parts(rec)
        if not draw_main:
            return "选期对比: 该期无可解析开奖号码"
        dan = sorted(ticket.get("dan", []))
        tuo = sorted(ticket.get("tuo", []))
        sub = sorted(ticket.get("sub", []))
        main_pool = sorted(set(dan + tuo))
        main_hit_nums = sorted(set(main_pool) & set(draw_main))
        sub_hit_nums = sorted(set(sub) & set(draw_sub)) if sub and draw_sub else []
        issue = str(rec.get("期号", ""))
        main_s = self._num_list_html(main_hit_nums, set(main_hit_nums)) if main_hit_nums else "无"
        main_n = 10 if self.game_type == "快乐8" else self.cfg["main_n"]
        is_single = len(dan) + len(tuo) == main_n
        if is_single:
            text = f"对比{self._h(issue)}: 主区中{len(main_hit_nums)}个({main_s})"
        else:
            dan_hit = sorted(set(dan) & set(draw_main))
            tuo_hit = sorted(set(tuo) & set(draw_main))
            text = (f"对比{self._h(issue)}: 主区中{len(main_hit_nums)}个({main_s}) "
                    f"胆中{len(dan_hit)}个/拖中{len(tuo_hit)}个")
        if self.game_type in ("双色球", "大乐透") and sub:
            sub_s = self._num_list_html(sub_hit_nums, set(sub_hit_nums)) if sub_hit_nums else "无"
            text += f"；副区中{len(sub_hit_nums)}个({sub_s})"
        elif self.game_type == "七乐彩" and draw_sub:
            special_hit = sorted(set(main_pool) & set(draw_sub))
            if special_hit:
                text += f"；特别号中1个({self._num_html(special_hit[0], True)})"
            else:
                text += "；特别号中0个"
        return text

    def _selected_pos_compare_html(self, ticket):
        """位置型玩法选期对比；命中位号码用红色显示。"""
        rec = self._selected_history_record()
        if not rec:
            return "选期对比: 无历史记录"
        draw_main, _ = self._draw_parts(rec)
        if not draw_main:
            return "选期对比: 该期无可解析开奖号码"
        hit_pos = []
        for i, pos in enumerate(ticket.get("positions", [])):
            if i < len(draw_main):
                pool = set(pos.get("dan", [])) | set(pos.get("tuo", []))
                if draw_main[i] in pool:
                    hit_pos.append((i + 1, draw_main[i]))
        issue = str(rec.get("期号", ""))
        hit_s = " ".join(f"第{pi}位:{self._pos_num_html(num, True)}" for pi, num in hit_pos) if hit_pos else "无"
        return f"对比{self._h(issue)}: 中{len(hit_pos)}位({hit_s})"

    def _selected_history_record(self):
        """返回下拉框当前选中的开奖历史记录。"""
        try:
            if not hasattr(self, "_history_cb") or self._history_cb.count() <= 0:
                return self.records[0] if self.records else None
            idx = self._history_cb.currentData()
            if idx is None:
                idx = self._history_cb.currentIndex()
            idx = int(idx)
            return self.records[idx] if 0 <= idx < len(self.records) else None
        except Exception:
            return self.records[0] if self.records else None

    def _draw_parts(self, rec):
        """把一条开奖记录拆成主区/副区号码。"""
        nums = parse_draw_numbers(str((rec or {}).get("开奖号码", "")))
        if not nums:
            return [], []
        if self.game_type == "快乐8":
            return nums[:20], []
        if self.game_type == "双色球":
            return nums[:6], nums[6:7]
        if self.game_type == "大乐透":
            return nums[:5], nums[5:7]
        if self.game_type == "七乐彩":
            # 七乐彩第8个为特别号；本功能主要按前7个基本号对比。
            return nums[:7], nums[7:8]
        if self._is_positional_game:
            pc = int(self.cfg.get("pos_count", self.cfg["main_n"]))
            return nums[:pc], []
        return nums[:self.cfg["main_n"]], []

    def _selected_compare_text(self, ticket):
        """按用户下拉选中的开奖期，对当前组号码给出命中个数。"""
        rec = self._selected_history_record()
        if not rec:
            return "选期对比: 无历史记录"
        draw_main, draw_sub = self._draw_parts(rec)
        if not draw_main:
            return "选期对比: 该期无可解析开奖号码"
        dan = sorted(ticket.get("dan", []))
        tuo = sorted(ticket.get("tuo", []))
        sub = sorted(ticket.get("sub", []))
        main_pool = sorted(set(dan + tuo))
        main_hit_nums = sorted(set(main_pool) & set(draw_main))
        sub_hit_nums = sorted(set(sub) & set(draw_sub)) if sub and draw_sub else []
        issue = str(rec.get("期号", ""))
        main_s = " ".join(f"{x:02d}" for x in main_hit_nums) if main_hit_nums else "无"
        # 单式时可直接显示总命中；胆拖时显示“胆中/拖中”，便于看胆码质量。
        main_n = 10 if self.game_type == "快乐8" else self.cfg["main_n"]
        is_single = len(dan) + len(tuo) == main_n
        if is_single:
            text = f"对比{issue}: 主区中{len(main_hit_nums)}个({main_s})"
        else:
            dan_hit = sorted(set(dan) & set(draw_main))
            tuo_hit = sorted(set(tuo) & set(draw_main))
            text = (f"对比{issue}: 主区中{len(main_hit_nums)}个({main_s}) "
                    f"胆中{len(dan_hit)}个/拖中{len(tuo_hit)}个")
        if self.game_type in ("双色球", "大乐透") and sub:
            sub_s = " ".join(f"{x:02d}" for x in sub_hit_nums) if sub_hit_nums else "无"
            text += f"；副区中{len(sub_hit_nums)}个({sub_s})"
        elif self.game_type == "七乐彩" and draw_sub:
            # 七乐彩特别号只作提示，不参与主区中奖个数。
            special_hit = sorted(set(main_pool) & set(draw_sub))
            if special_hit:
                text += f"；特别号中1个({special_hit[0]:02d})"
            else:
                text += "；特别号中0个"
        return text

    # ---------- 位置型玩法（3D/七星彩/排列三/排列五） ----------
    def _pos_freq_omit(self, window=0):
        """位置型统计：返回每一位的频次、遗漏。window>0 时只看最近 window 期。"""
        from collections import Counter
        pc = int(self.cfg.get("pos_count", self.cfg["main_n"]))
        ranges = self.cfg.get("pos_ranges", [(0, 9)] * pc)
        rows = self._all_main_rows()
        if window and window > 0:
            rows = rows[:window]
        freqs, omits = [], []
        for pi in range(pc):
            lo, hi = ranges[pi]
            c = Counter(row[pi] for row in rows if len(row) > pi and lo <= row[pi] <= hi)
            omit = {}
            for d in range(lo, hi + 1):
                miss = 0
                for row in rows:
                    if len(row) > pi and row[pi] == d:
                        break
                    miss += 1
                omit[d] = miss
            freqs.append(c); omits.append(omit)
        return freqs, omits

    def _generate_positional(self):
        """位置型多胆轮流：每一位生成 胆码池 + 拖码池，单式时每位只有1个数字。"""
        import random
        n_dan = self._dan_spin.value()
        n_tuo = self._tuo_spin.value()
        n_groups = self._cnt_spin.value()
        mode = self._mode_cb.currentText()
        pc = int(self.cfg.get("pos_count", self.cfg["main_n"]))
        ranges = self.cfg.get("pos_ranges", [(0, 9)] * pc)
        # 位置型每位热度也按界面所选“热度统计窗口”统计
        sel_window = int(self._window_cb.currentData() or 0) if hasattr(self, "_window_cb") else 0
        freqs, omits = self._pos_freq_omit(sel_window)
        tickets = []
        base = int(getattr(self, "_rotation_cursor", 0))
        for gi in range(n_groups):
            ri = base + gi          # 轮流游标：连续点击继续往后轮换
            positions = []
            for pi in range(pc):
                lo, hi = ranges[pi]
                all_digits = list(range(lo, hi + 1))
                if mode == "龙头凤尾轮流":
                    ordered = sorted(all_digits, key=lambda d: (-omits[pi].get(d, 0), -freqs[pi].get(d, 0), d))
                elif mode == "号码头出组合统计":
                    # 位置型没有头号组合概念，这里用“遗漏优先 + 频次”替代，避免空结果。
                    ordered = sorted(all_digits, key=lambda d: (-omits[pi].get(d, 0), freqs[pi].get(d, 0), d))
                else:
                    ordered = sorted(all_digits, key=lambda d: (-freqs[pi].get(d, 0), omits[pi].get(d, 0), d))
                if ordered:
                    shift = (ri + pi) % len(ordered)
                    ordered = ordered[shift:] + ordered[:shift]
                dan = ordered[:min(n_dan, len(ordered))]
                rest = [d for d in ordered if d not in set(dan)]
                tuo = rest[:min(n_tuo, len(rest))]
                while len(dan) < min(n_dan, len(all_digits)):
                    d = random.choice(all_digits)
                    if d not in dan:
                        dan.append(d)
                while len(tuo) < min(n_tuo, max(0, len(all_digits) - len(dan))):
                    d = random.choice(all_digits)
                    if d not in dan and d not in tuo:
                        tuo.append(d)
                positions.append({"dan": sorted(dan), "tuo": sorted(tuo)})
            tickets.append({"positions": positions})
        self._tickets = tickets
        self._rotation_cursor = base + n_groups
        self._render_positional_tickets()

    def _pos_ticket_units(self, ticket):
        """位置型注数 = 各位置可选数字数乘积。"""
        total = 1
        for pos in ticket.get("positions", []):
            total *= max(0, len(set(pos.get("dan", [])) | set(pos.get("tuo", []))))
        return total

    def _selected_pos_compare_text(self, ticket):
        rec = self._selected_history_record()
        if not rec:
            return "选期对比: 无历史记录"
        draw_main, _ = self._draw_parts(rec)
        if not draw_main:
            return "选期对比: 该期无可解析开奖号码"
        hit_pos = []
        for i, pos in enumerate(ticket.get("positions", [])):
            if i < len(draw_main):
                pool = set(pos.get("dan", [])) | set(pos.get("tuo", []))
                if draw_main[i] in pool:
                    hit_pos.append((i + 1, draw_main[i]))
        issue = str(rec.get("期号", ""))
        hit_s = " ".join(f"第{pi}位:{self._pos_fmt(num)}" for pi, num in hit_pos) if hit_pos else "无"
        return f"对比{issue}: 中{len(hit_pos)}位({hit_s})"

    def _render_positional_tickets(self):
        if not getattr(self, "_tickets", None):
            return
        n_dan = self._dan_spin.value()
        n_tuo = self._tuo_spin.value()
        mode = self._mode_cb.currentText()
        lines = [self._h(f"=== {self.game_type} 位置型多胆轮流（每位{n_dan}胆{n_tuo}拖 · {mode}）===")]
        rec = self._selected_history_record()
        if rec:
            lines.append(self._h(f"开奖历史对比期：{rec.get('期号','')} {str(rec.get('开奖日期',''))[:10]}  {rec.get('开奖号码','')}"))
        for gi, ticket in enumerate(self._tickets):
            parts = []
            single_digits = []
            is_single = True
            for pi, pos in enumerate(ticket.get("positions", []), start=1):
                dan = sorted(pos.get("dan", [])); tuo = sorted(pos.get("tuo", []))
                pool = sorted(set(dan) | set(tuo))
                if len(pool) == 1:
                    single_digits.append(pool[0])
                    parts.append(f"第{pi}位:{self._pos_fmt(pool[0], pi)}")
                else:
                    is_single = False
                    parts.append(f"第{pi}位 胆:{','.join(self._pos_fmt(x, pi) for x in dan)} 拖:{','.join(self._pos_fmt(x, pi) for x in tuo)}")
            units = self._pos_ticket_units(ticket)
            chosen = self._selected_pos_compare_html(ticket)
            if is_single:
                nums = self._h(" ".join(self._pos_fmt(x, idx+1) for idx, x in enumerate(single_digits)))
                lines.append(f"第{gi+1:02d}组 [单式] {nums}  ｜{chosen}")
            else:
                lines.append(self._h(f"第{gi+1:02d}组 " + "；".join(parts) + f"  {units}注 ｜") + chosen)
        lines += ["", self._h("复制规则：位置型单式只复制号码；每位多码时显示各位胆/拖。"), self._h(f"共 {len(self._tickets)} 组。点【全部投注】写入投注记录。")]
        self._set_out_html_lines(lines)

    def _render_tickets(self):
        """把当前 self._tickets 重新渲染到文本框；切换历史下拉框时复用。"""
        if self._is_positional_game:
            self._render_positional_tickets()
            return
        if not getattr(self, "_tickets", None):
            return
        n_dan = self._dan_spin.value()
        n_tuo = self._tuo_spin.value()
        mode = self._mode_cb.currentText()
        main_n = 10 if self.game_type == "快乐8" else self.cfg["main_n"]
        lines = [self._h(f"=== {self.game_type} 多胆轮流（{n_dan}胆{n_tuo}拖 · {mode}）===")]
        rec = self._selected_history_record()
        if rec:
            lines.append(self._h(f"开奖历史对比期：{rec.get('期号','')} {str(rec.get('开奖日期',''))[:10]}  {rec.get('开奖号码','')}"))
        for gi, ticket in enumerate(self._tickets):
            dan = sorted(ticket.get("dan", []))
            tuo = sorted(ticket.get("tuo", []))
            sub = sorted(ticket.get("sub", []))
            is_single = len(dan) + len(tuo) == main_n
            main_pool = sorted(dan + tuo)
            sub_str = ("  +  " + " ".join(f"{x:02d}" for x in sub)) if sub else ""
            hist = self._history_compare_html(main_pool, sub)
            chosen = self._selected_compare_html(ticket)
            if is_single:
                main_str = self._h(" ".join(f"{x:02d}" for x in main_pool))
                lines.append(f"第{gi+1:02d}组 [单式] {main_str}{self._h(sub_str)}  ｜{chosen} ｜{hist}")
            else:
                dan_str = " ".join(f"{x:02d}" for x in dan)
                tuo_str = " ".join(f"{x:02d}" for x in tuo)
                need = main_n - len(dan)
                bets = math_comb(len(tuo), need)
                prefix = self._h(f"第{gi+1:02d}组 [胆:{dan_str}] [拖:{tuo_str}]{sub_str}  {bets}注 ｜")
                lines.append(prefix + chosen + " ｜" + hist)
        lines += ["", self._h("复制规则：单式只复制号码；非单式才显示胆/拖。"), self._h(f"共 {len(self._tickets)} 组。点【全部投注】写入投注记录。")]
        self._set_out_html_lines(lines)

    def _refresh_output_compare(self, *args):
        """切换开奖历史期号时，不重新生成号码，只刷新命中对比。"""
        try:
            if getattr(self, "_tickets", None) and self._tickets and self._tickets[0].get("package"):
                pkg_name = str(self._tickets[0].get("package", "套餐"))
                pack_count = max(t.get("package_no", 1) for t in self._tickets)
                self._render_package_tickets(pkg_name, pack_count)
            else:
                self._render_tickets()
        except Exception as e:
            logger.error(f"多胆轮流刷新历史对比失败: {e}", exc_info=True)

    def _format_copy_line(self, ticket):
        """复制格式：单式只复制号码；非单式胆拖才显示胆/拖。"""
        if self._is_positional_game and ticket.get("positions"):
            pools = []
            for pos in ticket.get("positions", []):
                pools.append(sorted(set(pos.get("dan", [])) | set(pos.get("tuo", []))))
            if all(len(p) == 1 for p in pools):
                return "".join(self._pos_fmt(p[0], i+1) for i, p in enumerate(pools))
            parts = []
            for i, pos in enumerate(ticket.get("positions", []), start=1):
                dan_s = ",".join(self._pos_fmt(x, i) for x in sorted(pos.get("dan", [])))
                tuo_s = ",".join(self._pos_fmt(x, i) for x in sorted(pos.get("tuo", [])))
                parts.append(f"第{i}位胆:{dan_s}拖:{tuo_s}")
            return " ".join(parts)
        main_n = 10 if self.game_type == "快乐8" else self.cfg["main_n"]
        dan = sorted(ticket.get("dan", []))
        tuo = sorted(ticket.get("tuo", []))
        sub = sorted(ticket.get("sub", []))
        is_single = len(dan) + len(tuo) == main_n
        if is_single:
            main = sorted(dan + tuo)
            if self.game_type in ("双色球", "大乐透"):
                return ",".join(f"{x:02d}" for x in main) + "|" + ",".join(f"{x:02d}" for x in sub)
            return ",".join(f"{x:02d}" for x in main)
        dan_s = ",".join(f"{x:02d}" for x in dan)
        tuo_s = ",".join(f"{x:02d}" for x in tuo)
        sub_s = (" 后区:" if self.game_type == "大乐透" else " 蓝球:") + ",".join(f"{x:02d}" for x in sub) if sub else ""
        return f"胆:{dan_s} 拖:{tuo_s}{sub_s}"

    # ---------- 套餐票生成辅助 ----------
    def _package_code(self):
        try:
            return self._package_cb.currentData() if hasattr(self, "_package_cb") else "normal"
        except Exception:
            return "normal"

    def _strategy_helpers(self, main_max):
        """供普通多胆和套餐票共用：返回选号策略所需的统计池。"""
        freq, omit = self._freq_omit()
        hot, warm, cold = self._hot_warm_cold()
        dragons, phoenix = self._dragon_phoenix()
        head_nums = self._head_combo_stat()
        all_by_freq = sorted(range(1, main_max + 1), key=lambda x: -freq.get(x, 0))
        return freq, omit, hot, warm, cold, dragons, phoenix, head_nums, all_by_freq

    def _ordered_unique_for_package(self, seq, main_max):
        out, seen = [], set()
        for x in seq:
            try:
                x = int(x)
            except Exception:
                continue
            if 1 <= x <= main_max and x not in seen:
                out.append(x); seen.add(x)
        return out

    def _package_ranked(self, mode, main_max, hot, warm, cold, dragons, phoenix, head_nums, all_by_freq):
        """套餐票用：策略排序后的完整候选列表（长度=main_max），供环形窗口轮换。"""
        if mode == "龙头凤尾轮流":
            ranked = self._ordered_unique_for_package(list(dragons) + list(phoenix) + list(all_by_freq), main_max)
        elif mode == "号码头出组合统计":
            ranked = self._ordered_unique_for_package(list(head_nums) + list(all_by_freq), main_max)
        else:
            ranked = self._ordered_unique_for_package(list(hot) + list(warm) + list(cold) + list(all_by_freq), main_max)
        for x in all_by_freq:
            if x not in ranked:
                ranked.append(x)
        return ranked

    def _package_dan_for_line(self, line_index, n_dan, mode, main_max, hot, warm, cold, dragons, phoenix, head_nums, all_by_freq):
        """套餐票胆码（与多胆轮流同策略）：
        1胆=严格 01→最大号顺序；2胆=同号组合；3胆=1热1温1冷；
        4胆=按玩法号码池组合；5胆及以上=得分(频次)+同出号码组合。"""
        if n_dan == 1:
            return [line_index % main_max + 1]
        # 快乐8 多胆：近期热度 + 分区均衡
        if getattr(self, "game_type", "") == "快乐8":
            return self._kl8_zone_hot_dan(n_dan, line_index, 0)
        ranked = self._package_ranked(mode, main_max, hot, warm, cold, dragons, phoenix, head_nums, all_by_freq)
        Lr = len(ranked)

        def _fill(dan):
            dan = self._ordered_unique_for_package(dan, main_max)
            i = 0
            while len(dan) < n_dan and i < Lr:
                if ranked[i] not in dan:
                    dan.append(ranked[i])
                i += 1
            c = 1
            while len(dan) < n_dan and c <= main_max:
                if c not in dan:
                    dan.append(c)
                c += 1
            return sorted(dan[:n_dan])

        if n_dan == 2:
            if Lr == 0:
                return _fill([])
            seed = ranked[(line_index * 2) % Lr]
            partners = [p for p in self._cooccur_with(seed) if p != seed]
            return _fill([seed] + partners[:1])

        if n_dan == 3:
            h = list(hot) or list(all_by_freq)
            w = list(warm) or list(all_by_freq)
            cd = list(cold) or list(all_by_freq)
            d = []
            if h:  d.append(h[line_index % len(h)])
            if w:  d.append(w[line_index % len(w)])
            if cd: d.append(cd[line_index % len(cd)])
            return _fill(d)

        if n_dan == 4:
            if Lr == 0:
                return _fill([])
            off = (line_index * 4) % Lr
            rot = ranked[off:] + ranked[:off]
            return _fill(rot[:n_dan])

        score_ranked = list(all_by_freq) or ranked
        if not score_ranked:
            return _fill([])
        seed = score_ranked[(line_index * max(1, n_dan)) % len(score_ranked)]
        dan = self._ordered_unique_for_package([seed] + self._cooccur_with(seed) + score_ranked, main_max)
        return _fill(dan[:n_dan])

    def _package_tuo_for_dan(self, dan, line_index, n_tuo, mode, main_max, hot, warm, cold, dragons, phoenix, head_nums, all_by_freq):
        import random
        ranked = self._package_ranked(mode, main_max, hot, warm, cold, dragons, phoenix, head_nums, all_by_freq)
        danset = set(dan)
        pool = self._ordered_unique_for_package([x for x in ranked if x not in danset], main_max)
        if pool:
            off = (line_index * max(1, n_tuo) + 13) % len(pool)
            pool = pool[off:] + pool[:off]
        tuo = pool[:n_tuo]
        while len(tuo) < n_tuo:
            c = random.randint(1, main_max)
            if c not in danset and c not in tuo:
                tuo.append(c)
        return sorted(tuo)

    def _gen_sub_n(self, sn):
        """生成指定个数副区号码；套餐票用于双色球6+4、大乐透5+3。"""
        import random
        if not self.cfg["has_sub"] or self.cfg["sub_max"] <= 0 or sn <= 0:
            return []
        smax = self.cfg["sub_max"]
        sn = min(sn, smax)
        from collections import Counter
        c = Counter()
        for r in self.records:
            nums = parse_draw_numbers(str(r.get("开奖号码", "")))
            if self.game_type == "双色球" and len(nums) >= 7:
                c[nums[6]] += 1
            elif self.game_type == "大乐透" and len(nums) >= 7:
                c[nums[5]] += 1; c[nums[6]] += 1
        pool = sorted(range(1, smax + 1), key=lambda x: -c.get(x, 0))
        top = pool[:max(sn + 4, smax // 2)] or list(range(1, smax + 1))
        random.shuffle(top)
        return sorted(top[:sn])

    def _package_defs(self):
        """返回当前玩法原程序里的套餐票定义。"""
        if self.game_type == "双色球":
            return SSQPackageDialog._SSQ_PACKAGES
        if self.game_type == "大乐透":
            return DLTPackageDialog._DLT_PACKAGES
        return {}

    def _package_ticket_units(self, ticket):
        """按多胆码语义计算一行票实际注数：主区若有胆码则胆码固定，拖码组合补足；副区按复式展开。"""
        dan = sorted(ticket.get("dan", []))
        tuo = sorted(ticket.get("tuo", []))
        sub = sorted(ticket.get("sub", []))
        main_n = self.cfg["main_n"]
        need = main_n - len(dan)
        if need < 0 or len(tuo) < need:
            return 0
        main_units = math_comb(len(tuo), need) if len(dan) > 0 else math_comb(len(dan) + len(tuo), main_n)
        if self.game_type == "双色球":
            sub_units = max(1, len(sub))
        elif self.game_type == "大乐透":
            sub_units = math_comb(len(sub), 2) if len(sub) >= 2 else 0
        else:
            sub_units = 1
        return main_units * sub_units

    def _package_price_per_unit(self):
        """多胆窗口暂不带大乐透追加选项；套餐金额按原套餐基础单价计算。"""
        return 2

    def _generate_package_tickets(self, code):
        """生成双色球/大乐透套餐票。套餐结构直接使用程序原有套餐票定义。"""
        if self.game_type not in ("双色球", "大乐透") or code in (None, "normal"):
            return False
        packages = self._package_defs()
        pkg_name = str(code)
        detail = packages.get(pkg_name)
        if not detail:
            QMessageBox.warning(self, "提示", f"没有找到套餐定义：{pkg_name}")
            return True

        n_dan = self._dan_spin.value()
        pack_count = self._cnt_spin.value()
        mode = self._mode_cb.currentText()
        main_n = self.cfg["main_n"]
        main_max = self.cfg["main_max"]
        if n_dan >= main_n:
            QMessageBox.warning(self, "提示", f"{self.game_type} 套餐票至少需要保留1个拖码")
            return True

        freq, omit, hot, warm, cold, dragons, phoenix, head_nums, all_by_freq = self._strategy_helpers(main_max)
        tickets = []
        global_line = int(getattr(self, "_rotation_cursor", 0))
        for pack_i in range(pack_count):
            line_in_pack = 0
            for bet_type, main_count, sub_count, repeat in detail:
                # 原套餐定义里的“红球数/前区数”就是这一行主区总选号数量。
                # 多胆模式下：胆码固定，拖码补足到该套餐行需要的主区个数。
                main_count = int(main_count)
                sub_count = int(sub_count)
                repeat = int(repeat)
                if main_count < main_n:
                    # 理论上原套餐不会出现；兜底避免崩溃。
                    main_count = main_n
                n_tuo = max(1, main_count - n_dan)
                for _ in range(repeat):
                    dan = self._package_dan_for_line(global_line, n_dan, mode, main_max, hot, warm, cold, dragons, phoenix, head_nums, all_by_freq)
                    tuo = self._package_tuo_for_dan(dan, global_line, n_tuo, mode, main_max, hot, warm, cold, dragons, phoenix, head_nums, all_by_freq)
                    sub = self._gen_sub_n(sub_count)
                    desc = f"{bet_type} {main_count}+{sub_count}"
                    tickets.append({"dan": dan, "tuo": tuo, "sub": sub,
                                    "package": pkg_name, "package_no": pack_i + 1,
                                    "package_line": line_in_pack + 1, "package_desc": desc,
                                    "package_bet_type": bet_type,
                                    "package_main_count": main_count,
                                    "package_sub_count": sub_count})
                    global_line += 1
                    line_in_pack += 1
        self._tickets = tickets
        self._rotation_cursor = global_line
        self._render_package_tickets(pkg_name, pack_count)
        return True

    def _render_package_tickets(self, pkg_name, pack_count):
        if not getattr(self, "_tickets", None):
            return
        n_dan = self._dan_spin.value()
        mode = self._mode_cb.currentText()
        lines = [self._h(f"=== {self.game_type}{pkg_name} · 按原套餐票规则 · {n_dan}胆 · {mode} ===")]
        rec = self._selected_history_record()
        if rec:
            lines.append(self._h(f"开奖历史对比期：{rec.get('期号','')} {str(rec.get('开奖日期',''))[:10]}  {rec.get('开奖号码','')}"))
        last_pack = None
        total_units = 0
        for i, ticket in enumerate(self._tickets):
            pack_no = ticket.get("package_no", 1)
            if pack_no != last_pack:
                lines.append(self._h(f"\n--- {pkg_name}第{pack_no:02d}张 ---"))
                last_pack = pack_no
            dan = sorted(ticket.get("dan", []))
            tuo = sorted(ticket.get("tuo", []))
            sub = sorted(ticket.get("sub", []))
            main_pool = sorted(dan + tuo)
            main_str = " ".join(f"{x:02d}" for x in main_pool)
            sub_str = ("  +  " + " ".join(f"{x:02d}" for x in sub)) if sub else ""
            chosen = self._selected_compare_html(ticket)
            hist = self._history_compare_html(main_pool, sub)
            desc = ticket.get("package_desc", "")
            units = self._package_ticket_units(ticket)
            total_units += units
            if len(main_pool) == self.cfg["main_n"]:
                tag = "单式"
            else:
                tag = f"胆:{' '.join(f'{x:02d}' for x in dan)} 拖:{' '.join(f'{x:02d}' for x in tuo)}"
            prefix = self._h(f"第{i+1:02d}注 [{desc}] [{tag}] {main_str}{sub_str}  {units}注 ｜")
            lines.append(prefix + chosen + " ｜" + hist)
        price = self._package_price_per_unit()
        lines += ["", self._h("套餐规则来源：使用程序原有 SSQPackageDialog / DLTPackageDialog 的套餐定义。"),
                  self._h("复制规则：主区刚好是单式时只复制号码；不是单式时显示胆/拖。"),
                  self._h(f"共 {pack_count} 张套餐票，折合 {total_units} 注，金额约 {total_units * price} 元。")]
        self._set_out_html_lines(lines)

    # ---------- 生成 ----------
    def _generate(self):
        """多胆轮流生成：胆码轮换，拖码池数量由用户指定；结果附带历史对比。"""
        if self._is_positional_game:
            self._generate_positional()
            return
        if self._generate_package_tickets(self._package_code()):
            return
        import random
        n_dan = self._dan_spin.value()
        n_tuo = self._tuo_spin.value()
        n_groups = self._cnt_spin.value()
        mode = self._mode_cb.currentText()
        main_n = 10 if self.game_type == "快乐8" else self.cfg["main_n"]
        main_max = self.cfg["main_max"]
        need_tuo = main_n - n_dan
        if n_tuo < need_tuo:
            QMessageBox.warning(self, "提示", f"拖码不足：{n_dan}胆至少需要{need_tuo}个拖码")
            return

        # 读取界面所选“热度统计窗口”（影响所有玩法热温冷/频次）与“快乐8分区数”
        sel_window = int(self._window_cb.currentData() or 0) if hasattr(self, "_window_cb") else 0
        sel_zones = int(self._zones_cb.currentData() or KL8_ZONES) if hasattr(self, "_zones_cb") else KL8_ZONES

        freq, omit = self._freq_omit(sel_window)
        hot, warm, cold = self._hot_warm_cold(sel_window)
        dragons, phoenix = self._dragon_phoenix()
        head_nums = self._head_combo_stat()
        all_by_freq = sorted(range(1, main_max + 1), key=lambda x: -freq.get(x, 0))

        def ordered_unique(seq):
            out, seen = [], set()
            for x in seq:
                if 1 <= x <= main_max and x not in seen:
                    out.append(x); seen.add(x)
            return out

        # 策略排序后的“完整候选列表”（长度始终 = main_max）。
        # 旧逻辑用 hot[gi:] 这种切片，gi 一大就越界塌缩成 all_by_freq（每组/每次都一样），
        # 这正是“前区每次都相同、只有后区在变”的根因。改成对完整列表做环形窗口轮换，绝不塌缩。
        if mode == "龙头凤尾轮流":
            ranked = ordered_unique(list(dragons) + list(phoenix) + all_by_freq)
        elif mode == "号码头出组合统计":
            ranked = ordered_unique(list(head_nums) + all_by_freq)
        else:
            ranked = ordered_unique(list(hot) + list(warm) + list(cold) + all_by_freq)
        for x in all_by_freq:
            if x not in ranked:
                ranked.append(x)
        Lr = len(ranked)
        # 每次点击的随机抖动：保证“每次生成都不同”，而不只是后区不同。
        gen_jitter = random.randint(0, max(1, main_max - 1))

        def _fill_dan(dan):
            """补足/去重/排序，保证返回恰好 n_dan 个不重复且在范围内的号码。"""
            dan = ordered_unique(dan)
            i = 0
            while len(dan) < n_dan and i < Lr:
                if ranked[i] not in dan:
                    dan.append(ranked[i])
                i += 1
            c = 1
            while len(dan) < n_dan and c <= main_max:
                if c not in dan:
                    dan.append(c)
                c += 1
            return sorted(dan[:n_dan])

        def dan_for_group(gi):
            # 按胆数采用不同选胆策略；gi 已含轮流游标，再叠加 gen_jitter 保证每次点击不同。
            if n_dan == 1:
                # 1胆：严格按顺序轮换（随游标递进，01→最大号）
                return [gi % main_max + 1]

            # 快乐8 多胆：近期热度 + 分区均衡（按界面所选窗口/分区）
            if self.game_type == "快乐8":
                return self._kl8_zone_hot_dan(n_dan, gi, gen_jitter, sel_window or KL8_RECENT_WINDOW, sel_zones)

            if n_dan == 2:
                # 2胆：同号组合 —— 一个种子 + 与它历史同出最多的号
                if Lr == 0:
                    return _fill_dan([])
                seed = ranked[(gi * 2 + gen_jitter) % Lr]
                partners = [p for p in self._cooccur_with(seed) if p != seed]
                return _fill_dan([seed] + partners[:1])

            if n_dan == 3:
                # 3胆：1热 + 1温 + 1冷（各取一个，按组+抖动轮换）
                h = hot or all_by_freq
                w = warm or all_by_freq
                cd = cold or all_by_freq
                idx = gi + gen_jitter
                d = []
                if h:  d.append(h[idx % len(h)])
                if w:  d.append(w[idx % len(w)])
                if cd: d.append(cd[idx % len(cd)])
                return _fill_dan(d)

            if n_dan == 4:
                # 4胆：按当前玩法的号码池(ranked)做环形窗口轮换取4个
                if Lr == 0:
                    return _fill_dan([])
                off = (gi * 4 + gen_jitter) % Lr
                rot = ranked[off:] + ranked[:off]
                return _fill_dan(rot[:n_dan])

            # 5胆及以上：按得分(频次)取种子 + 历史同出号码组合
            score_ranked = all_by_freq or ranked
            if not score_ranked:
                return _fill_dan([])
            seed = score_ranked[(gi * max(1, n_dan) + gen_jitter) % len(score_ranked)]
            dan = ordered_unique([seed] + self._cooccur_with(seed) + score_ranked)
            return _fill_dan(dan[:n_dan])

        def tuo_for_dan(dan, gi):
            danset = set(dan)
            pool = ordered_unique([x for x in ranked if x not in danset])
            Lp = len(pool)
            if Lp:
                # 与胆码偏移解耦（*7+13），避免拖码窗口和胆码窗口同步移动
                off = (gi * max(1, n_tuo) + gen_jitter * 7 + 13) % Lp
                pool = pool[off:] + pool[:off]
            tuo = pool[:n_tuo]
            while len(tuo) < n_tuo:
                c = random.randint(1, main_max)
                if c not in danset and c not in tuo:
                    tuo.append(c)
            return sorted(tuo)

        tickets = []
        lines = [f"=== {self.game_type} 多胆轮流（{n_dan}胆{n_tuo}拖 · {mode}）==="]
        base = int(getattr(self, "_rotation_cursor", 0))
        for gi in range(n_groups):
            ri = base + gi          # 轮流游标：连续点击会继续往后轮换
            dan = dan_for_group(ri)
            tuo = tuo_for_dan(dan, ri)
            sub = self._gen_sub()
            ticket = {"dan": dan, "tuo": tuo, "sub": sub}
            tickets.append(ticket)
            is_single = len(dan) + len(tuo) == main_n
            main_pool = sorted(dan + tuo)
            sub_str = ("  +  " + " ".join(f"{x:02d}" for x in sub)) if sub else ""
            hist = self._history_compare_text(main_pool, sub)
            if is_single:
                main_str = " ".join(f"{x:02d}" for x in main_pool)
                lines.append(f"第{gi+1:02d}组 [单式] {main_str}{sub_str}  ｜{hist}")
            else:
                dan_str = " ".join(f"{x:02d}" for x in dan)
                tuo_str = " ".join(f"{x:02d}" for x in tuo)
                need = main_n - len(dan)
                bets = math_comb(len(tuo), need)
                lines.append(f"第{gi+1:02d}组 [胆:{dan_str}] [拖:{tuo_str}]{sub_str}  {bets}注 ｜{hist}")
        self._tickets = tickets
        self._rotation_cursor = base + n_groups
        self._render_tickets()

    def _gen_sub(self):
        """生成副区号码（双色球1蓝/大乐透2后/七乐彩1特），按历史频率优先。"""
        import random
        if not self.cfg["has_sub"] or self.cfg["sub_max"] <= 0:
            return []
        smax, sn = self.cfg["sub_max"], self.cfg["sub_n"]
        from collections import Counter
        c = Counter()
        for r in self.records:
            nums = parse_draw_numbers(str(r.get("开奖号码", "")))
            if self.game_type == "双色球" and len(nums) >= 7:
                c[nums[6]] += 1
            elif self.game_type == "大乐透" and len(nums) >= 7:
                c[nums[5]] += 1; c[nums[6]] += 1
        pool = sorted(range(1, smax+1), key=lambda x: -c.get(x, 0))
        top = pool[:max(sn+3, smax//2)] or list(range(1, smax+1))
        random.shuffle(top)
        return sorted(top[:sn])

    def _copy_numbers(self):
        if not self._tickets:
            QMessageBox.warning(self, "提示", "请先生成号码"); return

        # 套餐票复制必须保留“第一张、第二张……”分张标题。
        # 普通多胆仍保持原来的一行一注格式。
        if self._tickets and self._tickets[0].get("package"):
            zh_nums = "零一二三四五六七八九十"
            def _zh_no(n):
                try:
                    n = int(n)
                except Exception:
                    return str(n)
                if 0 < n <= 10:
                    return zh_nums[n]
                return f"{n:02d}"

            lines = []
            last_pack = None
            for t in self._tickets:
                pack_no = int(t.get("package_no", 1) or 1)
                if pack_no != last_pack:
                    if lines:
                        lines.append("")
                    lines.append(f"{str(t.get('package', '套餐票'))}第{_zh_no(pack_no)}张")
                    last_pack = pack_no
                lines.append(self._format_copy_line(t))
            text = "\n".join(lines)
        else:
            text = "\n".join(self._format_copy_line(t) for t in self._tickets)

        QApplication.clipboard().setText(text)
        QMessageBox.information(self, "复制成功", "号码已复制。套餐票已保留“金额套餐票第几张”分张标题；单式不显示胆/拖，非单式胆拖保留胆/拖。")

    def _bet_all(self):
        if not self._tickets:
            QMessageBox.warning(self, "提示", "请先生成号码"); return
        if self._is_positional_game:
            cnt = 0
            for t in self._tickets:
                nums = self._format_copy_line(t)
                bets_count = self._pos_ticket_units(t)
                try:
                    self.app.add_betting_record(self.game_type, "多胆轮流-位置型", nums, bets_count, bets_count * 2.0)
                    cnt += bets_count
                except Exception as e:
                    logger.error(f"位置型多胆轮流投注失败: {e}")
            QMessageBox.information(self, "完成", f"已投注 {cnt} 注到投注记录。")
            return
        cnt = 0
        main_n = 10 if self.game_type == "快乐8" else self.cfg["main_n"]
        for t in self._tickets:
            dan, tuo, sub = sorted(t.get("dan", [])), sorted(t.get("tuo", [])), sorted(t.get("sub", []))
            is_single = len(dan) + len(tuo) == main_n
            if is_single:
                nums = " ".join(f"{x:02d}" for x in sorted(dan + tuo))
                if sub:
                    nums += " + " + " ".join(f"{x:02d}" for x in sub)
                if t.get("package"):
                    bets_count = self._package_ticket_units(t)
                else:
                    bets_count = 1
                bet_type = f"套餐票-{t.get('package','单式')}" if t.get("package") else "多胆轮流-单式"
            else:
                nums = f"胆:{' '.join(f'{x:02d}' for x in dan)} 拖:{' '.join(f'{x:02d}' for x in tuo)}"
                if sub:
                    nums += " + " + " ".join(f"{x:02d}" for x in sub)
                bets_count = self._package_ticket_units(t) if t.get("package") else math_comb(len(tuo), main_n - len(dan))
                bet_type = f"套餐票-{t.get('package','胆拖')}" if t.get("package") else "多胆轮流-胆拖"
            price = self._package_price_per_unit() if t.get("package") else (3.0 if self.game_type == "大乐透" else 2.0)
            try:
                self.app.add_betting_record(self.game_type, bet_type, nums, bets_count, bets_count * price)
                cnt += bets_count
            except Exception as e:
                logger.error(f"多胆轮流投注失败: {e}")
        QMessageBox.information(self, "完成", f"已投注 {cnt} 注到投注记录。")


class PrizeCalcDialog(QDialog):
    """奖金计算器（参考"一定牛"款式）：按"选号个数 + 命中个数"测算共多少注、
    命中各奖级多少注、合计中奖金额。支持 快乐8 / 双色球 / 大乐透，各含【单复式】【胆拖】两种模式。
    浮动奖（一二等等）优先取当期真实单注金额，取不到时给参考封顶并标注。"""

    GAMES = ["快乐8", "双色球", "大乐透"]
    _CN = ["零", "一", "二", "三", "四", "五", "六", "七", "八", "九", "十"]

    def __init__(self, parent):
        super().__init__(parent)
        self.app = parent
        self.game = "双色球"
        self.mode = "单复式"
        self._inputs = {}       # key -> QComboBox
        self.setWindowTitle("🧮 奖金计算器")
        sc = QApplication.primaryScreen().availableGeometry()
        self.resize(min(560, int(sc.width() * 0.98)), min(900, int(sc.height() * 0.94)))
        self._build_ui()
        self._switch_game("双色球")

    # ======================= 数据 / 计算 =======================
    def _latest(self, game):
        recs = self.app.history_data.get(game, [])
        if not recs:
            return None
        return sorted(recs, key=lambda x: str(x.get("期号", "")), reverse=True)[0]

    def _get_pool_yi(self, game):
        rec = self._latest(game)
        if not rec:
            return 0.0
        raw = str(rec.get("奖池", "") or rec.get("totalmoney", "") or "")
        m = re.search(r"([\d.]+)\s*亿", raw)
        if m:
            try: return float(m.group(1))
            except: return 0.0
        digits = re.sub(r"[^\d.]", "", raw)
        try:
            return (float(digits) if digits else 0.0) / 1e8
        except:
            return 0.0

    def _real_float_prize(self, game, level):
        rec = self._latest(game)
        return _real_single_bonus(rec, level) if rec else None

    def _amount_for(self, game, level, pool_yi):
        """返回 (单注奖金, 是否浮动)。固定奖直接给值；浮动奖取真实/参考封顶。"""
        if game == "双色球":
            fixed = {"三等奖": 3000, "四等奖": 200, "五等奖": 10, "六等奖": 5, "福运奖": 5}
            if level in fixed:
                return fixed[level], False
            real = self._real_float_prize(game, level)
            if real:
                return real, True
            return (10000000 if (level == "一等奖" and pool_yi >= 1) else 5000000), True
        if game == "大乐透":
            hi = pool_yi >= 8
            # 固定奖(三~七等/旧三~九等)金额由官方规则按奖池确定，直接给值。
            # 不能用单期接口里的“单注”值——它可能是追加/异常值（例如把六等奖显示成9元、
            # 七等奖显示成7元），导致固定奖金额算错。浮动奖(一二等)才取真实单注。
            fixed = {"三等奖": (6666 if hi else 5000), "四等奖": (380 if hi else 300),
                     "五等奖": (200 if hi else 150), "六等奖": (18 if hi else 15),
                     "七等奖": (7 if hi else 5), "八等奖": 15, "九等奖": 5}
            if level in fixed:
                return fixed[level], False
            real = self._real_float_prize(game, level)
            if real is not None:
                return real, True
            return (10000000 if level == "一等奖" else 500000), True
        return 0, False

    def _bet_count(self):
        """根据当前下拉框计算投注总注数。"""
        g, m = self.game, self.mode
        v = lambda k, d=0: self._inputs[k].currentData() if k in self._inputs else d
        try:
            if g == "快乐8":
                k = v("play")
                if m == "单复式":
                    N = v("pick")
                    return math.comb(N, k) if N >= k else 0
                else:
                    D, T = v("dan"), v("tuo")
                    need = k - D
                    return math.comb(T, need) if (need >= 0 and T >= need) else 0
            if g == "双色球":
                B = v("blue")
                if m == "单复式":
                    R = v("red")
                    return (math.comb(R, 6) if R >= 6 else 0) * max(1, B)
                else:
                    D, T = v("dan"), v("tuo"); need = 6 - D
                    return (math.comb(T, need) if (need >= 0 and T >= need) else 0) * max(1, B)
            if g == "大乐透":
                K = v("back")
                kb = math.comb(K, 2) if K >= 2 else 0
                if m == "单复式":
                    F = v("front")
                    return (math.comb(F, 5) if F >= 5 else 0) * kb
                else:
                    D, T = v("dan"), v("tuo"); need = 5 - D
                    return (math.comb(T, need) if (need >= 0 and T >= need) else 0) * kb
        except Exception:
            return 0
        return 0

    def _breakdown(self):
        """按命中个数计算各奖级中奖注数。返回 [(level, count, single_amount, floating)]。"""
        g, m = self.game, self.mode
        C = math.comb
        v = lambda k, d=0: self._inputs[k].currentData() if k in self._inputs else d
        pool = self._get_pool_yi(g)
        rec = self._latest(g)
        out = {}   # level -> [count, amount, floating]

        def add(level, cnt):
            if cnt <= 0 or not level or level == "未中奖":
                return
            amt, fl = self._amount_for(g, level, pool)
            r = out.setdefault(level, [0, amt, fl])
            r[0] += cnt

        def comb_dist(hit, pool_n, pick):
            """从 pool_n 个里(其中 hit 个为中奖号)选 pick 个，返回 {命中数: 组合数}。"""
            d = {}
            for j in range(0, pick + 1):
                a, b = hit, pool_n - hit
                if j <= a and (pick - j) <= b and (pick - j) >= 0:
                    d[j] = C(a, j) * C(b, pick - j)
            return d

        if g == "快乐8":
            k = v("play")
            if m == "单复式":
                N, M = v("pick"), v("hit")
                dist = comb_dist(min(M, N, 20), N, k)   # 选 k 个里命中 j 个（实际仅20个开奖号）
            else:
                D, T, md, mt = v("dan"), v("tuo"), v("hitdan"), v("hittuo")
                need = k - D
                tdist = comb_dist(min(mt, T, 20), T, need)
                dist = {min(md, D) + j: c for j, c in tdist.items()}
            tbl = KL8_PRIZE_TABLE.get(k, {})
            for hits, cnt in dist.items():
                if hits in tbl:
                    nm = f"选{self._CN[k]}中{hits}"
                    amt = tbl[hits]
                    r = out.setdefault(nm, [0, amt, (k == 10 and hits == 10)])
                    r[0] += cnt
            return sorted(out.items(), key=lambda kv: -kv[1][1])

        if g == "双色球":
            B = v("blue")
            if m == "单复式":
                R, mr, mb = v("red"), v("hitred"), v("hitblue")
                rdist = comb_dist(min(mr, R, 6), R, 6)
            else:
                D, T, md, mt, mb = v("dan"), v("tuo"), v("hitdan"), v("hittuo"), v("hitblue")
                need = 6 - D
                tdist = comb_dist(min(mt, T, need), T, need)
                rdist = {min(md, D) + j: c for j, c in tdist.items()}
            mb = min(mb, B, 1)
            for j, cnt in rdist.items():
                for bh, bc in ((1, mb), (0, max(0, B - mb))):
                    if bc <= 0:
                        continue
                    lvl = _ssq_prize_level(j, bh, rec)
                    add(lvl, cnt * bc)
            return sorted(out.items(), key=lambda kv: -kv[1][1])

        if g == "大乐透":
            K = v("back")
            date = (rec.get("开奖日期", "") if rec else "")
            if m == "单复式":
                F, mf, mk = v("front"), v("hitfront"), v("hitback")
                fdist = comb_dist(min(mf, F, 5), F, 5)
            else:
                D, T, md, mt, mk = v("dan"), v("tuo"), v("hitdan"), v("hittuo"), v("hitback")
                need = 5 - D
                tdist = comb_dist(min(mt, T, need), T, need)
                fdist = {min(md, D) + j: c for j, c in tdist.items()}
            bdist = comb_dist(min(mk, K, 2), K, 2)
            for j, fc in fdist.items():
                for b, bc in bdist.items():
                    lvl = _dlt_prize_level(j, b, date)
                    add(lvl, fc * bc)
            return sorted(out.items(), key=lambda kv: -kv[1][1])
        return []

    # ======================= UI =======================
    def _pill(self, text, on):
        b = QPushButton(text)
        b.setCheckable(True); b.setChecked(on)
        b.setCursor(Qt.PointingHandCursor)
        return b

    def _restyle_tabs(self):
        for g, b in self._game_btns.items():
            on = (g == self.game)
            b.setChecked(on)
            b.setStyleSheet(
                "QPushButton{border:none;border-radius:18px;padding:8px 18px;font-size:14px;font-weight:bold;%s}"
                % ("background:#E8541E;color:white;" if on else "background:#F2F2F2;color:#333;"))
        for mname, b in self._mode_btns.items():
            on = (mname == self.mode)
            b.setChecked(on)
            b.setStyleSheet(
                "QPushButton{border:none;padding:4px 6px;font-size:15px;%s}"
                % ("color:#E8541E;font-weight:bold;border-bottom:3px solid #E8541E;" if on
                   else "color:#666;font-weight:normal;"))

    def _build_ui(self):
        root = QVBoxLayout(self); root.setContentsMargins(0, 0, 0, 0); root.setSpacing(0)

        # 顶部标题
        self._title = QLabel("奖金计算器")
        self._title.setAlignment(Qt.AlignCenter)
        self._title.setStyleSheet("background:#E8541E;color:white;font-size:16px;font-weight:bold;padding:12px;")
        root.addWidget(self._title)

        body = QWidget(); root.addWidget(body, 1)
        lay = QVBoxLayout(body); lay.setContentsMargins(14, 12, 14, 12); lay.setSpacing(10)

        # 玩法标签 + 期号
        top = QHBoxLayout()
        self._game_btns = {}
        for g in self.GAMES:
            b = self._pill(g, g == self.game)
            b.clicked.connect(lambda _=False, gg=g: self._switch_game(gg))
            self._game_btns[g] = b
            top.addWidget(b)
        top.addStretch(1)
        self._issue_cb = QComboBox()
        self._issue_cb.setMinimumWidth(130)
        self._issue_cb.currentIndexChanged.connect(self._refresh_draw)
        top.addWidget(self._issue_cb)
        lay.addLayout(top)

        # 开奖号码 + 奖池
        self._draw_lbl = QLabel("")
        self._draw_lbl.setWordWrap(True)
        self._draw_lbl.setTextFormat(Qt.RichText)
        self._draw_lbl.setStyleSheet("font-size:13px;")
        lay.addWidget(self._draw_lbl)

        # 模式：单复式 / 胆拖
        mrow = QHBoxLayout(); mrow.setSpacing(20)
        self._mode_btns = {}
        for mname in ("单复式", "胆拖"):
            b = self._pill(mname, mname == self.mode)
            b.clicked.connect(lambda _=False, mm=mname: self._switch_mode(mm))
            self._mode_btns[mname] = b
            mrow.addWidget(b)
        mrow.addStretch(1)
        lay.addLayout(mrow)

        # 动态输入区
        self._inp_host = QWidget()
        self._inp_grid = QGridLayout(self._inp_host)
        self._inp_grid.setHorizontalSpacing(12); self._inp_grid.setVerticalSpacing(10)
        lay.addWidget(self._inp_host)

        # 共X注Y元
        self._total_lbl = QLabel("")
        self._total_lbl.setStyleSheet("font-size:16px;font-weight:bold;color:#333;")
        lay.addWidget(self._total_lbl)

        # 开始计算
        calc_btn = QPushButton("开始计算")
        calc_btn.setCursor(Qt.PointingHandCursor)
        calc_btn.setStyleSheet("QPushButton{background:#E8541E;color:white;font-size:16px;font-weight:bold;"
                               "border:none;border-radius:8px;padding:13px;}QPushButton:pressed{background:#cc4615;}")
        calc_btn.clicked.connect(self._calc)
        lay.addWidget(calc_btn)

        # 结果
        self._out = QTextEdit(); self._out.setReadOnly(True); self._out.setMaximumHeight(150)
        self._out.setStyleSheet("border:1px solid #eee;border-radius:6px;")
        lay.addWidget(self._out)

        # 奖级规则表
        self._table = QTableWidget()
        self._table.setEditTriggers(QTableWidget.NoEditTriggers)
        self._table.setSelectionMode(QTableWidget.NoSelection)
        self._table.verticalHeader().setVisible(False)
        self._table.setStyleSheet("QTableWidget{font-size:12px;}QHeaderView::section{background:#FBE9E2;"
                                  "color:#C0392B;font-weight:bold;padding:6px;border:none;}")
        lay.addWidget(self._table, 1)

    def _switch_game(self, game):
        self.game = game
        self._title.setText(f"{game}奖金计算器")
        # 期号下拉
        self._issue_cb.blockSignals(True)
        self._issue_cb.clear()
        recs = sorted(self.app.history_data.get(game, []), key=lambda x: str(x.get("期号", "")), reverse=True)[:60]
        for r in recs:
            self._issue_cb.addItem(f"第{r.get('期号','')}期", r)
        self._issue_cb.blockSignals(False)
        self._restyle_tabs()
        self._refresh_draw()
        self._rebuild_inputs()
        self._fill_table()

    def _switch_mode(self, mode):
        self.mode = mode
        self._restyle_tabs()
        self._rebuild_inputs()

    def _refresh_draw(self):
        rec = self._issue_cb.currentData() or self._latest(self.game)
        if not rec:
            self._draw_lbl.setText("⚠ 暂无开奖数据，请先在主界面更新数据")
            return
        nums = parse_draw_numbers(rec.get("开奖号码", ""))
        pool = self._get_pool_yi(self.game)
        balls = []
        if self.game == "双色球":
            reds, blue = nums[:6], nums[6:7]
            balls = [self._ball(n, "#E8541E") for n in reds] + [self._ball(n, "#2E7DEF") for n in blue]
        elif self.game == "大乐透":
            balls = [self._ball(n, "#E8541E") for n in nums[:5]] + [self._ball(n, "#2E7DEF") for n in nums[5:7]]
        else:
            balls = [self._ball(n, "#E8541E") for n in nums[:20]]
        pool_txt = f"　<span style='color:#C0392B'>奖池:{pool:.2f}亿</span>" if pool > 0 else ""
        self._draw_lbl.setText(
            f"<b>第{rec.get('期号','')}期开奖号码：</b>{pool_txt}<br>" + " ".join(balls))

    def _ball(self, n, color):
        return (f"<span style='background:{color};color:white;border-radius:9px;"
                f"padding:2px 6px;font-weight:bold;'>{int(n):02d}</span>")

    def _mk_combo(self, key, items, default=None):
        cb = QComboBox()
        for label, data in items:
            cb.addItem(label, data)
        if default is not None:
            idx = cb.findData(default)
            if idx >= 0: cb.setCurrentIndex(idx)
        cb.currentIndexChanged.connect(self._update_total)
        self._inputs[key] = cb
        return cb

    def _rng(self, lo, hi, unit="个"):
        return [(f"{i}{unit}", i) for i in range(lo, hi + 1)]

    def _rebuild_inputs(self):
        # 清空旧控件
        self._inputs = {}
        while self._inp_grid.count():
            it = self._inp_grid.takeAt(0)
            w = it.widget()
            if w: w.deleteLater()

        def cell(r, c, label, combo):
            box = QVBoxLayout()
            lb = QLabel(label); lb.setStyleSheet("color:#888;font-size:12px;")
            combo.setStyleSheet("QComboBox{border:1px solid #ddd;border-radius:6px;padding:8px;font-size:14px;}")
            box.addWidget(lb); box.addWidget(combo)
            host = QWidget(); host.setLayout(box)
            self._inp_grid.addWidget(host, r, c)

        g, m = self.game, self.mode
        if g == "快乐8":
            plays = [(f"选{self._CN[i]}", i) for i in range(1, 11)]
            if m == "单复式":
                cell(0, 0, "选择玩法：", self._mk_combo("play", plays, 10))
                cell(0, 1, "选号个数：", self._mk_combo("pick", self._rng(1, 30), 10))
                cell(0, 2, "命中个数：", self._mk_combo("hit", self._rng(0, 20), 0))
            else:
                cell(0, 0, "选择玩法：", self._mk_combo("play", plays, 10))
                cell(0, 1, "选号胆码：", self._mk_combo("dan", self._rng(1, 9), 1))
                cell(0, 2, "命中胆码：", self._mk_combo("hitdan", self._rng(0, 9), 0))
                cell(1, 0, "选号拖码：", self._mk_combo("tuo", self._rng(1, 30), 10))
                cell(1, 1, "命中拖码：", self._mk_combo("hittuo", self._rng(0, 20), 0))
        elif g == "双色球":
            if m == "单复式":
                cell(0, 0, "选择红球：", self._mk_combo("red", self._rng(6, 33), 7))
                cell(0, 1, "选择蓝球：", self._mk_combo("blue", self._rng(1, 16), 1))
                cell(1, 0, "命中红球：", self._mk_combo("hitred", self._rng(0, 6), 0))
                cell(1, 1, "命中蓝球：", self._mk_combo("hitblue", self._rng(0, 1), 0))
            else:
                cell(0, 0, "选择红胆：", self._mk_combo("dan", self._rng(1, 5), 1))
                cell(0, 1, "选择红拖：", self._mk_combo("tuo", self._rng(1, 32), 12))
                cell(0, 2, "蓝球个数：", self._mk_combo("blue", self._rng(1, 16), 1))
                cell(1, 0, "命中红胆：", self._mk_combo("hitdan", self._rng(0, 5), 0))
                cell(1, 1, "命中红拖：", self._mk_combo("hittuo", self._rng(0, 6), 0))
                cell(1, 2, "命中蓝球：", self._mk_combo("hitblue", self._rng(0, 1), 0))
        elif g == "大乐透":
            if m == "单复式":
                cell(0, 0, "前区个数：", self._mk_combo("front", self._rng(5, 35), 6))
                cell(0, 1, "后区个数：", self._mk_combo("back", self._rng(2, 12), 2))
                cell(1, 0, "命中前区：", self._mk_combo("hitfront", self._rng(0, 5), 0))
                cell(1, 1, "命中后区：", self._mk_combo("hitback", self._rng(0, 2), 0))
            else:
                cell(0, 0, "前区胆码：", self._mk_combo("dan", self._rng(1, 4), 2))
                cell(0, 1, "前区拖码：", self._mk_combo("tuo", self._rng(1, 32), 5))
                cell(0, 2, "后区个数：", self._mk_combo("back", self._rng(2, 12), 2))
                cell(1, 0, "命中前胆：", self._mk_combo("hitdan", self._rng(0, 4), 0))
                cell(1, 1, "命中前拖：", self._mk_combo("hittuo", self._rng(0, 5), 0))
                cell(1, 2, "命中后区：", self._mk_combo("hitback", self._rng(0, 2), 0))
        # 快乐8：奖级规则表随"选择玩法"动态切换
        if g == "快乐8" and "play" in self._inputs:
            self._inputs["play"].currentIndexChanged.connect(self._fill_table)
        self._update_total()
        self._fill_table()

    def _update_total(self):
        bets = self._bet_count()
        price = 2.0  # 单注基本投注价（大乐透基本投注亦为2元）
        self._total_lbl.setText(f"共 {bets} 注  {int(bets*price)} 元")

    def _fill_table(self):
        g = self.game
        if g == "快乐8":
            k = 10
            if "play" in self._inputs:
                try:
                    k = int(self._inputs["play"].currentData() or 10)
                except Exception:
                    k = 10
            cn = self._CN[k] if 0 < k < len(self._CN) else str(k)
            cols = ["中奖规则", "单注奖金"]
            rows = [(f"选{cn}中{h}", f"{a:,}") for h, a in KL8_PRIZE_TABLE.get(k, {}).items()]
        elif g == "双色球":
            cols = ["奖级", "中奖条件", "单注奖金"]
            rows = [("一等奖", "6红+1蓝", "浮动·封顶500~1000万"), ("二等奖", "6红", "浮动·封顶500万"),
                    ("三等奖", "5红+1蓝", "3,000"), ("四等奖", "5红 / 4红+1蓝", "200"),
                    ("五等奖", "4红 / 3红+1蓝", "10"), ("六等奖", "中蓝(2/1/0红+1蓝)", "5"),
                    ("福运奖", "3红(奖池≥15亿开)", "5")]
        else:
            cols = ["奖级", "中奖条件", "单注奖金"]
            rows = [("一等奖", "5前+2后", "浮动·最高1000万"), ("二等奖", "5前+1后", "浮动·封顶500万"),
                    ("三等奖", "5前 / 4前+2后", "5000/6666"), ("四等奖", "4前+1后", "300/380"),
                    ("五等奖", "4前 / 3前+2后", "150/200"), ("六等奖", "3前+1后 / 2前+2后", "15/18"),
                    ("七等奖", "3前 / 2前+1后 / 1前+2后 / 2后", "5/7")]
        self._table.clear()
        self._table.setColumnCount(len(cols))
        self._table.setHorizontalHeaderLabels(cols)
        self._table.setRowCount(len(rows))
        for r, row in enumerate(rows):
            for c, val in enumerate(row):
                item = QTableWidgetItem(str(val))
                if c == len(cols) - 1:
                    item.setForeground(QColor("#C0392B"))
                self._table.setItem(r, c, item)
        self._table.resizeColumnsToContents()
        try:
            self._table.horizontalHeader().setStretchLastSection(True)
        except Exception:
            pass

    def _calc(self):
        rec = self._issue_cb.currentData() or self._latest(self.game)
        bets = self._bet_count()
        if bets <= 0:
            self._out.setHtml("<p style='color:#C0392B'>注数为 0，请检查选号/拖码个数是否足够组成一注。</p>")
            return
        try:
            rows = self._breakdown()
        except Exception as e:
            self._out.setHtml(f"<p style='color:#C0392B'>计算出错：{e}</p>")
            return
        cost = int(bets * 2.0)
        html = [f"<b>共投注 {bets} 注，{cost} 元</b>"]
        if not rows:
            html.append("<p style='color:#888'>按当前命中个数：<b>未中奖</b></p>")
        else:
            total_fixed = 0; has_float = False
            html.append("<table cellspacing='0' cellpadding='3'>")
            html.append("<tr style='color:#888'><td>奖级</td><td>中奖注数</td><td>单注奖金</td><td>小计</td></tr>")
            for lvl, (cnt, amt, fl) in rows:
                if fl:
                    has_float = True
                    sub = f"{cnt}×浮动"
                    amt_txt = f"¥{amt:,}*"
                else:
                    total_fixed += cnt * amt
                    sub = f"¥{cnt*amt:,}"
                    amt_txt = f"¥{amt:,}"
                html.append(f"<tr><td><b>{lvl}</b></td><td>{cnt} 注</td>"
                            f"<td>{amt_txt}</td><td style='color:#C0392B'>{sub}</td></tr>")
            html.append("</table>")
            html.append(f"<b style='color:#27AE60;font-size:14px'>固定奖合计：¥{total_fixed:,}</b>")
            if has_float:
                html.append("<br><small style='color:#888'>* 浮动奖（一二等/选十中十）以当期开奖公告实际金额为准；"
                            "上方按当期真实或参考封顶值估算。</small>")
        self._out.setHtml("".join(html))


class DragonPhoenixPredictDialog(QDialog):
    """
    龙头凤尾预测 + 集合覆盖分析系统：
      ① 龙头（每期最小号）历史统计 → 频率/遗漏/热冷 → 预测下期龙头候选
      ② 凤尾（每期最大号）历史统计 → 频率/遗漏/热冷 → 预测下期凤尾候选
      ③ 覆盖结构：对多组预测集合做 交集/并集/差集/补集 运算
      ④ 最终生成投注推荐号码组合
    支持全部玩法：双色球/大乐透/快乐8/七乐彩/3D/七星彩/排列三/排列五
    """

    GAME_CFG = {
        "双色球":  {"main_max": 33, "main_n": 6,  "sub_max": 16, "sub_n": 1,  "has_sub": True,  "is_pos": False},
        "大乐透":  {"main_max": 35, "main_n": 5,  "sub_max": 12, "sub_n": 2,  "has_sub": True,  "is_pos": False},
        "快乐8":   {"main_max": 80, "main_n": 10, "sub_max": 0,  "sub_n": 0,  "has_sub": False, "is_pos": False},
        "七乐彩":  {"main_max": 30, "main_n": 7,  "sub_max": 0,  "sub_n": 0,  "has_sub": False, "is_pos": False},
        "3D":      {"main_max": 9,  "main_n": 3,  "sub_max": 0,  "sub_n": 0,  "has_sub": False, "is_pos": True},
        "七星彩":  {"main_max": 9,  "main_n": 7,  "sub_max": 0,  "sub_n": 0,  "has_sub": False, "is_pos": True},
        "排列三":  {"main_max": 9,  "main_n": 3,  "sub_max": 0,  "sub_n": 0,  "has_sub": False, "is_pos": True},
        "排列五":  {"main_max": 9,  "main_n": 5,  "sub_max": 0,  "sub_n": 0,  "has_sub": False, "is_pos": True},
    }

    def __init__(self, parent, game_type: str):
        super().__init__(parent)
        self.parent_app   = parent
        self.game_type    = game_type
        self.cfg          = self.GAME_CFG.get(game_type, self.GAME_CFG["双色球"])
        self.records      = sorted(
            parent.history_data.get(game_type, []),
            key=lambda x: str(x.get("期号", "")), reverse=True
        )
        self.pred_sets    = {}   # 各算法预测集合 {name: set}
        self.cover_result = []   # 最终覆盖结果号码列表
        self._build_ui()

    # ────────────────────────────────── UI ──────────────────────────────────

    def _build_ui(self):
        self.setWindowTitle(f"🐉 {self.game_type} 龙头凤尾预测 + 集合覆盖分析")
        self.setMinimumSize(820, 750)
        root = QVBoxLayout(self)

        tabs = QTabWidget()
        root.addWidget(tabs)

        tabs.addTab(self._tab_dragon_phoenix(), "🐉 龙头凤尾统计")
        tabs.addTab(self._tab_set_coverage(),   "🔗 集合覆盖分析")
        tabs.addTab(self._tab_result(),          "🎯 投注推荐")

        close_btn = QPushButton("关闭")
        close_btn.clicked.connect(self.accept)
        root.addWidget(close_btn)

    # ───────────── Tab1: 龙头凤尾统计 ─────────────

    def _tab_dragon_phoenix(self) -> QWidget:
        w = QWidget(); lay = QVBoxLayout(w)

        if not self.records:
            lay.addWidget(QLabel("⚠ 暂无历史数据，请先获取开奖数据"))
            return w

        n_records = min(len(self.records), 200)
        cfg = self.cfg

        # ── 数据提取 ──
        dragons = []   # 每期最小主区号
        phoenixes = [] # 每期最大主区号
        for rec in self.records[:n_records]:
            nums = parse_draw_numbers(rec.get("开奖号码", ""))
            main = self._extract_main(nums)
            if main:
                dragons.append(min(main))
                phoenixes.append(max(main))

        if not dragons:
            lay.addWidget(QLabel("⚠ 无法解析历史号码"))
            return w

        # 存储供后续使用
        self._dragons   = dragons
        self._phoenixes = phoenixes

        # 统计
        from collections import Counter
        d_freq  = Counter(dragons)
        p_freq  = Counter(phoenixes)
        max_num = cfg["main_max"]

        # ── 龙头统计组 ──
        scroll = QScrollArea(); scroll.setWidgetResizable(True)
        inner  = QWidget(); inner_lay = QVBoxLayout(inner)
        scroll.setWidget(inner)
        lay.addWidget(scroll)

        for title, freq_cnt, pool_range in [
            ("🐉 龙头（每期最小号）统计", d_freq, range(1, max_num + 1)),
            ("🦚 凤尾（每期最大号）统计", p_freq, range(1, max_num + 1)),
        ]:
            grp  = QGroupBox(f"{title}（近{n_records}期）")
            glay = QVBoxLayout(grp)
            total = sum(freq_cnt.values()) or 1

            # 找热/冷
            sorted_nums = sorted(pool_range, key=lambda x: -freq_cnt.get(x, 0))
            hot  = set(sorted_nums[:5])
            cold = set(sorted_nums[-5:])

            tbl = QTableWidget()
            tbl.setColumnCount(5)
            tbl.setHorizontalHeaderLabels(["号码", "出现次数", "占比%", "当前遗漏", "热冷"])
            tbl.horizontalHeader().setSectionResizeMode(QHeaderView.Stretch)
            tbl.setEditTriggers(QAbstractItemView.NoEditTriggers)
            tbl.setAlternatingRowColors(True)
            tbl.setMaximumHeight(260)

            # 计算遗漏
            omit_map = {}
            for n in pool_range:
                m = 0
                for val in (dragons if "龙头" in title else phoenixes):
                    if val == n:
                        break
                    m += 1
                omit_map[n] = m

            nums_show = [x for x in pool_range if freq_cnt.get(x, 0) > 0 or omit_map.get(x, 0) < 10]
            tbl.setRowCount(len(nums_show))
            for row, n in enumerate(sorted(nums_show)):
                cnt  = freq_cnt.get(n, 0)
                pct  = cnt / total * 100
                omit = omit_map.get(n, 0)
                is_hot  = n in hot
                is_cold = n in cold
                hot_str = "🔥热" if is_hot else ("❄冷" if is_cold else "—")
                for col, val in enumerate([str(n), str(cnt), f"{pct:.1f}%", str(omit), hot_str]):
                    item = QTableWidgetItem(val)
                    if is_hot:
                        item.setForeground(QColor("#C62828"))
                    elif is_cold:
                        item.setForeground(QColor("#1565C0"))
                    tbl.setItem(row, col, item)
            glay.addWidget(tbl)

            # 推荐标签
            top5   = sorted(hot, key=lambda x: -freq_cnt.get(x, 0))[:5]
            omit5  = sorted(pool_range, key=lambda x: -omit_map.get(x, 0))[:5]
            rec_lbl = QLabel(
                f"<b>热号推荐：</b> {', '.join(map(str, top5))}　　"
                f"<b>高遗漏推荐：</b> {', '.join(map(str, omit5))}"
            )
            rec_lbl.setStyleSheet("padding:4px;background:#FFF9C4;border-radius:4px;")
            glay.addWidget(rec_lbl)
            inner_lay.addWidget(grp)

        # ── 近20期龙头凤尾走势表 ──
        trend_grp  = QGroupBox("📈 近20期龙头/凤尾走势")
        trend_lay  = QVBoxLayout(trend_grp)
        trend_tbl  = QTableWidget(min(20, len(dragons)), 4)
        trend_tbl.setHorizontalHeaderLabels(["期号", "龙头(最小)", "凤尾(最大)", "跨度"])
        trend_tbl.horizontalHeader().setSectionResizeMode(QHeaderView.Stretch)
        trend_tbl.setEditTriggers(QAbstractItemView.NoEditTriggers)
        for row in range(min(20, len(dragons))):
            issue = str(self.records[row].get("期号", ""))
            d_val = dragons[row]
            p_val = phoenixes[row]
            span  = p_val - d_val
            for col, val in enumerate([issue, str(d_val), str(p_val), str(span)]):
                item = QTableWidgetItem(val)
                if col == 1:
                    item.setForeground(QColor("#E74C3C"))
                elif col == 2:
                    item.setForeground(QColor("#27AE60"))
                trend_tbl.setItem(row, col, item)
        trend_lay.addWidget(trend_tbl)
        inner_lay.addWidget(trend_grp)

        # ── 预测下期按钮 ──
        pred_btn = QPushButton("🔮 预测下期龙头凤尾（生成候选集合）")
        pred_btn.setStyleSheet("background:#E74C3C;color:white;font-weight:bold;padding:7px;font-size:13px;")
        pred_btn.clicked.connect(self._predict_dragon_phoenix)
        lay.addWidget(pred_btn)

        # 用多算法模型数据生成号码，并入候选集合
        model_btn = QPushButton("🤖 用模型数据生成号码（并入候选集合）")
        model_btn.setStyleSheet("background:#8E44AD;color:white;font-weight:bold;padding:7px;font-size:13px;")
        model_btn.clicked.connect(self._gen_from_model)
        lay.addWidget(model_btn)

        self._dp_result_lbl = QLabel("← 点击上方按钮生成预测")
        self._dp_result_lbl.setStyleSheet("padding:6px;background:#EBF5FB;border-radius:4px;")
        self._dp_result_lbl.setWordWrap(True)
        lay.addWidget(self._dp_result_lbl)

        return w

    def _gen_from_model(self):
        """调用多算法模型，基于本玩法历史数据生成号码，并作为新的候选集合并入 pred_sets。"""
        if not self.records:
            QMessageBox.warning(self, "提示", "无历史数据，请先在首页【🔁 全量更新到最新】"); return
        try:
            ref = build_prediction_from_history(self.game_type, self.records, n_preds=6)
        except Exception as e:
            QMessageBox.warning(self, "出错", f"模型生成失败：\n{e}"); return
        multi = ref.get("multi_predictions", []) if ref else []
        if not multi:
            QMessageBox.warning(self, "提示", "模型未生成有效号码（历史数据可能过少）"); return
        max_num = self.cfg["main_max"]
        if not hasattr(self, "pred_sets") or self.pred_sets is None:
            self.pred_sets = {}
        added_lines = ["<b>🤖 模型生成候选集合：</b>"]
        for idx, pred in enumerate(multi, 1):
            nums = pred.get("main") or pred.get("nums") or pred.get("numbers") or []
            nums = [int(n) for n in nums if isinstance(n, (int,)) or (str(n).isdigit())]
            nums = sorted({n for n in nums if 1 <= n <= max_num})
            if not nums:
                continue
            algo = pred.get("algo", f"模型{idx}")
            self.pred_sets[f"模型_{algo}"] = set(nums)
            added_lines.append(f"  {algo}: {nums}")
        if len(added_lines) == 1:
            QMessageBox.warning(self, "提示", "模型号码超出范围，未并入"); return
        prev = self._dp_result_lbl.text() if hasattr(self, "_dp_result_lbl") else ""
        self._dp_result_lbl.setText((prev + "<br>" if prev and "点击" not in prev else "") + "<br>".join(added_lines))
        QMessageBox.information(self, "完成",
            f"已生成 {len(added_lines)-1} 组模型候选集合并并入。\n"
            "请到「集合覆盖分析」标签做交并集运算。")

    def _predict_dragon_phoenix(self):
        """生成下期龙头凤尾预测候选集合，同时写入 pred_sets"""
        if not hasattr(self, "_dragons") or not self._dragons:
            QMessageBox.warning(self, "提示", "无历史数据")
            return
        from collections import Counter
        dragons   = self._dragons
        phoenixes = self._phoenixes
        max_num   = self.cfg["main_max"]

        d_freq = Counter(dragons)
        p_freq = Counter(phoenixes)

        # 遗漏
        d_omit = {}; p_omit = {}
        for n in range(1, max_num + 1):
            m = 0
            for v in dragons:
                if v == n: break
                m += 1
            d_omit[n] = m
        for n in range(1, max_num + 1):
            m = 0
            for v in phoenixes:
                if v == n: break
                m += 1
            p_omit[n] = m

        # 热号集合
        hot_d  = set(sorted(range(1, max_num+1), key=lambda x: -d_freq.get(x,0))[:5])
        hot_p  = set(sorted(range(1, max_num+1), key=lambda x: -p_freq.get(x,0))[:5])
        # 遗漏集合
        omit_d = set(sorted(range(1, max_num+1), key=lambda x: -d_omit.get(x,0))[:5])
        omit_p = set(sorted(range(1, max_num+1), key=lambda x: -p_omit.get(x,0))[:5])
        # 趋势（近5期出现过的龙头/凤尾）
        trend_d = set(dragons[:5])
        trend_p = set(phoenixes[:5])
        # 均值±1区间
        import statistics
        d_mean = round(statistics.mean(dragons[:30])) if dragons else (max_num // 2)
        p_mean = round(statistics.mean(phoenixes[:30])) if phoenixes else (max_num // 2)
        mean_d = {max(1, d_mean-2), max(1, d_mean-1), d_mean, min(max_num, d_mean+1), min(max_num, d_mean+2)}
        mean_p = {max(1, p_mean-2), max(1, p_mean-1), p_mean, min(max_num, p_mean+1), min(max_num, p_mean+2)}

        self.pred_sets = {
            "龙头_热号":   hot_d,
            "龙头_遗漏":   omit_d,
            "龙头_趋势":   trend_d,
            "龙头_均值区": mean_d,
            "凤尾_热号":   hot_p,
            "凤尾_遗漏":   omit_p,
            "凤尾_趋势":   trend_p,
            "凤尾_均值区": mean_p,
        }

        lines = ["<b>龙头候选集合：</b>"]
        lines.append(f"  🔥热号: {sorted(hot_d)}")
        lines.append(f"  ⏳遗漏: {sorted(omit_d)}")
        lines.append(f"  📈趋势: {sorted(trend_d)}")
        lines.append(f"  📊均值区: {sorted(mean_d)}")
        lines.append("<b>凤尾候选集合：</b>")
        lines.append(f"  🔥热号: {sorted(hot_p)}")
        lines.append(f"  ⏳遗漏: {sorted(omit_p)}")
        lines.append(f"  📈趋势: {sorted(trend_p)}")
        lines.append(f"  📊均值区: {sorted(mean_p)}")
        self._dp_result_lbl.setText("<br>".join(lines))
        QMessageBox.information(self, "完成", "预测集合已生成，请切换到「集合覆盖分析」标签进行运算！")

    # ───────────── Tab2: 集合覆盖分析 ─────────────

    def _tab_set_coverage(self) -> QWidget:
        w = QWidget(); lay = QVBoxLayout(w)

        # ── 说明 ──
        info = QLabel(
            "<b>集合覆盖分析：</b> 对多组预测号码池进行集合运算，找出最优覆盖推荐号码。<br>"
            "• <b>交集</b>：多个集合都选中的号码（高置信度）<br>"
            "• <b>并集</b>：任意集合选中的号码（广覆盖）<br>"
            "• <b>差集 A-B</b>：A有而B没有的号码（独特预测）<br>"
            "• <b>补集</b>：全域中未被选中的号码（黑马策略）"
        )
        info.setStyleSheet("padding:6px;background:#EBF5FB;border-radius:4px;font-size:12px;")
        info.setWordWrap(True)
        lay.addWidget(info)

        # ── 多算法集合生成 ──
        gen_grp = QGroupBox("① 生成各算法预测集合")
        gen_lay = QVBoxLayout(gen_grp)

        top_row = QHBoxLayout()
        top_row.addWidget(QLabel("近期数据期数:"))
        self._cover_n_spin = QSpinBox()
        self._cover_n_spin.setRange(20, 500); self._cover_n_spin.setValue(100)
        top_row.addWidget(self._cover_n_spin)
        gen_btn = QPushButton("🔄 生成所有算法集合")
        gen_btn.setStyleSheet("background:#27AE60;color:white;font-weight:bold;padding:6px;")
        gen_btn.clicked.connect(self._generate_all_pred_sets)
        top_row.addWidget(gen_btn)
        gen_lay.addLayout(top_row)

        self._sets_display = QTextEdit()
        self._sets_display.setReadOnly(True)
        self._sets_display.setFixedHeight(160)
        self._sets_display.setPlaceholderText("点击「生成所有算法集合」后显示各集合内容…")
        gen_lay.addWidget(self._sets_display)
        lay.addWidget(gen_grp)

        # ── 集合运算配置 ──
        ops_grp = QGroupBox("② 集合运算配置")
        ops_lay = QGridLayout(ops_grp)

        ops_lay.addWidget(QLabel("选择集合A:"), 0, 0)
        self._set_a_combo = QComboBox()
        ops_lay.addWidget(self._set_a_combo, 0, 1)

        ops_lay.addWidget(QLabel("选择集合B:"), 0, 2)
        self._set_b_combo = QComboBox()
        ops_lay.addWidget(self._set_b_combo, 0, 3)

        ops_lay.addWidget(QLabel("运算类型:"), 1, 0)
        self._op_combo = QComboBox()
        self._op_combo.addItems([
            "交集 (A ∩ B)",
            "并集 (A ∪ B)",
            "差集 A-B",
            "差集 B-A",
            "补集 (全域 - A)",
            "对称差 (A △ B)",
            "交集+补集 (双重筛选)",
            "并集-交集 (边缘号码)",
        ])
        ops_lay.addWidget(self._op_combo, 1, 1, 1, 2)

        calc_btn = QPushButton("▶ 执行运算")
        calc_btn.setStyleSheet("background:#E74C3C;color:white;font-weight:bold;padding:6px;")
        calc_btn.clicked.connect(self._run_set_operation)
        ops_lay.addWidget(calc_btn, 1, 3)

        # 多集合批量交集/并集
        ops_lay.addWidget(QLabel("批量运算:"), 2, 0)
        batch_inter_btn = QPushButton("所有集合 交集")
        batch_inter_btn.setStyleSheet("background:#8E44AD;color:white;font-weight:bold;padding:5px;")
        batch_inter_btn.clicked.connect(lambda: self._batch_op("intersection"))
        ops_lay.addWidget(batch_inter_btn, 2, 1)
        batch_union_btn = QPushButton("所有集合 并集")
        batch_union_btn.setStyleSheet("background:#2980B9;color:white;font-weight:bold;padding:5px;")
        batch_union_btn.clicked.connect(lambda: self._batch_op("union"))
        ops_lay.addWidget(batch_union_btn, 2, 2)
        batch_smart_btn = QPushButton("智能覆盖推荐")
        batch_smart_btn.setStyleSheet("background:#16A085;color:white;font-weight:bold;padding:5px;")
        batch_smart_btn.clicked.connect(self._smart_cover_recommend)
        ops_lay.addWidget(batch_smart_btn, 2, 3)

        lay.addWidget(ops_grp)

        # ── 运算结果 ──
        res_grp  = QGroupBox("③ 运算结果")
        res_lay  = QVBoxLayout(res_grp)
        self._op_result_edit = QTextEdit()
        self._op_result_edit.setReadOnly(True)
        self._op_result_edit.setFixedHeight(130)
        res_lay.addWidget(self._op_result_edit)

        res_btns = QHBoxLayout()
        use_btn = QPushButton("✅ 用此结果生成投注推荐")
        use_btn.setStyleSheet("background:#27AE60;color:white;font-weight:bold;padding:6px;")
        use_btn.clicked.connect(self._use_op_result)
        res_btns.addWidget(use_btn)
        copy_btn = QPushButton("📋 复制结果")
        copy_btn.clicked.connect(lambda: QApplication.clipboard().setText(self._op_result_edit.toPlainText()))
        res_btns.addWidget(copy_btn)
        res_lay.addLayout(res_btns)
        lay.addWidget(res_grp)

        return w

    def _generate_all_pred_sets(self):
        """生成所有算法的预测集合"""
        n   = self._cover_n_spin.value()
        rec = self.records[:n]
        if not rec:
            QMessageBox.warning(self, "提示", "无历史数据"); return

        cfg     = self.cfg
        max_num = cfg["main_max"]
        main_n  = cfg["main_n"]

        # 提取主区号码列表
        all_main_lists = []
        for r in rec:
            nums = parse_draw_numbers(r.get("开奖号码", ""))
            main = self._extract_main(nums)
            if main:
                all_main_lists.append(main)

        if not all_main_lists:
            QMessageBox.warning(self, "提示", "无法解析历史数据"); return

        from collections import Counter
        flat  = [n for row in all_main_lists for n in row]
        freq  = Counter(flat)
        total = len(all_main_lists)

        # 遗漏
        last_seen = {}
        for i, row in enumerate(all_main_lists):
            for n in row:
                if n not in last_seen:
                    last_seen[n] = i
        omit = {n: last_seen.get(n, total) for n in range(1, max_num+1)}

        all_nums = list(range(1, max_num + 1))
        sorted_freq = sorted(all_nums, key=lambda x: -freq.get(x,0))
        sorted_omit = sorted(all_nums, key=lambda x: -omit.get(x,0))

        # 龙头/凤尾数据
        dragons   = [min(row) for row in all_main_lists]
        phoenixes = [max(row) for row in all_main_lists]
        from collections import Counter as _C
        d_freq = _C(dragons);  p_freq = _C(phoenixes)

        # 构建所有预测集合
        k = max(main_n + 3, 10)   # 每个集合约取 k 个号码作为候选池
        self.pred_sets = {
            "热号集合":      set(sorted_freq[:k]),
            "遗漏集合":      set(sorted_omit[:k]),
            "冷号集合":      set(sorted_freq[-k:]),
            "热遗混合":      set(sorted_freq[:k//2]) | set(sorted_omit[:k//2]),
            "近5期热号":     set(n for row in all_main_lists[:5] for n in row),
            "近10期热号":    set(n for row in all_main_lists[:10] for n in row),
            "奇数池":        set(x for x in all_nums if x % 2 == 1),
            "偶数池":        set(x for x in all_nums if x % 2 == 0),
            "龙头_热号":     set(sorted(range(1, max_num+1), key=lambda x: -d_freq.get(x,0))[:k//2]),
            "龙头_遗漏":     set(sorted(range(1, max_num+1), key=lambda x: -(total - last_seen.get(x, 0)))[:k//2]),
            "凤尾_热号":     set(sorted(range(1, max_num+1), key=lambda x: -p_freq.get(x,0))[:k//2]),
            "凤尾_遗漏":     set(sorted(range(1, max_num+1), key=lambda x: -(total - last_seen.get(x, 0)))[:k//2]),
            "全域":          set(all_nums),
        }

        # 如有龙头凤尾预测则并入
        if hasattr(self, "_dragons"):
            self.pred_sets["龙头_趋势"] = set(self._dragons[:5])
            self.pred_sets["凤尾_趋势"] = set(self._phoenixes[:5])

        # 更新下拉框
        names = sorted(k for k in self.pred_sets if k != "全域")
        self._set_a_combo.clear(); self._set_a_combo.addItems(names)
        self._set_b_combo.clear(); self._set_b_combo.addItems(names)
        if len(names) >= 2:
            self._set_b_combo.setCurrentIndex(1)

        # 显示集合摘要
        lines = []
        for name, s in self.pred_sets.items():
            lines.append(f"【{name}】({len(s)}个): {sorted(s)[:15]}{'...' if len(s)>15 else ''}")
        self._sets_display.setPlainText("\n".join(lines))

    def _run_set_operation(self):
        if not self.pred_sets:
            QMessageBox.warning(self, "提示", "请先点击「生成所有算法集合」"); return
        a_name = self._set_a_combo.currentText()
        b_name = self._set_b_combo.currentText()
        op     = self._op_combo.currentText()
        A = self.pred_sets.get(a_name, set())
        B = self.pred_sets.get(b_name, set())
        U = self.pred_sets.get("全域", set(range(1, self.cfg["main_max"]+1)))

        if   "交集" in op and "补集" not in op:   result = A & B;        op_str = "A ∩ B"
        elif "并集" in op and "交集" not in op:   result = A | B;        op_str = "A ∪ B"
        elif "差集 A-B" in op:                    result = A - B;        op_str = "A - B"
        elif "差集 B-A" in op:                    result = B - A;        op_str = "B - A"
        elif "补集" in op and "交集" not in op:   result = U - A;        op_str = "U - A"
        elif "对称差" in op:                       result = A ^ B;        op_str = "A △ B"
        elif "交集+补集" in op:                    result = (A & B) | (U - (A | B)); op_str = "(A∩B) ∪ (U-A-B)"
        elif "并集-交集" in op:                   result = (A | B) - (A & B); op_str = "(A∪B)-(A∩B)"
        else:                                      result = A & B;        op_str = "A ∩ B"

        sorted_r = sorted(result)
        self._op_result_edit.setPlainText(
            f"运算: {a_name} {op_str} {b_name}\n"
            f"结果({len(sorted_r)}个): {sorted_r}\n\n"
            f"A({len(A)}个): {sorted(A)}\n"
            f"B({len(B)}个): {sorted(B)}"
        )
        self.cover_result = sorted_r

    def _batch_op(self, mode: str):
        if not self.pred_sets:
            QMessageBox.warning(self, "提示", "请先生成集合"); return
        sets = [v for k, v in self.pred_sets.items() if k != "全域" and v]
        if not sets:
            return
        if mode == "intersection":
            result = sets[0].copy()
            for s in sets[1:]:
                result &= s
            op_name = "所有集合交集"
        else:
            result = sets[0].copy()
            for s in sets[1:]:
                result |= s
            op_name = "所有集合并集"
        sorted_r = sorted(result)
        self._op_result_edit.setPlainText(
            f"【{op_name}】共{len(sorted_r)}个号码:\n{sorted_r}"
        )
        self.cover_result = sorted_r

    def _smart_cover_recommend(self):
        """智能覆盖推荐：对各集合投票，取高票号码作为推荐池"""
        if not self.pred_sets:
            QMessageBox.warning(self, "提示", "请先生成集合"); return
        from collections import Counter
        vote = Counter()
        for k, s in self.pred_sets.items():
            if k == "全域": continue
            for n in s:
                vote[n] += 1
        max_num = self.cfg["main_max"]
        main_n  = self.cfg["main_n"]
        # 取票数 ≥ 一半集合数量的号码，至少取 main_n*2
        min_votes = max(2, len(self.pred_sets) // 3)
        recommended = sorted([n for n, v in vote.items() if v >= min_votes], key=lambda x: -vote[x])
        if len(recommended) < main_n:
            recommended = [n for n, _ in vote.most_common(main_n * 2)]

        lines = ["🏆 智能覆盖推荐（多集合投票）"]
        lines.append(f"推荐号码池({len(recommended)}个): {sorted(recommended)}")
        lines.append("")
        lines.append("各号码得票详情（前20）:")
        for n, v in vote.most_common(20):
            bar = "█" * v
            lines.append(f"  {n:>3}: {bar} ({v}票)")
        self._op_result_edit.setPlainText("\n".join(lines))
        self.cover_result = sorted(recommended)

    def _use_op_result(self):
        if not self.cover_result:
            QMessageBox.warning(self, "提示", "请先执行集合运算"); return
        QMessageBox.information(self, "已设置", f"已将 {len(self.cover_result)} 个号码设为投注推荐池，请切换到「投注推荐」标签")

    # ───────────── Tab3: 投注推荐 ─────────────

