    # ── 辅助：获取选中号码 ────────────────────────────────────────────────
    def _get_dan(self):
        return sorted([int(b.text()) for b in self.dan_btns if b.isChecked()])

    def _get_tuo(self):
        dan_set = set(self._get_dan())
        return sorted([int(b.text()) for b in self.tuo_btns if b.isChecked() and int(b.text()) not in dan_set])

    def _get_sub(self):
        return sorted([int(b.text()) for b in self.sub_btns if b.isChecked()])

    def _update_labels(self):
        dan = self._get_dan(); tuo = self._get_tuo(); sub = self._get_sub()
        c_d = "#E74C3C" if len(dan)<4 else ("#27AE60" if 4<=len(dan)<=6 else "#E67E22")
        self._dan_lbl.setText(f"胆码: {len(dan)}个 {'✅' if 4<=len(dan)<=6 else '(建议4~6)'}")
        self._dan_lbl.setStyleSheet(f"color:{c_d};font-weight:bold;font-size:11px;")
        c_t = "#8E44AD" if len(tuo)<6 else ("#27AE60" if 8<=len(tuo)<=12 else "#E67E22")
        self._tuo_lbl.setText(f"拖码: {len(tuo)}个 {'✅' if 8<=len(tuo)<=12 else '(建议8~12)'}")
        self._tuo_lbl.setStyleSheet(f"color:{c_t};font-weight:bold;font-size:11px;")
        if self._sub_lbl:
            self._sub_lbl.setText(f"{self.cfg['sub_label']}: {len(sub)}个")
        if dan:
            grps = self._build_dan_groups(dan, self._dan_gspin.value())
            self._dan_preview.setText(
                "旋转分组: " + "  |  ".join(f"[{','.join(map(str,g))}]" for g in grps)
                + f"  共{len(grps)}组")
        else:
            self._dan_preview.setText("（选完胆码后自动预览旋转分组）")

    # ── 胆码旋转 ──────────────────────────────────────────────────────────
    def _build_dan_groups(self, dan: list, group_size: int) -> list:
        hit_target = self._dan_hspin.value()
        if len(dan) <= group_size:
            return [dan[:]]
        all_sub   = list(combinations(dan, hit_target))
        all_grps  = list(combinations(dan, group_size))
        covered   = set(); selected = []
        for g in all_grps:
            g_sub = set(frozenset(s) for s in combinations(g, hit_target))
            new   = g_sub - covered
            if new:
                selected.append(list(g)); covered |= new
            if len(covered) >= len(all_sub): break
        return selected if selected else [list(dan[:group_size])]

    # ── 拖码矩阵缩水 ─────────────────────────────────────────────────────
    def _tuo_matrix_cover(self, tuo: list, need: int, hit: int) -> list:
        n   = len(tuo)
        key = (min(n, 12), hit)
        tpl = self._MATRIX.get(key)
        if tpl:
            rows = []
            for row in tpl:
                nums = [tuo[idx] for idx in row if idx < n]
                if len(nums) == need: rows.append(sorted(nums))
            if rows: return rows
        if n < need: return [sorted(tuo)]
        all_c  = list(combinations(tuo, need))
        tgts   = list(combinations(tuo, hit))
        covered = set(); selected = []
        # V43: 确定性贪心（不再 random.shuffle），保证同样选号每次输出一致、费用可复现
        for combo in all_c:
            subs = set(frozenset(c) for c in combinations(combo, hit))
            new  = subs - covered
            if new: selected.append(list(combo)); covered |= new
            if len(covered) >= len(tgts): break
        return [sorted(s) for s in selected] if selected else [sorted(tuo[:need])]

    # ── AI推荐 ────────────────────────────────────────────────────────────
    def _ai_recommend_dan(self):
        cfg = self.cfg
        is_pos = cfg["mtype"].startswith("pos")
        area = cfg["main_area"]; rng = range(0,10) if is_pos else range(1, cfg["main_max"]+1)
        scores = {}
        for n in rng:
            omit = self.app.get_omission(self.game_type, n, area)
            freq = self.app.get_frequency(self.game_type, n, area)
            cht  = self.app.get_cold_hot(self.game_type,  n, area)
            s = freq*0.4 + min(omit,15)*0.3 + (1.0 if cht=="warm" else 0.5 if cht=="hot" else 0.2)*20
            scores[n] = s
        top = sorted(scores, key=lambda x: -scores[x])[:5]
        for btn in self.dan_btns: btn.setChecked(int(btn.text()) in top)
        self._update_labels()
        QMessageBox.information(self, "AI推荐胆码",
            f"已推荐 {len(top)} 个胆码: {', '.join(map(str, sorted(top)))}\n基于频率×0.4+遗漏×0.3+冷热×0.3")

    def _ai_recommend_tuo(self):
        cfg  = self.cfg; dan_s = set(self._get_dan())
        area = cfg["main_area"]; is_pos = cfg["mtype"].startswith("pos")
        rng  = range(0,10) if is_pos else range(1, cfg["main_max"]+1)
        scores = {}
        for n in rng:
            if n in dan_s: continue
            freq = self.app.get_frequency(self.game_type, n, area)
            omit = self.app.get_omission(self.game_type, n, area)
            cht  = self.app.get_cold_hot(self.game_type,  n, area)
            s = freq*0.35 + min(omit,20)*0.35 + (0.8 if cht=="warm" else 0.4 if cht=="hot" else 0.6)*15
            scores[n] = s
        top = sorted(scores, key=lambda x: -scores[x])[:10]
        for btn in self.tuo_btns: btn.setChecked(int(btn.text()) in top)
        self._update_labels()
        QMessageBox.information(self, "AI推荐拖码",
            f"已推荐 {len(top)} 个拖码: {', '.join(map(str, sorted(top)))}")

    def _ai_recommend_sub(self):
        cfg = self.cfg; area = cfg["sub_area"]
        if not area or not self.sub_btns: return
        scores = {}
        for n in range(1, cfg["sub_max"]+1):
            freq = self.app.get_frequency(self.game_type, n, area)
            omit = self.app.get_omission(self.game_type, n, area)
            scores[n] = freq*0.6 + min(omit,15)*0.4
        top = sorted(scores, key=lambda x: -scores[x])[:max(2, cfg["sub_need"]+1)]
        for btn in self.sub_btns: btn.setChecked(int(btn.text()) in top)
        self._update_labels()
        QMessageBox.information(self, f"AI推荐{cfg['sub_label']}",
            f"已推荐 {len(top)} 个{cfg['sub_label']}: {', '.join(map(str, sorted(top)))}")

    # ── 模型预测 ──────────────────────────────────────────────────────────
    def _run_model_predict(self):
        selected_models = [mk for mk, cb in self._model_checks.items() if cb.isChecked()]
        if not selected_models:
            QMessageBox.warning(self, "提示", "请至少勾选一个预测模型"); return
        hist = self.app.history_data.get(self.game_type, [])
        if not hist:
            QMessageBox.warning(self, "提示", f"暂无{self.game_type}历史数据，请先获取开奖数据"); return

        self.app.backtest_predictions()
        cnt = self._pred_cnt_spin.value()
        fusion = self._fusion_combo.currentText()
        cfg = self.cfg

        all_preds = []
        err_models = []
        for mk in selected_models:
            mn = PREDICTION_MODELS.get(mk, {}).get("name", mk)
            try:
                for _ in range(cnt):
                    p = self.app.predict_for_game(self.game_type, mk)
                    if p: all_preds.append((mk, mn, p))
            except Exception as e:
                err_models.append(f"{mn}({e})")

        if not all_preds:
            self._pred_result_te.setPlainText("⚠ 所有模型运行失败，请检查历史数据是否充足"); return

        # 融合处理
        vote_main = {}; vote_sub = {}
        for mk, mn, p in all_preds:
            main_nums = (p.get("red") or p.get("front") or p.get("main") or
                         [v for k, v in sorted(p.items()) if k.startswith("pos")])
            main_nums = main_nums if isinstance(main_nums, list) else [main_nums]
            for n in main_nums:
                vote_main[n] = vote_main.get(n, 0) + 1
            sub_nums = (p.get("blue") or p.get("back") or [])
            sub_nums = [sub_nums] if isinstance(sub_nums, int) else (sub_nums or [])
            for n in sub_nums:
                vote_sub[n] = vote_sub.get(n, 0) + 1

        # 根据融合方式选号
        need = cfg["main_need"]
        if "投票" in fusion or "加权" in fusion:
            rec_main = sorted(sorted(vote_main, key=lambda x: -vote_main[x])[:need+4])
        elif "交集" in fusion:
            # 出现在超过半数模型中的号码
            threshold = len(selected_models) // 2 + 1
            rec_main = sorted([n for n, cnt_v in vote_main.items() if cnt_v >= threshold])
            if len(rec_main) < need:
                extras = sorted(vote_main, key=lambda x: -vote_main[x])
                for ex in extras:
                    if ex not in rec_main: rec_main.append(ex)
                    if len(rec_main) >= need+2: break
            rec_main = sorted(rec_main[:need+2])
        else:  # 并集
            rec_main = sorted(sorted(vote_main, key=lambda x: -vote_main[x])[:need+6])

        rec_sub = sorted(sorted(vote_sub, key=lambda x: -vote_sub[x])[:max(2, cfg["sub_need"]+1)])
        self._last_pred_main = rec_main
        self._last_pred_sub  = rec_sub

        # 格式化输出
        lines = [f"🤖 {self.game_type} 多模型融合预测结果（{fusion}）"]
        lines.append(f"   共 {len(selected_models)} 个模型 × {cnt} 次  运行 {len(all_preds)} 次")
        lines.append("")
        lines.append(f"【综合推荐{cfg['main_label']}（{need}+备选）】: {', '.join(map(str, rec_main))}")
        if rec_sub and cfg["sub_area"]:
            lines.append(f"【综合推荐{cfg['sub_label']}】: {', '.join(map(str, rec_sub))}")
        lines.append("")
        lines.append("── 各模型投票详情 ──")
        top_votes = sorted(vote_main.items(), key=lambda x: -x[1])[:15]
        for n, v in top_votes:
            bar = "█" * v + "░" * max(0, len(selected_models)*cnt - v)
            pct = v / (len(selected_models)*cnt) * 100
            lines.append(f"  号码 {n:3d}: {''.join(['█']*min(v,20))} {pct:.0f}%  ({v}票)")
        lines.append("")
        if err_models:
            lines.append(f"⚠ 异常模型: {', '.join(err_models)}")

        self._pred_result_te.setPlainText("\n".join(lines))

    def _fill_pred_to_selection(self):
        if not hasattr(self, "_last_pred_main"):
            QMessageBox.warning(self, "提示", "请先点击【运行选中模型】"); return
        main = self._last_pred_main; sub = self._last_pred_sub
        need = self.cfg["main_need"]
        # 前 need 个填胆码，后面填拖码
        dan_rec = set(main[:min(5, len(main))])
        tuo_rec = set(main[min(5, len(main)):min(len(main), 15)])
        for btn in self.dan_btns:
            btn.setChecked(int(btn.text()) in dan_rec)
        for btn in self.tuo_btns:
            n = int(btn.text())
            btn.setChecked(n in tuo_rec and n not in dan_rec)
        if self.sub_btns and sub:
            sub_s = set(sub[:self.cfg["sub_need"]+1])
            for btn in self.sub_btns:
                btn.setChecked(int(btn.text()) in sub_s)
        self._update_labels()
        QMessageBox.information(self, "已填入", f"已将预测号码填入选号区\n胆码: {sorted(dan_rec)}\n拖码: {sorted(tuo_rec)}")

    # ── 重号/边码/关系码 初始化 ──────────────────────────────────────────
    def _init_repeat_edge_data(self):
        """启动时自动加载重号和边码统计"""
        cfg   = self.cfg; records = self.app.history_data.get(self.game_type, [])
        if len(records) < 2: return
        edge_set = cfg["edge"]; is_pos = cfg["mtype"].startswith("pos")

        def get_main_nums(rec):
            raw = rec.get("开奖号码", "")
            try:
                import re as _re
                nums = [int(x) for x in _re.findall(r'\d+', str(raw))]
            except Exception: nums = []
            return sorted(nums[:cfg["main_need"]])

        # ── 重号表 ──
        repeat_counts = []
        self._re_tbl.setRowCount(min(50, len(records)-1))
        for i in range(1, min(51, len(records))):
            prev_m = set(get_main_nums(records[i-1]))
            curr_m = set(get_main_nums(records[i]))
            reps   = sorted(curr_m & prev_m)
            ri = i-1
            self._re_tbl.setItem(ri, 0, QTableWidgetItem(str(records[i].get("期号",""))))
            self._re_tbl.setItem(ri, 1, QTableWidgetItem(" ".join(map(str, sorted(curr_m)))))
            self._re_tbl.setItem(ri, 2, QTableWidgetItem(str(len(reps))))
            self._re_tbl.setItem(ri, 3, QTableWidgetItem(", ".join(map(str, reps))))
            self._re_tbl.setItem(ri, 4, QTableWidgetItem(str(ri)))
            if len(reps) >= 2:
                for c in range(5):
                    it = self._re_tbl.item(ri, c)
                    if it: it.setBackground(QColor("#FFEBEE"))
            repeat_counts.append(len(reps))

        # 预测统计
        avg_r = sum(repeat_counts)/len(repeat_counts) if repeat_counts else 0
        last10 = repeat_counts[-10:]
        pred_r = round(sum(last10)/len(last10)) if last10 else 1
        last_main = get_main_nums(records[-1]) if records else []
        self._last_main = last_main; self._pred_repeat_n = pred_r

        self._re_summary.setPlainText(
            f"全局平均重号数: {avg_r:.2f}个  |  近10期均值: {sum(last10)/len(last10) if last10 else 0:.2f}个\n"
            f"★ 预测下期重号数: {pred_r}个  |  上期号码(候选重号): {last_main}")

        # ── 边码表 ──
        edge_counts = []
        self._edge_tbl.setRowCount(min(50, len(records)))
        for i in range(min(50, len(records))):
            curr_m = get_main_nums(records[i])
            edges  = sorted([n for n in curr_m if n in edge_set])
            self._edge_tbl.setItem(i, 0, QTableWidgetItem(str(records[i].get("期号",""))))
            self._edge_tbl.setItem(i, 1, QTableWidgetItem(" ".join(map(str, curr_m))))
            self._edge_tbl.setItem(i, 2, QTableWidgetItem(str(len(edges))))
            self._edge_tbl.setItem(i, 3, QTableWidgetItem(", ".join(map(str, edges))))
            if edges:
                for c in (2,3):
                    it = self._edge_tbl.item(i, c)
                    if it: it.setForeground(QColor("#8E44AD"))
            edge_counts.append(len(edges))

        avg_e  = sum(edge_counts)/len(edge_counts) if edge_counts else 0
        last10e = edge_counts[-10:]
        pred_e  = round(sum(last10e)/len(last10e)) if last10e else 1
        self._pred_edge_n = pred_e; self._edge_set_local = edge_set

        self._edge_summary.setPlainText(
            f"全局平均边码数: {avg_e:.2f}个  |  近10期均值: {sum(last10e)/len(last10e) if last10e else 0:.2f}个\n"
            f"★ 预测下期边码数: {pred_e}个  |  边码定义: {sorted(edge_set)}")

    def _fill_repeat_to_dan(self):
        """将预测重号填入胆码区"""
        if not hasattr(self, "_last_main"): return
        pred_n = getattr(self, "_pred_repeat_n", 1)
        rep_nums = set(self._last_main[:pred_n+1])
        for btn in self.dan_btns:
            btn.setChecked(int(btn.text()) in rep_nums)
        self._update_labels()
        QMessageBox.information(self, "已填入", f"已将预测重号 {sorted(rep_nums)} 填入胆码区")

    def _fill_edge_to_tuo(self):
        """将边码填入拖码区"""
        if not hasattr(self, "_edge_set_local"): return
        dan_s = set(self._get_dan())
        edge_nums = {n for n in self._edge_set_local if n not in dan_s}
        for btn in self.tuo_btns:
            n = int(btn.text())
            if n in edge_nums: btn.setChecked(True)
        self._update_labels()
        QMessageBox.information(self, "已填入", f"已将边码 {sorted(edge_nums)} 填入拖码区")

    def _run_cooccurrence(self):
        """计算共现矩阵并显示"""
        records = self.app.history_data.get(self.game_type, [])
        n_use   = min(self._cooc_n_spin.value(), len(records))
        top_n   = self._cooc_top_spin.value()
        cfg     = self.cfg

        import re as _re
        def get_main(rec):
            raw = rec.get("开奖号码", "")
            nums = [int(x) for x in _re.findall(r'\d+', str(raw))]
            return sorted(nums[:cfg["main_need"]])

        cooc = {}
        total_draws = 0
        for rec in records[:n_use]:
            nums = get_main(rec)
            total_draws += 1
            for i in range(len(nums)):
                for j in range(i+1, len(nums)):
                    key = (nums[i], nums[j])
                    cooc[key] = cooc.get(key, 0) + 1

        if not cooc:
            self._cooc_summary.setPlainText("数据不足，无法计算共现"); return

        sorted_cooc = sorted(cooc.items(), key=lambda x: -x[1])[:top_n]
        self._last_cooc = sorted_cooc

        self._cooc_tbl.setRowCount(len(sorted_cooc))
        for i, ((a, b), cnt_v) in enumerate(sorted_cooc):
            pct = cnt_v / total_draws * 100
            strength = "★★★" if pct >= 30 else ("★★" if pct >= 15 else "★")
            self._cooc_tbl.setItem(i, 0, QTableWidgetItem(str(a)))
            self._cooc_tbl.setItem(i, 1, QTableWidgetItem(str(b)))
            self._cooc_tbl.setItem(i, 2, QTableWidgetItem(str(cnt_v)))
            self._cooc_tbl.setItem(i, 3, QTableWidgetItem(f"{pct:.1f}"))
            self._cooc_tbl.setItem(i, 4, QTableWidgetItem(strength))
            if pct >= 30:
                for c in range(5):
                    it = self._cooc_tbl.item(i, c)
                    if it: it.setBackground(QColor("#E8F8F5"))

        # 提取高频共现号
        top_nums = set()
        for (a, b), _ in sorted_cooc[:10]:
            top_nums.add(a); top_nums.add(b)
        self._last_cooc_nums = sorted(top_nums)

        self._cooc_summary.setPlainText(
            f"分析 {n_use} 期数据，共 {len(cooc)} 个号码对  |  最高共现: {sorted_cooc[0]}\n"
            f"高频关系码组: {self._last_cooc_nums}")

    def _fill_cooc_to(self, target: str):
        if not hasattr(self, "_last_cooc_nums"): 
            QMessageBox.warning(self, "提示", "请先点击【分析关系码】"); return
        nums = set(self._last_cooc_nums)
        if target == "dan":
            dan_need = 5
            select_nums = set(list(nums)[:dan_need])
            for btn in self.dan_btns:
                btn.setChecked(int(btn.text()) in select_nums)
        else:
            dan_s = set(self._get_dan())
            for btn in self.tuo_btns:
                n = int(btn.text())
                if n in nums and n not in dan_s: btn.setChecked(True)
        self._update_labels()
        QMessageBox.information(self, "已填入", f"已将关系码 {sorted(nums)[:10]} 填入{'胆码' if target=='dan' else '拖码'}区")

    # ── 生成方案 ──────────────────────────────────────────────────────────
    def _generate(self):
        dan = self._get_dan(); tuo = self._get_tuo(); sub = self._get_sub()
        cfg = self.cfg
        # V43: 该"胆拖旋转 + 矩阵缩水"覆盖模型生成的是"若干个不重复数字"的组合。
        # 对 3D/排列三(选3个不重复数字)恰好等价于【组选六】，可用；
        # 但排列五(5)/七星彩(7)取5/7个不重复数字不对应任何真实玩法(定位玩法只有直选)，拦截。
        if cfg["mtype"] in ("pos5", "pos7"):
            QMessageBox.information(self, "本玩法不适用",
                f"双重嵌套覆盖（胆码旋转 + 拖码矩阵缩水）适用于选号型玩法"
                f"（双色球/大乐透/快乐8/七乐彩）及 3D/排列三（按组选六处理）。\n\n"
                f"{self.game_type} 为定位玩法（5/7 个有序位置、数字可重复），"
                f"没有“挑若干不重复数字”的对应玩法，请改用专用的直选投注工具。")
            return
        main_need = cfg["main_need"]; sub_need = cfg["sub_need"]
        main_label = cfg["main_label"]; sub_label = cfg["sub_label"]

        errs = []
        if len(dan) < 2:         errs.append("胆码池至少选2个")
        if len(tuo) < 3:         errs.append("拖码池至少选3个")
        if sub_need > 0 and len(sub) < sub_need: errs.append(f"{sub_label}至少选{sub_need}个")
        if errs:
            QMessageBox.warning(self, "⚠ 选号不足", "\n".join(errs)); return

        g_size   = self._dan_gspin.value()
        hit_guar = self._matrix_spin.value()

        # 第一层：胆码旋转
        dan_groups = self._build_dan_groups(dan, g_size)

        # 第二层：拖码矩阵缩水
        tuo_remain = max(1, main_need - g_size)
        hit_eff = min(hit_guar, tuo_remain)
        # 防组合爆炸/卡死：无内置模板时需枚举 C(len(tuo), tuo_remain)，大池子会瞬间爆内存
        if (min(len(tuo), 12), hit_eff) not in self._MATRIX:
            try:
                est = math.comb(len(tuo), tuo_remain)
            except Exception:
                est = 0
            if est > 300000:
                QMessageBox.warning(self, "⚠ 拖码过多",
                    f"当前拖码池在该配置下需枚举约 {est:,} 种组合，可能导致卡顿或内存不足。\n"
                    f"请减少拖码数量、调大「胆码每组数」或调整「命中保证」后重试。")
                return
        matrix_rows = self._tuo_matrix_cover(tuo, tuo_remain, hit_eff)

        # 嵌套合成
        lines = []
        is_lotto = cfg["mtype"] == "lotto"
        is_kl8   = cfg["mtype"] == "kl8"
        is_qlc   = cfg["mtype"] == "qlc"
        is_pos   = cfg["mtype"].startswith("pos")

        sub_pairs = []
        if sub and sub_need == 2:
            # 大乐透：取所有2个后区组合
            sub_pairs = list(combinations(sub, 2))
            if not sub_pairs: sub_pairs = [(sub[0], sub[min(1,len(sub)-1)])]
        elif sub and sub_need == 1:
            sub_pairs = [(s,) for s in sub]

        for dan_grp in dan_groups:
            for tuo_row in matrix_rows:
                full_main = sorted(set(dan_grp) | set(tuo_row))
                if len(full_main) < main_need:
                    extra = [n for n in tuo if n not in full_main]
                    full_main = sorted(full_main + extra[:main_need - len(full_main)])
                full_main = full_main[:main_need]
                main_str  = ", ".join(f"{n:02d}" for n in full_main)

                if is_pos:
                    lines.append(f"{main_label}: {main_str}")
                elif is_kl8 or is_qlc:
                    lines.append(f"{main_label}: {main_str}")
                elif is_lotto:
                    if sub_pairs:
                        for sp in sub_pairs:
                            sub_str = ", ".join(f"{n:02d}" for n in sp)
                            lines.append(f"{main_label}: {main_str}  {sub_label}: {sub_str}")
                    else:
                        lines.append(f"{main_label}: {main_str}")
                else:
                    lines.append(f"{main_label}: {main_str}")

        lines = list(dict.fromkeys(lines))
        self.result_lines = lines

        price      = cfg["price"]
        total_cost = len(lines) * price
        # 全复式对比：主区 C(池, main_need)；副区按 sub_need 取组合数(大乐透后区=C(后区数,2))
        if sub and sub_need >= 2:
            sub_full = math.comb(len(sub), sub_need) if len(sub) >= sub_need else 1
        elif sub and sub_need == 1:
            sub_full = len(sub)
        else:
            sub_full = 1
        full_c     = math.comb(len(dan)+len(tuo), main_need) * max(1, sub_full)
        savings    = (1 - len(lines)/max(full_c,1))*100

        summary = [
            f"{'='*52}",
            f"🎯 {self.game_type} — 双重嵌套覆盖方案",
            f"{'='*52}",
            f"胆码池 ({len(dan)}个): {', '.join(map(str, dan))}",
            f"拖码池 ({len(tuo)}个): {', '.join(map(str, tuo))}",
        ]
        if sub: summary.append(f"{sub_label} ({len(sub)}个): {', '.join(map(str, sub))}")
        summary += [
            f"{'─'*52}",
            f"第一层 胆码旋转: {len(dan_groups)} 组 (每组{g_size}个)",
            f"第二层 矩阵缩水: {len(matrix_rows)} 行 (保证≥{hit_guar}命中)",
            f"{'─'*52}",
            f"✅ 嵌套后总注数: {len(lines)} 注  ¥{total_cost:.0f}",
            f"全复式对比:     {full_c} 注",
            f"💰 节省比例:     {savings:.1f}%  (减少{full_c-len(lines)}注)",
            f"{'─'*52}",
            (f"📌 {self.game_type} 按【组选六】处理：每注为{main_need}个不重复数字，开奖号含这{main_need}个数字即中（不计顺序）。"
             if is_pos else
             f"覆盖保证：只要{main_label}命中号在选号池中≥{hit_guar}个，必有1注覆盖！"),
            f"{'='*52}",
            "",
        ]
        summary += [f"第{i+1:03d}注: {l}" for i, l in enumerate(lines)]
        self._result_te.setPlainText("\n".join(summary))
        # 切换到结果标签
        try:
            parent_tabs = self.findChild(QTabWidget)
            if parent_tabs: parent_tabs.setCurrentIndex(3)
        except Exception: pass
        QMessageBox.information(self, "✅ 生成完成",
            f"已生成 {len(lines)} 注嵌套覆盖方案！\n¥{total_cost:.0f}（全复式为{full_c}注，节省{savings:.1f}%）")

    def _copy_result(self):
        txt = self._result_te.toPlainText()
        if not txt.strip(): QMessageBox.information(self, "提示", "请先点击【生成嵌套方案】"); return
        QApplication.clipboard().setText(txt)
        QMessageBox.information(self, "✅ 已复制", f"已复制 {len(self.result_lines)} 注方案到剪贴板！")

    def _bet_all(self):
        if not self.result_lines:
            QMessageBox.information(self, "提示", "请先点击【生成嵌套方案】"); return
        target = self.app.get_default_target_issue(self.game_type)
        price  = self.cfg["price"]
        for line in self.result_lines:
            self.app.add_betting_record(self.game_type, "嵌套覆盖", line, 1, price, target_issue=target)
        QMessageBox.information(self, "✅ 投注成功",
            f"已添加【{self.game_type}】双重嵌套覆盖 {len(self.result_lines)} 注！\n"
            f"总费用 ¥{len(self.result_lines)*price:.0f}")

    def _build_hist_analysis_tab(self, parent_tabs: QTabWidget) -> QWidget:
        """历史数据分析选号 Tab — 频次/遗漏统计，点击号码填入胆码/拖码区。"""
        cfg       = self.cfg
        main_max  = cfg.get("main_max", 33)
        main_lbl  = cfg.get("main_label", "号码")
        sub_max   = cfg.get("sub_max", 0)
        sub_lbl   = cfg.get("sub_label", "")

        tab = QWidget(); lay = QVBoxLayout(tab); lay.setSpacing(4)
        banner = QLabel(f"📊 历史数据分析 — 频次/遗漏统计，点击号码直接填入胆码/拖码区")
        banner.setStyleSheet("font-size:11px;font-weight:bold;color:#1A5276;padding:3px;")
        lay.addWidget(banner)

        # 控制栏
        ctrl = QHBoxLayout()
        ctrl.addWidget(QLabel("分析近:"))
        n_sp = QSpinBox(); n_sp.setRange(10, 300); n_sp.setValue(50)
        ctrl.addWidget(n_sp); ctrl.addWidget(QLabel("期"))
        area_opts = [main_lbl]
        if sub_max > 0: area_opts.append(sub_lbl)
        area_opts.append("全部")
        area_cb = QComboBox(); area_cb.addItems(area_opts)
        ctrl.addWidget(QLabel("  区域:")); ctrl.addWidget(area_cb)
        run_btn = QPushButton("🔍 分析")
        run_btn.setStyleSheet("background:#E67E22;color:white;font-weight:bold;padding:4px 10px;border-radius:3px;")
        ctrl.addWidget(run_btn); ctrl.addStretch()
        lay.addLayout(ctrl)

        # 统计汇总标签
        summary_lbl = QLabel("")
        summary_lbl.setStyleSheet("font-size:11px;color:#555;padding:2px;")
        lay.addWidget(summary_lbl)

        # 号码面板
        panel_grp = QGroupBox(f"点击选号（🔴热号  🔵冷号  🟡高遗漏）— 选中后点击填入按钮")
        panel_grp.setStyleSheet("QGroupBox{font-size:10px;font-weight:bold;padding-top:12px;}")
        panel_grid = QGridLayout(); panel_grid.setSpacing(2)
        panel_grp.setLayout(panel_grid)
        lay.addWidget(panel_grp)

        btn_map: dict[int, QPushButton] = {}

        # 频次/遗漏排行
        rank_te = QTextEdit(); rank_te.setReadOnly(True)
        rank_te.setMaximumHeight(110)
        rank_te.setStyleSheet("font-size:10px;background:#F8F9FA;border:1px solid #ddd;")
        lay.addWidget(rank_te)

        def rebuild_panel(freq_map, omit_map, hot_set, cold_set, omit_top, nums_range):
            while panel_grid.count():
                item = panel_grid.takeAt(0)
                if item.widget(): item.widget().deleteLater()
            btn_map.clear()
            cols = 10 if max(nums_range, default=1) > 20 else 8
            for idx, n in enumerate(nums_range):
                if n in hot_set:    bg, fg = "#E74C3C","white"
                elif n in cold_set: bg, fg = "#3498DB","white"
                elif n in omit_top: bg, fg = "#F39C12","white"
                else:               bg, fg = "#ECF0F1","#2C3E50"
                b = QPushButton(str(n)); b.setCheckable(True); b.setFixedSize(34, 30)
                b.setToolTip(f"号码{n}  出现{freq_map.get(n,0)}次  遗漏{omit_map.get(n,0)}期")
                b.setStyleSheet(
                    f"QPushButton{{background:{bg};color:{fg};border-radius:15px;font-size:10px;font-weight:bold;}}"
                    f"QPushButton:checked{{background:#8E44AD;color:white;border:2px solid #6C3483;}}")
                btn_map[n] = b
                panel_grid.addWidget(b, idx // cols, idx % cols)

        def do_analysis():
            from collections import Counter
            n_hist = n_sp.value()
            area   = area_cb.currentText()
            recs   = (self.app.history_data or {}).get(self.game_type, [])
            if not recs: QMessageBox.warning(tab, "提示", "暂无历史数据"); return

            all_parsed = []
            for rec in recs[:n_hist]:
                nums = self.app.get_draw_numbers(self.game_type, rec)
                if nums: all_parsed.append(nums)
            if not all_parsed: return

            if area == main_lbl:
                nums_range = list(range(1, main_max + 1))
                flat = [n for row in all_parsed for n in row if n <= main_max]
            elif sub_max > 0 and area == sub_lbl:
                nums_range = list(range(1, sub_max + 1))
                flat = [n for row in all_parsed for n in row if n > main_max]
            else:
                nums_range = list(range(1, main_max + 1))
                flat = [n for row in all_parsed for n in row]

            freq  = Counter(flat); total = len(all_parsed)
            last_app2: dict[int, int] = {}
            for i, row in enumerate(all_parsed):
                for n in row:
                    if n not in last_app2: last_app2[n] = i
            omit  = {n: last_app2.get(n, total) for n in range(1, max(nums_range or [1])+1)}
            sf    = sorted(freq, key=lambda x: -freq.get(x, 0))
            sz    = max(1, len(sf) // 3)
            hot_s = set(sf[:sz]); cold_s = set(sf[-sz:])
            omit_s= set(sorted(omit, key=lambda x: -omit.get(x, 0))[:sz])

            summary_lbl.setText(
                f"分析 {n_hist} 期 | 🔴热号(前{sz}): {sorted(hot_s)[:5]}...  "
                f"🔵冷号(后{sz}): {sorted(cold_s)[:5]}...  🟡高遗漏: {sorted(omit_s, key=lambda x: -omit.get(x,0))[:5]}..."
            )
            rebuild_panel(dict(freq), omit, hot_s, cold_s, omit_s, nums_range)
            # 排行文本
            top_freq  = sf[:15]
            top_omit  = sorted(omit, key=lambda x: -omit.get(x, 0))[:15]
            rank_te.setPlainText(
                "🔥 频率TOP15: " + "  ".join(f"[{n}:{freq.get(n,0)}次]" for n in top_freq) + "\n"
                "⏰ 遗漏TOP15: " + "  ".join(f"[{n}:{omit.get(n,0)}期]" for n in top_omit)
            )

        # 填入按钮
        fill_row = QHBoxLayout()
        def make_fill_btn(label, color, target_attr, target_name):
            b = QPushButton(label)
            b.setStyleSheet(f"background:{color};color:white;font-weight:bold;padding:5px;border-radius:3px;")
            def _fill():
                sel = sorted(n for n, btn in btn_map.items() if btn.isChecked())
                if not sel: QMessageBox.warning(tab, "提示", "请先选择号码"); return
                btn_list = getattr(self, target_attr, [])
                if not btn_list: QMessageBox.warning(tab, "提示", f"未找到{target_name}按钮区"); return
                for bt in btn_list: bt.setChecked(False)
                for n in sel:
                    idx = n - 1
                    if 0 <= idx < len(btn_list): btn_list[idx].setChecked(True)
                parent_tabs.setCurrentIndex(0)
                QMessageBox.information(tab, "✅", f"已填入{target_name} {len(sel)} 个: {sel}")
            b.clicked.connect(_fill)
            return b

        if hasattr(self, "_main_btns"):
            fill_row.addWidget(make_fill_btn("📥 填入胆码区", "#1A5276", "_main_btns", "胆码"))
        if hasattr(self, "_tuo_btns"):
            fill_row.addWidget(make_fill_btn("📥 填入拖码区", "#27AE60", "_tuo_btns", "拖码"))
        clr_btn = QPushButton("清空选中")
        clr_btn.setStyleSheet("padding:5px;border-radius:3px;")
        clr_btn.clicked.connect(lambda: [b.setChecked(False) for b in btn_map.values()])
        fill_row.addWidget(clr_btn); fill_row.addStretch()
        lay.addLayout(fill_row)

        run_btn.clicked.connect(do_analysis)
        return tab

