class ShuishuiDialog(QDialog):
    """缩水投注对话框（支持所有玩法，增加主流缩水选项）"""
    def __init__(self, parent, game_type, selected_numbers=None):
        super().__init__(parent)
        self.parent = parent
        self.game_type = game_type
        self.selected_numbers = selected_numbers or []  # 预选号码
        self.area_buttons = []  # 存储各个区域的按钮列表
        self.area_names = []     # 区域名称
        self.setWindowTitle(f"{game_type} - 缩水投注")
        _sc = QApplication.primaryScreen().availableGeometry()
        self.setMinimumSize(380, 800)
        self.resize(max(420, min(600, int(_sc.width()*0.38))), max(600, min(900, int(_sc.height()*0.85))))
        self.init_ui()
        if self.selected_numbers:
            self.preselect_numbers()

