    def _init_position_area(self, content_layout):
        """位置型号码选择区域（3D、排列三、排列五、七星彩）"""
        if self.game_type == "3D":
            positions = ["百位", "十位", "个位"]
            ranges = [(0,10)] * 3
        elif self.game_type == "排列三":
            positions = ["百位", "十位", "个位"]
            ranges = [(0,10)] * 3
        elif self.game_type == "排列五":
            positions = ["万位", "千位", "百位", "十位", "个位"]
            ranges = [(0,10)] * 5
        elif self.game_type == "七星彩":
            positions = ["第一位", "第二位", "第三位", "第四位", "第五位", "第六位", "第七位"]
            ranges = [(0,10)] * 6 + [(0,15)]  # 第7位0-14
        else:
            return

        self.area_names = positions
        self.area_buttons = []  # 每个元素是该位置的按钮列表

        for idx, (pos_name, rng) in enumerate(zip(positions, ranges)):
            group = QGroupBox(f"{pos_name} ({rng[0]}-{rng[1]-1})")
            layout = QVBoxLayout()
            grid = QGridLayout()
            grid.setSpacing(5)
            buttons = []
            for i in range(rng[0], rng[1]):
                # 根据游戏类型和位置获取冷热数据
                area_key = f"pos{idx+1}"
                omission = self.parent.get_omission(self.game_type, i, area_key)
                frequency = self.parent.get_frequency(self.game_type, i, area_key)
                cold_hot = self.parent.get_cold_hot(self.game_type, i, area_key)
                probability = self.parent.calculate_probability(self.game_type, i, area_key)
                btn = NumberButton(str(i), cold_hot, omission, frequency, probability=probability)
                btn.clicked.connect(self.update_selection)
                buttons.append(btn)
                row = i // 5
                col = i % 5
                grid.addWidget(btn, row, col)
            layout.addLayout(grid)
            # 快捷按钮
            quick = QHBoxLayout()
            quick.addWidget(QLabel("操作:"))
            all_btn = QPushButton("全选")
            all_btn.clicked.connect(lambda checked, btns=buttons: self.select_all(btns))
            quick.addWidget(all_btn)
            clear_btn = QPushButton("清空")
            clear_btn.clicked.connect(lambda checked, btns=buttons: self.clear_all(btns))
            quick.addWidget(clear_btn)
            random_btn = QPushButton("随机选")
            random_btn.clicked.connect(lambda checked, btns=buttons: self.random_select(btns, min(3, len(btns))))
            quick.addWidget(random_btn)
            layout.addLayout(quick)
            group.setLayout(layout)
            content_layout.addWidget(group)
            self.area_buttons.append(buttons)

        self.count_label = QLabel("各位置选择情况: " + " ".join([f"{p}:0" for p in positions]))
        content_layout.addWidget(self.count_label)

