        coldhot_layout.addWidget(QLabel("温号个数:"), 1, 0)
        self.ssq_warm_count = QSpinBox()
        self.ssq_warm_count.setRange(0, 33)
        coldhot_layout.addWidget(self.ssq_warm_count, 1, 1)
        coldhot_layout.addWidget(QLabel("冷号个数:"), 2, 0)
        self.ssq_cold_count = QSpinBox()
        self.ssq_cold_count.setRange(0, 33)
        coldhot_layout.addWidget(self.ssq_cold_count, 2, 1)
        layout.addWidget(self.ssq_coldhot_widget)
        self.ssq_coldhot_widget.hide()

        # 和值范围
        sum_layout = QHBoxLayout()
        sum_layout.addWidget(QLabel("和值范围:"))
        self.ssq_sum_min = QSpinBox()
        self.ssq_sum_min.setRange(21, 183)
        self.ssq_sum_min.setValue(80)
        sum_layout.addWidget(self.ssq_sum_min)
        sum_layout.addWidget(QLabel("-"))
        self.ssq_sum_max = QSpinBox()
        self.ssq_sum_max.setRange(21, 183)
