    def _generate_ssq_line(self, method: str, red_interval=None, blue_interval=None,
                            tail_checkboxes=None, hot=0, warm=0, cold=0,
                            sum_min=0, sum_max=9999) -> str:
        """生成单注双色球号码字符串（套餐票/综合投注复用）。"""
        def _parse_iv(s):
            a, b = s.split('-'); return int(a), int(b)

        if method == "区间选号" and red_interval and blue_interval:
            ra, rb = _parse_iv(red_interval)
            ba, bb = _parse_iv(blue_interval)
            red  = sorted(random.sample(range(ra, rb + 1), 6))
            blue = random.randint(ba, bb)
        elif method == "尾号选号" and tail_checkboxes is not None:
            tails = [t for t, cb in enumerate(tail_checkboxes) if cb.isChecked()] or list(range(10))
            rp = [x for x in range(1, 34) if x % 10 in tails]
            bp = [x for x in range(1, 17) if x % 10 in tails]
            red  = sorted(random.sample(rp, 6)) if len(rp) >= 6 else self.pick_numbers_by_coldhot("双色球", "red", 6)
            blue = random.choice(bp) if bp else random.randint(1, 16)
        elif method == "冷热号选号":
            total = hot + warm + cold or 1
            ratios = {'hot': hot / total, 'warm': warm / total, 'cold': cold / total}
            red  = self.pick_numbers_by_coldhot("双色球", "red",  6, ratios=ratios)
            blue = self.pick_numbers_by_coldhot("双色球", "blue", 1, ratios=ratios)[0]
        else:
            red  = self.pick_numbers_by_coldhot("双色球", "red",  6)
            blue = self.pick_numbers_by_coldhot("双色球", "blue", 1)[0]

        if not (sum_min <= sum(red) + blue <= sum_max) and method == "随机":
            red  = self.pick_numbers_by_coldhot("双色球", "red",  6)
            blue = self.pick_numbers_by_coldhot("双色球", "blue", 1)[0]

        return f"红球: {', '.join(map(str, red))} 蓝球: {blue}"


    def _generate_dlt_line(self, method: str, front_interval=None, back_interval=None,
                            tail_checkboxes=None, hot=0, warm=0, cold=0,
                            sum_min=0, sum_max=9999) -> str:
        """生成单注大乐透号码字符串，供多处复用（缩水对话框/套餐票/综合投注）。"""
        def _parse_iv(s):
            a, b = s.split('-')
            return int(a), int(b)

        if method == "区间选号" and front_interval and back_interval:
            fa, fb = _parse_iv(front_interval)
            ba, bb = _parse_iv(back_interval)
            front = sorted(random.sample(range(fa, fb + 1), 5))
            back  = sorted(random.sample(range(ba, bb + 1), 2))
        elif method == "尾号选号" and tail_checkboxes is not None:
            selected_tails = [t for t, cb in enumerate(tail_checkboxes) if cb.isChecked()] or list(range(10))
            fp = [x for x in range(1, 36) if x % 10 in selected_tails]
            bp = [x for x in range(1, 13) if x % 10 in selected_tails]
            front = sorted(random.sample(fp, 5)) if len(fp) >= 5 else self.parent.pick_numbers_by_coldhot("大乐透", "front", 5)
            back  = sorted(random.sample(bp, 2)) if len(bp) >= 2 else self.parent.pick_numbers_by_coldhot("大乐透", "back", 2)
        elif method == "冷热号选号":
            total = hot + warm + cold or 1
            ratios = {'hot': hot / total, 'warm': warm / total, 'cold': cold / total}
            front = self.parent.pick_numbers_by_coldhot("大乐透", "front", 5, ratios=ratios)
            back  = self.parent.pick_numbers_by_coldhot("大乐透", "back",  2, ratios=ratios)
        else:  # 随机
            front = self.parent.pick_numbers_by_coldhot("大乐透", "front", 5)
            back  = self.parent.pick_numbers_by_coldhot("大乐透", "back",  2)

        # 和值过滤：超出范围时简单重选一次（随机模式）
        if not (sum_min <= sum(front) + sum(back) <= sum_max) and method == "随机":
            front = self.parent.pick_numbers_by_coldhot("大乐透", "front", 5)
            back  = self.parent.pick_numbers_by_coldhot("大乐透", "back",  2)

        return f"前区: {', '.join(map(str, front))} 后区: {', '.join(map(str, back))}"

    def generate_dlt_numbers(self, method, bet_type, count):
        """生成大乐透号码，复用 parent._generate_dlt_line 避免重复逻辑。"""
        return [
            self._generate_dlt_line(
                method,
                front_interval=self.dlt_front_interval.currentText() if method == "区间选号" else None,
                back_interval=self.dlt_back_interval.currentText()   if method == "区间选号" else None,
                tail_checkboxes=self.dlt_tail_checkboxes             if method == "尾号选号" else None,
                hot=self.dlt_hot_count.value()  if method == "冷热号选号" else 0,
                warm=self.dlt_warm_count.value() if method == "冷热号选号" else 0,
                cold=self.dlt_cold_count.value() if method == "冷热号选号" else 0,
                sum_min=self.dlt_sum_min.value(),
                sum_max=self.dlt_sum_max.value(),
            )
            for _ in range(count)
        ]

