        self.is_positional = cfg.get("positional", False)
        self.pos_count = cfg.get("pos_count", self.main_need)
        self.pos_ranges = cfg.get("pos_ranges", [(0, self.main_max)] * self.main_need)
        self._combos: list = []
        self._last_draw_nums: list = []
        sc = QApplication.primaryScreen().availableGeometry()
        self.resize(min(680, int(sc.width()*0.97)), min(900, int(sc.height()*0.95)))
