    # ─── 生成算法 ─────────────────────────────────────────────
    def _kl8_set_play(self, n: int):
        """快乐8切换玩法（选一~选十）：更新每注主号码数及复式/胆拖可选范围，并重新生成。"""
        n = max(1, min(10, int(n)))
        self.main_need = n
        # 复式：号码池下限 = 选号数+1，上限 = 80
        if hasattr(self, "_complex_pool") and self._complex_pool is not None:
            self._complex_pool.blockSignals(True)
            lo = min(n + 1, self.main_max)
            self._complex_pool.setRange(lo, self.main_max)
            self._complex_pool.setValue(min(n + 2, self.main_max))
            self._complex_pool.setToolTip(f"主区可选 {lo}~{self.main_max} 个（最多全选）")
            self._complex_pool.blockSignals(False)
        # 胆拖：选一/选二号码太少无法胆拖，禁用；选三及以上启用
        if hasattr(self, "_dan_count") and self._dan_count is not None:
            can_dantuo = n >= 3
            self._dan_count.setEnabled(can_dantuo)
            self._tuo_count.setEnabled(can_dantuo)
            if can_dantuo:
                self._dan_count.blockSignals(True); self._tuo_count.blockSignals(True)
                self._dan_count.setRange(1, n - 1)
                if self._dan_count.value() > n - 1:
                    self._dan_count.setValue(1)
                tmin = n - self._dan_count.value() + 1
                self._tuo_count.setRange(tmin, min(self.main_max, 20))
                if self._tuo_count.value() < tmin:
                    self._tuo_count.setValue(tmin)
                self._dan_count.blockSignals(False); self._tuo_count.blockSignals(False)
        # 按当前票型重新生成
        try:
            self._generate_by_type(getattr(self, "_current_ticket_type", "单式"))
        except Exception as e:
            logger.error(f"快乐8玩法切换重新生成失败: {e}")

    def _generate(self):
        """默认生成（单式，使用单式tab参数）"""
        self._generate_by_type("单式")

    def _game_labels(self):
        """按玩法返回号码区标签，使套餐/胆拖显示与官方一致。"""
        if self.game_type == "双色球":
            return dict(main="红球", sub="蓝球", dan="胆码", tuo="拖码", dsub="蓝",
                        cplx=lambda mn, sn, b: f"{mn}红+{sn}蓝复式→{b}注")
        if self.game_type == "大乐透":
            return dict(main="前区", sub="后区", dan="前胆", tuo="前拖", dsub="后",
                        cplx=lambda mn, sn, b: f"{mn}+{sn}复式→{b}注")
        return dict(main="主区", sub="副区", dan="胆码", tuo="拖码", dsub="副",
                    cplx=lambda mn, sn, b: f"{mn}+{sn}复式→{b}注")

    def _unit_price(self):
        """每注单价：大乐透追加3元/不追加2元；其余玩法用配置基础单价。"""
        if self.game_type == "大乐透":
            add = getattr(self, "_dlt_additional", None)
            return 3.0 if (add is not None and add.isChecked()) else 2.0
        return self.price

    def _expand_ticket(self, t):
        """惰性展开一张原生票据为 (main,sub) 单注（生成器，避免全选复式时百万级一次性展开卡死）。"""
        import itertools
        kind = t.get("kind")
        if kind == "单式":
            yield (list(t["main"]), list(t.get("sub", [])))
            return
        if kind == "复式":
            mains = itertools.combinations(sorted(t["main"]), t["mneed"])
            if self.has_sub and t.get("sneed", 0) > 0 and t.get("sub"):
                sub_list = list(itertools.combinations(sorted(t["sub"]), t["sneed"])) or [()]
                for mc in mains:
                    for sc in sub_list:
                        yield (list(mc), list(sc))
            else:
                for mc in mains:
                    yield (list(mc), [])
            return
        if kind == "胆拖":
            dan = sorted(t["dan"]); tuo = sorted(t["tuo"])
            need = self.main_need - len(dan)
            for pick in itertools.combinations(tuo, max(0, need)):
                main = sorted(dan + list(pick))
                if self.has_sub:
                    dsub = sorted(t.get("dsub", [])); tsub = sorted(t.get("tsub", []))
                    if tsub:
                        sneed = self.sub_need - len(dsub)
                        for ps in itertools.combinations(tsub, max(0, sneed)):
                            yield (main, sorted(dsub + list(ps)))
                    else:
                        yield (main, sorted(t.get("sub", dsub)))
                else:
                    yield (main, [])
            return
        return

    def _ticket_bets(self, t):
        from math import comb as _comb
        kind = t.get("kind")
        if kind == "单式":
            return 1
        if kind == "复式":
            b = _comb(len(t["main"]), t["mneed"])
            if self.has_sub and t.get("sneed", 0) > 0 and t.get("sub"):
                b *= _comb(len(t["sub"]), t["sneed"])
            return b
        if kind == "胆拖":
            need = self.main_need - len(t["dan"])
            b = _comb(len(t["tuo"]), max(0, need)) if need >= 0 else 0
            if self.has_sub and t.get("tsub"):
                sneed = self.sub_need - len(t.get("dsub", []))
                b *= _comb(len(t["tsub"]), max(0, sneed))
            return b
        return sum(1 for _ in self._expand_ticket(t))

    def _fmt_nums(self, nums):
        if self.is_positional:
            return ", ".join(str(n) for n in nums)
        return ", ".join(str(int(n)) for n in nums)

    def _zbt_tag(self, nums):
        """按上期开奖计算这组号码的 重号/边号/跳号 个数，返回如 ' [重2 边1 跳1]'。"""
        last = set(getattr(self, "_last_draw_nums", []) or [])
        if not last or not nums:
            return ""
        chong = sum(1 for x in nums if x in last)
        bian  = sum(1 for x in nums if x not in last and any(abs(x-l)==1 for l in last))
        tiao  = sum(1 for x in nums if x not in last and not any(abs(x-l)==1 for l in last)
                    and any(abs(x-l)==2 for l in last))
        parts = []
        if chong: parts.append(f"重{chong}")
        if bian:  parts.append(f"边{bian}")
        if tiao:  parts.append(f"跳{tiao}")
        return ("  [" + " ".join(parts) + "]") if parts else "  [新号]"

    def _ticket_main_nums(self, t):
        """取票据用于重边跳分析的主区号码集合。"""
        k = t.get("kind")
        if k == "胆拖":
            return sorted(list(t.get("dan", [])) + list(t.get("tuo", [])))
        return sorted(t.get("main", []))

    def _fmt_ticket_line(self, t, idx, annotate=True):
        """把原生票据格式化为官方样式的一行文字。annotate=True 时在号码后追加重/边/跳标注。"""
        L = self._game_labels()
        kind = t.get("kind")
        tag = self._zbt_tag(self._ticket_main_nums(t)) if annotate else ""
        if kind == "单式":
            head = f"第{idx}注（单式 {self.main_need}+{self.sub_need}）" if self.has_sub \
                   else f"第{idx}注（单式）"
            if self.has_sub:
                return f"  {head}: {L['main']}[{self._fmt_nums(t['main'])}] {L['sub']}[{self._fmt_nums(t.get('sub',[]))}]{tag}"
            return f"  {head}: {L['main']}[{self._fmt_nums(t['main'])}]{tag}"
        if kind == "复式":
            bets = self._ticket_bets(t)
            mn = len(t["main"]); sn = len(t.get("sub", []))
            if self.has_sub and sn:
                ct = L["cplx"](mn, sn, bets)
                return f"  第{idx}组（{ct}）: {L['main']}[{self._fmt_nums(t['main'])}] {L['sub']}[{self._fmt_nums(t['sub'])}]{tag}"
            return f"  第{idx}组（{mn}复式→{bets}注）: {L['main']}[{self._fmt_nums(t['main'])}]{tag}"
        if kind == "胆拖":
            bets = self._ticket_bets(t)
            if self.has_sub:
                sub_part = ""
                tsub = t.get("tsub") or t.get("sub") or []
                if tsub:
                    cplx = "" if len(tsub) <= self.sub_need else f"复式{len(tsub)}选{self.sub_need}"
                    sub_part = f" {L['dsub']}:{self._fmt_nums(sorted(tsub))}{('（'+cplx+'）') if cplx else ''}"
                return (f"── 第{idx}份 {L['dan']}:{self._fmt_nums(t['dan'])} "
                        f"{L['tuo']}:{self._fmt_nums(t['tuo'])}{sub_part} ({bets}注){tag}")
            return (f"── 第{idx}份 {L['dan']}:{self._fmt_nums(t['dan'])} "
                    f"{L['tuo']}:{self._fmt_nums(t['tuo'])} ({bets}注){tag}")
        return f"  第{idx}注: ?"

    # ─── 生成算法 ─────────────────────────────────────────────
    def _generate_by_type(self, ticket_type: str):
        """根据票型分发生成逻辑，构建原生票据 _render_groups + 展开 _combos。"""
        self._current_ticket_type = ticket_type
        try:
            recs = sorted(
                self.app.history_data.get(self.game_type, []),
                key=lambda x: str(x.get("期号","")))
            self._last_draw_nums = self._get_last_draw_flat(recs)
            self._update_last_draw_label(recs)
            groups = []   # [{"title":str, "tickets":[...]}]

            if ticket_type == "单式":
                count = self._single_count.value()
                mode  = self._single_model.currentText()
                combos = self._run_predict(recs, count, mode)
                tickets = [{"kind":"单式","main":m,"sub":s} for m, s in combos]
                groups.append({"title":"", "tickets":tickets})
                self._ticket_type_lbl.setText(f"当前：单式预测  共{count}注")
                self._ticket_type_lbl.setStyleSheet(
                    "font-size:11px;font-weight:bold;color:white;padding:3px 8px;"
                    "background:#1A5276;border-radius:3px;")

            elif ticket_type == "复式":
                mode = self._complex_model.currentText()
                pool_n = self._complex_pool.value()
                sub_n  = self._complex_sub_pool.value() if self._complex_sub_pool else 0
                copies = self._complex_copies.value() if hasattr(self, "_complex_copies") else 1
                tickets = [self._make_complex_ticket(recs, mode, pool_n, sub_n)
                           for _ in range(copies)]
                groups.append({"title":"", "tickets":tickets})
                tot = sum(self._ticket_bets(t) for t in tickets)
                self._ticket_type_lbl.setText(
                    f"当前：复式预测  主区{pool_n}个 × {copies}组 →{tot}注")
                self._ticket_type_lbl.setStyleSheet(
                    "font-size:11px;font-weight:bold;color:white;padding:3px 8px;"
                    "background:#8E44AD;border-radius:3px;")

            elif ticket_type == "胆拖":
                mode    = self._dantuo_model.currentText()
                dan_n   = self._dan_count.value()
                tuo_n   = self._tuo_count.value()
                copies  = self._dantuo_copies.value() if hasattr(self, "_dantuo_copies") else 1
                tsub_n  = self._dantuo_tsub.value() if getattr(self, "_dantuo_tsub", None) else None
                tickets = [self._make_dantuo_ticket(recs, mode, dan_n, tuo_n, tsub_n)
                           for _ in range(copies)]
                tot = sum(self._ticket_bets(t) for t in tickets)
                sub_tag = ""
                if tsub_n and tsub_n > self.sub_need:
                    _w = {"双色球":"蓝","大乐透":"后"}.get(self.game_type, "副")
                    sub_tag = f"+{tsub_n}{_w}复式"
                title = f"胆拖票 {dan_n}胆{tuo_n}拖{sub_tag} × {copies}份  共{tot}注  ¥{tot*self._unit_price():.0f}"
                groups.append({"title":title, "tickets":tickets, "dantuo":True})
                self._ticket_type_lbl.setText(
                    f"当前：胆拖预测  {dan_n}胆+{tuo_n}拖{sub_tag} × {copies}份 →{tot}注")
                self._ticket_type_lbl.setStyleSheet(
                    "font-size:11px;font-weight:bold;color:white;padding:3px 8px;"
                    "background:#E67E22;border-radius:3px;")

            elif ticket_type == "套餐":
                mode = self._pkg_model.currentText()
                pkg  = self._pkg_combo.currentText()
                copies = self._pkg_copies.value() if hasattr(self, "_pkg_copies") else 1
                groups = self._generate_package(recs, mode, pkg, copies)
                tot = sum(self._ticket_bets(t) for g in groups for t in g["tickets"])
                self._ticket_type_lbl.setText(
                    f"当前：套餐预测 [{pkg[:8]}]×{copies}张  共{tot}注")
                self._ticket_type_lbl.setStyleSheet(
                    "font-size:11px;font-weight:bold;color:white;padding:3px 8px;"
                    "background:#27AE60;border-radius:3px;")

            self._render_groups = groups
            # 真实总注数用组合公式秒算（避免全选时百万级展开卡死）
            self._total_bets = sum(self._ticket_bets(t)
                                   for g in groups for t in g["tickets"])
            # _combos 仅用于网格高亮/下游分析，按安全上限懒展开（最多 EXPAND_CAP 注）
            EXPAND_CAP = 3000
            self._combos = []
            for g in groups:
                for t in g["tickets"]:
                    if len(self._combos) >= EXPAND_CAP:
                        break
                    for c in self._expand_ticket(t):
                        self._combos.append(c)
                        if len(self._combos) >= EXPAND_CAP:
                            break
                if len(self._combos) >= EXPAND_CAP:
                    break

            self._refresh_grid()
            self._refresh_text()
        except Exception as e:
            import traceback; traceback.print_exc()
            self._result_te.setPlainText(f"生成失败: {e}")

    def _run_predict(self, recs, count, mode):
        """统一调用预测核心（单式基础）"""
        if self.is_positional:
            return self._positional_predict(recs, count, mode)
        elif "高尔顿" in mode:
            return self._galton_predict(recs, count)
        else:
            return self._nine_grid_predict(recs, count, mode)

    def _pick_main_pool(self, recs, mode, pool_n):
        """按模型选出 pool_n 个主区号码（频次优先，不足随机补足）。"""
        import random
        from collections import Counter
        single = self._run_predict(recs, max(30, pool_n*3), mode)
        freq = Counter()
        for main, _sub in single:
            for n in main: freq[n] += 1
        pool = [n for n, _ in freq.most_common(pool_n)]
        if len(pool) < pool_n:
            lo = 0 if self.is_positional else 1
            extra = [n for n in range(lo, self.main_max+1) if n not in pool]
            random.shuffle(extra); pool += extra[:pool_n-len(pool)]
        return sorted(pool[:pool_n]), single

    def _pick_sub_pool(self, single, sub_n):
        import random
        from collections import Counter
        sfreq = Counter()
        for _m, s in single:
            for n in s: sfreq[n] += 1
        pool = [n for n, _ in sfreq.most_common(sub_n)]
        if len(pool) < sub_n:
            extra = [n for n in range(1, self.sub_max+1) if n not in pool]
            random.shuffle(extra); pool += extra[:sub_n-len(pool)]
        return sorted(pool[:sub_n])

    def _make_complex_ticket(self, recs, mode, pool_n, sub_pool_n=0):
        """生成一张复式票据（原生形态）。"""
        main_pool, single = self._pick_main_pool(recs, mode, pool_n)
        t = {"kind":"复式", "main":main_pool, "mneed":self.main_need,
             "sub":[], "sneed":0}
        if self.has_sub:
            sneed = self.sub_need
            spool_n = sub_pool_n if sub_pool_n and sub_pool_n >= sneed else sneed
            t["sub"] = self._pick_sub_pool(single, spool_n)
            t["sneed"] = sneed
        return t

    def _make_dantuo_ticket(self, recs, mode, dan_n, tuo_n, tsub_n=None):
        """生成一张胆拖票据（原生形态）。tsub_n 为副区(拖蓝/拖后)个数，>sub_need 即副区复式。"""
        import random
        from collections import Counter
        single = self._run_predict(recs, max(30, (dan_n+tuo_n)*3), mode)
        freq = Counter()
        for main, _sub in single:
            for n in main: freq[n] += 1
        ranked = [n for n, _ in freq.most_common()]
        dan = sorted(ranked[:dan_n])
        tuo = [n for n in ranked[dan_n:] if n not in dan][:tuo_n]
        lo = 0 if self.is_positional else 1
        extra = [n for n in range(lo, self.main_max+1) if n not in dan and n not in tuo]
        random.shuffle(extra)
        while len(tuo) < tuo_n and extra:
            tuo.append(extra.pop())
        tuo = sorted(tuo)
        t = {"kind":"胆拖", "dan":dan, "tuo":tuo}
        if self.has_sub:
            if tsub_n is None:
                tsub_n = self.sub_need
            tsub_n = max(self.sub_need, min(tsub_n, self.sub_max))
            sub_pool = self._pick_sub_pool(single, tsub_n)
            t["tsub"] = sub_pool          # 拖蓝/拖后池（副区复式时 > sub_need）
            t["dsub"] = []                # 暂不支持胆蓝，副区全为拖
            t["sub"]  = sub_pool          # 兼容显示
        return t

    def _generate_package(self, recs, mode, pkg_name, copies=1):
        """
        套餐预测：按套餐方案生成原生票据分组，可指定张数 copies。
        返回 groups = [{"title": 套餐头, "tickets":[原生票据...]}]，每张套餐一个分组。
        双色球/大乐透使用价格套餐定义，其余玩法用通用套餐。
        """
        from math import comb as _comb
        pkg_table = None
        if self.game_type == "双色球":
            pkg_table = SSQPackageDialog._SSQ_PACKAGES
        elif self.game_type == "大乐透":
            pkg_table = DLTPackageDialog._DLT_PACKAGES

        groups = []
        if pkg_table is not None and pkg_name in pkg_table:
            for ci in range(copies):
                tickets = []
                for bet_type, main_n, sub_n, n in pkg_table[pkg_name]:
                    if bet_type == "单式":
                        singles = self._run_predict(recs, n, mode)
                        for m, s in singles:
                            tickets.append({"kind":"单式","main":m,
                                            "sub":(s if self.has_sub else [])})
                    else:  # 复式
                        for _ in range(n):
                            tickets.append(self._make_complex_ticket(recs, mode, main_n, sub_n))
                bets = sum(self._ticket_bets(t) for t in tickets)
                amount = bets * self._unit_price()
                title = f"【{pkg_name}×第{ci+1}张】共{bets}注 ¥{amount:.0f}"
                groups.append({"title":title, "tickets":tickets})
            self._pkg_desc = f"{pkg_name}×{copies}张"
            return groups

        # ── 通用套餐（快乐8/3D/排列/七星彩等）──────────────────────
        for ci in range(copies):
            tickets = []
            if "经济套餐" in pkg_name:
                tickets = [{"kind":"单式","main":m,"sub":s}
                           for m, s in self._run_predict(recs, 5, mode)]
            elif "标准套餐" in pkg_name:
                tickets = [{"kind":"单式","main":m,"sub":s}
                           for m, s in self._run_predict(recs, 9, mode)]
            elif "进阶套餐" in pkg_name:
                tickets = [{"kind":"单式","main":m,"sub":s}
                           for m, s in self._run_predict(recs, 5, mode)]
                tickets.append(self._make_complex_ticket(recs, mode,
                              min(self.main_need+3, self.main_max)))
            elif "胆拖套餐" in pkg_name:
                tickets = [self._make_dantuo_ticket(recs, mode, 1,
                           min(self.main_need+3, self.main_max-1))]
            elif "全覆盖套餐" in pkg_name:
                tickets = [{"kind":"单式","main":m,"sub":s}
                           for m, s in self._run_predict(recs, 6, mode)]
                tickets.append(self._make_complex_ticket(recs, mode,
                              min(self.main_need+2, self.main_max)))
                tickets.append(self._make_dantuo_ticket(recs, mode, 1,
                              min(self.main_need+2, self.main_max-1)))
            elif "豪华套餐" in pkg_name:
                tickets = [{"kind":"单式","main":m,"sub":s}
                           for m, s in self._run_predict(recs, 20, mode)]
            else:
                tickets = [{"kind":"单式","main":m,"sub":s}
                           for m, s in self._run_predict(recs, 9, mode)]
            bets = sum(self._ticket_bets(t) for t in tickets)
            title = f"【{pkg_name}×第{ci+1}张】共{bets}注 ¥{bets*self._unit_price():.0f}"
            groups.append({"title":title, "tickets":tickets})
        self._pkg_desc = f"{pkg_name}×{copies}张"
        return groups

    def _compare_with_history(self):
        """把当前生成的号码与最近历史开奖比对，相同号码标红。
        关键：主区(红/前区)只与开奖主区比，副区(蓝/后区)只与开奖副区比，绝不混算。
        位置型(3D/排列三/排列五/七星彩)按"位置+数字"比对。"""
        recs = sorted(self.app.history_data.get(self.game_type, []),
                      key=lambda x: str(x.get("期号", "")), reverse=True)
        if not recs:
            self._result_te.setHtml("<p style='color:#E67E22'>⚠ 无历史开奖数据，请先在首页【🔁 全量更新到最新】</p>")
            return
        tickets = list(self._iter_render_tickets()) if hasattr(self, "_iter_render_tickets") else []
        if not tickets:
            self._result_te.setHtml("<p style='color:#E67E22'>⚠ 请先生成号码，再点历史比对</p>")
            return
        N = min(30, len(recs))
        use = recs[:N]

        def split_main_sub(nums):
            """按玩法把一期开奖号码拆成 (主区list, 副区list)。"""
            if self.game_type == "双色球":
                return nums[:6], nums[6:7]
            if self.game_type == "大乐透":
                return nums[:5], nums[5:7]
            if self.game_type == "七乐彩":
                return nums[:7], nums[7:8]
            # 快乐8 / 位置型：无副区
            return nums, []

        latest_nums = parse_draw_numbers(str(use[0].get("开奖号码", "")))
        latest_main, latest_sub = split_main_sub(latest_nums)
        latest_main_set, latest_sub_set = set(latest_main), set(latest_sub)

        # 历史集合（主区、副区分开）
        hist_main, hist_sub = set(), set()
        pos_hist = {}
        if self.is_positional:
            for r in use:
                ds = parse_draw_numbers(str(r.get("开奖号码", "")))
                for pi, d in enumerate(ds):
                    pos_hist.setdefault(pi, set()).add(d)
        else:
            for r in use:
                m, s = split_main_sub(parse_draw_numbers(str(r.get("开奖号码", ""))))
                hist_main |= set(m); hist_sub |= set(s)

        def color_main(n, pos=None):
            if self.is_positional:
                hit_latest = (pos is not None and pos < len(latest_nums) and n == latest_nums[pos])
                hit_hist = (pos is not None and n in pos_hist.get(pos, set()))
            else:
                hit_latest = n in latest_main_set
                hit_hist = n in hist_main
            txt = "%02d" % int(n)
            if hit_latest:
                return "<span style='color:#E74C3C;font-weight:bold'>" + txt + "</span>"
            if hit_hist:
                return "<span style='color:#E67E22'>" + txt + "</span>"
            return txt

        def color_sub(n):
            hit_latest = n in latest_sub_set
            hit_hist = n in hist_sub
            txt = "%02d" % int(n)
            if hit_latest:
                return "<span style='color:#3498DB;font-weight:bold'>" + txt + "</span>"
            if hit_hist:
                return "<span style='color:#E67E22'>" + txt + "</span>"
            return txt

        header = "<b>📊 " + self.game_type + " 历史比对（最近" + str(N) + "期）</b>"
        latest_line = "最近一期 第" + str(use[0].get("期号", "")) + " 期: " + str(use[0].get("开奖号码", ""))
        legend = ("<span style='color:#E74C3C;font-weight:bold'>红=主区命中最近期</span>　"
                  "<span style='color:#3498DB;font-weight:bold'>蓝=副区命中最近期</span>　"
                  "<span style='color:#E67E22'>橙=最近%d期出现过</span>　黑=未出现<hr>" % N)
        lines = [header, latest_line, legend]
        idx = 0
        for g, t in tickets:
            idx += 1
            kind = t.get("kind", "单式")
            if kind == "胆拖":
                main = sorted(list(t.get("dan", [])) + list(t.get("tuo", [])))
            else:
                main = list(t.get("main", []))
            if self.is_positional:
                colored = " ".join(color_main(n, pi) for pi, n in enumerate(main))
            else:
                colored = " ".join(color_main(n) for n in main)
            sub = t.get("sub", []) or t.get("tsub", [])
            sub_str = ""
            if self.has_sub and sub:
                sub_str = " <b>+</b> " + " ".join(color_sub(n) for n in sub)
            cnt_main = sum(1 for n in main if n in latest_main_set)
            cnt_sub = sum(1 for n in sub if n in latest_sub_set) if sub else 0
            tag = "命中最近期 主区%d个" % cnt_main
            if self.has_sub:
                tag += " 副区%d个" % cnt_sub
            lines.append("第%02d注: %s%s　<small>(%s)</small>" % (idx, colored, sub_str, tag))
        self._result_te.setHtml("<br>".join(lines))

    def _get_last_draw_flat(self, recs):
        """返回上期开奖号码的扁平列表（用于比对）"""
        if not recs:
            return []
        last_rec = recs[-1]
        raw = last_rec.get("开奖号码", "")
        nums = parse_draw_numbers(raw)
        # 七星彩：前6位0-9，第7位0-14，直接返回所有
        # 其他位置型：直接返回
        # 非位置型：正常返回
        return nums

    def _update_last_draw_label(self, recs):
        """更新上期开奖号码展示标签"""
        if not recs:
            self._last_draw_lbl.setText("上期开奖: 暂无数据")
            return
        last_rec = recs[-1]
        issue = last_rec.get("期号", "未知")
        raw = last_rec.get("开奖号码", "")
        nums = parse_draw_numbers(raw)
        if self.is_positional:
            if self.game_type == "七星彩" and len(nums) >= 7:
                disp = " ".join(str(n) for n in nums[:6]) + " | " + str(nums[6])
            else:
                disp = " ".join(str(n) for n in nums)
        elif self.game_type in ("快乐8",):
            disp = "  ".join(f"{n:02d}" for n in nums[:20])
        elif self.game_type == "双色球" and len(nums) >= 7:
            disp = " ".join(f"{n:02d}" for n in nums[:6]) + "  +  " + f"{nums[6]:02d}"
        elif self.game_type == "大乐透" and len(nums) >= 7:
            disp = " ".join(f"{n:02d}" for n in nums[:5]) + "  +  " + " ".join(f"{n:02d}" for n in nums[5:7])
        else:
            disp = " ".join(f"{n:02d}" for n in nums)
        self._last_draw_lbl.setText(f"📌 上期开奖 [第{issue}期]:  {disp}")

    def _nine_grid_predict(self, recs, count, mode):
        """九宫格矩阵：将号码空间分为3×3区域，按权重跨区采样"""
        from collections import Counter
        import random
        n = self.main_max; k = self.main_need
        recent = recs[-50:] if len(recs) >= 10 else recs

        freq = Counter()
        last_seen = {}
        for i, rec in enumerate(recent):
            for x in [v for v in parse_draw_numbers(rec.get("开奖号码","")) if 1 <= v <= n]:
                freq[x] += 1; last_seen[x] = i
        nr = len(recent)
        omission = {x: nr - last_seen.get(x,-1) - 1 for x in range(1, n+1)}
        last_main = [v for v in parse_draw_numbers(recs[-1].get("开奖号码","")) if v <= n] if recs else []

        # 权重函数
        def weight(x):
            f = freq.get(x,0); o = omission.get(x,0)
            if "高频"  in mode: return f * 3 + 1
            if "低频"  in mode: return (nr - f) * 3 + 1
            if "遗漏"  in mode: return o * 3 + 1
            if "重号"  in mode: return 5 if x in last_main else f + 1
            if "边号"  in mode: return 4 if x in (1,2,n-1,n) else f + 1
            return f * 2 + o + 1  # 均衡

        # 九宫格区域划分
        seg = max(1, n // 9)
        zones = []
        for i in range(9):
            lo = i * seg + 1; hi = (i+1)*seg if i < 8 else n
            zones.append(list(range(lo, hi+1)))

        combos = []; seen = set()
        for _ in range(count * 10):
            chosen = []; order = list(range(9)); random.shuffle(order)
            for zi in order:
                if len(chosen) >= k: break
                pool = [x for x in zones[zi] if x not in chosen]
                if not pool: continue
                ws = [weight(x) for x in pool]; tw = sum(ws)
                r = random.random() * tw; cum = 0
                for x, w in zip(pool, ws):
                    cum += w
                    if r <= cum: chosen.append(x); break
                else: chosen.append(pool[0])
            # 补足
            remaining = [x for x in range(1,n+1) if x not in chosen]
            random.shuffle(remaining)
            while len(chosen) < k and remaining: chosen.append(remaining.pop(0))
            main = tuple(sorted(chosen[:k]))
            if main not in seen:
                seen.add(main)
                sub = tuple(sorted(random.sample(range(1,self.sub_max+1), self.sub_need))) if self.has_sub and self.sub_max > 0 else ()
                combos.append((list(main), list(sub)))
            if len(combos) >= count: break
        # 不够就随机补
        while len(combos) < count:
            m = tuple(sorted(random.sample(range(1,n+1), k)))
            if m not in seen:
                seen.add(m)
                s = tuple(sorted(random.sample(range(1,self.sub_max+1), self.sub_need))) if self.has_sub and self.sub_max > 0 else ()
                combos.append((list(m), list(s)))
        return combos[:count]

    def _positional_predict(self, recs, count, mode):
        """
        位置型彩票（3D/排列三/排列五/七星彩）预测。
        每个位置独立从0-9（七星彩第7位0-14）采样，支持重复数字。
        3D/排列三/排列五: 3或5位，每位0-9
        七星彩: 6位0-9 + 第7位0-14
        """
        import random
        from collections import Counter
        recent = recs[-50:] if len(recs) >= 10 else recs
        nr = len(recent)

        def parse_positional(rec_str, pos_count, pos_ranges):
            """解析位置型开奖号码为各位数字列表"""
            nums = []
            s = str(rec_str).strip().replace("+", " ").replace(",", " ")
            import re as _re
            parts = [p for p in _re.split(r"\s+", s) if p.strip()]
            for p in parts:
                try:
                    nums.append(int(p))
                except (ValueError, TypeError):
                    pass
            # 只取前pos_count个，确保每位在范围内
            result = []
            for i in range(min(len(nums), pos_count)):
                lo, hi = pos_ranges[i]
                v = nums[i]
                if lo <= v <= hi:
                    result.append(v)
            return result if len(result) == pos_count else []

        # 每位统计频率和遗漏
        pos_freq = [{d: 0 for d in range(r[0], r[1]+1)} for r in self.pos_ranges]
        pos_last = [{} for _ in self.pos_ranges]

        for i, rec in enumerate(recent):
            digits = parse_positional(rec.get("开奖号码", ""), self.pos_count, self.pos_ranges)
            if len(digits) == self.pos_count:
                for pi, d in enumerate(digits):
                    pos_freq[pi][d] = pos_freq[pi].get(d, 0) + 1
                    pos_last[pi][d] = i

        pos_omit = []
        for pi, (lo, hi) in enumerate(self.pos_ranges):
            omit = {d: nr - pos_last[pi].get(d, -1) - 1 for d in range(lo, hi+1)}
            pos_omit.append(omit)

        # 每位权重函数
        def pos_weight(pi, d):
            f = pos_freq[pi].get(d, 0)
            o = pos_omit[pi].get(d, 0)
            if "高频" in mode:  return f * 3 + 1
            if "低频" in mode:  return max(1, (nr - f) * 3 + 1)
            if "遗漏" in mode:  return o * 3 + 1
            return f * 2 + o + 1  # 均衡/其他

        combos = []
        seen = set()
        for _ in range(count * 15):
            if len(combos) >= count:
                break
            chosen = []
            for pi, (lo, hi) in enumerate(self.pos_ranges):
                pool = list(range(lo, hi+1))
                ws = [pos_weight(pi, d) for d in pool]
                tw = sum(ws)
                r = random.random() * tw; cum = 0
                picked = pool[-1]
                for d, w in zip(pool, ws):
                    cum += w
                    if r <= cum:
                        picked = d; break
                chosen.append(picked)
            key = tuple(chosen)
            if key not in seen:
                seen.add(key)
                combos.append((list(chosen), []))
        # 补足
        while len(combos) < count:
            chosen = [random.randint(lo, hi) for lo, hi in self.pos_ranges]
            key = tuple(chosen)
            if key not in seen:
                seen.add(key)
                combos.append((list(chosen), []))
        return combos[:count]

    def _galton_predict(self, recs, count):
        """
        高尔顿板机器学习模型
        原理：每期开奖号码视为钉板路径，历史出现频次形成正态(高斯)分布。
        模型用近期数据 + 衰减权重 + 遗漏修正，拟合每个号码的"落球概率"，
        再用蒙特卡罗采样生成多注预测。
        """
        import random, math
        from collections import Counter
        # 位置型彩票（3D/排列三/排列五/七星彩）必须按"每位独立取数、可重复"生成，
        # 不能套用选号型逻辑，否则号码格式全错。
        if getattr(self, "is_positional", False):
            return self._positional_predict(recs, count, "均衡(推荐)")
        n = self.main_max; k = self.main_need
        recent = recs[-80:] if len(recs) >= 20 else recs
        if not recent:
            return self._nine_grid_predict(recs, count, "均衡(推荐)")

        # ── 1. 时间衰减频率 ──────────────────────────────────
        nr = len(recent)
        decay_freq = {x: 0.0 for x in range(1, n+1)}
        last_seen  = {}
        for i, rec in enumerate(recent):
            # 越新权重越高
            w_time = math.exp(0.04 * (i - nr + 1))  # 近期衰减因子
            for x in [v for v in parse_draw_numbers(rec.get("开奖号码","")) if 1 <= v <= n]:
                decay_freq[x] += w_time
                last_seen[x] = i
        omission = {x: nr - last_seen.get(x,-1) - 1 for x in range(1, n+1)}

        # ── 2. 高斯平滑（高尔顿板扩散）──────────────────────
        sigma = max(2, n // 15)  # 扩散宽度
        smoothed = {x: 0.0 for x in range(1, n+1)}
        for cx in range(1, n+1):
            for rx in range(1, n+1):
                dist = abs(rx - cx)
                smoothed[cx] += decay_freq[rx] * math.exp(-dist**2 / (2*sigma**2))

        # ── 3. 遗漏修正 ──────────────────────────────────────
        max_om = max(omission.values()) or 1
        for x in range(1, n+1):
            # 高遗漏号码获得额外权重（遗漏越久越可能出现）
            om_boost = 1.0 + 0.5 * (omission[x] / max_om)
            smoothed[x] *= om_boost

        # ── 4. 归一化为概率 ──────────────────────────────────
        total = sum(smoothed.values()) or 1
        probs = {x: smoothed[x]/total for x in range(1, n+1)}

        # ── 5. 蒙特卡罗采样 ─────────────────────────────────
        combos = []; seen = set()
        attempts = 0
        while len(combos) < count and attempts < count * 20:
            attempts += 1
            chosen = []
            pool = list(range(1, n+1))
            pool_probs = [probs[x] for x in pool]
            while len(chosen) < k and pool:
                tw = sum(pool_probs); r = random.random() * tw; cum = 0
                for j, (x, p) in enumerate(zip(pool, pool_probs)):
                    cum += p
                    if r <= cum:
                        chosen.append(x)
                        pool.pop(j); pool_probs.pop(j)
                        break
                else:
                    chosen.append(pool[0]); pool.pop(0); pool_probs.pop(0)
            main = tuple(sorted(chosen[:k]))
            if main not in seen:
                seen.add(main)
                sub = tuple(sorted(random.sample(range(1, self.sub_max+1), self.sub_need))) if self.has_sub and self.sub_max > 0 else ()
                combos.append((list(main), list(sub)))
        while len(combos) < count:
            m = tuple(sorted(random.sample(range(1,n+1), k)))
            if m not in seen:
                seen.add(m)
                s = tuple(sorted(random.sample(range(1,self.sub_max+1), self.sub_need))) if self.has_sub and self.sub_max > 0 else ()
                combos.append((list(m), list(s)))
        return combos[:count]

    # ─── 刷新显示 ─────────────────────────────────────────────
    def _iter_render_tickets(self):
        """遍历所有分组的票据，产出 (group, ticket)。"""
        for g in getattr(self, "_render_groups", []):
            for t in g["tickets"]:
                yield g, t

    def _refresh_grid(self):
        # 清除旧内容
        while self._grid_layout.count():
            item = self._grid_layout.takeAt(0)
            if item.widget(): item.widget().deleteLater()
        last = set(self._last_draw_nums)
        cols = 3
        cell_idx = 0
        kind_color = {"单式":"#E74C3C", "复式":"#8E44AD", "胆拖":"#E67E22"}
        for g, t in self._iter_render_tickets():
            r, c = divmod(cell_idx, cols); cell_idx += 1
            cell = QFrame()
            cell.setStyleSheet(
                "background:#EBF5FB;border:1px solid #2980B9;border-radius:6px;padding:2px;")
            cl = QVBoxLayout(cell); cl.setSpacing(2); cl.setContentsMargins(3,3,3,3)
            kind = t.get("kind","单式")
            bets = self._ticket_bets(t)
            hdr = {"单式":f"第{cell_idx}注 单式",
                   "复式":f"第{cell_idx}组 复式→{bets}注",
                   "胆拖":f"第{cell_idx}份 胆拖→{bets}注"}.get(kind, f"第{cell_idx}")
            tl = QLabel(hdr)
            tl.setStyleSheet(f"font-weight:bold;font-size:10px;color:white;"
                             f"background:{kind_color.get(kind,'#1A5276')};"
                             f"border-radius:3px;padding:1px 4px;")
            tl.setAlignment(Qt.AlignCenter); cl.addWidget(tl)
            # 主区号码集合（胆拖=胆+拖；复式=池；单式=号码）
            if kind == "胆拖":
                mains = sorted(t["dan"]) ; tuos = sorted(t["tuo"])
                dan_set = set(t["dan"])
                display_main = mains + tuos
            else:
                display_main = sorted(t["main"]) if kind != "单式" else list(t["main"])
                dan_set = set()
            br = QHBoxLayout(); br.setSpacing(2); br.setAlignment(Qt.AlignCenter)
            br.setContentsMargins(0,0,0,0)
            wrap = QVBoxLayout(); wrap.setSpacing(2)
            cnt = 0
            cur = br
            for num in display_main:
                if self.is_positional:
                    lbl_txt = str(num)
                else:
                    lbl_txt = f"{num:02d}"
                if kind == "胆拖" and num in dan_set:
                    ball_color = "#C0392B"   # 胆码深红
                elif last and num in last:
                    ball_color = "#D4AC0D"
                elif last and any(abs(num - l) == 1 for l in last):
                    ball_color = "#E67E22"
                else:
                    ball_color = "#E74C3C"
                b = QLabel(lbl_txt)
                b.setFixedSize(_sc(24),_sc(24)); b.setAlignment(Qt.AlignCenter)
                b.setStyleSheet(
                    f"background:{ball_color};color:white;border-radius:12px;"
                    "font-weight:bold;font-size:9px;")
                cur.addWidget(b); cnt += 1
                if cnt % 8 == 0:
                    wrap.addLayout(cur)
                    cur = QHBoxLayout(); cur.setSpacing(2); cur.setAlignment(Qt.AlignCenter)
            wrap.addLayout(cur)
            cl.addLayout(wrap)
            # 副区
            sub_disp = []
            if self.has_sub:
                if kind == "胆拖":
                    sub_disp = t.get("tsub") or t.get("sub", [])
                else:
                    sub_disp = t.get("sub", [])
            if sub_disp:
                sr = QHBoxLayout(); sr.setSpacing(2); sr.setAlignment(Qt.AlignCenter)
                for num in sorted(sub_disp):
                    b = QLabel(f"{num:02d}")
                    b.setFixedSize(_sc(22),_sc(22)); b.setAlignment(Qt.AlignCenter)
                    b.setStyleSheet(
                        "background:#3498DB;color:white;border-radius:11px;"
                        "font-weight:bold;font-size:9px;")
                    sr.addWidget(b)
                cl.addLayout(sr)
            self._grid_layout.addWidget(cell, r, c)

    def _fmt_num(self, num, pos_idx=None):
        """格式化号码显示：位置型彩票直接显示单位数字，其他用两位"""
        if self.is_positional:
            return str(num)
        return f"{num:02d}"

    def _refresh_text(self):
        ticket_type = getattr(self, "_current_ticket_type", "单式")
        pkg_desc = getattr(self, "_pkg_desc", "")
        total_bets = getattr(self, "_total_bets", len(self._combos))
        label = {"单式":"单式预测","复式":"复式预测",
                 "胆拖":"胆拖预测","套餐":f"套餐预测 {pkg_desc}"}.get(ticket_type, ticket_type)
        lines = [
            f"=== {self.game_type} 九宫格/高尔顿【{label}】(共{total_bets}注) ===",
            f"生成时间: {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}",
        ]
        if self._last_draw_nums:
            if self.is_positional:
                ld = " ".join(str(n) for n in self._last_draw_nums)
            else:
                ld = " ".join(f"{n:02d}" for n in self._last_draw_nums)
            lines.append(f"上期开奖: {ld}")
        lines.append("")
        # 按原生票据分组输出（套餐/胆拖保持原生形态，复式不分解）
        for g in getattr(self, "_render_groups", []):
            if g.get("title"):
                lines.append(g["title"])
            idx = 0
            for t in g["tickets"]:
                idx += 1
                lines.append(self._fmt_ticket_line(t, idx))
            lines.append("")
        self._result_te.setPlainText("\n".join(lines))

    # ─── 操作按钮 ─────────────────────────────────────────────
    def _add_all_bet(self):
        target = self.app.get_default_target_issue(self.game_type)
        cnt = 0
        for g in getattr(self, "_render_groups", []):
            for t in g["tickets"]:
                # 记录用原生号码字符串（复式/胆拖整票保存一条）
                ns = self._ticket_record_str(t)
                bets = self._ticket_bets(t)
                self.app.add_betting_record(
                    self.game_type, f"九宫格-{t.get('kind','单式')}", ns,
                    bets, self._unit_price() * bets, target_issue=target,
                    additional=bool(getattr(self, "_dlt_additional", None) and self._dlt_additional.isChecked()))
                cnt += 1
        QMessageBox.information(self, "成功",
            f"已添加 {cnt} 张票（共{getattr(self,'_total_bets',len(self._combos))}注）到投注记录！")

    def _ticket_record_str(self, t):
        """把票据转为可读号码字符串（用于投注记录）。"""
        L = self._game_labels()
        kind = t.get("kind")
        if kind == "单式":
            ms = " ".join(self._fmt_num(n) for n in t["main"])
            if self.has_sub and t.get("sub"):
                return ms + " + " + " ".join(f"{n:02d}" for n in t["sub"])
            return ms
        if kind == "复式":
            ms = "[复式] " + " ".join(self._fmt_num(n) for n in sorted(t["main"]))
            if self.has_sub and t.get("sub"):
                ms += " + " + " ".join(f"{n:02d}" for n in sorted(t["sub"]))
            return ms
        if kind == "胆拖":
            s = f"[胆拖] {L['dan']}:" + " ".join(self._fmt_num(n) for n in sorted(t["dan"]))
            s += f" {L['tuo']}:" + " ".join(self._fmt_num(n) for n in sorted(t["tuo"]))
            tsub = t.get("tsub") or t.get("sub") or []
            if self.has_sub and tsub:
                s += " + " + " ".join(f"{n:02d}" for n in sorted(tsub))
            return s
        return ""

    def _compact_ticket(self, t):
        """紧凑复制格式：主区号码逗号分隔 | 副区号码逗号分隔；胆拖中胆码加 * 标记。"""
        def j(ns):
            return ",".join(str(n) for n in ns) if self.is_positional \
                   else ",".join(f"{int(n):02d}" for n in ns)
        k = t.get("kind")
        if k == "复式":
            main = j(sorted(t["main"]))
            if self.has_sub and t.get("sub"):
                return f"{main}|{j(sorted(t['sub']))}"
            return main
        if k == "胆拖":
            L = self._game_labels()
            sub_word = L.get("dsub", "副")   # 蓝 / 后 / 副
            s = f"胆:{j(sorted(t['dan']))} 拖:{j(sorted(t['tuo']))}"
            sub = t.get("tsub") or t.get("sub") or []
            if self.has_sub and sub:
                s += f" {sub_word}:{j(sorted(sub))}"
            return s
        # 单式（默认）
        main = j(t.get("main", []))
        if self.has_sub and t.get("sub"):
            return f"{main}|{j(t['sub'])}"
        return main

    def _copy(self):
        """复制全部号码，弹出格式选择：中文详细 / 紧凑(主,..|副,..)。自动屏蔽重/边/跳标注。"""
        fmt, ok = QInputDialog.getItem(
            self, "选择复制格式", "请选择号码复制格式：",
            ["中文详细格式（前区[..] 后区[..]）",
             "紧凑格式（04,11,14,21,22|01,11）"],
            0, False)
        if not ok:
            return
        compact = fmt.startswith("紧凑")
        lines = []
        for g in getattr(self, "_render_groups", []):
            if g.get("title"):
                # 紧凑格式保留套餐头，去掉中文票型描述行噪音
                lines.append(g["title"])
            idx = 0
            for t in g["tickets"]:
                idx += 1
                if compact:
                    lines.append(self._compact_ticket(t))
                else:
                    lines.append(self._fmt_ticket_line(t, idx, annotate=False))
        QApplication.clipboard().setText("\n".join(lines))
        QMessageBox.information(self, "已复制",
            f"已复制全部号码（共{getattr(self,'_total_bets',len(self._combos))}注，已屏蔽重/边/跳标注，可直接投注）")

    def _save_local(self):
        ts = datetime.now().strftime("%Y%m%d_%H%M%S")
        fname = AUTO_PREDICT_DIR / f"九宫格_{self.game_type}_{ts}.txt"
        fname.write_text(self._result_te.toPlainText(), encoding="utf-8")
        QMessageBox.information(self, "已保存", f"已保存到:\n{fname}")


