def _ensure_cv2():
    """尝试导入 opencv-python，失败时自动安装"""
    try:
        import cv2
        return True
    except ImportError:
        try:
            import subprocess, sys
            subprocess.check_call([sys.executable, "-m", "pip", "install",
                                   "opencv-python-headless", "--break-system-packages", "-q"],
                                  timeout=120)
            import cv2
            return True
        except Exception:
            return False

def _ensure_pil():
    """尝试导入 Pillow"""
    try:
        from PIL import Image
        return True
    except ImportError:
        try:
            import subprocess, sys
            subprocess.check_call([sys.executable, "-m", "pip", "install",
                                   "Pillow", "--break-system-packages", "-q"], timeout=60)
            return True
        except Exception:
            return False

def _ensure_pyzbar():
    """尝试导入 pyzbar。注意：Windows 上 pyzbar 需要 zbar 运行库(DLL)，
    若只 pip 安装而缺 DLL，import 会抛 ImportError/OSError——此时返回 False，
    解析会自动改用 OpenCV 引擎。"""
    try:
        from pyzbar.pyzbar import decode  # noqa
        return True
    except Exception:
        pass
    # 尝试 pip 安装后再次真正导入（必须重新 import 验证，不能装完就返回 True）
    try:
        import subprocess, sys
        subprocess.check_call([sys.executable, "-m", "pip", "install",
                               "pyzbar", "--break-system-packages", "-q"], timeout=60)
    except Exception:
        return False
    try:
        from pyzbar.pyzbar import decode  # noqa  # 安装后验证是否真能用（含DLL）
        return True
    except Exception:
        # 多见于 Windows 缺少 zbar DLL；交给 OpenCV 引擎兜底
        return False

def _extract_nums_from_qr_text(text: str, main_max: int, main_need: int,
                                sub_max: int, sub_need: int):
    """从二维码解码文本中精确提取 (main_nums, sub_nums)。
    支持票面常见格式：含 '+' 分隔主副区(如 03 07 12 24 30 33+08)，
    或纯号码串。会先剔除期号(20xxxxx)避免混入球号。"""
    import re as _re
    src = text
    # 先去掉玩法标识里带数字的英文标记(kl8/3d/pl3/pl5/qlc等)，
    # 否则 'kl8' 的 8、'3d' 的 3 会被当成球号混入。
    src = _re.sub(r"(?i)\b(kl8|pl3|pl5|3d|qxc|qlc|ssq|dlt)\b", " ", src)
    # 彩票球号最多2位(最大80)，任何连续3位及以上的数字串必为
    # 期号/流水号/条码/金额，绝不是球号 → 整体删除，避免被拆进球号。
    src = _re.sub(r"\d{3,}", " ", src)
    mains, subs = [], []
    if "+" in src:
        seg = _re.search(r"([\d\s]+\+[\d\s]+)", src)
        if seg:
            p = seg.group(1).split("+")
            mains = [int(x) for x in _re.findall(r"\d{1,2}", p[0]) if 1 <= int(x) <= main_max]
            if len(p) > 1 and sub_max > 0:
                subs = [int(x) for x in _re.findall(r"\d{1,2}", p[1]) if 1 <= int(x) <= sub_max]
    if not mains:
        allnums = [int(x) for x in _re.findall(r"\d{1,2}", src) if 1 <= int(x) <= max(main_max, sub_max or 1)]
        mains = [n for n in allnums if 1 <= n <= main_max]
        if sub_max > 0 and sub_need > 0:
            used = set(mains[:main_need])
            subs = [n for n in allnums if 1 <= n <= sub_max and n not in used]
    # 去重保序并截断
    def _dedup(seq):
        seen = set(); out = []
        for x in seq:
            if x not in seen:
                seen.add(x); out.append(x)
        return out
    mains = _dedup(mains)[:main_need] if main_need else _dedup(mains)
    subs  = _dedup(subs)[:sub_need] if sub_need else _dedup(subs)
    return sorted(mains), sorted(subs)


def _ocr_recognize_numbers(img_path: str, game: str) -> tuple:
    """
    识别图片中的彩票号码。
    优先级：二维码引擎(微信/opencv，精确) → easyocr → opencv+tesseract → 纯数字OCR
    返回 (main_nums, sub_nums, raw_text, method_used)
    """
    import re as _re
    cfg = NINE_GRID_CONFIG.get(game, NINE_GRID_CONFIG["双色球"])
    main_max = cfg["main_max"]
    main_need = cfg["main_need"]
    sub_max = cfg.get("sub_max", 0)
    sub_need = cfg.get("sub_need", 0)

    raw_text = ""
    method_used = "未识别"

    # ── 引擎-1: 二维码优先（彩票票面都带兑奖二维码，比OCR数字精确得多）──
    # 复用满血的多引擎二维码解码（含微信增强引擎），本机环境最可靠。
    try:
        qr_text, qr_method = _decode_qr_image(img_path)
        if qr_text:
            qmains, qsubs = _extract_nums_from_qr_text(
                qr_text, main_max, main_need, sub_max, sub_need)
            if qmains:   # 二维码里确实解出了号码
                return qmains, qsubs, qr_text, f"二维码识别[{qr_method}]"
    except Exception:
        pass

    # ── 引擎0: easyocr（纯 Python OCR，手机端首选，无需系统 tesseract）──
    try:
        import easyocr  # 若已安装
        # 复用全局 reader，避免每次重载模型（首次较慢）
        global _EASYOCR_READER
        try:
            _EASYOCR_READER
        except NameError:
            _EASYOCR_READER = None
        if _EASYOCR_READER is None:
            _EASYOCR_READER = easyocr.Reader(['ch_sim', 'en'], gpu=False, verbose=False)
        parts = _EASYOCR_READER.readtext(img_path, detail=0)
        if parts:
            raw_text = " ".join(parts)
            method_used = "EasyOCR"
    except Exception:
        pass

    # ── 引擎1: opencv 图像预处理 + tesseract ─────────────────────
    if not raw_text:
      try:
        if _ensure_cv2():
            import cv2, numpy as np_
            img = cv2.imread(img_path)
            if img is not None:
                gray = cv2.cvtColor(img, cv2.COLOR_BGR2GRAY)
                # 自适应二值化增强数字
                thresh = cv2.adaptiveThreshold(
                    gray, 255, cv2.ADAPTIVE_THRESH_GAUSSIAN_C,
                    cv2.THRESH_BINARY, 11, 2)
                # 缩放放大（提升OCR精度）
                h, w = thresh.shape
                if w < 600:
                    scale = 600 / w
                    thresh = cv2.resize(thresh, (int(w*scale), int(h*scale)),
                                        interpolation=cv2.INTER_CUBIC)
                cv_tmp = str(AUTO_PREDICT_DIR / "tmp_cv_processed.png")
                cv2.imwrite(cv_tmp, thresh)
                # 尝试 tesseract
                try:
                    import subprocess
                    r = subprocess.run(
                        ["tesseract", cv_tmp, "stdout", "--psm", "6",
                         "-l", "chi_sim+eng", "--oem", "1"],
                        capture_output=True, text=True, timeout=15)
                    if r.stdout.strip():
                        raw_text = r.stdout
                        method_used = "OpenCV+Tesseract"
                except Exception:
                    pass
      except Exception:
        pass

    # ── 引擎2: 原图 tesseract（若上面没拿到结果）─────────────────
    if not raw_text:
        try:
            import subprocess
            r = subprocess.run(
                ["tesseract", img_path, "stdout", "--psm", "6",
                 "-l", "chi_sim+eng"],
                capture_output=True, text=True, timeout=12)
            if r.stdout.strip():
                raw_text = r.stdout
                method_used = "Tesseract原图"
        except Exception:
            pass

    # ── 引擎3: PIL + pytesseract ──────────────────────────────────
    if not raw_text:
        try:
            if _ensure_pil():
                from PIL import Image as PILImage, ImageEnhance, ImageFilter
                import pytesseract
                img_pil = PILImage.open(img_path).convert("L")
                img_pil = ImageEnhance.Contrast(img_pil).enhance(2.0)
                img_pil = img_pil.filter(ImageFilter.SHARPEN)
                raw_text = pytesseract.image_to_string(img_pil, lang="chi_sim+eng",
                                                        config="--psm 6")
                method_used = "PIL+pytesseract"
        except Exception:
            pass

    # ── 号码解析 ─────────────────────────────────────────────────
    def parse_nums(text):
        """从OCR文本中提取数字"""
        # 提取所有1-2位数字
        found = [int(x) for x in _re.findall(r"\b(\d{1,2})\b", text)
                 if 1 <= int(x) <= max(main_max, sub_max if sub_max else 1)]
        return found

    nums_all = parse_nums(raw_text)
    main_nums = sorted(set(n for n in nums_all if 1 <= n <= main_max))[:main_need]
    sub_nums = []
    if sub_max > 0 and sub_need > 0:
        used = set(main_nums)
        sub_nums = sorted(set(n for n in nums_all if 1 <= n <= sub_max and n not in used))[:sub_need]

    return main_nums, sub_nums, raw_text, method_used


class _CameraThread(QThread):
    """后台摄像头采集线程 —— 所有摄像头 I/O 都在此线程执行，主线程永不阻塞，彻底避免卡死"""
    frame_ready = Signal(object)   # 发送 numpy BGR 帧
    opened      = Signal(int)      # 成功打开的摄像头索引
    failed      = Signal(str)      # 错误信息

    def __init__(self, cam_index=0, parent=None):
        super().__init__(parent)
        self._cam_index = cam_index
        self._running   = False

    def run(self):
        try:
            import cv2
        except Exception:
            self.failed.emit("未安装 opencv-python，无法使用摄像头\n\n"
                             "请运行: pip_disabled_install opencv-python-headless")
            return
        import time
        cap = None
        # Windows 上优先用 DSHOW 后端：打开更快、更不易卡顿
        backends = []
        if hasattr(cv2, "CAP_DSHOW"):
            backends.append(cv2.CAP_DSHOW)
        backends.append(None)  # 系统默认后端
        try:
            for be in backends:
                try:
                    cap = cv2.VideoCapture(self._cam_index, be) if be is not None \
                          else cv2.VideoCapture(self._cam_index)
                except Exception:
                    cap = None
                if cap is not None and cap.isOpened():
                    break
                if cap is not None:
                    cap.release(); cap = None
        except Exception as e:
            self.failed.emit(f"打开摄像头失败: {e}")
            return
        if cap is None or not cap.isOpened():
            if cap is not None:
                cap.release()
            self.failed.emit(f"无法打开摄像头 {self._cam_index}\n\n"
                             "请检查设备连接/权限，或改用【选择图片】方式")
            return
        try:
            cap.set(cv2.CAP_PROP_FRAME_WIDTH,  1280)
            cap.set(cv2.CAP_PROP_FRAME_HEIGHT, 720)
            cap.set(cv2.CAP_PROP_BUFFERSIZE, 1)   # 仅缓存最新帧，降低预览延迟
        except Exception:
            pass
        self._running = True
        self.opened.emit(self._cam_index)
        fail_cnt = 0
        while self._running:
            try:
                ret, frame = cap.read()
            except Exception:
                ret, frame = False, None
            if not ret or frame is None:
                fail_cnt += 1
                if fail_cnt > 60:        # 连续读取失败 → 放弃
                    self.failed.emit("摄像头读取失败，已停止")
                    break
                self.msleep(15)
                continue
            fail_cnt = 0
            # cap.read() 每次返回新数组，可安全跨线程传递
            self.frame_ready.emit(frame)
            self.msleep(28)              # ~30fps，给主线程留出渲染时间
        try:
            cap.release()
        except Exception:
            pass

    def stop(self):
        self._running = False
        # 最多等待 1.5s，循环每 ~28ms 检查一次，通常瞬间退出
        self.wait(1500)


class CameraCaptureDlg(QDialog):
    """摄像头拍照对话框。
    优先使用 Qt 自带的 QtMultimedia(QCamera) —— 兼容桌面/笔记本/部分移动端，
    无需 OpenCV；若 QtMultimedia 不可用则回退到 OpenCV 后台线程采集；
    两者都不可用时提示改用【从相册/文件选图】。
    """

    captured = Signal(object)  # 发送 QPixmap

    def __init__(self, parent=None):
        super().__init__(parent)
        self.setWindowTitle("📸 摄像头拍照")
        self._thread     = None      # OpenCV 后备线程
        self._last_frame = None      # OpenCV 最近一帧(numpy)
        self._qcam       = None      # QtMultimedia 相机对象
        self._qsession   = None
        self._qcapture   = None
        self._mode       = None      # 'qt' | 'cv' | None
        sc = QApplication.primaryScreen().availableGeometry()
        self.resize(min(640, int(sc.width()*0.9)), min(560, int(sc.height()*0.85)))
        self._build_ui()
        QTimer.singleShot(50, self._start)

    # ---------- UI ----------
    def _build_ui(self):
        lay = QVBoxLayout(self)
        title = QLabel("📸 对准彩票，点击【拍照】")
        title.setAlignment(Qt.AlignCenter)
        title.setStyleSheet("font-size:13px;font-weight:bold;color:#1A5276;"
                            "background:#EBF5FB;padding:5px;border-radius:4px;")
        lay.addWidget(title)

        # 预览区：QtMultimedia 用 QVideoWidget，OpenCV 用 QLabel
        self._preview = QLabel("正在启动摄像头…")
        self._preview.setAlignment(Qt.AlignCenter)
        self._preview.setMinimumSize(480, 360)
        self._preview.setStyleSheet("background:#1a1a1a;color:white;font-size:13px;"
                                    "border:2px solid #2980B9;border-radius:4px;")
        self._video_widget = None    # 延迟创建
        lay.addWidget(self._preview, 1)
        self._preview_container = lay

        cam_row = QHBoxLayout()
        self._cam_cb = QComboBox()
        self._cam_cb.setToolTip("选择摄像头设备")
        self._cam_cb.currentIndexChanged.connect(self._switch_camera)
        cam_row.addWidget(QLabel("摄像头:"))
        cam_row.addWidget(self._cam_cb, 1)
        flip_btn = QPushButton("🔄 切换前后")
        flip_btn.setToolTip("在多个摄像头间切换（前置/后置）")
        flip_btn.clicked.connect(self._flip_camera)
        cam_row.addWidget(flip_btn)
        lay.addLayout(cam_row)

        btn_row = QHBoxLayout()
        snap_btn = QPushButton("📸 拍照")
        snap_btn.setStyleSheet("background:#E74C3C;color:white;font-weight:bold;"
                               "font-size:14px;padding:9px 24px;border-radius:5px;")
        snap_btn.clicked.connect(self._snap)
        pick_btn = QPushButton("📂 改用选图")
        pick_btn.setToolTip("摄像头打不开时，从相册/文件选择已拍好的图片")
        pick_btn.clicked.connect(self._pick_file)
        cancel_btn = QPushButton("取消")
        cancel_btn.clicked.connect(self._on_cancel)
        cancel_btn.setStyleSheet("padding:9px 12px;")
        btn_row.addWidget(pick_btn); btn_row.addStretch()
        btn_row.addWidget(cancel_btn); btn_row.addWidget(snap_btn)
        lay.addLayout(btn_row)

    # ---------- 启动：先试 QtMultimedia，再试 OpenCV ----------
    def _start(self):
        if self._try_start_qt():
            self._mode = "qt"
            return
        if self._try_start_cv():
            self._mode = "cv"
            return
        self._mode = None
        self._preview.setText(
            "⚠ 未能打开摄像头\n\n"
            "可能原因：未授予相机权限 / 设备无摄像头 / 缺少多媒体组件\n\n"
            "请点击下方【📂 改用选图】，用系统相机拍好后从相册选择")

    def _try_start_qt(self):
        """使用 Qt 自带 QtMultimedia 打开摄像头（最通用，无需OpenCV）。"""
        try:
            from PySide6.QtMultimedia import (QCamera, QMediaCaptureSession,
                                              QImageCapture, QMediaDevices)
            from PySide6.QtMultimediaWidgets import QVideoWidget
        except Exception:
            return False
        try:
            cams = QMediaDevices.videoInputs()
            if not cams:
                return False
            self._qt_devices = cams
            # 填充设备下拉
            self._cam_cb.blockSignals(True)
            self._cam_cb.clear()
            for i, dev in enumerate(cams):
                try:
                    name = dev.description()
                except Exception:
                    name = f"摄像头 {i}"
                self._cam_cb.addItem(name or f"摄像头 {i}", i)
            self._cam_cb.blockSignals(False)

            # 用 QVideoWidget 替换 QLabel 预览
            if self._video_widget is None:
                self._video_widget = QVideoWidget(self)
                self._video_widget.setMinimumSize(480, 360)
                self._preview_container.replaceWidget(self._preview, self._video_widget)
                self._preview.hide()

            self._qt_open(0)
            return True
        except Exception:
            return False

    def _qt_open(self, dev_index):
        from PySide6.QtMultimedia import (QCamera, QMediaCaptureSession, QImageCapture)
        # 关掉旧的
        self._qt_close()
        dev = self._qt_devices[dev_index]
        self._qcam = QCamera(dev)
        self._qsession = QMediaCaptureSession()
        self._qcapture = QImageCapture()
        self._qsession.setCamera(self._qcam)
        self._qsession.setVideoOutput(self._video_widget)
        self._qsession.setImageCapture(self._qcapture)
        self._qcapture.imageCaptured.connect(self._on_qt_captured)
        try:
            self._qcapture.errorOccurred.connect(
                lambda _id, _err, msg: QMessageBox.warning(self, "拍照失败", str(msg)))
        except Exception:
            pass
        self._qcam.start()

    def _qt_close(self):
        try:
            if self._qcam is not None:
                self._qcam.stop()
        except Exception:
            pass
        self._qcam = None; self._qsession = None; self._qcapture = None

    def _on_qt_captured(self, _id, image):
        # image 是 QImage
        try:
            px = QPixmap.fromImage(image)
            if not px.isNull():
                # 保存一份供下游 OCR/二维码识别
                try:
                    snap_path = str(AUTO_PREDICT_DIR / "tmp_camera_snap.png")
                    px.save(snap_path)
                except Exception:
                    pass
                self._cleanup()
                self.captured.emit(px)
                self.accept()
                return
        except Exception:
            pass
        QMessageBox.warning(self, "错误", "拍照失败，请重试")

    # ---------- OpenCV 后备 ----------
    def _try_start_cv(self):
        try:
            if not _ensure_cv2():
                return False
        except Exception:
            return False
        # 还原 QLabel 预览
        self._cam_cb.blockSignals(True)
        self._cam_cb.clear()
        for i in range(4):
            self._cam_cb.addItem(f"摄像头 {i}", i)
        self._cam_cb.blockSignals(False)
        self._open_camera_cv(0)
        return True

    def _open_camera_cv(self, idx):
        self._stop_cv()
        self._last_frame = None
        self._preview.setText("正在启动摄像头…")
        self._thread = _CameraThread(idx, self)
        self._thread.frame_ready.connect(self._on_frame_cv)
        self._thread.failed.connect(self._on_cam_error)
        self._thread.start()

    def _on_cam_error(self, msg):
        self._preview.setText(f"⚠ {msg}\n\n可点击【📂 改用选图】")

    def _on_frame_cv(self, frame):
        self._last_frame = frame
        try:
            import cv2
            from PySide6.QtGui import QImage
            rgb = cv2.cvtColor(frame, cv2.COLOR_BGR2RGB)
            h, w, ch = rgb.shape
            qimg = QImage(rgb.data, w, h, ch * w, QImage.Format_RGB888).copy()
            px = QPixmap.fromImage(qimg)
            self._preview.setPixmap(
                px.scaled(self._preview.size(), Qt.KeepAspectRatio, Qt.FastTransformation))
        except Exception:
            pass

    # ---------- 设备切换 ----------
    def _switch_camera(self, combo_idx):
        if combo_idx < 0:
            return
        dev_index = self._cam_cb.itemData(combo_idx)
        if dev_index is None:
            return
        if self._mode == "qt":
            try:
                self._qt_open(int(dev_index))
            except Exception:
                pass
        elif self._mode == "cv":
            self._open_camera_cv(int(dev_index))

    def _flip_camera(self):
        n = self._cam_cb.count()
        if n > 1:
            self._cam_cb.setCurrentIndex((self._cam_cb.currentIndex() + 1) % n)

    # ---------- 拍照 ----------
    def _snap(self):
        if self._mode == "qt" and self._qcapture is not None:
            try:
                self._qcapture.capture()   # 结果走 _on_qt_captured
                return
            except Exception as e:
                QMessageBox.warning(self, "错误", f"拍照出错: {e}"); return
        if self._mode == "cv":
            self._snap_cv(); return
        QMessageBox.information(self, "提示",
            "摄像头不可用，请点击【📂 改用选图】从相册选择已拍好的彩票照片")

    def _snap_cv(self):
        if self._last_frame is None:
            QMessageBox.warning(self, "提示", "摄像头尚未就绪，请稍候"); return
        try:
            import cv2
            from PySide6.QtGui import QImage
            frame = self._last_frame
            snap_path = str(AUTO_PREDICT_DIR / "tmp_camera_snap.png")
            try:
                cv2.imwrite(snap_path, frame)
            except Exception:
                pass
            rgb = cv2.cvtColor(frame, cv2.COLOR_BGR2RGB)
            h, w, ch = rgb.shape
            qimg = QImage(rgb.data, w, h, ch * w, QImage.Format_RGB888).copy()
            px = QPixmap.fromImage(qimg)
            if px.isNull():
                px = QPixmap(snap_path)
            if not px.isNull():
                self._cleanup()
                self.captured.emit(px)
                self.accept()
            else:
                QMessageBox.warning(self, "错误", "拍照失败，请重试")
        except Exception as e:
            QMessageBox.warning(self, "错误", f"拍照出错: {e}")

    # ---------- 从相册/文件选图（最稳妥的回退）----------
    def _pick_file(self):
        path, _ = QFileDialog.getOpenFileName(
            self, "选择已拍好的图片", "",
            "图片文件 (*.png *.jpg *.jpeg *.bmp *.gif *.webp *.heic)")
        if not path:
            return
        px = QPixmap(path)
        if px.isNull():
            QMessageBox.warning(self, "错误", "无法加载该图片"); return
        try:
            snap_path = str(AUTO_PREDICT_DIR / "tmp_camera_snap.png")
            px.save(snap_path)
        except Exception:
            pass
        self._cleanup()
        self.captured.emit(px)
        self.accept()

    # ---------- 清理 ----------
    def _stop_cv(self):
        if self._thread is not None:
            for sig, slot in (("frame_ready", self._on_frame_cv),
                              ("failed", self._on_cam_error)):
                try:
                    getattr(self._thread, sig).disconnect(slot)
                except Exception:
                    pass
            try:
                self._thread.stop()
            except Exception:
                pass
            self._thread = None

    def _cleanup(self):
        self._qt_close()
        self._stop_cv()

    def _on_cancel(self):
        self._cleanup()
        self.reject()

    def closeEvent(self, e):
        self._cleanup()
        super().closeEvent(e)


def _qr_lib_status():
    """返回各二维码解析库的可用情况，供失败时给出精准提示。"""
    st = {"pyzbar": False, "opencv": False, "wechat": False, "zxing": False}
    try:
        from pyzbar.pyzbar import decode as _d  # noqa
        st["pyzbar"] = True
    except Exception:
        pass
    try:
        import cv2
        st["opencv"] = True
        st["wechat"] = hasattr(cv2, "wechat_qrcode_WeChatQRCode")
    except Exception:
        pass
    try:
        import subprocess
        r = subprocess.run(["zxing", "--help"], capture_output=True, timeout=4)
        st["zxing"] = True
    except Exception:
        pass
    return st


def _decode_qr_image(qr_path: str):
    """多引擎 + 多预处理解析二维码，返回 (decoded_text, method)。
    针对手机拍照/截图常见问题（模糊、反光、旋转、太小、低对比度）做了大量
    预处理尝试，可安全地在后台线程调用。"""
    decoded = ""
    method  = ""

    # ── 预先把图片用 PIL/opencv 读成多个候选版本 ──────────────
    def _pil_variants():
        """用 PIL 生成多种增强版本，返回 [(PIL.Image, tagname), ...]"""
        variants = []
        try:
            if not _ensure_pil():
                return variants
            from PIL import Image as PILImg, ImageOps, ImageEnhance, ImageFilter
            base = PILImg.open(qr_path).convert("RGB")
            w, h = base.size
            # 太小则放大（二维码模块过小时 detector 抓不到）
            scale = 1
            if min(w, h) < 500:
                scale = max(2, int(600 / max(1, min(w, h))))
            big = base.resize((w * scale, h * scale)) if scale > 1 else base
            gray = ImageOps.grayscale(big)
            variants.append((big, "原图放大"))
            variants.append((gray, "灰度"))
            variants.append((ImageOps.autocontrast(gray), "自动对比度"))
            variants.append((ImageEnhance.Contrast(gray).enhance(2.2), "增强对比"))
            variants.append((ImageOps.invert(gray), "反色"))
            variants.append((gray.filter(ImageFilter.SHARPEN), "锐化"))
            # 旋转（拍歪了）
            for ang in (90, 180, 270):
                variants.append((big.rotate(ang, expand=True), f"旋转{ang}"))
        except Exception:
            pass
        return variants

    # ── 引擎1: pyzbar（最可靠，对多种版本依次尝试）─────────────
    try:
        if _ensure_pyzbar() and _ensure_pil():
            from pyzbar.pyzbar import decode as pz_decode
            from PIL import Image as PILImg
            # 先原图
            try:
                results = pz_decode(PILImg.open(qr_path))
                if results:
                    decoded = results[0].data.decode("utf-8", "ignore")
                    method = "pyzbar"
            except Exception:
                pass
            if not decoded:
                for img, tag in _pil_variants():
                    try:
                        results = pz_decode(img)
                        if results:
                            decoded = results[0].data.decode("utf-8", "ignore")
                            method = f"pyzbar[{tag}]"
                            break
                    except Exception:
                        continue
    except Exception:
        pass

    # ── 引擎2: opencv wechat_qrcode（微信引擎，对模糊最强）──────
    if not decoded:
        try:
            if _ensure_cv2():
                import cv2
                if hasattr(cv2, "wechat_qrcode_WeChatQRCode"):
                    det = cv2.wechat_qrcode_WeChatQRCode()
                    img_cv = cv2.imread(qr_path)
                    if img_cv is not None:
                        res, _ = det.detectAndDecode(img_cv)
                        if res:
                            decoded = res[0]
                            method = "OpenCV-WeChatQR"
        except Exception:
            pass

    # ── 引擎3: opencv QRCodeDetector（多预处理 + multi）─────────
    if not decoded:
        try:
            if _ensure_cv2():
                import cv2
                import numpy as _np
                img_cv = cv2.imread(qr_path)
                if img_cv is not None:
                    gray0 = cv2.cvtColor(img_cv, cv2.COLOR_BGR2GRAY)
                    h, w = gray0.shape
                    if min(h, w) < 500:
                        sc = max(2, int(600 / max(1, min(h, w))))
                        gray0 = cv2.resize(gray0, (w * sc, h * sc),
                                           interpolation=cv2.INTER_CUBIC)
                    cands = [("原图", img_cv), ("灰度", gray0)]
                    # Otsu 二值
                    try:
                        _, th = cv2.threshold(gray0, 0, 255,
                            cv2.THRESH_BINARY + cv2.THRESH_OTSU)
                        cands.append(("Otsu二值", th))
                        cands.append(("Otsu反色", cv2.bitwise_not(th)))
                    except Exception:
                        pass
                    # 自适应二值
                    try:
                        ad = cv2.adaptiveThreshold(gray0, 255,
                            cv2.ADAPTIVE_THRESH_GAUSSIAN_C, cv2.THRESH_BINARY, 21, 5)
                        cands.append(("自适应二值", ad))
                    except Exception:
                        pass
                    # 高斯去噪 + 锐化
                    try:
                        blur = cv2.GaussianBlur(gray0, (0, 0), 3)
                        sharp = cv2.addWeighted(gray0, 1.5, blur, -0.5, 0)
                        cands.append(("锐化", sharp))
                    except Exception:
                        pass
                    det = cv2.QRCodeDetector()
                    for tag, im in cands:
                        try:
                            # 单码
                            val, _, _ = det.detectAndDecode(im)
                            if val:
                                decoded = val; method = f"OpenCV-QRDet[{tag}]"; break
                            # 多码（部分版本支持）
                            if hasattr(det, "detectAndDecodeMulti"):
                                ok, vals, _, _ = det.detectAndDecodeMulti(im)
                                if ok and vals:
                                    v = next((x for x in vals if x), "")
                                    if v:
                                        decoded = v; method = f"OpenCV-QRMulti[{tag}]"; break
                        except Exception:
                            continue
        except Exception:
            pass

    # ── 引擎4: zxing 命令行 ───────────────────────────────────
    if not decoded:
        try:
            import subprocess
            r = subprocess.run(
                ["zxing", qr_path], capture_output=True, text=True, timeout=8)
            if r.returncode == 0 and r.stdout.strip():
                decoded = r.stdout.strip()
                method = "zxing-CLI"
        except Exception:
            pass

    return decoded, method


class _QRDecodeWorker(QThread):
    """后台二维码解析线程，避免 pyzbar/opencv/zxing 阻塞 UI"""
    done = Signal(str, str)   # decoded, method

    def __init__(self, qr_path, parent=None):
        super().__init__(parent)
        self._path = qr_path

    def run(self):
        try:
            decoded, method = _decode_qr_image(self._path)
        except Exception:
            decoded, method = "", ""
        self.done.emit(decoded, method)


class _OCRWorker(QThread):
    """后台 OCR 识别线程，避免 tesseract/图像处理阻塞 UI"""
    done = Signal(object)   # (main_nums, sub_nums, raw_text, method)

    def __init__(self, img_path, game, parent=None):
        super().__init__(parent)
        self._img_path = img_path
        self._game     = game

    def run(self):
        try:
            res = _ocr_recognize_numbers(self._img_path, self._game)
        except Exception as e:
            res = ([], [], "", f"识别出错: {e}")
        self.done.emit(res)


class ImageRecognizeDialog(QDialog):
    """图片识别号码 + 拍照 + 历史开奖比对 + 中奖概率统计（增强版）"""

    def __init__(self, parent):
        super().__init__(parent)
        self.app = parent
        self._pixmap = None
        self._img_path = None
        sc = QApplication.primaryScreen().availableGeometry()
        self.resize(min(720, int(sc.width()*0.97)), min(920, int(sc.height()*0.95)))
        self.setWindowTitle("🖼 图片识别 + 拍照识别 + 历史比对")
        self._build_ui()

    def _build_ui(self):
        lay = QVBoxLayout(self); lay.setSpacing(5)
        title = QLabel("🖼 彩票图片识别 / 拍照识别号码")
        title.setStyleSheet(
            "font-size:14px;font-weight:bold;color:white;padding:6px;"
            "background:qlineargradient(x1:0,y1:0,x2:1,y2:0,"
            "stop:0 #1A5276,stop:1 #8E44AD);border-radius:5px;")
        title.setAlignment(Qt.AlignCenter); lay.addWidget(title)

        # 玩法选择
        gr = QHBoxLayout()
        gr.addWidget(QLabel("彩票类型:"))
        self._game_cb = QComboBox()
        self._game_cb.addItems(list(NINE_GRID_CONFIG.keys()))
        gr.addWidget(self._game_cb); gr.addStretch()
        lay.addLayout(gr)

        # Step 1: 获取图片（4种方式）
        g1 = QGroupBox("步骤1: 获取图片（选择/粘贴/截图/拍照）")
        g1l = QVBoxLayout(g1)
        br1 = QHBoxLayout()
        for lbl, fn, col in [
            ("📂 选择图片", self._load_img,    "#2980B9"),
            ("📋 粘贴剪贴板", self._paste_img, "#16A085"),
            ("📸 拍照识别", self._open_camera,  "#E74C3C"),
            ("🔍 开始识别", self._recognize,    "#E67E22"),
        ]:
            b = QPushButton(lbl)
            b.setStyleSheet(f"background:{col};color:white;font-weight:bold;padding:6px;")
            b.clicked.connect(fn); br1.addWidget(b)
        g1l.addLayout(br1)
        self._img_lbl = QLabel("← 点击【选择图片】或【拍照识别】加载图片")
        self._img_lbl.setFixedHeight(140); self._img_lbl.setAlignment(Qt.AlignCenter)
        self._img_lbl.setStyleSheet(
            "background:#F0F0F0;border:2px dashed #BDC3C7;border-radius:4px;"
            "color:#7F8C8D;font-size:12px;")
        g1l.addWidget(self._img_lbl)
        self._ocr_method_lbl = QLabel("识别引擎: —")
        self._ocr_method_lbl.setStyleSheet("font-size:10px;color:#7F8C8D;")
        g1l.addWidget(self._ocr_method_lbl)
        lay.addWidget(g1)

        # Step 2: 号码输入
        g2 = QGroupBox("步骤2: 识别结果 / 手动输入")
        g2l = QVBoxLayout(g2)
        self._nums_edit = QLineEdit()
        self._nums_edit.setPlaceholderText(
            "识别结果自动填入，或手动输入: 03 07 12 24 30 33 + 08  (双色球格式)")
        self._nums_edit.setStyleSheet("font-size:13px;padding:6px;")
        g2l.addWidget(self._nums_edit)
        hint = QLabel("💡 主区号码用空格分隔，双色球/大乐透用 + 分隔子区号码")
        hint.setStyleSheet("font-size:10px;color:#7F8C8D;"); g2l.addWidget(hint)
        lay.addWidget(g2)

        # Step 3: 分析
        g3 = QGroupBox("步骤3: 历史比对 + 概率统计")
