        def run_auto_predict():
            self.calculate_omission()
            self.backtest_predictions()
            text_lines = [f"=== {game} 自动学习综合预测 ===",
                          f"历史期数: {len(records)}  分析时间: {datetime.now().strftime('%H:%M:%S')}\n"]
            # 各区域遗漏Top号
            if game == "双色球":
                omit_r = self.last_omission_data.get(game,{}).get("red",{})
                omit_b = self.last_omission_data.get(game,{}).get("blue",{})
                freq_r = self.frequency_data.get(game,{}).get("red",{})
                freq_b = self.frequency_data.get(game,{}).get("blue",{})
                top_miss_r = sorted(omit_r, key=lambda n: -omit_r[n])[:8]
                top_freq_r = sorted(freq_r, key=lambda n: -freq_r[n])[:8]
                top_miss_b = sorted(omit_b, key=lambda n: -omit_b[n])[:4]
                top_freq_b = sorted(freq_b, key=lambda n: -freq_b[n])[:4]
                text_lines.append(f"📊 红球 — 高遗漏号: {top_miss_r}")
                text_lines.append(f"📊 红球 — 高频次号: {top_freq_r}")
                text_lines.append(f"📊 蓝球 — 高遗漏号: {top_miss_b}")
                text_lines.append(f"📊 蓝球 — 高频次号: {top_freq_b}\n")
            elif game == "大乐透":
                omit_f = self.last_omission_data.get(game,{}).get("front",{})
                omit_k = self.last_omission_data.get(game,{}).get("back",{})
                freq_f = self.frequency_data.get(game,{}).get("front",{})
                freq_k = self.frequency_data.get(game,{}).get("back",{})
                top_miss_f = sorted(omit_f, key=lambda n: -omit_f[n])[:8]
                top_freq_f = sorted(freq_f, key=lambda n: -freq_f[n])[:8]
                top_miss_k = sorted(omit_k, key=lambda n: -omit_k[n])[:4]
                top_freq_k = sorted(freq_k, key=lambda n: -freq_k[n])[:4]
                text_lines.append(f"📊 前区 — 高遗漏号: {top_miss_f}")
                text_lines.append(f"📊 前区 — 高频次号: {top_freq_f}")
                text_lines.append(f"📊 后区 — 高遗漏号: {top_miss_k}")
                text_lines.append(f"📊 后区 — 高频次号: {top_freq_k}\n")
            # 所有模型预测
            text_lines.append("🔮 各模型预测结果（含历史命中率）:")
            g_scores = self.model_scores.get(game, {})
            model_preds = []
            for mk, mv in PREDICTION_MODELS.items():
                try:
                    pred = self.predict_for_game(game, mk)
                    self._record_prediction(game, mk, pred)
                    sc = g_scores.get(mk, {})
                    total = sc.get("total", 0)
                    hits  = sc.get("hits", 0)
                    rate_str = f"{hits/total*100:.0f}%" if total > 0 else "无数据"
                    avg_str = f"{sc.get('sum_match',0)/max(total,1):.2f}个" if total > 0 else "—"
                    if game == "双色球":
                        pred_str = f"红:{pred.get('red',[])}  蓝:{pred.get('blue','?')}"
                    elif game == "大乐透":
                        pred_str = f"前:{pred.get('front',[])}  后:{pred.get('back',[])}"
                    else:
                        pred_str = str(pred)
                    line = f"  [{mv['name']:12s}] {pred_str}  (命中率:{rate_str} 均匹配:{avg_str})"
                    model_preds.append((mk, hits/max(total,1), line))
                except Exception as e:
                    model_preds.append((mk, 0, f"  [{mv['name']:12s}] 预测失败: {e}"))
            # 按命中率排序
            model_preds.sort(key=lambda x: -x[1])
            for _, _, line in model_preds:
                text_lines.append(line)
            best_mk = model_preds[0][0] if model_preds else "1"
            best_name = PREDICTION_MODELS.get(best_mk,{}).get("name","")
            text_lines.append(f"\n★ 推荐使用: {best_name}")
            text_lines.append("\n（以上数据仅供参考，理性购彩）")
            auto_result_te.setPlainText("\n".join(text_lines))

        auto_run_btn = QPushButton("🚀 立即生成自动学习预测")
        auto_run_btn.setStyleSheet("background:#27AE60;color:white;font-weight:bold;padding:8px;font-size:13px;")
        auto_run_btn.clicked.connect(run_auto_predict)
