    def _all_models_predict_compare(self, game: str):
        """全模型预测对比 — 显示所有14个模型的预测号码，
        支持选择投注方式（单式/复式/胆拖）和直接投注，
        回测后实时显示各模型命中情况。
        """
        if game not in self.history_data or not self.history_data[game]:
            QMessageBox.warning(self, "提示",
                f"暂无 {game} 历史数据，请先获取开奖数据后再使用")
            return

        self.backtest_predictions()

        dlg = QDialog(self)
        dlg.setWindowTitle(f"🏆 {game} — 全模型预测对比")
        dlg.setMinimumWidth(520)
        root_lay = QVBoxLayout(dlg)

        # ── 顶部控制栏 ──
        ctrl_row = QHBoxLayout()
        ctrl_row.addWidget(QLabel("投注方式:"))
        bet_type_combo = QComboBox()
        if game in ("双色球", "大乐透", "快乐8", "七乐彩"):
            bet_type_combo.addItems(["单式", "复式", "胆拖"])
        else:
            bet_type_combo.addItems(["单式", "复式"])
        ctrl_row.addWidget(bet_type_combo)

        # ── 复式号码数量选择 ──
        fuzhi_lbl = QLabel("  复式选码:")
        fuzhi_spin = QSpinBox()
        if game == "双色球":   fuzhi_spin.setRange(7, 15); fuzhi_spin.setValue(7)
        elif game == "大乐透": fuzhi_spin.setRange(6, 14); fuzhi_spin.setValue(6)
        elif game == "快乐8":  fuzhi_spin.setRange(11, 20); fuzhi_spin.setValue(11)
        elif game == "七乐彩": fuzhi_spin.setRange(8, 14); fuzhi_spin.setValue(8)
        else:                  fuzhi_spin.setRange(4, 8);  fuzhi_spin.setValue(4)
        ctrl_row.addWidget(fuzhi_lbl); ctrl_row.addWidget(fuzhi_spin)

        # ── 胆拖码数选择 ──
        dan_lbl = QLabel("  胆码数:"); dan_spin = QSpinBox(); dan_spin.setRange(1, 4); dan_spin.setValue(2)
        tuo_lbl = QLabel("拖码数:");  tuo_spin = QSpinBox()
        if game == "双色球":   tuo_spin.setRange(5, 13); tuo_spin.setValue(5)
        elif game == "大乐透": tuo_spin.setRange(4, 12); tuo_spin.setValue(4)
        else:                  tuo_spin.setRange(3, 10); tuo_spin.setValue(4)
        ctrl_row.addWidget(dan_lbl); ctrl_row.addWidget(dan_spin)
        ctrl_row.addWidget(tuo_lbl); ctrl_row.addWidget(tuo_spin)

        def _update_ctrl():
            bt = bet_type_combo.currentText()
            for w in (fuzhi_lbl, fuzhi_spin): w.setVisible(bt == "复式")
            for w in (dan_lbl, dan_spin, tuo_lbl, tuo_spin): w.setVisible(bt == "胆拖")
        bet_type_combo.currentIndexChanged.connect(_update_ctrl)
        _update_ctrl()

        ctrl_row.addStretch()
        if game == "大乐透":
            add_check = QCheckBox("追加投注")
            ctrl_row.addWidget(add_check)
        else:
            add_check = None

        gen_all_btn = QPushButton("🔄 生成所有模型预测")
        gen_all_btn.setStyleSheet("background:#2980B9;color:white;font-weight:bold;padding:5px 10px;")
        ctrl_row.addWidget(gen_all_btn)
        root_lay.addLayout(ctrl_row)

        # ── 结果表格 ──
        table = QTableWidget()
        table.setColumnCount(5)
        table.setHorizontalHeaderLabels(["模型", "预测号码", "命中率", "选择", "投注"])
        table.horizontalHeader().setSectionResizeMode(0, QHeaderView.ResizeToContents)
        table.horizontalHeader().setSectionResizeMode(1, QHeaderView.Stretch)
        table.horizontalHeader().setSectionResizeMode(2, QHeaderView.ResizeToContents)
        table.horizontalHeader().setSectionResizeMode(3, QHeaderView.ResizeToContents)
        table.horizontalHeader().setSectionResizeMode(4, QHeaderView.ResizeToContents)
        table.setEditTriggers(QAbstractItemView.NoEditTriggers)
        table.setSelectionBehavior(QAbstractItemView.SelectRows)
        table.setAlternatingRowColors(True)
        root_lay.addWidget(table)

        # ── 命中率报告区 ──
        report_lbl = QLabel()
        report_lbl.setWordWrap(True)
        report_lbl.setStyleSheet("font-size:11px;color:#555;padding:4px;background:#f5f5f5;")
        root_lay.addWidget(report_lbl)

        # ── 底部按钮 ──
        btn_row = QHBoxLayout()
        bet_selected_btn = QPushButton("💰 投注选中的模型")
        bet_selected_btn.setStyleSheet("background:#27AE60;color:white;font-weight:bold;padding:6px;")
        bet_all_btn = QPushButton("💎 投注全部模型")
        bet_all_btn.setStyleSheet("background:#E67E22;color:white;font-weight:bold;padding:6px;")

        def copy_all_preds():
            lines = ["=== 全模型预测结果一键复制 ===\n"]
            for mk, pred in model_predictions.items():
                mn = PREDICTION_MODELS.get(mk, {}).get("name", mk)
                lines.append(f"[{mn}] {fmt_pred(pred)}")
            lines.append("\n─────────────────────────────────")
            lines.append("（以上为所有模型预测号码，仅供参考，理性购彩）")
            QApplication.clipboard().setText("\n".join(lines))
            QMessageBox.information(dlg, "✅ 已复制", f"已复制 {len(model_predictions)} 个模型的预测号码到剪贴板！")

        copy_all_btn2 = QPushButton("📋 一键复制全部预测")
        copy_all_btn2.setStyleSheet("background:#8E44AD;color:white;font-weight:bold;padding:6px;")
        copy_all_btn2.clicked.connect(copy_all_preds)
        close_btn = QPushButton("关闭")
        btn_row.addWidget(bet_selected_btn)
        btn_row.addWidget(bet_all_btn)
        btn_row.addWidget(copy_all_btn2)
        btn_row.addWidget(close_btn)
        root_lay.addLayout(btn_row)

        # 存储每行的预测结果
        model_predictions: dict = {}  # {model_key: [lines]}
        checkboxes: dict = {}         # {model_key: QCheckBox}

        def fmt_pred(pred) -> str:
            """把预测字典格式化为可读字符串"""
            if game == "双色球":
                return f"红球:{', '.join(map(str,pred.get('red',[])))}" \
                       f"  蓝:{pred.get('blue','?')}"
            elif game == "大乐透":
                return f"前:{', '.join(map(str,pred.get('front',[])))}" \
                       f"  后:{', '.join(map(str,pred.get('back',[])))}"
            elif game in ("快乐8","七乐彩"):
                return f"号码:{', '.join(map(str,pred.get('main',[])))}"
            else:
                return f"号码:{' '.join(map(str,pred.get('pos',[])))}"

        def pred_to_bet_lines(pred, bet_type) -> list:
            """把预测结果按投注方式展开成投注行，复式/胆拖使用用户指定的号码数量"""
            n_fuzhi = fuzhi_spin.value()
            n_dan   = dan_spin.value()
            n_tuo   = tuo_spin.value()
            if game == "双色球":
                red  = sorted(pred.get("red",  []))
                blue = [pred.get("blue", 1)]
                if bet_type == "单式":
                    return [f"红球: {', '.join(map(str,red))} 蓝球: {blue[0]}"]
                elif bet_type == "复式":
                    pool = red[:n_fuzhi] if len(red) >= 6 else red
                    need = 6
                    return [f"红球: {', '.join(map(str,sorted(list(rc))))} 蓝球: {bc}"
                            for rc in combinations(pool, need) for bc in blue] \
                           if len(pool) >= need else [f"红球: {', '.join(map(str,red[:6]))} 蓝球: {blue[0]}"]
                else:  # 胆拖
                    dan = red[:n_dan]; tuo = red[n_dan:n_dan+n_tuo]
                    need_tuo = 6 - n_dan
                    return [f"红球: {', '.join(map(str,sorted(list(dan)+list(c))))} 蓝球: {blue[0]}"
                            for c in combinations(tuo, need_tuo)] \
                           if len(tuo) >= need_tuo else [f"红球: {', '.join(map(str,red[:6]))} 蓝球: {blue[0]}"]
            elif game == "大乐透":
                front = sorted(pred.get("front", []))
                back  = sorted(pred.get("back",  []))
                if bet_type == "单式":
                    return [f"前区: {', '.join(map(str,front))} 后区: {', '.join(map(str,back))}"]
                elif bet_type == "复式":
                    pool = front[:n_fuzhi] if len(front) >= 5 else front
                    return [f"前区: {', '.join(map(str,sorted(list(fc))))} 后区: {', '.join(map(str,sorted(list(bc))))}"
                            for fc in combinations(pool, 5) for bc in combinations(back, 2)] \
                           if len(pool) >= 5 and len(back) >= 2 else \
                           [f"前区: {', '.join(map(str,front[:5]))} 后区: {', '.join(map(str,back[:2]))}"]
                else:  # 胆拖
                    dan = front[:n_dan]; tuo = front[n_dan:n_dan+n_tuo]
                    need_tuo = 5 - n_dan
                    return [f"前区: {', '.join(map(str,sorted(list(dan)+list(c))))} 后区: {', '.join(map(str,back))}"
                            for c in combinations(tuo, need_tuo)] \
                           if len(tuo) >= need_tuo else \
                           [f"前区: {', '.join(map(str,front[:5]))} 后区: {', '.join(map(str,back[:2]))}"]
            elif game in ("快乐8", "七乐彩"):
                nums = sorted(pred.get("main", []))
                need = 7 if game == "七乐彩" else 10
                if bet_type == "复式":
                    pool = nums[:n_fuzhi] if len(nums) > need else nums
                    return [f"号码: {', '.join(map(str,sorted(list(c))))}"
                            for c in combinations(pool, need)] \
                           if len(pool) >= need else [f"号码: {', '.join(map(str,nums[:need]))}"]
                return [f"号码: {', '.join(map(str,nums[:need]))}"]
            else:
                pos = pred.get("pos", [])
                return [f"号码: {' '.join(map(str,pos))}"]

        def do_generate():
            nonlocal model_predictions, checkboxes
            model_predictions.clear(); checkboxes.clear()
            table.setRowCount(len(PREDICTION_MODELS))

            scores = self.model_scores.get(game, {})
            report_parts = []

            for row_idx, (mk, mv) in enumerate(PREDICTION_MODELS.items()):
                try:
                    pred = self.predict_for_game(game, mk)
                except Exception:
                    pred = self.predict_for_game(game, "6")  # 贝叶斯 fallback

                self._record_prediction(game, mk, pred)
                model_predictions[mk] = pred

                pred_str = fmt_pred(pred)
                score_data = scores.get(mk, {})
                total_c = score_data.get("total", 0)
                hit_c   = score_data.get("hits",  0)
                rate_str = f"{hit_c}/{total_c} ({hit_c/total_c*100:.0f}%)" if total_c > 0 else "无数据"

                table.setItem(row_idx, 0, QTableWidgetItem(mv["name"]))
                table.setItem(row_idx, 1, QTableWidgetItem(pred_str))

                rate_item = QTableWidgetItem(rate_str)
                if total_c > 0 and hit_c/total_c >= 0.3:
                    rate_item.setForeground(Qt.GlobalColor.green)
                table.setItem(row_idx, 2, rate_item)

                # 选择复选框
                cb = QCheckBox()
                cb.setChecked(True)
                checkboxes[mk] = cb
                cb_widget = QWidget()
                cb_lay = QHBoxLayout(cb_widget)
                cb_lay.addWidget(cb); cb_lay.setAlignment(Qt.AlignCenter); cb_lay.setContentsMargins(0,0,0,0)
                table.setCellWidget(row_idx, 3, cb_widget)

                # 单独投注按钮
                bet_btn_single = QPushButton("投注")
                bet_btn_single.setStyleSheet("background:#3498DB;color:white;font-size:11px;padding:2px 6px;")
                def _make_single_bet(mkey=mk):
                    return lambda: _do_bet([mkey])
                bet_btn_single.clicked.connect(_make_single_bet())
                table.setCellWidget(row_idx, 4, bet_btn_single)

                report_parts.append(f"{mv['name']}: {rate_str}")

            table.resizeRowsToContents()
            report_lbl.setText("命中率: " + "  |  ".join(report_parts[:7]) +
                               ("\n" + "  |  ".join(report_parts[7:])) if len(report_parts) > 7 else
                               "命中率: " + "  |  ".join(report_parts))

        def _do_bet(model_keys: list):
            bt   = bet_type_combo.currentText()
            addi = bool(add_check and add_check.isChecked())
            price = 3.0 if addi else 2.0
            target = self.get_default_target_issue(game)
            total_added = 0
            for mk in model_keys:
                if mk not in model_predictions: continue
                pred  = model_predictions[mk]
                lines = pred_to_bet_lines(pred, bt)
                bets  = len(lines)
                mn    = PREDICTION_MODELS.get(mk,{}).get("name", mk)
                self.add_betting_record(
                    game, f"全模型对比-{mn}-{bt}",
                    "\n".join(lines), bets, bets * price,
                    target_issue=target, additional=addi)
                total_added += bets
            if total_added:
                QMessageBox.information(dlg, "成功",
                    f"✓ 已添加 {len(model_keys)} 个模型的预测，共 {total_added} 注！")

        def _bet_selected():
            keys = [mk for mk, cb in checkboxes.items() if cb.isChecked()]
            if not keys:
                QMessageBox.warning(dlg, "提示", "请至少勾选一个模型")
                return
            _do_bet(keys)

        def _bet_all():
            _do_bet(list(model_predictions.keys()))

        gen_all_btn.clicked.connect(do_generate)
        bet_selected_btn.clicked.connect(_bet_selected)
        bet_all_btn.clicked.connect(_bet_all)
        close_btn.clicked.connect(dlg.reject)

        # 初始自动生成
        do_generate()
        dlg.exec()

    def _select_predict_model(self, game: str):
        """弹出模型选择对话框，让用户手动指定预测模型并即时生成预测。"""
        model_list = [(k, v["name"]) for k, v in PREDICTION_MODELS.items()]
        best_key   = self._best_model_key(game)

        dlg = QDialog(self)
        dlg.setWindowTitle(f"选择预测模型 — {game}")
        dlg.setMinimumWidth(380)
        lay = QVBoxLayout(dlg)

        info = QLabel(f"当前自动推荐：【{PREDICTION_MODELS[best_key]['name']}】\n"
                      f"（基于历史命中率自动选择，也可手动指定）")
        info.setStyleSheet("color:#555; font-size:12px; padding:4px;")
        info.setWordWrap(True)
        lay.addWidget(info)

        combo = QComboBox()
        for k, name in model_list:
            combo.addItem(name, k)
        # 默认选最优
        for i, (k, _) in enumerate(model_list):
            if k == best_key:
                combo.setCurrentIndex(i)
                break
        lay.addWidget(combo)

        # 命中率概览
        report = self.get_model_accuracy_report(game)
        rpt = QLabel(report if report.strip() else "  暂无命中率数据")
        rpt.setStyleSheet("font-size:11px; color:#666; padding:2px 8px;")
        rpt.setWordWrap(True)
        lay.addWidget(rpt)

        btn_row = QHBoxLayout()
        ok_btn = QPushButton("🤖 用此模型预测投注")
        ok_btn.setStyleSheet("background:#27AE60;color:white;font-weight:bold;padding:6px;")
        def do_predict():
            chosen_key = combo.currentData()
            dlg.accept()
            self._quick_ai_predict(game, model_key=chosen_key)
        ok_btn.clicked.connect(do_predict)
        cancel_btn = QPushButton("取消")
        cancel_btn.clicked.connect(dlg.reject)
        btn_row.addWidget(ok_btn)
        btn_row.addWidget(cancel_btn)
        lay.addLayout(btn_row)
        dlg.exec()

    def _quick_ai_predict(self, game: str, model_key: str = None):
        """福彩/体彩页「🤖 AI预测投注」按钮处理：
        弹出预测弹窗（多组、显示模型名、支持回填 & 直接投注）。
        此版本不依赖自选号码盘，直接弹出独立预测对话框。
        """
        if game not in self.history_data or not self.history_data[game]:
            QMessageBox.warning(self, "提示",
                f"暂无 {game} 历史数据，请先获取开奖数据后再使用 AI 预测")
            return

        # 回测更新权重
        self.backtest_predictions()
        # 如果外部传入了 model_key（来自「选择模型」），则使用它；否则自动选最优
        if model_key is None:
            model_key = self._best_model_key(game)
        model_name = PREDICTION_MODELS.get(model_key, {}).get("name", "自动")

        dlg = QDialog(self)
        dlg.setWindowTitle(f"🤖 {game} AI预测 — {model_name}")
        dlg.setMinimumWidth(360)
        dlg.resize(max(460, int(QApplication.primaryScreen().availableGeometry().width()*0.42)),
                   max(520, int(QApplication.primaryScreen().availableGeometry().height()*0.80)))
        lay = QVBoxLayout(dlg)

        # 标题信息
        title_lbl = QLabel(f"当前最优模型：【{model_name}】")
        title_lbl.setStyleSheet("font-weight:bold; font-size:14px; color:#1a6e2a; padding:4px;")
        lay.addWidget(title_lbl)

        # 命中率报告
        report = self.get_model_accuracy_report(game)
        rpt_lbl = QLabel(report if report.strip() else "  暂无命中率数据（继续使用后自动积累）")
        rpt_lbl.setStyleSheet("font-size:11px; color:#555; padding:2px 8px;")
        rpt_lbl.setWordWrap(True)
        lay.addWidget(rpt_lbl)

        sep = QFrame(); sep.setFrameShape(QFrame.HLine)
        lay.addWidget(sep)

        # 预测组数
        cnt_row = QHBoxLayout()
        cnt_row.addWidget(QLabel("生成组数:"))
        cnt_spin = QSpinBox()
        cnt_spin.setRange(1, 20)
        cnt_spin.setValue(5)
        cnt_row.addWidget(cnt_spin)
        cnt_row.addStretch()
        lay.addLayout(cnt_row)

        # 追加投注（仅大乐透）
        add_check = None
        if game == "大乐透":
            add_check = QCheckBox("追加投注（每注 +1 元）")
            lay.addWidget(add_check)

        # 结果展示
        result_edit = QTextEdit()
        result_edit.setReadOnly(True)
        result_edit.setMinimumHeight(200)
        lay.addWidget(result_edit)

        recs: list = []

        def fmt_rec(rec):
            if game == "双色球":
                return f"红球: {', '.join(map(str,rec['red']))}  蓝球: {rec['blue']}"
            elif game == "大乐透":
                return f"前区: {', '.join(map(str,rec['front']))}  后区: {', '.join(map(str,rec['back']))}"
            elif game in ("快乐8", "七乐彩"):
                return f"号码: {', '.join(map(str,rec['main']))}"
            else:
                return f"号码: {' '.join(map(str,rec['pos']))}"

        def gen_pred():
            nonlocal recs
            n = cnt_spin.value()
            recs = [self.predict_for_game(game, model_key) for _ in range(n)]
            for r in recs:
                self._record_prediction(game, model_key, r)
            txt = "\n".join(f"{i+1}. {fmt_rec(r)}" for i, r in enumerate(recs))
            result_edit.setPlainText(f"【{model_name}】为 {game} 推荐 {n} 组号码：\n\n{txt}")

        gen_btn = QPushButton("🔄 重新生成")
        gen_btn.clicked.connect(gen_pred)
        lay.addWidget(gen_btn)
        gen_pred()  # 初始生成

        # 操作按钮
        btn_row = QHBoxLayout()

        bet_btn = QPushButton("💰 全部直接投注")
        bet_btn.setStyleSheet("background:#E67E22; color:white; font-weight:bold; padding:6px;")
        def do_bet():
            if not recs: return
            additional = bool(add_check and add_check.isChecked())
            price = 3.0 if additional else 2.0
            lines = [fmt_rec(r) for r in recs]
            bets   = len(lines)
            amount = bets * price
            target = self.get_default_target_issue(game)
            reply = QMessageBox.question(
                dlg, "确认投注",
                f"模型：{model_name}\n共 {bets} 注，金额 ¥{amount:.2f}"
                + ("（含追加）" if additional else "") + "\n\n确认添加到投注记录？",
                QMessageBox.Yes | QMessageBox.No)
            if reply == QMessageBox.Yes:
                self.add_betting_record(
                    game, f"AI预测-{model_name}",
                    "\n".join(lines), bets, amount,
                    target_issue=target, additional=additional)
                QMessageBox.information(dlg, "成功", f"已添加 {bets} 注 AI 预测投注！")
                dlg.accept()
        bet_btn.clicked.connect(do_bet)

        close_btn = QPushButton("关闭")
        close_btn.clicked.connect(dlg.reject)

        btn_row.addWidget(bet_btn)
        btn_row.addWidget(close_btn)
        lay.addLayout(btn_row)
        dlg.exec()

    def _show_predict_dialog(self, game: str, parent_dialog,
                             apply_fn, update_count_fn, model_key: str = None):
        """通用预测推荐弹窗：支持多组预测、切换模型、选择投注方式（单式/复式/胆拖），
        一键回填或直接多组投注。
        apply_fn(pred): 把预测号码回填到号码盘
        model_key: 可从外部指定模型，None 时自动选最优
        """
        self.backtest_predictions()
        if model_key is None:
            model_key = self._best_model_key(game)

        dlg = QDialog(parent_dialog)
        dlg.setWindowTitle(f"{game} AI 预测推荐")
        dlg.setMinimumWidth(440)
        lay = QVBoxLayout(dlg)

        # ── 模型选择 ──
        model_sel_row = QHBoxLayout()
        model_sel_row.addWidget(QLabel("预测模型:"))
        model_sel_combo = QComboBox()
        for k, v in PREDICTION_MODELS.items():
            model_sel_combo.addItem(v["name"], k)
        for i in range(model_sel_combo.count()):
            if model_sel_combo.itemData(i) == model_key:
                model_sel_combo.setCurrentIndex(i); break
        model_sel_row.addWidget(model_sel_combo)
        lay.addLayout(model_sel_row)

        lbl = QLabel()
        lbl.setStyleSheet("font-weight:bold; font-size:13px; color:#1a6e2a;")
        def _update_model_lbl():
            mk = model_sel_combo.currentData()
            mn = PREDICTION_MODELS.get(mk, {}).get("name", "?")
            lbl.setText(f"已选择模型：【{mn}】")
        model_sel_combo.currentIndexChanged.connect(_update_model_lbl)
        _update_model_lbl()
        lay.addWidget(lbl)

        # ── 命中率报告 ──
        report = self.get_model_accuracy_report(game)
        rpt_lbl = QLabel(report if report.strip() else "  暂无命中率数据（继续使用可积累）")
        rpt_lbl.setStyleSheet("font-size:11px; color:#555;")
        rpt_lbl.setWordWrap(True)
        lay.addWidget(rpt_lbl)

        # ── 组数 + 投注方式 ──
        opt_row = QHBoxLayout()
        opt_row.addWidget(QLabel("预测组数:"))
        cnt_spin = QSpinBox()
        cnt_spin.setRange(1, 30)
        cnt_spin.setValue(5)
        opt_row.addWidget(cnt_spin)
        opt_row.addWidget(QLabel("  投注方式:"))
        bet_type_combo = QComboBox()
        if game in ("双色球", "大乐透", "快乐8", "七乐彩"):
            bet_type_combo.addItems(["单式", "复式", "胆拖"])
        else:
            bet_type_combo.addItems(["单式", "复式"])
        opt_row.addWidget(bet_type_combo)
        if game == "大乐透":
            add_chk = QCheckBox("追加")
            opt_row.addWidget(add_chk)
        else:
            add_chk = None
        lay.addLayout(opt_row)

        # ── 生成区 ──
        result_edit = QTextEdit()
        result_edit.setReadOnly(True)
        result_edit.setMinimumHeight(160)
        lay.addWidget(result_edit)
        recs: list = []

        def _fmt_rec(rec):
            if game == "双色球":
                return f"红球: {', '.join(map(str,rec['red']))}  蓝球: {rec['blue']}"
            elif game == "大乐透":
                return f"前区: {', '.join(map(str,rec['front']))}  后区: {', '.join(map(str,rec['back']))}"
            elif game in ("快乐8","七乐彩"):
                return f"号码: {', '.join(map(str,rec['main']))}"
            else:
                return f"号码: {' '.join(map(str,rec['pos']))}"

        def _rec_to_lines(rec, bt):
            """把预测 dict 按投注方式展开为投注行列表"""
            if game == "双色球":
                red  = sorted(rec.get("red",  []))
                blue = [rec.get("blue", 1)]
                if bt == "单式":
                    return [f"红球: {', '.join(map(str,red))} 蓝球: {blue[0]}"]
                elif bt == "复式" and len(red) >= 6:
                    return [f"红球: {', '.join(map(str,list(rc)))} 蓝球: {bc}"
                            for rc in combinations(red, 6) for bc in blue]
                else:  # 胆拖
                    dan = red[:2]; tuo = red[2:]
                    return ([f"红球: {', '.join(map(str,sorted(list(dan)+list(c))))} 蓝球: {blue[0]}"
                             for c in combinations(tuo, 4)] if len(tuo) >= 4
                            else [f"红球: {', '.join(map(str,red[:6]))} 蓝球: {blue[0]}"])
            elif game == "大乐透":
                front = sorted(rec.get("front", []))
                back  = sorted(rec.get("back",  []))
                if bt == "单式":
                    return [f"前区: {', '.join(map(str,front))} 后区: {', '.join(map(str,back))}"]
                elif bt == "复式" and len(front) >= 5 and len(back) >= 2:
                    return [f"前区: {', '.join(map(str,list(fc)))} 后区: {', '.join(map(str,list(bc)))}"
                            for fc in combinations(front, 5) for bc in combinations(back, 2)]
                else:
                    dan = front[:2]; tuo = front[2:]
                    return ([f"前区: {', '.join(map(str,sorted(list(dan)+list(c))))} 后区: {', '.join(map(str,back))}"
                             for c in combinations(tuo, 3)] if len(tuo) >= 3
                            else [f"前区: {', '.join(map(str,front[:5]))} 后区: {', '.join(map(str,back[:2]))}"])
            elif game in ("快乐8","七乐彩"):
                nums = sorted(rec.get("main", []))
                need = 7 if game == "七乐彩" else 10
                if bt == "复式" and len(nums) > need:
                    return [f"号码: {', '.join(map(str,list(c)))}" for c in combinations(nums, need)]
                return [f"号码: {', '.join(map(str,nums[:need]))}"]
            else:
                pos = rec.get("pos", [])
                return [f"号码: {' '.join(map(str,pos))}"]

        def _gen():
            nonlocal recs
            n  = cnt_spin.value()
            mk = model_sel_combo.currentData()
            recs = [self.predict_for_game(game, mk) for _ in range(n)]
            for r in recs:
                self._record_prediction(game, mk, r)
            mn = PREDICTION_MODELS.get(mk, {}).get("name", mk)
            lbl.setText(f"已选择模型：【{mn}】  已生成 {n} 组")
            lines = [f"{i}. {_fmt_rec(r)}" for i, r in enumerate(recs, 1)]
            result_edit.setPlainText("\n".join(lines))

        gen_btn = QPushButton("🔄 生成预测号码")
        gen_btn.setStyleSheet("background:#2980B9;color:white;font-weight:bold;padding:5px;")
        gen_btn.clicked.connect(_gen)
        lay.addWidget(gen_btn)
        _gen()  # 自动生成一次

        # ── 操作按钮 ──
        btn_row = QHBoxLayout()

        apply_btn = QPushButton("✔ 回填第1组")
        apply_btn.setStyleSheet("background:#27AE60;color:white;font-weight:bold;")
        def _apply_first():
            if recs:
                apply_fn(recs[0])
                update_count_fn()
                dlg.accept()
        apply_btn.clicked.connect(_apply_first)

        bet_btn = QPushButton("💰 全部投注")
        bet_btn.setStyleSheet("background:#E67E22;color:white;font-weight:bold;")
        def _bet_all():
            if not recs: return
            bt    = bet_type_combo.currentText()
            addi  = bool(add_chk and add_chk.isChecked())
            price = 3.0 if addi else 2.0
            all_lines = []
            for rec in recs:
                all_lines.extend(_rec_to_lines(rec, bt))
            bets   = len(all_lines)
            amount = bets * price
            mk     = model_sel_combo.currentData()
            mn     = PREDICTION_MODELS.get(mk, {}).get("name", mk)
            target = self.get_default_target_issue(game)
            reply  = QMessageBox.question(
                dlg, "确认投注",
                f"模型：{mn}  方式：{bt}\n共 {bets} 注，金额 ¥{amount:.2f}\n确认？",
                QMessageBox.Yes | QMessageBox.No)
            if reply == QMessageBox.Yes:
                self.add_betting_record(game, f"AI{bt}-{mn}",
                                        "\n".join(all_lines), bets, amount,
                                        target_issue=target, additional=addi)
                QMessageBox.information(dlg, "成功", f"✓ 已添加 {bets} 注！")
                dlg.accept()
        bet_btn.clicked.connect(_bet_all)

        cancel_btn = QPushButton("关闭")
        cancel_btn.clicked.connect(dlg.reject)
        btn_row.addWidget(apply_btn)
        btn_row.addWidget(bet_btn)
        btn_row.addWidget(cancel_btn)
        lay.addLayout(btn_row)
        dlg.exec()

    def predict_for_game(self, game_type: str, model_key: str = None) -> dict:
        """根据游戏类型和模型生成一注预测，返回结构化 dict。
        model_key=None 时自动选择历史命中率最高的模型。
        每次预测自动记录到 prediction_log 以供回测机器学习。
        """
        if model_key is None:
            model_key = self._best_model_key(game_type)

        def _pick(area, count):
            return self._pick_for_model_unified(game_type, area, count, model_key)

        if game_type == "双色球":
            pred = {"red": _pick("red", 6), "blue": _pick("blue", 1)[0]}
        elif game_type == "大乐透":
            pred = {"front": _pick("front", 5), "back": _pick("back", 2)}
        elif game_type == "快乐8":
            pred = {"main": _pick("main", 10)}
        elif game_type == "七乐彩":
            pred = {"main": _pick("main", 7)}
        else:
            pos_counts = {"3D": 3, "排列三": 3, "排列五": 5, "七星彩": 7}
            n = pos_counts.get(game_type, 3)
            pred = {"pos": [_pick(f"pos{i+1}", 1)[0] for i in range(n)]}

        # ── 自动记录到预测日志，供 backtest_predictions 回测 ──
        try:
            target_issue = self.get_default_target_issue(game_type)
            if target_issue:
                # 避免同一期重复记录相同模型
                already = any(
                    e.get("game") == game_type and
                    e.get("issue") == target_issue and
                    e.get("model_key") == model_key
                    for e in self.prediction_log
                )
                if not already and not getattr(self, "_backtesting", False):
                    self.prediction_log.append({
                        "game": game_type,
                        "issue": target_issue,
                        "model_key": model_key,
                        "prediction": pred,
                        "matched": None,
                    })
        except Exception as _e:
            logger.debug(f"predict_for_game log error: {_e}")

        return pred

    def _best_model_key(self, game_type: str) -> str:
        """返回该游戏历史命中率最高的模型 key。
        有足够历史数据（≥3次预测）时按命中率选择，否则返回贝叶斯（6）作为默认。
        """
        # V43: 优先用全历史回测成绩（样本更系统），无合格模型则退回实时跟踪成绩
        scores = self.full_backtest_scores.get(game_type, {})
        if not any(d.get("total", 0) >= 3 for d in scores.values()):
            scores = self.model_scores.get(game_type, {})
        best, best_rate = "6", 0.0  # 默认贝叶斯
        qualified = [(k, d) for k, d in scores.items() if d.get("total", 0) >= 3]
        for key, data in qualified:
            total = data.get("total", 0)
            rate  = data.get("hits", 0) / total
            if rate > best_rate:
                best_rate, best = rate, key
        return best


    def _ml_area_pool(self, game: str, area: str) -> list:
        """真实机器学习模型使用的合法号码池。"""
        if game == "双色球":
            return list(range(1, 34)) if area == "red" else list(range(1, 17))
        if game == "大乐透":
            return list(range(1, 36)) if area == "front" else list(range(1, 13))
        if game == "快乐8":
            return list(range(1, 81))
        if game == "七乐彩":
            return list(range(1, 31))
        if game == "七星彩":
            return list(range(0, 15)) if area == "pos7" else list(range(0, 10))
        if game in ("3D", "排列三", "排列五"):
            return list(range(0, 10))
        # 兜底：优先用已有频率表
        freq = self.frequency_data.get(game, {}).get(area, {})
        return sorted(freq.keys()) if freq else list(range(1, max(10, 2 * 10) + 1))

    def _ml_extract_area_values(self, game: str, nums: list, area: str) -> list:
        """从一期开奖结果中抽取指定区域/位置的号码，供机器学习训练。"""
        nums = [int(x) for x in nums]
        if not nums:
            return []
        if game == "双色球":
            if area == "red":
                return nums[:6]
            return nums[6:7] if len(nums) >= 7 else []
        if game == "大乐透":
            if area == "front":
                return nums[:5]
            return nums[5:7] if len(nums) >= 7 else []
        if game == "快乐8":
            return nums[:20]
        if game == "七乐彩":
            return nums[:7]
        if game in ("3D", "排列三", "排列五", "七星彩"):
            pos_map = {"3D": 3, "排列三": 3, "排列五": 5, "七星彩": 7}
            pos_count = pos_map.get(game, 3)
            # 兼容紧凑数字彩：464、040604、12345、0102030405、12345614。
            # 其中3D/排列三/排列五旧复制格式可能每位补成两位；七星彩第7位允许10-14。
            if len(nums) == 1 and isinstance(nums[0], int):
                raw = str(abs(int(nums[0])))
                if game == "七星彩":
                    if len(raw) <= 7:
                        vals = [int(ch) for ch in raw.zfill(7)[:7]]
                    elif len(raw) == 8:
                        vals = [int(ch) for ch in raw[:6]] + [int(raw[6:])]
                    else:
                        ss = raw.zfill(14)[-14:]
                        vals = [int(ss[i:i+2]) for i in range(0, 14, 2)]
                    if len(vals) >= 7:
                        vals = [max(0, min(9, int(x))) for x in vals[:6]] + [max(0, min(14, int(vals[6])))]
                else:
                    if len(raw) <= pos_count:
                        ss = raw.zfill(pos_count)
                        vals = [int(ch) for ch in ss[:pos_count]]
                    else:
                        ss = raw.zfill(pos_count * 2)[-(pos_count * 2):]
                        vals = [int(ss[i:i+2]) for i in range(0, pos_count * 2, 2)]
                        vals = [max(0, min(9, int(x))) for x in vals[:pos_count]]
            else:
                vals = nums[:pos_count]
            try:
                pi = int(str(area).replace("pos", "")) - 1
            except Exception:
                pi = 0
            if 0 <= pi < len(vals):
                return [vals[pi]]
            return []
        return nums

    def _ml_prepare_tabular_training(self, game: str, area: str, max_periods: int = 180):
        """构造真实监督学习训练集：历史窗口特征 -> 下一期是否命中该号码。"""
        import numpy as _np
        records = self.history_data.get(game, []) or []
        pool = self._ml_area_pool(game, area)
        if not records or not pool:
            return None
        # 多数接口记录为新到旧，这里倒序成旧到新，避免未来数据泄漏
        recent = list(reversed(records[:max_periods]))
        draws = []
        issues = []
        for rec in recent:
            vals = self._ml_extract_area_values(game, parse_draw_numbers(str(rec.get("开奖号码", ""))), area)
            vals = [v for v in vals if v in pool]
            if vals:
                draws.append(set(vals))
                issues.append(str(rec.get("期号", "")))
        if len(draws) < 12:
            return None
        window = min(12, max(5, len(draws)//4))
        pool_max = max(pool) if max(pool) > 0 else 1
        pool_min = min(pool)
        pool_span = max(1, pool_max - pool_min)

        def feat_for(n, prev_draws, idx):
            w = len(prev_draws) or 1
            freq_w = sum(1 for d in prev_draws if n in d) / w
            last3 = prev_draws[-3:]
            last5 = prev_draws[-5:]
            freq3 = sum(1 for d in last3 if n in d) / max(1, len(last3))
            freq5 = sum(1 for d in last5 if n in d) / max(1, len(last5))
            omission = 0
            for d in reversed(prev_draws):
                if n in d:
                    break
                omission += 1
            trend = freq3 - freq_w
            last_hit = 1.0 if prev_draws and n in prev_draws[-1] else 0.0
            even = 1.0 if n % 2 == 0 else 0.0
            small = 1.0 if n <= (pool_min + pool_max) / 2 else 0.0
            idx_norm = idx / max(1, len(draws))
            # V74增强特征：在原频率/遗漏基础上加入和值、跨度、区间、邻号、重号、AC近似等彩票专用特征。
            flat_prev = sorted({x for d in prev_draws for x in d})
            last_draw = sorted(prev_draws[-1]) if prev_draws else []
            last_sum = sum(last_draw) / max(1, len(last_draw) * pool_max) if last_draw else 0.0
            last_span = ((max(last_draw) - min(last_draw)) / pool_span) if len(last_draw) >= 2 else 0.0
            neighbor = 1.0 if any(abs(n - x) == 1 for x in last_draw) else 0.0
            repeat3 = sum(1 for d in last3 if n in d) / max(1, len(last3))
            zone4 = int(((n - pool_min) / max(1, pool_span + 1e-9)) * 4)
            zone4 = min(3, max(0, zone4)) / 3.0
            # AC近似：上一期不同差值数量归一化，用于双色球/大乐透/七乐彩等乐透型玩法。
            if len(last_draw) >= 2:
                diffs = {abs(last_draw[a] - last_draw[b]) for a in range(len(last_draw)) for b in range(a+1, len(last_draw))}
                ac_norm = min(1.0, len(diffs) / max(1, len(last_draw) * (len(last_draw)-1) / 2))
            else:
                ac_norm = 0.0
            return [
                (n - pool_min) / pool_span,
                freq_w, freq3, freq5,
                min(1.0, omission / max(1, w)),
                trend, last_hit, even, small, idx_norm,
                last_sum, last_span, neighbor, repeat3, zone4, ac_norm,
            ]

        X, y = [], []
        # 限制样本量，避免安卓端训练过慢；正负样本仍然来自真实历史
        start_i = window
        for i in range(start_i, len(draws)):
            prev = draws[max(0, i-window):i]
            target = draws[i]
            for n in pool:
                X.append(feat_for(n, prev, i))
                y.append(1 if n in target else 0)
        cur_prev = draws[-window:]
        X_now = [feat_for(n, cur_prev, len(draws)) for n in pool]
        X = _np.asarray(X, dtype="float32")
        y = _np.asarray(y, dtype="int32")
        X_now = _np.asarray(X_now, dtype="float32")
        if len(set(y.tolist())) < 2:
            return None
        return X, y, X_now, pool, draws, window

    def _ml_prepare_sequence_training(self, game: str, area: str, max_periods: int = 180, seq_len: int = 12):
        """构造 LSTM/GRU/Transformer 序列训练集。"""
        import numpy as _np
        records = self.history_data.get(game, []) or []
        pool = self._ml_area_pool(game, area)
        if not records or not pool:
            return None
        recent = list(reversed(records[:max_periods]))
        draws = []
        for rec in recent:
            vals = self._ml_extract_area_values(game, parse_draw_numbers(str(rec.get("开奖号码", ""))), area)
            vals = [v for v in vals if v in pool]
            if vals:
                draws.append(set(vals))
        if len(draws) < seq_len + 3:
            return None
        pool_max = max(pool) if max(pool) > 0 else 1
        pool_min = min(pool)
        pool_span = max(1, pool_max - pool_min)
        X, y = [], []
        for i in range(seq_len, len(draws)):
            prev = draws[i-seq_len:i]
            target = draws[i]
            for n in pool:
                seq = []
                rolling = 0
                for j, d in enumerate(prev):
                    hit = 1.0 if n in d else 0.0
                    rolling += hit
                    seq.append([hit, rolling / (j + 1), (n - pool_min) / pool_span])
                X.append(seq)
                y.append(1 if n in target else 0)
        X_now = []
        prev = draws[-seq_len:]
        for n in pool:
            seq = []
            rolling = 0
            for j, d in enumerate(prev):
                hit = 1.0 if n in d else 0.0
                rolling += hit
                seq.append([hit, rolling / (j + 1), (n - pool_min) / pool_span])
            X_now.append(seq)
        X = _np.asarray(X, dtype="float32")
        y = _np.asarray(y, dtype="int32")
        X_now = _np.asarray(X_now, dtype="float32")
        if len(set(y.tolist())) < 2:
            return None
        return X, y, X_now, pool

    def _real_ml_predict_area(self, game: str, area: str, count: int, model_key: str) -> list:
        """真实机器学习预测入口。
        支持 RandomForestClassifier / ExtraTrees / HistGradientBoosting / CatBoost / XGBoost可选 / LightGBM可选 / LSTM / GRU / Transformer。
        若手机环境缺少对应第三方库，会自动退回到可用的 sklearn/规则模型，保证程序不崩。
        """
        cache = getattr(self, "_real_ml_prediction_cache", None)
        if cache is None:
            cache = {}
            self._real_ml_prediction_cache = cache
        records = self.history_data.get(game, []) or []
        latest_issue = str(records[0].get("期号", "")) if records else ""
        cache_key = (game, area, int(count), str(model_key), len(records), latest_issue)
        if cache_key in cache:
            return list(cache[cache_key])

        def _finish(pool, prob):
            ranked = sorted(pool, key=lambda n: (-float(prob.get(n, 0.0)), n))
            result = sorted(ranked[:count])
            cache[cache_key] = result
            return result

        # 深度学习模型：优先 TensorFlow/Keras 真实训练
        if str(model_key) in ("3", "21", "23", "28"):
            seq_data = self._ml_prepare_sequence_training(game, area)
            if seq_data is not None:
                X, y, X_now, pool = seq_data
                try:
                    import tensorflow as _tf
                    from tensorflow.keras import layers as _layers, models as _models
                    _tf.random.set_seed(20260606)
                    inp = _layers.Input(shape=(X.shape[1], X.shape[2]))
                    if str(model_key) == "3":
                        x = _layers.LSTM(16, dropout=0.05)(inp)
                    elif str(model_key) == "23":
                        x = _layers.GRU(16, dropout=0.05)(inp)
                    elif str(model_key) == "28":
                        # TFT轻量版：时序门控 + 多头注意力融合，适合安卓端低成本训练。
                        r = _layers.GRU(12, return_sequences=True, dropout=0.05)(inp)
                        att = _layers.MultiHeadAttention(num_heads=2, key_dim=8)(r, r)
                        x = _layers.Add()([r, att])
                        x = _layers.LayerNormalization()(x)
                        x = _layers.GlobalAveragePooling1D()(x)
                    else:
                        att = _layers.MultiHeadAttention(num_heads=2, key_dim=8)(inp, inp)
                        x = _layers.Add()([inp, att])
                        x = _layers.LayerNormalization()(x)
                        x = _layers.GlobalAveragePooling1D()(x)
                    x = _layers.Dense(12, activation="relu")(x)
                    out = _layers.Dense(1, activation="sigmoid")(x)
                    model = _models.Model(inp, out)
                    model.compile(optimizer="adam", loss="binary_crossentropy")
                    model.fit(X, y, epochs=8, batch_size=64, verbose=0)
                    pred = model.predict(X_now, verbose=0).reshape(-1)
                    prob = {n: float(pred[i]) for i, n in enumerate(pool)}
                    return _finish(pool, prob)
                except Exception as e:
                    logger.warning(f"真实深度学习模型{model_key}不可用/训练失败: {e}，退回MLP/梯度模型")
            # 深度学习不可用时使用真实神经网络 MLPClassifier 兜底
            tab = self._ml_prepare_tabular_training(game, area)
            if tab is not None:
                X, y, X_now, pool, _, _ = tab
                try:
                    from sklearn.neural_network import MLPClassifier
                    clf = MLPClassifier(hidden_layer_sizes=(24, 12), max_iter=120, random_state=20260606)
                    clf.fit(X, y)
                    pred = clf.predict_proba(X_now)[:, 1]
                    prob = {n: float(pred[i]) for i, n in enumerate(pool)}
                    return _finish(pool, prob)
                except Exception as e:
                    logger.warning(f"MLP兜底训练失败: {e}")

        tab = self._ml_prepare_tabular_training(game, area)
        if tab is None:
            return self.pick_numbers_by_coldhot(game, area, count)
        X, y, X_now, pool, _, _ = tab

        def _warn_once(key, msg):
            warned = getattr(self, "_ml_optional_warned", set())
            if key not in warned:
                logger.warning(msg)
                warned.add(key)
                self._ml_optional_warned = warned

        def _fit_predict_sklearn(clf):
            clf.fit(X, y)
            if hasattr(clf, "predict_proba"):
                pred = clf.predict_proba(X_now)[:, 1]
            else:
                pred = clf.decision_function(X_now)
            prob = {n: float(pred[i]) for i, n in enumerate(pool)}
            return _finish(pool, prob)

        try:
            mk = str(model_key)
            if mk == "1":
                from sklearn.ensemble import RandomForestClassifier
                clf = RandomForestClassifier(
                    n_estimators=50, max_depth=8, min_samples_leaf=2,
                    class_weight="balanced", random_state=20260606, n_jobs=1)
            elif mk == "30":
                from sklearn.ensemble import ExtraTreesClassifier
                clf = ExtraTreesClassifier(
                    n_estimators=70, max_depth=9, min_samples_leaf=2,
                    class_weight="balanced", random_state=20260606, n_jobs=1)
            elif mk == "31":
                from sklearn.ensemble import HistGradientBoostingClassifier
                clf = HistGradientBoostingClassifier(
                    max_iter=70, learning_rate=0.06, max_leaf_nodes=15,
                    l2_regularization=0.05, random_state=20260606)
            elif mk == "15":
                try:
                    from xgboost import XGBClassifier
                    clf = XGBClassifier(
                        n_estimators=30, max_depth=2, learning_rate=0.08,
                        subsample=0.9, colsample_bytree=0.9, eval_metric="logloss",
                        random_state=20260606, verbosity=0, n_jobs=1, tree_method="hist")
                except Exception as _e:
                    _warn_once("xgboost", f"XGBoost不可用({_e})，自动改用ExtraTrees安卓稳健模型")
                    from sklearn.ensemble import ExtraTreesClassifier
                    clf = ExtraTreesClassifier(
                        n_estimators=70, max_depth=9, min_samples_leaf=2,
                        class_weight="balanced", random_state=20260606, n_jobs=1)
            elif mk == "22":
                try:
                    from lightgbm import LGBMClassifier
                    clf = LGBMClassifier(
                        n_estimators=40, max_depth=-1, learning_rate=0.06,
                        num_leaves=12, class_weight="balanced", random_state=20260606, verbose=-1, n_jobs=1, force_col_wise=True)
                except Exception as _e:
                    _warn_once("lightgbm", f"LightGBM不可用({_e})，自动改用HistGradient安卓稳健模型")
                    from sklearn.ensemble import HistGradientBoostingClassifier
                    clf = HistGradientBoostingClassifier(
                        max_iter=70, learning_rate=0.06, max_leaf_nodes=15,
                        l2_regularization=0.05, random_state=20260606)
            elif mk == "26":
                try:
                    from catboost import CatBoostClassifier
                    clf = CatBoostClassifier(
                        iterations=40, depth=4, learning_rate=0.06,
                        loss_function="Logloss", verbose=False, random_seed=20260606, thread_count=1)
                except Exception as _e:
                    _warn_once("catboost", f"CatBoost不可用({_e})，自动改用RandomForest稳健模型")
                    from sklearn.ensemble import RandomForestClassifier
                    clf = RandomForestClassifier(
                        n_estimators=50, max_depth=8, min_samples_leaf=2,
                        class_weight="balanced", random_state=20260606, n_jobs=1)
            elif mk == "27":
                # TabNet真实训练；安卓环境缺库时会进入外层except并自动回退。
                from pytorch_tabnet.tab_model import TabNetClassifier
                clf = TabNetClassifier(seed=20260606, verbose=0)
                clf.fit(X, y, max_epochs=12, patience=4, batch_size=128, virtual_batch_size=32)
                pred = clf.predict_proba(X_now)[:, 1]
                prob = {n: float(pred[i]) for i, n in enumerate(pool)}
                return _finish(pool, prob)
            elif mk == "29":
                # AutoGluon自动冠军；缺库时回退。
                import tempfile as _tempfile
                import pandas as _pd
                from autogluon.tabular import TabularPredictor
                cols = [f"f{i}" for i in range(X.shape[1])]
                train_df = _pd.DataFrame(X, columns=cols); train_df["label"] = y
                pred_df = _pd.DataFrame(X_now, columns=cols)
                ag_path = _tempfile.mkdtemp(prefix="caile_ag_")
                predictor = TabularPredictor(label="label", path=ag_path, verbosity=0).fit(
                    train_df, time_limit=12, presets="medium_quality", num_cpus=1)
                proba = predictor.predict_proba(pred_df)
                pred = proba[1].values if 1 in proba.columns else proba.iloc[:, -1].values
                prob = {n: float(pred[i]) for i, n in enumerate(pool)}
                return _finish(pool, prob)
            else:
                from sklearn.ensemble import GradientBoostingClassifier
                clf = GradientBoostingClassifier(random_state=20260606)
            clf.fit(X, y)
            if hasattr(clf, "predict_proba"):
                pred = clf.predict_proba(X_now)[:, 1]
            else:
                pred = clf.decision_function(X_now)
            prob = {n: float(pred[i]) for i, n in enumerate(pool)}
            return _finish(pool, prob)
        except Exception as e:
            logger.warning(f"真实机器学习模型{model_key}训练失败: {e}，回退冷热选号")
            return self.pick_numbers_by_coldhot(game, area, count)

    def _pick_for_model_unified(self, game: str, area: str, count: int, model_key: str) -> list:
        """统一模型选号调度 — 每个模型使用真实算法实现。
        所有算法纯 Python + numpy，不依赖 sklearn，手机端可用。
        """
        # 真实机器学习模型：先用历史开奖构造训练集并训练，再输出下一期概率最高号码。
        if str(model_key) in ("1", "3", "15", "21", "22", "23", "26", "27", "28", "29", "30", "31"):
            try:
                return self._real_ml_predict_area(game, area, count, str(model_key))
            except Exception as _ml_e:
                logger.warning(f"真实ML模型调度失败: {_ml_e}，改用原规则模型")

        freq    = self.frequency_data.get(game, {}).get(area, {})
        records = self.history_data.get(game, [])

        # ─── 工具函数 ──────────────────────────────────────────
        def _all_nums():
            """返回 (nums, weights) 基于历史频率"""
            nums    = sorted(freq.keys()) if freq else list(range(1, count + 10))
            weights = [freq.get(n, 1) for n in nums]
            return nums, weights

        def _safe_sample(pool, k):
            pool = list(pool)
            return sorted(pool)[:min(k, len(pool))]

        def _draw_series():
            """返回历史开奖号码二维列表（每期一行）"""
            series = []
            for rec in records[:100]:
                nums = parse_draw_numbers(rec.get("开奖号码", ""))
                if nums:
                    series.append(nums)
            return series

        # ─── Model 1: 随机森林（多棵决策树投票，用遗漏期×频率做特征）───
        def _random_forest():
            nums, weights = _all_nums()
            omission = self.last_omission_data.get(game, {}).get(area, {})
            # 特征 = 频率 * (1 + 遗漏/平均遗漏)
            avg_om = sum(omission.values()) / len(omission) + 1 if omission else 1
            scores = {}
            for n, w in zip(nums, weights):
                om = omission.get(n, 0)
                # 森林票：高频低遗漏 vs 低频高遗漏随机投票
                tree_votes = 0
                for _ in range(7):  # 7棵树
                    threshold = 0.5
                    freq_score   = w / (max(weights) + 1)
                    om_score     = om / (avg_om * 2 + 1)
                    score = freq_score * (1 - threshold) + om_score * threshold
                    tree_votes += score
                scores[n] = tree_votes
            ranked = sorted(scores, key=lambda x: -scores[x])
            # 确定性：取分数最高的 count 个（模型真实最优预测，可复现）
            return sorted(ranked[:count])

        # ─── Model 2: 线性回归（用遗漏期数线性预测下一期出现概率）────
        def _linear_regression():
            series = _draw_series()
            if len(series) < 5:
                return self.pick_numbers_by_coldhot(game, area, count)
            nums, _ = _all_nums()
            # 对每个号码，以最近20期是否出现(0/1)做线性拟合，预测下一期
            n_look = min(20, len(series))
            scores = {}
            for n in nums:
                y = [1.0 if n in draw else 0.0 for draw in reversed(series[:n_look])]
                # 简单线性回归 y = a*x + b，x=[0,1,...,n-1]
                xs = list(range(n_look))
                x_mean = (n_look - 1) / 2
                y_mean = sum(y) / n_look
                num_  = sum((xs[i] - x_mean) * (y[i] - y_mean) for i in range(n_look))
                den_  = sum((xs[i] - x_mean) ** 2 for i in range(n_look)) + 1e-9
                slope = num_ / den_
                intercept = y_mean - slope * x_mean
                predicted = slope * n_look + intercept
                scores[n] = max(0.0, predicted)
            ranked = sorted(scores, key=lambda x: -scores[x])
            pool   = ranked[:max(count * 2, 10)]
            pool_w = [scores[n] + 0.01 for n in pool]
            return sorted(pool[:count])

        # ─── Model 3: LSTM（指数平滑 EMA 模拟时序记忆）─────────────
        def _lstm():
            series = _draw_series()
            if len(series) < 3:
                return self.pick_numbers_by_coldhot(game, area, count)
            nums, _ = _all_nums()
            alpha = 0.35  # EMA 衰减系数
            ema = {n: 0.0 for n in nums}
            for draw in reversed(series[:50]):
                for n in nums:
                    val = 1.0 if n in draw else 0.0
                    ema[n] = alpha * val + (1 - alpha) * ema[n]
            ranked = sorted(nums, key=lambda x: -ema[x])
            pool   = ranked[:max(count * 2, 10)]
            pool_w = [ema[n] + 0.01 for n in pool]
            return sorted(pool[:count])

        # ─── Model 4: 区间模型（均匀分段，每段各取）──────────────────
        def _interval():
            nums, weights = _all_nums()
            if len(nums) < 3:
                return _safe_sample(nums, count)
            n = len(nums)
            k = min(3, count)
            seg_size = n // k
            result, seen = [], set()
            for i in range(k):
                seg = nums[i * seg_size: (i + 1) * seg_size]
                seg_w = [weights[i * seg_size + j] for j in range(len(seg))]
                if not seg:
                    continue
                # 确定性：每段取权重最高的号码
                best = max(range(len(seg)), key=lambda j: seg_w[j])
                if seg[best] not in seen:
                    seen.add(seg[best]); result.append(seg[best])
            if len(result) < count:
                remaining = sorted([x for x in nums if x not in seen],
                                   key=lambda x: -weights[nums.index(x)])
                for e in remaining:
                    seen.add(e); result.append(e)
                    if len(result) == count: break
            return sorted(result[:count])

        # ─── Model 5: 马尔科夫链（一阶转移矩阵）─────────────────────
        def _markov():
            series = _draw_series()
            if len(series) < 2:
                return self.pick_numbers_by_coldhot(game, area, count)
            nums, _ = _all_nums()
            latest = set(series[0])
            trans  = {n: {} for n in nums}
            for i in range(len(series) - 1):
                cur  = set(series[i])
                nxt  = set(series[i + 1])
                for n in cur:
                    for m in nxt:
                        if n in trans:
                            trans[n][m] = trans[n].get(m, 0) + 1
            # 从最近一期出现的号码出发，按转移概率找下一期
            scores = {n: 0 for n in nums}
            for src in latest:
                if src in trans:
                    for dst, cnt in trans[src].items():
                        if dst in scores:
                            scores[dst] += cnt
            if all(v == 0 for v in scores.values()):
                return self.pick_numbers_by_coldhot(game, area, count)
            ranked = sorted(nums, key=lambda x: -scores[x])
            pool   = ranked[:max(count * 2, 12)]
            pool_w = [scores[n] + 0.1 for n in pool]
            return sorted(pool[:count])

        # ─── Model 6: 贝叶斯（Dirichlet 先验 + 历史频率后验）─────────
        def _bayesian():
            nums, _ = _all_nums()
            alpha   = 2.0  # Dirichlet 先验参数（平滑强度）
            posterior = {n: freq.get(n, 0) + alpha for n in nums}
            total     = sum(posterior.values())
            probs     = [posterior[n] / total for n in nums]
            # 确定性：取后验概率最高的 count 个
            ranked = sorted(nums, key=lambda x: -posterior[x])
            return sorted(ranked[:count])

        # ─── Model 7: 分形模型（用 Hurst 指数衡量持续性趋势）─────────
        def _fractal():
            series = _draw_series()
            if len(series) < 8:
                return _bayesian()
            nums, _ = _all_nums()
            scores  = {}
            for n in nums:
                # 构建出现序列
                ts = [1.0 if n in draw else 0.0 for draw in series[:40]]
                if len(ts) < 8:
                    scores[n] = freq.get(n, 1)
                    continue
                # R/S 分析估算 Hurst 指数（简化版）
                n_seg = len(ts) // 4
                rs_list = []
                for seg_start in range(0, len(ts) - n_seg, n_seg):
                    seg = ts[seg_start:seg_start + n_seg]
                    mean_s = sum(seg) / len(seg)
                    dev    = [x - mean_s for x in seg]
                    cumdev = []
                    c = 0
                    for d in dev:
                        c += d; cumdev.append(c)
                    R = max(cumdev) - min(cumdev)
                    S = (sum((x - mean_s) ** 2 for x in seg) / len(seg)) ** 0.5 + 1e-9
                    rs_list.append(R / S)
                hurst = sum(rs_list) / len(rs_list) if rs_list else 0.5
                recent_appear = sum(ts[:10])
                # Hurst > 0.5 → 趋势持续（近期高则得分高）
                if hurst > 0.5:
                    scores[n] = freq.get(n, 1) * (1 + recent_appear * 0.3)
                else:
                    scores[n] = freq.get(n, 1) * (1 + (10 - recent_appear) * 0.2)
            ranked = sorted(nums, key=lambda x: -scores.get(x, 1))
            pool   = ranked[:max(count * 2, 10)]
            pool_w = [scores.get(n, 1) for n in pool]
            return sorted(pool[:count])

        # ─── Model 8: 混沌模型（Logistic Map 映射到号码空间）─────────
        def _chaos():
            nums, _ = _all_nums()
            lo, hi  = min(nums), max(nums)
            r       = 3.9  # 混沌参数 3.57 < r ≤ 4
            # 初始值从最近期开奖号码和/总和 归一化
            series = _draw_series()
            init_val = 0.5
            if series:
                s = sum(series[0])
                init_val = (s % 97) / 100.0 or 0.37
            x = init_val
            chosen, seen = [], set()
            for _ in range(count * 20):
                x = r * x * (1 - x)
                mapped = int(lo + x * (hi - lo + 1))
                mapped = max(lo, min(hi, mapped))
                if mapped in nums and mapped not in seen:
                    seen.add(mapped); chosen.append(mapped)
                if len(chosen) == count: break
            if len(chosen) < count:
                remaining = [n for n in nums if n not in seen]
                chosen += remaining[:count - len(chosen)]
            return sorted(chosen[:count])

        # ─── Model 9: 蝌蚪模型（温度退火加权采样）────────────────────
        def _tadpole():
            nums, weights = _all_nums()
            omission = self.last_omission_data.get(game, {}).get(area, {})
            # 温度 T：遗漏越久，被选中的"热度"越高
            max_om = max(omission.values()) + 1 if omission else 1
            T      = 1.5  # 温度参数
            scores = {}
            for n, w in zip(nums, weights):
                om = omission.get(n, 0)
                heat = math.exp(om / max_om / T)   # 遗漏热度
                freq_factor = math.log(w + 2)       # 频率对数
                scores[n] = heat * freq_factor
            pool   = sorted(nums, key=lambda x: -scores.get(x, 1))[:max(count * 2, 12)]
            pool_w = [scores.get(n, 1) for n in pool]
            return sorted(pool[:count])

        # ─── Model 10: 蓝球专项（双色球蓝球 / 大乐透后区贝叶斯）──────
        def _blue_specialist():
            return _bayesian()

        # ─── Model 11: DeepSeek AI（暂用混沌+马尔科夫融合代替）────────
        def _deepseek():
            chaos_res  = _chaos()
            markov_res = _markov()
            # 两组结果各取一半合并
            half = count // 2
            merged = list(dict.fromkeys(chaos_res[:half] + markov_res[:half] + chaos_res + markov_res))
            return sorted(merged[:count])

        # ─── Model 12: 遗漏回归模型（遗漏期数越长越可能出现）────────────
        def _omission_regression():
            nums, weights = _all_nums()
            omission = self.last_omission_data.get(game, {}).get(area, {})
            if not omission:
                return _bayesian()
            # 遗漏越长，选中概率越高（线性遗漏权重）
            max_om = max(omission.values()) + 1
            scores = {}
            for n in nums:
                om = omission.get(n, 0)
                freq_base = math.log(weights[nums.index(n)] + 2)
                # 遗漏权重：超过平均遗漏的给更高权重
                avg_om = sum(omission.values()) / len(omission)
                om_w   = 1.0 + max(0, (om - avg_om) / (max_om + 1)) * 3.0
                scores[n] = freq_base * om_w
            ranked = sorted(nums, key=lambda x: -scores.get(x, 1))
            pool   = ranked[:max(count * 2, 12)]
            pool_w = [scores.get(n, 1) for n in pool]
            return sorted(pool[:count])

        # ─── Model 13: 集成投票模型（随机森林+贝叶斯+马尔科夫三票）────
        def _ensemble_voting():
            rf_res = _random_forest()
            bay_res = _bayesian()
            mk_res  = _markov()
            # 统计票数：每个模型的结果给号码加票
            vote_scores = {}
            for model_res, weight in [(rf_res, 3), (bay_res, 2), (mk_res, 2)]:
                for i, n in enumerate(model_res):
                    # 排名越靠前票数越高
                    pos_weight = (len(model_res) - i) / len(model_res)
                    vote_scores[n] = vote_scores.get(n, 0) + weight * pos_weight
            nums_v, _ = _all_nums()
            # 未被投票的号码给极小基础权重
            for n in nums_v:
                if n not in vote_scores:
                    vote_scores[n] = 0.01
            ranked = sorted(nums_v, key=lambda x: -vote_scores.get(x, 0))
            pool   = ranked[:max(count * 2, 12)]
            pool_w = [vote_scores.get(n, 0.01) for n in pool]
            return sorted(pool[:count])

        # ─── Model 14: 周期共振模型（检测历史开奖的周期性规律）──────────
        def _cycle_resonance():
            series = _draw_series()
            if len(series) < 10:
                return _bayesian()
            nums, weights = _all_nums()
            # 对每个号码，检测其出现的周期规律（3期、5期、7期、10期）
            scores = {}
            for n in nums:
                appear_positions = [i for i, draw in enumerate(series[:60]) if n in draw]
                if len(appear_positions) < 2:
                    scores[n] = weights[nums.index(n)]
                    continue
                # 计算平均出现间隔
                gaps = [appear_positions[i+1] - appear_positions[i]
                        for i in range(len(appear_positions)-1)]
                avg_gap = sum(gaps) / len(gaps)
                last_appear = appear_positions[0]  # 最近一次出现距今期数
                # 如果即将到达周期点，给高分
                cycle_score = 0
                for cycle in [3, 5, 7, 10, 14, 21]:
                    if abs(last_appear - cycle) <= 1:  # 即将或刚好到周期
                        cycle_score += 2.0 / cycle
                    elif last_appear > cycle and (last_appear % cycle) <= 1:
                        cycle_score += 1.0 / cycle
                # 结合频率和周期
                freq_score = weights[nums.index(n)] / (max(weights) + 1)
                scores[n] = freq_score + cycle_score
            ranked = sorted(nums, key=lambda x: -scores.get(x, 1))
            pool   = ranked[:max(count * 2, 12)]
            pool_w = [scores.get(n, 1) for n in pool]
            return sorted(pool[:count])

        # ─── Model 15: XGBoost梯度提升（纯Python实现，残差迭代）────────
        def _xgboost():
            series = _draw_series()
            if len(series) < 5:
                return _bayesian()
            nums, weights = _all_nums()
            n_look = min(30, len(series))
            # 用残差迭代思路：每轮计算预测误差，加权修正
            pred_scores = {n: 0.0 for n in nums}
            lr = 0.3  # learning rate
            for rnd in range(8):  # 8轮提升
                for n in nums:
                    recent = [1.0 if n in series[i] else 0.0 for i in range(min(n_look, len(series)))]
                    if not recent: continue
                    avg = sum(recent) / len(recent)
                    # 残差：近期出现率 vs 历史频率
                    hist_rate = weights[nums.index(n)] / (sum(weights) + 1e-9)
                    residual = avg - hist_rate
                    pred_scores[n] += lr * residual
            # 综合历史频率+梯度得分
            final = {n: (weights[nums.index(n)] / (max(weights)+1)) + pred_scores[n] for n in nums}
            ranked = sorted(nums, key=lambda x: -final.get(x, 0))
            pool = ranked[:max(count*2, 12)]
            pool_w = [max(0.01, final.get(n, 0.01)) for n in pool]
            return sorted(pool[:count])

        # ─── Model 16: 支持向量机SVM（线性核，纯Python实现）─────────
        def _svm():
            series = _draw_series()
            if len(series) < 8:
                return _random_forest()
            nums, weights = _all_nums()
            n_look = min(40, len(series))
            # 线性SVM思路：找到正负样本的决策边界
            # 特征：[频率归一化, 遗漏归一化, 最近5期出现率]
            omission = self.last_omission_data.get(game, {}).get(area, {})
            max_w = max(weights) + 1
            max_om = max(omission.values()) + 1 if omission else 1
            scores = {}
            for n, w in zip(nums, weights):
                f1 = w / max_w  # 频率特征
                f2 = omission.get(n, 0) / max_om  # 遗漏特征
                f3 = sum(1 for i in range(min(5,len(series))) if n in series[i]) / 5.0  # 近5期
                # 线性权重（模拟SVM超平面法向量，经验调参）
                scores[n] = 0.4*f1 + 0.35*f2 + 0.25*f3
            ranked = sorted(nums, key=lambda x: -scores.get(x, 0))
            pool = ranked[:max(count*2, 12)]
            pool_w = [scores.get(n, 0.01)+0.01 for n in pool]
            return sorted(pool[:count])

        # ─── Model 17: K近邻KNN（找最相似的历史期，预测下期）──────────
        def _knn():
            series = _draw_series()
            if len(series) < 6:
                return _bayesian()
            nums, _ = _all_nums()
            K = min(5, len(series)-1)
            # 用最近一期的号码集合做查询，找历史上最相似的K期
            query = set(series[0]) if series else set()
            similarities = []
            for i in range(1, len(series)):
                hist_set = set(series[i])
                # Jaccard相似度
                inter = len(query & hist_set)
                union = len(query | hist_set)
                sim = inter / (union + 1e-9)
                similarities.append((sim, i))
            similarities.sort(reverse=True)
            # 取最相似K期的下一期号码统计
            vote = {}
            for sim, idx in similarities[:K]:
                if idx+1 < len(series):
                    next_draw = series[idx+1]  # 该期之后的下一期
                    for n in next_draw:
                        if n in set(nums):
                            vote[n] = vote.get(n, 0) + sim + 0.1
            # 未被投票的补充基础频率
            for n in nums:
                if n not in vote:
                    vote[n] = 0.01
            ranked = sorted(nums, key=lambda x: -vote.get(x, 0))
            pool = ranked[:max(count*2, 12)]
            pool_w = [vote.get(n, 0.01) for n in pool]
            return sorted(pool[:count])

        # ─── Model 18: 神经网络BP（单隐层反向传播，纯Python）─────────
        def _neural_network():
            series = _draw_series()
            if len(series) < 10:
                return _lstm()
            nums, weights = _all_nums()
            n_look = min(20, len(series))
            # 输入层：每个号码的最近n期出现序列
            # 隐层：sigmoid激活，权重用遗漏×频率初始化
            # 输出层：预测下期出现概率
            omission = self.last_omission_data.get(game, {}).get(area, {})
            max_w = max(weights) + 1
            scores = {}
            for n, w in zip(nums, weights):
                # 输入特征向量
                x_freq = w / max_w
                x_om   = min(1.0, omission.get(n, 0) / (max(omission.values())+1)) if omission else 0
                x_trend = sum(1 if n in series[i] else -1 for i in range(min(5, len(series)))) / 5.0
                x_recent = sum(1 if n in series[i] else 0 for i in range(min(n_look, len(series)))) / n_look
                # 隐层（4个神经元，手工设权重）
                h1 = 1/(1+math.exp(-(1.2*x_freq - 0.3*x_om + 0.8*x_trend + 0.5*x_recent - 0.2)))
                h2 = 1/(1+math.exp(-(-0.5*x_freq + 1.5*x_om + 0.3*x_trend + 0.7*x_recent - 0.1)))
                h3 = 1/(1+math.exp(-(0.9*x_freq + 0.6*x_om - 0.4*x_trend + 1.0*x_recent - 0.3)))
                h4 = 1/(1+math.exp(-(0.4*x_freq + 0.4*x_om + 1.2*x_trend - 0.2*x_recent + 0.1)))
                # 输出层
                out = 1/(1+math.exp(-(0.8*h1 + 1.2*h2 + 0.7*h3 + 0.9*h4 - 0.5)))
                scores[n] = out
            ranked = sorted(nums, key=lambda x: -scores.get(x, 0))
            pool = ranked[:max(count*2, 12)]
            pool_w = [scores.get(n, 0.01)+0.01 for n in pool]
            return sorted(pool[:count])

        # ─── Model 19: 双向LSTM融合（正向+逆向EMA，融合预测）────────
        def _bilstm():
            series = _draw_series()
            if len(series) < 5:
                return _lstm()
            nums, _ = _all_nums()
            alpha = 0.3
            # 正向EMA（从远到近）
            fwd = {n: 0.0 for n in nums}
            for draw in reversed(series[:60]):
                for n in nums:
                    fwd[n] = alpha*(1.0 if n in draw else 0.0) + (1-alpha)*fwd[n]
            # 逆向EMA（从近到远，近期权重更大）
            bwd = {n: 0.0 for n in nums}
            for draw in series[:60]:
                for n in nums:
                    bwd[n] = alpha*(1.0 if n in draw else 0.0) + (1-alpha)*bwd[n]
            # 融合（正向60%+逆向40%）
            combined = {n: 0.6*fwd[n] + 0.4*bwd[n] for n in nums}
            ranked = sorted(nums, key=lambda x: -combined[x])
            pool = ranked[:max(count*2, 12)]
            pool_w = [combined[n]+0.01 for n in pool]
            return sorted(pool[:count])

        # ─── Model 20: 冠军集成优选（基于回测最佳模型动态加权）───────
        def _champion_ensemble():
            # 获取各模型历史命中率，动态加权
            scores_data = self.model_scores.get(game, {})
            model_weights = {}
            for mk in ["1","2","3","5","6","7","8","12","13","14","15","16","17","18","19",
                       "21","22","23","24","25"]:
                d = scores_data.get(mk, {})
                total = d.get("total", 0)
                if total >= 2:
                    rate = d.get("hits", 0) / total
                    model_weights[mk] = max(0.1, rate)
                else:
                    model_weights[mk] = 0.15  # 无数据给基础权重
            # 按权重运行各模型，汇总投票（综合25个模型，排除自身20与套娃模型）
            fn_map = {"1":_random_forest,"2":_linear_regression,"3":_lstm,
                      "5":_markov,"6":_bayesian,"7":_fractal,"8":_chaos,
                      "12":_omission_regression,"13":_ensemble_voting,
                      "14":_cycle_resonance,"15":_xgboost,"16":_svm,
                      "17":_knn,"18":_neural_network,"19":_bilstm,
                      "21":_transformer,"22":_lightgbm,"23":_gru,
                      "24":_monte_carlo,"25":_adaboost}
            vote_scores = {}
            nums_v, _ = _all_nums()
            for mk, fn in fn_map.items():
                w = model_weights.get(mk, 0.1)
                try:
                    res = fn()
                    for i, n in enumerate(res):
                        pos_w = (len(res)-i)/len(res)
                        vote_scores[n] = vote_scores.get(n, 0) + w * pos_w
                except: pass
            for n in nums_v:
                if n not in vote_scores:
                    vote_scores[n] = 0.01
            ranked = sorted(nums_v, key=lambda x: -vote_scores.get(x, 0))
            pool = ranked[:max(count*2, 12)]
            pool_w = [vote_scores.get(n, 0.01) for n in pool]
            return sorted(pool[:count])

        # ─── Model 21: Transformer注意力（自注意力，近期对各号码的注意力权重）───
        def _transformer():
            series = _draw_series()
            if len(series) < 5:
                return _bayesian()
            nums, weights = _all_nums()
            n_look = min(40, len(series))
            # query = 最近一期；对历史每期算注意力分（点积相似度→softmax）
            recent_sets = [set(series[i]) for i in range(min(n_look, len(series)))]
            query = recent_sets[0] if recent_sets else set()
            # 注意力得分：每期与query的交集大小，按时间衰减
            att_raw = []
            for i, s in enumerate(recent_sets):
                decay = math.exp(-i / 12.0)
                score = (len(query & s) + 0.5) * decay
                att_raw.append(score)
            tot = sum(math.exp(a) for a in att_raw) or 1.0
            att = [math.exp(a) / tot for a in att_raw]
            # 加权聚合：每个号码 = Σ 注意力 × 该期是否含该号码
            val = {n: 0.0 for n in nums}
            for i, s in enumerate(recent_sets):
                for n in nums:
                    if n in s:
                        val[n] += att[i]
            # 叠加历史频率作为残差连接
            max_w = max(weights) + 1
            final = {n: 0.7*val[n] + 0.3*(weights[nums.index(n)]/max_w) for n in nums}
            ranked = sorted(nums, key=lambda x: -final.get(x, 0))
            pool = ranked[:max(count*2, 12)]
            pool_w = [final.get(n, 0.01)+0.01 for n in pool]
            return sorted(pool[:count])

        # ─── Model 22: LightGBM提升（leaf-wise叶子优先的梯度提升）──────────
        def _lightgbm():
            series = _draw_series()
            if len(series) < 5:
                return _xgboost()
            nums, weights = _all_nums()
            omission = self.last_omission_data.get(game, {}).get(area, {})
            n_look = min(30, len(series))
            max_w  = max(weights) + 1
            max_om = (max(omission.values()) + 1) if omission else 1
            # leaf-wise：每轮只对当前误差最大的“叶子”（号码子集）做split修正
            scores = {n: weights[nums.index(n)]/max_w for n in nums}
            lr = 0.25
            for _ in range(10):
                resid = {}
                for n in nums:
                    recent = sum(1 for i in range(min(n_look,len(series))) if n in series[i]) / n_look
                    resid[n] = recent - scores[n]
                # 找误差最大的一批号码（叶子）优先修正
                leaf = sorted(nums, key=lambda x: -abs(resid[x]))[:max(count*3, 15)]
                for n in leaf:
                    om_bonus = 0.1 * (omission.get(n, 0) / max_om)
                    scores[n] += lr * resid[n] + om_bonus * lr
            ranked = sorted(nums, key=lambda x: -scores.get(x, 0))
            pool = ranked[:max(count*2, 12)]
            pool_w = [max(0.01, scores.get(n, 0.01)) for n in pool]
            return sorted(pool[:count])

        # ─── Model 23: GRU门控循环（更新门/重置门控制长短期记忆）──────────
        def _gru():
            series = _draw_series()
            if len(series) < 5:
                return _lstm()
            nums, _ = _all_nums()
            # 隐藏状态 h，逐期更新（从远到近）；更新门z、重置门r 控制记忆
            h = {n: 0.0 for n in nums}
            seq = list(reversed(series[:60]))
            for s in seq:
                sset = set(s)
                for n in nums:
                    x = 1.0 if n in sset else 0.0
                    # 门控（用经验权重模拟sigmoid门）
                    z = 1/(1+math.exp(-(1.0*x + 0.5*h[n] - 0.3)))   # 更新门
                    r = 1/(1+math.exp(-(0.8*x - 0.4*h[n] + 0.1)))   # 重置门
                    h_tilde = math.tanh(1.2*x + r*0.6*h[n])          # 候选记忆
                    h[n] = (1 - z)*h[n] + z*h_tilde                  # 新状态
            ranked = sorted(nums, key=lambda x: -h.get(x, 0))
            pool = ranked[:max(count*2, 12)]
            pool_w = [max(0.01, h.get(n, 0.0)+0.5) for n in pool]
            return sorted(pool[:count])

        # ─── Model 24: 蒙特卡洛模拟（按概率大量随机抽样，统计高频号）──────
        def _monte_carlo():
            nums, weights = _all_nums()
            omission = self.last_omission_data.get(game, {}).get(area, {})
            series = _draw_series()
            max_w  = max(weights) + 1
            max_om = (max(omission.values()) + 1) if omission else 1
            # 综合概率分布：频率 + 近期热度 + 适度遗漏回补
            prob = {}
            for n, w in zip(nums, weights):
                recent = sum(1 for i in range(min(10,len(series))) if n in series[i]) / 10.0 if series else 0
                prob[n] = 0.5*(w/max_w) + 0.3*recent + 0.2*(omission.get(n,0)/max_om)
            # 蒙特卡洛：固定种子的局部RNG，真实采样且结果可复现(不污染全局random)
            sims = 2000
            counter = {n: 0 for n in nums}
            pool_list = list(nums)
            wlist = [max(0.001, prob[n]) for n in pool_list]
            _rng = random.Random(20260605)
            for _ in range(sims):
                picks = set()
                attempts = 0
                while len(picks) < count and attempts < count*5:
                    c = _rng.choices(pool_list, weights=wlist, k=1)[0]
                    picks.add(c); attempts += 1
                for p in picks:
                    counter[p] += 1
            ranked = sorted(nums, key=lambda x: -counter.get(x, 0))
            return sorted(ranked[:count])

        # ─── Model 25: AdaBoost自适应（弱分类器加权迭代，难样本提权）──────
        def _adaboost():
            series = _draw_series()
            if len(series) < 6:
                return _random_forest()
            nums, weights = _all_nums()
            omission = self.last_omission_data.get(game, {}).get(area, {})
            n_look = min(30, len(series))
            max_w  = max(weights) + 1
            max_om = (max(omission.values()) + 1) if omission else 1
            # 三个弱分类器：频率分类器、遗漏分类器、近期趋势分类器
            def wc_freq(n):  return weights[nums.index(n)] / max_w
            def wc_omit(n):  return omission.get(n, 0) / max_om
            def wc_trend(n): return sum(1 for i in range(min(n_look,len(series))) if n in series[i]) / n_look
            learners = [wc_freq, wc_omit, wc_trend]
            # 样本权重初始化
            sw = {n: 1.0/len(nums) for n in nums}
            final = {n: 0.0 for n in nums}
            for wc in learners:
                vals = {n: wc(n) for n in nums}
                mean = sum(vals.values())/len(vals)
                # 误差：以均值为阈值，弱分类器对“是否出号”的错误率（加权）
                err = sum(sw[n] for n in nums if (vals[n] >= mean) != (sw[n] >= (sum(sw.values())/len(sw)))) + 1e-6
                err = min(0.499, max(0.001, err))
                alpha = 0.5 * math.log((1-err)/err)   # 分类器权重
                for n in nums:
                    final[n] += alpha * vals[n]
                    # 难样本（低分）提权
                    sw[n] *= math.exp(-alpha * (1 if vals[n] >= mean else -1))
                s = sum(sw.values()) or 1
                for n in nums: sw[n] /= s
            ranked = sorted(nums, key=lambda x: -final.get(x, 0))
            pool = ranked[:max(count*2, 12)]
            pool_w = [max(0.01, final.get(n, 0.01)) for n in pool]
            return sorted(pool[:count])

        dispatch = {
            "1":  _random_forest,      # 随机森林
            "2":  _linear_regression,  # 线性回归
            "3":  _lstm,               # LSTM（EMA）
            "4":  _interval,           # 区间模型
            "5":  _markov,             # 马尔科夫链
            "6":  _bayesian,           # 贝叶斯
            "7":  _fractal,            # 分形模型
            "8":  _chaos,              # 混沌模型
            "9":  _tadpole,            # 蝌蚪模型
            "10": _blue_specialist,    # 蓝球专项
            "11": _deepseek,           # AI融合
            "12": _omission_regression,# 遗漏回归
            "13": _ensemble_voting,    # 集成投票
            "14": _cycle_resonance,    # 周期共振
            "15": _xgboost,            # XGBoost梯度提升
            "16": _svm,                # 支持向量机
            "17": _knn,                # K近邻
            "18": _neural_network,     # 神经网络BP
            "19": _bilstm,             # 双向LSTM
            "20": _champion_ensemble,  # 冠军集成优选
            "21": _transformer,        # Transformer注意力
            "22": _lightgbm,           # LightGBM提升
            "23": _gru,                # GRU门控循环
            "24": _monte_carlo,        # 蒙特卡洛模拟
            "25": _adaboost,           # AdaBoost自适应
            "26": _xgboost,            # CatBoost缺库时先回退到提升树逻辑
            "30": _random_forest,      # ExtraTrees安卓稳健入口由真实ML调度接管
            "31": _xgboost,            # HistGradient安卓稳健入口由真实ML调度接管
            "27": _neural_network,     # TabNet缺库时回退表格神经网络
            "28": _transformer,        # TFT缺库时回退Transformer注意力
            "29": _champion_ensemble,  # AutoGluon缺库时回退冠军集成
        }
        try:
            fn = dispatch.get(model_key, _bayesian)
            result = fn()
            # 安全校验：确保返回的号码在合法范围内且数量正确
            nums_valid, _ = _all_nums()
            nums_set = set(nums_valid)
            result = [n for n in result if n in nums_set]
            if len(result) < count:
                extra = _safe_sample([n for n in nums_valid if n not in set(result)],
                                     count - len(result))
                result = sorted(result + extra)
            return sorted(result[:count])
        except Exception as e:
            logger.warning(f"模型{model_key}预测失败({e})，回退冷热选号")
            return self.pick_numbers_by_coldhot(game, area, count)

    def build_model_leaderboard(self, game: str, window: int = 100) -> list:
        """V74 模型排行榜：根据已有 model_scores/full_backtest_scores 生成最近表现排序。
        不制造假成绩；没有足够回测样本时返回可用模型列表并标记样本不足。
        """
        rows = []
        scores = {}
        try:
            scores.update((self.full_backtest_scores or {}).get(game, {}))
        except Exception:
            pass
        try:
            scores.update((self.model_scores or {}).get(game, {}))
        except Exception:
            pass
        for key, cfg in PREDICTION_MODELS.items():
            d = scores.get(str(key), {}) if isinstance(scores, dict) else {}
            total = int(d.get("total", 0) or 0)
            hits = int(d.get("hits", 0) or 0)
            rate = (hits / total) if total else 0.0
            rows.append({
                "model_key": str(key),
                "name": cfg.get("name", str(key)),
                "total": total,
                "hits": hits,
                "rate": rate,
                "status": "有效" if total >= 3 else "样本不足",
            })
        rows.sort(key=lambda r: (-r["rate"], -r["total"], int(r["model_key"])))
        return rows

    def get_dynamic_fusion_weights(self, game: str) -> dict:
        """V74 动态融合权重：机器学习/深度学习/专家预测/冷热遗漏。
        有足够模型回测时提高冠军模型权重；没有样本时使用稳健默认值。
        """
        lb = self.build_model_leaderboard(game)
        best = lb[0] if lb else {"rate": 0.0, "total": 0}
        if best.get("total", 0) >= 10 and best.get("rate", 0) > 0:
            ml = min(0.55, 0.35 + best["rate"] * 0.25)
        else:
            ml = 0.40
        return {
            "machine_learning": round(ml, 3),
            "deep_learning": 0.20,
            "expert_sites": 0.30,
            "cold_hot_omission": round(max(0.05, 1.0 - ml - 0.20 - 0.30), 3),
            "leader_model": best.get("model_key", "6"),
        }

    def _load_model_data(self):
        """V43: 从磁盘恢复 model_scores / full_backtest_scores / prediction_log。"""
        try:
            if MODEL_SCORES_FILE.exists():
                d = json.loads(MODEL_SCORES_FILE.read_text(encoding="utf-8"))
                if isinstance(d, dict):
                    self.model_scores = d
        except Exception as e:
            logger.warning(f"加载 model_scores.json 失败: {e}")
        try:
            if FULL_BACKTEST_FILE.exists():
                d = json.loads(FULL_BACKTEST_FILE.read_text(encoding="utf-8"))
                if isinstance(d, dict):
                    self.full_backtest_scores = d
        except Exception as e:
            logger.warning(f"加载 full_backtest_scores.json 失败: {e}")
        try:
            if PREDICTION_LOG_FILE.exists():
                d = json.loads(PREDICTION_LOG_FILE.read_text(encoding="utf-8"))
                if isinstance(d, list):
                    self.prediction_log = d
        except Exception as e:
            logger.warning(f"加载 prediction_log.json 失败: {e}")

    def _save_model_data(self):
        """V43: 持久化 model_scores / full_backtest_scores / prediction_log。"""
        try:
            MODEL_SCORES_FILE.write_text(
                json.dumps(self.model_scores, ensure_ascii=False, indent=2), encoding="utf-8")
        except Exception as e:
            logger.warning(f"保存 model_scores.json 失败: {e}")
        try:
            FULL_BACKTEST_FILE.write_text(
                json.dumps(self.full_backtest_scores, ensure_ascii=False, indent=2), encoding="utf-8")
        except Exception as e:
            logger.warning(f"保存 full_backtest_scores.json 失败: {e}")
        try:
            PREDICTION_LOG_FILE.write_text(
                json.dumps(self.prediction_log[-200:], ensure_ascii=False, indent=2), encoding="utf-8")
        except Exception as e:
            logger.warning(f"保存 prediction_log.json 失败: {e}")

    def record_prediction_outcome(self, game: str, model_key: str, hit: bool):
        """记录一次预测的命中情况，供自学习权重使用。"""
        if game not in self.model_scores:
            self.model_scores[game] = {}
        if model_key not in self.model_scores[game]:
            self.model_scores[game][model_key] = {"hits": 0, "total": 0, "sum_match": 0}
        self.model_scores[game][model_key].setdefault("sum_match", 0)
        self.model_scores[game][model_key]["total"] += 1
        if hit:
            self.model_scores[game][model_key]["hits"] += 1
        try:
            self._save_model_data()
        except Exception:
            pass

    def get_model_accuracy_report(self, game: str) -> str:
        """返回各模型对该游戏的历史命中率报告字符串。"""
        scores = self.model_scores.get(game, {})
        if not scores:
            return "  暂无预测历史数据"
        lines = []
        for key, data in sorted(scores.items()):
            total = data.get("total", 0)
            hits  = data.get("hits", 0)
            name  = PREDICTION_MODELS.get(key, {}).get("name", f"模型{key}")
            rate  = f"{hits/total*100:.1f}%" if total > 0 else "—"
            lines.append(f"  {name}: {hits}/{total} 次命中 ({rate})")
        return "\n".join(lines)


    def show_predict(self):
        game = self.analysis_game_combo.currentText()
        model_key = self.model_combo.currentData()
        model_name = self.model_combo.currentText()
        prediction_count = self.prediction_spin.value()
        self.figure.clear()
        ax = self.figure.add_subplot(111)

        if game not in self.history_data or not self.history_data[game]:
            self.analysis_result.setText("暂无历史数据，无法进行预测")
            return

        # ── 生成预测号码（统一入口）──
        recommendations = [self.predict_for_game(game, model_key) for _ in range(prediction_count)]
        self.last_prediction = {"game": game, "model_key": model_key, "data": recommendations}
        # 记录本次预测并触发历史回测（自学习权重更新）
        for rec in recommendations:
            self._record_prediction(game, model_key, rec)
        updated = self.backtest_predictions()
        if updated:
            logger.info(f"show_predict: 回测更新 {updated} 条预测记录")

        # ── 构建文字结果 ──
        result_text = f"【{game}】{model_name} 推荐 {prediction_count} 组\n"
        if model_key == "11":
            result_text += "⚠️ DeepSeek AI 模式需要网络，当前使用冷热模型代替\n"
        result_text += "\n"
        for idx, rec in enumerate(recommendations, 1):
            if game == "双色球":
                result_text += f"{idx}. 红球: {', '.join(map(str, rec['red']))}  蓝球: {rec['blue']}\n"
            elif game == "大乐透":
                result_text += f"{idx}. 前区: {', '.join(map(str, rec['front']))}  后区: {', '.join(map(str, rec['back']))}\n"
            elif game in ("快乐8", "七乐彩"):
                result_text += f"{idx}. 号码: {', '.join(map(str, rec['main']))}\n"
            else:
                result_text += f"{idx}. 号码: {', '.join(map(str, rec['pos']))}\n"

        # ── 模型命中率报告 ──
        report = self.get_model_accuracy_report(game)
        result_text += f"\n── 各模型历史命中率 ──\n{report}"

        self.analysis_result.setText(result_text)

        # ── 绘制号码频率分布图 ──
        try:
            freq_area = "red" if game == "双色球" else ("front" if game == "大乐透" else "main")
            freq = self.frequency_data.get(game, {}).get(freq_area, {})
            if freq:
                nums = sorted(freq.keys())
                vals = [freq[n] for n in nums]
                # 高亮本次预测的号码
                pred_nums = set()
                for rec in recommendations:
                    if game == "双色球":    pred_nums.update(rec.get("red", []))
                    elif game == "大乐透":  pred_nums.update(rec.get("front", []))
                    elif game in ("快乐8", "七乐彩"): pred_nums.update(rec.get("main", []))
                    else:                   pred_nums.update(rec.get("pos", []))
                colors = ["#E74C3C" if n in pred_nums else "#3498DB" for n in nums]
                ax.bar(nums, vals, color=colors, alpha=0.8)
                ax.set_xlabel("号码")
                ax.set_ylabel("出现频次")
                ax.set_title(f"{game} 频率分布（红色=本次预测）")
                ax.legend(handles=[
                    __import__('matplotlib.patches', fromlist=['Patch']).Patch(color='#E74C3C', label='本次预测'),
                    __import__('matplotlib.patches', fromlist=['Patch']).Patch(color='#3498DB', label='其他号码'),
                ])
            else:
                ax.text(0.5, 0.5, f"【{model_name}】{game} 推荐号码已生成\n请查看下方文本",
                        ha='center', va='center', fontsize=12)
        except Exception:
            ax.text(0.5, 0.5, f"【{model_name}】{game} 推荐号码已生成\n请查看下方文本",
                    ha='center', va='center', fontsize=12)
        self.canvas.draw()

    def bet_predicted_numbers(self):
        if not hasattr(self, 'last_prediction') or self.last_prediction is None:
            QMessageBox.warning(self, "错误", "请先点击'预测分析'生成号码")
            return
        game = self.last_prediction["game"]
        data = self.last_prediction["data"]
        if not data:
            QMessageBox.warning(self, "错误", "预测数据为空")
            return
        dialog = MultiPredictionBetDialog(self, game, data)
        if dialog.exec():
            pass

    def _sample_combos(self, pool, k, tickets, max_comb=None):
        """从 pool 中抽取 tickets 个不重复的 k 元组合。
        号码池较小时枚举后随机取；号码池较大时直接随机抽样，
        避免 list(combinations(...)) 在 C(n,k) 极大时把程序卡死/撑爆内存。"""
        import random as _random
        from itertools import combinations as _combinations
        pool = list(pool)
        if k <= 0 or len(pool) < k:
            return []
        if max_comb is None:
            max_comb = math.comb(len(pool), k)
        tickets = max(0, min(int(tickets), max_comb))
        if tickets <= 0:
            return []
        # 组合总数不大时，枚举全部再随机取（结果分布最准）。
        if max_comb <= 200000:
            combs = list(_combinations(sorted(pool), k))
            if tickets >= len(combs):
                return [list(c) for c in combs]
            return [list(c) for c in _random.sample(combs, tickets)]
        # 组合空间过大：拒绝采样直接生成不重复组合，绝不枚举全部。
        seen = set()
        out = []
        attempts = 0
        limit = tickets * 100 + 1000
        while len(out) < tickets and attempts < limit:
            c = tuple(sorted(_random.sample(pool, k)))
            if c not in seen:
                seen.add(c)
                out.append(list(c))
            attempts += 1
        return out

    def add_prediction_bet(self, game, prediction, bet_type, copies, dan_count, additional):
        latest_issue = ""
        if game in self.history_data and self.history_data[game]:
            latest_record = self.history_data[game][0]
            latest_issue = latest_record.get("期号", "")
        target_issue = self.get_next_issue(game, latest_issue) if latest_issue else ""

        if bet_type == "单式":
            numbers_str = self.format_numbers(game, prediction)
            self.add_betting_record(game, "预测单式", numbers_str, copies, (3.0 if additional else 2.0) * copies, target_issue, additional)
            QMessageBox.information(self, "成功", f"已添加 {copies} 注预测单式到投注记录")
            return

        elif bet_type == "复式":
            if game == "双色球":
                red_pool = prediction["red"]
                blue_pool = [prediction["blue"]]
                max_comb = math.comb(len(red_pool), 6) * len(blue_pool)
                tickets = min(copies, max_comb)
                red_combs = list(combinations(red_pool, 6))
                used = set()
                selected = []
                while len(selected) < tickets and len(used) < max_comb:
                    r = random.choice(red_combs)
                    b = random.choice(blue_pool)
                    key = (tuple(sorted(r)), b)
                    if key not in used:
                        used.add(key)
                        selected.append((r, b))
                if len(selected) < tickets:
                    remaining = [ (r, b) for r in red_combs for b in blue_pool if (tuple(sorted(r)), b) not in used ]
                    selected.extend(remaining[:tickets - len(selected)])
                lines = [f"红球: {', '.join(map(str, r))} 蓝球: {b}" for r, b in selected]
                numbers_str = "\n".join(lines)
                self.add_betting_record(game, "预测复式", numbers_str, len(selected), len(selected)*(3.0 if additional else 2.0), target_issue, additional)
            elif game == "大乐透":
                front_pool = prediction["front"]
                back_pool = prediction["back"]
                max_comb = math.comb(len(front_pool), 5) * math.comb(len(back_pool), 2)
                tickets = min(copies, max_comb)
                front_combs = list(combinations(front_pool, 5))
                back_combs = list(combinations(back_pool, 2))
                used = set()
                selected = []
                while len(selected) < tickets and len(used) < max_comb:
                    f = random.choice(front_combs)
                    b = random.choice(back_combs)
                    key = (tuple(sorted(f)), tuple(sorted(b)))
                    if key not in used:
                        used.add(key)
                        selected.append((f, b))
                if len(selected) < tickets:
                    remaining = [ (f, b) for f in front_combs for b in back_combs if (tuple(sorted(f)), tuple(sorted(b))) not in used ]
                    selected.extend(remaining[:tickets - len(selected)])
                lines = [f"前区: {', '.join(map(str, f))} 后区: {', '.join(map(str, b))}" for f, b in selected]
                numbers_str = "\n".join(lines)
                self.add_betting_record(game, "预测复式", numbers_str, len(selected), len(selected)*(3.0 if additional else 2.0), target_issue, additional)
            elif game == "快乐8":
                pool = prediction["main"]
                max_comb = math.comb(len(pool), 10) if len(pool) >= 10 else 0
                tickets = min(copies, max_comb)
                if tickets <= 0:
                    QMessageBox.warning(self, "错误", "快乐8预测复式至少需要10个号码"); return
                selected = self._sample_combos(pool, 10, tickets, max_comb)
                lines = [f"选10: {', '.join(map(str, c))}" for c in selected]
                numbers_str = "\n".join(lines)
                self.add_betting_record(game, "预测复式", numbers_str, len(selected), len(selected)*(3.0 if additional else 2.0), target_issue, additional)
            elif game == "七乐彩":
                pool = prediction["main"]
                max_comb = math.comb(len(pool), 7) if len(pool) >= 7 else 0
                tickets = min(copies, max_comb)
                if tickets <= 0:
                    QMessageBox.warning(self, "错误", "七乐彩预测复式至少需要7个号码"); return
                selected = self._sample_combos(pool, 7, tickets, max_comb)
                lines = [f"号码: {', '.join(map(str, c))}" for c in selected]
                numbers_str = "\n".join(lines)
                self.add_betting_record(game, "预测复式", numbers_str, len(selected), len(selected)*(3.0 if additional else 2.0), target_issue, additional)
            elif game in ["3D", "排列三"]:
                pos_pool = prediction["pos"]
                QMessageBox.warning(self, "错误", f"{game}预测复式需要每个位置多个号码，当前仅有一个")
                return
            elif game == "七星彩":
                pos_pool = prediction["pos"]
                QMessageBox.warning(self, "错误", f"{game}预测复式需要每个位置多个号码，当前仅有一个")
                return
            elif game == "排列五":
                pos_pool = prediction["pos"]
                QMessageBox.warning(self, "错误", f"{game}预测复式需要每个位置多个号码，当前仅有一个")
                return
            QMessageBox.information(self, "成功", f"已添加 {tickets} 注预测复式到投注记录")

        elif bet_type == "胆拖":
            if game == "双色球":
                red_pool = prediction["red"]
                blue_pool = [prediction["blue"]]
                if dan_count >= len(red_pool):
                    QMessageBox.warning(self, "错误", "胆码个数不能大于等于红球个数")
                    return
                dan = red_pool[:dan_count]
                tuo = red_pool[dan_count:]
                bets = math.comb(len(tuo), 6 - dan_count) * len(blue_pool) * copies
                numbers_str = f"胆码({dan_count}个): {', '.join(map(str, dan))}\n拖码({len(tuo)}个): {', '.join(map(str, tuo))}\n蓝球: {', '.join(map(str, blue_pool))}"
                self.add_betting_record(game, "预测胆拖", numbers_str, bets, bets*(3.0 if additional else 2.0), target_issue, additional)
            elif game == "大乐透":
                front_pool = prediction["front"]
                back_pool = prediction["back"]
                if dan_count >= len(front_pool):
                    QMessageBox.warning(self, "错误", "胆码个数不能大于等于前区个数")
                    return
                dan = front_pool[:dan_count]
                tuo = front_pool[dan_count:]
                bets = math.comb(len(tuo), 5 - dan_count) * math.comb(len(back_pool), 2) * copies
                numbers_str = f"前区胆码({dan_count}个): {', '.join(map(str, dan))}\n前区拖码({len(tuo)}个): {', '.join(map(str, tuo))}\n后区: {', '.join(map(str, back_pool))}"
                self.add_betting_record(game, "预测胆拖", numbers_str, bets, bets*(3.0 if additional else 2.0), target_issue, additional)
            else:
                QMessageBox.information(self, "提示", f"{game}暂不支持胆拖投注")

    def format_numbers(self, game, prediction):
        if game == "双色球":
            return f"红球: {', '.join(map(str, prediction['red']))} 蓝球: {prediction['blue']}"
        elif game == "大乐透":
            return f"前区: {', '.join(map(str, prediction['front']))} 后区: {', '.join(map(str, prediction['back']))}"
        elif game in ["快乐8", "七乐彩"]:
            return f"号码: {', '.join(map(str, prediction['main']))}"
        else:
            return f"号码: {', '.join(map(str, prediction['pos']))}"

    def calculate_multi_prediction_bet(self, game, selected_predictions, bet_type, dan_count, additional):
        if bet_type.startswith("单式"):
            bets = len(selected_predictions)
            amount = bets * (3.0 if additional and game == "大乐透" else 2.0)
            return bets, amount
        elif bet_type.startswith("复式"):
            if game == "双色球":
                red_set = set()
                blue_set = set()
                for pred in selected_predictions:
                    red_set.update(pred['red'])
                    blue_set.add(pred['blue'])
                red_pool = list(red_set)
                blue_pool = list(blue_set)
                bets = math.comb(len(red_pool), 6) * len(blue_pool)
                amount = bets * (3.0 if additional else 2.0)
                return bets, amount
            elif game == "大乐透":
                front_set = set()
                back_set = set()
                for pred in selected_predictions:
                    front_set.update(pred['front'])
                    back_set.update(pred['back'])
                front_pool = list(front_set)
                back_pool = list(back_set)
                bets = math.comb(len(front_pool), 5) * math.comb(len(back_pool), 2)
                amount = bets * (3.0 if additional else 2.0)
                return bets, amount
            elif game == "快乐8":
                main_set = set()
                for pred in selected_predictions:
                    main_set.update(pred['main'])
                main_pool = list(main_set)
                bets = math.comb(len(main_pool), 10)
                amount = bets * 2.0
                return bets, amount
            elif game == "七乐彩":
                main_set = set()
                for pred in selected_predictions:
                    main_set.update(pred['main'])
                main_pool = list(main_set)
                bets = math.comb(len(main_pool), 7)
                amount = bets * 2.0
                return bets, amount
            else:
                bets = len(selected_predictions)
                amount = bets * 2.0
                return bets, amount
        elif bet_type.startswith("胆拖"):
            if game == "双色球":
                red_set = set()
                blue_set = set()
                for pred in selected_predictions:
                    red_set.update(pred['red'])
                    blue_set.add(pred['blue'])
                red_pool = list(red_set)
                blue_pool = list(blue_set)
                if dan_count >= len(red_pool):
                    QMessageBox.warning(self, "错误", "胆码个数不能大于等于红球总数")
                    return 0, 0
                tuo_pool = red_pool[dan_count:]
                bets = math.comb(len(tuo_pool), 6 - dan_count) * len(blue_pool)
                amount = bets * (3.0 if additional else 2.0)
                return bets, amount
            elif game == "大乐透":
                front_set = set()
                back_set = set()
                for pred in selected_predictions:
                    front_set.update(pred['front'])
                    back_set.update(pred['back'])
                front_pool = list(front_set)
                back_pool = list(back_set)
                if dan_count >= len(front_pool):
                    QMessageBox.warning(self, "错误", "胆码个数不能大于等于前区总数")
                    return 0, 0
                tuo_pool = front_pool[dan_count:]
                bets = math.comb(len(tuo_pool), 5 - dan_count) * math.comb(len(back_pool), 2)
                amount = bets * (3.0 if additional else 2.0)
                return bets, amount
            else:
                QMessageBox.warning(self, "错误", f"{game}暂不支持胆拖投注")
                return 0, 0
        else:
            return 0, 0

    def add_multi_prediction_bet(self, game, selected_predictions, bet_type, dan_count, additional):
        bets, amount = self.calculate_multi_prediction_bet(game, selected_predictions, bet_type, dan_count, additional)
