    def _apply_responsive_tree(self):
        """
        遍历整个主窗口控件树，对所有子控件动态缩放 stylesheet 中的 font-size。
        同时开启触屏友好的滚动策略。
        手机/平板模式下生效，桌面直接返回。
        """
        scale = _get_ui_scale()
        if scale >= 0.99:
            return  # 桌面不做任何修改

        import re as _re
        _font_re = _re.compile(r"font-size:(\d+)px")

        from PySide6.QtWidgets import QWidget as _QW, QAbstractScrollArea, QScrollArea
        all_widgets = self.findChildren(_QW)
        for w in all_widgets:
            ss = w.styleSheet()
            if ss and "font-size" in ss:
                def _sub(m, _s=scale):
                    v = int(m.group(1))
                    return f"font-size:{max(8, int(round(v * _s)))}px"
                new_ss = _font_re.sub(_sub, ss)
                if new_ss != ss:
                    try:
                        w.setStyleSheet(new_ss)
                    except Exception:
                        pass
            # 让所有滚动区域按需显示滚动条
            if isinstance(w, (QAbstractScrollArea, QScrollArea)):
                try:
                    w.setVerticalScrollBarPolicy(Qt.ScrollBarAsNeeded)
                    w.setHorizontalScrollBarPolicy(Qt.ScrollBarAsNeeded)
                except Exception:
                    pass

