        fuzhi_spin_kl8.setRange(11, 20); fuzhi_spin_kl8.setValue(11)
        dan_lbl_kl8 = QLabel("  胆码:"); dan_spin_kl8 = QSpinBox(); dan_spin_kl8.setRange(1,4); dan_spin_kl8.setValue(2)
        tuo_lbl_kl8 = QLabel("拖码:"); tuo_spin_kl8 = QSpinBox(); tuo_spin_kl8.setRange(5,12); tuo_spin_kl8.setValue(5)
        bet_type_layout.addWidget(fuzhi_lbl_kl8); bet_type_layout.addWidget(fuzhi_spin_kl8)
        bet_type_layout.addWidget(dan_lbl_kl8); bet_type_layout.addWidget(dan_spin_kl8)
