        # 80个号码自适应：用更小的球让号码完整显示
        _cols_kl8 = 10
        _sp = 2
        _btn_sz = max(20, min(32, (_content_w - 16) // _cols_kl8 - _sp))
        NumberButton.set_btn_size(_btn_sz)
        scroll_layout.setSpacing(_sp)
        dialog.setUpdatesEnabled(False)

        main_buttons = []
        for i in range(1, 81):
            omission = self.get_omission("快乐8", i, "main")
