        latest = self.get_latest_draw_numbers("快乐8")
        repeat_main = set(latest.get("main", [])) if latest else set()

        # 快乐8区间：1-10,11-20,21-30,31-40,41-50,51-60,61-70,71-80
        intervals = [(1,10),(11,20),(21,30),(31,40),(41,50),(51,60),(61,70),(71,80)]

