        btn_cold = QPushButton("冷号")
        btn_cold.clicked.connect(apply_cold)
        filter_layout.addWidget(btn_cold)

        def apply_edge_kl8():
            """边码快选：选中上期开奖号码的左右相邻号码（环形，1-80）"""
            latest_kl8 = self.get_latest_draw_numbers("快乐8")
            if not latest_kl8:
                QMessageBox.information(dialog, "提示", "暂无上期开奖数据")
                return
            prev_nums = set(latest_kl8.get("main", latest_kl8.get("numbers", [])))
            N, MIN = 80, 1
            RANGE = N - MIN + 1
            edge_nums = set()
            for n in prev_nums:
                edge_nums.add(MIN + (n - MIN - 1) % RANGE)
                edge_nums.add(MIN + (n - MIN + 1) % RANGE)
            edge_nums -= prev_nums
            all_btns = []
            for row in main_buttons.values() if isinstance(main_buttons, dict) else [main_buttons]:
                if isinstance(row, list): all_btns.extend(row)
                else: all_btns.append(row)
            for btn in all_btns:
                try:
                    if int(btn.text()) in edge_nums and not btn.is_kill:
                        btn.setChecked(True)
                except: pass
            update_count()

        def apply_jump_kl8():
            """跳号快选：选中上期开奖号码的跳号（环形，1-80）"""
            latest_kl8 = self.get_latest_draw_numbers("快乐8")
            if not latest_kl8:
                QMessageBox.information(dialog, "提示", "暂无上期开奖数据")
                return
            prev_nums = set(latest_kl8.get("main", latest_kl8.get("numbers", [])))
            N, MIN = 80, 1
            RANGE = N - MIN + 1
            jump_nums = set()
            for n in prev_nums:
                for d in (2, 3):
                    jump_nums.add(MIN + (n - MIN - d) % RANGE)
                    jump_nums.add(MIN + (n - MIN + d) % RANGE)
            jump_nums -= prev_nums
            all_btns = []
            for row in main_buttons.values() if isinstance(main_buttons, dict) else [main_buttons]:
                if isinstance(row, list): all_btns.extend(row)
                else: all_btns.append(row)
            for btn in all_btns:
                try:
                    if int(btn.text()) in jump_nums and not btn.is_kill:
                        btn.setChecked(True)
                except: pass
            update_count()

