    # ---------- 七乐彩自选号码 ----------
    def self_select_qlc(self):
        """七乐彩自选号码 - 包含尾号选择"""
        dialog = QDialog(self)
        dialog.setWindowTitle("七乐彩自选号码")
        _sc = QApplication.primaryScreen().availableGeometry()
        _sc_w = _sc.width()
        # 强制使用保守的对话框宽度（兼容各种Android DPI缩放）
        # _sc_w可能是物理或逻辑像素，取较小值以确保内容不超出
        _dpr = QApplication.primaryScreen().devicePixelRatio()
        _dw_raw = max(280, int(_sc_w * 0.94))
        # 若DPR>1且宽度看起来是物理像素则除以DPR
        if _dpr > 1.2 and _dw_raw > 500:
            _dw_raw = int(_dw_raw / _dpr)
        _dw = max(280, _dw_raw)
        _dh = max(600, min(980, int(_sc.height() * 0.94)))
        dialog.setMinimumSize(320, 520)
        dialog.resize(_dw, _dh)

        layout = QVBoxLayout()
        tabs = QTabWidget()

        select_tab = QWidget()
        select_scroll = QScrollArea()
        select_scroll.setWidgetResizable(False)
        select_scroll.setHorizontalScrollBarPolicy(Qt.ScrollBarAlwaysOff)
        select_scroll.setVerticalScrollBarPolicy(Qt.ScrollBarAsNeeded)
        select_scroll_content = QWidget()
        # 内容宽度 = 对话框宽度 - 垂直滚动条宽度(约20px) - 边距
        _content_w = max(260, _dw - 24)
        select_scroll_content.setFixedWidth(_content_w)
        select_layout = QVBoxLayout(select_scroll_content)
        select_layout.setContentsMargins(2, 2, 2, 2)
        select_layout.setSpacing(3)

        bet_type_layout = QHBoxLayout()
        bet_type_layout.addWidget(QLabel("投注方式:"))
        bet_type_combo = QComboBox()
        bet_type_combo.addItems(["单式投注", "复式投注", "胆拖投注"])
        bet_type_layout.addWidget(bet_type_combo)
        # 复式/胆拖号码数量选择
        fuzhi_lbl_qlc = QLabel("  选码数:"); fuzhi_spin_qlc = QSpinBox()
        fuzhi_spin_qlc.setRange(8, 14); fuzhi_spin_qlc.setValue(8)
        dan_lbl_qlc = QLabel("  胆码:"); dan_spin_qlc = QSpinBox()
        dan_spin_qlc.setRange(1, 4); dan_spin_qlc.setValue(2)
        tuo_lbl_qlc = QLabel("拖码:"); tuo_spin_qlc = QSpinBox()
        tuo_spin_qlc.setRange(5, 12); tuo_spin_qlc.setValue(5)
        bet_type_layout.addWidget(fuzhi_lbl_qlc); bet_type_layout.addWidget(fuzhi_spin_qlc)
        bet_type_layout.addWidget(dan_lbl_qlc); bet_type_layout.addWidget(dan_spin_qlc)
        bet_type_layout.addWidget(tuo_lbl_qlc); bet_type_layout.addWidget(tuo_spin_qlc)
        def _update_bet_qlc():
            bt = bet_type_combo.currentText()
            for w in (fuzhi_lbl_qlc, fuzhi_spin_qlc): w.setVisible("复式" in bt)
            for w in (dan_lbl_qlc, dan_spin_qlc, tuo_lbl_qlc, tuo_spin_qlc): w.setVisible("胆拖" in bt)
        bet_type_combo.currentIndexChanged.connect(_update_bet_qlc)
        _update_bet_qlc()
        select_layout.addLayout(bet_type_layout)

        main_group = QGroupBox("号码选择 (1-30)")
        main_layout = QVBoxLayout()
        main_layout.setContentsMargins(2, 2, 2, 2)

        main_grid = QGridLayout()
        # 30个号码自适应
        _cols_qlc = 10
        _sp = 2
        _btn_sz = max(20, min(32, (_content_w - 16) // _cols_qlc - _sp))
        NumberButton.set_btn_size(_btn_sz)
        main_grid.setSpacing(_sp)

        main_buttons = []
        dialog.setUpdatesEnabled(False)
        # 批量预计算 七乐彩 main 统计
        _七乐c_main_stats = {i: (self.get_omission("七乐彩",i,"main"), self.get_frequency("七乐彩",i,"main"), self.get_cold_hot("七乐彩",i,"main"), self.calculate_probability("七乐彩",i,"main")) for i in range(1,31)}
        for i in range(1, 31):
            omission, frequency, cold_hot, probability = _七乐c_main_stats[i]
            btn = NumberButton(str(i), cold_hot, omission, frequency, probability=probability)
            main_buttons.append(btn)
            row = (i-1) // _cols_qlc
            col = (i-1) % _cols_qlc
            main_grid.addWidget(btn, row, col)

        main_layout.addLayout(main_grid)
        main_group.setLayout(main_layout)
        main_group.setStyleSheet("QGroupBox{font-size:11px;padding-top:14px;margin-top:2px;}QGroupBox::title{top:2px;}")
        main_group.setMinimumWidth(_cols_qlc * (_btn_sz + _sp) + 20)
        select_layout.addWidget(main_group)

        # 尾号快速选择
        tail_group = QGroupBox("尾号快速选择")
        tail_layout = QHBoxLayout(tail_group)
        tail_checkboxes = []
        for t in range(10):
            cb = QCheckBox(str(t))
            tail_layout.addWidget(cb)
            tail_checkboxes.append(cb)
        apply_tail_btn = QPushButton("应用尾号选择")
        tail_layout.addWidget(apply_tail_btn)
        select_layout.addWidget(tail_group)

        # 快捷选号按钮
        filter_group = QGroupBox("快捷选号")
        filter_group.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Preferred)
        filter_inner = QWidget()
        filter_layout = QHBoxLayout(filter_inner)
        filter_layout.setContentsMargins(4, 2, 4, 2)
        filter_layout.setSpacing(4)
        filter_scroll = QScrollArea()
        filter_scroll.setWidget(filter_inner)
        filter_scroll.setWidgetResizable(True)
        filter_scroll.setHorizontalScrollBarPolicy(Qt.ScrollBarAsNeeded)
        filter_scroll.setVerticalScrollBarPolicy(Qt.ScrollBarAlwaysOff)
        filter_scroll.setFixedHeight(52)
        filter_scroll.setFrameShape(QFrame.NoFrame)
        filter_grp_layout = QVBoxLayout(filter_group)
        filter_grp_layout.setContentsMargins(2, 14, 2, 2)
        filter_grp_layout.addWidget(filter_scroll)

        latest = self.get_latest_draw_numbers("七乐彩")
        repeat_set = set(latest.get("main", [])) if latest else set()

        # 区间：1-10,11-20,21-30
        intervals = [(1,10),(11,20),(21,30)]

        def apply_repeat():
            for btn in main_buttons:
                num = int(btn.text())
                if num in repeat_set:
                    btn.setChecked(True)
            update_count()

        def apply_kill():
            for btn in main_buttons:
                if btn.isChecked(): btn.set_kill(True)
            update_count()
        def cancel_kill():
            for btn in main_buttons:
                btn.set_kill(False)
            update_count()
        def cancel_kill():
            for btn in main_buttons:
                btn.set_kill(False)
            update_count()

        def apply_interval(start, end):
            for btn in main_buttons:
                num = int(btn.text())
                if start <= num <= end:
                    btn.setChecked(True)
            update_count()

        main_class = self.cold_hot_data["七乐彩"]["main"]

        def apply_hot():
            for btn in main_buttons:
                num = int(btn.text())
                if main_class.get(num) == 'hot':
                    btn.setChecked(True)
            update_count()

        def apply_warm():
            for btn in main_buttons:
                num = int(btn.text())
                if main_class.get(num) == 'warm':
                    btn.setChecked(True)
            update_count()

        def apply_cold():
            for btn in main_buttons:
                num = int(btn.text())
                if main_class.get(num) == 'cold':
                    btn.setChecked(True)
            update_count()

        def clear_all_selection():
            for btn in main_buttons:
                btn.setChecked(False)
            update_count()

        btn_repeat = QPushButton("重号")
        btn_repeat.clicked.connect(apply_repeat)
        filter_layout.addWidget(btn_repeat)
        btn_kill = QPushButton("杀号")
        btn_kill.setStyleSheet("background:#555;color:white;font-weight:bold;")
        btn_kill.clicked.connect(apply_kill)
        filter_layout.addWidget(btn_kill)
        btn_unkill = QPushButton("取消杀号")
        btn_unkill.setStyleSheet("background:#27AE60;color:white;")
        btn_unkill.clicked.connect(cancel_kill)
        filter_layout.addWidget(btn_unkill)

        for start, end in intervals:
            btn = QPushButton(f"{start}-{end}")
            btn.clicked.connect(lambda checked, s=start, e=end: apply_interval(s, e))
            filter_layout.addWidget(btn)

        btn_hot = QPushButton("热号")
        btn_hot.clicked.connect(apply_hot)
        filter_layout.addWidget(btn_hot)
        btn_warm = QPushButton("温号")
        btn_warm.clicked.connect(apply_warm)
        filter_layout.addWidget(btn_warm)
        btn_cold = QPushButton("冷号")
        btn_cold.clicked.connect(apply_cold)
        filter_layout.addWidget(btn_cold)

        def apply_edge_qlc():
            """边码快选：边码为开奖号左右相邻号，超出范围环形绕回"""
            if not repeat_set:
                QMessageBox.information(dialog, "提示", "暂无上期开奖数据")
                return
            N = 30
            MIN = 1
            RANGE = N - MIN + 1
            edge_nums = set()
            for n in repeat_set:
                edge_nums.add(MIN + (n - MIN - 1) % RANGE)  # 左1（环形）
                edge_nums.add(MIN + (n - MIN + 1) % RANGE)  # 右1（环形）
            edge_nums -= set(repeat_set)
            for btn in main_buttons:
                num = int(btn.text())
                if num in edge_nums and not btn.is_kill:
                    btn.setChecked(True)
            update_count()

        def apply_jump_qlc():
            """跳号快选：跳号为开奖号左右隔1或隔2个号，超出范围环形绕回"""
            if not repeat_set:
                QMessageBox.information(dialog, "提示", "暂无上期开奖数据")
                return
            N = 30
            MIN = 1
            RANGE = N - MIN + 1
            jump_nums = set()
            for n in repeat_set:
                for d in (2, 3):
                    jump_nums.add(MIN + (n - MIN - d) % RANGE)
                    jump_nums.add(MIN + (n - MIN + d) % RANGE)
            jump_nums -= set(repeat_set)
            for btn in main_buttons:
                num = int(btn.text())
                if num in jump_nums and not btn.is_kill:
                    btn.setChecked(True)
            update_count()

        btn_edge_qlc = QPushButton("边码")
        btn_edge_qlc.setStyleSheet("background:#8E44AD;color:white;font-weight:bold;")
        btn_edge_qlc.setToolTip("选中上期开奖号码的边码（左右相邻号码）")
        btn_edge_qlc.clicked.connect(apply_edge_qlc)
        filter_layout.addWidget(btn_edge_qlc)
        btn_jump_qlc = QPushButton("跳号")
        btn_jump_qlc.setStyleSheet("background:#16A085;color:white;font-weight:bold;")
        btn_jump_qlc.setToolTip("选中上期开奖号码的跳号（隔1-2位的号码）")
        btn_jump_qlc.clicked.connect(apply_jump_qlc)
        filter_layout.addWidget(btn_jump_qlc)
        btn_clear = QPushButton("清空")
        btn_clear.clicked.connect(clear_all_selection)
        filter_layout.addWidget(btn_clear)

        select_layout.addWidget(filter_group)

        def apply_tail():
            selected_tails = [t for t, cb in enumerate(tail_checkboxes) if cb.isChecked()]
            if not selected_tails:
                QMessageBox.warning(dialog, "提示", "请至少选择一个尾数")
                return
            for btn in main_buttons:
                num = int(btn.text())
                if num % 10 in selected_tails:
                    btn.setChecked(True)
                else:
                    btn.setChecked(False)
            update_count()

        apply_tail_btn.clicked.connect(apply_tail)

        select_count_label = QLabel("已选择: 0个号码")
        select_layout.addWidget(select_count_label)

        def update_count():
            selected = sum(btn.isChecked() for btn in main_buttons)
            if selected < 7:
                select_count_label.setText(f"已选择: {selected}个号码 (至少需要7个)")
                select_count_label.setStyleSheet("color: orange;")
            elif selected == 7:
                select_count_label.setText(f"已选择: {selected}个号码 (正好7个)")
                select_count_label.setStyleSheet("color: green;")
            else:
                select_count_label.setText(f"已选择: {selected}个号码 (超过7个，将进行复式投注)")
                select_count_label.setStyleSheet("color: blue;")

        for btn in main_buttons:
            btn.clicked.connect(update_count)

        btn_layout = QHBoxLayout()
        confirm_btn = QPushButton("确认投注")
        analysis_btn = QPushButton("号码分析")
        history_compare_btn = QPushButton("历史比对")
        shuishui_btn = QPushButton("缩水投注")
        matrix_btn = QPushButton("矩阵投注")
        predict_btn = QPushButton("预测推荐")
        cancel_btn = QPushButton("取消")

        def confirm():
            selected = [i+1 for i, btn in enumerate(main_buttons) if btn.isChecked()]
            bet_type = bet_type_combo.currentText()

            if not selected:
                QMessageBox.warning(dialog, "错误", "请选择号码")
                return

            if bet_type == "单式投注":
                if len(selected) != 7:
                    QMessageBox.warning(dialog, "错误", "单式投注需要选择正好7个号码")
                    return
                lines = [f"号码: {', '.join(map(str, sorted(selected)))}"]
                bets = 1

            elif bet_type == "复式投注":
                if len(selected) <= 7:
                    QMessageBox.warning(dialog, "错误", "复式投注需要选择至少8个号码")
                    return
                combs = list(combinations(selected, 7))
                lines = [f"号码: {', '.join(map(str, sorted(c)))}" for c in combs]
                bets = len(lines)

            else:  # 胆拖投注
                if len(selected) < 8:
                    QMessageBox.warning(dialog, "错误", "胆拖需要至少8个号码（1胆+7拖）")
                    return
                dt_dlg = SelfSelectDantuoDialog(self, "七乐彩",
                    main_selected=selected, aux_selected=[])
                if dt_dlg.exec() != QDialog.Accepted:
                    return
                p = dt_dlg.get_params()
                dan_n = p["dan_nums"]; tuo_n = p["tuo_nums"]; copies = p["copies"]
                dan_count = len(dan_n); need = 7 - dan_count
                lines = [f"号码: {', '.join(map(str, sorted(list(dan_n)+list(c))))}"
                         for c in combinations(tuo_n, need)] * copies
                bets = len(lines)

            total_bets = bets
            amount = total_bets * 2.0
            target_issue = self.get_default_target_issue("七乐彩")
            result = "\n".join(lines)
            QMessageBox.information(self, f"七乐彩{bet_type}", f"生成 {bets} 注，金额 ¥{amount:.2f}")
            self.add_betting_record("七乐彩", bet_type, result, total_bets, amount, target_issue=target_issue)
            dialog.accept()

        def analyze():
            selected = [i+1 for i, btn in enumerate(main_buttons) if btn.isChecked()]

            if not selected:
                QMessageBox.warning(dialog, "错误", "请先选择号码")
                return

            analysis_dialog = LotteryAnalysisDialog(self, "七乐彩", selected)
            analysis_dialog.exec()

        def history_compare():
            selected = [i+1 for i, btn in enumerate(main_buttons) if btn.isChecked()]
            structured = {"main": selected}
            compare_dialog = HistoryCompareDialog(self, "七乐彩", selected_numbers=None, structured_numbers=structured)
            compare_dialog.exec()

        def do_shuishui():
            selected = [i+1 for i, btn in enumerate(main_buttons) if btn.isChecked()]
            dialog = ShuishuiDialog(self, "七乐彩", selected)
            dialog.exec()

        def do_matrix():
            selected = [i+1 for i, btn in enumerate(main_buttons) if btn.isChecked()]
            dialog = MatrixDialog(self, "七乐彩", selected)
            dialog.exec()

        def do_predict():
            def apply_fn(pred):
                for btn in main_buttons: btn.setChecked(False)
                for num in pred["main"]: main_buttons[num-1].setChecked(True)
            self._show_predict_dialog("七乐彩", dialog, apply_fn, update_count)

        confirm_btn.clicked.connect(confirm)
        analysis_btn.clicked.connect(analyze)
        history_compare_btn.clicked.connect(history_compare)
        shuishui_btn.clicked.connect(do_shuishui)
        matrix_btn.clicked.connect(do_matrix)
        predict_btn.clicked.connect(do_predict)
        cancel_btn.clicked.connect(dialog.reject)
        btn_layout.addWidget(confirm_btn)
        btn_layout.addWidget(analysis_btn)
        btn_layout.addWidget(history_compare_btn)
        btn_layout.addWidget(shuishui_btn)
        btn_layout.addWidget(matrix_btn)
        btn_layout.addWidget(predict_btn)
        btn_layout.addWidget(cancel_btn)

        recent_group = QGroupBox("最近开奖记录")
        recent_layout = QVBoxLayout(recent_group)
        recent_table = QTableWidget()
        recent_table.setColumnCount(2)
        recent_table.setHorizontalHeaderLabels(["期号", "开奖号码"])
        recent_table.horizontalHeader().setSectionResizeMode(QHeaderView.Stretch)
        recent_table.setFixedHeight(120)
        recent_layout.addWidget(recent_table)
        select_layout.addWidget(recent_group)

        if "七乐彩" in self.history_data:
            records = self.history_data["七乐彩"][:5]
            recent_table.setRowCount(len(records))
            for row, rec in enumerate(records):
                recent_table.setItem(row, 0, QTableWidgetItem(str(rec.get("期号", ""))))
                recent_table.setItem(row, 1, QTableWidgetItem(str(rec.get("开奖号码", ""))))

        select_scroll.setWidget(select_scroll_content)
        select_tab.setLayout(QVBoxLayout())
        select_tab.layout().setContentsMargins(0,0,0,0)
        select_tab.layout().addWidget(select_scroll)
        tabs.addTab(select_tab, "🎯 选号")
        dialog.setUpdatesEnabled(True)

        history_tab = QWidget()
        history_layout = QVBoxLayout(history_tab)

        history_table = QTableWidget()
        history_table.setColumnCount(5)
        history_table.setHorizontalHeaderLabels(["期号", "开奖日期", "开奖号码", "一等奖", "奖池"])
        history_table.horizontalHeader().setSectionResizeMode(QHeaderView.Stretch)

        if "七乐彩" in self.history_data and self.history_data["七乐彩"]:
            data = self.history_data["七乐彩"][:50]
            history_table.setRowCount(len(data))
            for row, record in enumerate(data):
                history_table.setItem(row, 0, QTableWidgetItem(str(record.get("期号", ""))))
                history_table.setItem(row, 1, QTableWidgetItem(str(record.get("开奖日期", ""))))
                history_table.setItem(row, 2, QTableWidgetItem(str(record.get("开奖号码", ""))))
                history_table.setItem(row, 3, QTableWidgetItem(str(record.get("一等奖", "0注"))))
                history_table.setItem(row, 4, QTableWidgetItem(str(record.get("奖池", "0"))))
        else:
            history_table.setRowCount(1)
            history_table.setItem(0, 0, QTableWidgetItem("暂无数据"))
            history_table.setItem(0, 1, QTableWidgetItem("请先获取历史开奖数据"))

        history_layout.addWidget(history_table)
        tabs.addTab(history_tab, "📋 最近50期")

        layout.addWidget(tabs)
        layout.addLayout(btn_layout)
        dialog.setLayout(layout)
        dialog.exec()

    # ---------- 七星彩自选号码 ----------
    def self_select_qxc(self):
        """七星彩自选号码 - 包含尾号选择"""
        dialog = QDialog(self)
        dialog.setWindowTitle("七星彩自选号码")
        _sc = QApplication.primaryScreen().availableGeometry()
        _sc_w = _sc.width()
        # 强制使用保守的对话框宽度（兼容各种Android DPI缩放）
        # _sc_w可能是物理或逻辑像素，取较小值以确保内容不超出
        _dpr = QApplication.primaryScreen().devicePixelRatio()
        _dw_raw = max(280, int(_sc_w * 0.94))
        # 若DPR>1且宽度看起来是物理像素则除以DPR
        if _dpr > 1.2 and _dw_raw > 500:
            _dw_raw = int(_dw_raw / _dpr)
        _dw = max(280, _dw_raw)
        _dh = max(600, min(980, int(_sc.height() * 0.94)))
        dialog.setMinimumSize(320, 520)
        dialog.resize(_dw, _dh)

        layout = QVBoxLayout()
        tabs = QTabWidget()

        select_tab = QWidget()
        select_scroll = QScrollArea()
        select_scroll.setWidgetResizable(False)
        select_scroll.setHorizontalScrollBarPolicy(Qt.ScrollBarAlwaysOff)
        select_scroll.setVerticalScrollBarPolicy(Qt.ScrollBarAsNeeded)
        select_scroll_content = QWidget()
        # 内容宽度 = 对话框宽度 - 垂直滚动条宽度(约20px) - 边距
        _content_w = max(260, _dw - 24)
        select_scroll_content.setFixedWidth(_content_w)
        select_layout = QVBoxLayout(select_scroll_content)
        select_layout.setContentsMargins(2, 2, 2, 2)
        select_layout.setSpacing(3)

        bet_type_layout = QHBoxLayout()
        bet_type_layout.addWidget(QLabel("投注方式:"))
        bet_type_combo = QComboBox()
        bet_type_combo.addItems(["单式投注", "复式投注"])
        bet_type_layout.addWidget(bet_type_combo)
        select_layout.addLayout(bet_type_layout)

        positions = ["第一位", "第二位", "第三位", "第四位", "第五位", "第六位", "第七位(特别号)"]
        position_buttons = []

        for pos_idx, pos_name in enumerate(positions):
            pos_group = QGroupBox(f"{pos_name} (0-{'14' if pos_idx == 6 else '9'})")
            pos_layout = QVBoxLayout()
            pos_layout.setContentsMargins(2, 2, 2, 2)
            pos_grid = QGridLayout()
            max_num = 15 if pos_idx == 6 else 10
            # 每个位置的数字自适应列数，基于对话框宽度动态计算球大小
            if max_num <= 10:
                _cols_pos = max_num  # 0-9 全部一行
            else:
                _cols_pos = 8   # 0-14 两行(8+7)
            _sp = 2
            _btn_sz = max(20, min(32, (_content_w - 16) // _cols_pos - _sp))
            NumberButton.set_btn_size(_btn_sz)
            pos_grid.setSpacing(_sp)

            pos_buttons = []

            for i in range(0, max_num):
                omission = self.get_omission("七星彩", i, f"pos{pos_idx+1}")
                frequency = self.get_frequency("七星彩", i, f"pos{pos_idx+1}")
                cold_hot = self.get_cold_hot("七星彩", i, f"pos{pos_idx+1}")
                probability = self.calculate_probability("七星彩", i, f"pos{pos_idx+1}")
                btn = NumberButton(str(i), cold_hot, omission, frequency, probability=probability)
                pos_buttons.append(btn)
                pos_grid.addWidget(btn, i // _cols_pos, i % _cols_pos)

            pos_layout.addLayout(pos_grid)
            pos_group.setLayout(pos_layout)
            pos_group.setStyleSheet("QGroupBox{font-size:11px;padding-top:14px;margin-top:2px;}QGroupBox::title{top:2px;}")
            select_layout.addWidget(pos_group)
