        filter_layout.addWidget(btn_warm)
        btn_cold = QPushButton("冷号")
        btn_cold.clicked.connect(apply_cold)
        filter_layout.addWidget(btn_cold)

        def apply_edge_qxc():
            """边码快选：选中上期各位开奖数字的左右相邻数字（环形边码）"""
            prev_flat = set()
            if isinstance(repeat_pos, (list, tuple)):
                for s in repeat_pos: prev_flat.update(s)
            elif isinstance(repeat_pos, set):
                prev_flat = repeat_pos
            if not prev_flat:
                QMessageBox.information(dialog, "提示", "暂无上期开奖数据")
                return
            RANGE = 10  # 0-9
            edge_nums = set()
            for n in prev_flat:
                edge_nums.add((n - 1) % RANGE)
                edge_nums.add((n + 1) % RANGE)
            edge_nums -= prev_flat
            for btn in pos_buttons:
                num = int(btn.text())
                if num in edge_nums and not btn.is_kill:
                    btn.setChecked(True)
            update_count()

        def apply_jump_qxc():
            """跳号快选：选中上期各位开奖数字的跳号（环形）"""
            prev_flat = set()
            if isinstance(repeat_pos, (list, tuple)):
                for s in repeat_pos: prev_flat.update(s)
            elif isinstance(repeat_pos, set):
                prev_flat = repeat_pos
            if not prev_flat:
                QMessageBox.information(dialog, "提示", "暂无上期开奖数据")
                return
            RANGE = 10
            jump_nums = set()
            for n in prev_flat:
                for d in (2, 3):
                    jump_nums.add((n - d) % RANGE)
                    jump_nums.add((n + d) % RANGE)
            jump_nums -= prev_flat
            for btn in pos_buttons:
                num = int(btn.text())
                if num in jump_nums and not btn.is_kill:
                    btn.setChecked(True)
            update_count()

        btn_edge_qxc = QPushButton("边码")
        btn_edge_qxc.setStyleSheet("background:#8E44AD;color:white;font-weight:bold;")
        btn_edge_qxc.setToolTip("选中上期开奖号码的边码（左右相邻号码）")
        btn_edge_qxc.clicked.connect(apply_edge_qxc)
        filter_layout.addWidget(btn_edge_qxc)
        btn_jump_qxc = QPushButton("跳号")
        btn_jump_qxc.setStyleSheet("background:#16A085;color:white;font-weight:bold;")
        btn_jump_qxc.setToolTip("选中上期开奖号码的跳号（隔1-2位的号码）")
