        btn_unkill.setStyleSheet("background:#27AE60;color:white;")
        btn_unkill.clicked.connect(cancel_kill)
        filter_layout.addWidget(btn_unkill)

        for start, end in intervals:
            btn = QPushButton(f"{start}-{end}")
            btn.clicked.connect(lambda checked, s=start, e=end: apply_interval(s, e))
            filter_layout.addWidget(btn)

        btn_hot = QPushButton("热号")
        btn_hot.clicked.connect(apply_hot)
        filter_layout.addWidget(btn_hot)
        btn_warm = QPushButton("温号")
        btn_warm.clicked.connect(apply_warm)
        filter_layout.addWidget(btn_warm)
        btn_cold = QPushButton("冷号")
        btn_cold.clicked.connect(apply_cold)
        filter_layout.addWidget(btn_cold)

        def apply_edge_pl3():
            """边码快选：选中上期各位开奖数字的左右相邻数字（环形边码）"""
            if not repeat_set:
                QMessageBox.information(dialog, "提示", "暂无上期开奖数据")
                return
            RANGE = 10  # 0-9
            edge_nums = set()
            for n in repeat_set:
                edge_nums.add((n - 1) % RANGE)
                edge_nums.add((n + 1) % RANGE)
            edge_nums -= repeat_set
            for btn in one_buttons:
                num = int(btn.text())
                if num in edge_nums and not btn.is_kill:
                    btn.setChecked(True)
            update_count()

        def apply_jump_pl3():
            """跳号快选：选中上期各位开奖数字的跳号（环形）"""
            if not repeat_set:
                QMessageBox.information(dialog, "提示", "暂无上期开奖数据")
                return
            RANGE = 10
            jump_nums = set()
            for n in repeat_set:
                for d in (2, 3):
                    jump_nums.add((n - d) % RANGE)
                    jump_nums.add((n + d) % RANGE)
            jump_nums -= repeat_set
            for btn in one_buttons:
                num = int(btn.text())
                if num in jump_nums and not btn.is_kill:
                    btn.setChecked(True)
            update_count()

        btn_edge_pl3 = QPushButton("边码")
        btn_edge_pl3.setStyleSheet("background:#8E44AD;color:white;font-weight:bold;")
        btn_edge_pl3.setToolTip("选中上期开奖号码的边码（左右相邻号码）")
        btn_edge_pl3.clicked.connect(apply_edge_pl3)
        filter_layout.addWidget(btn_edge_pl3)
        btn_jump_pl3 = QPushButton("跳号")
        btn_jump_pl3.setStyleSheet("background:#16A085;color:white;font-weight:bold;")
        btn_jump_pl3.setToolTip("选中上期开奖号码的跳号（隔1-2位的号码）")
        btn_jump_pl3.clicked.connect(apply_jump_pl3)
