        def apply_tail():
            selected_tails = [t for t, cb in enumerate(tail_checkboxes) if cb.isChecked()]
            if not selected_tails:
                QMessageBox.warning(dialog, "提示", "请至少选择一个尾数")
                return
            for btn in hundred_buttons + ten_buttons + one_buttons:
                num = int(btn.text())
