    def check_api_key(self):
        """验证极速API密钥"""
        import threading
        key = self.jisuapi_key
        if not key:
            QMessageBox.warning(self, "错误", "请先设置极速API密钥"); return
        def _test():
            try:
                result = self._jisuapi_get(JISUAPI_CONFIG["lottery_class"], {})
                if result is not None:
                    n = len(result) if isinstance(result, list) else 1
                    QTimer.singleShot(0, lambda: (
                        QMessageBox.information(self, "✅ 密钥有效",
                            f"极速API密钥验证成功！\n支持 {n} 种彩票"),
                        self.update_api_key_status(valid=True)
                    ))
                else:
                    QTimer.singleShot(0, lambda: (
                        QMessageBox.warning(self, "密钥无效", "极速API验证失败，请检查密钥"),
                        self.update_api_key_status(valid=False)
                    ))
            except Exception as e:
                QTimer.singleShot(0, lambda e=e: (
                    QMessageBox.critical(self, "网络错误", f"验证失败: {e}"),
                    self.update_api_key_status(valid=False)
                ))
        threading.Thread(target=_test, daemon=True).start()

