    def _start_manual_update(self, progress):
        try:
            games = ["双色球", "快乐8", "3D", "七乐彩", "大乐透", "七星彩", "排列三", "排列五"]
            success_count = 0
            for game in games:
                try:
                    updated = self.update_game_data_from_api(game)
                    if updated:
                        success_count += 1
                except Exception as e:
                    logger.error(f"更新{game}数据失败: {str(e)}")
            progress.close()
            progress.deleteLater()
            if success_count > 0:
                self.update_home_info()
                self.calculate_omission()
                QMessageBox.information(self, "更新完成", f"自动更新完成，成功更新{success_count}个游戏的数据")
            else:
                QMessageBox.information(self, "更新完成", "没有新数据或更新失败")
        except Exception as e:
            progress.close()
            progress.deleteLater()
            QMessageBox.warning(self, "更新失败", f"更新数据失败: {str(e)}")

