    def get_today_draw_info(self):
        today = datetime.now().strftime("%A")
        chinese_days = {"Monday": "周一", "Tuesday": "周二", "Wednesday": "周三",
                        "Thursday": "周四", "Friday": "周五", "Saturday": "周六", "Sunday": "周日"}
        today_chinese = chinese_days.get(today, "今日")
        today_games = []
        for game, info in LOTTERY_DRAW_TIMES.items():
            days = info["days"]
            if "每日" in days or today_chinese in days:
                draw_time = info["time"]
                today_games.append(f"{game}({draw_time})")
        if today_games:
            return f"🎯 今日开奖: {', '.join(today_games)}"
        else:
            return f"ℹ️ 今日无开奖"

    def _generate_balls_html(self, game, numbers_str):
        """生成彩票开奖号码的圆形球体HTML（用于QLabel，支持完整CSS）。
        颜色规则：
          双色球：前6红球(白字) + 第7蓝球(白字)
          大乐透：前5前区红球(白字) + 后2后区蓝球(白字)
          七乐彩：前7红球(白字) + 第8特别号蓝球(白字)
          七星彩：前6位红球(白字) + 第7位蓝球(白字)
          其他：全部红球(白字)
        """
        if not numbers_str or str(numbers_str).strip() == "":
            return "<span style='color:#aaa;font-size:11px;'>暂无数据</span>"
        numbers = parse_draw_numbers(str(numbers_str))
        if not numbers:
            return "<span style='color:#aaa;font-size:11px;'>暂无数据</span>"

        total  = len(numbers)
        parts  = []

        for idx, num in enumerate(numbers):
            # 判断是红球还是蓝球
            if game == "双色球":
                is_blue = (total >= 7 and idx == 6)
            elif game == "大乐透":
                is_blue = (total >= 7 and idx >= 5)
            elif game == "七乐彩":
                is_blue = (total >= 8 and idx == 7)
            elif game == "七星彩":
                is_blue = (total >= 7 and idx == 6)
            else:
                is_blue = False

            if is_blue:
                bg  = "#1565C0"
                fg  = "#ffffff"
            else:
                bg  = "#C62828"
                fg  = "#ffffff"

            # QLabel 支持 border-radius，可以渲染圆形
            parts.append(
                f"<span style='"
                f"display:inline-block;"
                f"background-color:{bg};"
                f"color:{fg};"
                f"border-radius:18px;"
                f"width:34px;"
                f"height:34px;"
                f"line-height:34px;"
                f"text-align:center;"
                f"font-weight:bold;"
                f"font-size:13px;"
                f"margin:2px;"
                f"padding:0px;"
                f"'>&nbsp;{num}&nbsp;</span>"
            )

        return "".join(parts)

    def update_home_results(self):
        """用 QTableWidget + LotteryBallsWidget 显示最新开奖结果。
        jisuapi数据结构：开奖号码=主区, 参考号码=蓝球/后区特别号
        列：游戏 | 期号 | 开奖号码(圆形球) | 中奖信息(按钮)
        """
        games = ["双色球", "大乐透", "快乐8", "七星彩", "3D", "排列三", "七乐彩", "排列五"]
        self.home_results_table.setRowCount(len(games))

        for row, game in enumerate(games):
            try:
                rec   = None
                issue = "—"; pool = "—"
                prize_info_list = []
                display_nums_str = ""

                if game in self.history_data and self.history_data[game]:
                    rec   = self.history_data[game][0]
                    issue = str(rec.get("期号", "—"))

                    # ── 拼合完整开奖号码（主区 + 参考号码/蓝球）──
                    main_num  = str(rec.get("开奖号码", "")).strip()
                    refer_num = str(rec.get("参考号码", rec.get("蓝球", ""))).strip()
                    if refer_num and refer_num not in ("", "0", "None", "null"):
                        display_nums_str = main_num + " " + refer_num
                    else:
                        display_nums_str = main_num

                    # 奖池
                    pool = str(rec.get("奖池", rec.get("销售额", "—"))).strip()
                    if not pool or pool in ("None", "None元", "0元", "0", "", "0.00元"):
                        pool = "—"
                    elif not pool.endswith("元") and pool != "—":
                        pool += "元"

                    # 中奖信息：从 奖级 list 提取（jisuapi格式）
                    prize_list = rec.get("奖级", [])
                    if prize_list:
                        for p in prize_list[:3]:  # 显示前3个奖级
                            eq = p.get("等级", ""); num = p.get("注数",""); bonus = p.get("单注","")
                            if eq and str(num) not in ("0","","None"):
                                prize_info_list.append(f"{eq}: {num}注 ¥{bonus}")
                    # 兼容旧格式
                    for k in ("一等奖", "二等奖"):
                        v = rec.get(k)
                        if v and str(v) not in ("0","0注","0元","None",""):
                            if not any(k in s for s in prize_info_list):
                                prize_info_list.append(f"{k}: {v}")

                # Col 0: 游戏名
                name_item = QTableWidgetItem(game)
                name_item.setTextAlignment(Qt.AlignCenter)
                name_item.setForeground(QColor("#2E8B57"))
                f = name_item.font(); f.setBold(True); name_item.setFont(f)
                self.home_results_table.setItem(row, 0, name_item)

                # Col 1: 期号
                issue_item = QTableWidgetItem(issue)
                issue_item.setTextAlignment(Qt.AlignCenter)
                self.home_results_table.setItem(row, 1, issue_item)

                # Col 2: 开奖号码 — LotteryBallsWidget 圆形球体
                numbers = _parse_balls_for_widget(display_nums_str, game) if display_nums_str else []
                if numbers:
                    ball_w  = LotteryBallsWidget(game, numbers)
                    ctr     = QWidget()
                    c_lay   = QHBoxLayout(ctr)
                    c_lay.setContentsMargins(3, 1, 3, 1)
                    c_lay.addWidget(ball_w)
                    c_lay.addStretch()
                    self.home_results_table.setCellWidget(row, 2, ctr)
                else:
                    no_item = QTableWidgetItem("暂无数据 — 请先获取开奖")
                    no_item.setForeground(QColor("#aaa"))
                    no_item.setTextAlignment(Qt.AlignCenter)
                    self.home_results_table.setItem(row, 2, no_item)

                # Col 3: 中奖信息按钮
                info_btn = QPushButton("🏆 中奖信息")
                info_btn.setStyleSheet(
                    "background:#E67E22;color:white;font-weight:bold;"
                    "font-size:11px;padding:3px 6px;border-radius:3px;"
                )
                def _make_show_prize(g=game, r=rec, p=pool, pi=prize_info_list):
                    def _show():
                        self._show_prize_info(g, r, p, pi)
                    return _show
                info_btn.clicked.connect(_make_show_prize())
                ctr3 = QWidget()
                l3   = QHBoxLayout(ctr3)
                l3.setContentsMargins(2, 1, 2, 1)
                l3.addWidget(info_btn)
                self.home_results_table.setCellWidget(row, 3, ctr3)

            except Exception as e:
                logger.error(f"生成{game}开奖结果显示失败: {str(e)}")

        # 固定行高适配球体（快乐8用小球，其他用标准球）
        for row in range(self.home_results_table.rowCount()):
            # Get game for this row
            game_item = self.home_results_table.item(row, 0)
            row_game = game_item.text() if game_item else ""
            if row_game == "快乐8":
                rh = LotteryBallsWidget._BALL_D_SMALL * 2 + LotteryBallsWidget.PAD_V * 4 + 8
            else:
                rh = LotteryBallsWidget.BALL_D + LotteryBallsWidget.PAD_V * 2 + 8
            self.home_results_table.setRowHeight(row, rh)

    def _show_prize_info(self, game: str, rec: dict, pool: str, prize_info_list: list):
        """弹出显示指定彩票最新一期的中奖信息和奖池余额。"""
        dlg = QDialog(self)
        dlg.setWindowTitle(f"🏆 {game} 中奖信息")
        dlg.setMinimumWidth(380)
        lay = QVBoxLayout(dlg)

        if not rec:
            lay.addWidget(QLabel("暂无数据，请先获取开奖数据"))
            lay.addWidget(QPushButton("关闭", clicked=dlg.reject))
            dlg.exec(); return

        issue = rec.get("期号", "—")
        date  = rec.get("开奖日期", "—")
        nums  = rec.get("开奖号码", "—")

        # 期号和号码
        header = QLabel(f"【{game}】第 {issue} 期  开奖日期: {date}")
        header.setStyleSheet("font-weight:bold;font-size:13px;color:#2E8B57;padding:4px;")
        lay.addWidget(header)

        # 开奖号码展示
        numbers = _parse_balls_for_widget(str(nums), game) if nums and nums != "—" else []
        if numbers:
            ball_w = LotteryBallsWidget(game, numbers)
            ball_w.setFixedHeight(LotteryBallsWidget.BALL_D + LotteryBallsWidget.PAD_V * 2 + 4)
            ball_ctr = QWidget()
            b_lay = QHBoxLayout(ball_ctr)
            b_lay.addWidget(ball_w); b_lay.addStretch()
            lay.addWidget(ball_ctr)

        sep = QFrame(); sep.setFrameShape(QFrame.HLine); sep.setStyleSheet("color:#ddd;")
        lay.addWidget(sep)

        # 奖池信息
        pool_lbl = QLabel(f"🏦 奖池余额: {pool}")
        pool_lbl.setStyleSheet("font-size:13px;color:#c0392b;font-weight:bold;padding:4px;")
        lay.addWidget(pool_lbl)

        # 各奖级中奖信息
        prize_grp = QGroupBox("各奖级中奖情况")
        prize_lay = QVBoxLayout(prize_grp)
        # 从 rec 里取所有奖级字段
        _prize_keys = ["一等奖", "二等奖", "三等奖", "四等奖", "五等奖",
                       "六等奖", "七等奖", "福运奖",
                       "头奖注数", "头奖金额", "销售额"]
        found_any = False
        for k in _prize_keys:
            v = rec.get(k)
            if v is not None and str(v) not in ("", "None", "0", "0注", "0元"):
                prize_lay.addWidget(QLabel(f"  {k}: {v}"))
                found_any = True
        # 如果 rec 里没有结构化字段，显示额外的 prize_info_list
        for pi in prize_info_list:
            if pi not in [f"  {k}: {rec.get(k)}" for k in _prize_keys]:
                prize_lay.addWidget(QLabel(f"  {pi}"))
                found_any = True
        if not found_any:
            prize_lay.addWidget(QLabel("  暂无详细中奖信息（API未返回奖级数据）"))
        lay.addWidget(prize_grp)

        # 历史中奖记录（近5期）
        hist_grp = QGroupBox(f"近5期开奖记录")
        hist_lay = QVBoxLayout(hist_grp)
        recs = self.history_data.get(game, [])[:5]
        for r in recs:
            r_nums = r.get("开奖号码", "—")
            r_issue = r.get("期号", "—")
            r_date  = r.get("开奖日期", "—")
            hist_lay.addWidget(QLabel(f"  第{r_issue}期 ({r_date}): {r_nums}"))
        lay.addWidget(hist_grp)

        close_btn = QPushButton("关闭")
        close_btn.clicked.connect(dlg.reject)
        lay.addWidget(close_btn)
        dlg.exec()

    def home_predict_analysis(self):
        """首页预测分析：带遗漏值的号码选择，完整历史比对和概率分析。"""
        try:
            games = ["双色球", "大乐透", "快乐8", "七星彩", "3D", "排列三", "七乐彩", "排列五"]
            dlg = QDialog(self)
            dlg.setWindowTitle("🔮 预测概率分析")
            sc = QApplication.primaryScreen().availableGeometry()
            _dpr = QApplication.primaryScreen().devicePixelRatio()
            _sc_w = sc.width()
            if _dpr > 1.2 and _sc_w > 500: _sc_w = int(_sc_w / _dpr)
            _dw = max(320, int(_sc_w * 0.96))
            _dh = max(680, int(sc.height() * 0.94))
            dlg.resize(_dw, _dh)
            root = QVBoxLayout(dlg)
            root.setSpacing(4)
            root.setContentsMargins(6, 6, 6, 6)

            # ── 玩法选择 ──
            g_row = QHBoxLayout()
            g_row.addWidget(QLabel("选择玩法:"))
            game_combo = QComboBox()
            game_combo.addItems(games)
            g_row.addWidget(game_combo)
            root.addLayout(g_row)

            # ── 直接粘贴号码分析（支持单式/复式/胆拖/套餐任意注数）──
            paste_row = QHBoxLayout()
            paste_row.addWidget(QLabel("粘贴号码:"))
            paste_edit = QLineEdit()
            paste_edit.setPlaceholderText("如  01 02 03 04 05 06 07 09 11 15 25 26 29 + 11   （+后为蓝球/后区）")
            paste_edit.setStyleSheet("font-size:12px;padding:3px;")
            paste_row.addWidget(paste_edit, 1)
            parse_btn = QPushButton("解析选中")
            parse_btn.setStyleSheet("background:#16A085;color:white;font-weight:bold;padding:4px 10px;")
            paste_row.addWidget(parse_btn)
            root.addLayout(paste_row)

            # ── 号码选择区（带遗漏/频率的NumberButton）──
            num_grp = QGroupBox("选择要分析的号码")
            num_grp.setStyleSheet("QGroupBox{font-size:11px;padding-top:14px;margin-top:2px;}QGroupBox::title{top:2px;}")
            num_lay = QVBoxLayout(num_grp)
            num_lay.setContentsMargins(2, 2, 2, 2)
            num_lay.setSpacing(3)

            num_scroll = QScrollArea()
            num_scroll.setWidgetResizable(False)
            num_scroll.setHorizontalScrollBarPolicy(Qt.ScrollBarAlwaysOff)
            num_scroll.setVerticalScrollBarPolicy(Qt.ScrollBarAsNeeded)
            num_inner = QWidget()
            _content_w = max(260, _dw - 28)
            num_inner.setFixedWidth(_content_w)
            num_grid = QGridLayout(num_inner)
            num_grid.setSpacing(2)
            num_scroll.setWidget(num_inner)
            num_scroll.setMinimumHeight(120)
            num_scroll.setMaximumHeight(340)
            num_lay.addWidget(num_scroll)

            count_lbl = QLabel("已选: 0 个")
            count_lbl.setStyleSheet("font-size:11px;color:#555;")
            num_lay.addWidget(count_lbl)

            quick_row = QHBoxLayout()
            auto_btn  = QPushButton("🤖 AI自动选号")
            auto_btn.setStyleSheet("background:#27AE60;color:white;font-weight:bold;padding:4px;")
            clear_btn2 = QPushButton("清空")
            quick_row.addWidget(auto_btn); quick_row.addWidget(clear_btn2)
            num_lay.addLayout(quick_row)
            root.addWidget(num_grp)

            # 存储 (NumberButton, area_key, number)
            ball_entries = []

            def rebuild_balls():
                nonlocal ball_entries
                for btn, _, _ in ball_entries:
                    btn.hide(); btn.deleteLater()
                ball_entries.clear()
                # 仅清除 num_scroll 内部内容，不破坏外层布局
                old_inner = QWidget()
                num_scroll.setWidget(old_inner)
                QApplication.processEvents()

                g = game_combo.currentText()
                if g == "双色球":
                    areas = [("红球(1-33)","red",1,33,6),("蓝球(1-16)","blue",1,16,4)]
                elif g == "大乐透":
                    areas = [("前区(1-35)","front",1,35,7),("后区(1-12)","back",1,12,6)]
                elif g == "快乐8":
                    areas = [("号码(1-80)","main",1,80,10)]
                elif g == "七乐彩":
                    areas = [("号码(1-30)","main",1,30,10)]
                elif g in ("3D","排列三"):
                    areas = [("百位(0-9)","pos1",0,9,10),("十位(0-9)","pos2",0,9,10),("个位(0-9)","pos3",0,9,10)]
                elif g == "七星彩":
                    areas = [(f"第{i+1}位(0-9)",f"pos{i+1}",0,9,10) for i in range(6)]
                    areas.append(("第7位(0-14)","pos7",0,14,8))
                elif g == "排列五":
                    areas = [(f"第{i+1}位(0-9)",f"pos{i+1}",0,9,10) for i in range(5)]
                else:
                    areas = [("号码","main",1,30,10)]

                sp = 2
                # ★ 每个区域单独一个 QGroupBox，彻底避免号码混排 ★
                inner_w = QWidget()
                inner_w.setFixedWidth(_content_w)
                inner_vlay = QVBoxLayout(inner_w)
                inner_vlay.setSpacing(4)
                inner_vlay.setContentsMargins(2, 2, 2, 2)

                for area_name, area_key, lo, hi, cols in areas:
                    btn_sz = max(20, min(34, (_content_w - 20) // cols - sp))
                    NumberButton.set_btn_size(btn_sz)
                    a_grp = QGroupBox(area_name)
                    a_grp.setStyleSheet("QGroupBox{font-size:10px;padding-top:12px;margin-top:1px;}QGroupBox::title{top:1px;}")
                    a_lay = QVBoxLayout(a_grp)
                    a_lay.setContentsMargins(2, 4, 2, 2); a_lay.setSpacing(1)
                    a_grid = QGridLayout(); a_grid.setSpacing(sp)
                    for n in range(lo, hi + 1):
                        omit = self.get_omission(g, n, area_key)
                        freq = self.get_frequency(g, n, area_key)
                        cht  = self.get_cold_hot(g, n, area_key)
                        prob = self.calculate_probability(g, n, area_key)
                        nb = NumberButton(str(n), cht, omit, freq, probability=prob)
                        nb.clicked.connect(update_count)
                        ball_entries.append((nb, area_key, n))
                        idx = n - lo
                        a_grid.addWidget(nb, idx // cols, idx % cols)
                    a_lay.addLayout(a_grid)
                    inner_vlay.addWidget(a_grp)

                num_scroll.setWidget(inner_w)
                # 动态计算滚动区高度
                avg_btn_h = max(22, min(36, (_content_w-20)//max(a[4] for a in areas)-sp)) + sp + 2
                total_rows = sum((hi-lo)//cols + 1 for _,_,lo,hi,cols in areas)
                scroll_h = min(440, max(120, total_rows * avg_btn_h + len(areas) * 28))
                num_scroll.setMinimumHeight(scroll_h)
                num_scroll.setMaximumHeight(scroll_h)
                update_count()


            def update_count():
                sel = sum(1 for b, _, _ in ball_entries if b.isChecked())
                count_lbl.setText(f"已选: {sel} 个")

            def auto_select():
                g  = game_combo.currentText()
                mk = self._best_model_key(g)
                pred = self.predict_for_game(g, mk)
                pred_by_area = {}
                if g == "双色球":
                    pred_by_area["red"]   = set(pred.get("red", []))
                    pred_by_area["blue"]  = {pred.get("blue", 0)}
                elif g == "大乐透":
                    pred_by_area["front"] = set(pred.get("front", []))
                    pred_by_area["back"]  = set(pred.get("back", []))
                elif g in ("快乐8","七乐彩"):
                    pred_by_area["main"]  = set(pred.get("main", []))
                else:
                    for i, v in enumerate(pred.get("pos", [])):
                        pred_by_area[f"pos{i+1}"] = {v}
                for btn, ak, n in ball_entries:
                    btn.setChecked(n in pred_by_area.get(ak, set()))
                update_count()

            def clear_all():
                for btn, _, _ in ball_entries: btn.setChecked(False)
                update_count()

            def parse_and_select():
                """把粘贴的号码串解析并在球面板上选中，支持任意注数（单式/复式/胆拖/套餐池）。"""
                import re as _re
                txt = paste_edit.text().strip()
                if not txt:
                    QMessageBox.information(dlg, "提示", "请先粘贴号码"); return
                g = game_combo.currentText()
                # 拆分主区/副区（以 + 或 | 分隔）
                main_part, sub_part = txt, ""
                for sep in ["+", "|", "＋"]:
                    if sep in txt:
                        parts = txt.split(sep, 1)
                        main_part, sub_part = parts[0], parts[1]
                        break
                main_nums = [int(x) for x in _re.findall(r"\d+", main_part)]
                sub_nums  = [int(x) for x in _re.findall(r"\d+", sub_part)]
                # 位置型彩票：号码按顺序落到各位
                clear_all()
                area_keys = sorted({ak for _, ak, _ in ball_entries},
                                   key=lambda k: (len(k), k))
                is_pos = g in ("3D","排列三","排列五","七星彩")
                hit = 0
                if is_pos:
                    # 每位一个号码，依次映射 pos1,pos2,...
                    pos_order = []
                    seen = set()
                    for _, ak, _ in ball_entries:
                        if ak.startswith("pos") and ak not in seen:
                            seen.add(ak); pos_order.append(ak)
                    pos_order.sort(key=lambda k: int(k[3:]))
                    for i, val in enumerate(main_nums):
                        if i >= len(pos_order): break
                        ak = pos_order[i]
                        for btn, bak, bn in ball_entries:
                            if bak == ak and bn == val:
                                btn.setChecked(True); hit += 1
                else:
                    # 主区
                    main_ak = None
                    if g == "双色球": main_ak, sub_ak = "red", "blue"
                    elif g == "大乐透": main_ak, sub_ak = "front", "back"
                    else: main_ak, sub_ak = "main", ""
                    for btn, bak, bn in ball_entries:
                        if bak == main_ak and bn in main_nums:
                            btn.setChecked(True); hit += 1
                        elif sub_ak and bak == sub_ak and bn in sub_nums:
                            btn.setChecked(True); hit += 1
                update_count()
                if hit == 0:
                    QMessageBox.warning(dlg, "提示",
                        "未能匹配到号码，请检查格式或所选玩法是否正确")
                else:
                    # 解析成功后自动分析
                    do_analyze()

            parse_btn.clicked.connect(parse_and_select)
            paste_edit.returnPressed.connect(parse_and_select)

            game_combo.currentIndexChanged.connect(rebuild_balls)
            auto_btn.clicked.connect(auto_select)
            clear_btn2.clicked.connect(clear_all)
            rebuild_balls()

            # ── 分析结果区 ──
            result_grp = QGroupBox("历史比对 & 概率分析")
            result_grp.setStyleSheet("QGroupBox{font-size:11px;padding-top:14px;margin-top:2px;}QGroupBox::title{top:2px;}")
            result_lay = QVBoxLayout(result_grp)
            result_lay.setContentsMargins(2, 2, 2, 2)
            result_text = QTextEdit()
            result_text.setReadOnly(True)
            result_text.setMinimumHeight(260)
            result_text.setStyleSheet("font-size:12px;")
            result_lay.addWidget(result_text)
            root.addWidget(result_grp, stretch=1)

            def do_analyze():
                g = game_combo.currentText()
                sel_by_area = {}
                for btn, ak, n in ball_entries:
                    if btn.isChecked():
                        sel_by_area.setdefault(ak, set()).add(n)
                # 转为排序列表
                for k in sel_by_area:
                    sel_by_area[k] = sorted(sel_by_area[k])

                if not sel_by_area:
                    QMessageBox.warning(dlg, "提示", "请先选择号码"); return

                if g == "双色球":
                    main_nums = sel_by_area.get("red", [])
                    sub_nums  = sel_by_area.get("blue", [])
                    main_area = "red"; sub_area = "blue"
                    main_label = "红球"; sub_label = "蓝球"
                elif g == "大乐透":
                    main_nums = sel_by_area.get("front", [])
                    sub_nums  = sel_by_area.get("back", [])
                    main_area = "front"; sub_area = "back"
                    main_label = "前区"; sub_label = "后区"
                elif g in ("快乐8","七乐彩"):
                    main_nums = sel_by_area.get("main", [])
                    sub_nums  = []; main_area = "main"; sub_area = ""
                    main_label = "号码"; sub_label = ""
                else:
                    main_nums = []
                    for i in range(1, 8):
                        main_nums += sel_by_area.get(f"pos{i}", [])
                    sub_nums = []; main_area = "pos1"; sub_area = ""
                    main_label = "号码"; sub_label = ""

                if not main_nums:
                    QMessageBox.warning(dlg, "提示", "请先选择号码"); return

                records = self.history_data.get(g, [])
                if not records:
                    result_text.setPlainText("暂无历史数据，请先获取开奖记录"); return

                # 历史匹配统计
                match_counts = []
                match_details = []  # (期号, 开奖号码, 命中数)
                for rec in records[:100]:
                    draw_raw = parse_draw_numbers(rec.get("开奖号码",""))
                    if g == "双色球":   draw = draw_raw[:6]
                    elif g == "大乐透": draw = draw_raw[:5]
                    elif g == "七乐彩": draw = draw_raw[:7]
                    else: draw = draw_raw
                    cnt = len(set(main_nums) & set(draw))
                    match_counts.append(cnt)
                    if cnt >= 3:
                        match_details.append((rec.get("期号","?"), draw_raw, cnt))

                n_total   = len(match_counts)
                avg_match = sum(match_counts)/n_total if n_total else 0
                max_match = max(match_counts) if match_counts else 0
                prob_1    = sum(1 for m in match_counts if m>=1)/n_total if n_total else 0
                prob_3    = sum(1 for m in match_counts if m>=3)/n_total if n_total else 0
                prob_5    = sum(1 for m in match_counts if m>=5)/n_total if n_total else 0

                freq_data  = self.frequency_data.get(g, {})
                freq_map_m = freq_data.get(main_area, {})
                freq_map_s = freq_data.get(sub_area, {}) if sub_area else {}
                total_draws = len(records)

                lines = [
                    f"{'='*22} {g} 预测概率分析 {'='*22}",
                    f"分析号码 — {main_label}: {', '.join(map(str, main_nums))}"
                ]
                if sub_nums:
                    lines.append(f"          {sub_label}: {', '.join(map(str, sub_nums))}")
                lines += [
                    "",
                    f"📊 历史比对（近{n_total}期）:",
                    f"   平均每期匹配: {avg_match:.2f} 个",
                    f"   最高单期匹配: {max_match} 个",
                    f"   匹配≥1个概率: {prob_1*100:.1f}%",
                    f"   匹配≥3个概率: {prob_3*100:.1f}%",
                    f"   匹配≥5个概率: {prob_5*100:.1f}%",
                ]
                # 命中≥3的历史期详情
                if match_details:
                    lines.append(f"\n   近{n_total}期中命中≥3个的期次（共{len(match_details)}期）:")
                    for issue, draw, cnt in match_details[:10]:
                        hit_nums = sorted(set(main_nums) & set(draw[:6] if g=="双色球" else draw[:5] if g=="大乐透" else draw))
                        lines.append(f"     第{issue}期: 命中{cnt}个 {hit_nums}")

                # 各号码频率&遗漏（完整显示所有选中号码）
                lines += [
                    "",
                    f"📈 {main_label}各号码频率 & 遗漏（近{total_draws}期）:",
                    f"   {'号码':>4}  {'出现':>5}  {'频率':>6}  {'遗漏':>4}  {'热度':>4}"
                ]
                for n in main_nums:
                    cnt  = freq_map_m.get(n, 0)
                    pct  = cnt/total_draws*100 if total_draws else 0
                    omit = self.get_omission(g, n, main_area)
                    cht  = self.get_cold_hot(g, n, main_area)
                    tag  = {"hot":"🔴热","warm":"🟡温","cold":"🟢冷"}.get(cht,"  -")
                    lines.append(f"   {n:>4}  {cnt:>5}次  {pct:>5.1f}%  {omit:>4}期  {tag}")

                if sub_nums and sub_area:
                    lines += [
                        "",
                        f"📈 {sub_label}频率 & 遗漏（近{total_draws}期）:",
                        f"   {'号码':>4}  {'出现':>5}  {'频率':>6}  {'遗漏':>4}"
                    ]
                    for n in sub_nums:
                        cnt  = freq_map_s.get(n, 0)
                        pct  = cnt/total_draws*100 if total_draws else 0
                        omit = self.get_omission(g, n, sub_area)
                        lines.append(f"   {n:>4}  {cnt:>5}次  {pct:>5.1f}%  {omit:>4}期")

                # 各AI模型与选号的重合（完整25个模型）
                self.backtest_predictions()
                lines += ["", "🤖 各AI模型与选号的重合情况（全25模型）:"]
                for mk, mv in PREDICTION_MODELS.items():
                    try:
                        pred = self.predict_for_game(g, mk)
                        if g=="双色球":   pm=set(pred.get("red",[]))
                        elif g=="大乐透": pm=set(pred.get("front",[]))
                        elif g in ("快乐8","七乐彩"): pm=set(pred.get("main",[]))
                        else: pm=set(pred.get("pos",[]))
                        overlap=len(set(main_nums) & pm)
                        mkd=self.model_scores.get(g,{}).get(mk,{})
                        tp=mkd.get("total",0); hp=mkd.get("hits",0)
                        rs=f"{hp/tp*100:.0f}%({tp}次)" if tp>0 else "无数据"
                        lines.append(f"   {mv['name']:12s}: 重合{overlap:2d}个  [命中率{rs}]")
                    except: pass

                # 综合建议
                lines += ["", "💡 综合建议:"]
                avg_freq = avg_match * total_draws / 100 if total_draws else 0
                hot_n  = [n for n in main_nums if freq_map_m.get(n, 0) >= avg_freq] if avg_freq > 0 else []
                cold_n = [n for n in main_nums if freq_map_m.get(n, 0) < avg_freq * 0.5] if avg_freq > 0 else []
                if hot_n:  lines.append(f"   热号（建议保留）: {', '.join(map(str,sorted(hot_n)))}")
                if cold_n: lines.append(f"   冷号（可考虑替换）: {', '.join(map(str,sorted(cold_n)))}")
                lines.append(f"   历史匹配≥3个概率: {prob_3*100:.1f}%  |  ≥5个概率: {prob_5*100:.1f}%")
                lines.append("   ⚠ 彩票具有随机性，以上分析仅供参考，理性购彩")
                lines.append("="*50)
                result_text.setPlainText("\n".join(lines))

            # ── 底部按钮 ──
            btn_row = QHBoxLayout()
            analyze_btn = QPushButton("🔮 开始分析")
            analyze_btn.setStyleSheet("background:#2980B9;color:white;font-weight:bold;padding:6px;")
            analyze_btn.clicked.connect(do_analyze)

            def copy_analysis():
                text = result_text.toPlainText()
                if not text.strip(): QMessageBox.information(dlg,"提示","请先点击【开始分析】"); return
                QApplication.clipboard().setText(text)
                QMessageBox.information(dlg,"✅ 已复制","分析结果已复制到剪贴板！")

            copy_btn2 = QPushButton("📋 复制分析结果")
            copy_btn2.setStyleSheet("background:#8E44AD;color:white;font-weight:bold;padding:6px;")
            copy_btn2.clicked.connect(copy_analysis)

            bet_btn = QPushButton("💰 直接投注选中号码")
            bet_btn.setStyleSheet("background:#27AE60;color:white;font-weight:bold;padding:6px;")
            def do_bet():
                g = game_combo.currentText()
                if g == "双色球":
                    reds  = sorted(b for btn,ak,b in ball_entries if btn.isChecked() and ak=="red")
                    blues = sorted(b for btn,ak,b in ball_entries if btn.isChecked() and ak=="blue")
                    if len(reds)<6 or not blues:
                        QMessageBox.warning(dlg,"提示","双色球需至少6个红球+1个蓝球"); return
                    from itertools import combinations as _c
                    lines_b=[f"红球: {', '.join(map(str,sorted(rc)))} 蓝球: {bc}"
                             for rc in _c(reds,6) for bc in blues] if len(reds)>6 or len(blues)>1 					        else [f"红球: {', '.join(map(str,reds))} 蓝球: {blues[0]}"]
                elif g == "大乐透":
                    fronts=sorted(b for btn,ak,b in ball_entries if btn.isChecked() and ak=="front")
                    backs =sorted(b for btn,ak,b in ball_entries if btn.isChecked() and ak=="back")
                    if len(fronts)<5 or len(backs)<2:
                        QMessageBox.warning(dlg,"提示","大乐透需至少5个前区+2个后区"); return
                    from itertools import combinations as _c
                    lines_b=[f"前区: {', '.join(map(str,sorted(fc)))} 后区: {', '.join(map(str,sorted(bc)))}"
                             for fc in _c(fronts,5) for bc in _c(backs,2)] if len(fronts)>5 or len(backs)>2 					        else [f"前区: {', '.join(map(str,fronts))} 后区: {', '.join(map(str,backs))}"]
                else:
                    selected=sorted(b for btn,ak,b in ball_entries if btn.isChecked())
                    if not selected: QMessageBox.warning(dlg,"提示","请先选择号码"); return
                    lines_b=[f"号码: {', '.join(map(str,selected))}"]
                n_bets=len(lines_b)
                target=self.get_default_target_issue(g)
                if n_bets>1:
                    reply=QMessageBox.question(dlg,"复式确认",f"共{n_bets}注，总额¥{n_bets*2:.0f}，确认？",
                                               QMessageBox.Yes|QMessageBox.No)
                    if reply!=QMessageBox.Yes: return
                self.add_betting_record(g,"预测分析"+("(复式)" if n_bets>1 else ""),
                    "\n".join(lines_b),n_bets,n_bets*2.0,target_issue=target)
                QMessageBox.information(dlg,"成功",f"✓ 已添加{n_bets}注{g}预测分析投注！")
            bet_btn.clicked.connect(do_bet)

            close_btn = QPushButton("关闭"); close_btn.clicked.connect(dlg.reject)
            btn_row.addWidget(analyze_btn); btn_row.addWidget(copy_btn2)
            btn_row.addWidget(bet_btn); btn_row.addWidget(close_btn)
            root.addLayout(btn_row)
            dlg.exec()

        except Exception as e:
            logger.error(f"预测分析错误: {e}", exc_info=True)
            QMessageBox.warning(self, "错误", f"预测分析失败: {e}")


