    # ---------- 标签页初始化（完整实现）----------
    # ------ 通用 UI 工厂方法 ------
    def _make_game_group(self, game: str, extra_buttons: list | None = None) -> QGroupBox:
        """为指定游戏生成标准按钮组（自选/机选/复式/胆拖/幸运/缩水/矩阵/AI预测/尾号）。
        extra_buttons: [(label, slot), ...] 额外按钮（如套餐票）。
        注意：btn.clicked 信号会传入 checked:bool，必须用 lambda checked=False, g=game 接住
        """
        group = QGroupBox(game)
        layout = QVBoxLayout()

        # 第一行：自选/机选1注/机选多注
        row = QHBoxLayout()
        for label, slot in [("自选号码", lambda checked=False, g=game: self.self_select(g)),
                            ("机选1注",  lambda checked=False, g=game: self.generate_random(g)),
                            ("机选多注", lambda checked=False, g=game: self.generate_multiple(g))]:
            btn = QPushButton(label)
            btn.clicked.connect(slot)
            row.addWidget(btn)
        layout.addLayout(row)

        # 复式/胆拖/幸运
        for label, slot in [("复式投注", lambda checked=False, g=game: self.generate_complex(g)),
                            ("胆拖投注", lambda checked=False, g=game: self.generate_dantuo(g)),
                            ("幸运选号", lambda checked=False, g=game: self.lucky_select(g))]:
            btn = QPushButton(label)
            btn.clicked.connect(slot)
            layout.addWidget(btn)

        # 额外按钮（套餐票等）
        for label, slot in (extra_buttons or []):
            btn = QPushButton(label)
            btn.clicked.connect(slot)
            layout.addWidget(btn)

        # 缩水/矩阵
        for label, slot in [("缩水投注", lambda checked=False, g=game: self.shuishui_bet(g)),
                            ("矩阵投注", lambda checked=False, g=game: self.matrix_bet(g))]:
            btn = QPushButton(label)
            btn.clicked.connect(slot)
            layout.addWidget(btn)

        # 尾号功能行
        tail_row = QHBoxLayout()
        tail_pred_btn = QPushButton("🔢 尾号预测")
        tail_pred_btn.setStyleSheet("background-color:#7D3C98;color:white;font-weight:bold;")
        tail_pred_btn.clicked.connect(lambda checked=False, g=game: self.tail_predict(g))
        tail_row.addWidget(tail_pred_btn)

        tail_trend_btn = QPushButton("📊 尾号走势")
        tail_trend_btn.setStyleSheet("background-color:#1A5276;color:white;font-weight:bold;")
        tail_trend_btn.clicked.connect(lambda checked=False, g=game: self.tail_trend_chart(g))
        tail_row.addWidget(tail_trend_btn)
        layout.addLayout(tail_row)

        # AI 预测投注 + 模型选择
        ai_row = QHBoxLayout()
        ai_btn = QPushButton("🤖 AI预测投注")
        ai_btn.setStyleSheet("background-color:#27AE60;color:white;font-weight:bold;")
        ai_btn.clicked.connect(lambda checked=False, g=game: self._quick_ai_predict(g))
        ai_row.addWidget(ai_btn)

        model_btn = QPushButton("⚙ 选择模型")
        model_btn.setStyleSheet("background-color:#2980B9;color:white;font-weight:bold;")
        model_btn.clicked.connect(lambda checked=False, g=game: self._select_predict_model(g))
        model_btn.setToolTip("选择预测模型（当前自动选最优）")
        ai_row.addWidget(model_btn)
        layout.addLayout(ai_row)

        # 全模型对比投注
        compare_btn = QPushButton("🏆 全模型对比投注")
        compare_btn.setStyleSheet("background-color:#8E44AD;color:white;font-weight:bold;")
        compare_btn.clicked.connect(lambda checked=False, g=game: self._all_models_predict_compare(g))
        compare_btn.setToolTip("一次生成所有14个预测模型的号码，对比命中率，选择投注")

        hist_btn = QPushButton("📊 全历史分析")
        hist_btn.clicked.connect(lambda checked=False, g=game: self.show_full_history_model_stats(g))
        hist_btn.setStyleSheet("background:#8E44AD;color:white;font-weight:bold;padding:4px 6px;font-size:11px;")
        hist_btn.setToolTip("全历史遗漏/频次统计 + 全模型回测 + 自动学习预测")

        # 重号边号统计预测按钮
        re_btn_grp = QPushButton("🔁 重号边号统计")
        re_btn_grp.clicked.connect(lambda checked=False, g=game: self.show_repeat_edge_stats(g))
        re_btn_grp.setStyleSheet("background:#16A085;color:white;font-weight:bold;padding:4px 6px;font-size:11px;")
        re_btn_grp.setToolTip("重号/边号/连号统计与预测，支持直接投注")

        # 本地历史预测推荐按钮
        scrapling_btn = QPushButton("🔮 本地历史预测推荐")
        scrapling_btn.setEnabled(True)
        scrapling_btn.setStyleSheet(
            "background:qlineargradient(x1:0,y1:0,x2:1,y2:0,stop:0 #1a1a2e,stop:1 #16213e);"
            "color:#00d4ff;font-weight:bold;padding:4px 6px;font-size:11px;border-radius:4px;"
            "border:1px solid #00d4ff;")
        scrapling_btn.setToolTip("🕷 Scrapling爬虫实时抓取官网+多预测网站数据，生成8组多算法预测推荐\n无需API密钥，直接访问中国彩票官网")
        scrapling_btn.clicked.connect(lambda checked=False, g=game: self.show_scrapling_predict(g))

        layout.addWidget(compare_btn)
        layout.addWidget(hist_btn)
        layout.addWidget(re_btn_grp)
        layout.addWidget(scrapling_btn)

        # 九宫格矩阵 + 高尔顿模型
        nine_grid_btn = QPushButton("🔲 九宫格矩阵+高尔顿预测")
        nine_grid_btn.setStyleSheet(
            "background:qlineargradient(x1:0,y1:0,x2:1,y2:0,stop:0 #1E8449,stop:1 #2E86C1);"
            "color:white;font-weight:bold;padding:6px;font-size:12px;border-radius:4px;")
        nine_grid_btn.setToolTip(
            "九宫格矩阵：将号码空间分9区均衡采样\n"
            "高尔顿模型：时间衰减+高斯扩散+遗漏修正机器学习预测")
        nine_grid_btn.clicked.connect(lambda checked=False, g=game: self.open_nine_grid(g))
        layout.addWidget(nine_grid_btn)

        # 双重嵌套覆盖系统 — 全玩法支持
        nested_btn = QPushButton("🎯 双重嵌套覆盖系统")
        nested_btn.setStyleSheet(
            "background:qlineargradient(x1:0,y1:0,x2:1,y2:0,"
            "stop:0 #1A5276,stop:1 #7D3C98);"
            "color:white;font-weight:bold;padding:7px;font-size:13px;")
        nested_btn.setToolTip(
            "第一层：胆码旋转（对冲单点风险）\n"
            "第二层：拖码矩阵缩水（压榨资金效率）\n"
            "内置全部25个预测模型推荐，支持重号/边码/关系码分析")
        nested_btn.clicked.connect(lambda checked=False, g=game: self.nested_coverage_bet(g))
        layout.addWidget(nested_btn)

        # 龙头凤尾预测 + 集合覆盖分析
        dp_row = QHBoxLayout()
        dp_btn = QPushButton("🐉 龙头凤尾预测")
        dp_btn.setStyleSheet(
            "background:qlineargradient(x1:0,y1:0,x2:1,y2:0,"
            "stop:0 #922B21,stop:1 #1F618D);"
            "color:white;font-weight:bold;padding:6px;font-size:12px;border-radius:4px;")
        dp_btn.setToolTip(
            "🐉 龙头（每期最小号）& 凤尾（每期最大号）历史统计预测\n"
            "🔗 集合运算：交集/并集/差集/补集 多算法覆盖筛选\n"
            "🎯 生成最终投注推荐号码")
        dp_btn.clicked.connect(lambda checked=False, g=game: self.dragon_phoenix_predict(g))
        dp_row.addWidget(dp_btn)

        cover_btn = QPushButton("🔗 集合覆盖分析")
        cover_btn.setStyleSheet(
            "background:qlineargradient(x1:0,y1:0,x2:1,y2:0,"
            "stop:0 #1A5276,stop:1 #117A65);"
            "color:white;font-weight:bold;padding:6px;font-size:12px;border-radius:4px;")
        cover_btn.setToolTip(
            "多预测集合的交集/并集/差集/补集运算\n"
            "找出各算法共识号码或独特号码，精准覆盖")
        cover_btn.clicked.connect(lambda checked=False, g=game: self.dragon_phoenix_predict(g))
        dp_row.addWidget(cover_btn)
        layout.addLayout(dp_row)

        # 图片识别 + 扫码查奖（快速入口）
        scan_row = QHBoxLayout()
        img_btn2 = QPushButton("🖼 图片识别")
        img_btn2.setStyleSheet("background:#6C3483;color:white;font-weight:bold;font-size:11px;padding:5px;")
        img_btn2.clicked.connect(lambda checked=False: self.open_image_recognize())
        scan_row.addWidget(img_btn2)
        qr_btn2 = QPushButton("📷 扫码查奖")
        qr_btn2.setStyleSheet("background:#1E8449;color:white;font-weight:bold;font-size:11px;padding:5px;")
        qr_btn2.clicked.connect(lambda checked=False: self.open_qr_scan())
        scan_row.addWidget(qr_btn2)
        layout.addLayout(scan_row)

        group.setLayout(layout)
        return group

