    # ---------- 走势图相关方法 ----------
    def on_trend_game_changed(self):
        """玩法改变时更新走势图和号码按钮"""
        game = self.trend_game_combo.currentText()
        self.draw_trend_chart(game)
        self.create_trend_buttons(game)

    def draw_trend_chart(self, game_type):
        """绘制走势图"""
        self.trend_figure.clear()
        if game_type not in self.history_data or not self.history_data[game_type]:
            ax = self.trend_figure.add_subplot(211)
            ax.text(0.5, 0.5, f"暂无{game_type}历史数据", ha='center', va='center')
            self.trend_canvas.draw()
            return

        records = sorted(self.history_data[game_type], key=lambda x: x.get("期号", ""), reverse=True)
        period_count = self.trend_period_spin.value()
        records = records[:period_count]  # 取最近 period_count 期
        records.reverse()  # 按时间正序排列（从左到右）

        issues = [r.get("期号", "")[-4:] for r in records]  # 取期号后四位

        if game_type == "双色球":
            ax = self.trend_figure.add_subplot(211)
            red_data = []
            blue_data = []
            for r in records:
                nums = parse_draw_numbers(r.get("开奖号码", ""))
                if len(nums) >= 7:
                    red_data.append(nums[:6])
                    blue_data.append(nums[6])
                else:
                    red_data.append([0]*6)
                    blue_data.append(0)
            # 绘制红球（6条线）
            for i in range(6):
                values = [d[i] for d in red_data]
                ax.plot(range(len(issues)), values, marker='o', label=f'红球{i+1}')
            ax.set_title(f"{game_type} 红球走势")
            ax.set_xticks(range(len(issues)))
            ax.set_xticklabels(issues, rotation=45)
            ax.legend(loc='upper left', fontsize=8)
            ax.grid(True)

            # 蓝球单独一个子图
            ax2 = self.trend_figure.add_subplot(212)
            ax2.plot(range(len(issues)), blue_data, marker='s', color='blue', label='蓝球')
            ax2.set_title("蓝球走势")
            ax2.set_xticks(range(len(issues)))
            ax2.set_xticklabels(issues, rotation=45)
            ax2.legend()
            ax2.grid(True)
            self.trend_figure.tight_layout()

        elif game_type == "大乐透":
            ax = self.trend_figure.add_subplot(211)
            front_data = []
            back_data = []
            for r in records:
                nums = parse_draw_numbers(r.get("开奖号码", ""))
                if len(nums) >= 7:
                    front_data.append(nums[:5])
                    back_data.append(nums[5:7])
                else:
                    front_data.append([0]*5)
                    back_data.append([0,0])
            for i in range(5):
                values = [d[i] for d in front_data]
                ax.plot(range(len(issues)), values, marker='o', label=f'前区{i+1}')
            ax.set_title(f"{game_type} 前区走势")
            ax.set_xticks(range(len(issues)))
            ax.set_xticklabels(issues, rotation=45)
            ax.legend(loc='upper left', fontsize=8)
            ax.grid(True)

            ax2 = self.trend_figure.add_subplot(212)
            for i in range(2):
                values = [d[i] for d in back_data]
                ax2.plot(range(len(issues)), values, marker='s', label=f'后区{i+1}')
            ax2.set_title("后区走势")
            ax2.set_xticks(range(len(issues)))
            ax2.set_xticklabels(issues, rotation=45)
            ax2.legend()
            ax2.grid(True)
            self.trend_figure.tight_layout()

        elif game_type == "3D":
            ax = self.trend_figure.add_subplot(111)
            pos_data = []
            for r in records:
                nums = parse_draw_numbers(r.get("开奖号码", ""))
                if len(nums) >= 3:
                    pos_data.append(nums[:3])
                else:
                    pos_data.append([0,0,0])
            for i in range(3):
                values = [d[i] for d in pos_data]
                ax.plot(range(len(issues)), values, marker='o', label=['百位','十位','个位'][i])
            ax.set_title(f"{game_type} 走势")
            ax.set_xticks(range(len(issues)))
            ax.set_xticklabels(issues, rotation=45)
            ax.legend()
            ax.grid(True)
            self.trend_figure.tight_layout()

        elif game_type == "排列三":
            ax = self.trend_figure.add_subplot(111)
            pos_data = []
            for r in records:
                nums = parse_draw_numbers(r.get("开奖号码", ""))
                if len(nums) >= 3:
                    pos_data.append(nums[:3])
                else:
                    pos_data.append([0,0,0])
            for i in range(3):
                values = [d[i] for d in pos_data]
                ax.plot(range(len(issues)), values, marker='o', label=['百位','十位','个位'][i])
            ax.set_title(f"{game_type} 走势")
            ax.set_xticks(range(len(issues)))
            ax.set_xticklabels(issues, rotation=45)
            ax.legend()
            ax.grid(True)
            self.trend_figure.tight_layout()

        elif game_type == "七星彩":
            ax = self.trend_figure.add_subplot(111)
            pos_data = []
            for r in records:
                nums = parse_draw_numbers(r.get("开奖号码", ""))
                if len(nums) >= 7:
                    pos_data.append(nums[:7])
                else:
                    pos_data.append([0]*7)
            for i in range(7):
                values = [d[i] for d in pos_data]
                ax.plot(range(len(issues)), values, marker='o', label=f'第{i+1}位')
            ax.set_title(f"{game_type} 走势")
            ax.set_xticks(range(len(issues)))
            ax.set_xticklabels(issues, rotation=45)
            ax.legend(loc='upper left', fontsize=8)
            ax.grid(True)
            self.trend_figure.tight_layout()

        elif game_type == "排列五":
            ax = self.trend_figure.add_subplot(111)
            pos_data = []
            for r in records:
                nums = parse_draw_numbers(r.get("开奖号码", ""))
                if len(nums) >= 5:
                    pos_data.append(nums[:5])
                else:
                    pos_data.append([0]*5)
            for i in range(5):
                values = [d[i] for d in pos_data]
                ax.plot(range(len(issues)), values, marker='o', label=['万位','千位','百位','十位','个位'][i])
            ax.set_title(f"{game_type} 走势")
            ax.set_xticks(range(len(issues)))
            ax.set_xticklabels(issues, rotation=45)
            ax.legend()
            ax.grid(True)
            self.trend_figure.tight_layout()

        elif game_type == "快乐8":
            ax = self.trend_figure.add_subplot(111)
            # 快乐8有20个号码，绘制平均值作为参考
            avg_data = []
            for r in records:
                nums = parse_draw_numbers(r.get("开奖号码", ""))
                if nums:
                    avg_data.append(np.mean(nums[:20]))
                else:
                    avg_data.append(0)
            ax.plot(range(len(issues)), avg_data, marker='o', color='purple', label='平均值')
            ax.set_title(f"{game_type} 平均值走势")
            ax.set_xticks(range(len(issues)))
            ax.set_xticklabels(issues, rotation=45)
            ax.legend()
            ax.grid(True)
            self.trend_figure.tight_layout()

        elif game_type == "七乐彩":
            ax = self.trend_figure.add_subplot(111)
            avg_data = []
            for r in records:
                nums = parse_draw_numbers(r.get("开奖号码", ""))
                if nums:
                    avg_data.append(np.mean(nums[:7]))
                else:
                    avg_data.append(0)
            ax.plot(range(len(issues)), avg_data, marker='o', color='green', label='平均值')
            ax.set_title(f"{game_type} 平均值走势")
            ax.set_xticks(range(len(issues)))
            ax.set_xticklabels(issues, rotation=45)
            ax.legend()
            ax.grid(True)
            self.trend_figure.tight_layout()

        self.trend_canvas.draw()

    def create_trend_buttons(self, game_type):
        """根据玩法创建号码按钮"""
        # 清除旧按钮
        for i in reversed(range(self.trend_buttons_layout.count())):
            item = self.trend_buttons_layout.itemAt(i)
            if item.widget():
                item.widget().deleteLater()

        self.trend_buttons = []  # 存储所有按钮，每个元素为 (区域名, 按钮列表)

        if game_type == "双色球":
            # 红球区域
            red_group = QGroupBox("红球 (1-33)")
            red_layout = QGridLayout()
            red_buttons = []
            for i in range(1, 34):
                omission = self.get_omission(game_type, i, "red")
                frequency = self.get_frequency(game_type, i, "red")
                cold_hot = self.get_cold_hot(game_type, i, "red")
                btn = NumberButton(str(i), cold_hot, omission, frequency, probability=0)
                btn.clicked.connect(self.trend_update_selection)
                red_buttons.append(btn)
                row = (i-1) // 6
                col = (i-1) % 6
                red_layout.addWidget(btn, row, col)
            red_group.setLayout(red_layout)
            red_group.setStyleSheet("QGroupBox{font-size:11px;padding-top:14px;margin-top:2px;}QGroupBox::title{top:2px;}")
            self.trend_buttons_layout.addWidget(red_group)
            self.trend_buttons.append(("red", red_buttons))

            # 蓝球区域
            blue_group = QGroupBox("蓝球 (1-16)")
            blue_layout = QGridLayout()
            blue_buttons = []
            for i in range(1, 17):
                omission = self.get_omission(game_type, i, "blue")
                frequency = self.get_frequency(game_type, i, "blue")
                cold_hot = self.get_cold_hot(game_type, i, "blue")
                btn = NumberButton(str(i), cold_hot, omission, frequency, probability=0)
                btn.clicked.connect(self.trend_update_selection)
                blue_buttons.append(btn)
                row = (i-1) // 8
                col = (i-1) % 8
                blue_layout.addWidget(btn, row, col)
            blue_group.setLayout(blue_layout)
            blue_group.setStyleSheet("QGroupBox{font-size:11px;padding-top:14px;margin-top:2px;}QGroupBox::title{top:2px;}")
            self.trend_buttons_layout.addWidget(blue_group)
            self.trend_buttons.append(("blue", blue_buttons))

        elif game_type == "大乐透":
            front_group = QGroupBox("前区 (1-35)")
            front_layout = QGridLayout()
            front_buttons = []
            for i in range(1, 36):
                omission = self.get_omission(game_type, i, "front")
                frequency = self.get_frequency(game_type, i, "front")
                cold_hot = self.get_cold_hot(game_type, i, "front")
                btn = NumberButton(str(i), cold_hot, omission, frequency, probability=0)
                btn.clicked.connect(self.trend_update_selection)
                front_buttons.append(btn)
                row = (i-1) // 7
                col = (i-1) % 7
                front_layout.addWidget(btn, row, col)
            front_group.setLayout(front_layout)
            front_group.setStyleSheet("QGroupBox{font-size:11px;padding-top:14px;margin-top:2px;}QGroupBox::title{top:2px;}")
            self.trend_buttons_layout.addWidget(front_group)
            self.trend_buttons.append(("front", front_buttons))

            back_group = QGroupBox("后区 (1-12)")
            back_layout = QGridLayout()
            back_buttons = []
            for i in range(1, 13):
                omission = self.get_omission(game_type, i, "back")
                frequency = self.get_frequency(game_type, i, "back")
                cold_hot = self.get_cold_hot(game_type, i, "back")
                btn = NumberButton(str(i), cold_hot, omission, frequency, probability=0)
                btn.clicked.connect(self.trend_update_selection)
                back_buttons.append(btn)
                row = (i-1) // 6
                col = (i-1) % 6
