        parse_btn.setStyleSheet("background:#8E44AD;color:white;font-weight:bold;padding:7px;")
        add_bet_btn = QPushButton("💰 全部加入投注")
        add_bet_btn.setStyleSheet("background:#27AE60;color:white;font-weight:bold;padding:7px;")
        copy_btn   = QPushButton("📋 复制内容")
        copy_btn.setStyleSheet("background:#2980B9;color:white;font-weight:bold;padding:7px;")
        close_btn  = QPushButton("关闭")
        close_btn.setStyleSheet("padding:7px;")
        for b in (parse_btn, add_bet_btn, copy_btn, close_btn):
            btn_row.addWidget(b)
        lay.addLayout(btn_row)

        # ── 状态栏 ────────────────────────────────────────────────────
        status_lbl = QLabel("")
        status_lbl.setStyleSheet("font-size:11px;color:#555;padding:2px 4px;")
        lay.addWidget(status_lbl)

        _parsed = []

        # ── 辅助函数 ──────────────────────────────────────────────────
        def load_files():
            file_list.clear()
            try:
                AUTO_PREDICT_DIR.mkdir(parents=True, exist_ok=True)
                files = sorted(AUTO_PREDICT_DIR.glob("*.txt"), reverse=True)
                for f in files:
                    file_list.addItem(f.name)
                if not files:
                    status_lbl.setText(f"共 0 个历史文件，目录: {AUTO_PREDICT_DIR}；已尝试生成当天预测，请稍后点刷新")
                    QTimer.singleShot(0, lambda: self._run_auto_predict_daily_if_needed(force=True))
                else:
                    status_lbl.setText(f"共 {len(files)} 个历史文件，目录: {AUTO_PREDICT_DIR}")
            except Exception as ex:
                status_lbl.setText(f"读取失败: {ex}")

        def on_file_select(item):
            try:
                fpath = AUTO_PREDICT_DIR / item.text()
                txt = fpath.read_text(encoding="utf-8")
                content_te.setPlainText(txt)
                paste_te.clear()
                status_lbl.setText(f"已加载: {item.text()}")
            except Exception as ex:
                content_te.setPlainText(f"读取失败: {ex}")

        def do_delete_selected():
            items = file_list.selectedItems()
            if not items:
                QMessageBox.information(dlg, "提示", "请先在左侧列表中选中要删除的文件")
                return
            names = [it.text() for it in items]
            reply = QMessageBox.question(
                dlg, "确认删除",
                f"确定删除以下 {len(names)} 个预测文件？\n" + "\n".join(names[:10])
                + ("\n..." if len(names) > 10 else ""),
                QMessageBox.Yes | QMessageBox.No, QMessageBox.No)
            if reply != QMessageBox.Yes:
                return
            deleted = 0
            for name in names:
                try:
                    (AUTO_PREDICT_DIR / name).unlink()
                    deleted += 1
                except Exception as ex:
                    status_lbl.setText(f"删除 {name} 失败: {ex}")
            load_files()
            content_te.clear()
            status_lbl.setText(f"已删除 {deleted} 个文件")

        def do_delete_all():
            files = list(AUTO_PREDICT_DIR.glob("*.txt"))
            if not files:
                QMessageBox.information(dlg, "提示", "没有可删除的历史文件"); return
            reply = QMessageBox.question(
                dlg, "⚠️ 确认清空",
                f"确定清空全部 {len(files)} 个历史预测文件？\n此操作不可恢复！",
                QMessageBox.Yes | QMessageBox.No, QMessageBox.No)
            if reply != QMessageBox.Yes:
                return
            deleted = 0
            for f in files:
                try:
                    f.unlink(); deleted += 1
                except Exception:
                    pass
            load_files()
            content_te.clear()
            status_lbl.setText(f"已清空全部 {deleted} 个文件")

        def do_parse():
            import re as _re
            _parsed.clear()
            raw = paste_te.toPlainText().strip() or content_te.toPlainText().strip()
            if not raw:
                QMessageBox.information(dlg, "提示", "请先选择历史文件或粘贴预测文本"); return
            game_type = "未知"
            for g in ["双色球","大乐透","七星彩","排列五","排列三","3D","快乐8","七乐彩"]:
                if g in raw:
                    game_type = g; break
            lines = raw.splitlines()
            display_lines = [f"游戏: {game_type}", "─" * 44]
            for ln in lines:
                line = ln.strip()
                m = _re.match(r"第(\d+)(?:注|组)[：:]\s*(.+)", line)
                if not m:
                    continue
                idx = m.group(1); nums_raw = m.group(2).strip()
                # 兼容：第01注: 07 09...；第1注（单式5+2）: 前区[...] 后区[...]；第24注: 选7: ...
                display_lines.append(f"第{idx}注: {nums_raw}")
                _parsed.append({"idx": idx, "raw": nums_raw, "game": game_type})
            if _parsed:
                display_lines.insert(2, f"共解析 {len(_parsed)} 注")
                content_te.setPlainText("\n".join(display_lines))
                status_lbl.setText(f"解析完成：{len(_parsed)} 注，游戏：{game_type}")
            else:
                content_te.setPlainText("未找到符合格式的预测号码行\n\n原始内容：\n" + raw[:500])
                status_lbl.setText("解析结果：未找到号码行")

        def do_add_bet():
            if not _parsed:
                do_parse()
                if not _parsed: return
            game = _parsed[0]["game"] if _parsed else "未知"
            cfg = NINE_GRID_CONFIG.get(game, {})
            price = cfg.get("price", 2.0)
            target = self.get_default_target_issue(game)
            for p in _parsed:
                self.add_betting_record(game, "九宫格历史导入", p["raw"], 1, price, target_issue=target)
            QMessageBox.information(dlg, "✅ 成功", f"已将 {len(_parsed)} 注历史预测加入《{game}》投注记录！")
            status_lbl.setText(f"已加入投注 {len(_parsed)} 注")

        def do_copy():
            txt = paste_te.toPlainText().strip() or content_te.toPlainText().strip()
            if txt:
                QApplication.clipboard().setText(txt)
                status_lbl.setText("已复制到剪贴板")

        refresh_btn.clicked.connect(load_files)
        file_list.itemClicked.connect(on_file_select)
        del_btn.clicked.connect(do_delete_selected)
        del_all_btn.clicked.connect(do_delete_all)
        parse_btn.clicked.connect(do_parse)
        add_bet_btn.clicked.connect(do_add_bet)
        copy_btn.clicked.connect(do_copy)
        close_btn.clicked.connect(dlg.accept)

        load_files()
        dlg.exec()



