    def import_history_data(self):
        """从文件导入历史数据"""
        file_path, _ = QFileDialog.getOpenFileName(self, "导入历史数据", "", "JSON Files (*.json)")
        if file_path:
            try:
                with open(file_path, "r", encoding="utf-8") as f:
                    data = json.load(f)
                # 简单合并
                for game, records in data.items():
                    if game in self.history_data:
                        existing_issues = {r["期号"] for r in self.history_data[game]}
                        for rec in records:
                            if rec["期号"] not in existing_issues:
                                self.history_data[game].append(rec)
                        self.history_data[game].sort(key=lambda x: x["期号"], reverse=True)
                    else:
                        self.history_data[game] = records
                self.save_game_history_data("all")
                self.update_history_table()
                self.display_current_game_results()
                self.calculate_omission()
                QMessageBox.information(self, "成功", "历史数据导入完成")
            except Exception as e:
                QMessageBox.warning(self, "错误", f"导入失败: {str(e)}")

    def export_history_data(self):
        """导出历史数据到文件"""
        file_path, _ = QFileDialog.getSaveFileName(self, "导出历史数据", "", "JSON Files (*.json)")
        if file_path:
            try:
                with open(file_path, "w", encoding="utf-8") as f:
                    json.dump(self.history_data, f, ensure_ascii=False, indent=2)
                QMessageBox.information(self, "成功", f"数据已导出到 {file_path}")
            except Exception as e:
                QMessageBox.warning(self, "错误", f"导出失败: {str(e)}")

