    def fetch_latest_results(self):
        """获取所有彩票最新开奖（极速API主源）"""
        import threading
        def _worker():
            games = ["双色球", "大乐透", "快乐8", "3D", "七乐彩", "七星彩", "排列三", "排列五"]
            for game in games:
                try:
                    latest = self.fetch_jisuapi_lottery_latest(game)
                    if latest:
                        if game not in self.history_data: self.history_data[game] = []
                        existing = {r["期号"] for r in self.history_data[game]}
                        if latest["期号"] not in existing:
                            self.history_data[game].insert(0, latest)
                            self.history_data[game].sort(key=lambda x:x.get("期号",""), reverse=True)
                except Exception as e:
                    logger.warning(f"fetch_latest {game}: {e}")
            self._save_all_history()
            QTimer.singleShot(0, self.update_home_info)
            QTimer.singleShot(0, self.update_results_display)
        threading.Thread(target=_worker, daemon=True).start()



    def fetch_single_result(self):
        """按期号查询单期开奖（极速API）"""
        issue, ok = QInputDialog.getText(self, "按期号查询", "请输入期号（如 2024001）:")
        if not ok or not issue.strip(): return
        game = self.network_game_combo.currentText()
        caid = JISUAPI_CONFIG["lottery_id_map"].get(game)
        if not caid:
            QMessageBox.warning(self, "错误", f"不支持的彩票类型: {game}"); return
        import threading
        def _worker():
            try:
                result = self._jisuapi_get(JISUAPI_CONFIG["lottery_query"],
                                          {"caipiaoid": caid, "issueno": issue.strip()})
                if not result:
                    QTimer.singleShot(0, lambda: QMessageBox.warning(self,"错误","未找到该期数据"))
                    return
                rows = [result] if isinstance(result, dict) else result
                def _ui():
                    self.result_table.setRowCount(len(rows))
                    for row, rec in enumerate(rows):
                        self.result_table.setItem(row,0,QTableWidgetItem(str(rec.get("issueno",rec.get("期号","")))))
                        self.result_table.setItem(row,1,QTableWidgetItem(str(rec.get("opendate",rec.get("开奖日期","")))))
                        self.result_table.setItem(row,2,QTableWidgetItem(str(rec.get("number",rec.get("开奖号码","")))))
                        self.result_table.setItem(row,3,QTableWidgetItem(str(rec.get("saleamount",rec.get("销售额","")))))
                        # 一等奖信息
                        prizes = _normalize_jisu_prize_list(rec.get("prize")) or _normalize_jisu_prize_list(rec.get("奖级"))
                        p1 = prizes[0] if prizes else {}
                        self.result_table.setItem(row,4,QTableWidgetItem(str(p1.get("singlebonus",p1.get("单注","—")))))
                        self.result_table.setItem(row,5,QTableWidgetItem(str(p1.get("num",p1.get("注数","—")))))
                        p2 = prizes[1] if len(prizes)>1 else {}
                        self.result_table.setItem(row,6,QTableWidgetItem(str(p2.get("num",p2.get("注数","—")))))
                    QMessageBox.information(self,"成功",f"查询到 {len(rows)} 条记录  来源: 极速API")
                QTimer.singleShot(0, _ui)
            except Exception as e:
                QTimer.singleShot(0, lambda e=e: QMessageBox.critical(self,"错误",f"查询失败: {e}"))
        threading.Thread(target=_worker, daemon=True).start()


    def fetch_history_results(self):
        """查询历史开奖多期（极速API）"""
        game = self.network_game_combo.currentText()
        caid = JISUAPI_CONFIG["lottery_id_map"].get(game)
        if not caid:
            QMessageBox.warning(self, "错误", f"不支持的彩票类型: {game}"); return
        num, ok = QInputDialog.getInt(self, "查询历史", "请输入要查询的期数 (最大50):", 30, 1, 50)
        if not ok: return
        import threading
        def _worker():
            try:
                result = self._jisuapi_get(JISUAPI_CONFIG["lottery_history"],
                                          {"caipiaoid": caid, "issueno": ""})
                if not result:
                    QTimer.singleShot(0, lambda: QMessageBox.warning(self,"错误","极速API未返回数据"))
                    return
                records = result.get("list", [])[:num] if isinstance(result, dict) else result[:num]
                # 同时存入历史库
                if game not in self.history_data: self.history_data[game] = []
                existing = {r["期号"] for r in self.history_data[game]}
                added = 0
                for rec in records:
                    formatted = {
                        "期号": str(rec.get("issueno","")),
                        "开奖日期": str(rec.get("opendate","")),
                        "开奖号码": str(rec.get("number","")),
                        "参考号码": str(rec.get("refernumber","")),
                        "销售额": str(rec.get("saleamount","")),
                        "奖级": _jisu_prize_to_levels(rec.get("prize")),
                        "来源": "jisuapi",
                    }
                    if formatted["期号"] and formatted["期号"] not in existing:
                        self.history_data[game].insert(0, formatted)
                        added += 1
                if added > 0:
                    self.history_data[game].sort(key=lambda x:x.get("期号",""), reverse=True)
                    self._save_all_history()
                def _ui():
                    self.result_table.setRowCount(len(records))
                    for row, rec in enumerate(records):
                        self.result_table.setItem(row,0,QTableWidgetItem(str(rec.get("issueno",""))))
                        self.result_table.setItem(row,1,QTableWidgetItem(str(rec.get("opendate",""))))
                        self.result_table.setItem(row,2,QTableWidgetItem(str(rec.get("number",""))))
                        self.result_table.setItem(row,3,QTableWidgetItem(str(rec.get("saleamount",""))))
                        prizes = _normalize_jisu_prize_list(rec.get("prize"))
                        p1 = prizes[0] if prizes else {}
                        self.result_table.setItem(row,4,QTableWidgetItem(str(p1.get("singlebonus","—"))))
                        self.result_table.setItem(row,5,QTableWidgetItem(str(p1.get("num","—"))))
                        p2 = prizes[1] if len(prizes)>1 else {}
                        self.result_table.setItem(row,6,QTableWidgetItem(str(p2.get("num","—"))))
                    QMessageBox.information(self,"✅ 成功",f"获取 {len(records)} 期，新增入库 {added} 期\n来源: 极速API (jisuapi.com)")
                QTimer.singleShot(0, _ui)
            except Exception as e:
                QTimer.singleShot(0, lambda e=e: QMessageBox.critical(self,"错误",f"查询失败: {e}"))
        threading.Thread(target=_worker, daemon=True).start()

    def toggle_auto_fetch(self, state):
        """切换自动更新"""
        if state == Qt.Checked:
            if not self.auto_update_timer:
                self.auto_update_timer = QTimer()
                self.auto_update_timer.timeout.connect(self.auto_update_all_games)
                self.auto_update_timer.start(1800000)  # 30分钟
            QMessageBox.information(self, "自动更新", "自动更新已开启（30分钟一次）")
        else:
            if self.auto_update_timer:
                self.auto_update_timer.stop()
                self.auto_update_timer = None
            QMessageBox.information(self, "自动更新", "自动更新已关闭")

    def save_to_history(self):
        """将当前网络标签页显示的数据保存到历史库"""
        game = self.network_game_combo.currentText()
        new_count = 0
        for row in range(self.result_table.rowCount()):
            issue_item = self.result_table.item(row, 0)
            date_item = self.result_table.item(row, 1)
            number_item = self.result_table.item(row, 2)
            sale_item = self.result_table.item(row, 3)
            pool_item = self.result_table.item(row, 4)
            first_item = self.result_table.item(row, 5)
            second_item = self.result_table.item(row, 6)
            if issue_item and number_item:
                record = {
                    "期号": issue_item.text(),
                    "开奖日期": date_item.text() if date_item else "",
                    "开奖号码": number_item.text(),
                    "销售额": sale_item.text() if sale_item else "0元",
                    "奖池": pool_item.text() if pool_item else "0元",
                    "一等奖": first_item.text() if first_item else "0注",
                    "二等奖": second_item.text() if second_item else "0注"
                }
                # 去重
                if game not in self.history_data:
                    self.history_data[game] = []
                if record["期号"] not in [r["期号"] for r in self.history_data[game]]:
                    self.history_data[game].append(record)
                    new_count += 1
        if new_count > 0:
            self.history_data[game].sort(key=lambda x: x["期号"], reverse=True)
            self.save_game_history_data(game)
            self.update_history_table()
            self.calculate_omission()
            QMessageBox.information(self, "成功", f"已保存 {new_count} 条新记录到历史库")
        else:
            QMessageBox.information(self, "提示", "没有新数据需要保存")

    def analyze_current(self):
        """分析当前网络标签页显示的数据（简单显示统计信息）"""
        game = self.network_game_combo.currentText()
        rows = self.result_table.rowCount()
        if rows == 0:
            QMessageBox.information(self, "分析", "当前没有数据可分析")
            return
        numbers_list = []
        for row in range(rows):
            number_item = self.result_table.item(row, 2)
            if number_item:
                nums = parse_draw_numbers(number_item.text())
                numbers_list.append(nums)
        if not numbers_list:
            return
        all_nums = [num for sublist in numbers_list for num in sublist]
        freq = Counter(all_nums)
        sorted_freq = freq.most_common(10)
        analysis = f"共 {len(numbers_list)} 期开奖\n"
        analysis += "号码出现频率 TOP10：\n"
        for num, cnt in sorted_freq[:10]:
            analysis += f"  号码 {num}: {cnt} 次\n"
        QMessageBox.information(self, f"{game} 分析结果", analysis)

    def show_trend_chart(self):
        """显示走势图（在数据分析标签页）"""
        game = self.analysis_game_combo.currentText()
        if game not in self.history_data or not self.history_data[game]:
            QMessageBox.warning(self, "错误", f"{game} 暂无历史数据")
            return
        # 复用走势图标签页的功能，直接切换到该标签页
        self.tabs.setCurrentWidget(self.trend_tab)
        self.trend_game_combo.setCurrentText(game)
        self.on_trend_game_changed()

    def show_heatmap(self):
        """显示热力图（频率分布）"""
        game = self.analysis_game_combo.currentText()
        if game not in self.history_data or not self.history_data[game]:
            QMessageBox.warning(self, "错误", f"{game} 暂无历史数据")
            return
        self.figure.clear()
        ax = self.figure.add_subplot(111)
        if game == "双色球":
            # 绘制红球频率热力图
            if "red" in self.frequency_data.get(game, {}):
                freqs = self.frequency_data[game]["red"]
                nums = sorted(freqs.keys())
                values = [freqs[n] for n in nums]
                ax.bar(nums, values, color='red', alpha=0.7)
                ax.set_xlabel("红球号码")
                ax.set_ylabel("出现次数")
                ax.set_title(f"{game} 红球出现频率")
        elif game == "大乐透":
            # 前区
            if "front" in self.frequency_data.get(game, {}):
                freqs = self.frequency_data[game]["front"]
                nums = sorted(freqs.keys())
                values = [freqs[n] for n in nums]
                ax.bar(nums, values, color='orange', alpha=0.7)
                ax.set_xlabel("前区号码")
                ax.set_ylabel("出现次数")
                ax.set_title(f"{game} 前区出现频率")
        else:
            ax.text(0.5, 0.5, f"{game} 热力图暂未实现", ha='center', va='center')
        self.canvas.draw()

    def show_coldhot(self):
        """显示冷热号分析"""
        game = self.analysis_game_combo.currentText()
        if game not in self.cold_hot_data:
            QMessageBox.warning(self, "错误", f"{game} 暂无冷热数据")
            return
        self.figure.clear()
        ax = self.figure.add_subplot(111)
        # 简单显示最近一次的冷热分类
        text = f"{game} 冷热号分析\n"
        for area, data in self.cold_hot_data[game].items():
            hot = [num for num, cat in data.items() if cat == 'hot']
            warm = [num for num, cat in data.items() if cat == 'warm']
            cold = [num for num, cat in data.items() if cat == 'cold']
            text += f"\n{area}:\n  热号({len(hot)}个): {', '.join(map(str, hot[:10]))}{'...' if len(hot)>10 else ''}\n"
            text += f"  温号({len(warm)}个): {', '.join(map(str, warm[:10]))}{'...' if len(warm)>10 else ''}\n"
            text += f"  冷号({len(cold)}个): {', '.join(map(str, cold[:10]))}{'...' if len(cold)>10 else ''}\n"
        ax.text(0.5, 0.5, text, ha='center', va='center', wrap=True)
        self.canvas.draw()

    def clear_betting_history(self):
        """清空投注记录"""
        reply = QMessageBox.question(self, "确认清空", "确定要清空所有投注记录吗？",
                                      QMessageBox.Yes | QMessageBox.No)
        if reply == QMessageBox.Yes:
            self.betting_history = []
            self.update_records_table()
            self.save_betting_history()
            QMessageBox.information(self, "成功", "投注记录已清空")

    def export_to_csv(self):
        """导出投注记录到CSV文件"""
        if not self.betting_history:
            QMessageBox.warning(self, "错误", "没有记录可导出")
            return
        file_path, _ = QFileDialog.getSaveFileName(self, "导出CSV", "", "CSV Files (*.csv)")
        if file_path:
            try:
                import csv
                with open(file_path, 'w', newline='', encoding='utf-8-sig') as f:
                    writer = csv.writer(f)
                    writer.writerow(["游戏", "投注类型", "号码", "注数", "金额", "时间", "目标期号", "追加", "已兑奖", "中奖等级", "奖金"])
                    for record in self.betting_history:
                        writer.writerow([
                            record.get("game", ""),
                            record.get("bet_type", ""),
                            record.get("numbers", ""),
                            record.get("bets_count", 0),
                            record.get("amount", 0.0),
                            record.get("timestamp", ""),
                            record.get("target_issue", ""),
                            "是" if record.get("additional") else "否",
                            "是" if record.get("prize_checked") else "否",
                            record.get("prize_level", ""),
                            record.get("prize_amount", 0)
                        ])
                QMessageBox.information(self, "成功", f"记录已导出到 {file_path}")
            except Exception as e:
                QMessageBox.warning(self, "错误", f"导出失败: {str(e)}")

    def import_from_csv(self):
        """从CSV文件导入投注记录"""
        file_path, _ = QFileDialog.getOpenFileName(self, "导入CSV", "", "CSV Files (*.csv)")
        if file_path:
            try:
                import csv
                with open(file_path, 'r', encoding='utf-8-sig') as f:
                    reader = csv.reader(f)
                    header = next(reader)  # 跳过表头
                    for row in reader:
                        if len(row) >= 11:
                            record = {
                                "game": row[0],
                                "bet_type": row[1],
                                "numbers": row[2],
                                "bets_count": int(row[3]) if row[3].isdigit() else 0,
                                "amount": float(row[4]) if row[4] else 0.0,
                                "timestamp": row[5],
                                "target_issue": row[6],
                                "additional": row[7] == "是",
                                "prize_checked": row[8] == "是",
                                "prize_level": row[9],
                                "prize_amount": float(row[10]) if row[10] else 0.0,
                                "match_issue": ""
                            }
                            self.betting_history.append(record)
                self.update_records_table()
                self.save_betting_history()
                QMessageBox.information(self, "成功", "记录导入完成")
            except Exception as e:
                QMessageBox.warning(self, "错误", f"导入失败: {str(e)}")

    def export_analysis_data(self):
        """导出分析结果（在数据分析标签页）"""
        if not hasattr(self, 'analysis_result') or not self.analysis_result.toPlainText():
            QMessageBox.warning(self, "错误", "当前没有分析结果可导出")
            return
        file_path, _ = QFileDialog.getSaveFileName(self, "导出分析结果", "", "Text Files (*.txt)")
        if file_path:
            try:
                with open(file_path, 'w', encoding='utf-8') as f:
                    f.write(self.analysis_result.toPlainText())
                QMessageBox.information(self, "成功", f"分析结果已导出到 {file_path}")
            except Exception as e:
                QMessageBox.warning(self, "错误", f"导出失败: {str(e)}")


