    # ══════════════════════════════════════════════════════
    # 极速API (jisuapi.com) 数据接口方法
    # ══════════════════════════════════════════════════════

    def _jisuapi_get(self, endpoint, params=None):
        """极速API通用GET请求（带密钥检查+错误处理）"""
        import requests as _req
        # 兼容新旧密钥属性
        key = getattr(self, "jisuapi_key", "") or getattr(self, "api_key", "")
        if not key:
            logger.warning("极速API密钥未设置，请在设置→API密钥中填写")
            QTimer.singleShot(0, lambda: QMessageBox.warning(
                self, "⚠ 未设置密钥",
                "极速API密钥未设置！\n\n"
                "请点击右上角菜单 [⚙ 设置] → [🔑 设置API密钥]\n"
                "填写在 https://www.jisuapi.com 注册的 appkey\n\n"
                "（免费注册，有每天免费配额）"
            ))
            return None
        p = {"appkey": key}
        if params:
            p.update(params)
        url = JISUAPI_CONFIG["base_url"] + endpoint
        for attempt in range(2):
            try:
                resp = _req.get(url, params=p, timeout=15)
                data = resp.json()
                if str(data.get("status")) == "0":
                    return data.get("result", {})
                else:
                    msg = data.get("msg", "未知错误")
                    status = data.get("status", -1)
                    logger.warning(f"jisuapi {endpoint}: status={status} msg={msg}")
                    if status in (101, 102, 103):  # 密钥相关错误
                        QTimer.singleShot(0, lambda m=msg: QMessageBox.warning(
                            self, "❌ 密钥错误", f"极速API返回错误: {m}\n请检查密钥是否正确"))
                    return None
            except Exception as e:
                if attempt == 1:
                    logger.error(f"jisuapi {endpoint} error: {e}")
                    return None
        return None

    def fetch_real_lottery_ids(self):
        """从极速API /caipiao/class 获取真实caipiaoid，自动修正内置映射表。
        截图已确认正确ID，此方法作为校验用。
        """
        result = self._jisuapi_get(JISUAPI_CONFIG["lottery_class"])
        # class 接口直接返回列表（不是dict）
        if isinstance(result, dict):
            result = list(result.values())
        if not result or not isinstance(result, list):
            logger.warning("fetch_real_lottery_ids: 接口未返回列表")
            return False
        # 名称到代码的精确映射（根据截图15确认）
        _name_to_key = {
            "双色球": "双色球",
            "福彩3d": "3D",
            "七乐彩": "七乐彩",
            "快乐8":  "快乐8",
            "大乐透": "大乐透",
            "七星彩": "七星彩",
            "排列三": "排列三",
            "排列五": "排列五",
        }
        updated = 0
        all_ids = {}
        for item in result:
            name = str(item.get("name","")).strip()
            caid = item.get("caipiaoid")
            if not caid: continue
            all_ids[name] = caid
            key = _name_to_key.get(name.lower(), _name_to_key.get(name))
            if key and key in JISUAPI_CONFIG["lottery_id_map"]:
                old_id = JISUAPI_CONFIG["lottery_id_map"][key]
                if old_id != caid:
                    logger.info(f"自动修正 {key}: {old_id} → {caid}")
                    JISUAPI_CONFIG["lottery_id_map"][key] = caid
                    updated += 1
        logger.info(f"fetch_real_lottery_ids: {len(result)}种彩票, 修正{updated}个ID: {all_ids}")
        return True

    def fetch_jisuapi_lottery_latest(self, game_type):
        """获取指定彩票最新一期开奖（极速API /caipiao/query）
        返回字段: caipiaoid, issueno, number, refernumber,
                 opendate, officialopendate, deadline, saleamount, totalmoney, prize
        """
        caid = JISUAPI_CONFIG["lottery_id_map"].get(game_type)
        if not caid:
            logger.warning(f"fetch_jisuapi_lottery_latest: {game_type} 无对应caipiaoid")
            return None
        result = self._jisuapi_get(
            JISUAPI_CONFIG["lottery_query"],
            {"caipiaoid": caid, "issueno": ""}
        )
        if not result:
            return None
        main_num  = str(result.get("number", "")).strip()
        refer_num = str(result.get("refernumber", "")).strip()
        sale      = str(result.get("saleamount", ""))
        pool      = str(result.get("totalmoney", "0.00"))
        # 完整号码：主号+参考号（蓝球/特别号）
        if refer_num and refer_num not in ("", "0", "null", "None"):
            full_num = f"{main_num}+{refer_num}"
        else:
            full_num = main_num
        return {
            "期号":     str(result.get("issueno", "")),
            "开奖日期": str(result.get("opendate", result.get("officialopendate", ""))),
            "开奖号码": full_num,   # 含参考号
            "参考号码": refer_num,
            "完整号码": full_num,
            "截止时间": str(result.get("deadline", "")),
            "销售额":   sale,
            "奖池":     f"{pool}元" if pool and pool != "0.00" else (f"{sale}元" if sale else "—"),
            "奖级": _jisu_prize_to_levels(result.get("prize")),
            "来源": "jisuapi",
        }

    def fetch_jisuapi_lottery_history(self, game_type, count=40):
        """获取彩票历史开奖记录（极速API）
        注意：jisuapi history接口单次最多返回20条，通过start分页获取更多。
        默认获取40条（2次请求）。
        """
        caid = JISUAPI_CONFIG["lottery_id_map"].get(game_type)
        if not caid:
            logger.warning(f"fetch_jisuapi_lottery_history: {game_type} 无对应caipiaoid")
            return []
        items = []
        # 分页：每次20条，最多获取 count 条
        for start in range(0, count, 20):
            batch_num = min(20, count - start)
            result = self._jisuapi_get(
                JISUAPI_CONFIG["lottery_history"],
                {"caipiaoid": caid, "issueno": "", "num": batch_num, "start": start}
            )
            if not result:
                break
            batch = result.get("list", [])
            items.extend(batch)
            if len(batch) < batch_num:
                break  # 没有更多数据了
        records = []
        for item in items:
            # 开奖号码：主号码在 number，特别号在 refernumber
            main_num  = str(item.get("number", "")).strip()
            refer_num = str(item.get("refernumber", "")).strip()
            # 合并显示（双色球/大乐透等有特别号）
            if refer_num and refer_num not in ("", "0", "null", "None"):
                full_num = f"{main_num}+{refer_num}"
            else:
                full_num = main_num
            # 奖池金额：saleamount=销售额，totalmoney=奖池余额
            sale    = str(item.get("saleamount", ""))
            pool    = str(item.get("totalmoney", "0.00"))
            records.append({
                "期号":     str(item.get("issueno", "")),
                "开奖日期": str(item.get("opendate", item.get("officialopendate", ""))),
                "开奖号码": full_num,   # 含参考号（蓝球/特别号）用+分隔
                "参考号码": refer_num,
                "完整号码": full_num,
                "销售额":   sale,
                "奖池":     f"{pool}元" if pool and pool != "0.00" else (f"{sale}元" if sale else "—"),
                "奖级": _jisu_prize_to_levels(item.get("prize")),
                "来源": "jisuapi",
            })
        logger.info(f"fetch_jisuapi_lottery_history {game_type}(id={caid}): 获取{len(records)}条")
        return records

    def fetch_jisuapi_football(self, league="英超", date=""):
        """获取足球赛程（极速API /football/query）
        截图确认字段: start_date, start_time, right_team(主队), left_team(客队),
                     score_right(主分), score_left(客分), status(已结束/未开赛/进行中)
        """
        params = {"matchname": league}
        if date:
            params["date"] = date
        result = self._jisuapi_get(JISUAPI_CONFIG["football_query"], params)
        if not result:
            return []
        matches = []
        for item in result.get("list", []):
            home  = str(item.get("right_team", ""))   # jisuapi中 right=主队
            away  = str(item.get("left_team",  ""))   # jisuapi中 left=客队
            score_h = str(item.get("score_right", "-"))
            score_a = str(item.get("score_left",  "-"))
            status  = str(item.get("status", ""))
            matches.append({
                "序号":     len(matches) + 1,
                "联赛":     league,
                "主队":     home,
                "客队":     away,
                "主队分":   score_h,
                "客队分":   score_a,
                "比赛日期": str(item.get("start_date", "")),
                "比赛时间": str(item.get("start_time", "")),
                "状态":     status,
                "是否结束": status in ("已结束", "结束"),
            })
        return matches

    def fetch_jisuapi_football_rank(self, league="英超"):
        """获取足球联赛排名（极速API）"""
        result = self._jisuapi_get(JISUAPI_CONFIG["football_rank"], {"matchname": league})
        if not result: return []
        teams = []
        for group in result.get("list", []):
            for t in group.get("team_rank", []):
                teams.append({
                    "组别": group.get("group_name",""), "队伍": t.get("name",""),
                    "排名": t.get("rank",""), "场次": t.get("num",""),
                    "胜": t.get("win",""), "平": t.get("draw",""), "负": t.get("lose",""),
                    "进球": t.get("goal",""), "失球": t.get("diff",""), "积分": t.get("score",""),
                })
        return teams

    def fetch_jisuapi_nba(self, date=""):
        """获取NBA比分（极速API）"""
        params = {}
        if date: params["date"] = date
        result = self._jisuapi_get(JISUAPI_CONFIG["nba_query"], params)
        if not result: return []
        matches = []
        for item in result.get("list", []):
            matches.append({
                "序号":    len(matches)+1,
                "联赛":    "NBA",
                "主队":    item.get("hometeam",""),
                "客队":    item.get("awayteam",""),
                "主队分":  str(item.get("hometeam_score","-")),
                "客队分":  str(item.get("awayteam_score","-")),
                "比赛时间": item.get("starttime",""),
                "状态":    {"1":"未开赛","2":"进行中","3":"结束","4":"延期"}.get(str(item.get("status","")),""),
                "主胜赔":  "—", "客胜赔": "—", "让分": "0", "大小分线": "—",
                "截止时间": "", "期号": "",
            })
        return matches

    def fetch_jisuapi_nba_rank(self):
        """获取NBA东西部排名（极速API /nba/rank）
        截图确认字段: 东部排名/西部排名 → [team, rank, win, loss, winrate, pointsfor, pointsagainst]
        注意：字段是 loss（不是 lose）
        """
        result = self._jisuapi_get(JISUAPI_CONFIG["nba_rank"], {})
        if not result:
            return {}
        ranks = {}
        for conf in ["东部排名", "西部排名"]:
            teams = result.get(conf, [])
            ranks[conf] = [{
                "队伍":     str(t.get("team",    "")),
                "排名":     str(t.get("rank",    "")),
                "胜":       str(t.get("win",     "")),
                "负":       str(t.get("loss",    "")),   # 注意是loss
                "胜率":     f"{t.get('winrate', 0)}%",
                "场均得分": str(t.get("pointsfor",      "")),
                "场均失分": str(t.get("pointsagainst",  "")),
            } for t in teams]
        return ranks


