    def update_lottery_smart(self, game_type: str, silent: bool = False) -> bool:
        """统一更新入口：只使用极速API，不再失败后降级到爬虫/第三方接口。"""
        ok = self.update_lottery_from_jisuapi(game_type, silent=silent)
