        bet_btn.setStyleSheet("background:#27AE60;color:white;font-weight:bold;padding:8px 16px;border-radius:4px;")
        copy_all_btn = QPushButton("📋 复制全部预测")
        copy_all_btn.setStyleSheet("background:#8E44AD;color:white;font-weight:bold;padding:6px;border-radius:4px;")
        close_btn = QPushButton("关闭"); close_btn.clicked.connect(dlg.reject)
        btn_row.addWidget(QLabel("投注方式:")); btn_row.addWidget(bet_type_cb)
        btn_row.addStretch()
        btn_row.addWidget(copy_all_btn); btn_row.addWidget(bet_btn); btn_row.addWidget(close_btn)
        root.addLayout(btn_row)

        # 用极速API本地历史数据生成预测，同时抓取第三方预测网站（只限智能预测页）
        _local_records = list(self.history_data.get(game_type, []))
        class _ScrapeWorker(QThread):
            done = Signal(dict)
            err  = Signal(str)
            def __init__(self, gt, ng, recs):
                super().__init__(); self.gt = gt; self.ng = ng; self.recs = recs
            def run(self):
                try:
                    ref = build_prediction_from_history(self.gt, self.recs, n_preds=self.ng)
                    self.done.emit(ref)
                except Exception as ex:
                    self.err.emit(str(ex))

        _worker_holder = [None]

        def start_fetch():
            ng = n_grp_spin.value()
            if _worker_holder[0] and _worker_holder[0].isRunning():
                _worker_holder[0].quit()
            w = _ScrapeWorker(game_type, ng, _local_records)
            _worker_holder[0] = w
            progress_lbl.show()
            progress_lbl.setText("🔄 正在用本地历史数据训练，并抓取第三方预测网站…")
            w.done.connect(on_done); w.err.connect(on_err)
            w.start()

        def on_done(ref: dict):
            if not ref:
                progress_lbl.setText("❌ 暂无本地历史数据，请先在首页点【🔁 全量更新到最新】"); return
            progress_lbl.hide()
            records      = ref.get("recent_records", [])
            hot_nums     = ref.get("hot_nums", [])
            cold_nums    = ref.get("cold_nums", [])
            hi_omit      = ref.get("high_omission", [])
            advice_nums  = ref.get("advice_nums", [])
            freq_map     = ref.get("freq_map", {})
            omit_map     = ref.get("omission_map", {})
            source       = ref.get("source", "本地/极速API历史")
            multi_preds  = ref.get("multi_predictions", [])
            site_preds   = ref.get("site_predictions", [])
            integrated_nums = ref.get("integrated_nums", advice_nums)
            trend        = ref.get("trend_stats", {})

            # Tab1: 多算法预测
            lines1 = [f"=== {game_type} 多算法预测推荐 ===",
                      f"数据来源: {source}  分析最近 {len(records)} 期\n",
                      "━"*42]
            for idx, pred in enumerate(multi_preds, 1):
                algo = pred.get("algo", f"算法{idx}")
                main = pred.get("main", [])
                sub  = pred.get("sub", [])
                if game_type == "双色球":
                    lines1.append(f"  第{idx:02d}组 [{algo}]")
                    lines1.append(f"    红球: {' '.join(f'{n:02d}' for n in main)}  蓝球: {' '.join(f'{n:02d}' for n in sub)}")
                elif game_type == "大乐透":
                    lines1.append(f"  第{idx:02d}组 [{algo}]")
                    lines1.append(f"    前区: {' '.join(f'{n:02d}' for n in main)}  后区: {' '.join(f'{n:02d}' for n in sub)}")
                else:
                    lines1.append(f"  第{idx:02d}组 [{algo}]: {' '.join(f'{n:02d}' for n in main)}")
                lines1.append("")
            lines1 += ["━"*42,
                       f"★ 综合推荐（模型50%+网站30%+冷热遗漏20%）: {integrated_nums}",
                       f"★ 本地冷热遗漏参考: {advice_nums}",
                       "", "💡 理性购彩，以上仅供参考"]
            pred_te.setPlainText("\n".join(lines1))

            # Tab2: 网站预测
            lines2 = [f"=== {game_type} 网站预测汇总 ===\n"]
            if site_preds:
                for sp in site_preds:
                    src  = sp.get("source", "未知")
                    nums = sp.get("numbers", [])
                    stype = sp.get("type", "pred")
                    tag  = {"pred": "🔮 预测", "hot": "🔥 热号", "cold": "❄ 冷号",
                            "pos_stat": "📊 位置频率", "pos_omit": "⏰ 位置遗漏"}.get(stype, "🔮")
                    w = sp.get("weight", "-")
                    s30 = sp.get("score_30", "-")
                    s50 = sp.get("score_50", "-")
                    s100 = sp.get("score_100", "-")
                    lines2.append(f"  [{src}] {tag}  权重:{w}  近30/50/100评分:{s30}/{s50}/{s100}")
                    # 位置型玩法特殊展示（每位独立显示）
                    if stype in ("pos_stat", "pos_omit"):
                        pos_count = sp.get("pos_count", len(nums))
                        pos_str = "  ".join(f"第{i+1}位:{nums[i]}" for i in range(len(nums)))
                        lines2.append(f"    {pos_str}")
                        lines2.append(f"    组合号码: {''.join(str(n) for n in nums)}\n")
                    else:
                        lines2.append(f"    号码: {' '.join(f'{n:02d}' for n in nums[:25])}\n")
            else:
                lines2 += ["  暂未抓取到网站预测数据（可能受网络限制或网页改版）",
                           "  建议点击「重新训练/抓取」按钮重试",
                           "  主要参考本地历史模型预测结果"]
            site_te.setPlainText("\n".join(lines2))

            # Tab3: 统计分析
            lines3 = [f"=== {game_type} 频次/遗漏/趋势分析 ===",
                      f"数据来源: {source}  分析最近 {len(records)} 期\n",
                      f"🔥 高频热号: {hot_nums}",
                      f"❄  冷号:     {cold_nums}",
                      f"⏰ 高遗漏:   {hi_omit}", ""]
            if trend:
                lines3 += ["📈 近期趋势:",
                           f"  近5期平均和值: {trend.get('avg_sum_5','-')}",
                           f"  近10期平均和值: {trend.get('avg_sum_10','-')}",
                           f"  近5期平均奇数: {trend.get('avg_odd_5','-')}个",
                           f"  近5期平均跨度: {trend.get('span_avg_5','-')}", ""]
            lines3.append("═══ 最近10期开奖号码 ═══")
            for rec in records[:10]:
                lines3.append(f"  {rec.get('期号',''):12s} {rec.get('开奖日期',''):10s}  {rec.get('开奖号码','')}")
            lines3 += ["",
                       f"📊 频次排行（前25）:",
                       "  " + "  ".join(f"[{n}:{freq_map.get(n,0)}次]" for n in sorted(freq_map, key=lambda x: -freq_map[x])[:25]),
                       "",
                       f"⏱ 遗漏排行（前15）:",
                       "  " + "  ".join(f"[{n}:{omit_map.get(n,0)}期]" for n in hi_omit[:15])]
            stat_te.setPlainText("\n".join(lines3))

            # 构建号码选择按钮
            while sel_lay.count():
                item = sel_lay.takeAt(0)
                if item.widget(): item.widget().deleteLater()
            sel_btn_map.clear()
            if game_type == "双色球":
                areas_cfg = [("红球(1-33)", "red", list(range(1,34))), ("蓝球(1-16)", "blue", list(range(1,17)))]
            elif game_type == "大乐透":
                areas_cfg = [("前区(1-35)", "front", list(range(1,36))), ("后区(1-12)", "back", list(range(1,13)))]
            elif game_type == "快乐8":
                areas_cfg = [("号码(1-80)", "main", list(range(1,81)))]
            elif game_type == "七乐彩":
                areas_cfg = [("号码(1-30)", "main", list(range(1,31)))]
            else:
                areas_cfg = [("号码", "main", list(range(1,35)))]
            for al, ak, nr in areas_cfg:
                sel_btn_map[ak] = {}
                grp2 = QGroupBox(al); g2lay = QGridLayout(grp2); g2lay.setSpacing(2)
                cols2 = 10 if len(nr) > 20 else 8
                for idx2, n2 in enumerate(nr):
                    cht = self.get_cold_hot(game_type, n2, ak)
                    bg  = "#E74C3C" if cht=="hot" else ("#3498DB" if cht=="cold" else "#F0F0F0")
                    fg  = "white" if cht != "warm" else "black"
                    b2 = QPushButton(str(n2)); b2.setCheckable(True); b2.setFixedSize(32, 28)
                    b2.setStyleSheet(f"QPushButton{{background:{bg};color:{fg};border-radius:14px;font-size:9px;}}"
                                     f"QPushButton:checked{{background:#F39C12;color:white;border:2px solid #E67E22;}}")
                    if n2 in integrated_nums: b2.setChecked(True)
                    sel_btn_map[ak][n2] = b2
                    g2lay.addWidget(b2, idx2//cols2, idx2%cols2)
                sel_lay.addWidget(grp2)

        def on_err(msg):
            progress_lbl.setText(f"❌ 抓取出错: {msg}")

        def do_bet():
            sel_nums = {ak: sorted([n for n,b in bmap.items() if b.isChecked()]) for ak,bmap in sel_btn_map.items()}
            if not any(sel_nums.values()):
                QMessageBox.warning(dlg, "提示", "请先选择号码"); return
            bets = self.calculate_trend_bets(game_type, {k:len(v) for k,v in sel_nums.items()}, bet_type_cb.currentText(), 1)
            if bets == 0:
                QMessageBox.warning(dlg, "提示", "号码数量不足以组成有效投注"); return
            parts = [f"{k}: {', '.join(map(str,v))}" for k,v in sel_nums.items() if v]
            self.add_betting_record(game_type, f"本地历史推荐{bet_type_cb.currentText()}",
                                    "  ".join(parts), bets, bets*2.0, target_issue=self.get_default_target_issue(game_type))
            QMessageBox.information(dlg, "成功", f"已添加 {bets} 注到投注记录！")

        def do_copy_all():
            txt = pred_te.toPlainText() + "\n\n" + site_te.toPlainText() + "\n\n" + stat_te.toPlainText()
            QApplication.clipboard().setText(txt)
            QMessageBox.information(dlg, "✅", "已复制全部预测内容到剪贴板！")

        refresh_btn.clicked.connect(start_fetch)
        copy_all_btn.clicked.connect(do_copy_all)
        bet_btn.clicked.connect(do_bet)
        start_fetch()
        dlg.exec()
        if _worker_holder[0]: _worker_holder[0].quit(); _worker_holder[0].wait()

