    # 开奖数据爬取（任九/胜负彩/竞彩足球/竞彩篮球）
    # ══════════════════════════════════════════════════════════
    def fetch_sports_lottery_results(self, game_type, silent=False):
        """已禁用非极速API体育/足彩开奖抓取源，避免多源爬虫拖慢程序。"""
        logger.info(f"fetch_sports_lottery_results 已禁用非极速API源：{game_type}")
        ok = self.fetch_sports_lottery_results_jisuapi(game_type, silent=True)
        if not ok and not silent:
            try:
                QTimer.singleShot(0, lambda: QMessageBox.warning(
                    self, "已禁用",
                    f"【{game_type}】非极速API开奖接口/爬虫已禁用。\n当前仅保留极速API更新开奖记录。"))
            except Exception:
                pass
        return bool(ok)

    def _fetch_lottery_gov_cn(self, game_type, game_no):
        """中国体育彩票官网 lottery.gov.cn JSON接口（最新数据源）"""
        import requests
        if not game_no:
            return []
        headers = {
            "User-Agent": "Mozilla/5.0 (Linux; Android 14; Pixel 8) AppleWebKit/537.36 Chrome/124 Mobile Safari/537.36",
            "Accept": "application/json,*/*",
            "Referer": "https://www.sporttery.cn/",
            "Cache-Control": "no-cache",
        }
        # 足彩代码->lottery.gov.cn接口参数
        # cp 参数: jczq竞彩足球, jclq竞彩篮球, rjc任九, sfc胜负彩, jqc进球彩
        cp_map = {"010":"rjc", "006":"sfc", "004":"jqc", "002":"jczq", "003":"jclq"}
        cp = cp_map.get(game_no, "")
        if not cp:
            return []
        urls = [
            f"https://www.lottery.gov.cn/kj/kjlb.html?cp={cp}",
            f"https://static.sporttery.cn/app/lottery/kjcx/{cp}/kjcx.json",
            f"https://webapi.sporttery.cn/gateway/lottery/getHistoryPageListV1.qry?gameNo={game_no}&pageSize=30&pageNo=1",
        ]
        for url in urls:
            try:
                resp = requests.get(url, headers=headers, timeout=15)
                try:
                    data = resp.json()
                except Exception:
                    import json as _jj, re as _rre
                    m = _rre.search(r"(\{.*\}|\[.*\])", resp.text, _rre.DOTALL)
                    if not m: continue
                    data = _jj.loads(m.group(0))
                items = (data.get("value", {}).get("list", []) or
                         data.get("list", []) or data.get("data", []) or
                         (data if isinstance(data, list) else []))
                results = []
                for item in items[:30]:
                    if not isinstance(item, dict): continue
                    issue = str(item.get("lotteryDrawNum", item.get("issue", item.get("期号",""))))
                    date  = str(item.get("lotteryDrawTime", item.get("date", item.get("开奖日期",""))))[:10]
                    nums  = str(item.get("lotteryDrawResult", item.get("result", item.get("开奖号码","")))).replace(",", " ").strip()
                    # 从matchList提取
                    if not nums:
                        match_list = item.get("matchList", item.get("matches", []))
                        if match_list:
                            nums = " ".join(str(m.get("matchResult","?")) for m in match_list if m.get("matchResult") is not None)
                    if issue and nums:
                        results.append({"期号": issue, "开奖日期": date, "开奖号码": nums, "游戏": game_type})
                if results:
                    logger.info(f"_fetch_lottery_gov_cn {game_type}: {len(results)}期 from {url[:60]}")
                    return results
            except Exception as e:
                logger.debug(f"lottery_gov_cn {url[:60]}: {e}")
        return []

    def _fetch_sporttery_webapi(self, game_type, game_no):
        """体育彩票官方webapi获取历史开奖（支持任九/胜负彩/进球彩/竞彩）
        多个URL备用，自动重试。
        """
        import requests
        headers = {
            "User-Agent": "Mozilla/5.0 (Linux; Android 14; Pixel 8) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Mobile Safari/537.36",
            "Accept": "application/json, text/plain, */*",
            "Accept-Language": "zh-CN,zh;q=0.9,en;q=0.8",
            "Referer": "https://www.sporttery.cn/",
            "Origin": "https://www.sporttery.cn",
            "Cache-Control": "no-cache",
        }
        # 多个备用URL
        urls = [
            f"https://webapi.sporttery.cn/gateway/lottery/getHistoryPageListV1.qry?gameNo={game_no}&provinceId=0&pageSize=30&isVerify=1&pageNo=1",
            f"https://webapi.sporttery.cn/gateway/lottery/getHistoryPageListV1.qry?gameNo={game_no}&pageSize=30&pageNo=1",
            f"https://www.sporttery.cn/fc/getFootResult.do?gameNo={game_no}&pSize=30&pNo=1",
        ]
        for url in urls:
            try:
                resp = requests.get(url, headers=headers, timeout=8)
                resp.raise_for_status()
                data = resp.json()
                items = (data.get("value", {}).get("list", []) or
                         data.get("data", {}).get("list", []) or
                         data.get("list", []) or
                         data.get("result", {}).get("list", []) or [])
                if not items and isinstance(data.get("value"), list):
                    items = data["value"]
                results = []
                for item in items[:30]:
                    issue = str(item.get("lotteryDrawNum", item.get("issueNo", item.get("no", ""))))
                    date  = str(item.get("lotteryDrawTime", item.get("drawDate", item.get("date", ""))))[:10]
                    raw   = item.get("lotteryDrawResult", item.get("drawResult", item.get("result", "")))
                    nums  = str(raw).replace(",", " ").strip() if raw else ""
                    # 从matchList中提取结果
                    match_list = item.get("matchList") or item.get("matches") or []
                    if not nums and match_list:
                        nums = " ".join(str(m.get("matchResult","?")) for m in match_list if m.get("matchResult") is not None)
                    teams = "|".join(
                        f'{m.get("homeTeamName","?")}vs{m.get("awayTeamName","?")}'
                        f'[{m.get("matchResult","")},{m.get("homeScore","")}:{m.get("awayScore","")}]'
                        for m in match_list[:14] if m.get("homeTeamName")
                    )
                    odds_info = "|".join(
                        f'{m.get("homeTeamName","")}: 胜{m.get("winOdds","")} 平{m.get("drawOdds","")} 负{m.get("loseOdds","")}'
                        for m in match_list[:14] if m.get("winOdds")
                    )
                    if issue and (nums or teams):
                        results.append({
                            "期号": issue, "开奖日期": date, "游戏": game_type,
                            "开奖号码": nums or " ".join(
                                str(m.get("matchResult","?")) for m in match_list if m.get("matchResult") is not None),
                            "赛事详情": teams,
                            "赔率信息": odds_info,
                        })
                if results:
                    logger.info(f"_fetch_sporttery_webapi {game_type}: {len(results)}期 from {url[:60]}")
                    return results
            except Exception as e:
                logger.debug(f"sporttery_webapi {url[:60]}: {e}")
                continue
        return []

    def _fetch_zhty_json(self, game_type):
        """中国体育彩票网JSON接口（任九/胜负彩/进球彩备用），多源尝试"""
        import requests, re
        # 各源URL列表
        code_map = {"任九": ("R9","010","rjc"), "胜负彩": ("14","006","sfc"), "进球彩": ("JQC","004","jqc")}
        if game_type not in code_map:
            return []
        fc_code, gno, c500 = code_map[game_type]
        headers = {
            "User-Agent": "Mozilla/5.0 (Linux; Android 14) AppleWebKit/537.36 Chrome/124 Mobile Safari/537.36",
            "Referer": "https://www.sporttery.cn/",
            "Accept": "application/json,*/*",
            "Cache-Control": "no-cache",
        }
        urls = [
            f"https://www.sporttery.cn/fc/getFootResult.do?gameNo={fc_code}&pSize=30&pNo=1",
            f"https://webapi.sporttery.cn/gateway/lottery/getHistoryPageListV1.qry?gameNo={gno}&provinceId=0&pageSize=30&isVerify=1&pageNo=1",
            f"https://www.zhcw.com/kjxx/{c500}/json/?pageSize=30&pageNo=1",
        ]
        for url in urls:
            try:
                resp = requests.get(url, headers=headers, timeout=14)
                data = resp.json()
                items = (data.get("value", {}).get("list", []) or
                         data.get("result", {}).get("list", []) or
                         data.get("data", []) or data.get("list", []) or
                         (data.get("value") if isinstance(data.get("value"), list) else []))
                results = []
                for item in items[:30]:
                    issue = str(item.get("lotteryDrawNum", item.get("issueNo", item.get("期号", item.get("no","")))))
                    date  = str(item.get("lotteryDrawTime", item.get("drawDate", item.get("date",""))))[:10]
                    nums  = str(item.get("lotteryDrawResult", item.get("drawResult", item.get("开奖号码", item.get("result",""))))).replace(",", " ").strip()
                    if issue and nums:
                        results.append({"期号": issue, "开奖日期": date, "开奖号码": nums, "游戏": game_type})
                if results:
                    logger.info(f"_fetch_zhty_json {game_type}: {len(results)}期 from {url[:60]}")
                    return results
            except Exception as e:
                logger.debug(f"zhty_json {url[:60]}: {e}")
        return []

    def _fetch_500_json_universal(self, game_type):
        """500彩票JSON API（通用，支持任九/胜负彩/进球彩/竞彩足球/竞彩篮球）"""
        import requests, re
        # 500彩票gameNo映射
        code_map = {
            "任九":    ("010", "rjc"),
            "胜负彩":  ("006", "sfc"),
            "进球彩":  ("004", "jqc"),
            "竞彩足球":("002", "jczq"),
            "竞彩篮球":("003", "jclq"),
        }
        gno, code = code_map.get(game_type, ("", ""))
        if not gno:
            return []
        from datetime import datetime as _dt2
        cur_year = _dt2.now().year
        headers = {
            "User-Agent": "Mozilla/5.0 (Linux; Android 14; K) AppleWebKit/537.36 Chrome/124 Mobile Safari/537.36",
            "Referer": f"https://kaijiang.500.com/{code}.shtml",
            "Accept": "application/json,*/*",
            "Cache-Control": "no-cache",
        }
        urls = [
            f"https://kaijiang.500.com/static/{code}/{cur_year}.json",
            f"https://kaijiang.500.com/static/{code}/{cur_year-1}.json",
            f"https://datachart.500.com/{code}/history/newinc/history.php?limit=30&json=1",
            f"https://datachart.500.com/{code}/history/history.php?limit=30&json=1",
            f"https://www.500.com/cgi-bin/ctzqhm.cgi?type={code}&page=1",
        ]
        for url in urls:
            try:
                resp = requests.get(url, headers=headers, timeout=14)
                try:
                    data = resp.json()
                except Exception:
                    import json as _j2
                    data = _j2.loads(resp.text.lstrip("\ufeff").strip())
                items = (data.get("list", []) or data.get("data", []) or
                         (data if isinstance(data, list) else []))
                results = []
                for item in (items[:30] if isinstance(items, list) else []):
                    if not isinstance(item, dict):
                        continue
                    issue = str(item.get("issue", item.get("期号", item.get("no", item.get("issueNo","")))))
                    date  = str(item.get("date",  item.get("开奖日期", item.get("time", item.get("drawDate","")))))[:10]
                    nums  = str(item.get("result", item.get("开奖号码", item.get("winning", item.get("drawResult","")))))
                    nums  = nums.replace(",", " ").strip()
                    if issue and nums and nums not in ("None","null",""):
                        results.append({"期号": issue, "开奖日期": date, "开奖号码": nums, "游戏": game_type})
                if results:
                    logger.info(f"_fetch_500_json {game_type}: {len(results)}期 from {url[:60]}")
                    return results
            except Exception as e:
                logger.debug(f"500_json {url[:60]}: {e}")
        return []

    def _fetch_500_html_universal(self, game_type, silent=False):
        """500彩票HTML解析（终极备用，支持任九/胜负彩/进球彩/竞彩）"""
        import requests, re
        code_map = {
            "任九":    "rjc",
            "胜负彩":  "sfc",
            "进球彩":  "jqc",
            "竞彩足球":"jczq",
            "竞彩篮球":"jclq",
        }
        code = code_map.get(game_type, "")
        if not code:
            return []
        headers = {
            "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 Chrome/124.0.0.0 Safari/537.36",
            "Referer": f"https://kaijiang.500.com/{code}.shtml",
            "Accept": "text/html,application/xhtml+xml,*/*;q=0.8",
            "Accept-Language": "zh-CN,zh;q=0.9",
        }
        urls = [
            f"https://kaijiang.500.com/{code}.shtml",
            f"https://datachart.500.com/{code}/history/newinc/history.php?limit=30",
            f"https://www.zhcw.com/kjxx/{code}/",
        ]
        for url in urls:
            try:
                resp = requests.get(url, headers=headers, timeout=15)
                resp.encoding = "utf-8"
                text = resp.text
                results = []
                # 正则直接提取期号+开奖结果，不依赖BeautifulSoup
                # 匹配形如: 2026xxx ... 3 1 0 3 0 1 ...
                issue_re = re.compile(r'(\d{5,8})[^\d].*?(\d{4}-\d{2}-\d{2})', re.DOTALL)
                # 先尝试JSON内嵌
                json_match = re.search(r'\"list\"\s*:\s*(\[.*?\])', text, re.DOTALL)
                if json_match:
                    try:
                        import json as _json
                        items = _json.loads(json_match.group(1))
                        for item in items[:30]:
                            if not isinstance(item, dict): continue
                            issue = str(item.get("issue", item.get("期号","")))
                            date  = str(item.get("date", item.get("开奖日期","")))[:10]
                            nums  = str(item.get("result", item.get("开奖号码",""))).replace(",", " ")
                            if issue and nums and nums != "None":
                                results.append({"期号": issue, "开奖日期": date, "开奖号码": nums.strip(), "游戏": game_type})
                        if results:
                            return results
                    except: pass
                # HTML表格行解析（任意格式）
                # 找包含期号的<tr>行
                rows = re.findall(r'<tr[^>]*>(.*?)</tr>', text, re.DOTALL | re.IGNORECASE)
                for row in rows[:200]:
                    cells = re.findall(r'<t[dh][^>]*>(.*?)</t[dh]>', row, re.DOTALL | re.IGNORECASE)
                    texts = [re.sub(r'<[^>]+>', '', c).strip() for c in cells]
                    texts = [t for t in texts if t]
                    if len(texts) < 3:
                        continue
                    # 找期号（5-8位数字）
                    issue = next((t for t in texts if re.match(r'^\d{5,8}$', t)), "")
                    if not issue:
                        continue
                    # 找日期
                    date = next((t for t in texts if re.match(r'\d{4}[-/]\d{2}[-/]\d{2}', t)), "")
                    # 找结果（胜平负编码）
                    result_parts = [t for t in texts if re.match(r'^[0-3胜平负\*]+$', t) and len(t) <= 3]
                    if not result_parts:
                        # 找包含多个胜/平/负/数字的格子
                        for t in texts:
                            if re.match(r'^[\d\s胜平负]+$', t) and len(t.split()) >= 9:
                                result_parts = t.split()
                                break
                    if issue and len(result_parts) >= 9:
                        results.append({
                            "期号": issue, "开奖日期": date,
                            "开奖号码": " ".join(result_parts[:14]),
                            "游戏": game_type
                        })
                    elif issue and result_parts:
                        # 进球彩/竞彩等格式不同
                        results.append({
                            "期号": issue, "开奖日期": date,
                            "开奖号码": " ".join(result_parts),
                            "游戏": game_type
                        })
                if results:
                    # 去重
                    seen = set()
                    uniq = []
                    for r in results:
                        if r["期号"] not in seen:
                            seen.add(r["期号"])
                            uniq.append(r)
                    return uniq[:30]
            except Exception as e:
                logger.warning(f"500_html {url}: {e}")
        """
        """
        if game_type not in self.history_data:
            self.history_data[game_type] = []

        # ── 统一刷新辅助 ──────────────────────────────────────────
        def _do_refresh(records, source_name):
            existing = {str(r.get("期号","")) for r in self.history_data[game_type]}
            added = 0
            for rec in records:
                iss = str(rec.get("期号",""))
                if iss and iss not in existing:
                    self.history_data[game_type].insert(0, rec)
                    existing.add(iss)
                    added += 1
            self.history_data[game_type].sort(key=lambda x: str(x.get("期号","")), reverse=True)
            self._save_all_history()
            # 刷新对应UI表格（主线程安全）
            def _ui_update():
                try:
                    if game_type == "任九" and hasattr(self, "rj_hist_table"):
                        self._refresh_sport_hist_table("任九", self.rj_hist_table)
                    elif game_type == "胜负彩" and hasattr(self, "sfc_hist_table"):
                        self._refresh_sport_hist_table("胜负彩", self.sfc_hist_table)
                    elif game_type == "竞彩足球" and hasattr(self, "cjzq_hist_table"):
                        self._refresh_sport_hist_table("竞彩足球", self.cjzq_hist_table)
                    elif game_type == "竞彩篮球" and hasattr(self, "cjlq_hist_table"):
                        self._refresh_sport_hist_table("竞彩篮球", self.cjlq_hist_table)
                    try: self._refresh_sg_result_table()
                    except: pass
                except Exception as e:
                    logger.debug(f"_ui_update {game_type}: {e}")
            QTimer.singleShot(0, _ui_update)
            if not silent:
                QTimer.singleShot(100, lambda: QMessageBox.information(
                    self, "✅ 更新完成",
                    f"【{game_type}】获取 {len(records)} 期，新增 {added} 期\n数据来源: {source_name}"))
            logger.info(f"fetch_sports_lottery_results {game_type}: {len(records)}期 新增{added} 来源:{source_name}")
            return True

        # ── 1. 体彩官网JSON接口（任九/胜负彩最稳定）────────────────
        if game_type in ("任九", "胜负彩"):
            try:
                records = self._fetch_rjsfc_zhcw_json(game_type)
                if records:
                    return _do_refresh(records, "体彩官网")
            except Exception as e:
                logger.warning(f"体彩官网JSON {game_type}: {e}")

        # ── 2. 竞彩官网JSON接口（竞彩足球/篮球）────────────────────
        if game_type == "竞彩足球":
            try:
                records = self._fetch_jczq_zhcw_json()
                if records:
                    return _do_refresh(records, "竞彩官网")
            except Exception as e:
                logger.warning(f"竞彩官网 竞彩足球: {e}")

        if game_type == "竞彩篮球":
            try:
                records = self._fetch_jclq_zhcw_json()
                if records:
                    return _do_refresh(records, "竞彩篮球官网")
            except Exception as e:
                logger.warning(f"竞彩官网 竞彩篮球: {e}")

        # ── 3. 500彩票 JSON接口 ───────────────────────────────────
        if game_type in ("任九", "胜负彩"):
            try:
                records = self._fetch_rjsfc_500_json(game_type)
                if records:
                    return _do_refresh(records, "500彩票")
            except Exception as e:
                logger.warning(f"500彩票JSON {game_type}: {e}")

        # ── 4. 500彩票 HTML备用 ───────────────────────────────────
        if game_type in ("任九", "胜负彩"):
            try:
                records = self._fetch_rjsfc_500_html(game_type)
                if records:
                    return _do_refresh(records, "500彩票HTML")
            except Exception as e:
                logger.warning(f"500彩票HTML {game_type}: {e}")

        # ── 5. 全部失败 ───────────────────────────────────────────
        if not silent:
            QTimer.singleShot(0, lambda: QMessageBox.warning(
                self, "⚠ 更新失败",
                f"无法获取【{game_type}】开奖数据\n\n"
                f"可能原因：\n"
                f"  1. 网络连接问题\n"
                f"  2. 该期比赛结果尚未公布（次日公布）\n"
                f"  3. 数据源暂时维护\n\n"
                f"建议等次日再试，或手动核对体彩官网结果。"))
        return False

    def _fetch_rjsfc_zhcw_json(self, game_type):
        """从体彩官网JSON接口获取任九/胜负彩开奖历史"""
        import requests, re
        # 体彩官网开奖API
        if game_type == "任九":
            # 任九开奖结果
            urls = [
                "https://www.sporttery.cn/fc/getFootResult.do?gameNo=&pSize=30&pNo=1",
                "https://www.sporttery.cn/fc/staticpage/getFootResultList.do",
            ]
            game_id = "R9"
        else:
            # 胜负彩
            urls = [
                "https://www.sporttery.cn/fc/getFootResult.do?gameNo=&pSize=30&pNo=1",
            ]
            game_id = "14"

        headers = {
            "User-Agent": "Mozilla/5.0 (Linux; Android 13; Pixel 7) AppleWebKit/537.36 Chrome/124 Mobile Safari/537.36",
            "Referer": "https://www.sporttery.cn/",
            "Accept": "application/json,text/html,*/*;q=0.8",
        }
        from datetime import datetime
        results = []
        for url in urls:
            try:
                resp = requests.get(url, headers=headers, timeout=15)
                data = resp.json()
                items = (data.get("value", {}).get("list", []) or
                         data.get("data", {}).get("list", []) or
                         data.get("list", []) or [])
                for item in items[:30]:
                    issue = str(item.get("lotteryDrawNum", item.get("issueNo", item.get("期号", ""))))
                    date  = str(item.get("lotteryDrawTime", item.get("drawDate", item.get("开奖日期", ""))))
                    nums  = str(item.get("lotteryDrawResult", item.get("drawResult", item.get("开奖号码", ""))))
                    if not issue or not nums:
                        continue
                    # 格式化号码（胜3平1负0）
                    nums_clean = re.sub(r"[^0-9\s13胜平负]", " ", nums).strip()
                    results.append({
                        "期号": issue, "开奖日期": date,
                        "开奖号码": nums_clean, "来源": "体彩官网"
                    })
                if results:
                    return results
            except Exception as e:
                logger.debug(f"_fetch_rjsfc_zhcw_json {url}: {e}")
                continue
        return results

    def _fetch_jczq_zhcw_json(self):
        """从竞彩官网获取竞彩足球历史开奖"""
        import requests, re
        headers = {
            "User-Agent": "Mozilla/5.0 (Linux; Android 13) AppleWebKit/537.36 Chrome/124 Mobile Safari/537.36",
            "Referer": "https://www.lottery.gov.cn/",
        }
        urls = [
            "https://www.lottery.gov.cn/kj/kjlb.html?cp=jczq",
            "https://jc.sporttery.cn/football/getMatchResult.do?pSize=20&pNo=1",
        ]
        results = []
        for url in urls:
            try:
                resp = requests.get(url, headers=headers, timeout=15)
                if "json" in resp.headers.get("content-type",""):
                    data = resp.json()
                    items = data.get("value", {}).get("list", []) or data.get("list", []) or []
                    for item in items[:20]:
                        issue = str(item.get("issue", item.get("期号", item.get("lotteryDrawNum",""))))
                        date  = str(item.get("date", item.get("开奖日期","")))
                        nums  = str(item.get("result", item.get("开奖号码","")))
                        if issue and nums:
                            results.append({"期号": issue, "开奖日期": date,
                                            "开奖号码": nums, "来源": "竞彩官网"})
                else:
                    # HTML解析
                    from bs4 import BeautifulSoup
                    soup = BeautifulSoup(resp.text, "html.parser")
                    for row in soup.select("tr"):
                        cols = [td.get_text(strip=True) for td in row.find_all("td")]
                        if len(cols) >= 3:
                            issue = cols[0]; nums = " ".join(cols[1:-1]); date = cols[-1]
                            if re.match(r"\d{5,}", issue):
                                results.append({"期号": issue, "开奖日期": date,
                                                "开奖号码": nums, "来源": "竞彩官网"})
                if results: return results
            except Exception as e:
                logger.debug(f"_fetch_jczq_zhcw_json {url}: {e}")
        return results

