    # ── 任九/胜负彩历史开奖爬取 ──────────────────────────────


    # ══════════════════════════════════════════════════════════
    # 当期赛事获取：拉澳足球(主) → 官方API → 500HTML
    # ══════════════════════════════════════════════════════════

    # ══════════════════════════════════════════════════════════
    # 预测引擎：赔率60% + H2H战绩25% + 历史统计15%
    # ══════════════════════════════════════════════════════════
    def predict_match_result(self, matches, game_type):
        """综合预测每场结果：赔率60% + H2H历史战绩25% + 历史开奖统计15%"""
        def odds_to_prob(s):
            try: v=float(str(s).replace("—","0")); return 1.0/v if v>0 else 0.33
            except: return 0.33
        predictions = []
        for m in matches:
            # 1. 赔率概率（占60%）
            pw=odds_to_prob(m.get("胜赔","2.5"))
            pd=odds_to_prob(m.get("平赔","3.2"))
            pl=odds_to_prob(m.get("负赔","3.0"))
            tot=pw+pd+pl or 1.0
            pw/=tot; pd/=tot; pl/=tot
            # 2. 历史开奖位置统计（占15%）
            hist_vals=[]
            for gt in ("任九","胜负彩","竞彩足球"):
                for rec in self.history_data.get(gt,[])[:50]:
                    parts=rec.get("开奖号码","").split()
                    idx=m.get("序号",1)-1
                    if 0<=idx<len(parts): hist_vals.append(parts[idx])
            hw=(hist_vals.count("3")+hist_vals.count("胜")+1)
            hd=(hist_vals.count("1")+hist_vals.count("平")+1)
            hl=(hist_vals.count("0")+hist_vals.count("负")+1)
            ht=hw+hd+hl; hw/=ht; hd/=ht; hl/=ht
            # 3. H2H历史战绩（占25%）
            h2h_w=hw; h2h_d=hd; h2h_l=hl  # 默认与历史统计相同
            try:
                h2h=self.fetch_team_h2h(m.get("主队",""),m.get("客队",""))
                if h2h and len(h2h)>=2:
                    wins=sum(1 for x in h2h if "胜" in x.get("结果","") or x.get("结果","")=="1")
                    draws=sum(1 for x in h2h if "平" in x.get("结果","") or x.get("结果","")=="X")
                    loses=sum(1 for x in h2h if "负" in x.get("结果","") or x.get("结果","")=="2")
                    h2h_tot=wins+draws+loses or 1
                    h2h_w=wins/h2h_tot; h2h_d=draws/h2h_tot; h2h_l=loses/h2h_tot
            except Exception: pass
            # 综合加权
            fw=pw*0.60+hw*0.15+h2h_w*0.25
            fd=pd*0.60+hd*0.15+h2h_d*0.25
            fl=pl*0.60+hl*0.15+h2h_l*0.25
            best=max(fw,fd,fl)
            probs=sorted([(fw,"3"),(fd,"1"),(fl,"0")],reverse=True)
            recommend=[probs[0][1]] if best>=0.55 else [probs[0][1],probs[1][1]]
            predictions.append({
                "序号":m.get("序号",1),"主队":m.get("主队",""),"客队":m.get("客队",""),
                "联赛":m.get("联赛",""),"让球":m.get("让球",""),
                "胜赔":m.get("胜赔","—"),"平赔":m.get("平赔","—"),"负赔":m.get("负赔","—"),
                "推荐":recommend,
                "胜率":f"{fw*100:.1f}%","平率":f"{fd*100:.1f}%","负率":f"{fl*100:.1f}%",
                "置信":f"{best*100:.1f}%",
            })
        return predictions

    def fetch_todays_matches(self, game_type):
        """只使用极速API获取当期赛事；体彩官网/500/中彩网/赔率爬虫已禁用。"""
        sources = {
            "任九": lambda: self._fetch_rjsfc_jisuapi("任九"),
            "胜负彩": lambda: self._fetch_rjsfc_jisuapi("胜负彩"),
            "进球彩": self._fetch_jqc_jisuapi,
            "竞彩足球": self._fetch_jczq_jisuapi,
            "竞彩篮球": self._fetch_jclq_jisuapi,
        }
        func = sources.get(game_type)
        if not func:
            return []
        try:
            result = func() or []
            logger.info(f"fetch_todays_matches {game_type}: 仅极速API，返回 {len(result)} 场")
            return result
        except Exception as e:
            logger.warning(f"fetch_todays_matches {game_type}: 极速API失败: {e}")
            return []

    def _fetch_rjsfc_jisuapi(self, game_type):
        """极速API获取任九/胜负彩当期赛事（基于足球联赛赛程拼合）"""
        key = getattr(self, "jisuapi_key", "") or getattr(self, "api_key", "")
        if not key:
            return []
        import requests
        base = JISUAPI_CONFIG["base_url"]
        leagues = ["英超", "西甲", "德甲", "意甲", "法甲", "中超", "欧冠", "亚冠"]
        all_matches = []
        from datetime import datetime, timedelta
        today = datetime.now().strftime("%Y-%m-%d")
        tomorrow = (datetime.now() + timedelta(days=1)).strftime("%Y-%m-%d")
        for league in leagues[:5]:  # 取前5个联赛避免请求过多
            try:
                for date in [today, tomorrow]:
                    params = {"appkey": key, "matchname": league, "date": date}
                    resp = requests.get(f"{base}/football/query", params=params, timeout=10)
                    data = resp.json()
                    if data.get("status") != 0:
                        continue
                    items = data.get("result", [])
                    if not isinstance(items, list):
                        items = [items] if isinstance(items, dict) else []
                    for m in items:
                        home = str(m.get("hometeam", m.get("home", "")))
                        away = str(m.get("awayteam", m.get("away", "")))
                        if not home or not away:
                            continue
                        mt = str(m.get("time", m.get("matchtime", today)))
                        all_matches.append({
                            "序号":     str(len(all_matches) + 1),
                            "联赛":     league,
                            "主队":     home,
                            "客队":     away,
                            "胜赔":     str(m.get("win", m.get("odds_win", "—"))),
                            "平赔":     str(m.get("draw", m.get("odds_draw", "—"))),
                            "负赔":     str(m.get("lose", m.get("odds_lose", "—"))),
                            "主支持率": str(m.get("winrate", "—")),
                            "平支持率": str(m.get("drawrate", "—")),
                            "客支持率": str(m.get("loserate", "—")),
                            "比赛时间": mt,
                            "截止时间": mt,
                            "期号":     today.replace("-", ""),
                        })
            except Exception as e:
                logger.debug(f"jisuapi football {league}: {e}")
                continue
        if len(all_matches) >= 9:  # 任九至少需要9场
            return all_matches[:14]  # 胜负彩最多14场
        return []

    def _fetch_rjsfc_zhcw(self, game_type):
        """中彩网获取任九/胜负彩当期赛事"""
        import requests, re
        code = "rjc" if game_type == "任九" else "sfc"
        urls = [
            f"https://www.zhcw.com/kjxx/{code}/",
            f"https://www.lottery.gov.cn/html/lottery/{code}/",
        ]
        headers = {"User-Agent": "Mozilla/5.0 (Linux; Android 13) Chrome/124 Mobile Safari/537.36",
                   "Accept": "text/html,*/*", "Accept-Language": "zh-CN,zh;q=0.9"}
        for url in urls:
            try:
                resp = requests.get(url, headers=headers, timeout=12)
                resp.encoding = "utf-8"
                text = resp.text
                # 尝试提取赛事信息
                matches = []
                # 匹配主队 vs 客队 格式
                rows = re.findall(
                    r'(\d{1,3})\s+([^\|<\n]+?)\s+vs\.?\s+([^\|<\n]+?)\s+(\d+\.\d+)\s+(\d+\.\d+)\s+(\d+\.\d+)',
                    text)
                for row in rows[:14]:
                    seq, home, away, w, d, l = row
                    matches.append({"序号": seq, "联赛": "", "主队": home.strip(),
                                    "客队": away.strip(), "胜赔": w, "平赔": d, "负赔": l,
                                    "主支持率": "—", "平支持率": "—", "客支持率": "—",
                                    "比赛时间": "", "截止时间": "", "期号": ""})
                if matches:
                    return matches
            except Exception as e:
                logger.debug(f"zhcw {url}: {e}")
        return []

    def _fetch_jqc_jisuapi(self):
        """极速API获取进球彩当期赛事（足球比赛进球数预测）"""
        result = self._fetch_rjsfc_jisuapi("进球彩")
        # 进球彩格式：添加进球赔率字段
        for m in result:
            if "进球赔率" not in m:
                m["进球赔率"] = "0球:— 1球:— 2球:— 3球:— 4球:— 5+球:—"
        return result

    def _fetch_jczq_jisuapi(self):
        """极速API获取竞彩足球赛事"""
        matches = self._fetch_rjsfc_jisuapi("竞彩足球")
        for m in matches:
            if "让球" not in m:
                m["让球"] = "0"
            if "进球赔率" not in m:
                m["进球赔率"] = ""
        return matches

    def _fetch_jclq_jisuapi(self):
        """极速API获取竞彩篮球（NBA）"""
        key = getattr(self, "jisuapi_key", "") or getattr(self, "api_key", "")
        if not key:
            return []
        import requests
        from datetime import datetime, timedelta
        base = JISUAPI_CONFIG["base_url"]
        today = datetime.now().strftime("%Y-%m-%d")
        matches = []
        try:
            for date in [today, (datetime.now() + timedelta(days=1)).strftime("%Y-%m-%d")]:
                params = {"appkey": key, "date": date}
                resp = requests.get(f"{base}/nba/query", params=params, timeout=12)
                data = resp.json()
                if data.get("status") != 0:
                    continue
                items = data.get("result", [])
                if not isinstance(items, list):
                    items = []
                for m in items[:15]:
                    home = str(m.get("hometeam", m.get("home", "")))
                    away = str(m.get("awayteam", m.get("away", "")))
                    if not home or not away:
                        continue
                    matches.append({
                        "序号":     str(len(matches) + 1),
                        "联赛":     "NBA",
                        "主队":     home,
                        "客队":     away,
                        "让分":     str(m.get("pointspread", m.get("handicap", "0"))),
                        "主胜赔":   str(m.get("homeodds", m.get("win", "—"))),
                        "客胜赔":   str(m.get("awayodds", m.get("lose", "—"))),
                        "大小分线": str(m.get("totalpoints", m.get("total", "—"))),
                        "比赛时间": str(m.get("time", m.get("gametime", today))),
                        "截止时间": str(m.get("time", today)),
                        "期号":     today.replace("-", ""),
                    })
            if matches:
                return matches
        except Exception as e:
            logger.debug(f"jisuapi nba: {e}")
        return []

    def _fetch_rjsfc_sporttery_api(self, game_type):
        """体育彩票官网API获取任九/胜负彩当期赛事赔率"""
        import requests
        gno = "010" if game_type == "任九" else "006"
        headers = {
            "User-Agent": "Mozilla/5.0 (Linux; Android 13; Pixel 7) AppleWebKit/537.36 Chrome/124 Mobile Safari/537.36",
            "Accept": "application/json, */*",
            "Referer": "https://www.sporttery.cn/",
            "Origin": "https://www.sporttery.cn",
        }
        urls = [
            f"https://webapi.sporttery.cn/gateway/lottery/getMatchListV1.qry?gameNo={gno}&provinceId=0&isVerify=1",
            f"https://www.sporttery.cn/fc/getFootInfo.do?gameNo={gno}&pSize=20",
        ]
        for url in urls:
            try:
                resp = requests.get(url, headers=headers, timeout=15)
                data = resp.json()
                items = (data.get("value", {}).get("matchList", []) or
                         data.get("value", {}).get("list", []) or
                         data.get("matchList", []) or data.get("list", []))
                if not items:
                    continue
                matches = []
                issue_no = data.get("value", {}).get("issueNo", data.get("issueNo", ""))
                deadline = data.get("value", {}).get("deadLine", data.get("deadLine", ""))
                for m in items:
                    home = m.get("homeTeamName", m.get("host", m.get("主队", "")))
                    away = m.get("awayTeamName", m.get("guest", m.get("客队", "")))
                    if not home or not away:
                        continue
                    odds = m.get("oddsValue", {}) or {}
                    win_odds  = odds.get("3", m.get("winOdds", m.get("hostOdds", "—")))
                    draw_odds = odds.get("1", m.get("drawOdds", m.get("drawOdds", "—")))
                    lose_odds = odds.get("0", m.get("loseOdds", m.get("guestOdds", "—")))
                    # 支持率
                    win_pct  = m.get("winRate",  m.get("hostSupportRate", ""))
                    draw_pct = m.get("drawRate", m.get("drawSupportRate", ""))
                    lose_pct = m.get("loseRate", m.get("guestSupportRate", ""))
                    match_time = str(m.get("matchTime", m.get("playTime", m.get("比赛时间", ""))))
                    league = m.get("leagueName", m.get("league", m.get("联赛", "")))
                    seq = m.get("matchNumStr", m.get("matchNo", str(len(matches)+1)))
                    matches.append({
                        "序号":     str(seq),
                        "联赛":     league,
                        "主队":     home,
                        "客队":     away,
                        "胜赔":     str(win_odds),
                        "平赔":     str(draw_odds),
                        "负赔":     str(lose_odds),
                        "主支持率": f"{win_pct}%" if win_pct and "%" not in str(win_pct) else str(win_pct),
                        "平支持率": f"{draw_pct}%" if draw_pct and "%" not in str(draw_pct) else str(draw_pct),
                        "客支持率": f"{lose_pct}%" if lose_pct and "%" not in str(lose_pct) else str(lose_pct),
                        "比赛时间": match_time,
                        "截止时间": str(deadline),
                        "期号":     str(issue_no),
                    })
                if matches:
                    return matches
            except Exception as e:
                logger.debug(f"_fetch_rjsfc_sporttery_api {url}: {e}")
        return []

    def _fetch_rjsfc_500_odds(self, game_type):
        """500彩票赔率JSON接口获取任九/胜负彩赔率"""
        import requests, re
        code = "rjc" if game_type == "任九" else "sfc"
        headers = {
            "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) Chrome/124 Safari/537.36",
            "Referer": f"https://odds.500.com/{code}.shtml",
            "Accept": "application/json,*/*",
        }
        urls = [
            f"https://odds.500.com/fenxi/ouzhi.shtml?id=0&status=ing&type={code}",
            f"https://interface.500.com/cgi-bin/getcallback.cgi?type={code}&page=1",
            f"https://jc.500.com/{code}.shtml",
        ]
        for url in urls:
            try:
                resp = requests.get(url, headers=headers, timeout=12)
                if "json" in resp.headers.get("content-type", ""):
                    data = resp.json()
                    items = data.get("list", data.get("data", data if isinstance(data, list) else []))
                else:
                    # HTML解析：找含赔率的行
                    text = resp.text
                    resp.encoding = "utf-8"
                    # 找JSON嵌入
                    m = re.search(r'var\s+\w+\s*=\s*(\[{.*?}\])', text, re.DOTALL)
                    if m:
                        import json as _j
                        try:
                            items = _j.loads(m.group(1))
                        except:
                            items = []
                    else:
                        items = []
                matches = []
                for item in (items[:20] if isinstance(items, list) else []):
                    if not isinstance(item, dict):
                        continue
                    home = str(item.get("home", item.get("homeTeam", item.get("主队", ""))))
                    away = str(item.get("away", item.get("awayTeam", item.get("客队", ""))))
                    if not home or not away or home == away:
                        continue
                    matches.append({
                        "序号":     str(item.get("id", item.get("no", len(matches)+1))),
                        "联赛":     str(item.get("league", item.get("联赛", ""))),
                        "主队":     home,
                        "客队":     away,
                        "胜赔":     str(item.get("win", item.get("胜赔", "—"))),
                        "平赔":     str(item.get("draw", item.get("平赔", "—"))),
                        "负赔":     str(item.get("lose", item.get("负赔", "—"))),
                        "主支持率": str(item.get("winRate", "—")),
                        "平支持率": str(item.get("drawRate", "—")),
                        "客支持率": str(item.get("loseRate", "—")),
                        "比赛时间": str(item.get("time", item.get("比赛时间", ""))),
                        "截止时间": str(item.get("deadline", "")),
                        "期号":     str(item.get("issue", "")),
                    })
                if matches:
                    return matches
            except Exception as e:
                logger.debug(f"500_odds {url}: {e}")
        return []

