    def _fetch_rjsfc_lazq(self, game_type):
        """从拉澳足球(lazq.com)抓取任九/胜负彩实时赔率（最佳源）"""
        import requests, re
        from bs4 import BeautifulSoup
        headers = {
            "User-Agent": "Mozilla/5.0 (Linux; Android 13; Pixel 7) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Mobile Safari/537.36",
            "Accept": "text/html,application/xhtml+xml,*/*;q=0.8",
            "Accept-Language": "zh-CN,zh;q=0.9",
            "Referer": "https://lazq.com/",
        }
        try:
            resp = requests.get("https://lazq.com/", headers=headers, timeout=15)
            resp.encoding = "utf-8"
            soup = BeautifulSoup(resp.text, "html.parser")
            matches = []
            for row in soup.select("tr, .match-item"):
                cols = row.find_all(["td", "th"])
                texts = [c.get_text(strip=True) for c in cols]
                if len(texts) < 6: continue
                odds = [t for t in texts if re.match(r"^\d+\.\d{2}$", t)]
                if len(odds) < 3: continue
                pcts = [t for t in texts if re.match(r"\d{1,3}\.\d{1,2}%", t)]
                time_s = next((t for t in texts if re.match(r"\d{1,2}:\d{2}", t)), "")
                teams = [t for t in texts if len(t) >= 2 and not re.match(r"^[\d:.%/-]+$", t) and not t.isdigit()]
                if len(teams) < 2: continue
                home, away = teams[0], teams[-1]
                if home == away: continue
                matches.append({
                    "序号": len(matches)+1,
                    "联赛": "",
                    "主队": home, "客队": away,
                    "胜赔": odds[0],
                    "平赔": odds[1] if len(odds)>1 else "—",
                    "负赔": odds[2] if len(odds)>2 else "—",
                    "主支持率": pcts[0] if pcts else "—",
                    "平支持率": pcts[1] if len(pcts)>1 else "—",
                    "客支持率": pcts[2] if len(pcts)>2 else "—",
                    "比赛时间": time_s, "截止时间": "", "期号": "",
                })
                if len(matches) >= 14: break
            return matches
        except Exception as e:
            logger.warning(f"lazq rjsfc {game_type}: {e}"); return []

