    def fetch_team_h2h(self, home, away, league=""):
        """从 odds.500.com 获取同赔率历史对战战绩"""
        import requests, re
        from bs4 import BeautifulSoup
        headers = {
            "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 Chrome/124 Safari/537.36",
            "Referer": "https://odds.500.com/",
        }
        try:
            resp = requests.get("https://odds.500.com/fenxi/ouzhi.shtml", headers=headers, timeout=12)
            resp.encoding = "utf-8"
            soup = BeautifulSoup(resp.text, "html.parser")
            records = []
            for row in soup.select("table tr")[:15]:
                cols = row.find_all(["td","th"])
                texts = [c.get_text(strip=True) for c in cols]
                if len(texts) < 5: continue
                odds_v = [t for t in texts if re.match(r"^\d+\.\d{2}$", t)]
                result = next((t for t in texts if t in ("主胜","平局","客胜","主负")), "")
                if odds_v:
                    records.append({
                        "日期": texts[0] if texts else "",
                        "主队": texts[1] if len(texts)>1 else "",
                        "比分": texts[2] if len(texts)>2 else "",
                        "客队": texts[3] if len(texts)>3 else "",
                        "胜赔": odds_v[0],
                        "结果": result,
                    })
            return records if records else self._local_team_stats(home, away)
        except Exception as e:
            logger.warning(f"h2h 500: {e}")
            return self._local_team_stats(home, away)

    def _local_team_stats(self, home, away):
        """本地历史数据推算胜平负分布（无网络时使用）"""
        all_results = []
        for gt in ("任九","胜负彩","竞彩足球"):
            for rec in self.history_data.get(gt,[])[:50]:
                all_results.extend(rec.get("开奖号码","").split())
        w3=all_results.count("3")+all_results.count("胜")+1
        w1=all_results.count("1")+all_results.count("平")+1
        w0=all_results.count("0")+all_results.count("负")+1
        t=w3+w1+w0
        return [{"日期":"历史统计","主队":home,"比分":"—","客队":away,
                 "结果":f"胜率{w3/t*100:.0f}% 平率{w1/t*100:.0f}% 负率{w0/t*100:.0f}%"}]

