                for c,v in enumerate([f"{i+1:02d}",m.get("联赛",""),home,away,str(m.get("胜赔","—")),str(m.get("平赔","—")),str(m.get("负赔","—"))]): mt.setItem(i,c,QTableWidgetItem(v))
                sw=QWidget(); sl=QHBoxLayout(sw); sl.setContentsMargins(2,2,2,2)
