# ============================================================
# V42 PATCH: 全量更新按钮强制走极速历史接口直连逻辑
# 目的：绕开旧 FullHistoryFetchThread 的旧解析/旧导出逻辑，保留首页更新逻辑不动。
# 注意：本节的“编排器”已删除，仅保留下面被后续版本复用的工具函数。
# ============================================================
def _v42_read_jisu_key():
    import json
    from pathlib import Path
    paths = [API_KEY_FILE, APP_DIR / "api_key.json", Path.cwd() / "api_key.json", CONFIG_FILE]
    for p in paths:
        try:
            if not p or not Path(p).exists():
                continue
            raw = Path(p).read_text(encoding="utf-8").strip()
            if not raw:
                continue
            try:
                data = json.loads(raw)
            except Exception:
                data = raw
            if isinstance(data, dict):
                for k in ("jisuapi_key", "api_key", "appkey", "key", "jisu_key"):
                    v = str(data.get(k, "")).strip()
                    if v:
                        return v
            elif isinstance(data, str) and data.strip():
                return data.strip().strip('"')
        except Exception:
            pass
    return ""


def _v42_norm_record(item):
    number = str(item.get("number", "") or "").strip()
    refer = str(item.get("refernumber", "") or "").strip()
    full = number + (("+" + refer) if refer and refer not in ("None", "null", "0") else "")
    prize = item.get("prize", [])
    levels = _jisu_prize_to_levels(prize)
    return {
        "期号": str(item.get("issueno", "") or ""),
        "开奖日期": str(item.get("opendate", "") or ""),
        "开奖号码": full,
        "参考号码": refer,
        "完整号码": full,
        "销售额": str(item.get("saleamount", "") or ""),
        "奖池": str(item.get("totalmoney", "") or item.get("poolmoney", "") or ""),
        "奖级": levels,
        "来源": "jisuapi_history_v42",
    }


def _v42_record_complete(r):
    """判断一条本地记录是否“开奖号码 + 中奖(奖级)”都已齐全。
    只有齐全的记录才算“已更新过”，全量更新时可以跳过、不再抓取。"""
    if not isinstance(r, dict):
        return False
    has_num = bool(str(r.get("开奖号码", "") or "").strip())
    lv = r.get("奖级", [])
    if isinstance(lv, (list, dict)):
        has_prize = len(lv) > 0
    else:
        has_prize = bool(str(lv or "").strip())
    return has_num and has_prize


def _v42_direct_fetch_history(game, caipiaoid, key, max_pages=9999, existing_rows=None):
    import json, requests, traceback
    out_dir = HISTORY_EXPORT_DIR
    out_dir.mkdir(parents=True, exist_ok=True)
    url = "https://api.jisuapi.com/caipiao/history"
    # 本地已“完整”（号码+中奖都有）的期号集合：全量更新时这些不再重复抓取。
    local_complete = set()
    for r in (existing_rows or []):
        if _v42_record_complete(r):
            iss = str(r.get("期号", "") or "").strip()
            if iss:
                local_complete.add(iss)
    all_items = []
    start = 0
    total = None
    first_debug = {}
    try:
        while True:
            params = {"appkey": key, "caipiaoid": caipiaoid, "issueno": "", "start": start, "num": 20}
            resp = requests.get(url, params=params, timeout=25)
            text = resp.text
            try:
                data = resp.json()
            except Exception:
                data = {}
            result = data.get("result") if isinstance(data, dict) else {}
            if not isinstance(result, dict):
                result = {}
            batch = result.get("list") or []
            if total is None:
                try:
                    total = int(result.get("total") or 0)
                except Exception:
                    total = 0
                first_debug = {
                    "game": game,
                    "url": url,
                    "params": {"appkey": "***", "caipiaoid": caipiaoid, "issueno": "", "start": start, "num": 20},
                    "key_len": len(key or ""),
                    "http_status": getattr(resp, "status_code", None),
                    "status": data.get("status") if isinstance(data, dict) else None,
                    "msg": data.get("msg") if isinstance(data, dict) else None,
                    "result_type": type(result).__name__,
                    "result_total": total,
                    "list_count": len(batch) if isinstance(batch, list) else -1,
                    "local_complete": len(local_complete),
                    "raw_preview": text[:1000],
                }
                (out_dir / f"debug_api_{game}.json").write_text(json.dumps(first_debug, ensure_ascii=False, indent=2), encoding="utf-8")
            if not isinstance(data, dict) or str(data.get("status")) != "0":
                return [], f"status={data.get('status') if isinstance(data, dict) else None}, msg={data.get('msg') if isinstance(data, dict) else '非JSON'}"
            if not isinstance(batch, list) or not batch:
                return all_items, "接口无更多数据" if all_items else "接口无返回数据"
            batch_norm = [_v42_norm_record(x) for x in batch if isinstance(x, dict)]
            all_items.extend(batch_norm)
            start += len(batch)
            # 增量提前结束：极速接口按期号从新到旧返回，若整页都是本地“已完整”的期号，
            # 说明已经追到最新、后面全是旧的已存数据，直接停止，不再翻页抓取。
            if existing_rows is not None and local_complete:
                new_in_batch = sum(
                    1 for r in batch_norm
                    if str(r.get("期号", "") or "").strip() not in local_complete
                )
                if new_in_batch == 0:
                    return all_items, "ok-增量已最新"
            if total and start >= total:
                break
            if len(batch) < 20:
                break
            if start // 20 >= max_pages:
                break
        return all_items, "ok"
    except Exception as e:
        try:
            (out_dir / f"debug_api_{game}.json").write_text(json.dumps({"game":game,"error":str(e),"traceback":traceback.format_exc()}, ensure_ascii=False, indent=2), encoding="utf-8")
        except Exception:
            pass
        return [], str(e)


def _v42_save_all_history(history_map):
    import json
    HISTORY_EXPORT_DIR.mkdir(parents=True, exist_ok=True)
    HISTORY_DATA_FILE.write_text(json.dumps(history_map, ensure_ascii=False, indent=2), encoding="utf-8")
    (HISTORY_EXPORT_DIR / "all_lottery_history.json").write_text(json.dumps(history_map, ensure_ascii=False, indent=2), encoding="utf-8")
    for g, rows in history_map.items():
        (HISTORY_EXPORT_DIR / f"{g}_history.json").write_text(json.dumps(rows, ensure_ascii=False, indent=2), encoding="utf-8")


def _v42_load_existing_history():
    import json
    try:
        if HISTORY_DATA_FILE.exists():
            data = json.loads(HISTORY_DATA_FILE.read_text(encoding="utf-8"))
            if isinstance(data, dict):
                return data
    except Exception:
        pass
    return {}


def _v42_merge_records(old_rows, new_rows):
    old_rows = old_rows if isinstance(old_rows, list) else []
    seen = set()
    merged = []
    for r in list(new_rows or []) + list(old_rows or []):
        if not isinstance(r, dict):
            continue
        key = str(r.get("期号", "")) or (str(r.get("开奖日期", "")) + str(r.get("开奖号码", "")))
        if key in seen:
            continue
        seen.add(key)
        merged.append(r)
    return merged


