# ============================================================
# V76 PATCH — 机器学习回测中心：30/50/100期滚动回测 + 自动权重
# 说明：本补丁只使用本地 history_data，不联网；可在安卓端低成本运行。
# ============================================================
V76_MODEL_WEIGHTS_FILE = APP_DIR / "v76_model_weights.json"
V76_ROLLING_BACKTEST_FILE = APP_DIR / "v76_rolling_backtest.json"


def _v76_issue_key(rec):
    """期号排序辅助：尽量按数字期号排序，失败则按字符串。"""
    s = str((rec or {}).get("期号", ""))
    m = re.findall(r"\d+", s)
    if m:
        try:
            return int("".join(m[-2:]) if len(m) > 1 else m[0])
        except Exception:
            pass
    return s


def _v76_extract_actual(game, rec):
    """把历史开奖记录解析成结构化开奖号。"""
    nums = parse_draw_numbers(str((rec or {}).get("开奖号码", "")))
    nums = [int(x) for x in nums]
    if game == "双色球":
        return {"red": nums[:6], "blue": nums[6] if len(nums) >= 7 else None}
    if game == "大乐透":
        return {"front": nums[:5], "back": nums[5:7] if len(nums) >= 7 else []}
    if game == "快乐8":
        return {"main": nums[:20]}
    if game == "七乐彩":
        return {"main": nums[:7], "special": nums[7] if len(nums) >= 8 else None}
    if game in ("3D", "排列三"):
        # 兼容 040604 这种被拆为 04 06 04 的历史格式：只取每个数字最后一位
        if len(nums) == 3:
            return {"pos": [n % 10 for n in nums]}
        digits = [int(d) for d in re.findall(r"\d", str((rec or {}).get("开奖号码", "")))]
        return {"pos": digits[:3]}
    if game == "排列五":
        if len(nums) == 5:
            return {"pos": [n % 10 for n in nums]}
        digits = [int(d) for d in re.findall(r"\d", str((rec or {}).get("开奖号码", "")))]
        return {"pos": digits[:5]}
    if game == "七星彩":
        # 前6位0-9，第7位0-14；若历史源把第七位14作为整体数字，parse_draw_numbers可保留
        if len(nums) >= 7:
            return {"pos": [int(x) for x in nums[:7]]}
        digits = [int(d) for d in re.findall(r"\d", str((rec or {}).get("开奖号码", "")))]
        return {"pos": digits[:7]}
    return {"main": nums}


def _v76_prediction_score(game, pred, actual):
    """统一评分：返回命中详情和用于模型排名的加权分。"""
    pred = pred or {}; actual = actual or {}
    detail = {"score": 0.0, "main_hit": 0, "sub_hit": 0, "pos_hit": 0, "hit_desc": ""}
    try:
        if game == "双色球":
            rh = len(set(pred.get("red", [])) & set(actual.get("red", [])))
            bh = 1 if pred.get("blue") is not None and pred.get("blue") == actual.get("blue") else 0
            score = rh + bh * 2.0
            detail.update(score=score, main_hit=rh, sub_hit=bh, hit_desc=f"红{rh}+蓝{bh}")
        elif game == "大乐透":
            fh = len(set(pred.get("front", [])) & set(actual.get("front", [])))
            bh = len(set(pred.get("back", [])) & set(actual.get("back", [])))
            score = fh + bh * 1.5
            detail.update(score=score, main_hit=fh, sub_hit=bh, hit_desc=f"前{fh}+后{bh}")
        elif game == "快乐8":
            mh = len(set(pred.get("main", [])) & set(actual.get("main", [])))
            score = mh
            detail.update(score=score, main_hit=mh, hit_desc=f"中{mh}")
        elif game == "七乐彩":
            mh = len(set(pred.get("main", [])) & set(actual.get("main", [])))
            sh = 1 if actual.get("special") in set(pred.get("main", [])) else 0
            score = mh + sh * 1.2
            detail.update(score=score, main_hit=mh, sub_hit=sh, hit_desc=f"基本{mh}+特{sh}")
        elif game in ("3D", "排列三", "排列五", "七星彩"):
            pp = pred.get("pos", []) or []
            aa = actual.get("pos", []) or []
            ph = sum(1 for i in range(min(len(pp), len(aa))) if int(pp[i]) == int(aa[i]))
            score = ph
            detail.update(score=score, pos_hit=ph, hit_desc=f"按位{ph}/{len(aa)}")
        else:
            mh = len(set(pred.get("main", [])) & set(actual.get("main", [])))
            detail.update(score=float(mh), main_hit=mh, hit_desc=f"中{mh}")
    except Exception as e:
        detail["hit_desc"] = f"评分失败:{e}"
    return detail


def _v76_safe_predict_with_training(self, game, model_key, train_chronological):
    """无未来泄漏预测：临时把该玩法历史替换成训练集，再调用现有预测器。"""
    old_hist = self.history_data.get(game, [])
    old_flag = getattr(self, "_backtesting", False)
    try:
        # 程序大多数函数默认 history_data[game] 为新->旧，所以这里反转
        self.history_data[game] = list(reversed(train_chronological))
        self._backtesting = True
        try:
            self.calculate_frequency()
        except Exception:
            pass
        try:
            self.calculate_omission()
        except Exception:
            pass
        return self.predict_for_game(game, str(model_key))
    finally:
        self.history_data[game] = old_hist
        self._backtesting = old_flag


def _v76_rolling_backtest_models(self, game, windows=(30, 50, 100), model_keys=None, min_train=25):
    """最近30/50/100期滚动回测，逐期只用目标期之前的数据训练/预测。"""
    records = list(self.history_data.get(game, []) or [])
    if len(records) < min_train + 5:
        return {"game": game, "error": f"历史数据不足：{len(records)}期，至少需要{min_train+5}期", "windows": {}}
    # 去重并按期号从旧到新排序
    seen = set(); clean = []
    for rec in records:
        issue = str(rec.get("期号", ""))
        if issue and issue in seen:
            continue
        if issue:
            seen.add(issue)
        clean.append(rec)
    chronological = sorted(clean, key=_v76_issue_key)
    if model_keys is None:
        # 优先回测真实ML与集成模型；也保留贝叶斯/冷热类兜底，避免手机端过慢
        preferred = ["1", "6", "12", "13", "15", "20", "21", "22", "23", "26", "27", "28", "29"]
        model_keys = [k for k in preferred if k in PREDICTION_MODELS]
    result = {"game": game, "updated_at": datetime.now().strftime("%Y-%m-%d %H:%M:%S"), "windows": {}}
    max_window = min(max(windows), max(0, len(chronological) - min_train))
    if max_window <= 0:
        return {"game": game, "error": "可回测期数不足", "windows": {}}
    start_index = max(min_train, len(chronological) - max_window)
    # 缓存每个目标期、每个模型预测，避免30/50/100重复计算
    per_period = []
    for i in range(start_index, len(chronological)):
        target = chronological[i]
        actual = _v76_extract_actual(game, target)
        row = {"issue": str(target.get("期号", "")), "actual": actual, "models": {}}
        train = chronological[:i]
        for mk in model_keys:
            try:
                pred = _v76_safe_predict_with_training(self, game, mk, train)
                sc = _v76_prediction_score(game, pred, actual)
                row["models"][str(mk)] = {"prediction": pred, **sc}
            except Exception as e:
                row["models"][str(mk)] = {"error": str(e), "score": 0.0, "hit_desc": "失败"}
        per_period.append(row)
    for w in windows:
        chunk = per_period[-min(w, len(per_period)):]
        model_rows = []
        for mk in model_keys:
            vals = [p["models"].get(str(mk), {}) for p in chunk]
            scores = [float(v.get("score", 0) or 0) for v in vals]
            valid = [v for v in vals if "error" not in v]
            best = max(scores) if scores else 0.0
            avg = sum(scores) / max(1, len(scores))
            # 达标定义：双色球≥3分，大乐透≥3分，快乐8≥4，位置型≥1
            threshold = 4 if game == "快乐8" else (1 if game in ("3D", "排列三", "排列五", "七星彩") else 3)
            hits = sum(1 for s in scores if s >= threshold)
            total = len(scores)
            model_rows.append({
                "model_key": str(mk),
                "name": PREDICTION_MODELS.get(str(mk), {}).get("name", str(mk)),
                "total": total,
                "valid": len(valid),
                "avg_score": round(avg, 4),
                "max_score": round(best, 4),
                "hit_rate": round(hits / total, 4) if total else 0.0,
                "last_hit": vals[-1].get("hit_desc", "") if vals else "",
            })
        model_rows.sort(key=lambda r: (-r["avg_score"], -r["hit_rate"], -r["max_score"]))
        result["windows"][str(w)] = {"periods": len(chunk), "models": model_rows}
    return result


def _v76_compute_model_weights(backtest_result, window="100"):
    """把回测成绩转换为模型权重。"""
    data = ((backtest_result or {}).get("windows", {}) or {}).get(str(window))
    if not data:
        return {}
    rows = data.get("models", []) or []
    raw = {}
    for r in rows:
        # 平均分为主，命中率为辅；加小底分防止全为0
        val = max(0.0001, float(r.get("avg_score", 0) or 0) + float(r.get("hit_rate", 0) or 0) * 1.5)
        raw[str(r.get("model_key"))] = val
    s = sum(raw.values()) or 1.0
    return {k: round(v / s, 4) for k, v in raw.items()}


def _v76_save_backtest_and_weights(self, game, result):
    """保存V76回测结果与权重，同时同步到full_backtest_scores供旧界面使用。"""
    try:
        all_bt = {}
        if V76_ROLLING_BACKTEST_FILE.exists():
            all_bt = json.loads(V76_ROLLING_BACKTEST_FILE.read_text(encoding="utf-8")) or {}
        all_bt[game] = result
        V76_ROLLING_BACKTEST_FILE.write_text(json.dumps(all_bt, ensure_ascii=False, indent=2), encoding="utf-8")
    except Exception as e:
        logger.warning(f"V76保存滚动回测失败: {e}")
    try:
        weights = _v76_compute_model_weights(result, "100") or _v76_compute_model_weights(result, "50") or _v76_compute_model_weights(result, "30")
        all_w = {}
        if V76_MODEL_WEIGHTS_FILE.exists():
            all_w = json.loads(V76_MODEL_WEIGHTS_FILE.read_text(encoding="utf-8")) or {}
        all_w[game] = {"updated_at": datetime.now().strftime("%Y-%m-%d %H:%M:%S"), "weights": weights}
        V76_MODEL_WEIGHTS_FILE.write_text(json.dumps(all_w, ensure_ascii=False, indent=2), encoding="utf-8")
        # 同步旧排行榜数据：hits用hit_rate折算，total用periods
        self.full_backtest_scores.setdefault(game, {})
        w100 = (result.get("windows", {}) or {}).get("100") or (result.get("windows", {}) or {}).get("50") or (result.get("windows", {}) or {}).get("30") or {}
        periods = int(w100.get("periods", 0) or 0)
        for r in w100.get("models", []) or []:
            mk = str(r.get("model_key"))
            self.full_backtest_scores[game][mk] = {
                "total": periods,
                "hits": int(round(float(r.get("hit_rate", 0) or 0) * periods)),
                "avg_score": r.get("avg_score", 0),
                "max_score": r.get("max_score", 0),
                "name": r.get("name", mk),
            }
        try:
            FULL_BACKTEST_FILE.write_text(json.dumps(self.full_backtest_scores, ensure_ascii=False, indent=2), encoding="utf-8")
        except Exception:
            pass
        return weights
    except Exception as e:
        logger.warning(f"V76保存模型权重失败: {e}")
        return {}


def _v76_weighted_fusion_predict(self, game, count=5, window="100"):
    """按V76权重做融合预测；没有权重时自动使用冠军/贝叶斯。"""
    try:
        all_w = json.loads(V76_MODEL_WEIGHTS_FILE.read_text(encoding="utf-8")) if V76_MODEL_WEIGHTS_FILE.exists() else {}
        weights = ((all_w.get(game, {}) or {}).get("weights", {}) or {})
    except Exception:
        weights = {}
    if not weights:
        return self.predict_for_game(game, None)
    # 对每个模型预测结果投票加权
    old_flag = getattr(self, "_backtesting", False)
    self._backtesting = True
    try:
        preds = []
        for mk, wt in sorted(weights.items(), key=lambda x: -float(x[1]))[:8]:
            try:
                preds.append((float(wt), self.predict_for_game(game, mk)))
            except Exception:
                pass
    finally:
        self._backtesting = old_flag
    def top_from(area, need, pool=None):
        c = Counter()
        for wt, p in preds:
            vals = p.get(area, [])
            if isinstance(vals, int): vals = [vals]
            for n in vals:
                c[int(n)] += wt
        if pool is None:
            pool = self._ml_area_pool(game, area)
        ranked = [n for n, _ in c.most_common() if n in set(pool)]
        if len(ranked) < need:
            ranked += [n for n in pool if n not in ranked]
        return sorted(ranked[:need])
    if game == "双色球":
        return {"red": top_from("red", 6), "blue": top_from("blue", 1)[0]}
    if game == "大乐透":
        return {"front": top_from("front", 5), "back": top_from("back", 2)}
    if game == "快乐8":
        return {"main": top_from("main", 10)}
    if game == "七乐彩":
        return {"main": top_from("main", 7)}
    if game in ("3D", "排列三", "排列五", "七星彩"):
        npos = {"3D":3, "排列三":3, "排列五":5, "七星彩":7}.get(game, 3)
        return {"pos": [top_from(f"pos{i}", 1)[0] for i in range(1, npos + 1)]}
    return self.predict_for_game(game, None)


def _v76_format_backtest_report(game, result, weights):
    lines = [f"🏆 {game} V76滚动回测完成", f"时间：{result.get('updated_at','')}"]
    if result.get("error"):
        lines.append(f"❌ {result['error']}")
        return "\n".join(lines)
    for w in ("30", "50", "100"):
        block = (result.get("windows", {}) or {}).get(w)
        if not block:
            continue
        lines.append(f"\n最近{w}期（实际回测{block.get('periods',0)}期）")
        for idx, r in enumerate((block.get("models", []) or [])[:10], 1):
            wt = weights.get(str(r.get("model_key")), 0)
            lines.append(f"{idx}. {r.get('name')}  平均分:{r.get('avg_score')}  命中率:{r.get('hit_rate'):.2%}  最高:{r.get('max_score')}  权重:{wt:.2%}  最新:{r.get('last_hit','')}")
    return "\n".join(lines)


def _v76_open_ml_center(self):
    """首页机器学习中心：运行30/50/100期回测并生成自动权重。"""
    dlg = QDialog(self)
    dlg.setWindowTitle("🤖 V76 机器学习回测中心")
    _responsive_dlg_size(dlg, 920, 860)
    lay = QVBoxLayout(dlg)
    top = QHBoxLayout()
    top.addWidget(QLabel("玩法:"))
    game_combo = QComboBox()
    game_combo.addItems(["双色球", "大乐透", "快乐8", "七乐彩", "3D", "排列三", "排列五", "七星彩"])
    top.addWidget(game_combo)
    run_btn = QPushButton("▶ 运行30/50/100期滚动回测并自动加权")
    run_btn.setStyleSheet("background:#C0392B;color:white;font-weight:bold;padding:8px;")
    top.addWidget(run_btn, 1)
    lay.addLayout(top)
    hint = QLabel("说明：逐期只使用目标期之前的历史训练，避免未来数据泄漏。安卓端建议先单玩法运行。")
    hint.setStyleSheet("color:#666;font-size:12px;")
    hint.setWordWrap(True)
    lay.addWidget(hint)
    out = QTextEdit(); out.setReadOnly(True)
    lay.addWidget(out, 1)
    pred_btn = QPushButton("🎯 用当前权重生成融合预测")
    pred_btn.setStyleSheet("background:#27AE60;color:white;font-weight:bold;padding:8px;")
    lay.addWidget(pred_btn)

    def _run():
        game = game_combo.currentText()
        out.setPlainText(f"⏳ 正在回测 {game}，请稍候……\n首次运行会训练多个模型，手机上可能需要一段时间。")
        QApplication.processEvents()
        try:
            result = _v76_rolling_backtest_models(self, game)
            weights = _v76_save_backtest_and_weights(self, game, result)
            out.setPlainText(_v76_format_backtest_report(game, result, weights))
        except Exception as e:
            out.setPlainText("❌ 回测失败：\n" + traceback.format_exc())

    def _predict():
        game = game_combo.currentText()
        try:
            p = _v76_weighted_fusion_predict(self, game)
            out.append("\n\n🎯 当前自动权重融合预测：")
            out.append(json.dumps(p, ensure_ascii=False, indent=2))
        except Exception:
            out.append("\n❌ 融合预测失败：\n" + traceback.format_exc())
    run_btn.clicked.connect(_run)
    pred_btn.clicked.connect(_predict)
    dlg.exec()


def _v76_install_patch():
    cls = globals().get("LotteryApp")
    if not isinstance(cls, type):
        return
    cls.v76_rolling_backtest_models = _v76_rolling_backtest_models
    cls.v76_weighted_fusion_predict = _v76_weighted_fusion_predict
    cls.open_ml_backtest_center = _v76_open_ml_center
    # 让动态权重优先使用V76权重文件
    old_get_weights = getattr(cls, "get_dynamic_fusion_weights", None)
    def _new_get_dynamic_fusion_weights(self, game):
        try:
            all_w = json.loads(V76_MODEL_WEIGHTS_FILE.read_text(encoding="utf-8")) if V76_MODEL_WEIGHTS_FILE.exists() else {}
            weights = ((all_w.get(game, {}) or {}).get("weights", {}) or {})
            if weights:
                best = max(weights.items(), key=lambda x: float(x[1]))[0]
                return {
                    "machine_learning": 0.50,
                    "deep_learning": 0.20,
                    "expert_sites": 0.20,
                    "cold_hot_omission": 0.10,
                    "leader_model": best,
                    "model_weights": weights,
                }
        except Exception:
            pass
        if callable(old_get_weights):
            return old_get_weights(self, game)
        return {"machine_learning":0.4,"deep_learning":0.2,"expert_sites":0.3,"cold_hot_omission":0.1,"leader_model":"6"}
    cls.get_dynamic_fusion_weights = _new_get_dynamic_fusion_weights
    # 首页增加按钮，不重写原首页，只在原 init_home_tab 完成后追加一个入口
    old_init_home = getattr(cls, "init_home_tab", None)
    if callable(old_init_home) and not getattr(cls, "_v76_home_patched", False):
        def _init_home_with_v76(self, *args, **kwargs):
            old_init_home(self, *args, **kwargs)
            try:
                scroll = self.home_tab.findChild(QScrollArea)
                page = scroll.widget() if scroll else None
                lay = page.layout() if page else None
                if lay is not None:
                    btn = QPushButton("🤖 机器学习中心 / 模型回测加权")
                    btn.setStyleSheet("font-size:13px;padding:8px;background:#2C3E50;color:white;font-weight:bold;border-radius:6px;")
                    btn.clicked.connect(self.open_ml_backtest_center)
                    # 插到首页靠前区域；失败就追加到底部
                    lay.insertWidget(3, btn)
            except Exception as e:
                logger.debug(f"V76首页按钮插入失败: {e}")
        cls.init_home_tab = _init_home_with_v76
        cls._v76_home_patched = True

_v76_install_patch()
# ============================================================
# V76 PATCH END
# ============================================================



# ============================================================
# V77 PATCH — 自动进化预测系统
# 功能：模型淘汰/降权、专家网站排行榜、快乐8专项中心、每日自动训练预测
# 说明：不阻塞主更新；全部使用本地缓存和现有抓取/预测接口，缺库或无网自动降级。
# ============================================================
V77_MODEL_LIFECYCLE_FILE = APP_DIR / "v77_model_lifecycle.json"
V77_EXPERT_RANK_FILE = APP_DIR / "v77_expert_site_rank.json"
V77_DAILY_AUTO_FILE = APP_DIR / "v77_daily_auto_report.json"
V77_KL8_SPECIAL_FILE = APP_DIR / "v77_kl8_special_center.json"
V77_PREDICTION_TRACK_FILE = APP_DIR / "v77_prediction_tracking.json"


def _v77_read_json(path, default=None):
    try:
        p = Path(path)
        if p.exists():
            return json.loads(p.read_text(encoding="utf-8"))
    except Exception:
        pass
    return {} if default is None else default


def _v77_write_json(path, data):
    try:
        Path(path).write_text(json.dumps(data, ensure_ascii=False, indent=2), encoding="utf-8")
        return True
    except Exception as e:
        logger.warning(f"V77写入失败 {path}: {e}")
        return False


def _v77_game_threshold(game):
    # 用V76评分口径转换成状态阈值；不追求绝对中奖，只用于同类模型内淘汰/降权。
    if game == "快乐8":
        return {"excellent": 5.5, "active": 4.0, "weak": 3.2, "pause": 2.4}
    if game in ("3D", "排列三"):
        return {"excellent": 1.8, "active": 1.25, "weak": 0.8, "pause": 0.45}
    if game == "排列五":
        return {"excellent": 2.3, "active": 1.6, "weak": 1.0, "pause": 0.55}
    if game == "七星彩":
        return {"excellent": 2.6, "active": 1.8, "weak": 1.2, "pause": 0.7}
    return {"excellent": 3.6, "active": 2.8, "weak": 2.1, "pause": 1.4}


def _v77_refresh_model_lifecycle(self, game):
    """根据V76最近30/50/100期回测成绩给模型打状态：active/downweighted/paused/eliminated。"""
    all_bt = _v77_read_json(V76_ROLLING_BACKTEST_FILE, {})
    bt = (all_bt.get(game, {}) or {})
    windows = bt.get("windows", {}) or {}
    thresholds = _v77_game_threshold(game)
    rows_by_key = {}
    for w, weight in (("30", 0.50), ("50", 0.30), ("100", 0.20)):
        for r in ((windows.get(w, {}) or {}).get("models", []) or []):
            mk = str(r.get("model_key", ""))
            if not mk:
                continue
            box = rows_by_key.setdefault(mk, {"weighted_score":0.0,"weighted_hit_rate":0.0,"seen":0.0,"name":r.get("name", mk),"last_hit":""})
            box["weighted_score"] += float(r.get("avg_score", 0) or 0) * weight
            box["weighted_hit_rate"] += float(r.get("hit_rate", 0) or 0) * weight
            box["seen"] += weight
            if r.get("last_hit"):
                box["last_hit"] = r.get("last_hit")
    old_all = _v77_read_json(V77_MODEL_LIFECYCLE_FILE, {})
    old_game = old_all.get(game, {}) or {}
    lifecycle = {}
    for mk, box in rows_by_key.items():
        seen = max(0.0001, float(box.get("seen", 0) or 0))
        avg_score = box["weighted_score"] / seen
        hit_rate = box["weighted_hit_rate"] / seen
        prev = old_game.get(mk, {}) or {}
        low_streak = int(prev.get("low_streak", 0) or 0)
        if avg_score >= thresholds["active"]:
            status = "active"
            factor = 1.0
            low_streak = 0
        elif avg_score >= thresholds["weak"]:
            status = "downweighted"
            factor = 0.55
            low_streak += 1
        elif avg_score >= thresholds["pause"]:
            status = "paused"
            factor = 0.20
            low_streak += 1
        else:
            status = "eliminated" if low_streak >= 2 else "paused"
            factor = 0.0 if status == "eliminated" else 0.10
            low_streak += 1
        lifecycle[mk] = {
            "name": box.get("name", mk),
            "status": status,
            "weight_factor": round(factor, 3),
            "avg_score": round(avg_score, 4),
            "hit_rate": round(hit_rate, 4),
            "low_streak": low_streak,
            "last_hit": box.get("last_hit", ""),
            "updated_at": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
        }
    old_all[game] = lifecycle
    _v77_write_json(V77_MODEL_LIFECYCLE_FILE, old_all)
    return lifecycle


def _v77_get_active_model_weights(self, game):
    """V76权重 + V77淘汰/降权后的最终模型权重。"""
    try:
        all_w = _v77_read_json(V76_MODEL_WEIGHTS_FILE, {})
        base = ((all_w.get(game, {}) or {}).get("weights", {}) or {})
    except Exception:
        base = {}
    if not base:
        return {}
    lifecycle_all = _v77_read_json(V77_MODEL_LIFECYCLE_FILE, {})
    lifecycle = (lifecycle_all.get(game, {}) or {})
    if not lifecycle:
        try:
            lifecycle = _v77_refresh_model_lifecycle(self, game)
        except Exception:
            lifecycle = {}
    adjusted = {}
    for mk, wt in base.items():
        factor = float((lifecycle.get(str(mk), {}) or {}).get("weight_factor", 1.0))
        if factor <= 0:
            continue
        adjusted[str(mk)] = max(0.0, float(wt) * factor)
    s = sum(adjusted.values())
    if s <= 0:
        return dict(base)
    return {k: round(v / s, 4) for k, v in adjusted.items()}


def _v77_format_lifecycle_report(game, lifecycle):
    lines = [f"🧬 {game} 模型自动淘汰/降权状态"]
    if not lifecycle:
        return "暂无模型状态，请先运行V76滚动回测。"
    status_name = {"active":"启用", "downweighted":"降权", "paused":"暂停", "eliminated":"淘汰"}
    rows = sorted(lifecycle.items(), key=lambda kv: ({"active":0,"downweighted":1,"paused":2,"eliminated":3}.get(kv[1].get("status"),9), -float(kv[1].get("avg_score",0))))
    for mk, r in rows:
        lines.append(f"{mk}. {r.get('name', mk)} | {status_name.get(r.get('status'), r.get('status'))} | 分数{r.get('avg_score')} | 命中率{round(float(r.get('hit_rate',0))*100,1)}% | 权重系数{r.get('weight_factor')}")
    return "\n".join(lines)


def _v77_score_expert_predictions_against_history(self, game, limit=30):
    """专家网站排行榜：用已抓取/现抓取预测与最近历史做粗评估；无可匹配期号时按号码覆盖度评分。"""
    records = list(self.history_data.get(game, []) or [])[:limit]
    actual_sets = []
    for rec in records:
        a = _v76_extract_actual(game, rec)
        if game == "双色球":
            actual_sets.append(set(a.get("red", [])) | ({a.get("blue")} if a.get("blue") is not None else set()))
        elif game == "大乐透":
            actual_sets.append(set(a.get("front", [])) | set(a.get("back", [])))
        elif game == "快乐8":
            actual_sets.append(set(a.get("main", [])))
        elif game == "七乐彩":
            actual_sets.append(set(a.get("main", [])) | ({a.get("special")} if a.get("special") is not None else set()))
        elif game in ("3D", "排列三", "排列五", "七星彩"):
            actual_sets.append(set(a.get("pos", [])))
    try:
        preds = ScraplingLotteryFetcher.fetch_prediction_sites(game) or []
    except Exception:
        preds = []
    by_source = {}
    for p in preds:
        source = str(p.get("source") or p.get("site") or "未知来源")
        nums = []
        for key in ("numbers", "main", "red", "front", "pos"):
            val = p.get(key)
            if isinstance(val, list):
                nums.extend(int(x) for x in val if str(x).lstrip('-').isdigit())
        for key in ("blue", "back", "sub"):
            val = p.get(key)
            if isinstance(val, list):
                nums.extend(int(x) for x in val if str(x).lstrip('-').isdigit())
            elif isinstance(val, int):
                nums.append(val)
        nums = sorted(set(nums))
        if not nums:
            continue
        scores = [len(set(nums) & aset) for aset in actual_sets] or [0]
        box = by_source.setdefault(source, {"source": source, "count":0, "avg_hit":0.0, "max_hit":0, "last_numbers": []})
        box["count"] += 1
        box["avg_hit"] += sum(scores) / max(1, len(scores))
        box["max_hit"] = max(int(box.get("max_hit", 0)), max(scores) if scores else 0)
        box["last_numbers"] = nums[:30]
    rows = []
    for source, box in by_source.items():
        c = max(1, int(box.get("count", 1)))
        avg = float(box.get("avg_hit", 0.0)) / c
        # source_weight用于融合：专家源表现越好，权重越高；保留底分避免全部0。
        rows.append({
            "source": source,
            "count": c,
            "avg_hit": round(avg, 4),
            "max_hit": int(box.get("max_hit", 0)),
            "source_weight": round(max(0.01, avg + int(box.get("max_hit", 0)) * 0.05), 4),
            "last_numbers": box.get("last_numbers", []),
        })
    rows.sort(key=lambda r: (-r["avg_hit"], -r["max_hit"], r["source"]))
    all_rank = _v77_read_json(V77_EXPERT_RANK_FILE, {})
    all_rank[game] = {"updated_at": datetime.now().strftime("%Y-%m-%d %H:%M:%S"), "limit": limit, "sources": rows}
    _v77_write_json(V77_EXPERT_RANK_FILE, all_rank)
    return rows


def _v77_format_expert_rank(game, rows):
    lines = [f"🌐 {game} 专家网站/预测源排行榜"]
    if not rows:
        lines.append("暂无可评分专家预测源：可能网络不可用，或网站未返回有效预测号码。")
        return "\n".join(lines)
    for i, r in enumerate(rows[:20], 1):
        lines.append(f"{i}. {r.get('source')} | 平均命中{r.get('avg_hit')} | 最高{r.get('max_hit')} | 抓取{r.get('count')}条 | 源权重{r.get('source_weight')}")
    return "\n".join(lines)


def _v77_kl8_special_analysis(self, windows=(30, 50, 100)):
    """快乐8专项中心：分区、重号、遗漏、选一~选十玩法建议。"""
    records = list(self.history_data.get("快乐8", []) or [])
    if not records:
        return {"error":"快乐8无历史数据"}
    chronological = sorted(records, key=_v76_issue_key)
    nums_rows = [_v76_extract_actual("快乐8", r).get("main", []) for r in chronological]
    latest = nums_rows[-1] if nums_rows else []
    flat = [n for row in nums_rows for n in row]
    freq_all = Counter(flat)
    # 当前遗漏
    last_seen = {}
    for idx, row in enumerate(reversed(nums_rows)):
        for n in row:
            if n not in last_seen:
                last_seen[n] = idx
    omission = {n: last_seen.get(n, len(nums_rows)) for n in range(1, 81)}
    report = {"updated_at": datetime.now().strftime("%Y-%m-%d %H:%M:%S"), "windows": {}, "plays": {}}
    for w in windows:
        chunk = nums_rows[-min(w, len(nums_rows)):]
        f = Counter(n for row in chunk for n in row)
        zones = {"1-20":0,"21-40":0,"41-60":0,"61-80":0}
        for row in chunk:
            zones["1-20"] += sum(1 for n in row if 1 <= n <= 20)
            zones["21-40"] += sum(1 for n in row if 21 <= n <= 40)
            zones["41-60"] += sum(1 for n in row if 41 <= n <= 60)
            zones["61-80"] += sum(1 for n in row if 61 <= n <= 80)
        denom = max(1, len(chunk))
        report["windows"][str(w)] = {
            "hot": [n for n, _ in f.most_common(20)],
            "cold": [n for n, _ in sorted(((n, f.get(n, 0)) for n in range(1,81)), key=lambda x:(x[1], x[0]))[:20]],
            "high_omission": [n for n, _ in sorted(omission.items(), key=lambda x:(-x[1], x[0]))[:20]],
            "zone_avg": {k: round(v / denom, 2) for k, v in zones.items()},
            "latest_repeat_avg": round(sum(len(set(row) & set(latest)) for row in chunk) / denom, 2) if latest else 0,
        }
    # 选一~选十给出推荐池：热号40% + 遗漏30% + 分区均衡30%
    base_hot = report["windows"].get("50", report["windows"].get("30", {})).get("hot", [])
    base_omit = report["windows"].get("50", report["windows"].get("30", {})).get("high_omission", [])
    scored = Counter()
    for rank, n in enumerate(base_hot): scored[n] += max(0, 40-rank)
    for rank, n in enumerate(base_omit): scored[n] += max(0, 30-rank) * 0.8
    for n in range(1,81): scored[n] += max(0, 10 - omission.get(n,0) * 0.05)
    ranked = [n for n,_ in scored.most_common()]
    for pick in range(1, 11):
        report["plays"][f"选{pick}"] = sorted(ranked[:pick])
    _v77_write_json(V77_KL8_SPECIAL_FILE, report)
    return report


def _v77_format_kl8_report(report):
    if report.get("error"):
        return "❌ " + report.get("error")
    lines = ["🎯 快乐8专项中心", f"时间：{report.get('updated_at','')}"]
    for w in ("30", "50", "100"):
        b = (report.get("windows", {}) or {}).get(w)
        if not b: continue
        lines.append(f"\n最近{w}期：")
        lines.append("热号：" + " ".join(f"{n:02d}" for n in b.get("hot", [])[:12]))
        lines.append("高遗漏：" + " ".join(f"{n:02d}" for n in b.get("high_omission", [])[:12]))
        lines.append("分区均值：" + " / ".join(f"{k}:{v}" for k,v in (b.get("zone_avg", {}) or {}).items()))
        lines.append(f"上期重号均值：{b.get('latest_repeat_avg')}")
    lines.append("\n选一~选十推荐：")
    for k, nums in (report.get("plays", {}) or {}).items():
        lines.append(f"{k}: " + " ".join(f"{n:02d}" for n in nums))
    return "\n".join(lines)


def _v77_track_prediction(self, game, prediction, source="V77融合预测"):
    all_log = _v77_read_json(V77_PREDICTION_TRACK_FILE, [])
    if not isinstance(all_log, list):
        all_log = []
    all_log.append({
        "time": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
        "game": game,
        "source": source,
        "prediction": prediction,
        "checked": False,
    })
    # 防止文件无限膨胀
    all_log = all_log[-1000:]
    _v77_write_json(V77_PREDICTION_TRACK_FILE, all_log)


def _v77_run_daily_auto_pipeline(self, games=None, light=True):
    """每日自动流程：更新历史->回测/加权->专家评分->快乐8专项->生成融合预测。"""
    if games is None:
        games = ["双色球", "大乐透", "快乐8", "七乐彩", "3D", "排列三", "排列五", "七星彩"]
    report = {"date": datetime.now().strftime("%Y-%m-%d"), "time": datetime.now().strftime("%Y-%m-%d %H:%M:%S"), "games": {}}
    for game in games:
        one = {"status":"ok"}
        try:
            # 不强制联网；已有更新函数时调用，失败忽略，保证主流程不中断。
            if hasattr(self, "update_history_for_game") and callable(getattr(self, "update_history_for_game")):
                try: self.update_history_for_game(game)
                except Exception: pass
            bt = _v76_rolling_backtest_models(self, game, windows=(30, 50, 100), min_train=25)
            weights = _v76_save_backtest_and_weights(self, game, bt)
            lifecycle = _v77_refresh_model_lifecycle(self, game)
            active_weights = _v77_get_active_model_weights(self, game) or weights
            try:
                expert_rows = _v77_score_expert_predictions_against_history(self, game, limit=30)
            except Exception:
                expert_rows = []
            pred = _v77_weighted_fusion_predict(self, game)
            _v77_track_prediction(self, game, pred, "V77每日自动融合")
            one.update({
                "leader_model": max(active_weights.items(), key=lambda x: float(x[1]))[0] if active_weights else "",
                "active_weights": active_weights,
                "model_lifecycle": lifecycle,
                "expert_sources": expert_rows[:10],
                "prediction": pred,
            })
            if game == "快乐8":
                one["kl8_special"] = _v77_kl8_special_analysis(self)
        except Exception as e:
            one = {"status":"error", "error": str(e), "traceback": traceback.format_exc()}
        report["games"][game] = one
    _v77_write_json(V77_DAILY_AUTO_FILE, report)
    return report


def _v77_weighted_fusion_predict(self, game, count=5, window="100"):
    """V77融合：先应用淘汰/降权后的模型权重，再调用V76投票逻辑。"""
    weights = _v77_get_active_model_weights(self, game)
    if not weights:
        return _v76_weighted_fusion_predict(self, game, count=count, window=window)
    # 临时写入V76权重结构，复用V76融合函数，避免大改原逻辑。
    old_all = _v77_read_json(V76_MODEL_WEIGHTS_FILE, {})
    backup = old_all.get(game)
    try:
        old_all[game] = {"updated_at": datetime.now().strftime("%Y-%m-%d %H:%M:%S"), "weights": weights, "v77_adjusted": True}
        _v77_write_json(V76_MODEL_WEIGHTS_FILE, old_all)
        pred = _v76_weighted_fusion_predict(self, game, count=count, window=window)
        try: _v77_track_prediction(self, game, pred, "V77淘汰降权融合")
        except Exception: pass
        return pred
    finally:
        try:
            cur = _v77_read_json(V76_MODEL_WEIGHTS_FILE, {})
            if backup is None:
                cur.pop(game, None)
            else:
                cur[game] = backup
            _v77_write_json(V76_MODEL_WEIGHTS_FILE, cur)
        except Exception:
            pass


def _v77_open_auto_evolution_center(self):
    dlg = QDialog(self)
    dlg.setWindowTitle("🧬 V77 自动进化预测中心")
    _responsive_dlg_size(dlg, 980, 900)
    lay = QVBoxLayout(dlg)
    top = QHBoxLayout()
    top.addWidget(QLabel("玩法:"))
    game_combo = QComboBox()
    game_combo.addItems(["双色球", "大乐透", "快乐8", "七乐彩", "3D", "排列三", "排列五", "七星彩"])
    top.addWidget(game_combo)
    lay.addLayout(top)
    btns = QHBoxLayout()
    run_bt = QPushButton("▶ 回测并刷新模型淘汰/权重")
    expert_bt = QPushButton("🌐 专家网站排行榜")
    kl8_bt = QPushButton("🎯 快乐8专项中心")
    daily_bt = QPushButton("⚙ 每日自动训练预测")
    pred_bt = QPushButton("🎲 当前融合预测")
    for b in (run_bt, expert_bt, kl8_bt, daily_bt, pred_bt):
        b.setStyleSheet("padding:7px;font-weight:bold;")
        btns.addWidget(b)
    lay.addLayout(btns)
    out = QTextEdit(); out.setReadOnly(True)
    lay.addWidget(out, 1)

    def _game(): return game_combo.currentText()
    def _run_models():
        g = _game()
        out.setPlainText(f"⏳ 正在运行 {g} 回测、模型淘汰和自动加权……")
        QApplication.processEvents()
        try:
            bt = _v76_rolling_backtest_models(self, g, windows=(30,50,100), min_train=25)
            weights = _v76_save_backtest_and_weights(self, g, bt)
            lifecycle = _v77_refresh_model_lifecycle(self, g)
            active_weights = _v77_get_active_model_weights(self, g)
            out.setPlainText(_v76_format_backtest_report(g, bt, weights) + "\n\n" + _v77_format_lifecycle_report(g, lifecycle) + "\n\nV77最终权重：\n" + json.dumps(active_weights, ensure_ascii=False, indent=2))
        except Exception:
            out.setPlainText(traceback.format_exc())
    def _expert():
        g = _game()
        out.setPlainText(f"⏳ 正在抓取并评分 {g} 专家预测源……")
        QApplication.processEvents()
        try:
            rows = _v77_score_expert_predictions_against_history(self, g)
            out.setPlainText(_v77_format_expert_rank(g, rows))
        except Exception:
            out.setPlainText(traceback.format_exc())
    def _kl8():
        out.setPlainText("⏳ 正在生成快乐8专项分析……")
        QApplication.processEvents()
        try:
            out.setPlainText(_v77_format_kl8_report(_v77_kl8_special_analysis(self)))
        except Exception:
            out.setPlainText(traceback.format_exc())
    def _daily():
        out.setPlainText("⏳ 正在执行每日自动训练/预测流程……\n安卓端首次运行可能较慢。")
        QApplication.processEvents()
        try:
            g = _game()
            # 为防手机卡顿，按钮默认只跑当前玩法；全玩法可后续在设置中扩展。
            report = _v77_run_daily_auto_pipeline(self, games=[g])
            out.setPlainText("✅ 每日自动流程完成：\n" + json.dumps(report, ensure_ascii=False, indent=2))
        except Exception:
            out.setPlainText(traceback.format_exc())
    def _pred():
        g = _game()
        try:
            p = _v77_weighted_fusion_predict(self, g)
            out.setPlainText(f"🎲 {g} V77融合预测：\n" + json.dumps(p, ensure_ascii=False, indent=2))
        except Exception:
            out.setPlainText(traceback.format_exc())
    run_bt.clicked.connect(_run_models)
    expert_bt.clicked.connect(_expert)
    kl8_bt.clicked.connect(_kl8)
    daily_bt.clicked.connect(_daily)
    pred_bt.clicked.connect(_pred)
    dlg.exec()


def _v77_install_patch():
    cls = globals().get("LotteryApp")
    if not isinstance(cls, type):
        return
    cls.v77_refresh_model_lifecycle = _v77_refresh_model_lifecycle
    cls.v77_get_active_model_weights = _v77_get_active_model_weights
    cls.v77_score_expert_predictions = _v77_score_expert_predictions_against_history
    cls.v77_kl8_special_analysis = _v77_kl8_special_analysis
    cls.v77_run_daily_auto_pipeline = _v77_run_daily_auto_pipeline
    cls.v77_weighted_fusion_predict = _v77_weighted_fusion_predict
    cls.open_auto_evolution_center = _v77_open_auto_evolution_center
    # 覆盖V76融合预测入口为V77降权/淘汰版
    cls.v76_weighted_fusion_predict = _v77_weighted_fusion_predict
    old_get_weights = getattr(cls, "get_dynamic_fusion_weights", None)
    def _v77_get_dynamic_fusion_weights(self, game):
        base = old_get_weights(self, game) if callable(old_get_weights) else {"machine_learning":0.4,"deep_learning":0.2,"expert_sites":0.3,"cold_hot_omission":0.1}
        try:
            active = _v77_get_active_model_weights(self, game)
            if active:
                base["model_weights"] = active
                base["leader_model"] = max(active.items(), key=lambda x: float(x[1]))[0]
                base["machine_learning"] = max(float(base.get("machine_learning",0.4)), 0.50)
        except Exception:
            pass
        return base
    cls.get_dynamic_fusion_weights = _v77_get_dynamic_fusion_weights
    # 首页增加入口
    old_init_home = getattr(cls, "init_home_tab", None)
    if callable(old_init_home) and not getattr(cls, "_v77_home_patched", False):
        def _init_home_with_v77(self, *args, **kwargs):
            old_init_home(self, *args, **kwargs)
            try:
                scroll = self.home_tab.findChild(QScrollArea)
                page = scroll.widget() if scroll else None
                lay = page.layout() if page else None
                if lay is not None:
                    btn = QPushButton("🧬 自动进化预测中心 / 模型淘汰 / 专家排行")
                    btn.setStyleSheet("font-size:13px;padding:8px;background:#6C3483;color:white;font-weight:bold;border-radius:6px;")
                    btn.clicked.connect(self.open_auto_evolution_center)
                    lay.insertWidget(4, btn)
            except Exception as e:
                logger.debug(f"V77首页按钮插入失败: {e}")
        cls.init_home_tab = _init_home_with_v77
        cls._v77_home_patched = True

_v77_install_patch()
# ============================================================
# V77 PATCH END
