        changed = False
        # 已有玩法但weights为空时自动补；完全空文件不强制写全部玩法，避免误导。
        for game, item in list(data.items()):
            if not isinstance(item, dict):
                data[game] = {"updated_at": _v82_now(), "weights": _v83_normalize_weights({}, None), "source": V83_PATCH_VERSION}
