# ============================================================
# V84 PATCH — 已知漏洞和稳定性修复
# 修复点：
# 1) 禁止运行时自动 pip_disabled_install 第三方库，避免安卓端卡死/供应链风险；
# 2) JSON 配置/权重文件改为原子写入，降低异常退出导致文件损坏概率；
# 3) 权重/生命周期/预算文件启动时自动校验与修复；
# 4) API Key 文件尽量设置为仅当前用户可读写；
# 5) 继续保持缺库自动降级，不影响预测和回测入口。
# ============================================================
V84_PATCH_VERSION = "V84_known_bug_vuln_fixed"


def _v84_safe_ensure_scrapling():
    """安全版：只检测 scrapling，不再自动 pip_disabled_install。缺库时走 requests 兜底。"""
    try:
        from scrapling.fetchers import Fetcher  # noqa: F401
        return True
    except Exception:
        logger.info("scrapling 未安装：已禁用运行时自动安装，改用 requests 兜底抓取。")
        return False


def _v84_atomic_write_json(path, data):
    """原子写 JSON，避免写一半导致配置/权重文件损坏。"""
    try:
        p = Path(path)
        p.parent.mkdir(parents=True, exist_ok=True)
        tmp = p.with_name(p.name + ".tmp")
        tmp.write_text(json.dumps(data, ensure_ascii=False, indent=2), encoding="utf-8")
        try:
            os.replace(str(tmp), str(p))
        except Exception:
            p.write_text(json.dumps(data, ensure_ascii=False, indent=2), encoding="utf-8")
            try:
                if tmp.exists():
                    tmp.unlink()
            except Exception:
                pass
        return True
    except Exception as e:
        logger.warning(f"V84原子写JSON失败 {path}: {e}")
        return False


def _v84_read_json(path, default=None):
    try:
        p = Path(path)
        if not p.exists():
            return default
        data = json.loads(p.read_text(encoding="utf-8"))
        return default if data in (None, "") else data
    except Exception as e:
        logger.warning(f"V84读取JSON失败，已使用默认值 {path}: {e}")
        return default


def _v84_repair_weights_file():
    try:
        data = _v84_read_json(V76_MODEL_WEIGHTS_FILE, {})
        if not isinstance(data, dict):
            data = {}
        changed = False
        for game, item in list(data.items()):
            if not isinstance(item, dict):
                data[game] = {"updated_at": _v82_now(), "weights": _v83_normalize_weights({}, None), "source": V84_PATCH_VERSION}
                changed = True
                continue
            weights = item.get("weights")
            if not isinstance(weights, dict) or not weights or sum(float(v or 0) for v in weights.values()) <= 0:
                item["weights"] = _v83_normalize_weights({}, None)
                item["updated_at"] = _v82_now()
                item["source"] = V84_PATCH_VERSION
                changed = True
            else:
                fixed = _v83_normalize_weights(weights, None)
                if fixed != weights:
                    item["weights"] = fixed
                    item["updated_at"] = _v82_now()
                    item["source"] = V84_PATCH_VERSION
                    changed = True
        if changed:
            _v84_atomic_write_json(V76_MODEL_WEIGHTS_FILE, data)
    except Exception:
        logger.debug("V84修复权重文件失败", exc_info=True)


def _v84_harden_api_key_file():
    try:
        p = Path(API_KEY_FILE)
        if p.exists():
            try:
                os.chmod(str(p), 0o600)
            except Exception:
                pass
        p2 = APP_DIR / "api_key.json"
        if p2.exists():
            try:
                os.chmod(str(p2), 0o600)
            except Exception:
                pass
    except Exception:
        pass


def _v84_ensure_runtime_files():
    try:
        _v82_ensure_runtime_files()
        # 复查四个核心运行文件，损坏/缺失时自动修复
        if not isinstance(_v84_read_json(V77_MODEL_LIFECYCLE_FILE, {}), dict):
            _v84_atomic_write_json(V77_MODEL_LIFECYCLE_FILE, _v82_default_lifecycle())
        if not isinstance(_v84_read_json(V78_BUDGET_FILE, {}), dict):
            _v84_atomic_write_json(V78_BUDGET_FILE, _v82_default_budget())
        if not isinstance(_v84_read_json(V76_ROLLING_BACKTEST_FILE, {}), dict):
            _v84_atomic_write_json(V76_ROLLING_BACKTEST_FILE, {})
        if not isinstance(_v84_read_json(V76_MODEL_WEIGHTS_FILE, {}), dict):
            _v84_atomic_write_json(V76_MODEL_WEIGHTS_FILE, {})
        _v84_repair_weights_file()
        _v84_harden_api_key_file()
    except Exception as e:
        logger.warning(f"V84运行文件校验失败: {e}")


def _v84_save_model_weights(self, game, result):
    _v84_ensure_runtime_files()
    safe_result = result if isinstance(result, dict) else {"game": game, "windows": {}, "model_keys": _v81_default_model_keys(), "error": "空回测结果"}
    try:
        all_bt = _v84_read_json(V76_ROLLING_BACKTEST_FILE, {})
        if not isinstance(all_bt, dict):
            all_bt = {}
        all_bt[game] = safe_result
        _v84_atomic_write_json(V76_ROLLING_BACKTEST_FILE, all_bt)
    except Exception:
        logger.warning("V84保存滚动回测失败:\n" + traceback.format_exc())
    weights = _v83_generate_model_weights(safe_result, "100")
    weights = _v83_normalize_weights(weights, safe_result.get("model_keys"))
    try:
        all_w = _v84_read_json(V76_MODEL_WEIGHTS_FILE, {})
        if not isinstance(all_w, dict):
            all_w = {}
        all_w[game] = {"updated_at": _v82_now(), "weights": weights, "source": V84_PATCH_VERSION}
        _v84_atomic_write_json(V76_MODEL_WEIGHTS_FILE, all_w)
    except Exception:
        logger.warning("V84保存模型权重失败:\n" + traceback.format_exc())
    # 继续复用V83逻辑同步生命周期/full_backtest_scores，若失败不影响权重保存
    try:
        lifecycle = _v84_read_json(V77_MODEL_LIFECYCLE_FILE, _v82_default_lifecycle())
        if not isinstance(lifecycle, dict):
            lifecycle = _v82_default_lifecycle()
        lifecycle.setdefault("models", {})
        w100 = ((safe_result.get("windows", {}) or {}).get("100") or
                (safe_result.get("windows", {}) or {}).get("50") or
                (safe_result.get("windows", {}) or {}).get("30") or {})
        for r in w100.get("models", []) or []:
            mk = str(r.get("model_key", ""))
            if not mk:
                continue
            lifecycle["models"].setdefault(mk, {})
            lifecycle["models"][mk].update({
                "name": r.get("name", mk),
                "status": "active" if float(r.get("avg_score", 0) or 0) > 0 else "observe",
                "last_score": r.get("avg_score", 0),
                "last_hit_rate": r.get("hit_rate", 0),
                "updated_at": _v82_now()
            })
        lifecycle["updated_at"] = _v82_now()
        _v84_atomic_write_json(V77_MODEL_LIFECYCLE_FILE, lifecycle)
    except Exception:
        logger.debug("V84同步生命周期失败", exc_info=True)
    return weights


def _v84_run_diagnostic(self):
    _v84_ensure_runtime_files()
    try:
        return _v82_run_diagnostic(self)
    except Exception:
        return "🩺 V84一键诊断失败：\n" + traceback.format_exc()


def _v84_install_patch():
    globals()["_ensure_scrapling"] = _v84_safe_ensure_scrapling
    globals()["_v82_write_json"] = _v84_atomic_write_json
    globals()["_v77_write_json"] = _v84_atomic_write_json
    globals()["_v78_write_json"] = _v84_atomic_write_json
