# ============================================================
# V85 PATCH — Android 已安装 ML 栈优化版
# 依据用户 pip list：scikit-learn / tensorflow / torch 已可用，
# 默认关闭 XGBoost / LightGBM / CatBoost，避免安卓端缺库刷警告。
# 主力模型：RandomForest / ExtraTrees / HistGradientBoosting / LSTM / GRU / Transformer。
# ============================================================
V85_PATCH_VERSION = "V85_android_tf_torch_ml"


def _v85_config_ml_threads():
    """限制 TensorFlow / PyTorch / BLAS 线程，降低安卓端卡死、发热、UI抢占概率。"""
    try:
        os.environ.setdefault("OMP_NUM_THREADS", "1")
        os.environ.setdefault("OPENBLAS_NUM_THREADS", "1")
        os.environ.setdefault("MKL_NUM_THREADS", "1")
        os.environ.setdefault("NUMEXPR_NUM_THREADS", "1")
        os.environ.setdefault("VECLIB_MAXIMUM_THREADS", "1")
        os.environ.setdefault("TF_CPP_MIN_LOG_LEVEL", "2")
    except Exception:
        pass
    try:
        import tensorflow as _tf
        try:
            _tf.config.threading.set_intra_op_parallelism_threads(1)
            _tf.config.threading.set_inter_op_parallelism_threads(1)
        except Exception:
            pass
    except Exception:
        pass
    try:
        import torch as _torch
        try:
            _torch.set_num_threads(1)
            if hasattr(_torch, "set_num_interop_threads"):
                _torch.set_num_interop_threads(1)
        except Exception:
            pass
    except Exception:
        pass


def _v85_default_model_keys():
    """V85默认回测模型：只用当前安卓环境更稳定的已装模型栈。"""
    preferred = ["1", "30", "31", "3", "23", "21", "6", "12", "13", "20"]
    models = globals().get("PREDICTION_MODELS", {}) or {}
    return [k for k in preferred if k in models] or [k for k in ("1", "30", "31", "6") if k in models]


def _v85_default_weights(model_keys=None):
    keys = [str(k) for k in (model_keys or _v85_default_model_keys())]
    base = {
        "1": 0.20,     # RandomForest
        "30": 0.22,    # ExtraTrees
        "31": 0.18,    # HistGradientBoosting
        "3": 0.10,     # LSTM
        "23": 0.10,    # GRU
        "21": 0.08,    # Transformer
        "6": 0.05,     # Bayes
        "12": 0.04,    # Omission
        "13": 0.02,    # Ensemble
        "20": 0.01,    # Champion
    }
    raw = {k: float(base.get(k, 0.03)) for k in keys if k in (globals().get("PREDICTION_MODELS", {}) or {})}
    if not raw:
        raw = {"1": 1.0}
    s = sum(raw.values()) or 1.0
    return {k: round(v / s, 4) for k, v in raw.items()}


# 保存旧入口，V85包装调用，避免改动原始大段逻辑。
try:
    _v85_old_real_ml_predict_area = LotteryApp._real_ml_predict_area
except Exception:
    _v85_old_real_ml_predict_area = None


def _v85_real_ml_predict_area(self, game: str, area: str, count: int, model_key: str) -> list:
    """V85真实ML调度：XGBoost/LightGBM/CatBoost默认映射到安卓稳健模型。"""
    _v85_config_ml_threads()
    mk = str(model_key)
    # 这些库当前安卓环境未安装，默认不直接尝试 import，避免慢和重复警告。
    if mk == "15":      # XGBoost -> ExtraTrees
        mk = "30"
    elif mk == "22":    # LightGBM -> HistGradientBoosting
        mk = "31"
    elif mk == "26":    # CatBoost -> RandomForest
        mk = "1"
    # 深度学习模型继续使用 TensorFlow/Keras，但线程已经被限制。
    if _v85_old_real_ml_predict_area:
        return _v85_old_real_ml_predict_area(self, game, area, count, mk)
    return self.pick_numbers_by_coldhot(game, area, count)


def _v85_rolling_backtest_models(self, game, windows=(30, 50, 100), model_keys=None, min_train=20):
    """V85滚动回测：默认用 Android 可用模型，避免空权重和可选缺库模型干扰。"""
    _v85_config_ml_threads()
    if model_keys is None:
        model_keys = _v85_default_model_keys()
    else:
        # 用户手动传入时也屏蔽缺库可选模型，映射到稳健替代。
        mapped = []
        for k in model_keys:
            sk = str(k)
            if sk == "15": sk = "30"
            elif sk == "22": sk = "31"
            elif sk == "26": sk = "1"
            mapped.append(sk)
        # 去重保持顺序
        seen = set(); model_keys = []
        for k in mapped:
            if k not in seen:
                seen.add(k); model_keys.append(k)
    return _v82_rolling_backtest_models(self, game, windows=windows, model_keys=model_keys, min_train=min_train)


def _v85_generate_model_weights(backtest_result, window="100"):
    weights = _v83_generate_model_weights(backtest_result, window)
    if not isinstance(weights, dict) or not weights:
        weights = _v85_default_weights((backtest_result or {}).get("model_keys"))
    # 删除可选缺库模型权重，映射到稳健模型
    mapped = {}
    for k, v in weights.items():
        kk = str(k)
        if kk == "15": kk = "30"
        elif kk == "22": kk = "31"
        elif kk == "26": kk = "1"
        mapped[kk] = mapped.get(kk, 0.0) + float(v or 0)
    s = sum(mapped.values()) or 1.0
    return {k: round(v / s, 4) for k, v in mapped.items() if v > 0}


def _v85_save_model_weights(self, game, result):
    # 复用V84原子写入，但用V85权重规则修正结果。
    _v84_ensure_runtime_files()
    safe_result = result if isinstance(result, dict) else {"game": game, "windows": {}, "model_keys": _v85_default_model_keys(), "error": "空回测结果"}
    if not safe_result.get("model_keys"):
        safe_result["model_keys"] = _v85_default_model_keys()
    try:
        all_bt = _v84_read_json(V76_ROLLING_BACKTEST_FILE, {})
        if not isinstance(all_bt, dict):
            all_bt = {}
        all_bt[game] = safe_result
        _v84_atomic_write_json(V76_ROLLING_BACKTEST_FILE, all_bt)
    except Exception:
        logger.warning("V85保存滚动回测失败:\n" + traceback.format_exc())
    weights = _v85_generate_model_weights(safe_result, "100") or _v85_default_weights(safe_result.get("model_keys"))
    try:
        all_w = _v84_read_json(V76_MODEL_WEIGHTS_FILE, {})
        if not isinstance(all_w, dict):
            all_w = {}
        all_w[game] = {"updated_at": _v82_now(), "weights": weights, "source": V85_PATCH_VERSION}
        _v84_atomic_write_json(V76_MODEL_WEIGHTS_FILE, all_w)
    except Exception:
        logger.warning("V85保存模型权重失败:\n" + traceback.format_exc())
    return weights


def _v85_open_ml_center(self):
    dlg = QDialog(self)
    dlg.setWindowTitle("🤖 V85 安卓深度学习回测中心")
    _responsive_dlg_size(dlg, 920, 860)
    lay = QVBoxLayout(dlg)
    top = QHBoxLayout()
    top.addWidget(QLabel("玩法:"))
    game_combo = QComboBox(); game_combo.addItems(["双色球", "大乐透", "快乐8", "七乐彩", "3D", "排列三", "排列五", "七星彩"])
    top.addWidget(game_combo)
    run_btn = QPushButton("▶ 运行30/50/100期滚动回测并自动加权")
    run_btn.setStyleSheet("background:#8E44AD;color:white;font-weight:bold;padding:8px;")
    top.addWidget(run_btn, 1)
    lay.addLayout(top)
    hint = QLabel("V85：根据当前 pip list，默认使用 RandomForest / ExtraTrees / HistGB / LSTM / GRU / Transformer；XGBoost、LightGBM、CatBoost 默认关闭并自动映射到稳健替代模型。")
    hint.setWordWrap(True); hint.setStyleSheet("color:#555;font-size:12px;")
    lay.addWidget(hint)
    out = QTextEdit(); out.setReadOnly(True); lay.addWidget(out, 1)
    pred_btn = QPushButton("🎯 用V85当前权重生成融合预测")
    pred_btn.setStyleSheet("background:#27AE60;color:white;font-weight:bold;padding:8px;")
    lay.addWidget(pred_btn)
    def _run():
        game = game_combo.currentText()
        out.setPlainText(f"⏳ 正在运行 V85 回测：{game}\n默认模型：" + ",".join(_v85_default_model_keys()))
        QApplication.processEvents()
        try:
            result = _v85_rolling_backtest_models(self, game)
            weights = _v85_save_model_weights(self, game, result)
            report = _v76_format_backtest_report(game, result, weights)
            report += "\n\n✅ V85权重：" + json.dumps(weights, ensure_ascii=False)
            out.setPlainText(report)
        except Exception:
            out.setPlainText("❌ V85回测失败：\n" + traceback.format_exc())
    def _predict():
        game = game_combo.currentText()
        try:
            p = _v76_weighted_fusion_predict(self, game)
            out.append("\n\n🎯 V85自动权重融合预测：")
            out.append(json.dumps(p, ensure_ascii=False, indent=2))
        except Exception:
            out.append("\n❌ 融合预测失败：\n" + traceback.format_exc())
    run_btn.clicked.connect(_run)
    pred_btn.clicked.connect(_predict)
    dlg.exec()


def _v85_config_env_only():
    """只设置环境变量，不在启动阶段导入 TensorFlow / Torch，避免安卓启动变慢。"""
