# ============================================================
# V86 PATCH — V85 bugcheck: 回测线程化 + 启动轻量化
# 1) 机器学习回测不再阻塞主界面。
# 2) TensorFlow / Torch 不在启动时强行导入，只在实际训练/回测时导入。
# 3) 回测失败会给出 traceback，不让界面空白。
# ============================================================
V86_PATCH_VERSION = "V86_v85_bugcheck_thread_fix"

class _V86BacktestThread(QThread):
    finished = Signal(str, object, object, str)

    def __init__(self, app_obj, game):
        super().__init__(app_obj)
        self.app_obj = app_obj
        self.game = game

    def run(self):
        try:
            result = _v85_rolling_backtest_models(self.app_obj, self.game)
            weights = _v85_save_model_weights(self.app_obj, self.game, result)
            report = _v76_format_backtest_report(self.game, result, weights)
            report += "\n\n✅ V86权重：" + json.dumps(weights, ensure_ascii=False)
            self.finished.emit(report, result, weights, "")
        except Exception:
            self.finished.emit("", {}, {}, traceback.format_exc())


def _v86_open_ml_center(self):
    dlg = QDialog(self)
    dlg.setWindowTitle("🤖 V86 安卓机器学习回测中心")
    _responsive_dlg_size(dlg, 920, 860)
    lay = QVBoxLayout(dlg)

    top = QHBoxLayout()
    top.addWidget(QLabel("玩法:"))
    game_combo = QComboBox()
    game_combo.addItems(["双色球", "大乐透", "快乐8", "七乐彩", "3D", "排列三", "排列五", "七星彩"])
    top.addWidget(game_combo)
    run_btn = QPushButton("▶ 运行30/50/100期滚动回测并自动加权")
    run_btn.setStyleSheet("background:#8E44AD;color:white;font-weight:bold;padding:8px;")
    top.addWidget(run_btn, 1)
    lay.addLayout(top)

    hint = QLabel("V86：回测已改为QThread后台线程，不阻塞界面；默认使用 RandomForest / ExtraTrees / HistGB / LSTM / GRU / Transformer；XGBoost、LightGBM、CatBoost默认关闭。")
    hint.setWordWrap(True)
    hint.setStyleSheet("color:#555;font-size:12px;")
    lay.addWidget(hint)

    out = QTextEdit()
    out.setReadOnly(True)
    lay.addWidget(out, 1)

    pred_btn = QPushButton("🎯 用当前权重生成融合预测")
    pred_btn.setStyleSheet("background:#27AE60;color:white;font-weight:bold;padding:8px;")
    lay.addWidget(pred_btn)

    def _run():
        game = game_combo.currentText()
        run_btn.setEnabled(False)
        pred_btn.setEnabled(False)
        out.setPlainText(f"⏳ 正在后台运行 V86 回测：{game}\n默认模型：" + ",".join(_v85_default_model_keys()) + "\n请等待结果输出，不要重复点击。")
        worker = _V86BacktestThread(self, game)
        dlg._v86_worker = worker

        def _done(report, result, weights, err):
            run_btn.setEnabled(True)
            pred_btn.setEnabled(True)
            if err:
                out.setPlainText("❌ V86回测失败：\n" + err)
            else:
                out.setPlainText(report)
            try:
                worker.deleteLater()
            except Exception:
                pass

        worker.finished.connect(_done)
        worker.start()

    def _predict():
        game = game_combo.currentText()
        try:
            p = _v76_weighted_fusion_predict(self, game)
            out.append("\n\n🎯 当前权重融合预测：")
            out.append(json.dumps(p, ensure_ascii=False, indent=2))
        except Exception:
            out.append("\n❌ 融合预测失败：\n" + traceback.format_exc())

    run_btn.clicked.connect(_run)
    pred_btn.clicked.connect(_predict)
    dlg.exec()


def _v86_install_patch():
    cls = globals().get("LotteryApp")
    if isinstance(cls, type):
        cls.open_ml_backtest_center = _v86_open_ml_center
        cls.open_ml_center = _v86_open_ml_center
    logger.info("V86补丁已安装：机器学习回测线程化，启动阶段不导入深度学习库")

_v86_install_patch()
