# ============================================================
# V87 PATCH — 修复“全量更新所有玩法所有历史”无进度/无完成回调
# 问题原因：旧 V42 补丁覆盖 FullHistoryFetchThread.run 后没有发射 all_finished，
# update_all_history_full 只监听 all_finished，导致数据可能抓了但界面看不到完成/刷新。
# ============================================================
def _v87_full_history_thread_run(self):
    try:
        key = _v42_read_jisu_key()
        if not key:
            try:
                self.error.emit("未读取到极速API密钥，请先保存 api_key.json")
            except Exception:
                pass
            return

        id_map = dict(JISUAPI_CONFIG.get("lottery_id_map", {}))
        unsupported = set(JISUAPI_CONFIG.get("football_lottery_types", []))
        games = list(getattr(self, "games", []) or [g for g in id_map.keys() if g not in unsupported])
        games = [g for g in games if g in id_map and g not in unsupported]
        if not games:
            games = ["双色球", "3D", "七乐彩", "快乐8", "大乐透", "七星彩", "排列三", "排列五", "福建36选7", "福建31选7", "福建22选5"]
        total = len(games)

        old = _v42_load_existing_history()
        if not isinstance(old, dict):
            old = {}
        total_new = 0
        report = []

        for idx, game in enumerate(games):
            if getattr(self, "_cancel", False):
                report.append("用户取消全量更新")
                break
            cid = id_map.get(game)
            if not cid:
                report.append(f"{game}: ❌ 缺少极速API玩法ID")
                continue
            try:
                self.progress.emit(idx, total, f"[{idx+1}/{total}] 正在全量抓取 {game} 所有历史…")
            except Exception:
                pass

            rows, msg = _v42_direct_fetch_history(game, cid, key)
            if rows:
                before = len(old.get(game, []) if isinstance(old.get(game, []), list) else [])
                old[game] = _v42_merge_records(old.get(game, []), rows)
                after = len(old.get(game, []))
                added = max(0, after - before)
                total_new += added
                try:
                    if hasattr(self, "app"):
                        self.app.history_data = old
                except Exception:
                    pass
                try:
                    self.game_done.emit(game, len(rows), added, after)
                except Exception:
                    pass
                report.append(f"{game}: ✅ 抓取{len(rows)}期，新增{added}期，本地共{after}期")
            else:
                report.append(f"{game}: ❌ {msg}")

        _v42_save_all_history(old)
        try:
            if hasattr(self, "app"):
                self.app.history_data = old
        except Exception:
            pass
        try:
            self.progress.emit(total, total, "全量历史更新完成，正在刷新界面…")
        except Exception:
            pass
        self.all_finished.emit(total_new, report)
    except Exception as e:
        logger.error(f"V87全量历史线程异常: {e}", exc_info=True)
        try:
            self.error.emit(str(e))
        except Exception:
            pass

try:
    if "FullHistoryFetchThread" in globals():
        FullHistoryFetchThread.run = _v87_full_history_thread_run
except Exception as _e:
    try:
        logger.warning(f"V87全量更新补丁安装失败: {_e}")
    except Exception:
        pass

# 确保 update_all_history_full 仍然走带进度条的 QThread，但完成后一定刷新本地缓存/首页。
def _v87_update_all_history_full(self, max_per_game: int = 200000):
    # V88: QProgressDialog was missing from the global QtWidgets import in some builds.
    # Keep a local import so the full-history button never fails with NameError.
    try:
        from PySide6.QtWidgets import QProgressDialog as _QProgressDialog
    except Exception:
        _QProgressDialog = None
    if (not isinstance(max_per_game, int)) or isinstance(max_per_game, bool) or max_per_game <= 0:
        max_per_game = 200000
    key = getattr(self, "jisuapi_key", "") or getattr(self, "api_key", "") or _v42_read_jisu_key()
    if not key:
        QMessageBox.warning(self, "缺少密钥", "没有读取到极速API密钥，请先在设置里保存API Key。")
        return
    try:
        self.jisuapi_key = key
        self.api_key = key
    except Exception:
        pass

    if getattr(self, "_full_fetch_thread", None) and self._full_fetch_thread.isRunning():
        QMessageBox.information(self, "提示", "全量更新正在进行中，请稍候…")
        return

    unsupported = set(JISUAPI_CONFIG.get("football_lottery_types", []))
    games = [g for g in JISUAPI_CONFIG.get("lottery_id_map", {}).keys() if g not in unsupported]
    if _QProgressDialog is None:
        QMessageBox.warning(self, "缺少组件", "QProgressDialog 加载失败，无法显示全量更新进度。")
        return
    progress = __Stage14SafeProgressDialog("准备全量更新所有玩法历史开奖…", "取消", 0, len(games), self)
    progress.setWindowTitle("🔄 全量更新所有玩法全部历史")
    progress.setWindowModality(Qt.WindowModal)
    progress.setMinimumDuration(0)
    progress.setAutoClose(False)
    progress.setAutoReset(False)
    progress.setValue(0)

    thread = FullHistoryFetchThread(self, games, max_per_game=max_per_game, page_size=100)
    self._full_fetch_thread = thread

    def _on_progress(idx, total, text):
        try:
            if idx >= 0:
                progress.setValue(min(idx, total))
            progress.setLabelText(text)
        except Exception:
            pass

    def _on_all_finished(total_added, report):
        try:
            progress.setValue(len(games))
            progress.close()
        except Exception:
            pass
        try:
            self.load_history_data()
        except Exception:
            pass
        try:
            self.update_home_results()
        except Exception:
            pass
        try:
            self.update_latest_results_display()
        except Exception:
            pass
        try:
            self.calculate_omission()
        except Exception:
            pass
        QMessageBox.information(
            self,
            "✅ 全量更新完成",
            "所有玩法历史已尽可能从极速API抓取并保存。\n"
            f"本次共新增 {total_added} 期。\n\n" + "\n".join(report)
        )

    def _on_error(msg):
        try:
            progress.close()
        except Exception:
            pass
        QMessageBox.warning(self, "全量更新出错", f"发生错误：\n{msg}")

    progress.canceled.connect(thread.cancel)
    thread.progress.connect(_on_progress)
    thread.all_finished.connect(_on_all_finished)
    thread.error.connect(_on_error)
    thread.start()

try:
    if "LotteryApp" in globals():
        LotteryApp.update_all_history_full = _v87_update_all_history_full
        LotteryApp.full_update_to_latest = _v87_update_all_history_full
        LotteryApp.update_all_to_latest = _v87_update_all_history_full
        LotteryApp.fetch_full_history = _v87_update_all_history_full
except Exception as _e:
    try:
        logger.warning(f"V87主窗口全量更新入口修补失败: {_e}")
    except Exception:
        pass
