def _v93_open_external_url(url: str):
    """跨端打开外部链接；失败时返回 False。"""
    try:
        from PySide6.QtGui import QDesktopServices as _QDesktopServices
        from PySide6.QtCore import QUrl as _QUrl
        return bool(_QDesktopServices.openUrl(_QUrl(url)))
    except Exception:
        try:
            import webbrowser as _webbrowser
            return bool(_webbrowser.open(url))
        except Exception:
            return False


