def _v90_local_cfg(game):
    return {
        "福建36选7": {"max": 36, "need": 7, "area": "main"},
        "福建31选7": {"max": 31, "need": 7, "area": "main"},
        "福建22选5": {"max": 22, "need": 5, "area": "main"},
    }.get(game)


def _v90_resolve_lottery_id(game, key=""):
    """地方彩ID动态识别。优先使用配置；配置为None时请求 /caipiao/class 并按名称匹配。"""
    try:
        cid = JISUAPI_CONFIG.get("lottery_id_map", {}).get(game)
        if cid not in (None, "", 0, "0"):
            return int(cid)
    except Exception:
        pass
    if not key:
        try:
            key = _v42_read_jisu_key()
        except Exception:
            key = ""
    if not key:
        return None
    try:
        data, raw, err, final_url = _v89_request_json_with_retry(
            "https://api.jisuapi.com/caipiao/class",
            {"appkey": key}, retries=2, timeout=20
        )
        if err or not isinstance(data, dict) or str(data.get("status")) != "0":
            return None
        result = data.get("result")
        # result 可能是 list，也可能是嵌套分类列表。
        flat = []
        def walk(x):
            if isinstance(x, dict):
                flat.append(x)
                for v in x.values():
                    if isinstance(v, (list, dict)):
                        walk(v)
            elif isinstance(x, list):
                for it in x:
                    walk(it)
        walk(result)
        aliases = {
            "福建36选7": ["福建36选7", "36选7", "福建体彩36选7"],
            "福建31选7": ["福建31选7", "31选6", "福建31选7", "31选7"],
            "福建22选5": ["福建22选5", "22选5"],
        }.get(game, [game])
        for item in flat:
            name = str(item.get("name") or item.get("lotteryname") or item.get("title") or "")
            cid = item.get("caipiaoid") or item.get("id") or item.get("lotteryid")
            if cid and any(a in name for a in aliases):
                try:
                    cid = int(cid)
                    JISUAPI_CONFIG.setdefault("lottery_id_map", {})[game] = cid
                    logger.info(f"V90动态识别{game} caipiaoid={cid} name={name}")
                    return cid
                except Exception:
                    pass
    except Exception:
        logger.warning(f"V90动态识别{game} ID失败:\n" + traceback.format_exc())
    return None


def _v90_random_pick(self, game_type, area, total_count):
    cfg = _v90_local_cfg(game_type)
    if cfg and area in ("main", "red", "front"):
        total_count = min(int(total_count), cfg["max"])
        return sorted(random.sample(range(1, cfg["max"] + 1), total_count))
    return _v90_old_random_pick(self, game_type, area, total_count)


def _v90_pick_one_ticket(self, game_type, kl8_n=10):
    cfg = _v90_local_cfg(game_type)
    if cfg:
        nums = self.pick_numbers_by_coldhot(game_type, "main", cfg["need"])
        return "号码: " + ", ".join(f"{int(n):02d}" for n in sorted(nums))
    return _v90_old_pick_one_ticket(self, game_type, kl8_n=kl8_n)


def _v90_self_select(self, game_type):
    if game_type in V90_LOCAL_GAMES:
        QMessageBox.information(self, "福建地方彩", f"{game_type}已接入机选、复式、胆拖、历史更新和复制识别。自选选号面板将在后续版本做专用球盘；当前可先使用机选/复式/胆拖。")
        return
    return _v90_old_self_select(self, game_type)


