def _v91_flatten_json_items(obj):
    """兼容汇鸟接口各种返回结构，尽量找到开奖列表。"""
    if isinstance(obj, list):
        return obj
    if not isinstance(obj, dict):
        return []
    # 常见结构：data.list / data.data / data.rows / result.list / result.data
    candidates = []
    for k in ("data", "result", "rows", "list"):
        v = obj.get(k)
        if isinstance(v, list):
            candidates.append(v)
        elif isinstance(v, dict):
            for kk in ("data", "list", "rows", "records", "items"):
                vv = v.get(kk)
                if isinstance(vv, list):
                    candidates.append(vv)
    if candidates:
        # 取最长的列表，通常就是开奖历史列表
        return max(candidates, key=len)
    return []


def _v91_find_first(item, keys, default=""):
    if not isinstance(item, dict):
        return default
    for k in keys:
        if k in item and item.get(k) not in (None, "", [], {}):
            return item.get(k)
    return default


def _v91_normalize_fujian_record(game, item):
    """汇鸟福建地方彩记录标准化到程序统一历史格式。"""
    import re as _re
    if not isinstance(item, dict):
        item = {}
    issue = str(_v91_find_first(item, [
        "expect", "issue", "issueno", "period", "lottery_no", "lotteryNo", "number_no", "drawNo", "code"
    ], "") or "").strip()
    date = str(_v91_find_first(item, [
        "opentime", "openTime", "open_date", "openDate", "date", "time", "draw_time", "drawTime"
    ], "") or "").strip()
    num_raw = str(_v91_find_first(item, [
        "opencode", "openCode", "open_code", "number", "numbers", "result", "openNumber", "open_numbers", "code"
    ], "") or "").strip()

    # 如果 code 被用作期号，避免把期号当开奖号码
    if num_raw == issue:
        num_raw = str(_v91_find_first(item, ["opencode", "openCode", "number", "numbers", "result", "openNumber"], "") or "").strip()

    # 保留 + 号前后含义，其他分隔统一为空格
    cleaned = num_raw.replace("，", ",").replace("|", "+").replace("、", ",").replace(";", ",")
    parts_plus = cleaned.split("+") if "+" in cleaned else [cleaned]
    main_nums = [int(x) for x in _re.findall(r"\d+", parts_plus[0])]
    refer_nums = []
    if len(parts_plus) > 1:
        refer_nums = [int(x) for x in _re.findall(r"\d+", "+".join(parts_plus[1:]))]

    cfg = V91_FUJIAN_CFG.get(game) or {}
    maxn = int(cfg.get("max", 99))
    need = int(cfg.get("need", len(main_nums) or 0))
    main_nums = [n for n in main_nums if 0 <= n <= maxn]
    refer_nums = [n for n in refer_nums if 0 <= n <= maxn]

    # 若接口没有 +，但返回超过 need 个，最后多出的保留为参考/特别号，不丢数据
    if not refer_nums and need and len(main_nums) > need:
        refer_nums = main_nums[need:]
        main_nums = main_nums[:need]

    main_str = " ".join(f"{n:02d}" for n in main_nums)
    ref_str = " ".join(f"{n:02d}" for n in refer_nums)
    full = main_str + (("+" + ref_str) if ref_str else "")

    if not issue:
        issue = str(_v91_find_first(item, ["id"], "") or "")
    return {
        "期号": issue,
        "开奖日期": date[:19],
        "开奖号码": full,
        "参考号码": ref_str,
        "完整号码": full,
        "销售额": str(_v91_find_first(item, ["sale", "sales", "saleamount", "salesAmount"], "") or ""),
        "奖池": str(_v91_find_first(item, ["pool", "poolmoney", "totalmoney", "jackpot"], "") or ""),
        "奖级": [],
        "来源": "huiniao_lotteryHistory_v91",
        "原始数据": item,
    }


def _v91_fetch_fujian_history(game, max_records=200000, progress_cb=None):
    """福建地方彩单独更新：按 page/limit 串行分页抓汇鸟接口。"""
    import json as _json
    import time as _time
    typ = V91_FUJIAN_TYPE_MAP.get(game)
    if not typ:
        return [], f"未知福建玩法: {game}"
    urls = [
        "http://api.huiniao.top/interface/home/lotteryHistory",
        "https://api.huiniao.top/interface/home/lotteryHistory",
    ]
    limit = 50
    page = 1
    rows = []
    seen = set()
    debug = []
    out_dir = HISTORY_EXPORT_DIR
    try:
        out_dir.mkdir(parents=True, exist_ok=True)
    except Exception:
        pass

    while len(rows) < int(max_records or 200000):
        if callable(progress_cb):
            try:
                progress_cb(f"{game}：请求福建接口 page={page}，已抓取{len(rows)}期")
            except Exception:
                pass
        params = {"type": typ, "page": page, "limit": limit}
        data = None; raw = ""; err = None; final_url = ""
        # 每页最多尝试 http/https 两个地址，每个地址带重试
        for url in urls:
            data, raw, err, final_url = _v89_request_json_with_retry(url, params, retries=3, timeout=20)
            if err is None and isinstance(data, (dict, list)):
                break
        debug.append({
            "game": game, "type": typ, "page": page, "limit": limit,
            "url": final_url, "err": err, "raw_preview": (raw or "")[:500],
            "time": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
        })
        try:
            (out_dir / f"debug_api_{game}.json").write_text(_json.dumps({"game": game, "type": typ, "rows": debug[-20:]}, ensure_ascii=False, indent=2), encoding="utf-8")
        except Exception:
            pass
        if err:
            return rows, ("福建接口网络失败，已保留已抓取数据: " + err) if rows else err

        items = _v91_flatten_json_items(data)
        if not items:
            return rows, "ok" if rows else "福建接口无返回数据"
        new_count = 0
        for item in items:
            rec = _v91_normalize_fujian_record(game, item)
            key = _v89_record_key(rec)
            if not key or key in seen:
                continue
            seen.add(key)
            if rec.get("开奖号码"):
                rows.append(rec)
                new_count += 1
        if len(items) < limit or new_count == 0:
            break
        page += 1
        _time.sleep(0.8)
    return rows, "ok"


def _v91_full_history_thread_run(self):
    """V91全量：全国数字彩走极速API；福建地方彩走汇鸟接口。"""
    try:
        key = _v42_read_jisu_key()
        if not key:
            try:
                key = (getattr(self, "_key", "") or getattr(getattr(self, "app", None), "jisuapi_key", "") or getattr(getattr(self, "app", None), "api_key", "") or "").strip()
            except Exception:
                key = ""

        requested = list(getattr(self, "games", []) or (list(V89_NUMERIC_GAMES) + V91_FUJIAN_GAMES))
        # 去重且保序
        games = []
        for g in requested:
            if g == "福建31选6":
                g = "福建31选7"
            if g not in games:
                games.append(g)
        if not games:
            games = list(V89_NUMERIC_GAMES) + V91_FUJIAN_GAMES

        old = _v42_load_existing_history()
        if not isinstance(old, dict):
            old = {}
        total_new = 0
        report = []
        max_per_game = int(getattr(self, "max_per_game", 200000) or 200000)
        total = len(games)

        for idx, game in enumerate(games):
            if getattr(self, "_cancel", False):
                report.append("用户取消全量更新")
                break
            try:
                self.progress.emit(idx, total, f"[{idx+1}/{total}] 正在更新 {game} …")
            except Exception:
                pass
            def _p(text, _idx=idx, _total=total):
                try:
                    self.progress.emit(_idx, _total, text)
                except Exception:
                    pass

            if game in V91_FUJIAN_GAMES:
                rows, msg = _v91_fetch_fujian_history(game, max_records=max_per_game, progress_cb=_p)
            else:
                if not key:
                    report.append(f"{game}: ❌ 未读取到极速API密钥")
                    continue
                cid = None
                try:
                    cid = JISUAPI_CONFIG.get("lottery_id_map", {}).get(game)
                except Exception:
                    cid = None
                if cid in (None, "", 0, "0"):
                    report.append(f"{game}: ❌ 缺少极速API玩法ID")
                    continue
                rows, msg = _v89_direct_fetch_history(game, cid, key, max_records=max_per_game, progress_cb=_p)

            before = len(old.get(game, []) if isinstance(old.get(game, []), list) else [])
            if rows:
                old[game] = _v89_merge_records(old.get(game, []), rows)
                after = len(old.get(game, []))
                added = max(0, after - before)
                total_new += added
                try:
                    if hasattr(self, "app"):
                        self.app.history_data = old
                except Exception:
                    pass
                try:
                    self.game_done.emit(game, len(rows), added, after)
                except Exception:
                    pass
                suffix = "" if msg == "ok" else f"；提示：{msg}"
                report.append(f"{game}: ✅ 抓取{len(rows)}期，新增{added}期，本地共{after}期{suffix}")
            else:
                report.append(f"{game}: ❌ {msg}")
            _v89_save_all_history(old)
            try:
                import time as _time
                _time.sleep(0.8)
            except Exception:
                pass
        try:
            if hasattr(self, "app"):
                self.app.history_data = old
        except Exception:
            pass
        try:
            self.progress.emit(total, total, "V91历史更新完成，正在刷新界面…")
        except Exception:
            pass
        self.all_finished.emit(total_new, report)
    except Exception as e:
        logger.error(f"V91全量/福建历史线程异常: {e}", exc_info=True)
        try:
            self.error.emit(str(e))
        except Exception:
            pass


def _v91_update_fujian_history_only(self, max_per_game: int = 200000):
    """首页按钮：只更新福建地方彩，不请求极速API。"""
    try:
        from PySide6.QtWidgets import QProgressDialog as _QProgressDialog, QMessageBox as _QMessageBox
    except Exception:
        _QProgressDialog = None
        _QMessageBox = QMessageBox
    if getattr(self, "full_history_thread", None) and self.full_history_thread.isRunning():
        _QMessageBox.information(self, "提示", "历史更新正在运行，请稍候…")
        return
    games = list(V91_FUJIAN_GAMES)
    progress = None
    if _QProgressDialog:
        progress = __Stage14SafeProgressDialog("准备单独更新福建彩票…", "取消", 0, len(games), self)
        progress.setWindowTitle("🏮 福建彩票单独更新")
        progress.setMinimumDuration(0)
        progress.setAutoClose(False)
        progress.setAutoReset(False)

    th = FullHistoryFetchThread(self, games, max_per_game=max_per_game, page_size=20)
    self.full_history_thread = th

    def on_progress(i, total, text):
        if progress:
            progress.setMaximum(max(1, total))
            progress.setValue(min(i, total))
            progress.setLabelText(text)
            if progress.wasCanceled():
                try: th.cancel()
                except Exception: pass
    def on_done(total_new, report):
        if progress:
            progress.setValue(len(games))
            progress.close()
        try:
            self.load_history_data()
        except Exception:
            try: self.history_data = _v42_load_existing_history()
            except Exception: pass
        try:
            self.calculate_omission_values()
        except Exception:
            pass
        _QMessageBox.information(self, "福建彩票更新完成", f"福建彩票单独更新完成。\n本次新增 {total_new} 期。\n\n" + "\n".join(report[:50]))
    def on_err(msg):
        if progress:
            progress.close()
        _QMessageBox.warning(self, "福建彩票更新出错", str(msg))
    th.progress.connect(on_progress)
    th.all_finished.connect(on_done)
    th.error.connect(on_err)
    if progress:
        progress.canceled.connect(th.cancel)
    th.start()


def _v91_install_patch():
    # 覆盖全量线程：福建走汇鸟，其它数字彩仍按原极速API逻辑
    try:
        if "FullHistoryFetchThread" in globals():
            FullHistoryFetchThread.run = _v91_full_history_thread_run
    except Exception:
        pass
    cls = globals().get("LotteryApp")
    if isinstance(cls, type):
        cls.update_fujian_history_only = _v91_update_fujian_history_only
    try:
        logger.info("V91补丁已安装：福建36选7/31选7/22选5单独走 huiniao lotteryHistory 接口；首页增加福建彩票更新入口")
    except Exception:
        pass

try:
    _v91_install_patch()
except Exception:
    try:
        logger.warning("V91补丁安装失败:\n" + traceback.format_exc())
    except Exception:
        pass
