# ============================================================
# V92 PATCH — 福建地方彩彻底脱离极速API全量更新
# 目标：
# 1) 福建36选7 / 福建31选7 / 福建22选5 永远不再走 JISUAPI /caipiao/history。
# 2) 全量更新报告不再出现“福建xx：缺少极速API玩法ID”。
# 3) 兼容旧名称“福建31选6”，统一转换为“福建31选7”。
# 4) 全国数字彩走极速API；福建地方彩走 api.huiniao.top lotteryHistory。
# ============================================================
V92_PATCH_VERSION = "V92_fujian_update_separated_fixed"
V92_JISU_NUMERIC_GAMES = ["双色球", "3D", "七乐彩", "快乐8", "大乐透", "七星彩", "排列三", "排列五"]
V92_FUJIAN_GAMES = ["福建36选7", "福建31选7", "福建22选5"]
V92_ALL_HISTORY_GAMES = V92_JISU_NUMERIC_GAMES + V92_FUJIAN_GAMES


def _v92_norm_game_name(game):
    g = str(game or "").strip()
    if g in ("福建31选6", "福建31选7附加", "fj31x7", "fj31x7fj"):
        return "福建31选7"
    if g == "fj36x7":
        return "福建36选7"
    if g == "fj22x5":
        return "福建22选5"
    return g


try:
    # 删除旧错误名称，避免旧入口把“福建31选6”拿去极速API查ID。
    _idmap = JISUAPI_CONFIG.setdefault("lottery_id_map", {})
    for _bad in ("福建31选6", "福建36选7", "福建31选7", "福建22选5"):
        # 福建三种彩票不需要极速API ID，放在 id_map 里反而容易被旧逻辑误判。
        _idmap.pop(_bad, None)
    # 保留全国数字彩映射；足彩/竞彩完全禁用。
    JISUAPI_CONFIG["football_lottery_types"] = []
    JISUAPI_CONFIG["football_leagues"] = []
    JISUAPI_CONFIG["football_fifa_available"] = False
except Exception:
    pass


def _v92_select_history_games(requested=None):
    """生成全量更新玩法列表：全国数字彩 + 福建地方彩，去重保序，不包含旧错名。"""
    raw = list(requested or V92_ALL_HISTORY_GAMES)
    out = []
    for g in raw:
        g = _v92_norm_game_name(g)
        if g in V92_ALL_HISTORY_GAMES and g not in out:
            out.append(g)
    if not out:
        out = list(V92_ALL_HISTORY_GAMES)
    return out


def _v92_full_history_thread_run(self):
    """V92全量线程：全国数字彩走极速API；福建地方彩走汇鸟接口；两边互不影响。"""
    try:
        key = _v42_read_jisu_key()
        if not key:
            try:
                key = (getattr(self, "_key", "") or getattr(getattr(self, "app", None), "jisuapi_key", "") or getattr(getattr(self, "app", None), "api_key", "") or "").strip()
            except Exception:
                key = ""

        games = _v92_select_history_games(getattr(self, "games", None))
        old = _v42_load_existing_history()
        if not isinstance(old, dict):
            old = {}
        total_new = 0
        report = []
        max_per_game = int(getattr(self, "max_per_game", 200000) or 200000)
        total = len(games)

        for idx, game in enumerate(games):
            if getattr(self, "_cancel", False):
                report.append("用户取消全量更新")
                break
            game = _v92_norm_game_name(game)
            try:
                self.progress.emit(idx, total, f"[{idx+1}/{total}] 正在更新 {game} …")
            except Exception:
                pass

            def _p(text, _idx=idx, _total=total):
                try:
                    self.progress.emit(_idx, _total, text)
                except Exception:
                    pass

            if game in V92_FUJIAN_GAMES:
                # 福建地方彩：只走用户提供的 api.huiniao.top 接口。
                rows, msg = _v91_fetch_fujian_history(game, max_records=max_per_game, progress_cb=_p)
            else:
                # 全国数字彩：只走极速API。
                if not key:
                    report.append(f"{game}: ❌ 未读取到极速API密钥")
                    continue
                try:
                    cid = JISUAPI_CONFIG.get("lottery_id_map", {}).get(game)
                except Exception:
                    cid = None
                if cid in (None, "", 0, "0"):
                    report.append(f"{game}: ❌ 缺少极速API玩法ID")
                    continue
                rows, msg = _v89_direct_fetch_history(game, cid, key, max_records=max_per_game, progress_cb=_p)

            before = len(old.get(game, []) if isinstance(old.get(game, []), list) else [])
            if rows:
                old[game] = _v89_merge_records(old.get(game, []), rows)
                after = len(old.get(game, []))
                added = max(0, after - before)
                total_new += added
                try:
                    if hasattr(self, "app"):
                        self.app.history_data = old
                except Exception:
                    pass
                try:
                    self.game_done.emit(game, len(rows), added, after)
                except Exception:
                    pass
                suffix = "" if msg == "ok" else f"；提示：{msg}"
                src = "福建接口" if game in V92_FUJIAN_GAMES else "极速API"
                report.append(f"{game}: ✅ {src}抓取{len(rows)}期，新增{added}期，本地共{after}期{suffix}")
            else:
                report.append(f"{game}: ❌ {msg}")

            # 每个玩法完成就落盘，避免中途网络失败导致已抓数据丢失。
            _v89_save_all_history(old)
            try:
                import time as _time
                _time.sleep(0.8)
            except Exception:
                pass

        try:
            if hasattr(self, "app"):
                self.app.history_data = old
        except Exception:
            pass
        try:
            self.progress.emit(total, total, "V92历史更新完成，正在刷新界面…")
        except Exception:
            pass
        self.all_finished.emit(total_new, report)
    except Exception as e:
        logger.error(f"V92全量历史线程异常: {e}", exc_info=True)
        try:
            self.error.emit(str(e))
        except Exception:
            pass


def _v92_update_all_history_full(self, max_per_game: int = 200000):
    """主界面全量更新入口：全国极速API + 福建接口，不再把福建玩法塞进极速API。"""
    try:
        from PySide6.QtWidgets import QProgressDialog as _QProgressDialog, QMessageBox as _QMessageBox
    except Exception:
        _QProgressDialog = None
        _QMessageBox = QMessageBox
    if (not isinstance(max_per_game, int)) or isinstance(max_per_game, bool) or max_per_game <= 0:
        max_per_game = 200000

    # 允许极速API不可用时继续更新福建彩票；全国玩法会在报告中提示失败。
    key = getattr(self, "jisuapi_key", "") or getattr(self, "api_key", "") or _v42_read_jisu_key()
    try:
        self.jisuapi_key = key
        self.api_key = key
    except Exception:
        pass

    if getattr(self, "_full_fetch_thread", None) and self._full_fetch_thread.isRunning():
        _QMessageBox.information(self, "提示", "全量更新正在进行中，请稍候…")
        return
    if getattr(self, "full_history_thread", None) and self.full_history_thread.isRunning():
        _QMessageBox.information(self, "提示", "历史更新正在运行，请稍候…")
        return

    games = list(V92_ALL_HISTORY_GAMES)
    if _QProgressDialog is None:
        _QMessageBox.warning(self, "缺少组件", "QProgressDialog 加载失败，无法显示全量更新进度。")
        return

    progress = __Stage14SafeProgressDialog("准备全量更新：全国数字彩走极速API，福建彩票走福建接口…", "取消", 0, len(games), self)
    progress.setWindowTitle("🔄 全量更新所有玩法全部历史")
    progress.setWindowModality(Qt.WindowModal)
    progress.setMinimumDuration(0)
    progress.setAutoClose(False)
    progress.setAutoReset(False)
    progress.setValue(0)

    thread = FullHistoryFetchThread(self, games, max_per_game=max_per_game, page_size=20)
    self._full_fetch_thread = thread
    self.full_history_thread = thread

    def _on_progress(idx, total, text):
        try:
            progress.setMaximum(max(1, total))
            if idx >= 0:
                progress.setValue(min(idx, total))
            progress.setLabelText(text)
            if progress.wasCanceled():
                try:
                    thread.cancel()
                except Exception:
                    pass
        except Exception:
            pass

    def _on_all_finished(total_added, report):
        try:
            progress.setValue(len(games))
            progress.close()
        except Exception:
            pass
        try:
            self.load_history_data()
        except Exception:
            try:
                self.history_data = _v42_load_existing_history()
            except Exception:
                pass
        for fn in ("update_home_results", "update_latest_results_display", "refresh_history_display", "calculate_omission", "calculate_omission_values"):
            try:
                f = getattr(self, fn, None)
                if callable(f):
                    f()
            except Exception:
                pass
        _QMessageBox.information(
            self,
            "✅ 全量更新完成",
            "全国数字彩已尽可能从极速API抓取；福建36选7/31选7/22选5已从福建接口抓取。\n"
            f"本次共新增 {total_added} 期。\n\n" + "\n".join(report[:80])
        )

    def _on_error(msg):
        try:
            progress.close()
        except Exception:
            pass
        _QMessageBox.warning(self, "全量更新出错", f"发生错误：\n{msg}")

    progress.canceled.connect(thread.cancel)
    thread.progress.connect(_on_progress)
    thread.all_finished.connect(_on_all_finished)
    thread.error.connect(_on_error)
    thread.start()


def _v92_update_fujian_history_only(self, max_per_game: int = 200000):
    """福建彩票单独更新入口：只更新福建三种玩法。"""
    try:
        from PySide6.QtWidgets import QProgressDialog as _QProgressDialog, QMessageBox as _QMessageBox
    except Exception:
        _QProgressDialog = None
        _QMessageBox = QMessageBox
    if getattr(self, "full_history_thread", None) and self.full_history_thread.isRunning():
        _QMessageBox.information(self, "提示", "历史更新正在运行，请稍候…")
        return
    games = list(V92_FUJIAN_GAMES)
    progress = None
    if _QProgressDialog:
        progress = __Stage14SafeProgressDialog("准备单独更新福建彩票…", "取消", 0, len(games), self)
        progress.setWindowTitle("🏮 福建彩票单独更新")
        progress.setMinimumDuration(0)
        progress.setAutoClose(False)
        progress.setAutoReset(False)
    thread = FullHistoryFetchThread(self, games, max_per_game=max_per_game, page_size=20)
    self.full_history_thread = thread

    def _on_progress(i, total, text):
        try:
            if progress:
                progress.setMaximum(max(1, total))
                progress.setValue(min(i, total))
                progress.setLabelText(text)
                if progress.wasCanceled():
                    try: thread.cancel()
                    except Exception: pass
        except Exception:
            pass

    def _on_done(total_new, report):
        try:
            if progress:
                progress.setValue(len(games))
                progress.close()
        except Exception:
            pass
        try:
            self.load_history_data()
        except Exception:
            try: self.history_data = _v42_load_existing_history()
            except Exception: pass
        try:
            self.calculate_omission_values()
        except Exception:
            pass
        _QMessageBox.information(self, "福建彩票更新完成", f"福建彩票单独更新完成。\n本次新增 {total_new} 期。\n\n" + "\n".join(report[:50]))

    def _on_err(msg):
        try:
            if progress:
                progress.close()
        except Exception:
            pass
        _QMessageBox.warning(self, "福建彩票更新出错", str(msg))

    if progress:
        progress.canceled.connect(thread.cancel)
    thread.progress.connect(_on_progress)
    thread.all_finished.connect(_on_done)
    thread.error.connect(_on_err)
    thread.start()


