# ============================================================
# V94 PATCH — 福建36选7/31选7/22选5：按用户提供 huiniao 接口文档修复
# 目标：
# 1) 福建三种彩票只走 http://api.huiniao.top/interface/home/lotteryHistory。
# 2) 兼容接口返回结构 data.last + data.data.list + totalPage。
# 3) 兼容字段 one/two/three/.../seven 作为开奖号码。
# 4) 福建三种彩票支持基础中奖比对；有官方奖级字段时优先显示官方数据。
# ============================================================
V94_PATCH_VERSION = "V94_fujian_online_compare_fix"
V94_HUINIAO_HISTORY_URLS = [
    "http://api.huiniao.top/interface/home/lotteryHistory",
    "https://api.huiniao.top/interface/home/lotteryHistory",
]
V94_FUJIAN_TYPE_MAP = {
    "福建36选7": "fj36x7",
    "福建31选7": "fj31x7",
    "福建22选5": "fj22x5",
    "福建31选6": "fj31x7",
}
V94_FUJIAN_GAMES = ["福建36选7", "福建31选7", "福建22选5"]
V94_NUMBER_FIELD_ORDER = [
    "one", "two", "three", "four", "five", "six", "seven", "eight", "nine", "ten",
    "red", "blue", "special", "refer", "refernumber", "ref", "bonus"
]


def _v94_recursive_find_lists(obj):
    """递归查找 huiniao 返回中的开奖列表。重点兼容 data.data.list。"""
    found = []
    def walk(x):
        if isinstance(x, list):
            if x and any(isinstance(i, dict) for i in x):
                found.append(x)
            for i in x:
                walk(i)
        elif isinstance(x, dict):
            # 优先检查常见列表键
            for k in ("list", "rows", "records", "items", "result"):
                v = x.get(k)
                if isinstance(v, list):
                    found.append(v)
            for v in x.values():
                if isinstance(v, (dict, list)):
                    walk(v)
    walk(obj)
    if not found:
        return []
    # 取最长列表；若长度相同，优先包含 code/day/one 等字段的列表
    def score(lst):
        s = len(lst) * 10
        if lst and isinstance(lst[0], dict):
            keys = set(lst[0].keys())
            s += len(keys & {"code", "day", "open_time", "one", "two", "three", "number", "opencode"})
        return s
    return max(found, key=score)


def _v94_get_nested(obj, path, default=None):
    cur = obj
    for p in path:
        if isinstance(cur, dict) and p in cur:
            cur = cur[p]
        else:
            return default
    return cur


def _v94_extract_total_page(obj):
    """从 huiniao 返回中读取 totalPage，读不到返回 None。"""
    for path in (("data", "data", "totalPage"), ("data", "totalPage"), ("result", "totalPage"), ("totalPage",)):
        v = _v94_get_nested(obj, path)
        try:
            if v not in (None, "", 0, "0"):
                return int(v)
        except Exception:
            pass
    return None




def _v94_item_value(item, keys, default=""):
    if not isinstance(item, dict):
        return default
    for k in keys:
        if k in item and item.get(k) not in (None, "", [], {}):
            return item.get(k)
    return default


def _v94_extract_numbers_from_huiniao_item(game, item):
    """从 huiniao 单条记录中提取开奖号码，优先 one/two/three 字段，其次 opencode/number。"""
    import re as _re
    cfg = V91_FUJIAN_CFG.get(game) or {"max": 99, "need": 0}
    maxn = int(cfg.get("max", 99))
    need = int(cfg.get("need", 0))

    nums = []
    # 文档示例：one/two/three...字段保存开奖号码
    for k in V94_NUMBER_FIELD_ORDER:
        if isinstance(item, dict) and k in item:
            v = item.get(k)
            if isinstance(v, (int, float)) or (isinstance(v, str) and v.strip().isdigit()):
                try:
                    n = int(v)
                    if 0 <= n <= maxn:
                        nums.append(n)
                except Exception:
                    pass

    # 若结构化字段不足，再尝试常规开奖号码字段；注意不要把期号 code 当号码
    if len(nums) < max(1, need):
        raw = str(_v94_item_value(item, [
            "opencode", "openCode", "open_code", "number", "numbers", "result", "openNumber", "open_numbers", "value"
        ], "") or "").strip()
        if raw:
            raw = raw.replace("，", ",").replace("|", "+").replace("、", ",").replace(";", ",")
            extra = [int(x) for x in _re.findall(r"\d+", raw) if 0 <= int(x) <= maxn]
            nums.extend(extra)

    # 去重但保留顺序，避免接口重复字段造成重复号码
    out = []
    for n in nums:
        if n not in out:
            out.append(n)
    main = out[:need] if need else out
    ref = out[need:] if need and len(out) > need else []
    return main, ref


def _v94_normalize_fujian_record(game, item):
    """将 huiniao 福建接口记录标准化为程序历史记录格式。"""
    if not isinstance(item, dict):
        item = {}
    issue = str(_v94_item_value(item, ["code", "expect", "issue", "issueno", "period", "lottery_no", "lotteryNo", "drawNo"], "") or "").strip()
    date = str(_v94_item_value(item, ["day", "open_time", "openTime", "opentime", "open_date", "openDate", "date", "time", "draw_time"], "") or "").strip()
    main_nums, ref_nums = _v94_extract_numbers_from_huiniao_item(game, item)
    main_str = " ".join(f"{int(n):02d}" for n in main_nums)
    ref_str = " ".join(f"{int(n):02d}" for n in ref_nums)
    full = main_str + (("+" + ref_str) if ref_str else "")
    prize_name = str(_v94_item_value(item, ["prize", "prize_name", "prizename", "win", "winstatus"], "") or "")
    return {
        "期号": issue,
        "开奖日期": date[:19],
        "开奖号码": full,
        "参考号码": ref_str,
        "完整号码": full,
        "销售额": str(_v94_item_value(item, ["sale", "sales", "saleamount", "salesAmount"], "") or ""),
        "奖池": str(_v94_item_value(item, ["pool", "poolmoney", "totalmoney", "jackpot"], "") or ""),
        "中奖等级": prize_name,
        "奖级": [],
        "来源": "huiniao_lotteryHistory_v94",
        "原始数据": item,
    }


# 覆盖 V91 的列表提取和标准化函数，供 V92 全量线程、福建单独更新同时使用。
def _v91_flatten_json_items(obj):
    return _v94_recursive_find_lists(obj)


def _v91_normalize_fujian_record(game, item):
    return _v94_normalize_fujian_record(game, item)


def _v91_fetch_fujian_history(game, max_records=200000, progress_cb=None, existing_rows=None):
    """V94 + V102：按 huiniao 文档分页抓福建地方彩。
    V102 修复：
      1) 处理 huiniao 业务码 code==401(请求频繁)：退避重试同一页，不再误报“无返回数据”
         （这正是 36选7 抓满若干页后、31选7/22选5 紧接着被限频而“无数据”的根因）。
      2) 增量抓取：本地已有的期号整页命中即停止，不再每次重复下载全部历史。
      3) 翻页/重试节奏放慢，降低被限频概率。"""
    import json as _json
    import time as _time
    typ = V94_FUJIAN_TYPE_MAP.get(game)
    if not typ:
        return [], f"未知福建玩法: {game}"
    # 本地已有期号（有开奖号码即视为已抓过），用于增量提前结束
    local_issues = set()
    for r in (existing_rows or []):
        if isinstance(r, dict) and str(r.get("开奖号码", "") or "").strip():
            iss = _v89_clean_issue(r.get("期号"))
            if iss:
                local_issues.add(iss)
    limit = 100
    page = 1
    rows = []
    seen = set()
    debug = []
    rate_limited = False
    consec_cached = 0   # 连续“整页都已本地存在”的页数
    out_dir = HISTORY_EXPORT_DIR
    try:
        out_dir.mkdir(parents=True, exist_ok=True)
    except Exception:
        pass

    while len(rows) < int(max_records or 200000):
        if callable(progress_cb):
            try:
                progress_cb(f"{game}：福建接口 page={page}，已抓取{len(rows)}期")
            except Exception:
                pass
        params = {"type": typ, "page": page, "limit": limit}
        data = None; raw = ""; err = None; final_url = ""; biz_code = None
        # 业务码 401（请求频繁）退避重试：同一页最多重试 5 次，逐步加长等待
        for attempt in range(5):
            for url in V94_HUINIAO_HISTORY_URLS:
                data, raw, err, final_url = _v89_request_json_with_retry(url, params, retries=3, timeout=20)
                if err is None and isinstance(data, (dict, list)):
                    break
            biz_code = data.get("code") if isinstance(data, dict) else None
            if err is None and str(biz_code) == "401":
                rate_limited = True
                if callable(progress_cb):
                    try:
                        progress_cb(f"{game}：接口请求频繁(401)，等待重试 page={page}（第{attempt+1}次）")
                    except Exception:
                        pass
                _time.sleep(2.5 + attempt * 2.5)
                continue
            break
        debug.append({
            "game": game, "type": typ, "page": page, "limit": limit,
            "url": final_url, "err": err, "biz_code": biz_code,
            "raw_preview": (raw or "")[:800],
            "time": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
        })
        try:
            (out_dir / f"debug_api_{game}.json").write_text(
                _json.dumps({"game": game, "type": typ, "debug": debug[-30:]}, ensure_ascii=False, indent=2),
                encoding="utf-8"
            )
        except Exception:
            pass
        if err:
            return rows, ("福建接口网络失败，已保留已抓取数据: " + err) if rows else err

        items = _v94_recursive_find_lists(data)
        total_page = _v94_extract_total_page(data)
        if not items:
            # 区分“限频”与“真的没有数据”，避免把限频误报成无数据
            if str(biz_code) == "401":
                return rows, ("福建接口请求频繁(401)，已抓取部分数据，请稍后再更新" if rows
                              else "福建接口请求频繁(401)，请稍后再试")
            if str(biz_code) == "0":
                return rows, "福建接口参数错误(0)"
            return rows, "ok" if rows else "福建接口无返回数据"

        new_count = 0
        known_in_page = 0
        dict_items = 0
        for item in items:
            if not isinstance(item, dict):
                continue
            dict_items += 1
            rec = _v94_normalize_fujian_record(game, item)
            key = _v89_record_key(rec)
            if not key or key in seen:
                continue
            seen.add(key)
            if not rec.get("开奖号码"):
                continue
            if key in local_issues:
                known_in_page += 1
            rows.append(rec)
            new_count += 1

        # 增量提前结束：要求连续多页期号全部本地已有才停止，
        # 既跳过已更新的、又能在本地有小缺口时继续补没更新过的。
        if local_issues and dict_items > 0 and known_in_page >= dict_items:
            consec_cached += 1
            if consec_cached >= 3:
                break
        else:
            consec_cached = 0
        if total_page is not None and page >= total_page:
            break
        if len(items) < limit or new_count == 0:
            break
        page += 1
        _time.sleep(1.0)
    return rows, ("ok-含限频重试" if rate_limited and rows else "ok")


def _v94_fujian_prize(game_type, bet_numbers, draw_numbers, draw_record=None):
    """福建地方彩基础中奖比对。官方浮动/具体奖金额以后端奖级为准；本地给固定奖兜底。"""
    try:
        bet = {int(x) for x in (bet_numbers or [])}
        draw = [int(x) for x in (draw_numbers or [])]
    except Exception:
        return "未中奖", 0
    if game_type == "福建36选7":
        main = set(draw[:7]); special = draw[7] if len(draw) >= 8 else None
        hit = len(bet & main)
        sp = 1 if (special is not None and special in bet) else 0
        if hit == 7: lvl = "特等奖"
        elif hit == 6 and sp: lvl = "一等奖"
        elif hit == 6: lvl = "二等奖"
        elif hit == 5 and sp: lvl = "三等奖"
        elif hit == 5: lvl = "四等奖"
        elif hit == 4 and sp: lvl = "五等奖"
        elif hit == 4 or (hit == 3 and sp): lvl = "六等奖"
        else: return "未中奖", 0
        base = PRIZE_RULES.get(game_type, {}).get(lvl, {}).get("base", 0)
        return lvl, base if isinstance(base, (int, float)) else 0
    if game_type == "福建31选7":
        main = set(draw[:7])
        hit = len(bet & main)
        if hit >= 7: lvl = "一等奖"
        elif hit == 6: lvl = "二等奖"
        elif hit == 5: lvl = "三等奖"
        elif hit == 4: lvl = "四等奖"
        else: return "未中奖", 0
        base = PRIZE_RULES.get(game_type, {}).get(lvl, {}).get("base", 0)
        return lvl, base if isinstance(base, (int, float)) else 0
    if game_type == "福建22选5":
        main = set(draw[:5])
        hit = len(bet & main)
        if hit >= 5: lvl = "一等奖"
        elif hit == 4: lvl = "二等奖"
        elif hit == 3: lvl = "三等奖"
        else: return "未中奖", 0
        base = PRIZE_RULES.get(game_type, {}).get(lvl, {}).get("base", 0)
        return lvl, base if isinstance(base, (int, float)) else 0
    return "未中奖", 0


def _v94_install_patch():
    # 补充福建31选7四等奖，避免命中4个时显示奖级但金额/规则缺失。
    try:
        PRIZE_RULES.setdefault("福建31选7", {}).setdefault("四等奖", {"base": 5, "description": "中4个号（以官方为准）"})
    except Exception:
        pass
    cls = globals().get("LotteryApp")
    if isinstance(cls, type):
        old_calc = getattr(cls, "calculate_prize", None)
        if callable(old_calc) and not getattr(cls, "_v94_calc_wrapped", False):
            def _calc(self, game_type, bet_numbers, draw_numbers, draw_record, additional=False, bet_type=""):
                g = _v92_norm_game_name(game_type) if "_v92_norm_game_name" in globals() else str(game_type or "")
                if g in V94_FUJIAN_GAMES:
                    return _v94_fujian_prize(g, bet_numbers, draw_numbers, draw_record)
                return old_calc(self, game_type, bet_numbers, draw_numbers, draw_record, additional, bet_type)
            cls.calculate_prize = _calc
            cls._v94_calc_wrapped = True
    try:
        logger.info("V94补丁已安装：福建地方彩按 huiniao 文档解析 data.data.list / one-two-three 字段，并支持基础中奖比对")
    except Exception:
        pass

try:
    _v94_install_patch()
except Exception:
    try:
        logger.warning("V94补丁安装失败:\n" + traceback.format_exc())
    except Exception:
        pass
