# ============================================================
# V98 PATCH — 福建彩入口/更新彻底修复 + 全量更新分流加固
# 1) 修复 update_fujian_history_only 缺失导致首页按钮崩溃。
# 2) 福建36选7/31选7/22选5 永远不走极速API，避免“缺少极速API玩法ID”。
# 3) 首页直接增加福建36选7、福建31选7、福建22选5入口按钮。
# 4) 避免后台线程直接创建/操作UI，只通过 Signal 返回主线程。
# ============================================================
V98_PATCH_VERSION = "V98_fujian_home_update_bugfix"
V98_JISU_GAMES = ["双色球", "3D", "七乐彩", "快乐8", "大乐透", "七星彩", "排列三", "排列五"]
V98_FUJIAN_GAMES = ["福建36选7", "福建31选7", "福建22选5"]
V98_ALL_GAMES = V98_JISU_GAMES + V98_FUJIAN_GAMES


def _v98_norm_game(game):
    g = str(game or "").strip()
    if g in ("福建31选6", "福建31选7", "fj31x7"):
        return "福建31选7"
    if g in ("福建36选7", "fj36x7"):
        return "福建36选7"
    if g in ("福建22选5", "fj22x5"):
        return "福建22选5"
    return g


def _v98_game_list(requested=None):
    raw = list(requested or V98_ALL_GAMES)
    out = []
    for g in raw:
        g = _v98_norm_game(g)
        # 彻底过滤足彩/竞彩和旧错名
        if g in ("任九", "胜负彩", "进球彩", "竞彩足球", "竞彩篮球", "福建31选6"):
            continue
        if g in V98_ALL_GAMES and g not in out:
            out.append(g)
    return out or list(V98_ALL_GAMES)


def _v98_fetch_fujian_history(game, max_records=200000, progress_cb=None, existing_rows=None):
    """福建地方彩统一抓取。优先复用V94/V91解析；失败时返回清晰错误。"""
    game = _v98_norm_game(game)
    fn = globals().get("_v91_fetch_fujian_history")
    if callable(fn):
        try:
            return fn(game, max_records=max_records, progress_cb=progress_cb, existing_rows=existing_rows)
        except TypeError:
            # 兼容未带 existing_rows 参数的旧实现
            return fn(game, max_records=max_records, progress_cb=progress_cb)
    return [], "福建接口函数未加载"


def _v98_full_history_thread_run(self):
    """全量线程最终版：全国数字彩走极速API；福建地方彩走 huiniao；不在线程里创建UI。"""
    try:
        key = ""
        try:
            key = _v42_read_jisu_key()
        except Exception:
            key = ""
        if not key:
            try:
                key = (getattr(self, "_key", "") or getattr(getattr(self, "app", None), "jisuapi_key", "") or getattr(getattr(self, "app", None), "api_key", "") or "").strip()
            except Exception:
                key = ""

        games = _v98_game_list(getattr(self, "games", None))
        old = _v42_load_existing_history()
        if not isinstance(old, dict):
            old = {}
        report, total_new = [], 0
        total = len(games)
        max_per_game = int(getattr(self, "max_per_game", 200000) or 200000)

        for idx, game in enumerate(games):
            if getattr(self, "_cancel", False):
                report.append("用户取消全量更新")
                break
            game = _v98_norm_game(game)
            try:
                self.progress.emit(idx, total, f"[{idx+1}/{total}] 正在更新 {game} …")
            except Exception:
                pass

            def _p(text, _idx=idx, _total=total):
                try:
                    self.progress.emit(_idx, _total, text)
                except Exception:
                    pass

            try:
                if game in V98_FUJIAN_GAMES:
                    rows, msg = _v98_fetch_fujian_history(game, max_records=max_per_game, progress_cb=_p,
                                                          existing_rows=old.get(game, []))
                else:
                    if not key:
                        report.append(f"{game}: ❌ 未读取到极速API密钥")
                        continue
                    cid = None
                    try:
                        cid = JISUAPI_CONFIG.get("lottery_id_map", {}).get(game)
                    except Exception:
                        cid = None
                    if cid in (None, "", 0, "0"):
                        report.append(f"{game}: ❌ 缺少极速API玩法ID")
                        continue
                    rows, msg = _v89_direct_fetch_history(game, cid, key, max_records=max_per_game, progress_cb=_p,
                                                          existing_rows=old.get(game, []))
            except Exception as e:
                rows, msg = [], str(e)

            before = len(old.get(game, []) if isinstance(old.get(game, []), list) else [])
            if rows:
                try:
                    old[game] = _v89_merge_records(old.get(game, []), rows)
                except Exception:
                    old[game] = list(rows)
                after = len(old.get(game, []))
                added = max(0, after - before)
                total_new += added
                try:
                    if hasattr(self, "app"):
                        self.app.history_data = old
                except Exception:
                    pass
                try:
                    self.game_done.emit(game, len(rows), added, after)
                except Exception:
                    pass
                suffix = "" if msg == "ok" else f"；提示：{msg}"
                report.append(f"{game}: ✅ 抓取{len(rows)}期，新增{added}期，本地共{after}期{suffix}")
            else:
                report.append(f"{game}: ❌ {msg}")
            try:
                _v89_save_all_history(old)
            except Exception as e:
                report.append(f"{game}: ⚠️ 保存失败 {e}")
            try:
                import time as _time
                # 福建玩法走 huiniao，连续请求容易触发 401 限频，间隔放长一些
                _time.sleep(1.5 if game in V98_FUJIAN_GAMES else 0.5)
            except Exception:
                pass

        try:
            if hasattr(self, "app"):
                self.app.history_data = old
        except Exception:
            pass
        try:
            self.progress.emit(total, total, "历史更新完成，正在刷新界面…")
        except Exception:
            pass
        try:
            self.all_finished.emit(total_new, report)
        except Exception:
            pass
    except Exception as e:
        logger.error(f"V98全量历史线程异常: {e}", exc_info=True)
        try:
            self.error.emit(str(e))
        except Exception:
            pass


def _v98_update_history_common(self, games, title, max_per_game=200000):
    """主线程创建进度框；后台线程只抓数据。"""
    try:
        from PySide6.QtWidgets import QProgressDialog as _QProgressDialog, QMessageBox as _QMessageBox
    except Exception:
        _QProgressDialog = None
        _QMessageBox = QMessageBox
    games = _v98_game_list(games)
    if getattr(self, "full_history_thread", None) and self.full_history_thread.isRunning():
        _QMessageBox.information(self, "提示", "历史更新正在运行，请稍候…")
        return
    progress = None
    if _QProgressDialog:
        progress = __Stage14SafeProgressDialog(f"准备{title}…", "取消", 0, max(1, len(games)), self)
        progress.setWindowTitle(title)
        progress.setMinimumDuration(0)
        progress.setAutoClose(False)
        progress.setAutoReset(False)
    th = FullHistoryFetchThread(self, games, max_per_game=max_per_game, page_size=20)
    self.full_history_thread = th

    def on_progress(i, total, text):
        if progress:
            progress.setMaximum(max(1, total))
            progress.setValue(min(i, total))
            progress.setLabelText(text)
            if progress.wasCanceled():
                try: th.cancel()
                except Exception: pass
    def on_done(total_new, report):
        if progress:
            progress.setValue(len(games))
            progress.close()
        try:
            self.load_history_data()
        except Exception:
            try: self.history_data = _v42_load_existing_history()
            except Exception: pass
        try:
            self.calculate_omission_values()
        except Exception:
            pass
        text = f"{title}完成。\n本次新增 {total_new} 期。\n\n" + "\n".join(report[:80])
        _QMessageBox.information(self, title, text)
    def on_err(msg):
        if progress:
            progress.close()
        _QMessageBox.warning(self, f"{title}出错", str(msg))
    th.progress.connect(on_progress)
    th.all_finished.connect(on_done)
    th.error.connect(on_err)
    if progress:
        progress.canceled.connect(th.cancel)
    th.start()


