# ============================================================
# V101 PATCH: 21点后投注自动归属下一期
# ============================================================
try:
    from datetime import datetime as _v101_datetime
except Exception:
    _v101_datetime = None
import re as _v101_re


def _v101_is_after_21(now=None):
    try:
        now = now or _v101_datetime.now()
        return (now.hour, now.minute, now.second) >= (21, 0, 0)
    except Exception:
        return False


def _v101_next_issue(issue):
    """期号+1，保留纯数字期号长度；失败时返回原期号。"""
    try:
        raw = str(issue or "").strip()
        m = _v101_re.search(r"\d+", raw)
        if not m:
            return raw
        token = m.group(0)
        nxt = str(int(token) + 1).zfill(len(token))
        return raw[:m.start()] + nxt + raw[m.end():]
    except Exception:
        return str(issue or "")


def _v101_get_latest_issue(self, game):
    try:
        data = getattr(self, "history_data", {}) or {}
        rows = data.get(game) or data.get(str(game)) or []
        if rows:
            return str(rows[0].get("期号", "") or rows[0].get("issueno", "") or rows[0].get("code", ""))
    except Exception:
        pass
    return ""


def _v101_get_bet_issue(self, game, current_issue="", now=None):
    """投注归属期号：21:00以后按下一期保存。"""
    issue = str(current_issue or "").strip()
    if not issue:
        issue = _v101_get_latest_issue(self, game)
    if issue and _v101_is_after_21(now):
        return _v101_next_issue(issue)
    return issue


def _v101_normalize_new_bet_record(self, record):
    """统一修正投注记录期号。只处理未打标的新记录，避免反复+1。"""
    try:
        if not isinstance(record, dict):
            return record
        if record.get("_v101_issue_fixed"):
            return record
        game = record.get("game") or record.get("游戏") or ""
        if not game:
            return record
        old_issue = str(record.get("target_issue", "") or "").strip()
        new_issue = _v101_get_bet_issue(self, game, old_issue)
        if new_issue:
            record["target_issue"] = new_issue
            record["bet_issue"] = new_issue
        record["_v101_issue_rule"] = "21点后自动归属下一期"
        record["_v101_issue_fixed"] = True
    except Exception:
        pass
    return record


def _v101_wrap_add_betting_record(old_func):
    def _wrapped(self, game, bet_type, numbers, bets_count, amount, target_issue="", additional=False):
        try:
            target_issue = _v101_get_bet_issue(self, game, target_issue)
        except Exception:
            pass
        return old_func(self, game, bet_type, numbers, bets_count, amount, target_issue, additional)
    return _wrapped


def _v101_wrap_save_betting_history(old_func):
    def _wrapped(self, *args, **kwargs):
        try:
            for r in getattr(self, "betting_history", []) or []:
                _v101_normalize_new_bet_record(self, r)
        except Exception:
            pass
        return old_func(self, *args, **kwargs)
    return _wrapped


def _v101_install_patch():
    cls = globals().get("LotteryApp")
    if not isinstance(cls, type):
        return
    cls.get_bet_issue_after_21 = _v101_get_bet_issue
    cls._v101_normalize_new_bet_record = _v101_normalize_new_bet_record
    if hasattr(cls, "add_betting_record") and not getattr(cls.add_betting_record, "_v101_wrapped", False):
        wrapped = _v101_wrap_add_betting_record(cls.add_betting_record)
        wrapped._v101_wrapped = True
        cls.add_betting_record = wrapped
    if hasattr(cls, "save_betting_history") and not getattr(cls.save_betting_history, "_v101_wrapped", False):
        wrapped = _v101_wrap_save_betting_history(cls.save_betting_history)
        wrapped._v101_wrapped = True
        cls.save_betting_history = wrapped
    try:
        logger.info("V101补丁已安装：21点后投注号码自动保存为下一期")
    except Exception:
        pass

try:
    _v101_install_patch()
except Exception:
    try:
        logger.warning("V101补丁安装失败:\n" + traceback.format_exc())
    except Exception:
        pass
# ============================================================
# V101 PATCH END
