# 自绘控件
# =========================================================================== #
class PitchHeader(QWidget):
    """草坪条纹顶栏:割草纹 + 中线 + 中圈,世界杯球场视角。"""

    def __init__(self, parent=None):
        super().__init__(parent)
        self.setAutoFillBackground(False)

    def paintEvent(self, _):
        p = QPainter(self)
        p.setRenderHint(QPainter.Antialiasing)
        w, h = self.width(), self.height()
        # 底色渐变
        grad = QLinearGradient(0, 0, 0, h)
        grad.setColorAt(0.0, QColor(C_PITCH_B))
        grad.setColorAt(1.0, QColor(C_PITCH_A))
        p.fillRect(self.rect(), grad)
        # 割草竖条纹
        stripe_w = max(36, w // 12)
        dark = QColor(0, 0, 0, 22)
        for i, x in enumerate(range(0, w + stripe_w, stripe_w)):
            if i % 2 == 0:
                p.fillRect(x, 0, stripe_w, h, dark)
        # 中线 + 中圈(白色草坪划线)
        line = QPen(QColor(255, 255, 255, 70), 2)
        p.setPen(line)
        cx = w * 0.5
        p.drawLine(int(cx), 0, int(cx), h)
        r = h * 0.62
        p.setBrush(Qt.NoBrush)
        p.drawEllipse(QRectF(cx - r, h / 2.0 - r, r * 2, r * 2))
        # 底部金色饰线(大力神杯金)
        p.fillRect(0, h - 3, w, 3, QColor(C_GOLD))
        p.end()


class ProbBar(QWidget):
    """主胜/平/客胜三段水平概率条,段内标百分比。"""

    def __init__(self, placeholder: str = "选择比赛后显示概率分布", parent=None):
        super().__init__(parent)
        self.probs = None
        self.placeholder = placeholder
        self.setMinimumHeight(30)

    def set_probs(self, probs: Optional[dict]):
        self.probs = _norm(probs)
        self.update()

    def paintEvent(self, _):
        p = QPainter(self)
        p.setRenderHint(QPainter.Antialiasing)
        rect = self.rect().adjusted(1, 3, -1, -3)
        radius = rect.height() / 2.0
        if not self.probs:
            p.setPen(QPen(QColor("#c4cdd5"), 1))
            p.setBrush(QColor("#e9edf1"))
            p.drawRoundedRect(QRectF(rect), radius, radius)
            p.setPen(QColor("#8a949e"))
            p.drawText(rect, Qt.AlignCenter, self.placeholder)
            p.end()
            return
        p.setPen(Qt.NoPen)
        p.setBrush(QColor("#e9edf1"))
        p.drawRoundedRect(QRectF(rect), radius, radius)
        p.save()
        p.setClipRect(QRectF(rect))
        x = float(rect.left())
        total_w = float(rect.width())
        font = QFont(self.font())
        font.setBold(True)
        p.setFont(font)
        for key, color in (("home", QColor(C_HOME)), ("draw", QColor(C_DRAW)),
                           ("away", QColor(C_AWAY))):
            w = total_w * self.probs[key]
            seg = QRectF(x, rect.top(), w, rect.height())
            p.setPen(Qt.NoPen)
            p.setBrush(color)
            p.drawRect(seg)
            if w > 52:
                p.setPen(QColor("white"))
                p.drawText(seg, Qt.AlignCenter, "%s %.0f%%"
                           % (OUTCOME_CN[key], self.probs[key] * 100))
            x += w
        p.restore()
        p.setPen(QPen(QColor("#b9c2cb"), 1))
        p.setBrush(Qt.NoBrush)
        p.drawRoundedRect(QRectF(rect), radius, radius)
        p.end()


