class Scoreboard(QWidget):
    """球场记分牌:深绿渐变面板,白字对阵 + 金色 VS;世界杯金边。"""

    def __init__(self, parent=None):
        super().__init__(parent)
        self.data = None     # (no, ev) 或 None
        self.setFixedHeight(64)

    def set_match(self, no: str, ev: dict):
        self.data = (no, ev)
        self.update()

    def clear(self):
        self.data = None
        self.update()

    def paintEvent(self, _):
        p = QPainter(self)
        p.setRenderHint(QPainter.Antialiasing)
        rect = QRectF(self.rect()).adjusted(1, 1, -1, -1)
        grad = QLinearGradient(0, 0, 0, rect.height())
        grad.setColorAt(0.0, QColor("#14532d"))
        grad.setColorAt(1.0, QColor("#0e3d22"))
        wc = bool(self.data) and is_world_cup(ev_league_name(self.data[1]))
        p.setPen(QPen(QColor(C_GOLD) if wc else QColor("#0a2e18"), 2))
        p.setBrush(grad)
        p.drawRoundedRect(rect, 12, 12)
        if not self.data:
            p.setPen(QColor("#7fae8f"))
            p.drawText(rect, Qt.AlignCenter, "⚽ 点击卡片选择一场比赛")
            p.end()
            return
        no, ev = self.data
        dt = ev_dt(ev)
        league = cn_league(ev_league_name(ev))
        meta = "%s · %s · %s%s" % (no or "—",
                                   dt.strftime("%m-%d %H:%M") if dt else "?",
                                   "🏆" if wc else "", league)
        p.setPen(QColor(C_GOLD) if wc else QColor("#9fd4ae"))
        f = QFont(self.font())
        f.setPointSizeF(max(8.0, f.pointSizeF() - 1))
        p.setFont(f)
        top = QRectF(rect.left(), rect.top() + 4, rect.width(), 18)
        p.drawText(top, Qt.AlignCenter, meta)
        # 对阵行
        f2 = QFont(self.font())
        f2.setBold(True)
        f2.setPointSizeF(f2.pointSizeF() + 3)
        p.setFont(f2)
        mid_y = rect.top() + 22
        mid_h = rect.height() - 26
        cw = 44.0
        left = QRectF(rect.left() + 8, mid_y, rect.width() / 2 - cw / 2 - 8, mid_h)
        right = QRectF(rect.left() + rect.width() / 2 + cw / 2, mid_y,
                       rect.width() / 2 - cw / 2 - 8, mid_h)
        center = QRectF(rect.left() + rect.width() / 2 - cw / 2, mid_y, cw, mid_h)
        p.setPen(QColor("white"))
        p.drawText(left, Qt.AlignRight | Qt.AlignVCenter,
                   cn_team(str(ev.get("home_team", ""))))
        p.drawText(right, Qt.AlignLeft | Qt.AlignVCenter,
                   cn_team(str(ev.get("away_team", ""))))
        p.setPen(QColor(C_GOLD))
        p.drawText(center, Qt.AlignCenter, "VS")
        p.end()


def _odds_chip(label: str, value, color: str) -> QLabel:
    text = "%s %.2f" % (label, value) if value else "%s —" % label
    lab = QLabel(text)
    lab.setAlignment(Qt.AlignCenter)
    lab.setStyleSheet(
        "background:%s; color:white; border-radius:10px;"
        "padding:2px 8px; font-weight:bold; font-size:12px;" % color)
    return lab


def make_match_card(no: str, ev: dict, badge=None) -> QFrame:
    """一场比赛的卡片;badge=(文字, 颜色) 为推荐角标,可空。"""
    wc = is_world_cup(ev_league_name(ev))
    card = QFrame()
    card.setObjectName("matchCardWC" if wc else "matchCard")
    lay = QVBoxLayout(card)
    lay.setContentsMargins(12, 8, 12, 8)
    lay.setSpacing(4)

    dt = ev_dt(ev)
    league = cn_league(ev_league_name(ev))
    inj = ev_injuries(ev)
    n_inj = len(inj["home"]) + len(inj["away"])

    # 行1:元信息 + 角标
    row1 = QHBoxLayout()
    meta = QLabel("%s · %s · %s%s" % (
        no or "—", dt.strftime("%m-%d %H:%M") if dt else "?",
        "🏆" if wc else "", league))
    meta.setStyleSheet("color:%s; font-size:12px; font-weight:bold;"
                       % (C_GOLD if wc else "#5a6772"))
    row1.addWidget(meta)
    row1.addStretch(1)
    if badge:
        b_lab = QLabel(badge[0])
        b_lab.setStyleSheet("background:%s; color:white; border-radius:9px;"
                            "padding:1px 7px; font-size:11px; font-weight:bold;"
                            % badge[1])
        row1.addWidget(b_lab)
    if n_inj:
        inj_lab = QLabel("⚠ %d人" % n_inj)
        inj_lab.setStyleSheet("color:%s; font-size:12px; font-weight:bold;" % C_AVOID)
        row1.addWidget(inj_lab)
    lay.addLayout(row1)

    # 行2:对阵
    row2 = QHBoxLayout()
    h_lab = QLabel(cn_team(str(ev.get("home_team", ""))))
    h_lab.setStyleSheet("font-size:15px; font-weight:bold; color:#16232e;")
    h_lab.setAlignment(Qt.AlignRight | Qt.AlignVCenter)
    vs = QLabel("VS")
    vs.setAlignment(Qt.AlignCenter)
    vs.setFixedWidth(38)
    vs.setStyleSheet("color:white; background:%s; border-radius:12px;"
                     "font-weight:bold; font-size:12px; padding:2px;"
                     % (C_GOLD if wc else C_ACCENT))
    a_lab = QLabel(cn_team(str(ev.get("away_team", ""))))
    a_lab.setStyleSheet("font-size:15px; font-weight:bold; color:#16232e;")
    a_lab.setAlignment(Qt.AlignLeft | Qt.AlignVCenter)
    row2.addWidget(h_lab, 1)
    row2.addWidget(vs)
    row2.addWidget(a_lab, 1)
    lay.addLayout(row2)

    # 行3:赔率胶囊
    odds = ev_odds(ev)
    row3 = QHBoxLayout()
    row3.addStretch(1)
    if odds:
        row3.addWidget(_odds_chip("胜", odds["odds_home"], C_HOME))
        row3.addWidget(_odds_chip("平", odds["odds_draw"], C_DRAW))
        row3.addWidget(_odds_chip("负", odds["odds_away"], C_AWAY))
    else:
        na = QLabel("暂无赔率")
        na.setStyleSheet("color:#8a949e; font-size:12px;")
        row3.addWidget(na)
    row3.addStretch(1)
    lay.addLayout(row3)
    return card


