class BatchDialog(QDialog):
    def __init__(self, text: str, parent=None, records=None, plog=None):
        super().__init__(parent)
        self.setWindowTitle("批量推荐(按最优 EV 排序)")
        self.resize(420, 640)
        self._text = text
        self._records = records or []
        self._plog = plog
        lay = QVBoxLayout(self)
        ed = QPlainTextEdit()
        ed.setReadOnly(True)
        ed.setPlainText(text)
        ed.setFont(QFont("Monospace", 10))
        ed.setStyleSheet("background:#ffffff; border:1px solid #d4dbe2;"
                         "border-radius:8px; padding:6px;")
        lay.addWidget(ed)
        brow = QHBoxLayout()
        if self._records and self._plog:
            sv = QPushButton("💾 全部记入日志")
            sv.clicked.connect(self._save_all)
            brow.addWidget(sv)
        exp = QPushButton("导出TXT")
        exp.clicked.connect(self._export)
        brow.addWidget(exp)
        btn = QPushButton("关闭")
        btn.clicked.connect(self.accept)
        brow.addWidget(btn)
        lay.addLayout(brow)

    def _save_all(self):
        n = sum(1 for r in self._records if self._plog.add(r))
        QMessageBox.information(self, "日志", "已记入 %d 条预测。" % n)

    def _export(self):
        path = os.path.join(os.path.expanduser("~"), "竞彩推荐_%s.txt"
                            % datetime.now().strftime("%Y%m%d_%H%M"))
        try:
            with open(path, "w", encoding="utf-8") as f:
                f.write(self._text)
            QMessageBox.information(self, "导出成功", "已保存到:\n%s" % path)
        except OSError as e:
            QMessageBox.warning(self, "导出失败", str(e))


class LogDialog(QDialog):
    """预测日志:统计、最近明细、对账更新、导出、清空。"""

    def __init__(self, log: PredictionLog, token: str, parent=None):
        super().__init__(parent)
        self.setWindowTitle("📒 预测日志")
        self.resize(420, 640)
        self.log, self.token = log, token
        self.rec_thread = None
        lay = QVBoxLayout(self)
        self.stats_lbl = QLabel("")
        self.stats_lbl.setWordWrap(True)
        self.stats_lbl.setStyleSheet("background:white; border:1px solid #d8e2d8;"
                                     "border-radius:10px; padding:8px;")
        lay.addWidget(self.stats_lbl)
        self.ed = QPlainTextEdit()
        self.ed.setReadOnly(True)
        self.ed.setFont(QFont("Monospace", 10))
        self.ed.setStyleSheet("background:#ffffff; border:1px solid #d4dbe2;"
                              "border-radius:8px; padding:6px;")
        lay.addWidget(self.ed, 1)
        self._learned = None
        brow = QHBoxLayout()
        self.rec_btn = QPushButton("对账更新")
        self.rec_btn.setObjectName("goldBtn")
        self.rec_btn.clicked.connect(self.on_reconcile)
        brow.addWidget(self.rec_btn)
        self.apply_btn = QPushButton("⚖️ 应用实盘权重")
        self.apply_btn.setEnabled(False)
        self.apply_btn.clicked.connect(self.on_apply_weight)
        brow.addWidget(self.apply_btn)
        exp = QPushButton("导出TXT")
        exp.clicked.connect(self.on_export)
        brow.addWidget(exp)
        self.clr_btn = QPushButton("清空")
        self.clr_btn.clicked.connect(self.on_clear)
        brow.addWidget(self.clr_btn)
        cls = QPushButton("关闭")
        cls.clicked.connect(self.accept)
        brow.addWidget(cls)
        lay.addLayout(brow)
        self.refresh()

    def refresh(self):
        records = self.log.load()
        stats = log_stats(records)
        self._learned = learn_weight(records)
        if self._learned:
            w, n, gain = self._learned
            stats += ("\n⚖️ 实盘最优权重:模型 %.0f%% / 市场 %.0f%%"
                      "(n=%d,似然提升 %+.4f)"
                      % (w * 100, (1 - w) * 100, n, gain))
            self.apply_btn.setEnabled(True)
        else:
            stats += ("\n⚖️ 实盘权重学习:结算且含双源概率的记录满 %d 条后可用"
                      % LEARN_MIN_SAMPLES)
            self.apply_btn.setEnabled(False)
        self.stats_lbl.setText(stats.replace("\n", "<br>"))
        recent = list(reversed(records))[:80]
        self.ed.setPlainText("\n".join(log_line(r) for r in recent)
                             or "暂无记录。生成推荐后点「记入日志」。")

    def on_apply_weight(self):
        if self._learned and hasattr(self.parent(), "apply_learned_weight"):
            w, n, _ = self._learned
            self.parent().apply_learned_weight(w, n)
            QMessageBox.information(self, "权重",
                                    "已应用:模型 %.0f%% / 市场 %.0f%%。\n"
                                    "之后所有推荐与角标都按新权重融合,"
                                    "关闭应用自动保存。" % (w * 100, (1 - w) * 100))

    def on_reconcile(self):
        if self.rec_thread and self.rec_thread.isRunning():
            return
        self.rec_btn.setEnabled(False)
        self.clr_btn.setEnabled(False)        # 对账期间禁清空,避免结果覆盖竞态
        # 线程挂到长生命周期的竞彩主窗口:对话框中途关闭不会销毁运行中线程
        owner = self.parent() or self
        self.rec_thread = ReconcileThread(self.token, self.log.load(), owner)
        self.rec_thread.done.connect(self.on_reconcile_done)
        self.rec_thread.start()

    def on_reconcile_done(self, records: list, msg: str):
        self.rec_btn.setEnabled(True)
        self.clr_btn.setEnabled(True)
        self.log.save(records)
        self.refresh()
        QMessageBox.information(self, "对账", msg)

    def on_export(self):
        records = self.log.load()
        path = os.path.join(os.path.expanduser("~"), "竞彩日志_%s.txt"
                            % datetime.now().strftime("%Y%m%d_%H%M"))
        try:
            with open(path, "w", encoding="utf-8") as f:
                f.write(log_stats(records) + "\n\n")
                f.write("\n".join(log_line(r) for r in reversed(records)))
            QMessageBox.information(self, "导出成功", "已保存到:\n%s" % path)
        except OSError as e:
            QMessageBox.warning(self, "导出失败", str(e))

    def on_clear(self):
        if QMessageBox.question(self, "清空日志", "确定删除全部预测记录?") \
                == QMessageBox.Yes:
            self.log.save([])
            self.refresh()


