# 主窗口
# =========================================================================== #
class JingcaiWindow(QMainWindow):
    def __init__(self):
        super().__init__()
        self.setWindowTitle(APP_TITLE)
        self.resize(420, 780)        # 竖屏比例
        self.numbered = []           # 全量 [(no, ev)]
        self.visible = []            # 过滤后 [(no, ev)]
        self.fetch_thread = None
        self.hist_thread = None
        self.models = {}             # {league_name: LeagueModel}
        self.plog = PredictionLog()
        self._last_rec = None        # (adv, ev, model_probs) 最近一次单场推荐
        self.w_model = 0.50          # 融合权重:模型占比(实盘学习可更新)
        self._build_ui()
        self._apply_style()
        self._load_config()
        self._refresh_list()      # 欢迎页

    # ----- 配置持久化 ----- #
    def _load_config(self):
        try:
            with open(CONFIG_PATH, "r", encoding="utf-8") as f:
                cfg = json.load(f)
        except (OSError, ValueError):
            return
        if cfg.get("token"):
            self.token_edit.setText(str(cfg["token"]))
        if isinstance(cfg.get("days"), int):
            self.days_spin.setValue(cfg["days"])
        if isinstance(cfg.get("hist_days"), int):
            self.hist_spin.setValue(cfg["hist_days"])
        self.auto_chk.setChecked(bool(cfg.get("auto_model", True)))
        self.injadj_chk.setChecked(bool(cfg.get("injury_adjust", True)))
        try:
            self.w_model = max(0.0, min(1.0, float(cfg.get("w_model", 0.50))))
        except (TypeError, ValueError):
            pass

    def _save_config(self):
        try:
            os.makedirs(os.path.dirname(CONFIG_PATH), exist_ok=True)
            with open(CONFIG_PATH, "w", encoding="utf-8") as f:
                json.dump({"token": self.token_edit.text(),
                           "days": self.days_spin.value(),
                           "hist_days": self.hist_spin.value(),
                           "auto_model": self.auto_chk.isChecked(),
                           "injury_adjust": self.injadj_chk.isChecked(),
                           "w_model": self.w_model},
                          f, ensure_ascii=False)
        except OSError:
            pass

    def closeEvent(self, e):
        self._save_config()
        super().closeEvent(e)

