# 自检(逻辑离线)
# =========================================================================== #
def _jingcai_selftest():
    assert cn_team("Manchester City") == "曼城"
    assert cn_team("Málaga CF") == "马拉加"
    assert cn_team("FC Tampa Bay Rowdies") == "FC Tampa Bay Rowdies"
    assert cn_league("Premier League") == "英超"
    assert cn_league("USL Championship") == "美冠联"
    assert cn_league("FIFA World Cup 2026") == "世界杯"
    assert is_world_cup("FIFA World Cup 2026") and not is_world_cup("Premier League")

    m = implied_from_odds(2.10, 3.30, 3.60)
    assert m and abs(m["home"] + m["draw"] + m["away"] - 1.0) < 1e-9
    assert implied_from_odds(1.0, 3.0, 3.0) is None
    assert kelly_fraction(0.3, 2.0) == 0.0
    assert kelly_fraction(0.9, 5.0) == DEFAULT_KELLY_CAP

    # UTC → 本机时区换算
    ev = {"event_date": "2026-06-13T19:00:00+00:00"}
    dt = ev_dt(ev)
    assert dt is not None and dt.tzinfo is not None
    from datetime import timezone
    assert dt == datetime(2026, 6, 13, 19, 0, tzinfo=timezone.utc)  # 同一时刻
    ev2 = {"event_date": "2026-06-13T19:00:00Z"}
    assert ev_dt(ev2) == dt

    ev3 = {"event_date": "2026-06-13T19:00:00+00:00", "home_team": "Manchester City",
           "away_team": "Arsenal", "league": "Premier League",
           "odds_home": 2.05, "odds_draw": 3.40, "odds_away": 3.80,
           "unavailable_players": {
               "home": [{"name": "E. Haaland", "status": "injured",
                         "reason": "Muscle Injury", "expected_return": "2026-06-24"}],
               "away": None}}
    assert ev_odds(ev3)["odds_home"] == 2.05
    inj = ev_injuries(ev3)
    assert len(inj["home"]) == 1 and inj["away"] == []

    numbered = assign_match_numbers([
        {"event_date": "2026-06-13T19:00:00+00:00"},
        {"event_date": "2026-06-13T15:00:00+00:00"},
        {"event_date": ""}])
    assert numbered[0][0].endswith("001") and numbered[1][0].endswith("002") \
        or numbered[0][0][:2] != numbered[1][0][:2]   # 跨本地日期时允许分属两天
    assert numbered[2][0] == ""

    adv = recommend_match("Manchester City", "Arsenal",
                          model_probs={"home": .58, "draw": .24, "away": .18},
                          odds={"odds_home": 2.05, "odds_draw": 3.40,
                                "odds_away": 3.80},
                          match_no="周六001", home_cn="曼城", away_cn="阿森纳")
    assert adv.best.outcome == "home" and adv.best.level == "推荐"
    assert adv.title == "周六001  曼城 vs 阿森纳"

    # --- 内置泊松模型 --- #
    import random
    random.seed(42)
    true_att = {"A": 1.6, "B": 1.0, "C": 0.6}
    true_def = {"A": 0.7, "B": 1.0, "C": 1.4}
    ms = []
    for rnd in range(40):
        for h in true_att:
            for a in true_att:
                if h == a:
                    continue
                lh = 1.30 * true_att[h] * true_def[a] * 1.30
                la = 1.30 * true_att[a] * true_def[h]
                hs = sum(random.random() < lh / 6 for _ in range(6))
                as_ = sum(random.random() < la / 6 for _ in range(6))
                ms.append((h, a, hs, as_, rnd * 2))
    lm = LeagueModel()
    assert lm.fit(ms)
    assert lm.att["A"] > lm.att["B"] > lm.att["C"]
    assert lm.deff["A"] < lm.deff["B"] < lm.deff["C"]
    lh, la = lm.lambdas("A", "C")
    pw, pd_, pl, po = score_probs(lh, la)
    assert pw > 0.6 and abs(pw + pd_ + pl - 1.0) < 1e-9 and 0 < po < 1
    assert lm.lambdas("A", "未知队") is None
    assert LeagueModel().fit([("A", "B", 1, 0, 0)]) is False   # 数据不足

    # 伤停修正:2 确定 + 1 疑似 → ×0.90;下限 0.70
    recs = [("x", "injured", "", ""), ("y", "suspended", "", ""),
            ("z", "doubtful", "", "")]
    assert abs(injury_factor(recs) - 0.90) < 1e-9
    assert injury_factor([("p", "injured", "", "")] * 20) == 0.70
    assert injury_factor([]) == 1.0

    assert judge_level(0.55, 0.08) == "推荐"
    assert judge_level(0.20, 0.10) == "观望"     # 概率低于下限
    assert judge_level(0.55, -0.02) == "回避"

    assert ev_is_finished({"home_score": 2, "away_score": "1"})
    assert not ev_is_finished({"home_score": None, "away_score": 1})

    # --- v5: DC ρ / xG 混合 / 回测 --- #
    pw0, pd0, pl0, _ = score_probs(1.4, 1.1, 0.0)
    pwr, pdr, plr, _ = score_probs(1.4, 1.1, -0.10)
    assert abs(pwr + pdr + plr - 1.0) < 1e-9          # ρ 修正后仍归一
    assert pdr != pd0                                  # ρ 确实改变平局概率
    assert -0.25 <= lm.rho <= 0.25                     # 网格搜索范围内
    assert lm.predict("A", "C") is not None and lm.predict("A", "未知队") is None

    bg = blended_goals({"home_score": 2, "away_score": 0,
                        "actual_home_xg": 1.0, "actual_away_xg": 1.5})
    assert abs(bg[0] - (0.6 * 2 + 0.4 * 1.0)) < 1e-9 and bg[2] == 2 and bg[3] == 0
    bg2 = blended_goals({"home_score": 1, "away_score": 1})   # 无 xG 回退原始
    assert bg2 == (1.0, 1.0, 1, 1)
    assert blended_goals({"home_score": None, "away_score": 1}) is None

    ms7 = [(h, a, hs, as_, d, int(round(hs)), int(round(as_)))
           for h, a, hs, as_, d in ms]
    hits, n = backtest(ms7)
    assert n > 0 and hits / n > 0.40                   # 合成强弱分明数据应高于随机

    # --- v7: 预测日志 --- #
    import tempfile
    recs = [
        {"event_id": 1, "pick": "home", "odds": 2.0, "level": "推荐",
         "settled": False, "match_time": "2026-06-10T19:00:00+08:00",
         "no": "周三001", "home_cn": "甲", "away_cn": "乙", "pick_cn": "主胜",
         "ev": 0.07, "pnl": 0.0},
        {"event_id": 2, "pick": "away", "odds": 3.0, "level": "观望",
         "settled": False, "match_time": "2026-06-10T21:00:00+08:00",
         "no": "周三002", "home_cn": "丙", "away_cn": "丁", "pick_cn": "客胜",
         "ev": 0.02, "pnl": 0.0},
    ]
    idx = {1: {"home_score": 2, "away_score": 1},      # 主胜 → 命中
           2: {"home_score": 1, "away_score": 1}}      # 平 → 未中
    assert settle_records(recs, idx) == 2
    assert recs[0]["hit"] is True and abs(recs[0]["pnl"] - 1.0) < 1e-9
    assert recs[1]["hit"] is False and recs[1]["pnl"] == -1.0
    assert settle_records(recs, idx) == 0              # 二次结算不重复
    st = log_stats(recs)
    assert "已结算 2" in st and "50.0%" in st and "[推荐]" in st
    assert "✓" in log_line(recs[0]) and "✗" in log_line(recs[1])
    assert "待开赛" in log_line({"settled": False, "odds": 2.0, "ev": 0.0})

    with tempfile.TemporaryDirectory() as tdir:
        pl = PredictionLog(os.path.join(tdir, "log.json"))
        assert pl.load() == []
        assert pl.add(dict(recs[0], settled=False))
        assert pl.add(dict(recs[0], settled=False, odds=2.10))   # 同场未结算覆盖
        data = pl.load()
        assert len(data) == 1 and data[0]["odds"] == 2.10
        data[0]["settled"] = True
        pl.save(data)
        assert pl.add(dict(recs[0], settled=False))    # 已结算不覆盖 → 追加
        assert len(pl.load()) == 2

    # --- v8: 实盘权重学习 --- #
    import random as _r
    _r.seed(3)
    def mk(outcome, mp, mk_):
        return {"settled": True, "outcome": outcome,
                "model_probs": mp, "market_probs": mk_}
    # 模型几乎总对、市场均匀 → w 应趋近 1
    good = []
    for _ in range(60):
        o = _r.choice(["home", "draw", "away"])
        mp = [0.1, 0.1, 0.1]; mp[{"home":0,"draw":1,"away":2}[o]] = 0.8
        good.append(mk(o, mp, [1/3, 1/3, 1/3]))
    w, n, gain = learn_weight(good)
    assert w >= 0.9 and n == 60 and gain > 0
    # 模型瞎猜、市场准 → w 应趋近 0,且提升≈0
    bad = []
    for _ in range(60):
        o = _r.choice(["home", "draw", "away"])
        mk_p = [0.1, 0.1, 0.1]; mk_p[{"home":0,"draw":1,"away":2}[o]] = 0.8
        mp = [1/3, 1/3, 1/3]
        bad.append(mk(o, mp, mk_p))
    w2, _, gain2 = learn_weight(bad)
    assert w2 <= 0.1 and gain2 <= 1e-9
    assert learn_weight(good[:10]) is None             # 样本不足
    # 旧版记录(无双源概率)被安全跳过
    assert learn_weight(good[:20] + [{"settled": True, "outcome": "home"}] * 50) is None
    # make_log_record 含双源概率
    a8 = recommend_match("Manchester City", "Arsenal",
                         model_probs={"home": .58, "draw": .24, "away": .18},
                         odds={"odds_home": 2.05, "odds_draw": 3.40,
                               "odds_away": 3.80}, match_no="周六001",
                         home_cn="曼城", away_cn="阿森纳")
    r8 = make_log_record(a8, {"id": 9, "event_date": "2026-06-13T11:00:00+00:00",
                              "odds_home": 2.05, "odds_draw": 3.40,
                              "odds_away": 3.80, "league": "Premier League"},
                         model_probs={"home": .58, "draw": .24, "away": .18})
    assert r8 and len(r8["model_probs"]) == 3 and len(r8["market_probs"]) == 3
    assert abs(sum(r8["market_probs"]) - 1.0) < 1e-3
    print("逻辑自检通过")


def _v106_get_window(self):
    win = getattr(self, "_jingcai_win", None)
    if win is None:
        win = JingcaiWindow()
        self._jingcai_win = win
        try:
            app = QApplication.instance()
            if app is not None:
                app.aboutToQuit.connect(win._save_config)
        except Exception:
            pass
    return win


def _v106_open_jingcai(self):
    try:
        win = _v106_get_window(self)
        for tw in self.findChildren(QTabWidget):
            idx = tw.indexOf(win)
            if idx >= 0:
                tw.setCurrentIndex(idx)
                return
        win.show()
        win.raise_()
        win.activateWindow()
    except Exception:
        try:
            QMessageBox.warning(self, "竞彩",
                                "竞彩模块启动失败:\n" + traceback.format_exc())
        except Exception:
            pass


def _v106_add_tab(self):
    tabs = None
    for tw in self.findChildren(QTabWidget):
        for i in range(tw.count()):
            if "首页" in tw.tabText(i):
                tabs = tw
                break
        if tabs is not None:
            break
    if tabs is None:
        return False
    win = _v106_get_window(self)
    if tabs.indexOf(win) >= 0:
        return True
    pos = tabs.count()
    for i in range(tabs.count()):
        if "体彩" in tabs.tabText(i):
            pos = i + 1
            break
    tabs.insertTab(pos, win, "⚽ 竞彩")
    return True


def _v106_find_layout_of(widget):
    pw = widget.parentWidget()
    if not pw or not pw.layout():
        return None
    stack = [pw.layout()]
    while stack:
        lay = stack.pop()
        for i in range(lay.count()):
            it = lay.itemAt(i)
            if it is None:
                continue
            if it.widget() is widget:
                return lay
            if it.layout():
                stack.append(it.layout())
    return None


def _v106_inject_button(self):
    """向首页工具行注入「⚽ 竞彩足球」按钮。

    防重与锚点都限定在【最新构建的首页】内:首页可能被多次重建且
    旧页面未销毁,全窗口文本探测会被陈旧按钮误判为已注入,导致
    新页面永远缺按钮。取最后一个「扫码查奖」(创建顺序=最新页)。"""
    root = getattr(self, "home_tab", None) or self
    anchors = [b for b in root.findChildren(QPushButton)
               if "扫码查奖" in b.text()]
    if not anchors:
        return False
    anchor = anchors[-1]
    host = anchor.parentWidget()
    if host is not None:
        for b in host.findChildren(QPushButton):
            if "竞彩足球" in b.text():
                return True
    lay = _v106_find_layout_of(anchor)
    if lay is None:
        return False
    jc_btn = QPushButton("⚽ 竞彩足球")
    jc_btn.setToolTip("竞彩足球推荐:赔率+伤停+泊松模型融合分析,实盘日志追踪")
    jc_btn.setStyleSheet(
        "QPushButton{background:#1e8e3e;color:white;font-weight:bold;"
        "border-radius:6px;padding:6px 10px;border-bottom:3px solid #d4af37;}"
        "QPushButton:hover{background:#136a2d;}")
    jc_btn.clicked.connect(self.open_jingcai)
    lay.addWidget(jc_btn)
    return True


def _v106_ensure_entry(self, tries=15):
    try:
        _v106_add_tab(self)
        _v106_inject_button(self)
    except Exception:
        try:
            logger.warning("V106竞彩入口注入异常:\n" + traceback.format_exc())
        except Exception:
            pass
    if tries > 0:
        try:
            QTimer.singleShot(800, lambda: _v106_ensure_entry(self, tries - 1))
        except Exception:
            pass


def _v106_wrap_init_home_tab(old_func):
    """V98 同款:首页每次构建后立即注入竞彩按钮(确定性入口)。"""
    def wrapper(self, *args, **kwargs):
        result = old_func(self, *args, **kwargs)
        try:
            _v106_inject_button(self)
        except Exception:
            try:
                logger.debug("V106首页竞彩按钮注入失败:\n" + traceback.format_exc())
            except Exception:
                pass
        return result
    wrapper._v106_wrapped = True
    return wrapper


def _v106_wrap_init_ui(old_func):
    def wrapper(self, *args, **kwargs):
        result = old_func(self, *args, **kwargs)
        try:
            _v106_ensure_entry(self)
        except Exception:
            pass
        return result
    wrapper._v106_wrapped = True
    return wrapper


