# ============================================================
# V107 PATCH BEGIN —— 全量历史更新完整性保障(所有玩法不漏期)
# 问题根因:
#   增量提前停止策略(连续3页本地已有即停)会永久跳过"深处历史缺口"
#   ——若本地数据是"顶部最新完整 + 早年大段缺失"(此前抓取中断/上限
#   截断造成),增量更新永远走不到缺口处;且抓完从不校验接口侧总数,
#   缺了多少无人知晓。极速API与福建 huiniao 两条路径同病。
# 修复方案(两遍式 + 总数校验):
#   ① 第一遍仍走增量(快,跳过已有);
#   ② 探测接口侧总期数(极速 result.total;福建 limit=1 时
#      totalPage 即总条数);
#   ③ 本地条数 + 容差 < 接口总数 → 判定有缺口,自动对该玩法
#      强制全量重抓(existing_rows=None,无提前停止),合并补齐;
#   ④ 复核并在报告中标注每个玩法的 本地/接口 完整性结论;
#   ⑤ 每玩法抓完即原子保存(沿用 V89),中断不丢已抓数据。
# ============================================================

V107_GAP_TOLERANCE = 2   # 接口总数可能含当期未开奖等浮动,≤2 期视为完整


def _v107_probe_total(game, key=""):
    """探测接口侧该玩法的历史总期数;失败返回 None(跳过校验)。"""
    try:
        game = _v98_norm_game(game)
        if game in V98_FUJIAN_GAMES:
            typ = V94_FUJIAN_TYPE_MAP.get(game)
            if not typ:
                return None
            params = {"type": typ, "page": 1, "limit": 1}
            for url in V94_HUINIAO_HISTORY_URLS:
                data, raw, err, _fu = _v89_request_json_with_retry(
                    url, params, retries=2, timeout=15)
                if err is None and isinstance(data, dict) \
                        and str(data.get("code")) != "401":
                    tp = _v94_extract_total_page(data)
                    if tp:
                        return int(tp)        # limit=1 → totalPage == 总条数
            return None
        cid = None
        try:
            cid = JISUAPI_CONFIG.get("lottery_id_map", {}).get(game)
        except Exception:
            cid = None
        if cid in (None, "", 0, "0") or not key:
            return None
        data, raw, err, _fu = _v89_request_json_with_retry(
            "https://api.jisuapi.com/caipiao/history",
            {"appkey": key, "caipiaoid": cid, "issueno": "", "start": 0,
             "num": 1}, retries=2, timeout=15)
        if err or not isinstance(data, dict) or str(data.get("status")) != "0":
            return None
        result = data.get("result")
        if not isinstance(result, dict):
            return None
        t = result.get("total")
        return int(t) if t else None
    except Exception:
        return None


def _v107_fetch_one(self, game, key, max_per_game, existing_rows, _p):
    """单玩法抓取(existing_rows=None 即强制全量)。返回 (rows, msg)。"""
    game = _v98_norm_game(game)
    if game in V98_FUJIAN_GAMES:
        return _v98_fetch_fujian_history(game, max_records=max_per_game,
                                         progress_cb=_p,
                                         existing_rows=existing_rows)
    if not key:
        return [], "未读取到极速API密钥"
    cid = None
    try:
        cid = JISUAPI_CONFIG.get("lottery_id_map", {}).get(game)
    except Exception:
        cid = None
    if cid in (None, "", 0, "0"):
        return [], "缺少极速API玩法ID"
    return _v89_direct_fetch_history(game, cid, key, max_records=max_per_game,
                                     progress_cb=_p,
                                     existing_rows=existing_rows)


def _v107_full_history_thread_run(self):
    """全量线程 V107:增量加速 + 接口总数校验 + 缺口自动强制全量补抓。"""
    try:
        key = ""
        try:
            key = _v42_read_jisu_key()
        except Exception:
            key = ""
        if not key:
            try:
                key = (getattr(self, "_key", "")
                       or getattr(getattr(self, "app", None), "jisuapi_key", "")
                       or getattr(getattr(self, "app", None), "api_key", "")
                       or "").strip()
            except Exception:
                key = ""

        games = _v98_game_list(getattr(self, "games", None))
        old = _v42_load_existing_history()
        if not isinstance(old, dict):
            old = {}
        report, total_new = [], 0
        total = len(games)
        max_per_game = int(getattr(self, "max_per_game", 200000) or 200000)

        for idx, game in enumerate(games):
            if getattr(self, "_cancel", False):
                report.append("用户取消全量更新")
                break
            game = _v98_norm_game(game)

            def _p(text, _idx=idx, _total=total):
                try:
                    self.progress.emit(_idx, _total, text)
                except Exception:
                    pass

            _p(f"[{idx+1}/{total}] 正在更新 {game} …")
            before = len(old.get(game, [])
                         if isinstance(old.get(game, []), list) else [])

            # ── 第一遍:增量 ──
            try:
                rows, msg = _v107_fetch_one(self, game, key, max_per_game,
                                            old.get(game, []), _p)
            except Exception as e:
                rows, msg = [], str(e)
            if rows:
                try:
                    old[game] = _v89_merge_records(old.get(game, []), rows)
                except Exception:
                    old[game] = list(rows)

            # ── 完整性校验 ──
            local_n = len(old.get(game, [])
                          if isinstance(old.get(game, []), list) else [])
            verdict = ""
            if rows or before:
                api_total = _v107_probe_total(game, key)
                if api_total and local_n + V107_GAP_TOLERANCE < api_total:
                    gap = api_total - local_n
                    _p(f"{game}:检测到历史缺口 {gap} 期"
                       f"(本地{local_n}/接口{api_total}),强制全量补抓…")
                    if not getattr(self, "_cancel", False):
                        try:
                            rows2, msg2 = _v107_fetch_one(
                                self, game, key, max_per_game, None, _p)
                        except Exception as e:
                            rows2, msg2 = [], str(e)
                        if rows2:
                            try:
                                old[game] = _v89_merge_records(
                                    old.get(game, []), rows2)
                            except Exception:
                                pass
                            rows = rows or rows2
                        local_n = len(old.get(game, []))
                        if local_n + V107_GAP_TOLERANCE >= api_total:
                            verdict = (f";完整性:✅已补齐"
                                       f"(本地{local_n}/接口{api_total})")
                        else:
                            verdict = (f";完整性:⚠️补抓后仍缺"
                                       f"{api_total - local_n}期"
                                       f"(本地{local_n}/接口{api_total})"
                                       f",提示:{msg2}")
                elif api_total:
                    verdict = f";完整性:✅(本地{local_n}/接口{api_total})"
                else:
                    verdict = ";完整性:接口未提供总数,跳过校验"

            after = len(old.get(game, [])
                        if isinstance(old.get(game, []), list) else [])
            added = max(0, after - before)
            total_new += added
            try:
                if hasattr(self, "app"):
                    self.app.history_data = old
            except Exception:
                pass
            ok_msg = any(t in str(msg) for t in ("ok", "已最新", "已是最新"))
            if rows or added or (before and ok_msg):
                try:
                    self.game_done.emit(game, len(rows), added, after)
                except Exception:
                    pass
                suffix = "" if msg == "ok" else f";提示:{msg}"
                report.append(f"{game}: ✅ 新增{added}期,本地共{after}期"
                              f"{suffix}{verdict}")
            else:
                report.append(f"{game}: ❌ {msg}{verdict}")
            try:
                _v89_save_all_history(old)      # 每玩法原子保存,断点不丢
            except Exception as e:
                report.append(f"{game}: ⚠️ 保存失败 {e}")
            try:
                import time as _time
                _time.sleep(1.5 if game in V98_FUJIAN_GAMES else 0.5)
            except Exception:
                pass

        try:
            if hasattr(self, "app"):
                self.app.history_data = old
        except Exception:
            pass
        try:
            self.progress.emit(total, total, "历史更新完成,正在刷新界面…")
        except Exception:
            pass
        try:
            self.all_finished.emit(total_new, report)
        except Exception:
            pass
    except Exception as e:
        logger.error(f"V107全量历史线程异常: {e}", exc_info=True)
        try:
            self.error.emit(str(e))
        except Exception:
            pass


def _v107_install_patch():
    if "FullHistoryFetchThread" in globals():
        FullHistoryFetchThread.run = _v107_full_history_thread_run
    try:
        logger.info("V107补丁已安装:全量更新两遍式补抓+接口总数校验,所有玩法不漏期")
    except Exception:
        pass


try:
    _v107_install_patch()
except Exception:
    try:
        logger.warning("V107补丁安装失败:\n" + traceback.format_exc())
    except Exception:
        pass
