# ============================================================
# V108 PATCH BEGIN —— 全玩法智能胆码生成器
# 覆盖:福彩(双色球/快乐8/七乐彩/3D) + 体彩(大乐透/排列三/
#       排列五/七星彩) + 福建地方彩(36选7/31选7/22选5)
# 能力:① 生成前可联网抓取最新开奖(极速API/huiniao,增量+保存)
#       ② AI 四信号综合评分:近期加权频率(时间衰减)/长期频率/
#          遗漏回补压力/重邻号动量 → 逐号打分选胆
#       ③ 乐透型选主区胆码(1-5个+备选);位置型逐位选胆
#       ④ 近30期滚动回测,如实报告"至少中1胆"命中率
# 入口:首页工具行「🎯 智能胆码」(LotteryApp.open_dan_generator)
# ============================================================

V108_GAMES = {
    # 乐透型: max=主区最大号, need=主区个数, has_plus=开奖串含'+'后区
    "双色球":     {"type": "lotto", "max": 33, "need": 6,  "has_plus": True},
    "大乐透":     {"type": "lotto", "max": 35, "need": 5,  "has_plus": True},
    "快乐8":      {"type": "lotto", "max": 80, "need": 20, "has_plus": False},
    "七乐彩":     {"type": "lotto", "max": 30, "need": 7,  "has_plus": True},
    "福建36选7":  {"type": "lotto", "max": 36, "need": 6,  "has_plus": True},
    "福建31选7":  {"type": "lotto", "max": 31, "need": 7,  "has_plus": True},
    "福建22选5":  {"type": "lotto", "max": 22, "need": 5,  "has_plus": False},
    # 位置型: pos=位数,每位 0-9
    "3D":        {"type": "digit", "pos": 3},
    "排列三":     {"type": "digit", "pos": 3},
    "排列五":     {"type": "digit", "pos": 5},
    "七星彩":     {"type": "digit", "pos": 7},
}
V108_FUCAI = ["双色球", "快乐8", "七乐彩", "3D"]
V108_TICAI = ["大乐透", "排列三", "排列五", "七星彩"]
V108_FJ = ["福建36选7", "福建31选7", "福建22选5"]
V108_ALL = V108_FUCAI + V108_TICAI + V108_FJ


def _v108_issue_key(rec):
    try:
        return int(re.sub(r"\D", "", str(rec.get("期号", ""))) or 0)
    except Exception:
        return 0


def _v108_parse_main(game, s):
    """从开奖号码串解析主区号码(乐透)或逐位数字(位置型);失败 None。"""
    cfg = V108_GAMES.get(game)
    if not cfg:
        return None
    s = str(s or "").strip()
    if not s:
        return None
    if cfg["type"] == "digit":
        nums = [int(x) for x in re.findall(r"\d+", s)]
        if len(nums) == cfg["pos"] and all(0 <= n <= 9 for n in nums):
            return nums
        digits = [int(c) for c in re.sub(r"\D", "", s)]
        return digits[:cfg["pos"]] if len(digits) >= cfg["pos"] else None
    part = s.split("+")[0] if (cfg.get("has_plus") and "+" in s) else s
    nums = [int(x) for x in re.findall(r"\d+", part)]
    nums = [n for n in nums if 1 <= n <= cfg["max"]]
    if len(nums) < cfg["need"]:
        return None
    return nums[:cfg["need"]]


def _v108_parsed_history(game, records):
    """返回按期号从新到旧排序的已解析主区列表。"""
    rows = [r for r in (records or []) if isinstance(r, dict)]
    rows.sort(key=_v108_issue_key, reverse=True)
    out = []
    for r in rows:
        p = _v108_parse_main(game, r.get("开奖号码", ""))
        if p:
            out.append(p)
    return out


def _v108_z(d):
    vals = list(d.values())
    if not vals:
        return {}
    mean = sum(vals) / len(vals)
    var = sum((v - mean) ** 2 for v in vals) / max(1, len(vals))
    sd = var ** 0.5 or 1.0
    return {k: (v - mean) / sd for k, v in d.items()}


def _v108_lotto_scores(parsed, cfg, recent_n=30, long_n=200, decay=0.93):
    """乐透型逐号综合评分。返回 [(号码, 总分, 明细dict)] 降序。"""
    mx, need = cfg["max"], cfg["need"]
    nums = list(range(1, mx + 1))
    rec, lng = parsed[:recent_n], parsed[:long_n]
    wfreq = {n: 0.0 for n in nums}
    w = 1.0
    for draw in rec:
        s = set(draw)
        for n in nums:
            if n in s:
                wfreq[n] += w
        w *= decay
    lfreq = {n: 0 for n in nums}
    for draw in lng:
        for n in set(draw):
            if n in lfreq:
                lfreq[n] += 1
    omit = {}
    for n in nums:
        o = len(parsed)
        for i, draw in enumerate(parsed):
            if n in draw:
                o = i
                break
        omit[n] = o
    exp_gap = max(1.0, mx / float(need))          # 理论平均间隔
    press = {n: min(omit[n] / exp_gap, 3.0) / 3.0 for n in nums}
    last = set(parsed[0]) if parsed else set()
    nb = {n: (1.0 if n in last else (0.5 if (n - 1 in last or n + 1 in last)
                                     else 0.0)) for n in nums}
    zw, zl = _v108_z(wfreq), _v108_z(lfreq)
    out = []
    for n in nums:
        score = 0.40 * zw.get(n, 0) + 0.20 * zl.get(n, 0) \
                + 0.25 * (press[n] * 2 - 1) + 0.15 * (nb[n] * 2 - 1)
        out.append((n, score, {"近%d期" % recent_n: sum(1 for d in rec if n in d),
                               "长期%d" % len(lng): lfreq[n],
                               "遗漏": omit[n], "重邻": nb[n] >= 0.5}))
    out.sort(key=lambda t: -t[1])
    return out


def _v108_digit_scores(parsed, cfg, recent_n=50, decay=0.95):
    """位置型:每位返回 [(数字, 分, 明细)] 降序的列表。"""
    pos = cfg["pos"]
    rec = parsed[:recent_n]
    result = []
    for p in range(pos):
        wfreq = {d: 0.0 for d in range(10)}
        cnt = {d: 0 for d in range(10)}
        w = 1.0
        for draw in rec:
            if p < len(draw):
                wfreq[draw[p]] += w
                cnt[draw[p]] += 1
            w *= decay
        omit = {}
        for d in range(10):
            o = len(parsed)
            for i, draw in enumerate(parsed):
                if p < len(draw) and draw[p] == d:
                    o = i
                    break
            omit[d] = o
        press = {d: min(omit[d] / 10.0, 3.0) / 3.0 for d in range(10)}
        zw = _v108_z(wfreq)
        scored = [(d, 0.60 * zw.get(d, 0) + 0.40 * (press[d] * 2 - 1),
                   {"近%d期" % len(rec): cnt[d], "遗漏": omit[d]})
                  for d in range(10)]
        scored.sort(key=lambda t: -t[1])
        result.append(scored)
    return result


V108_MAX_ANALYZE = 400   # 统计/回测只看近400期:更早数据无统计价值且拖慢手机


def _v108_generate(game, records, k=3):
    """生成胆码。返回 dict 或 None(数据不足)。"""
    cfg = V108_GAMES.get(game)
    parsed = _v108_parsed_history(game, records)[:V108_MAX_ANALYZE]
    if not cfg or len(parsed) < 20:
        return None
    if cfg["type"] == "lotto":
        k = max(1, min(int(k or 3), 5, cfg["need"] - 1)) if cfg["need"] > 1 else 1
        scored = _v108_lotto_scores(parsed, cfg)
        return {"type": "lotto", "game": game, "n_hist": len(parsed),
                "dans": scored[:k], "alts": scored[k:k + k],
                "k": k}
    per_pos = _v108_digit_scores(parsed, cfg)
    return {"type": "digit", "game": game, "n_hist": len(parsed),
            "positions": [(p + 1, lst[0], lst[1]) for p, lst in
                          enumerate(per_pos)]}


def _v108_backtest(game, records, k=3, window=30):
    """滚动回测:对最近 window 期,各用其之前的历史生成胆码再对答案。
    乐透:返回 (至少中1胆比例, 平均命中胆数, 样本);
    位置:返回 (至少中1位比例, 平均命中位数, 样本)。"""
    cfg = V108_GAMES.get(game)
    parsed = _v108_parsed_history(game, records)[:V108_MAX_ANALYZE]
    if not cfg or len(parsed) < 40:
        return None
    n = min(window, len(parsed) - 30)
    hit1 = 0
    tot_hits = 0.0
    for i in range(n):
        train, target = parsed[i + 1:], parsed[i]
        if cfg["type"] == "lotto":
            kk = max(1, min(int(k or 3), 5, cfg["need"] - 1))
            dans = [t[0] for t in _v108_lotto_scores(train, cfg)[:kk]]
            hits = len(set(dans) & set(target))
        else:
            per = _v108_digit_scores(train, cfg)
            hits = sum(1 for p, lst in enumerate(per)
                       if p < len(target) and lst[0][0] == target[p])
        hit1 += (hits >= 1)
        tot_hits += hits
    return (hit1 / n, tot_hits / n, n)


class V108DanWorker(QThread):
    """可选联网更新最新开奖 → 生成胆码 + 回测。"""
    done = Signal(dict)

    def __init__(self, app_ref, game, k, fetch_online, parent=None):
        super().__init__(parent)
        self.app_ref, self.game, self.k = app_ref, game, int(k)
        self.fetch_online = bool(fetch_online)

    def run(self):
        out = {"game": self.game, "fetched": 0, "fetch_msg": "未联网(使用本地历史)"}
        try:
            hist = getattr(self.app_ref, "history_data", {}) or {}
            records = list(hist.get(self.game, []) or [])
            if self.fetch_online:
                try:
                    key = ""
                    try:
                        key = _v42_read_jisu_key()
                    except Exception:
                        key = ""
                    if not key:
                        key = (getattr(self.app_ref, "jisuapi_key", "")
                               or getattr(self.app_ref, "api_key", "") or "").strip()
                    rows, msg = _v107_fetch_one(self, self.game, key, 200000,
                                                records, lambda *_a: None)
                    if rows:
                        merged = _v89_merge_records(records, rows)
                        added = max(0, len(merged) - len(records))
                        records = merged
                        hist[self.game] = merged
                        try:
                            self.app_ref.history_data = hist
                            # 以磁盘现状为基底合并保存,避免内存
                            # 部分加载时覆盖丢失其它玩法数据
                            base = _v42_load_existing_history()
                            if not isinstance(base, dict):
                                base = {}
                            base[self.game] = merged
                            _v89_save_all_history(base)
                        except Exception:
                            pass
                        out["fetched"] = added
                        out["fetch_msg"] = "✅ 已联网同步,新增 %d 期" % added
                    else:
                        out["fetch_msg"] = "联网未获新数据:%s" % msg
                except Exception as e:
                    out["fetch_msg"] = "联网失败,降级用本地历史:%s" % e
            res = _v108_generate(self.game, records, self.k)
            if not res:
                out["error"] = ("历史数据不足(已解析 %d 期,至少需要 20 期),"
                                "请先在数据更新中抓取该玩法历史。"
                                % len(_v108_parsed_history(self.game, records)))
                self.done.emit(out)
                return
            out.update(res)
            bt = _v108_backtest(self.game, records, self.k)
            if bt:
                out["backtest"] = bt
        except Exception as e:
            out["error"] = "生成失败:%s" % e
        self.done.emit(out)


class V108DanDialog(QDialog):
    """智能胆码生成器界面。"""

    def __init__(self, app_ref, parent=None):
        super().__init__(parent)
        self.app_ref = app_ref
        self.worker = None
        self.setWindowTitle("🎯 智能胆码生成器")
        self.resize(420, 620)
        lay = QVBoxLayout(self)

        row1 = QHBoxLayout()
        row1.addWidget(QLabel("玩法:"))
        self.game_combo = QComboBox()
        for g in V108_FUCAI:
            self.game_combo.addItem("【福彩】" + g, g)
        for g in V108_TICAI:
            self.game_combo.addItem("【体彩】" + g, g)
        for g in V108_FJ:
            self.game_combo.addItem("【福建】" + g, g)
        row1.addWidget(self.game_combo, 1)
        row1.addWidget(QLabel("胆数:"))
        self.k_spin = QSpinBox()
        self.k_spin.setRange(1, 5)
        self.k_spin.setValue(3)
        row1.addWidget(self.k_spin)
        lay.addLayout(row1)

        row2 = QHBoxLayout()
        self.online_chk = QCheckBox("联网抓取最新开奖后再分析(推荐)")
        self.online_chk.setChecked(True)
        row2.addWidget(self.online_chk, 1)
        self.gen_btn = QPushButton("🎯 生成胆码")
        self.gen_btn.setStyleSheet(
            "QPushButton{background:#1e8e3e;color:white;font-weight:bold;"
            "border-radius:8px;padding:8px 16px;}"
            "QPushButton:disabled{background:#b8c2cb;}")
        self.gen_btn.clicked.connect(self.on_generate)
        row2.addWidget(self.gen_btn)
        lay.addLayout(row2)

        self.status_lbl = QLabel("选择玩法后点「生成胆码」。AI 综合近期加权频率、"
                                 "长期频率、遗漏回补、重邻号动量四类信号评分选胆。")
        self.status_lbl.setWordWrap(True)
        self.status_lbl.setStyleSheet("color:#5a6772;")
        lay.addWidget(self.status_lbl)

        self.result_lbl = QLabel("")
        self.result_lbl.setWordWrap(True)
        self.result_lbl.setTextFormat(Qt.RichText)
        self.result_lbl.setAlignment(Qt.AlignTop)
        self.result_lbl.setStyleSheet("background:white;border:1px solid #d8e2d8;"
                                      "border-radius:10px;padding:10px;")
        sc = QScrollArea()
        sc.setWidgetResizable(True)
        sc.setFrameShape(QFrame.NoFrame)
        sc.setWidget(self.result_lbl)
        lay.addWidget(sc, 1)

        brow = QHBoxLayout()
        self.copy_btn = QPushButton("📋 复制胆码")
        self.copy_btn.setEnabled(False)
        self.copy_btn.clicked.connect(self.on_copy)
        brow.addWidget(self.copy_btn)
        cls = QPushButton("关闭")
        cls.clicked.connect(self.accept)
        brow.addWidget(cls)
        lay.addLayout(brow)
        self._copy_text = ""

        self.game_combo.currentIndexChanged.connect(self._sync_k)
        self._sync_k()

    def _sync_k(self):
        g = self.game_combo.currentData()
        is_lotto = V108_GAMES.get(g, {}).get("type") == "lotto"
        self.k_spin.setEnabled(is_lotto)

    @staticmethod
    def _ball(n, color):
        return ("<span style='display:inline-block;background:%s;color:white;"
                "border-radius:11px;padding:3px 9px;font-weight:bold;"
                "font-size:15px;'>%02d</span>" % (color, n))

    def on_generate(self):
        if self.worker and self.worker.isRunning():
            return
        game = self.game_combo.currentData()
        self.gen_btn.setEnabled(False)
        self.copy_btn.setEnabled(False)
        self.status_lbl.setText("正在%s分析 %s …"
                                % ("联网更新并" if self.online_chk.isChecked()
                                   else "", game))
        owner = self.app_ref if isinstance(self.app_ref, QObject) else self
        self.worker = V108DanWorker(self.app_ref, game, self.k_spin.value(),
                                    self.online_chk.isChecked(), owner)
        self.worker.done.connect(self.on_done)
        self.worker.start()

    def on_done(self, out: dict):
        self.gen_btn.setEnabled(True)
        if out.get("error"):
            self.status_lbl.setText("❌ " + out["error"])
            self.result_lbl.setText("")
            return
        self.status_lbl.setText("数据源:本地历史 %d 期 · %s"
                                % (out.get("n_hist", 0), out.get("fetch_msg", "")))
        rows = []
        if out.get("type") == "lotto":
            dans = out["dans"]
            self._copy_text = " ".join("%02d" % t[0] for t in dans)
            rows.append("<b>%s</b> 推荐胆码(%d 个):<br>%s" % (
                out["game"], out["k"],
                " ".join(self._ball(t[0], "#c5221f") for t in dans)))
            rows.append("备选:" + " ".join(self._ball(t[0], "#2962ff")
                                            for t in out.get("alts", [])))
            rows.append("<table width='100%' cellspacing='0' "
                        "style='font-size:12px'>"
                        "<tr style='background:#e7f0e7;font-weight:bold'>"
                        "<td>胆</td><td>评分</td><td>依据</td></tr>" +
                        "".join("<tr><td><b>%02d</b></td><td>%.2f</td>"
                                "<td>%s</td></tr>"
                                % (n, s, " · ".join("%s:%s" % (k2, v2)
                                                    for k2, v2 in d.items()))
                                for n, s, d in dans) + "</table>")
        else:
            pos = out["positions"]
            self._copy_text = " ".join(str(t[1][0]) for t in pos)
            rows.append("<b>%s</b> 逐位胆码:<br>%s" % (
                out["game"],
                " ".join("第%d位 %s(备%d)" % (p, self._ball(d1[0], "#c5221f"),
                                               d2[0])
                         for p, d1, d2 in pos)))
            rows.append("<table width='100%' cellspacing='0' "
                        "style='font-size:12px'>"
                        "<tr style='background:#e7f0e7;font-weight:bold'>"
                        "<td>位</td><td>胆</td><td>依据</td>"
                        "<td>备选</td></tr>" +
                        "".join("<tr><td>%d</td><td><b>%d</b></td><td>%s</td>"
                                "<td>%d</td></tr>"
                                % (p, d1[0], " · ".join("%s:%s" % (k2, v2)
                                                        for k2, v2 in
                                                        d1[2].items()), d2[0])
                                for p, d1, d2 in pos) + "</table>")
        bt = out.get("backtest")
        if bt:
            rate, avg, n = bt
            unit = "胆" if out.get("type") == "lotto" else "位"
            rows.append("<span style='color:#1b5e2f'>📊 近 %d 期滚动回测:"
                        "至少中1%s <b>%.0f%%</b>,平均命中 <b>%.2f</b> %s"
                        "</span>" % (n, unit, rate * 100, avg, unit))
        rows.append("<span style='color:#9aa5b1'>※ 统计参考,彩票无必中,理性购彩</span>")
        self.result_lbl.setText("<br><br>".join(rows))
        self.copy_btn.setEnabled(bool(self._copy_text))

    def on_copy(self):
        try:
            QApplication.clipboard().setText(self._copy_text)
            self.status_lbl.setText("已复制:%s" % self._copy_text)
        except Exception:
            pass


def _v108_open_dan_generator(self):
    try:
        dlg = V108DanDialog(self, self)
        dlg.exec()
    except Exception:
        try:
            QMessageBox.warning(self, "智能胆码",
                                "打开失败:\n" + traceback.format_exc())
        except Exception:
            pass


def _v108_inject_button(self):
    """同 V106:防重与锚点限定在最新首页内,免疫旧页面堆叠。"""
    root = getattr(self, "home_tab", None) or self
    bases = [b for b in root.findChildren(QPushButton)
             if "扫码查奖" in b.text()]
    if not bases:
        return False
    host = bases[-1].parentWidget()
    anchor = bases[-1]
    if host is not None:
        for b in host.findChildren(QPushButton):
            if "智能胆码" in b.text():
                return True
        for b in host.findChildren(QPushButton):
            if "竞彩足球" in b.text():
                anchor = b
                break
    lay = _v106_find_layout_of(anchor)
    if lay is None:
        return False
    btn = QPushButton("🎯 智能胆码")
    btn.setToolTip("全玩法AI胆码:联网抓取最新开奖 + 四信号综合评分 + 历史回测")
    btn.setStyleSheet(
        "QPushButton{background:#8e24aa;color:white;font-weight:bold;"
        "border-radius:6px;padding:6px 10px;}"
        "QPushButton:hover{background:#6a1b9a;}")
    btn.clicked.connect(self.open_dan_generator)
    lay.addWidget(btn)
    return True


def _v108_wrap_init_home_tab(old_func):
    def wrapper(self, *args, **kwargs):
        result = old_func(self, *args, **kwargs)
        try:
            _v108_inject_button(self)
        except Exception:
            try:
                logger.debug("V108胆码按钮注入失败:\n" + traceback.format_exc())
            except Exception:
                pass
        return result
    wrapper._v108_wrapped = True
    return wrapper


def _v108_install_patch():
    cls = LotteryApp
    cls.open_dan_generator = _v108_open_dan_generator
    if hasattr(cls, "init_home_tab") and \
            not getattr(cls.init_home_tab, "_v108_wrapped", False):
        cls.init_home_tab = _v108_wrap_init_home_tab(cls.init_home_tab)
    try:
        logger.info("V108补丁已安装:全玩法智能胆码(联网+四信号综合+回测)")
    except Exception:
        pass


try:
    _v108_install_patch()
except Exception:
    try:
        logger.warning("V108补丁安装失败:\n" + traceback.format_exc())
    except Exception:
        pass
