# ============================================================
# V109 PATCH BEGIN —— 可选ML库缺失的日志清噪(Windows/Py3.14 适配)
# 背景:tensorflow/pytorch_tabnet/autogluon 暂不支持 Python 3.14,
#       对应模型自动回退属预期行为,但警告每轮预测重复刷屏。
# 改进:① 缺库警告每个库一次会话只提示一次,后续降为 debug;
#       ② 启动时一次性"可选ML库体检"汇总,附环境建议;
#       ③ 静默 sklearn MLP 的 ConvergenceWarning(回退模型可正常
#          训练预测,该警告无行动价值)。
# ============================================================

def _v109_install_patch():
    # ① sklearn 收敛警告静默
    try:
        import warnings as _w
        from sklearn.exceptions import ConvergenceWarning as _CW
        if isinstance(_CW, type) and issubclass(_CW, Warning):
            _w.filterwarnings("ignore", category=_CW)
    except Exception:
        pass

    # ② 缺库警告去重
    if not getattr(logger.warning, "_v109_wrapped", False):
        _seen = set()
        _orig_warning = logger.warning

        def _dedup_warning(msg, *args, **kwargs):
            try:
                text = str(msg)
                if "No module named" in text:
                    m = re.search(r"No module named '([^']+)'", text)
                    key = m.group(1).split(".")[0] if m else text[:60]
                    if key in _seen:
                        return logger.debug(msg, *args, **kwargs)
                    _seen.add(key)
                    return _orig_warning(
                        text + "(可选库缺失,模型已自动回退;本提示每库仅显示一次)",
                        *args, **kwargs)
            except Exception:
                pass
            return _orig_warning(msg, *args, **kwargs)

        _dedup_warning._v109_wrapped = True
        logger.warning = _dedup_warning

    # ③ 启动一次性可选库体检
    try:
        import importlib.util as _iu
        opt = ["tensorflow", "torch", "pytorch_tabnet", "autogluon",
               "xgboost", "lightgbm", "catboost"]
        missing = []
        for name in opt:
            try:
                if _iu.find_spec(name) is None:
                    missing.append(name)
            except Exception:
                pass
        if missing:
            logger.info(
                "V109可选ML库体检:缺失 %s → 相关模型自动回退备用算法,"
                "核心功能不受影响。当前 Python %s;tensorflow/autogluon/"
                "pytorch_tabnet 暂不支持 3.13+/3.14,如需启用全部模型,"
                "建议另装 Python 3.12 并在其虚拟环境中运行本程序。"
                % (", ".join(missing), sys.version.split()[0]))
        else:
            logger.info("V109可选ML库体检:全部就绪,30模型完整可用。")
    except Exception:
        pass

    try:
        logger.info("V109补丁已安装:缺库警告去重 + 启动体检 + 收敛警告静默")
    except Exception:
        pass


try:
    _v109_install_patch()
except Exception:
    try:
        logger.warning("V109补丁安装失败:\n" + traceback.format_exc())
    except Exception:
        pass
# ============================================================
# V109 PATCH END
# ============================================================


# ============================================================
# V110 PATCH BEGIN —— 开奖详情弹窗:近期记录可点击切换(全玩法)
# 点「近10期开奖记录」任意一期 → 弹窗整体切换为该期:
#   开奖号码彩球 / 该期奖池与销售额 / 该期各奖级中奖情况。
# 数据优先级:该期记录的结构化「奖级」列表 → 直接奖级字段
#   (一等奖…) → 最新一期附带的 prize_info_list → 友好提示。
# 覆盖 LotteryApp._show_prize_info,所有玩法(含福建)通用。
# ============================================================

V110_RECENT_N = 10


def _v110_clear_layout(lay):
    while lay.count():
        it = lay.takeAt(0)
        w = it.widget()
        if w is not None:
            w.deleteLater()
        elif it.layout() is not None:
            _v110_clear_layout(it.layout())


def _v110_prize_lines(rec, is_origin, origin_extra):
    """提取一期的奖级展示行。"""
    lines = []
    levels = rec.get("奖级")
    if isinstance(levels, list):
        for lv in levels:
            if not isinstance(lv, dict):
                continue
            name = str(lv.get("等级", "")).strip()
            cond = str(lv.get("条件", "")).strip()
            n = str(lv.get("注数", "")).strip()
            b = str(lv.get("单注", "")).strip()
            if name and (n or b):
                s = name + ("(%s)" % cond if cond else "") + ": "
                if n:
                    s += "%s注" % n
                if b:
                    s += " ¥%s" % b
                lines.append(s)
    if not lines:
        for k in ("一等奖", "二等奖", "三等奖", "四等奖", "五等奖", "六等奖",
                  "七等奖", "福运奖", "头奖注数", "头奖金额"):
            v = rec.get(k)
            if v is not None and str(v) not in ("", "None", "0", "0注", "0元"):
                lines.append("%s: %s" % (k, v))
    if not lines and is_origin:
        lines = [str(x).strip() for x in (origin_extra or []) if str(x).strip()]
    sale = str(rec.get("销售额", "")).strip()
    if sale and sale not in ("None", "0"):
        lines.append("销售额: %s" % sale)
    return lines


def _v110_show_prize_info(self, game, rec, pool, prize_info_list):
    """弹出中奖信息;近期记录可点击切换查看任意一期。"""
    dlg = QDialog(self)
    dlg.setWindowTitle("🏆 %s 中奖信息" % game)
    dlg.setMinimumWidth(380)
    outer = QVBoxLayout(dlg)

    if not rec:
        outer.addWidget(QLabel("暂无数据，请先获取开奖数据"))
        btn = QPushButton("关闭")
        btn.clicked.connect(dlg.reject)
        outer.addWidget(btn)
        self._v110_last_dlg = dlg
        if getattr(self, "_v110_test_mode", False):
            dlg.show()
        else:
            dlg.exec()
        return

    recs = [r for r in (self.history_data.get(game, []) or [])
            if isinstance(r, dict)]
    recs.sort(key=_v108_issue_key, reverse=True)   # 显式最新在前,不依赖存储顺序
    recs = recs[:V110_RECENT_N]
    origin_issue = str(rec.get("期号", ""))
    init_idx = next((i for i, r in enumerate(recs)
                     if str(r.get("期号", "")) == origin_issue), None)
    if init_idx is None:
        recs = ([rec] + recs)[:V110_RECENT_N]
        init_idx = 0

    # —— 可滚动内容区 —— #
    content = QWidget()
    lay = QVBoxLayout(content)
    sc = QScrollArea()
    sc.setWidgetResizable(True)
    sc.setFrameShape(QFrame.NoFrame)
    sc.setWidget(content)
    outer.addWidget(sc, 1)

    header = QLabel("")
    header.setStyleSheet("font-weight:bold;font-size:13px;color:#2E8B57;"
                         "padding:4px;")
    header.setWordWrap(True)
    lay.addWidget(header)

    ball_ctr = QWidget()
    ball_lay = QHBoxLayout(ball_ctr)
    ball_lay.setContentsMargins(0, 0, 0, 0)
    lay.addWidget(ball_ctr)

    sep = QFrame()
    sep.setFrameShape(QFrame.HLine)
    sep.setStyleSheet("color:#ddd;")
    lay.addWidget(sep)

    pool_lbl = QLabel("")
    pool_lbl.setStyleSheet("font-size:13px;color:#c0392b;font-weight:bold;"
                           "padding:4px;")
    pool_lbl.setWordWrap(True)
    lay.addWidget(pool_lbl)

    prize_grp = QGroupBox("各奖级中奖情况")
    prize_lay = QVBoxLayout(prize_grp)
    lay.addWidget(prize_grp)

    hist_grp = QGroupBox("近%d期开奖记录(点击查看该期详情)" % len(recs))
    hist_lay = QVBoxLayout(hist_grp)
    hist_lay.setSpacing(2)
    lay.addWidget(hist_grp)
    lay.addStretch(1)

    hist_btns = []
    state = {"cur": 0}

    def render(idx):
        state["cur"] = idx
        r = recs[idx]
        issue = str(r.get("期号", "—"))
        date = str(r.get("开奖日期", "—"))
        nums = str(r.get("开奖号码", "—"))
        header.setText("【%s】第 %s 期  开奖日期: %s" % (game, issue, date))
        _v110_clear_layout(ball_lay)
        try:
            numbers = _parse_balls_for_widget(nums, game) \
                if nums and nums != "—" else []
        except Exception:
            numbers = []
        if numbers:
            bw = LotteryBallsWidget(game, numbers)
            if game == "快乐8":
                bw.setFixedHeight(LotteryBallsWidget._BALL_D_SMALL * 2
                                  + LotteryBallsWidget.PAD_V * 4 + 8)
            else:
                bw.setFixedHeight(LotteryBallsWidget.BALL_D
                                  + LotteryBallsWidget.PAD_V * 2 + 4)
            ball_lay.addWidget(bw)
            ball_lay.addStretch(1)
        else:
            ball_lay.addWidget(QLabel(nums))
            ball_lay.addStretch(1)
        p = str(r.get("奖池", "") or "").strip()
        if p in ("", "—", "None", "0.00元", "0元"):
            p = pool if issue == origin_issue else "—"
        pool_lbl.setText("🏦 奖池余额: %s" % p)
        _v110_clear_layout(prize_lay)
        lines = _v110_prize_lines(r, issue == origin_issue, prize_info_list)
        if lines:
            for s in lines:
                prize_lay.addWidget(QLabel("  " + s))
        else:
            prize_lay.addWidget(
                QLabel("  该期暂无奖级数据（早期数据或该数据源未提供）"))
        for i, b in enumerate(hist_btns):
            if i == idx:
                b.setStyleSheet(
                    "QPushButton{text-align:left;border:none;padding:4px 6px;"
                    "background:#e7f0e7;color:#1b5e2f;font-weight:bold;"
                    "border-radius:4px;}")
            else:
                b.setStyleSheet(
                    "QPushButton{text-align:left;border:none;padding:4px 6px;"
                    "background:transparent;color:#1a66cc;}"
                    "QPushButton:hover{background:#eef3f8;}")

    for i, r in enumerate(recs):
        txt = "第%s期 (%s): %s" % (r.get("期号", "—"), r.get("开奖日期", "—"),
                                   r.get("开奖号码", "—"))
        b = QPushButton(txt)
        b.setCursor(Qt.PointingHandCursor)
        b.clicked.connect(lambda _=False, idx=i: render(idx))
        hist_lay.addWidget(b)
        hist_btns.append(b)

    render(init_idx)

    close_btn = QPushButton("关闭")
    close_btn.clicked.connect(dlg.reject)
    outer.addWidget(close_btn)
    try:
        scg = QApplication.primaryScreen().availableGeometry()
        dlg.resize(max(380, int(scg.width() * 0.92)),
                   max(560, int(scg.height() * 0.85)))
    except Exception:
        pass
    self._v110_last_dlg = dlg
    if getattr(self, "_v110_test_mode", False):
        dlg.show()
    else:
        dlg.exec()


def _v110_install_patch():
    LotteryApp._show_prize_info = _v110_show_prize_info
    try:
        logger.info("V110补丁已安装:开奖详情近%d期记录可点击切换(全玩法)"
                    % V110_RECENT_N)
    except Exception:
        pass


try:
    _v110_install_patch()
except Exception:
    try:
        logger.warning("V110补丁安装失败:\n" + traceback.format_exc())
    except Exception:
        pass
# ============================================================
# V110 PATCH END
