# ============================================================
# V111 CLEAN STAGE 1 PATCH — 安全瘦身稳定版
# 按本轮要求：
# 1) 保留 ScraplingLotteryFetcher / 外部爬虫备用源
# 2) 废弃 QProgressDialog 的全量更新弹窗路径
# 3) 废弃 FullHistoryFetchThread 的全量更新路径
# 4) 全量更新改为：极速API only + 20条分页 + 串行更新 + 断点续传 + 每页即时保存
# 5) 禁止运行时自动 pip_disabled_install scrapling，避免 Android/CJ IDE 闪退
# ============================================================

import json as _clean_json
import time as _clean_time
from pathlib import Path as _clean_Path

try:
    import requests as _clean_requests
except Exception:
    _clean_requests = None

CLEAN_STAGE1_DIR = APP_DIR / "v111_clean_stage1"
CLEAN_STAGE1_DIR.mkdir(parents=True, exist_ok=True)
CLEAN_STAGE1_PROGRESS = CLEAN_STAGE1_DIR / "jisu_resume_progress.json"
CLEAN_STAGE1_LOG = CLEAN_STAGE1_DIR / "jisu_update_log.json"
CLEAN_STAGE1_HEALTH = CLEAN_STAGE1_DIR / "data_health_report.json"

CLEAN_PAGE_SIZE = 20
CLEAN_RETRY = 3
CLEAN_TIMEOUT = 15
CLEAN_SLEEP = 0.8

CLEAN_EXPECTED_HISTORY = {
    "双色球": 3576,
    "大乐透": 3028,
    "快乐8": 2000,
    "七星彩": 2600,
    "3D": 7519,
    "福彩3D": 7519,
    "排列三": 7519,
    "七乐彩": 3000,
    "排列五": 7519,
}

CLEAN_UPDATE_GAMES = ["双色球", "大乐透", "快乐8", "七星彩", "3D", "排列三", "七乐彩", "排列五"]

class _CleanDummySignal:
    def connect(self, *args, **kwargs):
        return None

class _CleanNoProgressDialog:
    """Android稳定用：替代 QProgressDialog，避免定时器/线程弹窗导致闪退。"""
    canceled = _CleanDummySignal()
    def __init__(self, *args, **kwargs):
        self._was_canceled = False
    def setWindowTitle(self, *args, **kwargs): pass
    def setWindowModality(self, *args, **kwargs): pass
    def setMinimumDuration(self, *args, **kwargs): pass
    def setAutoClose(self, *args, **kwargs): pass
    def setAutoReset(self, *args, **kwargs): pass
    def setValue(self, *args, **kwargs): pass
    def setLabelText(self, *args, **kwargs):
        try:
            logger.info(str(args[0]) if args else "")
        except Exception:
            pass
    def close(self): pass
    def show(self): pass
    def wasCanceled(self): return self._was_canceled

# 覆盖全局 QProgressDialog 名称。旧代码若误调用，也不会再创建 Qt 进度弹窗。
QProgressDialog = _CleanNoProgressDialog

# 禁止自动安装 scrapling。保留外部爬虫类，但不允许运行时 pip_disabled_install。
def _ensure_scrapling():
    return False

def _clean_load_json(path, default):
    try:
        p = _clean_Path(path)
        if p.exists():
            return _clean_json.loads(p.read_text(encoding="utf-8"))
    except Exception:
        pass
    return default

def _clean_save_json(path, data):
    p = _clean_Path(path)
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(_clean_json.dumps(data, ensure_ascii=False, indent=2), encoding="utf-8")

def _clean_get_key(self=None):
    for attr in ("jisuapi_key", "api_key", "appkey"):
        try:
            v = getattr(self, attr, "") if self is not None else ""
            if v:
                return str(v).strip()
        except Exception:
            pass
    try:
        if JISUAPI_APPKEY:
            return str(JISUAPI_APPKEY).strip()
    except Exception:
        pass
    try:
        data = _clean_load_json(API_KEY_FILE, {})
        if isinstance(data, dict):
            for k in ("jisuapi_key", "api_key", "appkey", "key"):
                if data.get(k):
                    return str(data.get(k)).strip()
    except Exception:
        pass
    return ""

def _clean_history_dict(self=None):
    data = {}
    try:
        if self is not None and isinstance(getattr(self, "history_data", None), dict):
            data.update(getattr(self, "history_data"))
    except Exception:
        pass
    file_data = _clean_load_json(HISTORY_DATA_FILE, {})
    if isinstance(file_data, dict):
        # 文件为准，但保留内存独有键
        data.update(file_data)
    return data

def _clean_save_history_dict(self, data):
    try:
        if self is not None:
            self.history_data = data
    except Exception:
        pass
    _clean_save_json(HISTORY_DATA_FILE, data)
    try:
        if self is not None and hasattr(self, "_save_all_history"):
            self._save_all_history()
    except Exception:
        pass

def _clean_issue(row):
    if not isinstance(row, dict):
        return ""
    for k in ("期号", "issueno", "issue", "expect", "term", "code"):
        v = row.get(k)
        if v not in (None, ""):
            return str(v).strip()
    return ""

def _clean_norm_record(item):
    if not isinstance(item, dict):
        return None
    issue = str(item.get("issueno") or item.get("issue") or item.get("期号") or "").strip()
    if not issue:
        return None
    nums = str(item.get("number") or item.get("opencode") or item.get("开奖号码") or "").strip()
    refn = str(item.get("refernumber") or item.get("参考号码") or "").strip()
    prize_info = []
    try:
        for p in _normalize_jisu_prize_list(item.get("prize")):
            if isinstance(p, dict):
                prize_info.append({
                    "等级": p.get("prizename", p.get("等级", p.get("name", ""))),
                    "注数": p.get("num", p.get("注数", p.get("count", ""))),
                    "单注": p.get("singlebonus", p.get("单注", p.get("bonus", ""))),
                    "条件": p.get("require", p.get("条件", p.get("condition", ""))),
                })
    except Exception:
        prize_info = []
    return {
        "期号": issue,
        "开奖日期": str(item.get("opendate") or item.get("date") or item.get("开奖日期") or "")[:10],
        "开奖号码": nums,
        "参考号码": refn,
        "销售额": str(item.get("saleamount") or item.get("销售额") or ""),
        "奖级": prize_info,
        "来源": "jisuapi-clean-stage1",
    }

def _clean_extract_rows(data):
    if not isinstance(data, dict):
        return []
    result = data.get("result", data.get("data", data))
    if isinstance(result, list):
        return [x for x in result if isinstance(x, dict)]
    if isinstance(result, dict):
        for k in ("list", "rows", "data", "items", "history"):
            v = result.get(k)
            if isinstance(v, list):
                return [x for x in v if isinstance(x, dict)]
    return []

def _clean_caipiao_id(game):
    try:
        mp = JISUAPI_CONFIG.get("lottery_id_map", {})
        if game in mp:
            return mp[game]
        if game == "福彩3D" and "3D" in mp:
            return mp["3D"]
    except Exception:
        pass
    return {
        "双色球": 11, "3D": 12, "福彩3D": 12, "七乐彩": 13,
        "大乐透": 14, "七星彩": 15, "排列三": 16, "排列五": 17, "快乐8": 89,
    }.get(game)

def _clean_merge_game(data, game, rows):
    old = data.get(game, [])
    if game == "3D" and not old:
        old = data.get("福彩3D", [])
    if not isinstance(old, list):
        old = []
    by_issue = {}
    damaged = 0
    duplicate = 0
    for r in old:
        if not isinstance(r, dict):
            damaged += 1
            continue
        issue = _clean_issue(r)
        if not issue:
            damaged += 1
            continue
        if issue in by_issue:
            duplicate += 1
        by_issue[issue] = r
    before = len(by_issue)
    for item in rows:
        r = _clean_norm_record(item)
        if not r:
            damaged += 1
            continue
        issue = r["期号"]
        if issue in by_issue:
            duplicate += 1
        by_issue[issue] = r
    merged = list(by_issue.values())
    def keyfun(x):
        s = str(x.get("期号") or x.get("issueno") or "")
        try:
            return (0, int(s))
        except Exception:
            return (1, s)
    merged.sort(key=keyfun)
    data[game] = merged
    if game == "3D":
        data["福彩3D"] = merged
    return {"更新前": before, "更新后": len(merged), "新增": max(0, len(merged)-before), "重复": duplicate, "损坏": damaged}

def _clean_request_page(appkey, game, start):
    if _clean_requests is None:
        return None, "requests模块不可用"
    cid = _clean_caipiao_id(game)
    if not cid:
        return None, f"未知极速API彩种ID：{game}"
    url = JISUAPI_CONFIG.get("base_url", "https://api.jisuapi.com") + JISUAPI_CONFIG.get("lottery_history", "/caipiao/history")
    params = {"appkey": appkey, "caipiaoid": cid, "issueno": "", "start": start, "num": CLEAN_PAGE_SIZE}
    last_err = ""
    for i in range(CLEAN_RETRY):
        try:
            r = _clean_requests.get(url, params=params, timeout=CLEAN_TIMEOUT, headers={"User-Agent": "caile-v111-clean/1.0"})
            r.raise_for_status()
            data = r.json()
            if isinstance(data, dict):
                status = str(data.get("status", data.get("code", "0")))
                if status not in ("0", "200", "") and not data.get("result"):
                    return None, f"接口错误 status={status} msg={data.get('msg', data.get('message',''))}"
            return data, ""
        except Exception as e:
            last_err = str(e)
            _clean_time.sleep(CLEAN_SLEEP * (i + 1))
    return None, "请求失败: " + last_err

def _clean_status(self, msg):
    try:
        logger.info(msg)
    except Exception:
        pass
    for name in ("status_label", "status_lbl", "result_label"):
        try:
            w = getattr(self, name, None)
            if w is not None and hasattr(w, "setText"):
                w.setText(str(msg))
                break
        except Exception:
            pass
    try:
        QApplication.processEvents()
    except Exception:
        pass

def _clean_update_game(self, game, force=False, resume=True, max_pages=10000):
    appkey = _clean_get_key(self)
    if not appkey:
        return {"状态": "失败", "彩种": game, "原因": "未设置极速API密钥"}
    expected = CLEAN_EXPECTED_HISTORY.get(game, 0)
    data = _clean_history_dict(self)
    current_rows = data.get(game, [])
    if game == "3D" and not current_rows:
        current_rows = data.get("福彩3D", [])
    current_count = len(current_rows) if isinstance(current_rows, list) else 0
    if not force and expected and current_count >= expected * 0.995:
        return {"状态": "跳过", "彩种": game, "更新前": current_count, "更新后": current_count, "理论": expected, "说明": "本地数据已接近完整"}
    progress = _clean_load_json(CLEAN_STAGE1_PROGRESS, {})
    start = int(progress.get(game, 0)) if resume else 0
    total_fetch = 0
    page_count = 0
    last_error = ""
    before_total = current_count
    while page_count < max_pages:
        _clean_status(self, f"{game} 正在抓取 start={start}, num={CLEAN_PAGE_SIZE} ...")
        raw, err = _clean_request_page(appkey, game, start)
        if err:
            last_error = err
            break
        rows = _clean_extract_rows(raw)
        if not rows:
            progress.pop(game, None)
            _clean_save_json(CLEAN_STAGE1_PROGRESS, progress)
            break
        total_fetch += len(rows)
        data = _clean_history_dict(self)
        merge_info = _clean_merge_game(data, game, rows)
        _clean_save_history_dict(self, data)
        start += CLEAN_PAGE_SIZE
        progress[game] = start
        _clean_save_json(CLEAN_STAGE1_PROGRESS, progress)
        page_count += 1
        after_count = len(data.get(game, [])) if isinstance(data.get(game, []), list) else 0
        if expected and after_count >= expected * 0.995:
            progress.pop(game, None)
            _clean_save_json(CLEAN_STAGE1_PROGRESS, progress)
            break
        if len(rows) < CLEAN_PAGE_SIZE:
            progress.pop(game, None)
            _clean_save_json(CLEAN_STAGE1_PROGRESS, progress)
            break
    data = _clean_history_dict(self)
    after_rows = data.get(game, [])
    if game == "3D" and not after_rows:
        after_rows = data.get("福彩3D", [])
    after_total = len(after_rows) if isinstance(after_rows, list) else 0
    pct = round(after_total / expected * 100, 2) if expected else 0
    state = "完成" if not last_error else ("部分完成，可继续断点续传" if after_total > before_total else "失败")
    return {
        "状态": state,
        "彩种": game,
        "更新前": before_total,
        "更新后": after_total,
        "理论": expected,
        "完整度": pct,
        "本次接口抓取": total_fetch,
        "页数": page_count,
        "下一断点start": progress.get(game),
        "说明": last_error or "已到接口尾页/达到理论期数",
    }

def _clean_health(self=None):
    data = _clean_history_dict(self)
    detail = {}
    total_a = 0
    total_e = 0
    need = []
    for game in CLEAN_UPDATE_GAMES:
        expected = CLEAN_EXPECTED_HISTORY.get(game, 0)
        rows = data.get(game, [])
        if game == "3D" and not rows:
            rows = data.get("福彩3D", [])
        issues = set()
        if isinstance(rows, list):
            for r in rows:
                issue = _clean_issue(r)
                if issue:
                    issues.add(issue)
        actual = len(issues)
        pct = round(actual / expected * 100, 2) if expected else 0
        ok = actual >= expected * 0.95
        detail[game] = {"当前": actual, "理论": expected, "完整度": pct, "状态": "✔" if ok else "✘"}
        total_a += min(actual, expected)
        total_e += expected
        if not ok:
            need.append(game)
    report = {"时间": _clean_time.strftime("%Y-%m-%d %H:%M:%S"), "明细": detail, "数据库完整度": round(total_a / max(1,total_e) * 100, 2), "需要补档": need}
    _clean_save_json(CLEAN_STAGE1_HEALTH, report)
    return report

def _clean_format_health(self=None):
    h = _clean_health(self)
    lines = ["🛠 V111 Clean 数据完整性检查", f"时间：{h.get('时间')}", ""]
    for game, d in h.get("明细", {}).items():
        lines.append(f"{game} {d['当前']} / {d['理论']} {d['状态']} 完整度 {d['完整度']}%")
    lines.append("")
    lines.append(f"数据库完整度：{h.get('数据库完整度')}%")
    lines.append("需要补档：" + ("、".join(h.get("需要补档", [])) or "无"))
    return "\n".join(lines)

def _clean_full_update(self, max_per_game=200000, force=True, resume=True):
    if getattr(self, "_clean_stage1_running", False):
        try:
            QMessageBox.information(self, "提示", "极速API串行补档正在进行中，请稍候。")
        except Exception:
            pass
        return
    self._clean_stage1_running = True
    log = {}
    try:
        for game in CLEAN_UPDATE_GAMES:
            log[game] = _clean_update_game(self, game, force=force, resume=resume)
        health = _clean_health(self)
        result = {"时间": _clean_time.strftime("%Y-%m-%d %H:%M:%S"), "说明": "V111 Clean：极速API only，20条分页，串行更新，断点续传，无QProgressDialog，无FullHistoryFetchThread。", "补档日志": log, "健康报告": health}
        _clean_save_json(CLEAN_STAGE1_LOG, result)
        try:
            if hasattr(self, "update_home_results"):
                self.update_home_results()
            if hasattr(self, "calculate_omission"):
                self.calculate_omission()
        except Exception:
            pass
        msg = _clean_format_health(self)
        try:
            QMessageBox.information(self, "✅ V111 Clean 更新完成", msg)
        except Exception:
            pass
        return result
    finally:
        self._clean_stage1_running = False

def _clean_reset_resume(self):
    _clean_save_json(CLEAN_STAGE1_PROGRESS, {})
    try:
        QMessageBox.information(self, "断点已清空", "下次全量补档将从 start=0 开始。")
    except Exception:
        pass

def _clean_install_stage1():
    cls = globals().get("LotteryApp")
    if not isinstance(cls, type):
        return False
    # 覆盖历史全量更新路径：不再走 QProgressDialog + FullHistoryFetchThread
    cls.update_all_history_full = _clean_full_update
    cls.full_update_to_latest = _clean_full_update
    cls.update_all_to_latest = _clean_full_update
    cls.fetch_full_history = _clean_full_update
    cls.clean_stage1_update_game = _clean_update_game
    cls.clean_stage1_health = _clean_health
    cls.clean_stage1_health_text = _clean_format_health
    cls.clean_stage1_reset_resume = _clean_reset_resume

    old_init_ui = getattr(cls, "init_ui", None)
    if callable(old_init_ui) and not getattr(cls, "_clean_stage1_tab_installed", False):
        def _init_ui_clean_stage1(self, *args, **kwargs):
            ret = old_init_ui(self, *args, **kwargs)
            try:
                if hasattr(self, "tabs") and self.tabs is not None:
                    tab = QWidget()
                    lay = QVBoxLayout(tab)
                    title = QLabel("🛠 V111 Clean · 极速API串行补档")
                    title.setStyleSheet("font-size:20px;font-weight:bold;color:#B03A2E;padding:8px;")
                    lay.addWidget(title)
                    tip = QLabel("本页已绕开 QProgressDialog 和 FullHistoryFetchThread：极速API only，20条分页，断点续传，每页即时保存。外部爬虫已保留但不自动安装scrapling。")
                    tip.setWordWrap(True)
                    tip.setStyleSheet("background:#FEF5E7;color:#7E5109;border:1px solid #F5CBA7;border-radius:8px;padding:8px;")
                    lay.addWidget(tip)
                    row = QHBoxLayout()
                    btn_check = QPushButton("检查完整度")
                    btn_update = QPushButton("开始/继续补档")
                    btn_reset = QPushButton("清空断点")
                    btn_check.setStyleSheet("background:#2980B9;color:white;font-weight:bold;padding:9px;")
                    btn_update.setStyleSheet("background:#C0392B;color:white;font-weight:bold;padding:9px;")
                    btn_reset.setStyleSheet("background:#7D3C98;color:white;font-weight:bold;padding:9px;")
                    row.addWidget(btn_check); row.addWidget(btn_update); row.addWidget(btn_reset); row.addStretch()
                    lay.addLayout(row)
                    out = QTextEdit()
                    out.setReadOnly(True)
                    out.setStyleSheet("font-family:Consolas,Microsoft YaHei;font-size:13px;")
                    lay.addWidget(out, 1)
                    def do_check():
                        out.setPlainText(_clean_format_health(self))
                    def do_update():
                        res = _clean_full_update(self, force=True, resume=True)
                        out.setPlainText(_clean_json.dumps(res, ensure_ascii=False, indent=2))
                    def do_reset():
                        _clean_reset_resume(self)
                        out.setPlainText("已清空断点。")
                    btn_check.clicked.connect(do_check)
                    btn_update.clicked.connect(do_update)
                    btn_reset.clicked.connect(do_reset)
                    for i in range(self.tabs.count()-1, -1, -1):
                        if "V111 Clean" in self.tabs.tabText(i):
                            self.tabs.removeTab(i)
                    self.tabs.addTab(tab, "🛠 V111 Clean")
            except Exception:
                try:
                    logger.warning("V111 Clean Tab安装失败:\n" + traceback.format_exc())
                except Exception:
                    pass
            return ret
        cls.init_ui = _init_ui_clean_stage1
        cls._clean_stage1_tab_installed = True
    try:
        logger.info("V111 Clean Stage1 已安装：保留外部爬虫，废弃QProgressDialog/FullHistoryFetchThread更新路径")
    except Exception:
        pass
    return True

try:
    _clean_install_stage1()
except Exception:
    try:
        logger.warning("V111 Clean Stage1 安装失败:\n" + traceback.format_exc())
    except Exception:
        pass

