# ============================================================
# V111 CLEAN STAGE4 PATCH — 开奖详情页增加“期号搜索/选择框”
# 适用：所有玩法开奖详情弹窗/页面
# ============================================================

def _stage4_history_dict(self):
    try:
        if hasattr(self, "history_data") and isinstance(self.history_data, dict):
            return self.history_data
    except Exception:
        pass
    try:
        if "HISTORY_DATA_FILE" in globals() and Path(HISTORY_DATA_FILE).exists():
            return json.loads(Path(HISTORY_DATA_FILE).read_text(encoding="utf-8"))
    except Exception:
        pass
    return {}

def _stage4_issue_of(row):
    if not isinstance(row, dict):
        return ""
    for k in ("期号", "issueno", "issue", "expect", "term", "no"):
        v = row.get(k)
        if v not in (None, ""):
            return str(v).strip()
    return ""

def _stage4_date_of(row):
    if not isinstance(row, dict):
        return ""
    for k in ("开奖日期", "opendate", "date", "time", "openTime"):
        v = row.get(k)
        if v not in (None, ""):
            return str(v)[:10]
    return ""

def _stage4_nums_of(row):
    if not isinstance(row, dict):
        return ""
    for k in ("开奖号码", "opencode", "number", "openCode", "code", "result"):
        v = row.get(k)
        if v not in (None, ""):
            return str(v).strip()
    return ""

def _stage4_rows_for_game(self, game):
    data = _stage4_history_dict(self)
    rows = data.get(game, [])
    if game in ("3D", "福彩3D") and not rows:
        rows = data.get("福彩3D") or data.get("3D") or []
    if not isinstance(rows, list):
        return []
    by_issue = {}
    for r in rows:
        issue = _stage4_issue_of(r)
        if issue:
            by_issue[issue] = r
    def key_func(x):
        issue = _stage4_issue_of(x)
        try:
            return int(re.sub(r"\D", "", issue) or "0")
        except Exception:
            return 0
    return sorted(by_issue.values(), key=key_func, reverse=True)

def _stage4_show_issue_detail(self, game, issue):
    rows = _stage4_rows_for_game(self, game)
    target = None
    for r in rows:
        if _stage4_issue_of(r) == str(issue):
            target = r
            break
    if target is None:
        try:
            QMessageBox.information(self, "未找到", f"{game} 未找到第 {issue} 期")
        except Exception:
            pass
        return

    # 兜底详情弹窗：稳定，不依赖旧函数参数格式
    dlg = QDialog(self)
    dlg.setWindowTitle(f"{game} 第{issue}期开奖详情")
    try:
        _responsive_dlg_size(dlg, 720, 900)
    except Exception:
        dlg.resize(720, 900)
    lay = QVBoxLayout(dlg)

    # 顶部期号选择区
    selector = QFrame()
    selector.setStyleSheet("background:#F8F9F9;border:1px solid #D5DBDB;border-radius:8px;padding:6px;")
    row_lay = QHBoxLayout(selector)
    row_lay.setContentsMargins(8, 6, 8, 6)
    row_lay.addWidget(QLabel("🔎 期号搜索："))
    search = QLineEdit()
    search.setPlaceholderText("输入期号，如 2026066 / 26064")
    row_lay.addWidget(search, 1)
    combo = QComboBox()
    combo.setMinimumWidth(240)
    issue_items = []
    for r in rows:
        iss = _stage4_issue_of(r)
        label = f"{iss}  {_stage4_date_of(r)}  {_stage4_nums_of(r)[:28]}"
        issue_items.append((iss, label))
        combo.addItem(label, iss)
    for i, (iss, _) in enumerate(issue_items):
        if str(iss) == str(issue):
            combo.setCurrentIndex(i)
            break
    row_lay.addWidget(combo, 2)
    go_btn = QPushButton("查看")
    go_btn.setStyleSheet("background:#2471A3;color:white;font-weight:bold;padding:6px 10px;")
    row_lay.addWidget(go_btn)
    lay.addWidget(selector)

    title = QLabel(f"【{game}】第 {issue} 期  开奖日期：{_stage4_date_of(target)}")
    title.setStyleSheet("font-size:18px;font-weight:bold;color:#1E8449;padding:8px;")
    lay.addWidget(title)

    nums = QLabel(_stage4_nums_of(target))
    nums.setWordWrap(True)
    nums.setStyleSheet("font-size:20px;font-weight:bold;color:#C0392B;padding:12px;border:1px solid #ddd;border-radius:8px;")
    lay.addWidget(nums)

    txt = QTextEdit()
    txt.setReadOnly(True)
    txt.setPlainText(json.dumps(target, ensure_ascii=False, indent=2))
    lay.addWidget(txt, 1)

    btn = QPushButton("关闭")
    btn.clicked.connect(dlg.accept)
    lay.addWidget(btn)

    def do_filter(text):
        text = str(text).strip()
        combo.blockSignals(True)
        combo.clear()
        for iss, label in issue_items:
            if not text or text in str(iss) or text in label:
                combo.addItem(label, iss)
        combo.blockSignals(False)

    def do_go():
        new_issue = combo.currentData()
        if new_issue and str(new_issue) != str(issue):
            dlg.accept()
            QTimer.singleShot(60, lambda: _stage4_show_issue_detail(self, game, new_issue))

    search.textChanged.connect(do_filter)
    go_btn.clicked.connect(do_go)
    combo.activated.connect(lambda *_: do_go())

    dlg.exec()

def _stage4_install():
    cls = globals().get("LotteryApp")
    if not isinstance(cls, type):
        return False

    cls.stage4_show_issue_detail = _stage4_show_issue_detail
    cls.stage4_rows_for_game = _stage4_rows_for_game

    old_init_ui = getattr(cls, "init_ui", None)
    if callable(old_init_ui) and not getattr(cls, "_stage4_issue_tab_installed", False):
        def _init_ui_stage4(self, *args, **kwargs):
            ret = old_init_ui(self, *args, **kwargs)
            try:
                if hasattr(self, "tabs") and self.tabs is not None:
                    tab = QWidget()
                    lay = QVBoxLayout(tab)
                    title = QLabel("🔎 开奖期号搜索")
                    title.setStyleSheet("font-size:20px;font-weight:bold;color:#145A32;padding:8px;")
                    lay.addWidget(title)

                    top = QHBoxLayout()
                    game_box = QComboBox()
                    games = ["双色球","大乐透","快乐8","七星彩","3D","排列三","排列五","七乐彩","福建36选7","福建31选7","福建22选5"]
                    game_box.addItems(games)
                    issue_edit = QLineEdit()
                    issue_edit.setPlaceholderText("输入期号关键词")
                    issue_box = QComboBox()
                    issue_box.setMinimumWidth(260)
                    view_btn = QPushButton("查看开奖详情")
                    view_btn.setStyleSheet("background:#1E8449;color:white;font-weight:bold;padding:8px;")
                    top.addWidget(QLabel("玩法："))
                    top.addWidget(game_box)
                    top.addWidget(QLabel("搜索："))
                    top.addWidget(issue_edit, 1)
                    top.addWidget(issue_box, 2)
                    top.addWidget(view_btn)
                    lay.addLayout(top)

                    result = QTextEdit()
                    result.setReadOnly(True)
                    result.setStyleSheet("font-family:Consolas,Microsoft YaHei;font-size:13px;")
                    lay.addWidget(result, 1)

                    def refresh_issues():
                        game = game_box.currentText()
                        kw = issue_edit.text().strip()
                        rows = _stage4_rows_for_game(self, game)
                        issue_box.clear()
                        for r in rows:
                            issue = _stage4_issue_of(r)
                            date = _stage4_date_of(r)
                            nums = _stage4_nums_of(r)
                            label = f"{issue}  {date}  {nums[:36]}"
                            if not kw or kw in issue or kw in label:
                                issue_box.addItem(label, issue)
                        result.setPlainText(f"{game} 共找到 {issue_box.count()} 期，可选择后查看详情。")

                    def view_issue():
                        issue = issue_box.currentData()
                        game = game_box.currentText()
                        if issue:
                            _stage4_show_issue_detail(self, game, issue)

                    game_box.currentTextChanged.connect(refresh_issues)
                    issue_edit.textChanged.connect(refresh_issues)
                    issue_box.activated.connect(lambda *_: view_issue())
                    view_btn.clicked.connect(view_issue)
                    refresh_issues()

                    for i in range(self.tabs.count()-1, -1, -1):
                        if "开奖期号搜索" in self.tabs.tabText(i):
                            self.tabs.removeTab(i)
                    self.tabs.addTab(tab, "🔎 期号搜索")
            except Exception:
                try:
                    logger.warning("Stage4期号搜索Tab安装失败:\n" + traceback.format_exc())
                except Exception:
                    pass
            return ret
        cls.init_ui = _init_ui_stage4
        cls._stage4_issue_tab_installed = True

    try:
        logger.info("V111 Clean Stage4 已安装：开奖详情页期号搜索/选择框")
    except Exception:
        pass
    return True

try:
    _stage4_install()
except Exception:
    try:
        logger.warning("V111 Clean Stage4 安装失败:\n" + traceback.format_exc())
    except Exception:
        pass

