STAGE7_DIR = APP_DIR / "v111_china_jingcai"
STAGE7_DIR.mkdir(parents=True, exist_ok=True)
STAGE7_CHINA_CACHE = STAGE7_DIR / "china_jingcai_cache.json"
STAGE7_PLANS = STAGE7_DIR / "china_jingcai_plans.json"

STAGE7_TRAIN_RANGES = ["全部历史", "近3年", "近2年", "近1年", "365天", "180天", "90天", "30天"]
STAGE7_PLAY_TYPES = ["胜平负", "让球胜平负", "总进球", "半全场", "比分"]
STAGE7_LEAGUE_OPTIONS = ["全部赛事", "世界杯", "欧洲杯", "欧冠", "欧联", "英超", "英冠", "西甲", "德甲", "意甲", "法甲", "中超", "日职联", "日职乙", "韩K联", "美职联", "美冠联", "芬超", "瑞典超", "挪超", "荷甲", "葡超", "巴甲", "阿甲"]

def _stage7_load_json(path, default):
    try:
        p = Path(path)
        if p.exists():
            return json.loads(p.read_text(encoding="utf-8"))
    except Exception:
        pass
    return default

def _stage7_save_json(path, data):
    p = Path(path)
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(json.dumps(data, ensure_ascii=False, indent=2), encoding="utf-8")

def _stage7_code_from_prob(prob):
    prob = prob or {"home": 0.38, "draw": 0.30, "away": 0.32}
    best = max(prob.items(), key=lambda kv: kv[1])[0]
    return {"home": "3", "draw": "1", "away": "0"}.get(best, "3")

def _stage7_goal_category(total):
    try:
        x = float(total)
    except Exception:
        x = 2.2
    if x < 1.0: return "0/1"
    if x < 2.0: return "1/2"
    if x < 3.0: return "2/3"
    if x < 4.0: return "3/4"
    return "4/5/6+"

def _stage7_score_pick(prob):
    prob = prob or {"home": 0.38, "draw": 0.30, "away": 0.32}
    h = prob.get("home", 0.34); d = prob.get("draw", 0.30); a = prob.get("away", 0.33)
    if h >= max(d, a): return "1:0 / 2:1"
    if a >= max(h, d): return "0:1 / 1:2"
    return "1:1 / 0:0"

def _stage7_half_full_pick(prob):
    code = _stage7_code_from_prob(prob)
    if code == "3": return "平胜/胜胜"
    if code == "0": return "平负/负负"
    return "平平/胜平"

def _stage7_enrich_match(m, idx=1):
    m = dict(m or {})
    prob = m.get("prob") or {"home": 0.38, "draw": 0.30, "away": 0.32}
    goal = m.get("goal_pick") or {}
    expected = goal.get("expected") or [1.2, 1.0]
    try: total_exp = float(expected[0]) + float(expected[1])
    except Exception: total_exp = 2.2
    spf = _stage7_code_from_prob(prob)
    rq = (m.get("china_jc") or {}).get("rqspf", {})
    handicap = rq.get("handicap", 0)
    rq_code = rq.get("code", spf)
    m["china_jc"] = {
        "编号": m.get("no") or f"竞彩{idx:03d}", "停售": m.get("time", ""), "联赛": m.get("league", ""),
        "胜平负": {"推荐": spf, "概率": prob, "SP": m.get("odds", {})},
        "让球胜平负": {"让球": handicap, "推荐": rq_code, "概率": rq.get("prob", prob), "SP": {}},
        "总进球": {"推荐": _stage7_goal_category(total_exp), "预期总进球": round(total_exp, 2)},
        "半全场": {"推荐": _stage7_half_full_pick(prob)}, "比分": {"推荐": _stage7_score_pick(prob)},
        "官方盘口状态": "待接中国竞彩网官方SP接口；当前用BSD赔率/模型映射",
    }
    return m

def _stage7_load_matches():
    rows = _stage7_load_json(STAGE7_CHINA_CACHE, [])
    if not rows and "STAGE5_MATCH_FILE" in globals(): rows = _stage7_load_json(STAGE5_MATCH_FILE, [])
    return [_stage7_enrich_match(x, i+1) for i, x in enumerate(rows or [])]

def _stage7_save_matches(rows):
    rows = [_stage7_enrich_match(x, i+1) for i, x in enumerate(rows or [])]
    _stage7_save_json(STAGE7_CHINA_CACHE, rows)
    return rows

def _stage7_update_china_cache(days=4):
    rows=[]; err=""; status="cache"
    if "_stage5_update_jingcai_cache" in globals():
        try:
            res=_stage5_update_jingcai_cache(days=days, manual=True)
            rows=res.get("matches", []); err=res.get("error", ""); status=res.get("status", "ok")
        except Exception as e: err=str(e)
    if not rows: rows=_stage7_load_matches()
    rows=_stage7_save_matches(rows)
    return {"status":status,"error":err,"count":len(rows),"matches":rows}

def _stage7_match_filter(m, league_filter="全部赛事", keyword=""):
    league_filter=str(league_filter or "全部赛事"); keyword=str(keyword or "").strip().lower()
    hay=" ".join([str(m.get(k,"")) for k in ("no","league","home","away","raw_home","raw_away")]).lower()
    if keyword and keyword not in hay: return False
    if league_filter in ("全部赛事","全部"): return True
    lf=league_filter.lower()
    if league_filter == "世界杯": return ("世界杯" in hay) or ("world cup" in hay) or ("fifa" in hay)
    return (lf in hay) or (league_filter in str(m.get("league","")))

def _stage7_filter(rows, league_filter="全部赛事", keyword=""):
    return [m for m in (rows or []) if _stage7_match_filter(m, league_filter, keyword)]

def _stage7_pick_for_sfc(m):
    prob=m.get("prob") or {}; code=_stage7_code_from_prob(prob); vals=sorted(prob.values(), reverse=True) if prob else [0.38,0.32]
    diff=vals[0]-vals[1] if len(vals)>1 else 0
    if diff>=0.14: return code
    if diff>=0.07: return code + ("1" if code != "1" else "3")
    return "310" if code == "1" else ("31" if code == "3" else "10")

def _stage7_generate_all(rows=None, play_type="胜平负"):
    rows=[_stage7_enrich_match(x,i+1) for i,x in enumerate(rows or _stage7_load_matches())]
    sfc14=[]
    for i,m in enumerate(rows[:14],1):
        jc=m.get("china_jc",{})
        sfc14.append({"序号":i,"场次":m.get("no"),"赛事":m.get("league"),"主队":m.get("home"),"客队":m.get("away"),"推荐":_stage7_pick_for_sfc(m),"主推":jc.get("胜平负",{}).get("推荐","3"),"让球":jc.get("让球胜平负",{}).get("让球",0),"总进球":jc.get("总进球",{}).get("推荐",""),"半全场":jc.get("半全场",{}).get("推荐",""),"比分":jc.get("比分",{}).get("推荐",""),"风险":m.get("risk","中"),"概率":m.get("prob",{})})
    ren9=sorted(sfc14, key=lambda x:max((x.get("概率") or {"home":0}).values()), reverse=True)[:9]
    goals=[]
    for i,m in enumerate(rows[:4],1):
        jc=m.get("china_jc",{})
        goals.append({"序号":i,"场次":m.get("no"),"赛事":m.get("league"),"主队":m.get("home"),"客队":m.get("away"),"总进球":jc.get("总进球",{}).get("推荐",""),"预期":jc.get("总进球",{}).get("预期总进球","")})
    import itertools as _it
    lowmid=[m for m in rows if m.get("risk") in ("低","中")][:8]; combo={}
    for n in (2,3,4,6,8):
        key=f"{n}串1"; combo[key]=[]
        for group in list(_it.combinations(lowmid,n))[:30]:
            combo[key].append(" × ".join([f"{x.get('no')} {x.get('home')}vs{x.get('away')}[{(x.get('china_jc') or {}).get('胜平负',{}).get('推荐','3')}]" for x in group]))
    combo["自由串关"]=combo.get("2串1",[])[:10]+combo.get("3串1",[])[:10]
    plans={"胜负彩14场":sfc14,"任九":ren9,"总进球彩":goals,"几串几":combo,"玩法":play_type,"生成时间":datetime.now().strftime("%Y-%m-%d %H:%M:%S")}
    _stage7_save_json(STAGE7_PLANS, plans); return plans

def _stage7_format(plans):
    lines=[f"🎯 中国竞彩方案｜玩法：{plans.get('玩法','胜平负')}",f"时间：{plans.get('生成时间','')}",""]
    lines.append("【胜负彩14场】")
    for x in plans.get("胜负彩14场",[]): lines.append(f"{x.get('场次')} {x.get('主队')} vs {x.get('客队')} 推荐:{x.get('推荐')} 让球:{x.get('让球')} 总进球:{x.get('总进球')} 风险:{x.get('风险')}")
    lines.append("\n【任九】")
    for x in plans.get("任九",[]): lines.append(f"{x.get('场次')} {x.get('主队')} vs {x.get('客队')} 推荐:{x.get('推荐')}")
    lines.append("\n【总进球彩】")
    for x in plans.get("总进球彩",[]): lines.append(f"{x.get('场次')} {x.get('主队')} vs {x.get('客队')} 总进球:{x.get('总进球')} 预期:{x.get('预期')}")
    lines.append("\n【几串几】")
    for name,arr in plans.get("几串几",{}).items():
        lines.append(name+"：")
        for s in arr[:8]: lines.append("  "+s)
    return "\n".join(lines)

def _stage7_build_page(self):
    tab=QWidget(); root=QVBoxLayout(tab); root.setContentsMargins(8,8,8,8)
    title=QLabel("🎊 中国竞彩 · 官方盘口增强版"); title.setStyleSheet("font-size:22px;font-weight:bold;color:#B03A2E;padding:10px;background:#FFF3CD;border:2px solid #D4AF37;border-radius:12px;"); root.addWidget(title)
    ctrl=QHBoxLayout(); league_box=QComboBox(); league_box.addItems(STAGE7_LEAGUE_OPTIONS); league_box.setMinimumWidth(105)
    play_box=QComboBox(); play_box.addItems(STAGE7_PLAY_TYPES); play_box.setMinimumWidth(105)
    range_box=QComboBox(); range_box.addItems(STAGE7_TRAIN_RANGES); range_box.setMinimumWidth(105)
    search=QLineEdit(); search.setPlaceholderText("搜索队名/联赛/场次")
    days=QSpinBox(); days.setRange(1,14); days.setValue(4); days.setSuffix("天")
    update_btn=QPushButton("📡 更新中国竞彩"); plan_btn=QPushButton("🎯 生成玩法"); copy_btn=QPushButton("📋 复制投注")
    update_btn.setStyleSheet("background:#C0392B;color:white;font-weight:bold;padding:8px;border-radius:8px;"); plan_btn.setStyleSheet("background:#D4AF37;color:#7B241C;font-weight:bold;padding:8px;border-radius:8px;"); copy_btn.setStyleSheet("background:#117A65;color:white;font-weight:bold;padding:8px;border-radius:8px;")
    ctrl.addWidget(QLabel("赛事")); ctrl.addWidget(league_box); ctrl.addWidget(QLabel("玩法")); ctrl.addWidget(play_box); ctrl.addWidget(QLabel("训练")); ctrl.addWidget(range_box); ctrl.addWidget(search,1); ctrl.addWidget(days); ctrl.addWidget(update_btn); ctrl.addWidget(plan_btn); ctrl.addWidget(copy_btn); root.addLayout(ctrl)
    table=QTableWidget(); table.setColumnCount(14); table.setHorizontalHeaderLabels(["场次","赛事","时间","主队","客队","主胜","平","客胜","让球","RQ推荐","总进球","半全场","比分","风险"])
    try: table.horizontalHeader().setSectionResizeMode(QHeaderView.Stretch)
    except Exception: pass
    table.setStyleSheet("QHeaderView::section{background:#B03A2E;color:white;font-weight:bold;} QTableWidget{background:#FFFDF5;gridline-color:#E6C76E;}"); root.addWidget(table,3)
    out=QTextEdit(); out.setReadOnly(True); out.setStyleSheet("font-family:Consolas,Microsoft YaHei;font-size:13px;background:#FFF8E1;border:1px solid #D4AF37;border-radius:8px;"); root.addWidget(out,2)
    def cur_rows(): return _stage7_filter(_stage7_load_matches(), league_box.currentText(), search.text())
    def fill(rows):
        table.setRowCount(len(rows))
        for i,m in enumerate(rows):
            m=_stage7_enrich_match(m,i+1); jc=m.get("china_jc",{}); p=m.get("prob",{})
            vals=[m.get("no",""),m.get("league",""),m.get("time",""),m.get("home",""),m.get("away",""),f"{p.get('home',0)*100:.1f}%",f"{p.get('draw',0)*100:.1f}%",f"{p.get('away',0)*100:.1f}%",jc.get("让球胜平负",{}).get("让球",0),jc.get("让球胜平负",{}).get("推荐",""),jc.get("总进球",{}).get("推荐",""),jc.get("半全场",{}).get("推荐",""),jc.get("比分",{}).get("推荐",""),m.get("risk","")]
            for c,v in enumerate(vals): table.setItem(i,c,QTableWidgetItem(str(v)))
    def refresh():
        rows=cur_rows(); fill(rows); plans=_stage7_generate_all(rows, play_box.currentText()); out.setPlainText(f"当前筛选：{league_box.currentText()}｜玩法：{play_box.currentText()}｜训练：{range_box.currentText()}｜显示{len(rows)}场\n\n"+_stage7_format(plans))
    def do_update():
        res=_stage7_update_china_cache(days.value()); rows=_stage7_filter(res.get("matches",[]),league_box.currentText(),search.text()); fill(rows); plans=_stage7_generate_all(rows, play_box.currentText()); out.setPlainText(f"✅ 中国竞彩更新：{res.get('status')}｜全部{res.get('count')}场｜当前{len(rows)}场\n{res.get('error','')}\n\n"+_stage7_format(plans))
    def do_copy():
        plans=_stage7_generate_all(cur_rows(), play_box.currentText()); lines=[f"中国竞彩｜{league_box.currentText()}｜{play_box.currentText()}","胜负彩14场："]
        for x in plans.get("胜负彩14场",[]): lines.append(f"{x.get('场次')} {x.get('推荐')}")
        lines.append(""); lines.append("任九：")
        for x in plans.get("任九",[]): lines.append(f"{x.get('场次')} {x.get('推荐')}")
        text="\n".join(lines)
        try: QApplication.clipboard().setText(text); QMessageBox.information(self,"已复制","中国竞彩投注格式已复制")
        except Exception: pass
        out.setPlainText(text)
    update_btn.clicked.connect(do_update); plan_btn.clicked.connect(refresh); copy_btn.clicked.connect(do_copy)
    league_box.currentTextChanged.connect(lambda *_: refresh()); play_box.currentTextChanged.connect(lambda *_: refresh()); range_box.currentTextChanged.connect(lambda *_: refresh()); search.textChanged.connect(lambda *_: refresh())
    refresh(); return tab

def _stage7_install():
    cls=globals().get("LotteryApp")
    if not isinstance(cls,type): return False
    old=getattr(cls,"init_ui",None)
