# ============================================================
# V111 CLEAN STAGE9 PATCH — 中国盘口历史记录更新/保存
# 功能：
# 1) 新增 china_handicap_history.json 本地历史库；
# 2) 中国盘口页新增【更新盘口历史】按钮；
# 3) 点击后把当前中国竞彩赛事、手动盘口、SP、让球、总进球、半全场、比分全部归档；
# 4) 自动去重：按 日期+场次+主队+客队 保存；
# 5) 后续如果接入中国竞彩网官方盘口历史接口，只需替换 _stage9_fetch_official_handicap_history。
# ============================================================

STAGE9_HANDICAP_HISTORY_FILE = STAGE7_DIR / "china_handicap_history.json"

def _stage9_history_key(row):
    return "|".join([
        str(row.get("match_date", "")),
        str(row.get("no", "")),
        str(row.get("home", "")),
        str(row.get("away", "")),
    ])

def _stage9_load_history():
    data = _stage7_load_json(STAGE9_HANDICAP_HISTORY_FILE, [])
    return data if isinstance(data, list) else []

def _stage9_save_history(rows):
    by_key = {}
    for r in rows or []:
        if isinstance(r, dict):
            k = _stage9_history_key(r)
            if k.strip("|"):
                by_key[k] = r
    out = list(by_key.values())
    def sk(x):
        return str(x.get("match_date", "")) + " " + str(x.get("no", ""))
    out.sort(key=sk, reverse=True)
    _stage7_save_json(STAGE9_HANDICAP_HISTORY_FILE, out)
    return out

def _stage9_match_date(m):
    dt = str(m.get("datetime") or "")
    if dt:
        return dt[:10]
    t = str(m.get("time") or "")
    return t[:5] if t else datetime.now().strftime("%Y-%m-%d")

def _stage9_row_from_match(m):
    m = _stage8_apply_handicap(m) if "_stage8_apply_handicap" in globals() else _stage7_enrich_match(m)
    jc = m.get("china_jc", {}) or {}
    return {
        "saved_at": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
        "match_date": _stage9_match_date(m),
        "no": m.get("no", ""),
        "league": m.get("league", ""),
        "home": m.get("home", ""),
        "away": m.get("away", ""),
        "prob": m.get("prob", {}),
        "odds_bsd": m.get("odds", {}),
        "spf": jc.get("胜平负", {}),
        "rqspf": jc.get("让球胜平负", {}),
        "total_goals": jc.get("总进球", {}),
        "half_full": jc.get("半全场", {}),
        "score": jc.get("比分", {}),
        "source_status": jc.get("官方盘口状态", ""),
    }

def _stage9_fetch_official_handicap_history(days=30):
    """
    官方盘口历史接口预留位。
    当前没有接入中国竞彩网公开稳定接口时，返回空列表。
    后续可在这里接入：
      - 中国竞彩网赛程/SP接口
      - 竞彩官方历史SP
      - 第三方中国竞彩盘口历史API
    """
    return []

def _stage9_update_handicap_history(days=30):
    old = _stage9_load_history()
    rows = []

    # 1. 官方接口预留
    try:
        rows.extend(_stage9_fetch_official_handicap_history(days))
    except Exception:
        pass

    # 2. 当前中国竞彩缓存归档
    try:
        current = _stage8_load_matches() if "_stage8_load_matches" in globals() else _stage7_load_matches()
        for m in current:
            rows.append(_stage9_row_from_match(m))
    except Exception:
        pass

    # 3. 手动盘口单独归档：如果有手动盘口，但当前缓存没加载，也尽量保存到历史
    try:
        hmap = _stage8_load_handicap_map() if "_stage8_load_handicap_map" in globals() else {}
        current = _stage8_load_matches() if "_stage8_load_matches" in globals() else _stage7_load_matches()
        idx = {_stage8_match_key(m): m for m in current} if "_stage8_match_key" in globals() else {}
        for k, rec in hmap.items():
            m = idx.get(k)
            if m:
                rows.append(_stage9_row_from_match(m))
    except Exception:
        pass

    merged = _stage9_save_history(old + rows)
    return {
        "time": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
        "新增来源记录": len(rows),
        "历史总数": len(merged),
        "保存文件": str(STAGE9_HANDICAP_HISTORY_FILE),
        "说明": "已把当前中国竞彩盘口与手动盘口归档保存。官方历史接口未接入时使用本地历史库。",
    }

def _stage9_build_page(self):
    tab = QWidget()
    root = QVBoxLayout(tab)
    root.setContentsMargins(8,8,8,8)

    title = QLabel("🇨🇳 中国盘口 · 历史记录")
    title.setStyleSheet("font-size:22px;font-weight:bold;color:#B03A2E;padding:10px;background:#FFF3CD;border:2px solid #D4AF37;border-radius:12px;")
    root.addWidget(title)

    top = QHBoxLayout()
    update_btn = QPushButton("📡 更新盘口历史并保存")
    refresh_btn = QPushButton("🔄 查看历史")
    clear_btn = QPushButton("🧹 清空历史")
    update_btn.setStyleSheet("background:#C0392B;color:white;font-weight:bold;padding:8px;border-radius:8px;")
    refresh_btn.setStyleSheet("background:#117A65;color:white;font-weight:bold;padding:8px;border-radius:8px;")
    clear_btn.setStyleSheet("background:#7D3C98;color:white;font-weight:bold;padding:8px;border-radius:8px;")
    top.addWidget(update_btn)
    top.addWidget(refresh_btn)
    top.addWidget(clear_btn)
    top.addStretch()
    root.addLayout(top)

    table = QTableWidget()
    table.setColumnCount(12)
    table.setHorizontalHeaderLabels(["日期","场次","赛事","主队","客队","SPF推荐","SPF SP","让球","RQ推荐","总进球","半全场","比分"])
    try:
        table.horizontalHeader().setSectionResizeMode(QHeaderView.Stretch)
    except Exception:
        pass
    table.setStyleSheet("QHeaderView::section{background:#B03A2E;color:white;font-weight:bold;} QTableWidget{background:#FFFDF5;gridline-color:#E6C76E;}")
    root.addWidget(table, 3)

    out = QTextEdit()
    out.setReadOnly(True)
    out.setStyleSheet("font-family:Consolas,Microsoft YaHei;font-size:13px;background:#FFF8E1;border:1px solid #D4AF37;border-radius:8px;")
    root.addWidget(out, 1)

    def fill():
        rows = _stage9_load_history()
        table.setRowCount(len(rows))
        for i, r in enumerate(rows):
            spf = r.get("spf", {}) or {}
            rq = r.get("rqspf", {}) or {}
            tg = r.get("total_goals", {}) or {}
            hf = r.get("half_full", {}) or {}
            sc = r.get("score", {}) or {}
            vals = [
                r.get("match_date",""), r.get("no",""), r.get("league",""), r.get("home",""), r.get("away",""),
                spf.get("推荐",""), json.dumps(spf.get("SP",{}), ensure_ascii=False),
                rq.get("让球",""), rq.get("推荐",""),
                tg.get("推荐",""), hf.get("推荐",""), sc.get("推荐",""),
            ]
            for c, v in enumerate(vals):
                table.setItem(i, c, QTableWidgetItem(str(v)))
        out.setPlainText(f"中国盘口历史记录：{len(rows)} 条\n保存位置：{STAGE9_HANDICAP_HISTORY_FILE}")

    def do_update():
        res = _stage9_update_handicap_history()
        fill()
        out.append("\n✅ 更新完成：\n" + json.dumps(res, ensure_ascii=False, indent=2))
        try:
            QMessageBox.information(self, "完成", f"中国盘口历史已更新并保存，共 {res.get('历史总数')} 条")
        except Exception:
            pass

    def do_clear():
        try:
            if QMessageBox.question(self, "确认", "确定清空中国盘口历史记录？") != QMessageBox.Yes:
                return
        except Exception:
            pass
        _stage7_save_json(STAGE9_HANDICAP_HISTORY_FILE, [])
        fill()

    update_btn.clicked.connect(do_update)
    refresh_btn.clicked.connect(fill)
    clear_btn.clicked.connect(do_clear)
    fill()
    return tab

def _stage9_install():
    cls = globals().get("LotteryApp")
    if not isinstance(cls, type):
        return False

    cls.stage9_update_handicap_history = staticmethod(_stage9_update_handicap_history)

    old = getattr(cls, "init_ui", None)
    if callable(old) and not getattr(cls, "_stage9_handicap_history_installed", False):
        def init_ui_stage9(self, *args, **kwargs):
            ret = old(self, *args, **kwargs)
            try:
                if hasattr(self, "tabs") and self.tabs is not None:
                    for i in range(self.tabs.count()-1, -1, -1):
                        if self.tabs.tabText(i) == "📚 盘口历史":
                            self.tabs.removeTab(i)
                    self.tabs.addTab(_stage9_build_page(self), "📚 盘口历史")
            except Exception:
                try:
                    logger.warning("Stage9盘口历史页安装失败:\n" + traceback.format_exc())
                except Exception:
                    pass
            return ret
        cls.init_ui = init_ui_stage9
        cls._stage9_handicap_history_installed = True
    return True

try:
    _stage9_install()
except Exception:
    try:
        logger.warning("V111 Clean Stage9 安装失败:\n" + traceback.format_exc())
    except Exception:
        pass

