# ============================================================
# V111 CLEAN STAGE10 PATCH — 把竞彩专业放在体彩旁边
# 功能：
# 1) 启动后自动查找“体彩”相关Tab；
# 2) 把 🇨🇳 中国盘口、📚 盘口历史、🎊 竞彩专业、🇨🇳 中国竞彩 移到体彩后面；
# 3) 若没有找到体彩，则放到福彩/体彩中心附近；仍找不到则保持原位置。
# ============================================================

def _stage10_move_tab_to_after(self, tab_keywords, anchor_keywords):
    try:
        if not hasattr(self, "tabs") or self.tabs is None:
            return False
        tabs = self.tabs

        def find_anchor():
            for kw in anchor_keywords:
                for i in range(tabs.count()):
                    if kw in tabs.tabText(i):
                        return i
            return -1

        moved_any = False
        anchor = find_anchor()
        if anchor < 0:
            return False

        # 逐个移动，保持竞彩页面顺序
        insert_pos = anchor + 1
        for kw in tab_keywords:
            idx = -1
            for i in range(tabs.count()):
                if kw in tabs.tabText(i):
                    idx = i
                    break
            if idx < 0:
                continue

            widget = tabs.widget(idx)
            text = tabs.tabText(idx)
            icon = tabs.tabIcon(idx)
            tip = tabs.tabToolTip(idx)

            tabs.removeTab(idx)

            # 删除后，如果原idx在anchor前面，anchor位置会左移
            anchor = find_anchor()
            if anchor < 0:
                tabs.addTab(widget, icon, text)
                continue

            insert_pos = min(anchor + 1 + (1 if moved_any else 0), tabs.count())
            tabs.insertTab(insert_pos, widget, icon, text)
            tabs.setTabToolTip(insert_pos, tip)
            moved_any = True

        return moved_any
    except Exception:
        try:
            logger.warning("Stage10移动竞彩Tab失败:\n" + traceback.format_exc())
        except Exception:
            pass
        return False

def _stage10_reorder_jingcai_tabs(self):
    # “体彩”优先；如果页面命名是“体彩中心/体彩数据/大乐透”等，也尽量靠近体彩区域
    anchor_keywords = ["体彩", "大乐透", "排列三", "排列五", "七星彩"]
    jingcai_keywords = ["🇨🇳 中国盘口", "📚 盘口历史", "🇨🇳 中国竞彩", "🎊 竞彩专业", "竞彩"]
    return _stage10_move_tab_to_after(self, jingcai_keywords, anchor_keywords)

def _stage10_install():
    cls = globals().get("LotteryApp")
    if not isinstance(cls, type):
        return False

    cls.stage10_reorder_jingcai_tabs = _stage10_reorder_jingcai_tabs

    old_init_ui = getattr(cls, "init_ui", None)
    if callable(old_init_ui) and not getattr(cls, "_stage10_tab_order_installed", False):
        def init_ui_stage10(self, *args, **kwargs):
            ret = old_init_ui(self, *args, **kwargs)
            try:
                _stage10_reorder_jingcai_tabs(self)
            except Exception:
                pass
            return ret
        cls.init_ui = init_ui_stage10
        cls._stage10_tab_order_installed = True

    try:
        logger.info("V111 Clean Stage10 已安装：竞彩页已移动到体彩旁边")
    except Exception:
        pass
    return True

try:
    _stage10_install()
except Exception:
    try:
        logger.warning("V111 Clean Stage10 安装失败:\n" + traceback.format_exc())
    except Exception:
        pass

