# ============================================================
# V111 CLEAN STAGE11 PATCH — 数据更新 + 真实预测 + 竞彩点击详情稳定修复
# 修复重点：
# 1) 福彩/体彩极速API全量更新：20条分页、断点续传、失败重试、每页保存；
# 2) 预测模型重复号码：所有模型生成多组时加入扰动和去重，不再5注完全一样；
# 3) 模型训练/回测：新增快速诊断和自动回测权重，不再只显示“暂无预测历史数据”；
# 4) 竞彩点击：新增中国竞彩比赛详情弹窗，点击表格即可查看对应比赛数据；
# ============================================================

import random as _stage11_random
import hashlib as _stage11_hashlib
import urllib.parse as _stage11_urlparse
import time as _stage11_time

STAGE11_DIR = APP_DIR / "v111_stage11_stable"
STAGE11_DIR.mkdir(parents=True, exist_ok=True)
STAGE11_PROGRESS = STAGE11_DIR / "jisu_resume_progress.json"
STAGE11_LOG = STAGE11_DIR / "jisu_update_log.json"
STAGE11_MODEL_REPORT = STAGE11_DIR / "model_training_report.json"

STAGE11_GAMES = ["双色球", "大乐透", "快乐8", "七星彩", "3D", "排列三", "七乐彩", "排列五"]
STAGE11_CAIPIAO_ID = {"双色球":11, "3D":12, "福彩3D":12, "七乐彩":13, "大乐透":14, "七星彩":15, "排列三":16, "排列五":17, "快乐8":89}
STAGE11_EXPECTED = {"双色球":3576, "大乐透":3028, "快乐8":2000, "七星彩":2600, "3D":7519, "排列三":7519, "七乐彩":3000, "排列五":7519}
STAGE11_PAGE_SIZE = 20
STAGE11_EMPTY_LIMIT = 3
STAGE11_NO_NEW_LIMIT = 15
STAGE11_RETRY = 4

def _stage11_load_json(path, default):
    try:
        p = Path(path)
        if p.exists():
            return json.loads(p.read_text(encoding="utf-8"))
    except Exception:
        pass
    return default

def _stage11_save_json(path, data):
    p = Path(path)
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(json.dumps(data, ensure_ascii=False, indent=2), encoding="utf-8")

def _stage11_history_file():
    for name in ("HISTORY_DATA_FILE", "HISTORY_FILE", "DATA_FILE"):
        v = globals().get(name)
        if v:
            return Path(v)
    return APP_DIR / "history_data.json"

def _stage11_get_key(self=None):
    for attr in ("appkey", "api_key", "jisuapi_key"):
        try:
            v = getattr(self, attr, "")
            if v:
                return str(v).strip()
        except Exception:
            pass
    for name in ("APPKEY", "API_KEY", "JISUAPI_KEY", "JISU_APPKEY"):
        v = globals().get(name)
        if v:
            return str(v).strip()
    return "26c5553dcd7c30d5"

def _stage11_issue(row):
    if not isinstance(row, dict):
        return ""
    for k in ("期号", "issueno", "issue", "expect", "term", "no"):
        v = row.get(k)
        if v not in (None, ""):
            return str(v).strip()
    return ""

def _stage11_code(row):
    if not isinstance(row, dict):
        return ""
    for k in ("开奖号码", "opencode", "number", "openCode", "code", "result"):
        v = row.get(k)
        if v not in (None, ""):
            return str(v).strip()
    return ""

def _stage11_date(row):
    if not isinstance(row, dict):
        return ""
    for k in ("开奖日期", "opendate", "date", "time", "openTime"):
        v = row.get(k)
        if v not in (None, ""):
            return str(v)[:10]
    return ""

def _stage11_normalize_row(row):
    if not isinstance(row, dict):
        return None
    issue = _stage11_issue(row)
    code = _stage11_code(row)
    if not issue or not code:
        return None
    r = dict(row)
    r["期号"] = issue
    r["issueno"] = issue
    r["开奖号码"] = code
    if _stage11_date(r):
        r["开奖日期"] = _stage11_date(r)
    return r

def _stage11_load_history(self=None):
    # 优先使用内存，再读文件
    try:
        if self is not None and isinstance(getattr(self, "history_data", None), dict):
            data = getattr(self, "history_data")
            if data:
                return data
    except Exception:
        pass
    return _stage11_load_json(_stage11_history_file(), {})

def _stage11_save_history(self, data):
    _stage11_save_json(_stage11_history_file(), data)
    try:
        self.history_data = data
    except Exception:
        pass
    try:
        if hasattr(self, "save_history_data"):
            self.save_history_data()
    except Exception:
        pass

def _stage11_merge_game(self, game, rows):
    data = _stage11_load_history(self)
    old = data.get(game, [])
    if game == "3D" and not old:
        old = data.get("福彩3D", [])
    by = {}
    damaged = 0
    repeated = 0
    for r in old if isinstance(old, list) else []:
        nr = _stage11_normalize_row(r)
        if not nr:
            damaged += 1
            continue
        k = _stage11_issue(nr)
        if k in by:
            repeated += 1
        by[k] = nr
    before = len(by)
    for r in rows or []:
        nr = _stage11_normalize_row(r)
        if not nr:
            damaged += 1
            continue
        k = _stage11_issue(nr)
        if k in by:
            repeated += 1
        by[k] = nr
    def sort_key(x):
        s = _stage11_issue(x)
        try:
            return int(re.sub(r"\D", "", s) or "0")
        except Exception:
            return 0
    merged = sorted(by.values(), key=sort_key, reverse=True)
    data[game] = merged
    if game == "3D":
        data["福彩3D"] = merged
    _stage11_save_history(self, data)
    return {"before": before, "after": len(merged), "added": max(0, len(merged)-before), "damaged": damaged, "repeated": repeated}

def _stage11_extract_rows(resp):
    if not isinstance(resp, dict):
        return []
    result = resp.get("result", resp.get("data", resp))
    if isinstance(result, list):
        return [x for x in result if isinstance(x, dict)]
    if isinstance(result, dict):
        for k in ("list", "data", "rows", "history", "items"):
            v = result.get(k)
            if isinstance(v, list):
                return [x for x in v if isinstance(x, dict)]
    return []

def _stage11_request_page(appkey, game, start, timeout=18):
    if "requests" not in globals():
        try:
            import requests as _req
        except Exception as e:
            return None, "requests不可用：" + str(e)
    else:
        _req = globals()["requests"]
    cid = STAGE11_CAIPIAO_ID.get(game)
    if not cid:
        return None, f"未知彩种ID：{game}"
    url = "https://api.jisuapi.com/caipiao/history"
    params = {"appkey": appkey, "caipiaoid": cid, "issueno": "", "start": int(start), "num": STAGE11_PAGE_SIZE}
    last = ""
    for i in range(STAGE11_RETRY):
        try:
            r = _req.get(url, params=params, timeout=timeout)
            r.raise_for_status()
            data = r.json()
            status = str(data.get("status", data.get("code", "0"))) if isinstance(data, dict) else "0"
            if status not in ("0", "200", "") and not (isinstance(data, dict) and data.get("result")):
                return None, f"接口错误 status={status} msg={data.get('msg', data.get('message',''))}"
            return data, ""
        except Exception as e:
            last = str(e)
            _stage11_time.sleep(1.0 + i * 0.7)
    return None, "请求失败：" + last

def _stage11_count(self, game):
    data = _stage11_load_history(self)
    rows = data.get(game, [])
    if game == "3D" and not rows:
        rows = data.get("福彩3D", [])
    if not isinstance(rows, list):
        return 0
    return len({_stage11_issue(x) for x in rows if _stage11_issue(x)})

def _stage11_update_one_game(self, game, force=True, resume=True, max_pages=1200, cb=None):
    appkey = _stage11_get_key(self)
    progress = _stage11_load_json(STAGE11_PROGRESS, {})
    start = int(progress.get(game, 0)) if resume else 0
    before = _stage11_count(self, game)
    expected = STAGE11_EXPECTED.get(game, 0)
    if not force and expected and before >= expected * 0.995:
        return {"状态":"跳过", "彩种":game, "更新前":before, "更新后":before, "理论":expected}
    page = 0
    empty = 0
    no_new = 0
    total_rows = 0
    last_err = ""
    while page < max_pages:
        if cb: cb(f"{game} 正在更新：start={start} 本地={_stage11_count(self, game)}/{expected}")
        resp, err = _stage11_request_page(appkey, game, start)
        if err:
            last_err = err
            progress[game] = start
            _stage11_save_json(STAGE11_PROGRESS, progress)
            break
        rows = _stage11_extract_rows(resp)
        page += 1
        if not rows:
            empty += 1
            start += STAGE11_PAGE_SIZE
            progress[game] = start
            _stage11_save_json(STAGE11_PROGRESS, progress)
            if empty >= STAGE11_EMPTY_LIMIT:
                progress.pop(game, None)
                _stage11_save_json(STAGE11_PROGRESS, progress)
                break
            continue
        empty = 0
        total_rows += len(rows)
        info = _stage11_merge_game(self, game, rows)
        after = info["after"]
        added = info["added"]
        if added <= 0:
            no_new += 1
        else:
            no_new = 0
        if cb: cb(f"{game} 第{page}页 接口{len(rows)}条 新增{added} 当前{after}/{expected}")
        start += STAGE11_PAGE_SIZE
        progress[game] = start
        _stage11_save_json(STAGE11_PROGRESS, progress)
        # 关键：不因 len(rows)<20 就停，只看空页、达到理论、连续无新增
        if expected and after >= expected * 0.995:
            progress.pop(game, None)
            _stage11_save_json(STAGE11_PROGRESS, progress)
            break
        if no_new >= STAGE11_NO_NEW_LIMIT:
            progress.pop(game, None)
            _stage11_save_json(STAGE11_PROGRESS, progress)
            break
    after = _stage11_count(self, game)
    state = "完成" if not last_err else ("部分完成，可继续" if after > before else "失败")
    return {"状态":state, "彩种":game, "更新前":before, "更新后":after, "理论":expected, "完整度":round(after/max(1,expected)*100,2), "接口抓取":total_rows, "页数":page, "断点":progress.get(game), "说明":last_err or "正常结束"}

def _stage11_update_all(self, cb=None):
    log = {}
    for g in STAGE11_GAMES:
        log[g] = _stage11_update_one_game(self, g, force=True, resume=True, cb=cb)
    result = {"时间": datetime.now().strftime("%Y-%m-%d %H:%M:%S"), "日志": log}
    _stage11_save_json(STAGE11_LOG, result)
    return result

def _stage11_health(self):
    lines = ["🛠 Stage11 数据完整性检查", f"时间：{datetime.now().strftime('%Y-%m-%d %H:%M:%S')}", ""]
    total = 0; exp_total = 0
    for g in STAGE11_GAMES:
        c = _stage11_count(self, g); e = STAGE11_EXPECTED.get(g, 0)
        total += min(c, e); exp_total += e
        ok = "✔" if e and c >= e * 0.95 else "✘"
        lines.append(f"{g} {c} / {e} {ok} 完整度 {round(c/max(1,e)*100,2)}%")
    lines.append("")
    lines.append(f"总完整度：{round(total/max(1,exp_total)*100,2)}%")
    return "\n".join(lines)

# ---------- 预测模型修复：不再重复同一组 ----------
def _stage11_parse_nums_from_history(self, game):
    data = _stage11_load_history(self)
    rows = data.get(game, [])
    if game == "3D" and not rows:
        rows = data.get("福彩3D", [])
    draws = []
    for r in rows if isinstance(rows, list) else []:
        code = _stage11_code(r)
        if not code:
            continue
        try:
            vals = parse_draw_numbers(code) if "parse_draw_numbers" in globals() else [int(x) for x in re.findall(r"\d+", code)]
        except Exception:
            vals = [int(x) for x in re.findall(r"\d+", code)]
        if vals:
            draws.append(vals)
    return draws

def _stage11_pool(game, area):
    if game == "双色球":
        return list(range(1,34)) if area == "red" else list(range(1,17))
    if game == "大乐透":
        return list(range(1,36)) if area == "front" else list(range(1,13))
    if game == "快乐8":
        return list(range(1,81))
    if game == "七乐彩":
        return list(range(1,31))
    if game == "七星彩":
        return list(range(0,15)) if area == "pos7" else list(range(0,10))
    return list(range(0,10))

def _stage11_area_values(game, vals, area):
    vals = [int(x) for x in vals]
    if game == "双色球":
        return vals[:6] if area == "red" else vals[6:7]
    if game == "大乐透":
        return vals[:5] if area == "front" else vals[5:7]
    if game == "快乐8":
        return vals[:20]
    if game == "七乐彩":
        return vals[:7]
    if game in ("3D", "排列三", "排列五", "七星彩"):
        idx = int(str(area).replace("pos","") or "1") - 1
        return vals[idx:idx+1] if 0 <= idx < len(vals) else []
    return vals

def _stage11_weighted_sample(pool, weights, k, rng):
    pool = list(pool)
    weights = [max(0.001, float(weights.get(n, 1.0))) for n in pool]
    out = []
    while pool and len(out) < k:
        s = sum(weights)
        x = rng.random() * s
        acc = 0
        chosen_i = 0
        for i,w in enumerate(weights):
            acc += w
            if acc >= x:
                chosen_i = i; break
        out.append(pool.pop(chosen_i))
        weights.pop(chosen_i)
    return sorted(out)

def _stage11_predict_area(self, game, area, count, model_key=None, salt=0):
    draws = _stage11_parse_nums_from_history(self, game)
    pool = _stage11_pool(game, area)
    seed_src = f"{game}|{area}|{model_key}|{salt}|{time.time_ns()}"
    seed = int(_stage11_hashlib.md5(seed_src.encode("utf-8")).hexdigest()[:8], 16)
    rng = _stage11_random.Random(seed)
    # 没有历史时也随机合法号码，不能固定同一组
    if not draws:
        return sorted(rng.sample(pool, min(count, len(pool))))
    recent = draws[:240]
    weights = {n: 1.0 for n in pool}
    # 模型差异：不同模型使用不同冷热/遗漏/趋势偏好
    key_num = int(re.sub(r"\D","", str(model_key or "6")) or 6)
    for idx, vals in enumerate(recent):
        av = _stage11_area_values(game, vals, area)
        decay = 1.0 / (1.0 + idx * 0.025)
        for n in av:
            if n in weights:
                if key_num % 5 == 0:      # 冷号偏好
                    weights[n] -= 0.35 * decay
                elif key_num % 5 == 1:    # 热号偏好
                    weights[n] += 1.20 * decay
                elif key_num % 5 == 2:    # 平衡
                    weights[n] += 0.55 * decay
                elif key_num % 5 == 3:    # 近期趋势
                    weights[n] += (1.80 if idx < 30 else 0.25) * decay
                else:                      # 遗漏回补
                    weights[n] += (0.10 if idx < 20 else 0.80) * decay
    # 随机扰动，保证多注不完全重复
    for n in weights:
        weights[n] = max(0.01, weights[n] * rng.uniform(0.75, 1.35))
    return _stage11_weighted_sample(pool, weights, count, rng)

def _stage11_predict_for_game(self, game_type, model_key=None):
    if model_key is None:
        try:
            model_key = self._best_model_key(game_type)
        except Exception:
            model_key = "6"
    salt = getattr(self, "_stage11_predict_salt", 0) + 1
    self._stage11_predict_salt = salt
    if game_type == "双色球":
        return {"red": _stage11_predict_area(self, game_type, "red", 6, model_key, salt), "blue": _stage11_predict_area(self, game_type, "blue", 1, model_key, salt+101)[0]}
    if game_type == "大乐透":
        return {"front": _stage11_predict_area(self, game_type, "front", 5, model_key, salt), "back": _stage11_predict_area(self, game_type, "back", 2, model_key, salt+101)}
    if game_type == "快乐8":
        return {"main": _stage11_predict_area(self, game_type, "main", 10, model_key, salt)}
    if game_type == "七乐彩":
        return {"main": _stage11_predict_area(self, game_type, "main", 7, model_key, salt)}
    n = {"3D":3, "排列三":3, "排列五":5, "七星彩":7}.get(game_type, 3)
    return {"pos": [_stage11_predict_area(self, game_type, f"pos{i+1}", 1, model_key, salt+i)[0] for i in range(n)]}

def _stage11_backtest_models(self, game):
    draws = _stage11_parse_nums_from_history(self, game)
    sample = min(60, max(0, len(draws)-20))
    report = {"game":game, "history":len(draws), "sample":sample, "models":{}}
    if sample < 10:
        return report
    # 轻量回测：用不同model_key生成，看与下一期开奖重合数均值
    for k in list(PREDICTION_MODELS.keys())[:30] if "PREDICTION_MODELS" in globals() else [str(i) for i in range(1,11)]:
        hits = []
        for i in range(sample):
            # 这里只做稳定评分，不污染真实预测日志
            try:
                pred = _stage11_predict_for_game(self, game, k)
                actual = set(draws[i])
                if "red" in pred:
                    pset = set(pred["red"] + [pred["blue"]])
                elif "front" in pred:
                    pset = set(pred["front"] + pred["back"])
                elif "main" in pred:
                    pset = set(pred["main"])
                else:
                    pset = set(pred["pos"])
                hits.append(len(pset & actual))
            except Exception:
                pass
        if hits:
            report["models"][str(k)] = {"avg_hit": round(sum(hits)/len(hits),3), "total": len(hits)}
    _stage11_save_json(STAGE11_MODEL_REPORT, report)
    return report

def _stage11_model_report_text(self, game):
    r = _stage11_backtest_models(self, game)
    if r.get("sample",0) < 10:
        return f"模型诊断：{game} 历史样本 {r.get('history',0)} 期，样本不足，已使用扰动冷热模型生成。"
    best = sorted(r.get("models", {}).items(), key=lambda kv: kv[1].get("avg_hit",0), reverse=True)[:5]
    lines = [f"模型诊断：{game} 历史 {r.get('history')} 期，回测样本 {r.get('sample')} 期", "Top模型："]
    for k,v in best:
        name = PREDICTION_MODELS.get(k,{}).get("name",k) if "PREDICTION_MODELS" in globals() else k
        lines.append(f"{name}: 平均命中 {v.get('avg_hit')}")
    return "\n".join(lines)

# ---------- 竞彩点击详情 ----------
def _stage11_show_match_detail(self, m):
    m = _stage8_apply_handicap(m) if "_stage8_apply_handicap" in globals() else (_stage7_enrich_match(m) if "_stage7_enrich_match" in globals() else m)
    dlg = QDialog(self)
