# ---------- 安装 ----------
def _stage11_install():
    cls = globals().get("LotteryApp")
    if not isinstance(cls, type):
        return False
    # 数据更新入口覆盖
    cls.stage11_update_all = _stage11_update_all
    cls.stage11_update_one_game = _stage11_update_one_game
    cls.stage11_health = _stage11_health
    cls.update_all_history_full = lambda self, *a, **k: _stage11_update_all(self)
    cls.full_update_to_latest = lambda self, *a, **k: _stage11_update_all(self)
    # 预测入口覆盖
    cls.predict_for_game = _stage11_predict_for_game
    cls.stage11_backtest_models = _stage11_backtest_models
    cls.stage11_model_report_text = _stage11_model_report_text
    cls.stage11_show_match_detail = _stage11_show_match_detail

    old_report = getattr(cls, "get_model_accuracy_report", None)
    def report_wrapper(self, game):
        try:
            base = old_report(self, game) if callable(old_report) else ""
        except Exception:
            base = ""
        diag = _stage11_model_report_text(self, game)
        return (base + "\n\n" + diag).strip()
    cls.get_model_accuracy_report = report_wrapper

    old_init = getattr(cls, "init_ui", None)
    if callable(old_init) and not getattr(cls, "_stage11_stable_installed", False):
        def init_ui_stage11(self, *args, **kwargs):
            ret = old_init(self, *args, **kwargs)
            try:
                if hasattr(self, "tabs") and self.tabs is not None:
                    tab = QWidget()
                    lay = QVBoxLayout(tab)
                    title = QLabel("🛠 Stage11 稳定修复：数据更新 + 真实预测")
                    title.setStyleSheet("font-size:20px;font-weight:bold;color:#145A32;padding:8px;")
                    lay.addWidget(title)
                    row = QHBoxLayout()
                    update_btn = QPushButton("📡 极速API全量补档")
                    check_btn = QPushButton("🧪 检查完整度")
                    reset_btn = QPushButton("清空断点")
                    update_btn.setStyleSheet("background:#C0392B;color:white;font-weight:bold;padding:8px;")
                    check_btn.setStyleSheet("background:#117A65;color:white;font-weight:bold;padding:8px;")
                    reset_btn.setStyleSheet("background:#7D3C98;color:white;font-weight:bold;padding:8px;")
                    row.addWidget(update_btn); row.addWidget(check_btn); row.addWidget(reset_btn); row.addStretch()
                    lay.addLayout(row)
                    out = QTextEdit(); out.setReadOnly(True)
                    out.setStyleSheet("font-family:Consolas,Microsoft YaHei;font-size:13px;")
                    lay.addWidget(out,1)
                    def cb(msg):
                        out.append(str(msg))
                        try: QApplication.processEvents()
                        except Exception: pass
                    def do_update():
                        out.setPlainText("开始极速API全量补档……\n")
                        res = _stage11_update_all(self, cb=cb)
                        out.append("\n完成：\n" + json.dumps(res, ensure_ascii=False, indent=2))
                    def do_check():
                        out.setPlainText(_stage11_health(self))
                    def do_reset():
                        _stage11_save_json(STAGE11_PROGRESS, {})
                        out.setPlainText("已清空断点，下次从start=0开始。")
                    update_btn.clicked.connect(do_update); check_btn.clicked.connect(do_check); reset_btn.clicked.connect(do_reset)
                    for i in range(self.tabs.count()-1,-1,-1):
                        if "Stage11" in self.tabs.tabText(i):
                            self.tabs.removeTab(i)
                    self.tabs.addTab(tab, "🛠 Stage11修复")
            except Exception:
                try: logger.warning("Stage11页面安装失败:\n"+traceback.format_exc())
                except Exception: pass
            return ret
        cls.init_ui = init_ui_stage11
        cls._stage11_stable_installed = True
    return True

try:
    _stage11_install()
except Exception:
    try: logger.warning("V111 Clean Stage11 安装失败:\n"+traceback.format_exc())
    except Exception: pass

