# ============================================================
# V111 CLEAN STAGE12 PATCH — 机器学习模型完整性 + 胆码推荐完整性
# 功能：
# 1) 机器学习模型可用性检测：已安装/缺失/回退；
# 2) 训练报告：历史期数、样本数、Top模型、平均命中；
# 3) 统一模型生成：同一模型多注不重复；
# 4) 胆码推荐：胆码、拖码、排除码、冷热胆、遗漏胆、趋势胆、综合胆；
# 5) 支持：双色球、大乐透、快乐8、七乐彩、福彩3D、排列三、排列五、七星彩；
# 6) 新增“🧠 ML&胆码”页面，统一查看和复制。
# ============================================================

STAGE12_DIR = APP_DIR / "v111_stage12_ml_danma"
STAGE12_DIR.mkdir(parents=True, exist_ok=True)
STAGE12_REPORT_FILE = STAGE12_DIR / "ml_model_report.json"
STAGE12_DANMA_FILE = STAGE12_DIR / "danma_report.json"

STAGE12_GAMES = ["双色球", "大乐透", "快乐8", "七乐彩", "3D", "排列三", "排列五", "七星彩"]

STAGE12_MODEL_IMPORTS = {
    "线性回归": ("sklearn.linear_model", "LinearRegression"),
    "贝叶斯概率": ("sklearn.naive_bayes", "GaussianNB"),
    "随机森林": ("sklearn.ensemble", "RandomForestClassifier"),
    "梯度提升": ("sklearn.ensemble", "GradientBoostingClassifier"),
    "K近邻": ("sklearn.neighbors", "KNeighborsClassifier"),
    "SVM": ("sklearn.svm", "SVC"),
    "XGBoost": ("xgboost", "XGBClassifier"),
    "LightGBM": ("lightgbm", "LGBMClassifier"),
    "CatBoost": ("catboost", "CatBoostClassifier"),
}

def _stage12_json_save(path, data):
    Path(path).parent.mkdir(parents=True, exist_ok=True)
    Path(path).write_text(json.dumps(data, ensure_ascii=False, indent=2), encoding="utf-8")

def _stage12_model_availability():
    out = {}
    for name, spec in STAGE12_MODEL_IMPORTS.items():
        mod, cls = spec
        try:
            m = __import__(mod, fromlist=[cls])
            getattr(m, cls)
            out[name] = {"状态": "可用", "原因": ""}
        except Exception as e:
            out[name] = {"状态": "缺失", "原因": str(e)}
    out["冷热遗漏回退模型"] = {"状态": "可用", "原因": "标准库内置"}
    out["趋势扰动模型"] = {"状态": "可用", "原因": "标准库内置"}
    out["综合加权模型"] = {"状态": "可用", "原因": "标准库内置"}
    return out

def _stage12_draws(self, game):
    if "_stage11_parse_nums_from_history" in globals():
        return _stage11_parse_nums_from_history(self, game)
    data = _stage11_load_history(self) if "_stage11_load_history" in globals() else {}
    rows = data.get(game, [])
    draws = []
    for r in rows if isinstance(rows, list) else []:
        code = _stage11_code(r) if "_stage11_code" in globals() else str(r.get("开奖号码", ""))
        vals = [int(x) for x in re.findall(r"\d+", code)]
        if vals:
            draws.append(vals)
    return draws

def _stage12_ranges(game):
    if game == "双色球":
        return {"red": (1, 33, 6), "blue": (1, 16, 1)}
    if game == "大乐透":
        return {"front": (1, 35, 5), "back": (1, 12, 2)}
    if game == "快乐8":
        return {"main": (1, 80, 10)}
    if game == "七乐彩":
        return {"main": (1, 30, 7)}
    if game in ("3D", "排列三"):
        return {"pos1": (0, 9, 1), "pos2": (0, 9, 1), "pos3": (0, 9, 1)}
    if game == "排列五":
        return {f"pos{i}": (0, 9, 1) for i in range(1, 6)}
    if game == "七星彩":
        d = {f"pos{i}": (0, 9, 1) for i in range(1, 7)}
        d["pos7"] = (0, 14, 1)
        return d
    return {"main": (1, 33, 6)}

def _stage12_area_vals(game, vals, area):
    vals = [int(x) for x in vals]
    if game == "双色球":
        return vals[:6] if area == "red" else vals[6:7]
    if game == "大乐透":
        return vals[:5] if area == "front" else vals[5:7]
    if game == "快乐8":
        return vals[:20]
    if game == "七乐彩":
        return vals[:7]
    if game in ("3D", "排列三", "排列五", "七星彩"):
        i = int(area.replace("pos", "")) - 1
        return vals[i:i+1] if 0 <= i < len(vals) else []
    return vals

def _stage12_stats_for_area(draws, game, area):
    lo, hi, need = _stage12_ranges(game)[area]
    pool = list(range(lo, hi + 1))
    freq = {n: 0 for n in pool}
    last_seen = {n: None for n in pool}
    recent_weight = {n: 0.0 for n in pool}
    for idx, vals in enumerate(draws):
        arr = _stage12_area_vals(game, vals, area)
        for n in arr:
            if n in freq:
                freq[n] += 1
                if last_seen[n] is None:
                    last_seen[n] = idx
                recent_weight[n] += 1.0 / (1.0 + idx * 0.04)
    omission = {n: (last_seen[n] if last_seen[n] is not None else len(draws) + 10) for n in pool}
    maxf = max(freq.values()) if freq else 1
    maxo = max(omission.values()) if omission else 1
    score = {}
    for n in pool:
        hot = freq[n] / max(1, maxf)
        miss = omission[n] / max(1, maxo)
        trend = recent_weight[n]
        score[n] = round(hot * 0.42 + miss * 0.28 + trend * 0.30, 6)
    return {"pool": pool, "freq": freq, "omission": omission, "recent_weight": recent_weight, "score": score, "need": need}

def _stage12_top_numbers(stats, mode, count):
    pool = stats["pool"]
    if mode == "hot":
        key = lambda n: (stats["freq"][n], -stats["omission"][n], n)
    elif mode == "cold":
        key = lambda n: (-stats["freq"][n], stats["omission"][n], -n)
    elif mode == "omission":
        key = lambda n: (stats["omission"][n], stats["freq"][n], n)
    elif mode == "trend":
        key = lambda n: (stats["recent_weight"][n], stats["freq"][n], n)
    else:
        key = lambda n: (stats["score"][n], stats["freq"][n], stats["omission"][n], n)
    return sorted(pool, key=key, reverse=True)[:count]

def _stage12_recommend_danma(self, game, dan_count=None, tuo_count=None):
    draws = _stage12_draws(self, game)
    result = {"game": game, "history": len(draws), "areas": {}, "说明": "胆码=高权重候选；拖码=辅助覆盖；排除码=低权重/短期不优先。"}
    for area, (lo, hi, need) in _stage12_ranges(game).items():
        stats = _stage12_stats_for_area(draws, game, area)
        dc = dan_count if dan_count is not None else max(1, min(need - 1 if need > 1 else 1, 3))
        tc = tuo_count if tuo_count is not None else min(len(stats["pool"]), max(need * 3, 8))
        hot = _stage12_top_numbers(stats, "hot", max(dc, 5))
        omission = _stage12_top_numbers(stats, "omission", max(dc, 5))
        trend = _stage12_top_numbers(stats, "trend", max(dc, 5))
        combo = _stage12_top_numbers(stats, "combo", max(tc, need + dc + 4))
        cold = _stage12_top_numbers(stats, "cold", 8)
        # 胆码取综合榜前dc，兼顾热号/遗漏/趋势交集
        dan = []
        for n in combo + hot + omission + trend:
            if n not in dan:
                dan.append(n)
            if len(dan) >= dc:
                break
        tuo = [n for n in combo if n not in dan][:tc]
        exclude = [n for n in cold if n not in dan and n not in tuo][:8]
        result["areas"][area] = {
            "需要个数": need,
            "胆码": sorted(dan),
            "拖码": sorted(tuo),
            "排除码": sorted(exclude),
            "热号候选": hot,
            "遗漏候选": omission,
            "趋势候选": trend,
            "综合候选": combo,
        }
    _stage12_json_save(STAGE12_DANMA_FILE, result)
    return result

def _stage12_format_danma(rep):
    lines = [f"🎯 {rep.get('game')} 胆码推荐", f"历史样本：{rep.get('history')}期", rep.get("说明", ""), ""]
    for area, d in rep.get("areas", {}).items():
        lines.append(f"【{area}】")
        lines.append("胆码：" + ",".join(f"{x:02d}" for x in d.get("胆码", [])))
        lines.append("拖码：" + ",".join(f"{x:02d}" for x in d.get("拖码", [])))
        lines.append("排除：" + ",".join(f"{x:02d}" for x in d.get("排除码", [])))
        lines.append("")
    return "\n".join(lines)

def _stage12_generate_with_danma(self, game, groups=5):
    rep = _stage12_recommend_danma(self, game)
    out = []
    rng = random.Random(int(time.time() * 1000) % 9999999)
    for i in range(groups):
        ticket = {}
        for area, d in rep.get("areas", {}).items():
            need = d.get("需要个数", 1)
            dan = list(d.get("胆码", []))
            tuo = list(d.get("拖码", []))
            chosen = dan[:min(len(dan), max(0, need-1 if need > 1 else 1))]
            rest_need = need - len(chosen)
            pool = [x for x in tuo if x not in chosen]
            rng.shuffle(pool)
            chosen += pool[:rest_need]
            ticket[area] = sorted(chosen)
        out.append(ticket)
    # 去重
    uniq = []
    seen = set()
    for t in out:
        key = json.dumps(t, ensure_ascii=False, sort_keys=True)
        if key not in seen:
            seen.add(key); uniq.append(t)
    return uniq

def _stage12_model_full_report(self, game):
    availability = _stage12_model_availability()
    draws = _stage12_draws(self, game)
    back = _stage11_backtest_models(self, game) if "_stage11_backtest_models" in globals() else {"models": {}, "sample": 0}
    report = {
        "game": game,
        "history": len(draws),
        "availability": availability,
        "backtest": back,
        "danma": _stage12_recommend_danma(self, game),
        "updated_at": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
    }
    _stage12_json_save(STAGE12_REPORT_FILE, report)
    return report

def _stage12_format_model_report(report):
    lines = [f"🧠 {report.get('game')} 机器学习完整性报告", f"历史样本：{report.get('history')}期", ""]
    lines.append("【模型可用性】")
    for k, v in report.get("availability", {}).items():
        mark = "✅" if v.get("状态") == "可用" else "⚠"
        lines.append(f"{mark} {k}: {v.get('状态')}")
    lines.append("")
    bt = report.get("backtest", {})
    lines.append(f"【轻量回测】样本：{bt.get('sample', 0)}")
    models = bt.get("models", {})
    for k, v in sorted(models.items(), key=lambda kv: kv[1].get("avg_hit", 0), reverse=True)[:8]:
        name = PREDICTION_MODELS.get(k, {}).get("name", k) if "PREDICTION_MODELS" in globals() else k
        lines.append(f"{name}: 平均命中 {v.get('avg_hit')}")
    lines.append("")
    lines.append(_stage12_format_danma(report.get("danma", {})))
    return "\n".join(lines)

def _stage12_ticket_text(game, tickets):
    lines = [f"🎲 {game} 胆码辅助生成 {len(tickets)} 注", ""]
    for idx, t in enumerate(tickets, 1):
        parts = []
        for area, nums in t.items():
            parts.append(f"{area}: " + ",".join(f"{x:02d}" for x in nums))
        lines.append(f"{idx}. " + " | ".join(parts))
    return "\n".join(lines)

def _stage12_build_page(self):
    tab = QWidget()
    root = QVBoxLayout(tab)
    root.setContentsMargins(8,8,8,8)
    title = QLabel("🧠 机器学习 & 胆码推荐完整性")
    title.setStyleSheet("font-size:22px;font-weight:bold;color:#145A32;padding:10px;background:#EAF7EA;border:2px solid #1E8449;border-radius:12px;")
    root.addWidget(title)

    ctrl = QHBoxLayout()
    game_box = QComboBox(); game_box.addItems(STAGE12_GAMES)
    groups = QSpinBox(); groups.setRange(1, 50); groups.setValue(5); groups.setSuffix(" 注")
    report_btn = QPushButton("🧪 模型完整性检测")
    dan_btn = QPushButton("🎯 胆码推荐")
    gen_btn = QPushButton("🎲 胆码生成")
    copy_btn = QPushButton("📋 复制")
    for b, c in [(report_btn,"#117A65"),(dan_btn,"#B7950B"),(gen_btn,"#C0392B"),(copy_btn,"#2471A3")]:
        b.setStyleSheet(f"background:{c};color:white;font-weight:bold;padding:8px;border-radius:8px;")
    ctrl.addWidget(QLabel("玩法")); ctrl.addWidget(game_box); ctrl.addWidget(groups)
    ctrl.addWidget(report_btn); ctrl.addWidget(dan_btn); ctrl.addWidget(gen_btn); ctrl.addWidget(copy_btn); ctrl.addStretch()
    root.addLayout(ctrl)

    out = QTextEdit(); out.setReadOnly(True)
    out.setStyleSheet("font-family:Consolas,Microsoft YaHei;font-size:13px;background:#FCFFFC;border:1px solid #82E0AA;border-radius:8px;")
    root.addWidget(out, 1)

    state = {"text": ""}

    def set_text(t):
        state["text"] = t
        out.setPlainText(t)

    def do_report():
        rep = _stage12_model_full_report(self, game_box.currentText())
        set_text(_stage12_format_model_report(rep))

    def do_dan():
        rep = _stage12_recommend_danma(self, game_box.currentText())
        set_text(_stage12_format_danma(rep))

    def do_gen():
        tickets = _stage12_generate_with_danma(self, game_box.currentText(), groups.value())
        set_text(_stage12_ticket_text(game_box.currentText(), tickets))

    def do_copy():
        try:
            QApplication.clipboard().setText(state.get("text", ""))
            QMessageBox.information(self, "已复制", "内容已复制")
        except Exception:
            pass

    report_btn.clicked.connect(do_report)
    dan_btn.clicked.connect(do_dan)
    gen_btn.clicked.connect(do_gen)
    copy_btn.clicked.connect(do_copy)
    do_report()
    return tab

def _stage12_install():
    cls = globals().get("LotteryApp")
    if not isinstance(cls, type):
        return False
    cls.stage12_model_full_report = _stage12_model_full_report
    cls.stage12_recommend_danma = _stage12_recommend_danma
    cls.stage12_generate_with_danma = _stage12_generate_with_danma

    old_predict = getattr(cls, "predict_for_game", None)
    def predict_with_stage12(self, game_type, model_key=None):
        # 优先用Stage11的真实扰动预测；失败则用胆码生成兜底
        try:
            if callable(old_predict):
                return old_predict(self, game_type, model_key)
        except Exception:
            pass
        tickets = _stage12_generate_with_danma(self, game_type, 1)
        return tickets[0] if tickets else {}
    cls.predict_for_game = predict_with_stage12

    old_init = getattr(cls, "init_ui", None)
    if callable(old_init) and not getattr(cls, "_stage12_ml_danma_installed", False):
        def init_ui_stage12(self, *args, **kwargs):
            ret = old_init(self, *args, **kwargs)
            try:
                if hasattr(self, "tabs") and self.tabs is not None:
                    for i in range(self.tabs.count()-1, -1, -1):
                        if "ML&胆码" in self.tabs.tabText(i) or "机器学习" in self.tabs.tabText(i):
                            self.tabs.removeTab(i)
                    self.tabs.addTab(_stage12_build_page(self), "🧠 ML&胆码")
            except Exception:
                try: logger.warning("Stage12 ML胆码页面安装失败:\n"+traceback.format_exc())
                except Exception: pass
            return ret
        cls.init_ui = init_ui_stage12
        cls._stage12_ml_danma_installed = True
    return True

try:
    _stage12_install()
except Exception:
    try: logger.warning("V111 Clean Stage12 安装失败:\n"+traceback.format_exc())
    except Exception: pass

