    for b,c in [(update,"#C0392B"),(gen,"#D4AF37"),(copy,"#117A65")]:
        b.setStyleSheet(f"background:{c};color:white;font-weight:bold;padding:8px;border-radius:8px;")
    top.addWidget(QLabel("赛事")); top.addWidget(league); top.addWidget(search,1); top.addWidget(update); top.addWidget(gen); top.addWidget(copy)
    root.addLayout(top)
    table=QTableWidget(); table.setColumnCount(15)
    table.setHorizontalHeaderLabels(["场次","赛事","时间","主队","客队","主胜%","平%","客胜%","胜负彩","让球","RQ","进球","比分","半全场","风险"])
    try: table.horizontalHeader().setSectionResizeMode(QHeaderView.Stretch)
    except Exception: pass
    table.setStyleSheet("QHeaderView::section{background:#B03A2E;color:white;font-weight:bold;} QTableWidget{background:#FFFDF5;gridline-color:#E6C76E;}")
    root.addWidget(table,3)
    out=QTextEdit(); out.setReadOnly(True)
    out.setStyleSheet("font-family:Consolas,Microsoft YaHei;font-size:13px;background:#FFF8E1;border:1px solid #D4AF37;border-radius:8px;")
    root.addWidget(out,2)
    state={"rows":[],"text":""}
    def rows():
        return _stage13_filter(_stage13_load_ai_matches(), league.currentText(), search.text())
    def fill(rs):
        state["rows"]=rs; table.setRowCount(len(rs))
        for i,m in enumerate(rs):
            ai=m["ai_jc"]; p=ai["胜平负"]["概率"]
            vals=[m.get("no",""),m.get("league",""),m.get("time",""),m.get("home",""),m.get("away",""),
                  f"{p.get('home',0)*100:.1f}%",f"{p.get('draw',0)*100:.1f}%",f"{p.get('away',0)*100:.1f}%",
                  ai["胜平负"]["复式"],ai["让球胜平负"]["让球"],ai["让球胜平负"]["推荐"],
                  ai["进球彩"]["推荐"],ai["比分"]["推荐"],ai["半全场"]["推荐"],ai["胜平负"]["风险"]]
            for c,v in enumerate(vals): table.setItem(i,c,QTableWidgetItem(str(v)))
    def refresh():
        rs=rows(); fill(rs); plans=_stage13_generate_ai_plan(rs); txt=_stage13_format_plan(plans); state["text"]=txt; out.setPlainText(txt)
    def do_update():
        if "_stage7_update_china_cache" in globals(): _stage7_update_china_cache(4)
        if "_stage9_update_handicap_history" in globals(): _stage9_update_handicap_history()
        refresh(); out.append("\n✅ 已更新中国赛事/SP缓存与盘口历史库")
    def do_copy():
        plans=_stage13_generate_ai_plan(state["rows"])
        lines=["胜负彩14场："]+[f"{x['场次']} {x['胜负彩']}" for x in plans.get("胜负彩14场",[])]
        lines+=["","任九："]+[f"{x['场次']} {x['胜负彩']}" for x in plans.get("任九",[])]
        txt="\n".join(lines)
        try: QApplication.clipboard().setText(txt); QMessageBox.information(self,"已复制","已复制投注格式")
        except Exception: pass
        out.setPlainText(txt)
    def show_detail(row,col):
        if 0<=row<len(state["rows"]):
            if "_stage11_show_match_detail" in globals(): _stage11_show_match_detail(self,state["rows"][row])
    update.clicked.connect(do_update); gen.clicked.connect(refresh); copy.clicked.connect(do_copy)
    league.currentTextChanged.connect(lambda *_: refresh()); search.textChanged.connect(lambda *_: refresh())
    table.cellDoubleClicked.connect(show_detail); table.currentCellChanged.connect(lambda r,c,pr,pc: None)
    refresh()
    return tab

