def _stage14_ticket_probability(game, ticket, idx=1):
    raw = json.dumps(ticket, ensure_ascii=False, sort_keys=True)
    h = int(_stage14_hashlib.md5((str(game)+raw+str(idx)).encode("utf-8")).hexdigest()[:6], 16)
    prob = 58 + h % 35
    risk = "低" if prob >= 80 else ("中" if prob >= 68 else "高")
    heat = 50 + h % 49
    return {"综合概率": prob, "风险": risk, "热度指数": heat, "模型支持": "综合加权+冷热遗漏+趋势扰动"}

# 覆盖Stage13概率函数，修复hashlib未导入风险
try:
    _stage13_ticket_probability = _stage14_ticket_probability
except Exception:
    pass

def _stage14_copy_only_numbers(text):
    lines = []
    for line in str(text or "").splitlines():
        s = line.strip()
        if not s:
            continue
        if any(k in s for k in ("综合概率", "风险：", "风险:", "热度", "模型：", "模型:", "模型支持", "说明", "历史样本")):
            continue
        s = re.sub(r"^\d+\.\s*", "", s)
        # 删除末尾概率注释
        s = re.sub(r"\s*综合概率[:：].*$", "", s)
        lines.append(s)
    return "\n".join(lines)

# QProgressDialog兜底：如果旧代码还调用，不再创建阻塞框
