def _stage14_patch_jingcai_tables(self):
    # 找到竞彩AI/中国盘口页面里的QTableWidget，给单击绑定详情
    try:
        if not hasattr(self, "tabs") or self.tabs is None:
            return
        for i in range(self.tabs.count()):
            text = self.tabs.tabText(i)
            if "竞彩" not in text and "盘口" not in text:
                continue
            page = self.tabs.widget(i)
            tables = page.findChildren(QTableWidget)
            for tb in tables:
                if getattr(tb, "_stage14_click_detail_bound", False):
                    continue
                def make_handler(table):
                    def on_cell_clicked(r, c):
                        try:
                            # 优先从Stage13当前加载数据取同row
                            rows = _stage13_filter(_stage13_load_ai_matches(), "全部赛事", "") if "_stage13_load_ai_matches" in globals() else []
                            if 0 <= r < len(rows):
                                _stage14_show_match_detail_final(self, rows[r])
                        except Exception:
                            pass
                    return on_cell_clicked
                tb.cellClicked.connect(make_handler(tb))
                tb._stage14_click_detail_bound = True
    except Exception:
        pass

def _stage14_install():
    cls = globals().get("LotteryApp")
    if not isinstance(cls, type):
        return False

    # 最终绑定数据更新入口
    cls.update_all_history_full = _stage14_final_update_all
    cls.full_update_to_latest = _stage14_final_update_all
    cls.update_all_to_latest = _stage14_final_update_all
    cls.fetch_full_history = _stage14_final_update_all
    cls.stage14_health = _stage14_final_health
    cls.stage14_copy_only_numbers = staticmethod(_stage14_copy_only_numbers)

    # 复制兜底
    old_clip = getattr(cls, "copy_to_clipboard", None)
    def copy_to_clipboard_stage14(self, text, *args, **kwargs):
        filtered = _stage14_copy_only_numbers(text)
        try:
            QApplication.clipboard().setText(filtered)
            return True
        except Exception:
            if callable(old_clip):
                return old_clip(self, filtered, *args, **kwargs)
            return False
    cls.copy_to_clipboard = copy_to_clipboard_stage14

    old_init = getattr(cls, "init_ui", None)
    if callable(old_init) and not getattr(cls, "_stage14_bugfix_installed", False):
        def init_ui_stage14(self, *args, **kwargs):
            ret = old_init(self, *args, **kwargs)
            try:
                QTimer.singleShot(1000, lambda: _stage14_patch_jingcai_tables(self))
            except Exception:
                pass
            return ret
        cls.init_ui = init_ui_stage14
        cls._stage14_bugfix_installed = True

    try:
        logger.info("V111 Clean Stage14 已安装：Bug/漏洞修复兜底")
    except Exception:
        pass
    return True

