# ============================================================
# V111 CLEAN STAGE15 PATCH — 福建地方彩独立API更新
# 功能：
# 1) 新增“🏮 福建更新”页面；
# 2) 单独按钮更新福建36选7、福建31选7、福建22选5；
# 3) 不再混入全国福彩/体彩全量补档；
# 4) 支持20条分页、断点续传、每页保存、完整度检查；
# 5) 如果接口ID与实际不一致，可在页面里修改ID后保存。
# ============================================================

STAGE15_DIR = APP_DIR / "v111_stage15_fujian"
STAGE15_DIR.mkdir(parents=True, exist_ok=True)
STAGE15_CONFIG = STAGE15_DIR / "fujian_config.json"
STAGE15_PROGRESS = STAGE15_DIR / "fujian_progress.json"
STAGE15_LOG = STAGE15_DIR / "fujian_update_log.json"

# 注意：不同极速API账号/接口文档可能ID不同，所以做成可配置。
# 默认值若与你接口文档不同，可在“🏮 福建更新”页直接改。
STAGE15_DEFAULT_CONFIG = {
    "福建36选7": {"api_name": "fj36x7", "caipiaoid": "fj36x7", "expected": 3000},
    "福建31选7": {"api_name": "fj31x7", "caipiaoid": "fj31x7", "expected": 3000},
    "福建22选5": {"api_name": "fj22x5", "caipiaoid": "fj22x5", "expected": 3000},
    "page_size": 20,
    "api_base": "https://api.jisuapi.com/caipiao/history",
}

def _stage15_load_json(path, default):
    try:
        p = Path(path)
        if p.exists():
            return json.loads(p.read_text(encoding="utf-8"))
    except Exception:
        pass
    return default

def _stage15_save_json(path, data):
    p = Path(path)
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(json.dumps(data, ensure_ascii=False, indent=2), encoding="utf-8")

def _stage15_config():
    cfg = _stage15_load_json(STAGE15_CONFIG, {})
    merged = dict(STAGE15_DEFAULT_CONFIG)
    for k, v in cfg.items() if isinstance(cfg, dict) else []:
        if isinstance(v, dict) and isinstance(merged.get(k), dict):
            nv = dict(merged[k]); nv.update(v); merged[k] = nv
        else:
            merged[k] = v
    _stage15_save_json(STAGE15_CONFIG, merged)
    return merged

def _stage15_get_key(self=None):
    if "_stage11_get_key" in globals():
        try:
            return _stage11_get_key(self)
        except Exception:
            pass
    for attr in ("appkey", "api_key", "jisuapi_key"):
        try:
            v = getattr(self, attr, "")
            if v:
                return str(v).strip()
        except Exception:
            pass
    for name in ("APPKEY", "API_KEY", "JISUAPI_KEY", "JISU_APPKEY"):
        v = globals().get(name)
        if v:
            return str(v).strip()
    return "26c5553dcd7c30d5"

def _stage15_history_file():
    if "_stage11_history_file" in globals():
        try:
            return _stage11_history_file()
        except Exception:
            pass
    for name in ("HISTORY_DATA_FILE", "HISTORY_FILE", "DATA_FILE"):
        v = globals().get(name)
        if v:
            return Path(v)
    return APP_DIR / "history_data.json"

def _stage15_load_history(self=None):
    try:
        if self is not None and isinstance(getattr(self, "history_data", None), dict):
            return getattr(self, "history_data")
    except Exception:
        pass
    return _stage15_load_json(_stage15_history_file(), {})

def _stage15_save_history(self, data):
    _stage15_save_json(_stage15_history_file(), data)
    try:
        self.history_data = data
    except Exception:
        pass

def _stage15_issue(row):
    if "_stage11_issue" in globals():
        try:
            return _stage11_issue(row)
        except Exception:
            pass
    if not isinstance(row, dict):
        return ""
    for k in ("期号", "issueno", "issue", "expect", "term", "no"):
        v = row.get(k)
        if v not in (None, ""):
            return str(v).strip()
    return ""

def _stage15_code(row):
    if "_stage11_code" in globals():
        try:
            return _stage11_code(row)
        except Exception:
            pass
    if not isinstance(row, dict):
        return ""
    for k in ("开奖号码", "opencode", "number", "openCode", "code", "result"):
        v = row.get(k)
        if v not in (None, ""):
            return str(v).strip()
    return ""

def _stage15_date(row):
    if "_stage11_date" in globals():
        try:
            return _stage11_date(row)
        except Exception:
            pass
    if not isinstance(row, dict):
        return ""
    for k in ("开奖日期", "opendate", "date", "time", "openTime"):
        v = row.get(k)
        if v not in (None, ""):
            return str(v)[:10]
    return ""

def _stage15_normalize(row):
    if not isinstance(row, dict):
        return None
    issue = _stage15_issue(row)
    code = _stage15_code(row)
    if not issue or not code:
        return None
    r = dict(row)
    r["期号"] = issue
    r["issueno"] = issue
    r["开奖号码"] = code
    if _stage15_date(r):
        r["开奖日期"] = _stage15_date(r)
    return r

def _stage15_extract_rows(resp):
    if "_stage11_extract_rows" in globals():
        try:
            rows = _stage11_extract_rows(resp)
            if rows:
                return rows
        except Exception:
            pass
    if not isinstance(resp, dict):
        return []
    result = resp.get("result", resp.get("data", resp))
    if isinstance(result, list):
        return [x for x in result if isinstance(x, dict)]
    if isinstance(result, dict):
        for k in ("list", "data", "rows", "history", "items"):
            v = result.get(k)
            if isinstance(v, list):
                return [x for x in v if isinstance(x, dict)]
    return []

def _stage15_merge_game(self, game, rows):
    data = _stage15_load_history(self)
    old = data.get(game, [])
    by = {}
    for r in old if isinstance(old, list) else []:
        nr = _stage15_normalize(r)
        if nr:
            by[_stage15_issue(nr)] = nr
    before = len(by)
    for r in rows or []:
        nr = _stage15_normalize(r)
        if nr:
            by[_stage15_issue(nr)] = nr
    def sort_key(x):
        try:
            return int(re.sub(r"\D", "", _stage15_issue(x)) or "0")
        except Exception:
            return 0
    merged = sorted(by.values(), key=sort_key, reverse=True)
    data[game] = merged
    _stage15_save_history(self, data)
    return {"before": before, "after": len(merged), "added": max(0, len(merged)-before)}

def _stage15_count(self, game):
    rows = _stage15_load_history(self).get(game, [])
    if not isinstance(rows, list):
        return 0
    return len({_stage15_issue(x) for x in rows if _stage15_issue(x)})

def _stage15_request_page(appkey, game, start, caipiaoid, page_size=20, timeout=18):
    try:
        import requests as _req
    except Exception as e:
        return None, "requests不可用：" + str(e)
    cfg = _stage15_config()
    url = cfg.get("api_base") or "https://api.jisuapi.com/caipiao/history"
    # 福建接口有的文档用caipiaoid数字，有的用别名，这里直接允许用户配置
    params = {"appkey": appkey, "caipiaoid": caipiaoid, "issueno": "", "start": int(start), "num": int(page_size)}
    last = ""
    for i in range(4):
        try:
            r = _req.get(url, params=params, timeout=timeout)
            r.raise_for_status()
            data = r.json()
            status = str(data.get("status", data.get("code", "0"))) if isinstance(data, dict) else "0"
            if status not in ("0", "200", "") and not (isinstance(data, dict) and data.get("result")):
                return None, f"接口错误 status={status} msg={data.get('msg', data.get('message',''))}"
            return data, ""
        except Exception as e:
            last = str(e)
            time.sleep(1.0 + i * 0.7)
    return None, "请求失败：" + last

def _stage15_update_one(self, game, cb=None, resume=True, max_pages=1200):
    cfg = _stage15_config()
    gcfg = cfg.get(game, {})
    caipiaoid = str(gcfg.get("caipiaoid") or gcfg.get("api_name") or game)
    expected = int(gcfg.get("expected", 3000) or 3000)
    page_size = int(cfg.get("page_size", 20) or 20)
    progress = _stage15_load_json(STAGE15_PROGRESS, {})
    start = int(progress.get(game, 0)) if resume else 0
    before = _stage15_count(self, game)
    appkey = _stage15_get_key(self)
    empty = 0
    no_new = 0
    page = 0
    fetched = 0
    last_err = ""
    while page < max_pages:
        if getattr(self, "_stage15_cancel", False):
            last_err = "用户取消"
            break
        if cb:
            cb(f"{game} 更新中：caipiaoid={caipiaoid}, start={start}, 本地={_stage15_count(self, game)}/{expected}")
        resp, err = _stage15_request_page(appkey, game, start, caipiaoid, page_size)
        if err:
            last_err = err
            progress[game] = start
            _stage15_save_json(STAGE15_PROGRESS, progress)
            break
        rows = _stage15_extract_rows(resp)
        page += 1
        if not rows:
            empty += 1
            start += page_size
            progress[game] = start
            _stage15_save_json(STAGE15_PROGRESS, progress)
            if empty >= 3:
                progress.pop(game, None)
                _stage15_save_json(STAGE15_PROGRESS, progress)
                break
            continue
        empty = 0
        fetched += len(rows)
        info = _stage15_merge_game(self, game, rows)
        added = info["added"]
        after = info["after"]
        if cb:
            cb(f"{game} 第{page}页：接口{len(rows)}条，新增{added}，当前{after}/{expected}")
        if added <= 0:
            no_new += 1
        else:
            no_new = 0
        start += page_size
        progress[game] = start
        _stage15_save_json(STAGE15_PROGRESS, progress)
        # 不因小于20条停止，只看空页/连续无新增/达到理论
        if expected and after >= expected * 0.995:
            progress.pop(game, None)
            _stage15_save_json(STAGE15_PROGRESS, progress)
            break
        if no_new >= 12:
            progress.pop(game, None)
            _stage15_save_json(STAGE15_PROGRESS, progress)
            break
    after = _stage15_count(self, game)
    return {
        "彩种": game,
        "状态": "完成" if not last_err else ("部分完成，可继续" if after > before else "失败"),
        "更新前": before,
        "更新后": after,
        "理论": expected,
        "完整度": round(after / max(1, expected) * 100, 2),
        "接口抓取": fetched,
        "页数": page,
        "断点": _stage15_load_json(STAGE15_PROGRESS, {}).get(game),
        "说明": last_err or "正常结束",
    }

def _stage15_update_all(self, cb=None):
    self._stage15_cancel = False
    log = {}
    for game in ("福建36选7", "福建31选7", "福建22选5"):
        log[game] = _stage15_update_one(self, game, cb=cb, resume=True)
    result = {"时间": datetime.now().strftime("%Y-%m-%d %H:%M:%S"), "福建地方彩补档": log}
    _stage15_save_json(STAGE15_LOG, result)
    return result

def _stage15_health(self):
    cfg = _stage15_config()
    lines = ["🏮 福建地方彩完整度", f"时间：{datetime.now().strftime('%Y-%m-%d %H:%M:%S')}", ""]
    for game in ("福建36选7", "福建31选7", "福建22选5"):
        expected = int((cfg.get(game, {}) or {}).get("expected", 3000) or 3000)
        count = _stage15_count(self, game)
        ok = "✔" if count >= expected * 0.95 else "✘"
        lines.append(f"{game} {count} / {expected} {ok} 完整度 {round(count/max(1,expected)*100,2)}%  caipiaoid={cfg.get(game,{}).get('caipiaoid')}")
    lines.append("")
    lines.append(f"保存文件：{_stage15_history_file()}")
    lines.append(f"配置文件：{STAGE15_CONFIG}")
    return "\n".join(lines)

def _stage15_build_page(self):
    tab = QWidget()
    root = QVBoxLayout(tab)
    root.setContentsMargins(8,8,8,8)

    title = QLabel("🏮 福建地方彩 · 单独API更新")
    title.setStyleSheet("font-size:22px;font-weight:bold;color:#C0392B;padding:10px;background:#FFF3CD;border:2px solid #D4AF37;border-radius:12px;")
    root.addWidget(title)

    tip = QLabel("福建地方彩使用单独配置更新：福建36选7、福建31选7、福建22选5。若接口文档里的 caipiaoid 不是默认别名，可在下方修改后保存。")
    tip.setWordWrap(True)
    tip.setStyleSheet("background:#FEF9E7;border:1px solid #D4AF37;border-radius:8px;padding:8px;color:#7D6608;")
    root.addWidget(tip)

    cfg_box = QFrame()
    cfg_box.setStyleSheet("background:#FFFDF5;border:1px solid #D4AF37;border-radius:8px;padding:6px;")
    cfg_lay = QVBoxLayout(cfg_box)
    edits = {}
    cfg = _stage15_config()
    for game in ("福建36选7", "福建31选7", "福建22选5"):
        row = QHBoxLayout()
        row.addWidget(QLabel(game))
        id_edit = QLineEdit(str(cfg.get(game, {}).get("caipiaoid", "")))
        id_edit.setPlaceholderText("caipiaoid 或接口别名")
        exp_edit = QLineEdit(str(cfg.get(game, {}).get("expected", 3000)))
        exp_edit.setMaximumWidth(100)
        row.addWidget(QLabel("ID"))
        row.addWidget(id_edit, 1)
        row.addWidget(QLabel("理论期数"))
        row.addWidget(exp_edit)
        cfg_lay.addLayout(row)
        edits[game] = (id_edit, exp_edit)
    root.addWidget(cfg_box)

    row = QHBoxLayout()
    update_all = QPushButton("📡 更新全部福建地方彩")
    check_btn = QPushButton("🧪 检查完整度")
    save_cfg_btn = QPushButton("💾 保存接口配置")
    reset_btn = QPushButton("清空断点")
    stop_btn = QPushButton("停止本轮")
    for b, c in [(update_all,"#C0392B"),(check_btn,"#117A65"),(save_cfg_btn,"#B7950B"),(reset_btn,"#7D3C98"),(stop_btn,"#922B21")]:
        b.setStyleSheet(f"background:{c};color:white;font-weight:bold;padding:8px;border-radius:8px;")
    row.addWidget(update_all); row.addWidget(check_btn); row.addWidget(save_cfg_btn); row.addWidget(reset_btn); row.addWidget(stop_btn); row.addStretch()
    root.addLayout(row)

    single = QHBoxLayout()
    buttons = {}
    for game in ("福建36选7", "福建31选7", "福建22选5"):
        btn = QPushButton(f"更新{game}")
        btn.setStyleSheet("background:#D35400;color:white;font-weight:bold;padding:7px;border-radius:8px;")
        single.addWidget(btn)
        buttons[game] = btn
    single.addStretch()
    root.addLayout(single)

    out = QTextEdit()
    out.setReadOnly(True)
    out.setStyleSheet("font-family:Consolas,Microsoft YaHei;font-size:13px;background:#FCFFFC;border:1px solid #82E0AA;border-radius:8px;")
    root.addWidget(out, 1)

    def save_cfg():
        cfg = _stage15_config()
        for game, (id_edit, exp_edit) in edits.items():
            cfg.setdefault(game, {})
            cfg[game]["caipiaoid"] = id_edit.text().strip()
            try:
                cfg[game]["expected"] = int(exp_edit.text().strip())
            except Exception:
                cfg[game]["expected"] = 3000
        _stage15_save_json(STAGE15_CONFIG, cfg)
        out.setPlainText("✅ 福建接口配置已保存。\n\n" + _stage15_health(self))

    def cb(msg):
        out.append(str(msg))
        try:
            QApplication.processEvents()
        except Exception:
            pass

    def do_check():
        out.setPlainText(_stage15_health(self))

    def do_update_all():
        save_cfg()
        out.append("\n开始更新全部福建地方彩……")
        res = _stage15_update_all(self, cb=cb)
        out.append("\n完成：\n" + json.dumps(res, ensure_ascii=False, indent=2))

    def do_update_one(game):
        save_cfg()
        out.append(f"\n开始更新 {game}……")
        res = _stage15_update_one(self, game, cb=cb, resume=True)
        out.append("\n完成：\n" + json.dumps(res, ensure_ascii=False, indent=2))

    def do_reset():
        _stage15_save_json(STAGE15_PROGRESS, {})
        out.setPlainText("✅ 福建地方彩断点已清空，下次从start=0开始。")

    def do_stop():
        self._stage15_cancel = True
        out.append("⛔ 已发送停止请求，当前页结束后停止。")

    save_cfg_btn.clicked.connect(save_cfg)
    check_btn.clicked.connect(do_check)
    update_all.clicked.connect(do_update_all)
    reset_btn.clicked.connect(do_reset)
    stop_btn.clicked.connect(do_stop)
    for game, btn in buttons.items():
        btn.clicked.connect(lambda checked=False, g=game: do_update_one(g))

    out.setPlainText(_stage15_health(self))
    return tab

def _stage15_install():
    cls = globals().get("LotteryApp")
    if not isinstance(cls, type):
        return False

    cls.stage15_update_fujian_all = _stage15_update_all
    cls.stage15_update_fujian_one = _stage15_update_one
    cls.stage15_fujian_health = _stage15_health

    # 给旧按钮可能调用的方法兜底
    cls.update_fujian_history_only = _stage15_update_all
    cls.update_fujian_lottery_history = _stage15_update_all
    cls.update_fujian_all = _stage15_update_all

    old_init = getattr(cls, "init_ui", None)
    if callable(old_init) and not getattr(cls, "_stage15_fujian_installed", False):
        def init_ui_stage15(self, *args, **kwargs):
            ret = old_init(self, *args, **kwargs)
            try:
                if hasattr(self, "tabs") and self.tabs is not None:
                    for i in range(self.tabs.count()-1, -1, -1):
                        if "福建更新" in self.tabs.tabText(i):
                            self.tabs.removeTab(i)
                    self.tabs.addTab(_stage15_build_page(self), "🏮 福建更新")
            except Exception:
                try:
                    logger.warning("Stage15福建更新页安装失败:\n" + traceback.format_exc())
                except Exception:
                    pass
            return ret
        cls.init_ui = init_ui_stage15
        cls._stage15_fujian_installed = True

    try:
        logger.info("V111 Clean Stage15 已安装：福建地方彩独立API更新")
    except Exception:
        pass
    return True

try:
    _stage15_install()
except Exception:
    try:
        logger.warning("V111 Clean Stage15 安装失败:\n" + traceback.format_exc())
    except Exception:
        pass

