# ============================================================
# V111 CLEAN STAGE16 PATCH — 清理旧补丁 + 福建免费API配置版
# 功能：
# 1) 清理Stage3/Stage5/Stage6旧补丁块，减少旧残留；
# 2) 福建地方彩支持“免费API模式”；
# 3) 每个福建彩种可配置独立免费API URL模板；
# 4) 模板支持 {game} {api_name} {start} {num} {appkey}；
# 5) 自动解析常见JSON结构：result.list / result.data / data / rows / list；
# 6) 如果免费API分页参数不同，可直接把完整URL写成模板。
# ============================================================

STAGE16_FREE_API_HELP = """
免费API URL模板示例：
https://example.com/fujian/history?game={api_name}&start={start}&num={num}
https://example.com/api?lottery={game}&page_start={start}&limit={num}

可用变量：
{game}      中文彩种名，如 福建36选7
{api_name}  接口别名，如 fj36x7
{start}     分页起点：0,20,40...
{num}       每页条数，默认20
{appkey}    如果免费API也需要key，可复用极速API key

如果你的免费API没有分页，也可以只填固定URL；系统会自动解析并去重保存。
"""

def _stage16_cfg():
    cfg = _stage15_config() if "_stage15_config" in globals() else {}
    cfg.setdefault("api_mode", "free")  # free / jisu
    cfg.setdefault("free_api_timeout", 18)
    for game, api_name in (("福建36选7", "fj36x7"), ("福建31选7", "fj31x7"), ("福建22选5", "fj22x5")):
        cfg.setdefault(game, {})
        cfg[game].setdefault("api_name", api_name)
        cfg[game].setdefault("free_api_url", "")
        cfg[game].setdefault("caipiaoid", api_name)
        cfg[game].setdefault("expected", 3000)
    if "_stage15_save_json" in globals():
        _stage15_save_json(STAGE15_CONFIG, cfg)
    return cfg

def _stage16_format_url(template, game, start, num, appkey):
    cfg = _stage16_cfg()
    gcfg = cfg.get(game, {})
    api_name = gcfg.get("api_name") or gcfg.get("caipiaoid") or game
    try:
        return str(template).format(
            game=__import__('urllib.parse', fromlist=['quote']).quote(str(game)),
            game_raw=str(game),
            api_name=__import__('urllib.parse', fromlist=['quote']).quote(str(api_name)),
            api_name_raw=str(api_name),
            start=int(start),
            num=int(num),
            appkey=__import__('urllib.parse', fromlist=['quote']).quote(str(appkey or "")),
        )
    except Exception:
        return str(template)

def _stage16_deep_find_rows(obj):
    # 优先处理常见彩票接口结构
    if isinstance(obj, list):
        return [x for x in obj if isinstance(x, dict)]
    if not isinstance(obj, dict):
        return []
    for key in ("result", "data", "rows", "list", "history", "items"):
        val = obj.get(key)
        if isinstance(val, list):
            return [x for x in val if isinstance(x, dict)]
        if isinstance(val, dict):
            rows = _stage16_deep_find_rows(val)
            if rows:
                return rows
    # 如果没有标准key，递归找第一个dict/list
    for val in obj.values():
        if isinstance(val, (dict, list)):
            rows = _stage16_deep_find_rows(val)
            if rows:
                return rows
    return []

def _stage16_normalize_free_rows(rows):
    out = []
    for r in rows or []:
        if not isinstance(r, dict):
            continue
        nr = dict(r)
        # 兼容免费API可能使用的字段名
        issue = ""
        for k in ("期号", "issueno", "issue", "expect", "term", "period", "periodNo", "drawNo", "no"):
            if nr.get(k) not in (None, ""):
                issue = str(nr.get(k)).strip()
                break
        code = ""
        for k in ("开奖号码", "opencode", "openCode", "number", "code", "result", "nums", "numbers", "drawResult"):
            if nr.get(k) not in (None, ""):
                code = nr.get(k)
                if isinstance(code, list):
                    code = ",".join(str(x).zfill(2) if str(x).isdigit() else str(x) for x in code)
                code = str(code).strip()
                break
        date = ""
        for k in ("开奖日期", "opendate", "openDate", "date", "time", "openTime", "drawTime"):
            if nr.get(k) not in (None, ""):
                date = str(nr.get(k))[:10]
                break
        if issue and code:
            nr["期号"] = issue
            nr["issueno"] = issue
            nr["开奖号码"] = code
            if date:
                nr["开奖日期"] = date
            out.append(nr)
    return out

def _stage16_request_free_api(self, game, start=0, num=20):
    import urllib.request as _urlreq
    cfg = _stage16_cfg()
    gcfg = cfg.get(game, {})
    template = (gcfg.get("free_api_url") or "").strip()
    if not template:
        return None, "未配置免费API URL模板"
    appkey = _stage15_get_key(self) if "_stage15_get_key" in globals() else ""
    url = _stage16_format_url(template, game, start, num, appkey)
    timeout = int(cfg.get("free_api_timeout", 18) or 18)
    try:
        req = _urlreq.Request(url, headers={"User-Agent": "Mozilla/5.0 CaileV111/Stage16"})
        with _urlreq.urlopen(req, timeout=timeout) as resp:
            raw = resp.read().decode("utf-8", errors="replace")
        data = json.loads(raw)
        rows = _stage16_normalize_free_rows(_stage16_deep_find_rows(data))
        return rows, ""
    except Exception as e:
        return None, "免费API请求失败：" + str(e)

# 覆盖Stage15单彩种更新：按配置选择free或jisu
_stage16_old_stage15_update_one = _stage15_update_one if "_stage15_update_one" in globals() else None

def _stage16_update_one(self, game, cb=None, resume=True, max_pages=1200):
    cfg = _stage16_cfg()
    mode = str(cfg.get("api_mode", "free")).lower()
    if mode != "free":
        if callable(_stage16_old_stage15_update_one):
            return _stage16_old_stage15_update_one(self, game, cb=cb, resume=resume, max_pages=max_pages)
        return {"彩种": game, "状态": "失败", "说明": "极速API更新函数不可用"}

    gcfg = cfg.get(game, {})
    expected = int(gcfg.get("expected", 3000) or 3000)
    page_size = int(cfg.get("page_size", 20) or 20)
    progress = _stage15_load_json(STAGE15_PROGRESS, {}) if "_stage15_load_json" in globals() else {}
    start = int(progress.get(game, 0)) if resume else 0
    before = _stage15_count(self, game) if "_stage15_count" in globals() else 0
    empty = 0
    no_new = 0
    page = 0
    fetched = 0
    last_err = ""

    while page < max_pages:
        if getattr(self, "_stage15_cancel", False):
            last_err = "用户取消"
            break
        if cb:
            cb(f"{game} 免费API更新中：start={start}, num={page_size}, 本地={_stage15_count(self, game)}/{expected}")
        rows, err = _stage16_request_free_api(self, game, start=start, num=page_size)
        if err:
            last_err = err
            progress[game] = start
            _stage15_save_json(STAGE15_PROGRESS, progress)
            break
        rows = rows or []
        page += 1
        if not rows:
            empty += 1
            start += page_size
            progress[game] = start
            _stage15_save_json(STAGE15_PROGRESS, progress)
            if empty >= 3:
                progress.pop(game, None)
                _stage15_save_json(STAGE15_PROGRESS, progress)
                break
            continue

        empty = 0
        fetched += len(rows)
        info = _stage15_merge_game(self, game, rows)
        added = info.get("added", 0)
        after = info.get("after", _stage15_count(self, game))
        if cb:
            cb(f"{game} 第{page}页：免费API {len(rows)}条，新增{added}，当前{after}/{expected}")
        if added <= 0:
            no_new += 1
        else:
            no_new = 0

        start += page_size
        progress[game] = start
        _stage15_save_json(STAGE15_PROGRESS, progress)

        if expected and after >= expected * 0.995:
            progress.pop(game, None)
            _stage15_save_json(STAGE15_PROGRESS, progress)
            break
        if no_new >= 12:
            progress.pop(game, None)
            _stage15_save_json(STAGE15_PROGRESS, progress)
            break

    after = _stage15_count(self, game)
    return {
        "彩种": game,
        "接口模式": "免费API",
        "状态": "完成" if not last_err else ("部分完成，可继续" if after > before else "失败"),
        "更新前": before,
        "更新后": after,
        "理论": expected,
        "完整度": round(after / max(1, expected) * 100, 2),
        "接口抓取": fetched,
        "页数": page,
        "断点": (_stage15_load_json(STAGE15_PROGRESS, {}) or {}).get(game),
        "说明": last_err or "正常结束",
    }

def _stage16_update_all(self, cb=None):
    self._stage15_cancel = False
    log = {}
    for game in ("福建36选7", "福建31选7", "福建22选5"):
        log[game] = _stage16_update_one(self, game, cb=cb, resume=True)
    result = {"时间": datetime.now().strftime("%Y-%m-%d %H:%M:%S"), "福建地方彩补档": log, "接口模式": _stage16_cfg().get("api_mode")}
    _stage15_save_json(STAGE15_LOG, result)
    return result

def _stage16_build_page(self):
    tab = QWidget()
    root = QVBoxLayout(tab)
    root.setContentsMargins(8,8,8,8)

    title = QLabel("🏮 福建地方彩 · 免费API独立更新")
    title.setStyleSheet("font-size:22px;font-weight:bold;color:#C0392B;padding:10px;background:#FFF3CD;border:2px solid #D4AF37;border-radius:12px;")
    root.addWidget(title)

    tip = QLabel("这里支持福建地方彩免费API。把免费API地址填成模板后保存，再点击更新。模板变量：{game} {api_name} {start} {num} {appkey}")
    tip.setWordWrap(True)
