        cid = QLineEdit(str(gcfg.get("caipiaoid", "")))
        cid.setMaximumWidth(110)
        exp = QLineEdit(str(gcfg.get("expected", 3000)))
        exp.setMaximumWidth(90)
        row.addWidget(QLabel("别名"))
