def _stage19_build_jingcai_entry(self):
    if "_stage13_build_page" in globals():
        try:
            return _stage13_build_page(self)
        except Exception:
            pass
    if "_stage8_build_page" in globals():
        try:
            return _stage8_build_page(self)
        except Exception:
            pass
    tab = QWidget()
    lay = QVBoxLayout(tab)
    title = QLabel("⚽ 竞彩")
    title.setStyleSheet("font-size:22px;font-weight:bold;color:#B03A2E;padding:10px;")
    lay.addWidget(title)
    txt = QTextEdit()
    txt.setReadOnly(True)
    txt.setPlainText("竞彩页面已创建，但中国竞彩AI模块没有成功加载。")
    lay.addWidget(txt)
    return tab

def _stage19_find_sport_tab_index(tabs):
    for key in ["体彩", "大乐透", "排列三", "排列五", "七星彩"]:
        for i in range(tabs.count()):
            if key in tabs.tabText(i):
                return i
    return -1

def _stage19_rebuild_jingcai_tab(self):
    try:
        if not hasattr(self, "tabs") or self.tabs is None:
            return False
        tabs = self.tabs
        for i in range(tabs.count() - 1, -1, -1):
            name = tabs.tabText(i)
            if name in ("⚽ 竞彩", "🇨🇳 中国竞彩AI", "🇨🇳 中国竞彩", "🎊 竞彩专业") or ("竞彩AI" in name):
                tabs.removeTab(i)

        widget = _stage19_build_jingcai_entry(self)
        anchor = _stage19_find_sport_tab_index(tabs)
        if anchor >= 0:
            tabs.insertTab(anchor + 1, widget, "⚽ 竞彩")
            # Stage20: 不强制启动跳转竞彩页
            # tabs.setCurrentIndex(anchor + 1)
        else:
            tabs.addTab(widget, "⚽ 竞彩")
            # Stage20: 不强制启动跳转竞彩页
            # tabs.setCurrentWidget(widget)

        try:
            tables = widget.findChildren(QTableWidget)
            for tb in tables:
                if getattr(tb, "_stage19_click_bound", False):
                    continue
                def handler(row, col, table=tb):
                    try:
                        rows = _stage13_filter(_stage13_load_ai_matches(), "全部赛事", "") if "_stage13_load_ai_matches" in globals() else []
                        target = None
                        try:
                            no_txt = table.item(row, 0).text() if table.item(row, 0) else ""
                            home_txt = table.item(row, 3).text() if table.item(row, 3) else ""
                            away_txt = table.item(row, 4).text() if table.item(row, 4) else ""
                            for mm in rows:
                                if str(mm.get("no", "")) == no_txt and str(mm.get("home", "")) == home_txt and str(mm.get("away", "")) == away_txt:
                                    target = mm
                                    break
                        except Exception:
                            target = None
                        if target is None and 0 <= row < len(rows):
                            target = rows[row]
                        if target is not None and "_stage11_show_match_detail" in globals():
                            _stage11_show_match_detail(self, target)
                    except Exception:
                        pass
                tb.cellClicked.connect(handler)
                tb._stage19_click_bound = True
        except Exception:
            pass
        return True
    except Exception:
        try:
            logger.warning("Stage19重建竞彩Tab失败:\n" + traceback.format_exc())
        except Exception:
            pass
        return False

def _stage19_show_jingcai(self):
    try:
        if not hasattr(self, "tabs") or self.tabs is None:
            return
        tabs = self.tabs
        for i in range(tabs.count()):
            if tabs.tabText(i) == "⚽ 竞彩":
                tabs.setCurrentIndex(i)
                return
        _stage19_rebuild_jingcai_tab(self)
    except Exception:
        pass

def _stage19_patch_buttons(self):
    try:
        for btn in self.findChildren(QPushButton):
            try:
                if "竞彩" in btn.text():
                    try:
                        btn.clicked.disconnect()
                    except Exception:
                        pass
                    btn.clicked.connect(lambda checked=False, s=self: _stage19_show_jingcai(s))
            except Exception:
                pass
    except Exception:
        pass

def _stage19_install():
    cls = globals().get("LotteryApp")
    if not isinstance(cls, type):
        return False

    cls.stage19_rebuild_jingcai_tab = _stage19_rebuild_jingcai_tab
    cls.stage19_show_jingcai = _stage19_show_jingcai
    cls.show_jingcai_page = _stage19_show_jingcai
    cls.open_jingcai_page = _stage19_show_jingcai
    cls.show_jingcai = _stage19_show_jingcai

    old_init = getattr(cls, "init_ui", None)
    if callable(old_init) and not getattr(cls, "_stage19_jingcai_tab_fix_installed", False):
        def init_ui_stage19(self, *args, **kwargs):
            ret = old_init(self, *args, **kwargs)
            try:
                _stage19_rebuild_jingcai_tab(self)
                _stage19_patch_buttons(self)
            except Exception:
                try:
                    logger.warning("Stage19竞彩显示修复安装失败:\n" + traceback.format_exc())
                except Exception:
                    pass
            return ret
        cls.init_ui = init_ui_stage19
        cls._stage19_jingcai_tab_fix_installed = True

    return True

try:
    _stage19_install()
except Exception:
    try:
        logger.warning("V111 Clean Stage19 安装失败:\n" + traceback.format_exc())
    except Exception:
        pass

