# ============================================================
# V111 CLEAN STAGE21 PATCH — 中国盘口历史生成修复
# 修复：
# 1) 中国竞彩AI当前赛事缓存为空时，自动读取 china_handicap_history.json；
# 2) 盘口历史58条也能生成胜负彩/任九/进球彩/比分/半全场/串关；
# 3) 修复盘口历史字段转赛事字段的问题；
# 4) 中国盘口“更新历史并保存”后立即可生成AI方案。
# ============================================================

def _stage21_history_file_candidates():
    files = []
    try:
        files.append(STAGE9_HANDICAP_HISTORY_FILE)
    except Exception:
        pass
    try:
        files.append(STAGE7_DIR / "china_handicap_history.json")
    except Exception:
        pass
    try:
        files.append(APP_DIR / "v111_china_jingcai" / "china_handicap_history.json")
    except Exception:
        pass
    try:
        files.append(Path.cwd() / "v111_china_jingcai" / "china_handicap_history.json")
    except Exception:
        pass
    return files

def _stage21_load_handicap_history_rows():
    for p in _stage21_history_file_candidates():
        try:
            pp = Path(p)
            if pp.exists():
                data = json.loads(pp.read_text(encoding="utf-8"))
                if isinstance(data, list) and data:
                    return data
        except Exception:
            pass
    return []

def _stage21_prob_from_history_row(r):
    # 1. 直接读取保存的概率
    prob = r.get("prob") if isinstance(r, dict) else {}
    if isinstance(prob, dict) and prob:
        try:
            s = sum(float(x) for x in prob.values()) or 1
            return {
                "home": float(prob.get("home", 0)) / s,
                "draw": float(prob.get("draw", 0)) / s,
                "away": float(prob.get("away", 0)) / s,
            }
        except Exception:
            pass

    # 2. 从SP反推概率
    spf = r.get("spf", {}) if isinstance(r, dict) else {}
    sp = spf.get("SP", {}) if isinstance(spf, dict) else {}
    vals = {}
    for k, name in (("3", "home"), ("1", "draw"), ("0", "away")):
        try:
            o = float(sp.get(k, 0))
            if o > 1:
                vals[name] = 1.0 / o
        except Exception:
            pass
    if len(vals) == 3:
        s = sum(vals.values()) or 1
        return {k: vals[k] / s for k in vals}

    # 3. 默认概率
    return {"home": 0.38, "draw": 0.30, "away": 0.32}

def _stage21_history_row_to_match(r, idx=0):
    if not isinstance(r, dict):
        return {}
    prob = _stage21_prob_from_history_row(r)
    spf = r.get("spf", {}) or {}
    rq = r.get("rqspf", {}) or {}
    tg = r.get("total_goals", {}) or {}
    hf = r.get("half_full", {}) or {}
    score = r.get("score", {}) or {}

    no = str(r.get("no") or r.get("场次") or f"历史{idx+1:03d}")
    league = str(r.get("league") or r.get("赛事") or "中国竞彩")
    home = str(r.get("home") or r.get("主队") or "")
    away = str(r.get("away") or r.get("客队") or "")
    m = {
        "no": no,
        "league": league,
        "time": str(r.get("match_date") or r.get("time") or ""),
        "datetime": str(r.get("match_date") or ""),
        "home": home,
        "away": away,
        "prob": prob,
        "odds": {},
        "risk": "中",
        "sfc_pick": (spf.get("推荐") if isinstance(spf, dict) else "") or "3",
        "china_jc": {
            "胜平负": spf if isinstance(spf, dict) else {"推荐": "3", "概率": prob},
            "让球胜平负": rq if isinstance(rq, dict) else {"让球": 0, "推荐": "3", "概率": prob},
            "总进球": tg if isinstance(tg, dict) else {},
            "半全场": hf if isinstance(hf, dict) else {},
            "比分": score if isinstance(score, dict) else {},
            "官方盘口状态": "来自本地盘口历史库",
        },
    }
    # 补齐SP概率
    try:
        m["china_jc"]["胜平负"].setdefault("概率", prob)
        m["china_jc"]["胜平负"].setdefault("推荐", m["sfc_pick"])
        m["china_jc"]["让球胜平负"].setdefault("概率", prob)
        m["china_jc"]["让球胜平负"].setdefault("推荐", m["sfc_pick"])
        m["china_jc"]["让球胜平负"].setdefault("让球", 0)
    except Exception:
        pass
    return m

def _stage21_load_ai_matches_fixed():
    rows = []
    # 先尝试原Stage13当前赛事
    if "_stage13_load_ai_matches" in globals():
        try:
            rows = _stage13_load_ai_matches()
        except Exception:
            rows = []
    elif "_stage8_load_matches" in globals():
        try:
            rows = [_stage13_enrich_ai(x) for x in _stage8_load_matches()]
        except Exception:
            rows = []

    # 当前赛事为空，则读盘口历史库
    if not rows:
        hist = _stage21_load_handicap_history_rows()
        rows = [_stage21_history_row_to_match(x, i) for i, x in enumerate(hist)]
        rows = [x for x in rows if x.get("home") and x.get("away")]
        if "_stage13_enrich_ai" in globals():
            rows = [_stage13_enrich_ai(x) for x in rows]
    return rows

def _stage21_generate_ai_plan_fixed(rows=None):
    if rows is None:
        rows = _stage21_load_ai_matches_fixed()
    if "_stage13_generate_ai_plan" in globals():
        try:
            return _stage13_generate_ai_plan(rows)
        except Exception:
            pass
    # 兜底生成
    out = {"生成时间": datetime.now().strftime("%Y-%m-%d %H:%M:%S"), "胜负彩14场": [], "任九": [], "进球彩": [], "串关": {}}
    for i, m in enumerate(rows[:14], 1):
        prob = m.get("prob", {"home":0.38,"draw":0.30,"away":0.32})
        pick = "3" if prob.get("home",0) >= max(prob.get("draw",0), prob.get("away",0)) else ("1" if prob.get("draw",0) >= prob.get("away",0) else "0")
        risk = "低" if max(prob.values()) >= 0.55 else ("中" if max(prob.values()) >= 0.45 else "高")
        x = {"序号":i,"场次":m.get("no"),"赛事":m.get("league"),"主队":m.get("home"),"客队":m.get("away"),"胜负彩":pick,"主推":pick,"让球":0,"让球推荐":pick,"进球彩":"2/3","比分":"1:0 / 2:1 / 1:1","半全场":"平胜 / 平平","风险":risk,"概率":prob}
        out["胜负彩14场"].append(x)
    out["任九"] = out["胜负彩14场"][:9]
    out["进球彩"] = out["胜负彩14场"][:4]
    return out

def _stage21_format_plan_fixed(plans):
    if "_stage13_format_plan" in globals():
        try:
            return _stage13_format_plan(plans)
        except Exception:
            pass
    return json.dumps(plans, ensure_ascii=False, indent=2)

def _stage21_build_page(self):
    tab = QWidget()
    root = QVBoxLayout(tab)
    root.setContentsMargins(8,8,8,8)

    title = QLabel("🇨🇳 中国竞彩AI专业版")
    title.setStyleSheet("font-size:22px;font-weight:bold;color:#B03A2E;padding:10px;background:#FFF3CD;border:2px solid #D4AF37;border-radius:12px;")
    root.addWidget(title)

    top = QHBoxLayout()
    league = QComboBox()
    league.addItems(STAGE7_LEAGUE_OPTIONS if "STAGE7_LEAGUE_OPTIONS" in globals() else ["全部赛事","世界杯","芬超","美冠联"])
    search = QLineEdit()
    search.setPlaceholderText("搜索队名/联赛/场次")
    update = QPushButton("📡 更新中国SP/赛事")
    gen = QPushButton("🎯 生成AI方案")
    copy = QPushButton("📋 复制投注")
    for b,c in [(update,"#C0392B"),(gen,"#D4AF37"),(copy,"#117A65")]:
        b.setStyleSheet(f"background:{c};color:white;font-weight:bold;padding:8px;border-radius:8px;")
    top.addWidget(QLabel("赛事"))
    top.addWidget(league)
    top.addWidget(search,1)
    top.addWidget(update)
    top.addWidget(gen)
    top.addWidget(copy)
    root.addLayout(top)

    table = QTableWidget()
    table.setColumnCount(15)
    table.setHorizontalHeaderLabels(["场次","赛事","时间","主队","客队","主胜%","平%","客胜%","胜负彩","让球","RQ","进球","比分","半全场","风险"])
    try:
        table.horizontalHeader().setSectionResizeMode(QHeaderView.Stretch)
    except Exception:
        pass
    table.setStyleSheet("QHeaderView::section{background:#B03A2E;color:white;font-weight:bold;} QTableWidget{background:#FFFDF5;gridline-color:#E6C76E;}")
    root.addWidget(table,3)

    out = QTextEdit()
    out.setReadOnly(True)
    out.setStyleSheet("font-family:Consolas,Microsoft YaHei;font-size:13px;background:#FFF8E1;border:1px solid #D4AF37;border-radius:8px;")
    root.addWidget(out,2)

    state = {"rows": [], "text": ""}

    def load_rows():
        rows = _stage21_load_ai_matches_fixed()
        kw = search.text().strip().lower()
        lg = league.currentText()
        if lg and lg != "全部赛事":
            rows = [x for x in rows if lg in str(x.get("league",""))]
        if kw:
            rows = [x for x in rows if kw in (str(x.get("no","")) + str(x.get("league","")) + str(x.get("home","")) + str(x.get("away",""))).lower()]
        return rows

    def fill(rs):
        state["rows"] = rs
        table.setRowCount(len(rs))
        for i,m in enumerate(rs):
            ai = m.get("ai_jc", {})
            spf = ai.get("胜平负", {}) if isinstance(ai, dict) else {}
            p = spf.get("概率") or m.get("prob", {"home":0.38,"draw":0.30,"away":0.32})
            rq = ai.get("让球胜平负", {}) if isinstance(ai, dict) else {}
            vals = [
                m.get("no",""), m.get("league",""), m.get("time",""), m.get("home",""), m.get("away",""),
                f"{p.get('home',0)*100:.1f}%", f"{p.get('draw',0)*100:.1f}%", f"{p.get('away',0)*100:.1f}%",
                spf.get("复式") or spf.get("主推") or m.get("sfc_pick",""),
                rq.get("让球",0), rq.get("推荐",""),
                ai.get("进球彩",{}).get("推荐","2/3"),
                ai.get("比分",{}).get("推荐","1:0 / 2:1"),
                ai.get("半全场",{}).get("推荐","平胜 / 平平"),
                spf.get("风险", m.get("risk","中")),
            ]
            for c,v in enumerate(vals):
                table.setItem(i,c,QTableWidgetItem(str(v)))

    def refresh():
        rs = load_rows()
        fill(rs)
        plans = _stage21_generate_ai_plan_fixed(rs)
        txt = _stage21_format_plan_fixed(plans)
        if not rs:
            hist_n = len(_stage21_load_handicap_history_rows())
            txt += f"\n\n⚠ 当前可生成数据为空。盘口历史库记录：{hist_n} 条。请先点【盘口历史】里的更新保存，或点本页【更新中国SP/赛事】。"
        state["text"] = txt
        out.setPlainText(txt)

    def do_update():
        msg = []
        try:
            if "_stage7_update_china_cache" in globals():
                r = _stage7_update_china_cache(4)
                msg.append("赛事缓存：" + str(r))
        except Exception as e:
            msg.append("赛事缓存更新失败：" + str(e))
        try:
            if "_stage9_update_handicap_history" in globals():
                r = _stage9_update_handicap_history()
                msg.append("盘口历史：" + str(r))
        except Exception as e:
            msg.append("盘口历史更新失败：" + str(e))
        refresh()
        out.append("\n\n✅ 更新完成：\n" + "\n".join(msg))

    def do_copy():
        plans = _stage21_generate_ai_plan_fixed(state["rows"])
        lines = ["胜负彩14场："]
        for x in plans.get("胜负彩14场", []):
            lines.append(f"{x.get('场次')} {x.get('胜负彩')}")
        lines.append("")
        lines.append("任九：")
        for x in plans.get("任九", []):
            lines.append(f"{x.get('场次')} {x.get('胜负彩')}")
        txt = "\n".join(lines)
        try:
            QApplication.clipboard().setText(txt)
            QMessageBox.information(self, "已复制", "已复制投注格式")
        except Exception:
            pass
        out.setPlainText(txt)

    def show_detail(row, col):
        try:
            if 0 <= row < len(state["rows"]) and "_stage11_show_match_detail" in globals():
                _stage11_show_match_detail(self, state["rows"][row])
        except Exception:
            pass

    update.clicked.connect(do_update)
    gen.clicked.connect(refresh)
    copy.clicked.connect(do_copy)
    league.currentTextChanged.connect(lambda *_: refresh())
    search.textChanged.connect(lambda *_: refresh())
    table.cellClicked.connect(show_detail)

    refresh()
    return tab

def _stage21_install():
    global _stage13_load_ai_matches, _stage13_generate_ai_plan
    if "_stage13_load_ai_matches" in globals():
        _stage13_load_ai_matches = _stage21_load_ai_matches_fixed
    if "_stage13_generate_ai_plan" in globals():
        _stage13_generate_ai_plan = _stage21_generate_ai_plan_fixed

    cls = globals().get("LotteryApp")
    if not isinstance(cls, type):
        return False

    cls.stage21_load_ai_matches = staticmethod(_stage21_load_ai_matches_fixed)
    cls.stage21_generate_ai_plan = staticmethod(_stage21_generate_ai_plan_fixed)

    old_init = getattr(cls, "init_ui", None)
    if callable(old_init) and not getattr(cls, "_stage21_china_handicap_generate_installed", False):
        def init_ui_stage21(self, *args, **kwargs):
            ret = old_init(self, *args, **kwargs)
            try:
                if hasattr(self, "tabs") and self.tabs is not None:
                    for i in range(self.tabs.count()-1, -1, -1):
                        if self.tabs.tabText(i) in ("🇨🇳 中国竞彩AI", "⚽ 竞彩"):
                            self.tabs.removeTab(i)
                    self.tabs.addTab(_stage21_build_page(self), "🇨🇳 中国竞彩AI")
            except Exception:
                try:
                    logger.warning("Stage21中国盘口生成修复页安装失败:\n" + traceback.format_exc())
                except Exception:
                    pass
            return ret
        cls.init_ui = init_ui_stage21
        cls._stage21_china_handicap_generate_installed = True

    return True

try:
    _stage21_install()
except Exception:
    try:
        logger.warning("V111 Clean Stage21 安装失败:\n" + traceback.format_exc())
    except Exception:
        pass

