def _stage22_cn_team(name):
    if not name:
        return ""
    s = str(name).strip()
    if s in STAGE22_TEAM_CN:
        return STAGE22_TEAM_CN[s]
    if "TEAM_CN" in globals():
        try:
            if s in TEAM_CN:
                return TEAM_CN[s]
        except Exception:
            pass
    # 简单清理FC等后缀后再查
    clean = re.sub(r"^(FC|CF|AC|SC|AS)\s+", "", s).strip()
    clean = re.sub(r"\s+(FC|AFC|CF|SC|AC|CD|UD)$", "", clean).strip()
    return STAGE22_TEAM_CN.get(clean, s)

def _stage22_cn_league(name):
    s = str(name or "")
    mapping = {
        "World Cup": "世界杯", "FIFA World Cup": "世界杯", "Premier League": "英超",
        "La Liga": "西甲", "Serie A": "意甲", "Bundesliga": "德甲", "Ligue 1": "法甲",
        "Veikkausliiga": "芬超", "USL Championship": "美冠联", "MLS": "美职联",
        "Brazil": "巴西联", "Brasileiro": "巴甲", "Serie B": "巴乙",
    }
    for k, v in mapping.items():
        if k.lower() in s.lower():
            return v
    if "cn_league" in globals():
        try:
            return cn_league(s)
        except Exception:
            pass
    return s

def _stage22_prob(m):
    p = {}
    try:
        p = (m.get("ai_jc", {}) or {}).get("胜平负", {}).get("概率") or m.get("prob") or {}
    except Exception:
        p = {}
    if not p:
        p = {"home": 0.38, "draw": 0.30, "away": 0.32}
    try:
        p = {"home": float(p.get("home", 0)), "draw": float(p.get("draw", 0)), "away": float(p.get("away", 0))}
        s = sum(p.values()) or 1
        return {k: p[k]/s for k in p}
    except Exception:
        return {"home": 0.38, "draw": 0.30, "away": 0.32}

def _stage22_code_from_key(k):
    return {"home": "3", "draw": "1", "away": "0"}.get(k, "3")

def _stage22_best_key(p):
    return max(p, key=p.get)

def _stage22_risk_confidence(p):
    vals = sorted(p.values(), reverse=True)
    top = vals[0] if vals else 0.38
    diff = (vals[0]-vals[1]) if len(vals)>1 else 0
    confidence = int(max(35, min(96, top*100 + diff*80)))
    if confidence >= 72:
        risk = "低"
    elif confidence >= 58:
        risk = "中"
    else:
        risk = "高"
    return risk, confidence

def _stage22_sfc_pick(p):
    best = _stage22_code_from_key(_stage22_best_key(p))
    risk, conf = _stage22_risk_confidence(p)
    order = sorted(p.items(), key=lambda kv: kv[1], reverse=True)
    if risk == "低":
        return best
    if risk == "中":
        return "".join(dict.fromkeys(best + _stage22_code_from_key(order[1][0])))
    return "310"

def _stage22_cold_alert(m, p):
    # 高赔率方向/低概率方向但盘口给出强信号，做冷门预警
    risk, conf = _stage22_risk_confidence(p)
    best = _stage22_best_key(p)
    if risk == "高":
        return "高"
    if p.get("draw", 0) >= 0.30:
        return "防平"
    if best == "away" and p.get("away", 0) < 0.42:
        return "防冷"
    return "正常"

def _stage22_goal_score_half(m, p):
    h = p.get("home", .38); d = p.get("draw", .30); a = p.get("away", .32)
    hx = 0.65 + h * 2.15 + (1-d) * 0.10
    ax = 0.65 + a * 2.15 + (1-d) * 0.10
    total = hx + ax
    if total < 1.4:
        goals = "0/1"
    elif total < 2.2:
        goals = "1/2"
    elif total < 3.1:
        goals = "2/3"
    elif total < 4.0:
        goals = "3/4"
    else:
        goals = "4/5/6+"

    if h > max(d, a):
        score = "1:0 / 2:1 / 2:0"
        half = "平胜 / 胜胜"
    elif a > max(h, d):
        score = "0:1 / 1:2 / 0:2"
        half = "平负 / 负负"
    else:
        score = "1:1 / 0:0 / 2:2"
        half = "平平 / 胜平"
    return goals, score, half, round(hx, 2), round(ax, 2)

def _stage22_enrich_match(m):
    try:
        m = _stage13_enrich_ai(m) if "_stage13_enrich_ai" in globals() else dict(m)
    except Exception:
        m = dict(m)
    p = _stage22_prob(m)
    best_key = _stage22_best_key(p)
    main = _stage22_code_from_key(best_key)
    sfc = _stage22_sfc_pick(p)
    risk, confidence = _stage22_risk_confidence(p)
    goals, score, half, hx, ax = _stage22_goal_score_half(m, p)
    rq = ((m.get("china_jc", {}) or {}).get("让球胜平负", {}) if isinstance(m.get("china_jc"), dict) else {}) or {}
    rq_num = rq.get("让球", 0)
    rq_pick = rq.get("推荐") or main
    m["home_cn"] = _stage22_cn_team(m.get("home", ""))
    m["away_cn"] = _stage22_cn_team(m.get("away", ""))
    m["league_cn"] = _stage22_cn_league(m.get("league", ""))
    m["stage22_ai"] = {
        "概率": p,
        "主推": main,
        "胜负彩": sfc,
        "让球": rq_num,
        "让球推荐": rq_pick,
        "进球彩": goals,
        "比分": score,
        "半全场": half,
        "风险": risk,
        "信心": confidence,
        "冷门": _stage22_cold_alert(m, p),
        "预期进球": {"主": hx, "客": ax, "总": round(hx+ax, 2)},
    }
    return m

def _stage22_load_matches():
    rows = []
    if "_stage21_load_ai_matches_fixed" in globals():
        try:
            rows = _stage21_load_ai_matches_fixed()
        except Exception:
            rows = []
    if not rows and "_stage13_load_ai_matches" in globals():
        try:
            rows = _stage13_load_ai_matches()
        except Exception:
            rows = []
    if not rows and "_stage21_load_handicap_history_rows" in globals():
        try:
            hist = _stage21_load_handicap_history_rows()
            rows = [_stage21_history_row_to_match(x, i) for i, x in enumerate(hist)]
        except Exception:
            rows = []
    out = []
    for r in rows:
        try:
            e = _stage22_enrich_match(r)
            if e.get("home") and e.get("away"):
                out.append(e)
        except Exception:
            pass
    return out

def _stage22_generate_plan(rows):
    rows = [_stage22_enrich_match(x) for x in rows]
    sfc14 = []
    for i, m in enumerate(rows[:14], 1):
        ai = m["stage22_ai"]
        sfc14.append({
            "序号": i,
            "场次": m.get("no", ""),
            "赛事": m.get("league_cn") or _stage22_cn_league(m.get("league","")),
            "主队": m.get("home_cn") or _stage22_cn_team(m.get("home","")),
            "客队": m.get("away_cn") or _stage22_cn_team(m.get("away","")),
            "胜负彩": ai["胜负彩"],
            "主推": ai["主推"],
            "让球": ai["让球"],
            "让球推荐": ai["让球推荐"],
            "进球彩": ai["进球彩"],
            "比分": ai["比分"],
            "半全场": ai["半全场"],
            "风险": ai["风险"],
            "信心": ai["信心"],
            "冷门": ai["冷门"],
            "概率": _stage28_prob(ai),
        })
    # 任九：优先低风险和高信心
    ren9 = sorted(sfc14, key=lambda x: (x["风险"] == "低", x["信心"]), reverse=True)[:9]
    # 胆码：低风险且信心高的主推
    dan = [x for x in sfc14 if x["风险"] == "低" and len(str(x["胜负彩"])) == 1]
    tuo = [x for x in sfc14 if x not in dan]
    # 进球彩前4场或高信心前4
    goals = sorted(sfc14, key=lambda x: x["信心"], reverse=True)[:4]
    # 串关
    candidates = [x for x in sfc14 if x["风险"] in ("低", "中")][:8]
    combos = {"2串1": [], "3串1": [], "4串1": [], "6串1": [], "8串1": []}
    try:
        import itertools as _it
        for n in (2,3,4,6,8):
            for group in list(_it.combinations(candidates, n))[:20]:
                combos[f"{n}串1"].append(" × ".join([f"{g['场次']} {g['主队']}VS{g['客队']}[{g['主推']}]" for g in group]))
    except Exception:
        pass
    plan = {
        "生成时间": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
        "胜负彩14场": sfc14,
        "任九": ren9,
        "胆码": dan,
        "拖码": tuo,
        "进球彩": goals,
        "串关": combos,
    }
    try:
        STAGE22_PLAN_FILE.write_text(json.dumps(plan, ensure_ascii=False, indent=2), encoding="utf-8")
    except Exception:
        pass
    return plan

def _stage22_format_plan(plan):
    lines = [f"🇨🇳 中国竞彩AI专业版 V2.0｜{plan.get('生成时间','')}", ""]
    lines.append("【胜负彩14场】")
    if not plan.get("胜负彩14场"):
        lines.append("暂无可生成赛事，请先更新中国SP/赛事或盘口历史。")
    for x in plan.get("胜负彩14场", []):
        lines.append(f"{x['场次']} {x['主队']} VS {x['客队']} 胜负彩:{x['胜负彩']} 主推:{x['主推']} 让球:{x['让球']} RQ:{x['让球推荐']} 信心:{x['信心']} 风险:{x['风险']} 冷门:{x['冷门']}")
    lines.append("")
    lines.append("【任九】")
    for x in plan.get("任九", []):
        lines.append(f"{x['场次']} {x['主队']} VS {x['客队']} 推荐:{x['胜负彩']} 信心:{x['信心']}")
    lines.append("")
    lines.append("【胆码】")
    if plan.get("胆码"):
        for x in plan.get("胆码", []):
            lines.append(f"{x['场次']} {x['主队']} VS {x['客队']} 胆:{x['主推']} 信心:{x['信心']}")
    else:
        lines.append("本期无强胆，建议使用复式防冷。")
    lines.append("")
    lines.append("【进球彩 / 比分 / 半全场】")
    for x in plan.get("进球彩", []):
        lines.append(f"{x['场次']} {x['主队']} VS {x['客队']} 进球:{x['进球彩']} 比分:{x['比分']} 半全场:{x['半全场']}")
    lines.append("")
    lines.append("【串关优化】")
    for k, arr in plan.get("串关", {}).items():
        lines.append(k + "：")
        for s in arr[:6]:
            lines.append("  " + s)
    return "\n".join(lines)

def _stage22_detail_text(m):
    m = _stage22_enrich_match(m)
    ai = m["stage22_ai"]
    p=_stage28_prob(ai)
    return (
        f"{m.get('no','')}｜{m.get('league_cn','')}｜{m.get('time','')}\n"
        f"{m.get('home_cn','')} VS {m.get('away_cn','')}\n\n"
        f"主胜：{p.get('home',0)*100:.1f}%\n"
        f"平局：{p.get('draw',0)*100:.1f}%\n"
        f"客胜：{p.get('away',0)*100:.1f}%\n\n"
        f"胜负彩：{ai['胜负彩']}  主推：{ai['主推']}\n"
        f"让球：{ai['让球']}  让球推荐：{ai['让球推荐']}\n"
        f"比分：{ai['比分']}\n"
        f"总进球：{ai['进球彩']}\n"
        f"半全场：{ai['半全场']}\n"
        f"AI信心：{ai['信心']}  风险：{ai['风险']}  冷门：{ai['冷门']}\n"
        f"预期进球：主{ai['预期进球']['主']} / 客{ai['预期进球']['客']} / 总{ai['预期进球']['总']}\n"
    )

def _stage22_show_detail(self, m):
    dlg = QDialog(self)
    dlg.setWindowTitle("竞彩AI分析详情")
    dlg.resize(680, 760)
    lay = QVBoxLayout(dlg)
    title = QLabel("⚽ 竞彩AI分析详情")
    title.setStyleSheet("font-size:20px;font-weight:bold;color:#B03A2E;background:#FFF3CD;border:2px solid #D4AF37;border-radius:10px;padding:8px;")
    lay.addWidget(title)
    txt = QTextEdit()
    txt.setReadOnly(True)
    txt.setPlainText(_stage22_detail_text(m))
    lay.addWidget(txt, 1)
    b = QPushButton("关闭")
    b.clicked.connect(dlg.accept)
    lay.addWidget(b)
    dlg.exec()

def _stage22_build_page(self):
    tab = QWidget()
    root = QVBoxLayout(tab)
    root.setContentsMargins(8,8,8,8)
    title = QLabel("🇨🇳 中国竞彩AI专业版 V2.0")
    title.setStyleSheet("font-size:22px;font-weight:bold;color:#B03A2E;padding:10px;background:#FFF3CD;border:2px solid #D4AF37;border-radius:12px;")
    root.addWidget(title)

    top = QHBoxLayout()
    league = QComboBox()
    league.addItems(["全部赛事","世界杯","芬超","美冠联","巴甲","巴乙","美职联","英超","西甲","德甲","意甲","法甲"])
    search = QLineEdit()
    search.setPlaceholderText("搜索中文队名/赛事/场次")
    update = QPushButton("📡 更新中国SP/赛事")
    gen = QPushButton("🎯 生成AI方案")
    copy = QPushButton("📋 复制投注")
    for b,c in [(update,"#C0392B"),(gen,"#D4AF37"),(copy,"#117A65")]:
        b.setStyleSheet(f"background:{c};color:white;font-weight:bold;padding:8px;border-radius:8px;")
    top.addWidget(QLabel("赛事"))
    top.addWidget(league)
    top.addWidget(search,1)
    top.addWidget(update)
    top.addWidget(gen)
    top.addWidget(copy)
    root.addLayout(top)

    table = QTableWidget()
    table.setColumnCount(17)
    table.setHorizontalHeaderLabels(["场次","赛事","时间","主队","客队","主胜%","平%","客胜%","胜负彩","主推","让球","RQ","进球","比分","半全场","信心","风险"])
    try:
        table.horizontalHeader().setSectionResizeMode(QHeaderView.Stretch)
    except Exception:
        pass
    table.setStyleSheet("QHeaderView::section{background:#B03A2E;color:white;font-weight:bold;} QTableWidget{background:#FFFDF5;gridline-color:#E6C76E;}")
    root.addWidget(table, 3)

    out = QTextEdit()
    out.setReadOnly(True)
    out.setStyleSheet("font-family:Consolas,Microsoft YaHei;font-size:13px;background:#FFF8E1;border:1px solid #D4AF37;border-radius:8px;")
    root.addWidget(out, 2)

    state = {"rows": [], "plan": {}, "text": ""}

    def load_rows():
        rows = _stage22_load_matches()
        lg = league.currentText()
        kw = search.text().strip().lower()
        if lg and lg != "全部赛事":
            rows = [x for x in rows if lg in str(x.get("league_cn","")) or lg in str(x.get("league",""))]
        if kw:
            rows = [x for x in rows if kw in (str(x.get("no","")) + str(x.get("league_cn","")) + str(x.get("home_cn","")) + str(x.get("away_cn","")) + str(x.get("home","")) + str(x.get("away",""))).lower()]
        return rows

    def fill(rows):
        state["rows"] = rows
        table.setRowCount(len(rows))
        for i,m in enumerate(rows):
            ai = m["stage22_ai"]
            p=_stage28_prob(ai)
            vals = [
                m.get("no",""), m.get("league_cn",""), m.get("time",""),
                m.get("home_cn",""), m.get("away_cn",""),
                f"{p.get('home',0)*100:.1f}%", f"{p.get('draw',0)*100:.1f}%", f"{p.get('away',0)*100:.1f}%",
                ai["胜负彩"], ai["主推"], ai["让球"], ai["让球推荐"], ai["进球彩"],
                ai["比分"], ai["半全场"], ai["信心"], ai["风险"],
            ]
            for c,v in enumerate(vals):
                table.setItem(i,c,QTableWidgetItem(str(v)))

    def refresh():
        rows = load_rows()
        fill(rows)
        plan = _stage22_generate_plan(rows)
        state["plan"] = plan
        txt = _stage22_format_plan(plan)
        state["text"] = txt
        out.setPlainText(txt)

    def do_update():
        msgs = []
        try:
            if "_stage7_update_china_cache" in globals():
                msgs.append("赛事缓存：" + str(_stage7_update_china_cache(4)))
        except Exception as e:
            msgs.append("赛事缓存失败：" + str(e))
        try:
            if "_stage9_update_handicap_history" in globals():
                msgs.append("盘口历史：" + str(_stage9_update_handicap_history()))
        except Exception as e:
            msgs.append("盘口历史失败：" + str(e))
        refresh()
        out.append("\n\n✅ 更新完成：\n" + "\n".join(msgs))

    def do_copy():
        plan = state.get("plan") or _stage22_generate_plan(state["rows"])
        lines = ["胜负彩14场："]
        for x in plan.get("胜负彩14场", []):
            lines.append(f"{x['场次']} {x['胜负彩']}")
        lines.append("")
        lines.append("任九：")
        for x in plan.get("任九", []):
            lines.append(f"{x['场次']} {x['胜负彩']}")
        lines.append("")
        lines.append("胆码：")
        for x in plan.get("胆码", []):
            lines.append(f"{x['场次']} {x['主推']}")
        txt = "\n".join(lines)
        try:
            QApplication.clipboard().setText(txt)
            QMessageBox.information(self, "已复制", "已复制投注格式")
        except Exception:
            pass
        out.setPlainText(txt)

    def on_click(row, col):
        try:
            if 0 <= row < len(state["rows"]):
                _stage22_show_detail(self, state["rows"][row])
        except Exception:
            pass

    update.clicked.connect(do_update)
    gen.clicked.connect(refresh)
    copy.clicked.connect(do_copy)
    league.currentTextChanged.connect(lambda *_: refresh())
    search.textChanged.connect(lambda *_: refresh())
    table.cellClicked.connect(on_click)

    refresh()
    return tab

def _stage22_install():
    global cn_team
    try:
        cn_team = _stage22_cn_team
    except Exception:
        pass

    cls = globals().get("LotteryApp")
    if not isinstance(cls, type):
        return False

    cls.stage22_load_matches = staticmethod(_stage22_load_matches)
    cls.stage22_generate_plan = staticmethod(_stage22_generate_plan)
    cls.stage22_cn_team = staticmethod(_stage22_cn_team)

    old_init = getattr(cls, "init_ui", None)
    if callable(old_init) and not getattr(cls, "_stage22_china_jc_ai_v2_installed", False):
        def init_ui_stage22(self, *args, **kwargs):
            ret = old_init(self, *args, **kwargs)
            try:
                if hasattr(self, "tabs") and self.tabs is not None:
                    for i in range(self.tabs.count()-1, -1, -1):
                        if self.tabs.tabText(i) in ("🇨🇳 中国竞彩AI", "⚽ 竞彩"):
                            self.tabs.removeTab(i)
                    self.tabs.addTab(_stage22_build_page(self), "🇨🇳 中国竞彩AI")
            except Exception:
                try:
                    logger.warning("Stage22中国竞彩AI V2页面安装失败:\n" + traceback.format_exc())
                except Exception:
                    pass
            return ret
        cls.init_ui = init_ui_stage22
        cls._stage22_china_jc_ai_v2_installed = True

    return True

try:
    _stage22_install()
except Exception:
    try:
        logger.warning("V111 Clean Stage22 安装失败:\n" + traceback.format_exc())
    except Exception:
        pass

