STAGE24_MOBILE_MAX_WIDTH = 760

def _stage24_is_mobile_widget(w=None):
    try:
        app = QApplication.instance()
        screen = app.primaryScreen()
        if screen:
            geo = screen.availableGeometry()
            return geo.width() <= STAGE24_MOBILE_MAX_WIDTH or geo.height() <= 900
    except Exception:
        pass
    try:
        if w is not None:
            return w.width() <= STAGE24_MOBILE_MAX_WIDTH
    except Exception:
        pass
    return True

def _stage24_style_button(btn, color="#C0392B"):
    try:
        btn.setMinimumHeight(42)
        btn.setMinimumWidth(0)
        btn.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Fixed)
        btn.setStyleSheet(
            f"QPushButton{{background:{color};color:white;font-weight:bold;"
            "border-radius:8px;padding:8px 6px;font-size:14px;}}"
            "QPushButton:disabled{background:#BFC9CA;color:#ECF0F1;}"
        )
    except Exception:
        pass
    return btn

def _stage24_wrap_buttons(parent):
    # 把明显过宽的按钮取消固定宽度，改成可伸缩
    try:
        for btn in parent.findChildren(QPushButton):
            try:
                txt = btn.text()
                if len(txt) >= 3 or "投注" in txt or "生成" in txt or "更新" in txt or "竞彩" in txt:
                    btn.setMinimumWidth(0)
                    btn.setMaximumWidth(16777215)
                    btn.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Fixed)
                    if btn.height() < 38:
                        btn.setMinimumHeight(40)
            except Exception:
                pass
    except Exception:
        pass

def _stage24_table_mobile_mode(table, keep_headers):
    try:
        headers = []
        for c in range(table.columnCount()):
            it = table.horizontalHeaderItem(c)
            headers.append(it.text() if it else str(c))
        keep = set(keep_headers)
        for c, h in enumerate(headers):
            table.setColumnHidden(c, h not in keep)
        try:
            table.horizontalHeader().setSectionResizeMode(QHeaderView.Stretch)
        except Exception:
            pass
        table.setHorizontalScrollBarPolicy(Qt.ScrollBarAlwaysOff)
        table.setWordWrap(False)
        table.setAlternatingRowColors(True)
        table.verticalHeader().setDefaultSectionSize(36)
    except Exception:
        pass

def _stage24_dialog_text(self, title, text):
    dlg = QDialog(self)
    dlg.setWindowTitle(title)
    dlg.resize(380, 620)
    lay = QVBoxLayout(dlg)
    lab = QLabel(title)
    lab.setStyleSheet("font-size:18px;font-weight:bold;color:#B03A2E;background:#FFF3CD;border:2px solid #D4AF37;border-radius:10px;padding:8px;")
    lay.addWidget(lab)
    box = QTextEdit()
    box.setReadOnly(True)
    box.setPlainText(str(text))
    box.setStyleSheet("font-family:Microsoft YaHei;font-size:14px;background:#FFFDF5;")
    lay.addWidget(box, 1)
    btn = QPushButton("关闭")
    _stage24_style_button(btn, "#7F8C8D")
    btn.clicked.connect(dlg.accept)
    lay.addWidget(btn)
    dlg.exec()

def _stage24_check_handicap_update_result(result):
    try:
        if isinstance(result, dict):
            total = int(result.get("历史总数", result.get("更新后", result.get("total", 0))) or 0)
            newn = int(result.get("新增来源记录", result.get("新增", result.get("added", 0))) or 0)
            if total <= 0 and newn <= 0:
                return False, "未抓到任何中国盘口数据，已阻止假成功。请检查接口、网络或盘口来源。"
    except Exception:
        pass
    return True, ""

