# ============================================================
# V111 CLEAN STAGE26 PATCH — 天天盈球参考数据源接入版
# 参考页：https://yq.ttyingqiu.com/live/zq/matchDetail/dxq/114460941
# ============================================================
STAGE26_DIR = APP_DIR / "v111_stage26_ttyingqiu"
STAGE26_DIR.mkdir(parents=True, exist_ok=True)
STAGE26_CACHE_FILE = STAGE26_DIR / "ttyingqiu_reference_cache.json"
STAGE26_LOG_FILE = STAGE26_DIR / "ttyingqiu_update_log.json"
STAGE26_DEFAULT_URL = "https://yq.ttyingqiu.com/live/zq/matchDetail/dxq/114460941"

def _stage26_safe_load_json(path, default):
    try:
        p = Path(path)
        if p.exists():
            return json.loads(p.read_text(encoding="utf-8"))
    except Exception:
        pass
    return default

def _stage26_safe_save_json(path, data):
    try:
        Path(path).parent.mkdir(parents=True, exist_ok=True)
        Path(path).write_text(json.dumps(data, ensure_ascii=False, indent=2), encoding="utf-8")
        return True
    except Exception:
        return False

def _stage26_fetch_html(url, timeout=18):
    import requests
    headers = {
        "User-Agent": "Mozilla/5.0 (Linux; Android 14) AppleWebKit/537.36 Mobile Safari/537.36",
        "Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",
        "Accept-Language": "zh-CN,zh;q=0.9,en;q=0.8",
        "Referer": "https://yq.ttyingqiu.com/",
        "Connection": "close",
    }
    r = requests.get(url, headers=headers, timeout=timeout)
    try:
        r.encoding = r.apparent_encoding or "utf-8"
    except Exception:
        r.encoding = "utf-8"
    if r.status_code != 200:
        raise RuntimeError("HTTP %s" % r.status_code)
    return r.text

def _stage26_strip_html(html):
    try:
        soup = BeautifulSoup(html, "html.parser")
        for tag in soup(["script", "style", "noscript"]):
            tag.decompose()
        return soup.get_text("\n", strip=True)
    except Exception:
        txt = re.sub(r"<script[\s\S]*?</script>|<style[\s\S]*?</style>", " ", html, flags=re.I)
        txt = re.sub(r"<[^>]+>", "\n", txt)
        return re.sub(r"\n{2,}", "\n", txt)

def _stage26_extract_match_id(url):
    m = re.search(r"/matchDetail/[^/]+/(\d+)", str(url))
    return m.group(1) if m else ""

def _stage26_extract_basic(text):
    home = away = score = league = date = ""
    m = re.search(r"([^\s《》【】,，\-]{2,30})vs([^\s《》【】,，\-]{2,30})数据分析", text, flags=re.I)
    if m:
        home, away = m.group(1).strip(), m.group(2).strip()
    m2 = re.search(r"([\u4e00-\u9fa5A-Za-z]{2,20})\s+(\d+)\s*[-:：]\s*(\d+)\s+([\u4e00-\u9fa5A-Za-z]{2,20})", text)
    if m2 and not score:
        if not home: home = m2.group(1)
        if not away: away = m2.group(4)
        score = "%s:%s" % (m2.group(2), m2.group(3))
    m = re.search(r"(世界杯|国际友谊|芬超|美冠联|巴甲|巴乙|英超|西甲|德甲|意甲|法甲)", text)
    if m: league = m.group(1)
    m = re.search(r"(20\d{2}[-/年]\d{1,2}[-/月]\d{1,2})", text)
    if m: date = m.group(1).replace("年", "-").replace("月", "-").replace("/", "-").replace("日", "")
    return home, away, score, league, date

def _stage26_find_section(text, start_keywords, max_chars=3500):
    if isinstance(start_keywords, str):
        start_keywords = [start_keywords]
    pos = -1
    for k in start_keywords:
        pos = text.find(k)
        if pos >= 0: break
    if pos < 0: return ""
    end_keys = ["数据分析", "欧赔数据", "让球数据", "进球数据", "特色数据", "实时情报", "专家推荐", "未来赛程", "赛况聊球"]
    end = len(text)
    for k in end_keys:
        p = text.find(k, pos + 2)
        if p > pos:
            end = min(end, p)
    return text[pos:min(end, pos + max_chars)].strip()

def _stage26_parse_handicap_text(section):
    rows = []
    if not section: return rows
    lines = [x.strip() for x in section.splitlines() if x.strip()]
    company = ""
    for i, line in enumerate(lines):
        if re.match(r"^[\u4e00-\u9fa5A-Za-z0-9*]{1,16}$", line) and not re.search(r"主队|客队|盘口|赔率|显示|公司", line):
            company = line
        joined = " ".join(lines[i:i+8])
        m = re.search(r"([01]\.\d{2})\s+(-?\d+(?:[./]\d+)?)\s+([01]\.\d{2})", joined)
        if m:
            row = {"公司": company, "主队赔率": m.group(1), "让球": m.group(2), "客队赔率": m.group(3)}
            if row not in rows: rows.append(row)
        if len(rows) >= 30: break
    return rows

def _stage26_parse_summary(section):
    out = []
    for ln in [x.strip() for x in str(section).splitlines() if x.strip()]:
        if re.search(r"\d+:\d+|胜|平|负|大|小|世界杯|国际友谊|芬超|巴甲|交锋|排名", ln):
            out.append(ln)
        if len(out) >= 40: break
    return out

def _stage26_parse_ttyingqiu_page(url):
    html = _stage26_fetch_html(url)
    text = _stage26_strip_html(html)
    home, away, score, league, date = _stage26_extract_basic(text)
    handicap = _stage26_find_section(text, ["让球数据", "亚盘", "盘口"])
    euro = _stage26_find_section(text, ["欧赔数据", "欧洲数据"])
    goals = _stage26_find_section(text, ["进球数据", "大小球"])
    analysis = _stage26_find_section(text, ["数据分析", "历史交锋", "近期状态"], max_chars=6000)
    record = {
        "source": "天天盈球参考",
        "url": url,
        "match_id": _stage26_extract_match_id(url),
        "time_updated": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
        "league": league or "足球赛事",
        "match_date": date,
        "home": home,
        "away": away,
        "score": score,
        "handicap_rows": _stage26_parse_handicap_text(handicap),
        "history_summary": _stage26_parse_summary(analysis),
        "sections": {"让球数据": handicap[:3500], "欧赔数据": euro[:3500], "进球数据": goals[:3500], "数据分析": analysis[:6000]},
        "raw_text_head": text[:5000],
    }
    valid = bool((home and away) or record["handicap_rows"] or record["history_summary"] or "卡塔尔" in text or "瑞士" in text)
    return record, valid

def _stage26_update_ttyingqiu_cache(url=STAGE26_DEFAULT_URL):
    old = _stage26_safe_load_json(STAGE26_CACHE_FILE, [])
    if not isinstance(old, list): old = []
    log = {"time": datetime.now().strftime("%Y-%m-%d %H:%M:%S"), "url": url, "old_count": len(old), "new_count": 0, "saved": False, "message": ""}
    try:
        rec, valid = _stage26_parse_ttyingqiu_page(url)
        if not valid:
            log["message"] = "页面可能为前端动态加载，未解析到有效比赛数据，已保留旧缓存。"
        else:
            rows = [x for x in old if str(x.get("url")) != str(url)]
            rows.insert(0, rec)
            _stage26_safe_save_json(STAGE26_CACHE_FILE, rows)
            log.update({"new_count": 1, "saved": True, "message": "成功更新天天盈球参考数据：%s vs %s" % (rec.get("home", ""), rec.get("away", ""))})
    except Exception as e:
        log["message"] = "请求或解析失败：" + str(e)
    _stage26_safe_save_json(STAGE26_LOG_FILE, log)
    return log

def _stage26_load_ttyingqiu_cache():
    data = _stage26_safe_load_json(STAGE26_CACHE_FILE, [])
    return data if isinstance(data, list) else []

def _stage26_tty_to_ai_match(rec, idx=0):
    prob = {"home": 0.38, "draw": 0.30, "away": 0.32}
    rq = 0
    try:
        rows = rec.get("handicap_rows") or []
        if rows:
            pan = str(rows[0].get("让球", "0"))
            if "-1.5/2" in pan or "-2" in pan:
                prob, rq = {"home": 0.58, "draw": 0.23, "away": 0.19}, -2
            elif "-1/1.5" in pan or "-1.5" in pan:
                prob, rq = {"home": 0.52, "draw": 0.25, "away": 0.23}, -1
            elif "-1" in pan:
                prob, rq = {"home": 0.48, "draw": 0.27, "away": 0.25}, -1
            elif "1" in pan:
                prob, rq = {"home": 0.28, "draw": 0.28, "away": 0.44}, 1
    except Exception:
        pass
    return {
        "source": "ttyingqiu_reference",
        "no": "盈球%03d" % (idx + 1),
        "league": rec.get("league") or "天天盈球",
        "time": rec.get("match_date", ""),
        "home": rec.get("home") or "主队",
        "away": rec.get("away") or "客队",
        "score": rec.get("score") or "",
        "prob": prob,
        "china_jc": {"胜平负": {"概率": prob, "推荐": "3" if prob["home"] >= max(prob["draw"], prob["away"]) else ("1" if prob["draw"] >= prob["away"] else "0")}, "让球胜平负": {"让球": rq, "推荐": "3" if prob["home"] >= prob["away"] else "0"}, "参考来源": "天天盈球"},
        "ttyingqiu_ref": rec,
    }

def _stage26_merge_ttyingqiu_with_matches():
    rows = []
    # 避免递归：只调用老函数名，不调用自己
    for fn in ("_stage22_load_matches", "_stage21_load_ai_matches_fixed", "_stage13_load_ai_matches"):
        f = globals().get(fn)
        if callable(f):
            try:
                r = f()
                if isinstance(r, list) and r:
                    rows.extend(r)
                    break
            except Exception:
                pass
    for i, rec in enumerate(_stage26_load_ttyingqiu_cache()):
        rows.append(_stage26_tty_to_ai_match(rec, i))
    out, seen = [], set()
    for m in rows:
        if not isinstance(m, dict): continue
        key = (str(m.get("home", "")), str(m.get("away", "")), str(m.get("time", "")), str(m.get("source", "")))
        if key in seen: continue
        seen.add(key); out.append(m)
    if "_stage23_enrich" in globals():
        enriched = []
        for m in out:
            try: enriched.append(_stage23_enrich(m))
            except Exception: enriched.append(m)
        return enriched
    return out

def _stage26_build_ttyingqiu_page(self):
    tab = QWidget(); root = QVBoxLayout(tab); root.setContentsMargins(6,6,6,6)
    title = QLabel("📈 天天盈球参考数据源")
    title.setStyleSheet("font-size:20px;font-weight:bold;color:#B03A2E;padding:9px;background:#FFF3CD;border:2px solid #D4AF37;border-radius:12px;")
    root.addWidget(title)
    tip = QLabel("参考：数据分析、让球数据、进球数据、历史交锋、近期状态。解析不到时保留旧缓存，不空数据覆盖。")
    tip.setWordWrap(True); tip.setStyleSheet("background:#FEF9E7;border:1px solid #D4AF37;border-radius:8px;padding:7px;color:#7D6608;"); root.addWidget(tip)
    url_edit = QLineEdit(); url_edit.setPlaceholderText("粘贴天天盈球比赛详情链接"); url_edit.setText(STAGE26_DEFAULT_URL); root.addWidget(url_edit)
    row = QGridLayout(); update = QPushButton("📡 更新当前链接"); view = QPushButton("📋 查看缓存"); use_ai = QPushButton("🎯 合并到中国竞彩AI")
    for b, c in ((update, "#C0392B"), (view, "#117A65"), (use_ai, "#D4AF37")):
        try: _stage24_style_button(b, c)
        except Exception: b.setStyleSheet("background:%s;color:white;font-weight:bold;padding:8px;border-radius:8px;" % c)
    row.addWidget(update,0,0); row.addWidget(view,0,1); row.addWidget(use_ai,1,0,1,2); root.addLayout(row)
    table = QTableWidget(); table.setColumnCount(6); table.setHorizontalHeaderLabels(["赛事", "日期", "主队", "客队", "比分", "盘口数"])
    try: table.horizontalHeader().setSectionResizeMode(QHeaderView.Stretch)
    except Exception: pass
    table.setStyleSheet("QHeaderView::section{background:#B03A2E;color:white;font-weight:bold;} QTableWidget{background:#FFFDF5;gridline-color:#E6C76E;font-size:12px;}"); table.setHorizontalScrollBarPolicy(Qt.ScrollBarAlwaysOff); root.addWidget(table, 3)
    out = QTextEdit(); out.setReadOnly(True); out.setStyleSheet("font-family:Microsoft YaHei;font-size:13px;background:#FFF8E1;border:1px solid #D4AF37;border-radius:8px;"); root.addWidget(out, 2)
    state = {"rows": []}
    def fill():
        rows = _stage26_load_ttyingqiu_cache(); state["rows"] = rows; table.setRowCount(len(rows))
        for i, r in enumerate(rows):
            vals = [r.get("league", ""), r.get("match_date", ""), r.get("home", ""), r.get("away", ""), r.get("score", ""), len(r.get("handicap_rows") or [])]
            for c, v in enumerate(vals): table.setItem(i, c, QTableWidgetItem(str(v)))
        log = _stage26_safe_load_json(STAGE26_LOG_FILE, {})
        out.setPlainText("缓存记录：%d 条\n缓存文件：%s\n\n最近日志：\n%s" % (len(rows), STAGE26_CACHE_FILE, json.dumps(log, ensure_ascii=False, indent=2)))
    def do_update():
        log = _stage26_update_ttyingqiu_cache(url_edit.text().strip() or STAGE26_DEFAULT_URL); fill()
        if log.get("saved"): QMessageBox.information(self, "更新成功", log.get("message", "更新成功"))
        else: QMessageBox.warning(self, "未更新到数据", log.get("message", "未解析到有效数据，旧缓存已保留。"))
    def do_use_ai():
        rows = _stage26_merge_ttyingqiu_with_matches(); msg = "已合并天天盈球参考缓存与中国竞彩AI数据，共 %d 场。" % len(rows)
        out.setPlainText(msg); QMessageBox.information(self, "已合并", msg)
    def on_click(row, col):
        if 0 <= row < len(state["rows"]):
            txt = json.dumps(state["rows"][row], ensure_ascii=False, indent=2)
            if "_stage24_dialog_text" in globals(): _stage24_dialog_text(self, "天天盈球参考详情", txt)
            else: QMessageBox.information(self, "天天盈球参考详情", txt[:1800])
    update.clicked.connect(do_update); view.clicked.connect(fill); use_ai.clicked.connect(do_use_ai); table.cellClicked.connect(on_click); fill(); return tab

def _stage26_install():
    global _stage23_load_all_matches
    _stage23_load_all_matches = _stage26_merge_ttyingqiu_with_matches
    cls = globals().get("LotteryApp")
    if not isinstance(cls, type): return False
    cls.stage26_update_ttyingqiu_cache = staticmethod(_stage26_update_ttyingqiu_cache)
    cls.stage26_load_ttyingqiu_cache = staticmethod(_stage26_load_ttyingqiu_cache)
    old_init = getattr(cls, "init_ui", None)
    if callable(old_init) and not getattr(cls, "_stage26_ttyingqiu_installed", False):
        def init_ui_stage26(self, *args, **kwargs):
            ret = old_init(self, *args, **kwargs)
            try:
                if hasattr(self, "tabs") and self.tabs is not None:
                    for i in range(self.tabs.count()-1, -1, -1):
                        if "天天盈球" in self.tabs.tabText(i): self.tabs.removeTab(i)
                    self.tabs.insertTab(min(7, self.tabs.count()), _stage26_build_ttyingqiu_page(self), "📈 天天盈球")
            except Exception:
                try: logger.warning("Stage26天天盈球安装失败:\n" + traceback.format_exc())
                except Exception: pass
            return ret
        cls.init_ui = init_ui_stage26; cls._stage26_ttyingqiu_installed = True
    return True
try:
    _stage26_install()
except Exception:
    try: logger.warning("V111 Clean Stage26 安装失败:\n" + traceback.format_exc())
    except Exception: pass
