# ============================================================
# V111 CLEAN STAGE27 PATCH — 中国竞彩AI V2.1最新稳定版
#
# 三层数据架构：
# 1) 中国竞彩网 / Sporttery：主数据源，权重 0.60
# 2) 天天盈球：盘口辅助源，权重 0.25
# 3) 本地缓存：兜底源，权重 0.15
#
# 新增：
# - 数据源优先级管理
# - 盘口热度指数
# - 水位异动预警
# - 诱盘风险识别
# - 历史交锋/近期状态摘要
# - AI盘口雷达五维评分
# - 冷门预警榜
# - 任九/胜负彩/串关优化
# - 手机版窄表格
# ============================================================

STAGE27_DIR = APP_DIR / "v111_stage27_china_jc_v21_latest"
STAGE27_DIR.mkdir(parents=True, exist_ok=True)

STAGE27_PLAN_FILE = STAGE27_DIR / "china_jc_ai_v21_latest_plan.json"
STAGE27_LAST_TEXT_FILE = STAGE27_DIR / "last_china_jc_plan.txt"
STAGE27_DEBUG_FILE = STAGE27_DIR / "data_source_debug.json"

SPORTTERY_WEIGHT = 0.60
TTYINGQIU_WEIGHT = 0.25
CACHE_WEIGHT = 0.15

def _stage27_safe_json_load(path, default):
    try:
        p = Path(path)
        if p.exists():
            return json.loads(p.read_text(encoding="utf-8"))
    except Exception:
        pass
    return default

def _stage27_safe_json_save(path, data):
    try:
        Path(path).parent.mkdir(parents=True, exist_ok=True)
        Path(path).write_text(json.dumps(data, ensure_ascii=False, indent=2), encoding="utf-8")
        return True
    except Exception:
        return False

def _stage27_cn_team(name):
    s = str(name or "").strip()
    if not s:
        return ""
    for fn in ("_stage23_cn_team", "_stage22_cn_team", "cn_team"):
        f = globals().get(fn)
        if callable(f):
            try:
                out = f(s)
                if out and out != s:
                    return out
            except Exception:
                pass
    # 常用补充
    extra = {
        "Qatar":"卡塔尔","Switzerland":"瑞士","Brazil":"巴西","Morocco":"摩洛哥",
        "Inter Turku":"国际图尔库","AC Oulu":"AC奥卢","Ilves":"埃尔维斯","Turun Palloseura":"TPS图尔库",
        "FF Jaro":"雅罗","HJK":"赫尔辛基","VPS":"瓦萨PS","Kuopion Palloseura":"古比斯",
        "IFK Mariehamn":"玛丽港","IF Gnistan":"格尼斯坦","FC Lahti":"拉赫蒂","SJK":"塞伊奈约基",
        "Loudoun United FC":"劳顿联","Rhode Island FC":"罗德岛FC","Pittsburgh Riverhounds":"匹兹堡猎犬",
        "Indy Eleven":"印第十一","SC Jacksonville":"杰克逊维尔SC","Detroit City FC":"底特律城",
        "Charleston Battery":"查尔斯顿电池","FC Tulsa":"塔尔萨FC",
    }
    return extra.get(s, s)

def _stage27_cn_league(name):
    s = str(name or "")
    mapping = {
        "World Cup": "世界杯", "FIFA World Cup": "世界杯", "Veikkausliiga": "芬超",
        "USL Championship": "美冠联", "MLS": "美职联", "Brazil": "巴西联",
        "Brasileiro": "巴甲", "Serie B": "巴乙", "Premier League": "英超",
        "La Liga": "西甲", "Bundesliga": "德甲", "Serie A": "意甲", "Ligue 1": "法甲",
    }
    for k, v in mapping.items():
        if k.lower() in s.lower():
            return v
    for fn in ("_stage23_cn_league", "_stage22_cn_league", "cn_league"):
        f = globals().get(fn)
        if callable(f):
            try:
                return f(s)
            except Exception:
                pass
    return s

def _stage27_hash(*parts):
    import hashlib
    return int(hashlib.md5("|".join(map(str, parts)).encode("utf-8")).hexdigest()[:8], 16)

def _stage27_normalize_prob(p):
    try:
        out = {"home": float(p.get("home", 0)), "draw": float(p.get("draw", 0)), "away": float(p.get("away", 0))}
        if any(v < 0 for v in out.values()):
            raise ValueError()
        s = sum(out.values())
        if s <= 0:
            raise ValueError()
        return {k: out[k] / s for k in out}
    except Exception:
        return {"home": 0.38, "draw": 0.30, "away": 0.32}

def _stage27_sp_prob(match):
    # 中国竞彩SP/官方赔率反推概率
    try:
        sp = (((match.get("china_jc") or {}).get("胜平负") or {}).get("SP") or {})
        vals = {}
        for k, n in (("3", "home"), ("1", "draw"), ("0", "away")):
            o = float(sp.get(k, 0) or 0)
            if o > 1:
                vals[n] = 1 / o
        if len(vals) == 3:
            return _stage27_normalize_prob(vals)
    except Exception:
        pass
    try:
        odds = match.get("odds") or {}
        vals = {}
        for k, n in (("odds_home", "home"), ("odds_draw", "draw"), ("odds_away", "away")):
            o = float(odds.get(k, 0) or 0)
            if o > 1:
                vals[n] = 1 / o
        if len(vals) == 3:
            return _stage27_normalize_prob(vals)
    except Exception:
        pass
    try:
        p = match.get("prob")
        if p:
            return _stage27_normalize_prob(p)
    except Exception:
        pass
    return None

def _stage27_team_rating(team, league=""):
    cn = _stage27_cn_team(team)
    rating = 1450 + (_stage27_hash(cn, league) % 420)
    strong_words = ["巴西", "阿根廷", "法国", "英格兰", "西班牙", "德国", "葡萄牙", "荷兰", "瑞士", "曼城", "皇马", "拜仁", "巴黎"]
    if any(x in cn for x in strong_words):
        rating += 160
    return rating

def _stage27_elo_prob(match):
    home_rating = _stage27_team_rating(match.get("home", ""), match.get("league", "")) + 65
    away_rating = _stage27_team_rating(match.get("away", ""), match.get("league", ""))
    diff = home_rating - away_rating
    home_raw = 1 / (1 + 10 ** (-diff / 400))
    draw = max(0.18, min(0.34, 0.28 - abs(diff) / 1800))
    return _stage27_normalize_prob({
        "home": home_raw * (1 - draw),
        "draw": draw,
        "away": (1 - home_raw) * (1 - draw),
    })

def _stage27_cache_prob(match):
    p = match.get("prob")
    if p:
        return _stage27_normalize_prob(p)
    return _stage27_elo_prob(match)

def _stage27_ttyingqiu_signal(match):
    ref = match.get("ttyingqiu_ref") or {}
    rows = ref.get("handicap_rows") or match.get("handicap_rows") or []
    signal = {
        "heat": 50,
        "water_alert": "无明显异动",
        "trap_risk": 30,
        "handicap": "",
        "home_water": "",
        "away_water": "",
        "history_summary": ref.get("history_summary") or [],
    }
    try:
        if rows:
            first = rows[0]
            signal["handicap"] = str(first.get("让球", ""))
            signal["home_water"] = str(first.get("主队赔率", ""))
            signal["away_water"] = str(first.get("客队赔率", ""))
            hw = float(first.get("主队赔率", 0) or 0)
            aw = float(first.get("客队赔率", 0) or 0)
            pan = signal["handicap"]
            heat = 50
            if "-1.5" in pan or "-1.5/2" in pan or "-2" in pan:
                heat += 18
            if hw and hw < 0.85:
                heat += 12
                signal["water_alert"] = "主队低水，资金偏热"
            if hw and hw > 1.05:
                heat -= 10
                signal["water_alert"] = "主队升水，存在降温"
            if aw and aw < 0.85:
                heat -= 8
                signal["water_alert"] = "客队低水，需防客队方向"
            signal["heat"] = max(0, min(100, heat))
            # 深盘高水，容易诱上
            trap = 30
            if ("-1.5" in pan or "-2" in pan) and hw > 0.95:
                trap += 35
            if signal["heat"] >= 75:
                trap += 15
            signal["trap_risk"] = max(0, min(100, trap))
    except Exception:
        pass
    return signal

def _stage27_fuse_prob(match):
    # 三层融合：官方SP主导，天天盈球只辅助微调，本地缓存兜底
    sp = _stage27_sp_prob(match)
    cache_p = _stage27_cache_prob(match)
    elo_p = _stage27_elo_prob(match)
    tty = _stage27_ttyingqiu_signal(match)

    if sp:
        base = {
            "home": sp["home"] * SPORTTERY_WEIGHT + cache_p["home"] * CACHE_WEIGHT + elo_p["home"] * (1 - SPORTTERY_WEIGHT - CACHE_WEIGHT),
            "draw": sp["draw"] * SPORTTERY_WEIGHT + cache_p["draw"] * CACHE_WEIGHT + elo_p["draw"] * (1 - SPORTTERY_WEIGHT - CACHE_WEIGHT),
            "away": sp["away"] * SPORTTERY_WEIGHT + cache_p["away"] * CACHE_WEIGHT + elo_p["away"] * (1 - SPORTTERY_WEIGHT - CACHE_WEIGHT),
        }
        source = "Sporttery/中国SP+本地缓存+ELO"
    else:
        base = {
            "home": cache_p["home"] * 0.55 + elo_p["home"] * 0.45,
            "draw": cache_p["draw"] * 0.55 + elo_p["draw"] * 0.45,
            "away": cache_p["away"] * 0.55 + elo_p["away"] * 0.45,
        }
        source = "本地缓存+ELO"

    # 天天盈球盘口只做小幅校正，不取代官方
    heat = tty.get("heat", 50)
    handicap = str(tty.get("handicap", ""))
    if heat >= 70 and ("-1" in handicap or "-1.5" in handicap or "-2" in handicap):
        base["home"] *= 1.06
        base["draw"] *= 0.97
        base["away"] *= 0.97
        source += "+天天盈球盘口热度"
    elif heat <= 35:
        base["away"] *= 1.04
        base["draw"] *= 1.02
        source += "+天天盈球防冷"

    return _stage27_normalize_prob(base), source, tty

def _stage27_pick_code(key):
    return {"home": "3", "draw": "1", "away": "0"}.get(key, "3")

def _stage27_risk_confidence(prob, tty):
    order = sorted(prob.items(), key=lambda x: x[1], reverse=True)
    top = order[0][1]
    diff = order[0][1] - order[1][1]
    conf = int(max(30, min(96, top * 100 + diff * 95)))
    trap = int(tty.get("trap_risk", 30))
    if trap >= 70:
        conf = max(30, conf - 12)
    risk = "低" if conf >= 74 and trap < 65 else ("中" if conf >= 58 else "高")
    return risk, conf

def _stage27_cold_index(prob, tty):
    order = sorted(prob.items(), key=lambda x: x[1], reverse=True)
    idx = 25
    if order[0][1] - order[1][1] < 0.08:
        idx += 25
    if prob.get("draw", 0) >= 0.30:
        idx += 12
    if int(tty.get("trap_risk", 30)) >= 65:
        idx += 25
    if int(tty.get("heat", 50)) >= 80:
        idx += 10
    idx = max(0, min(99, idx))
    return idx, "高冷" if idx >= 75 else ("防冷" if idx >= 55 else "正常")

def _stage27_main_pick(prob, risk, cold_idx):
    order = sorted(prob.items(), key=lambda x: x[1], reverse=True)
    main = _stage27_pick_code(order[0][0])
    if risk == "低" and cold_idx < 60:
        return main, main
    if risk == "中":
        return "".join(dict.fromkeys(main + _stage27_pick_code(order[1][0]))), main
    return "310", main

def _stage27_goal_score_half(prob):
    h, d, a = prob.get("home", .35), prob.get("draw", .30), prob.get("away", .35)
    hx = 0.55 + h * 2.25 + (1 - d) * 0.12
    ax = 0.55 + a * 2.25 + (1 - d) * 0.12
    total = hx + ax
    goals = "0/1" if total < 1.4 else ("1/2" if total < 2.2 else ("2/3" if total < 3.1 else ("3/4" if total < 4.0 else "4/5/6+")))
    if h > max(d, a):
        score = "1:0 / 2:1 / 2:0"
        half = "平胜 / 胜胜"
    elif a > max(h, d):
        score = "0:1 / 1:2 / 0:2"
        half = "平负 / 负负"
    else:
        score = "1:1 / 0:0 / 2:2"
        half = "平平 / 胜平"
    return goals, score, half, round(hx, 2), round(ax, 2)

def _stage27_radar_scores(match, prob, tty):
    top = max(prob.values())
    return {
        "实力": int(max(30, min(95, top * 100 + 10))),
        "状态": int(45 + (_stage27_hash(match.get("home", ""), match.get("away", ""), "form") % 45)),
        "盘口": int(max(20, min(95, tty.get("heat", 50)))),
        "SP": int(max(30, min(95, top * 100 + 15))),
        "防冷": int(max(15, min(95, 100 - _stage27_cold_index(prob, tty)[0]))),
    }

def _stage27_enrich_match(match):
    m = dict(match or {})
    prob, source, tty = _stage27_fuse_prob(m)
    cold_idx, cold_level = _stage27_cold_index(prob, tty)
    risk, conf = _stage27_risk_confidence(prob, tty)
    sfc, main = _stage27_main_pick(prob, risk, cold_idx)
    goals, score, half, hx, ax = _stage27_goal_score_half(prob)

    rq = {}
    try:
        rq = ((m.get("china_jc") or {}).get("让球胜平负") or {})
    except Exception:
        rq = {}

    m["home_cn"] = _stage27_cn_team(m.get("home", ""))
    m["away_cn"] = _stage27_cn_team(m.get("away", ""))
    m["league_cn"] = _stage27_cn_league(m.get("league", ""))
    m["stage28_ai"] = {
        "概率": prob,
        "胜负彩": sfc,
        "主推": main,
        "让球": rq.get("让球", 0),
        "让球推荐": rq.get("推荐") or main,
        "进球彩": goals,
        "比分": score,
        "半全场": half,
        "风险": risk,
        "信心": conf,
        "冷门指数": cold_idx,
        "冷门": cold_level,
        "盘口热度": tty.get("heat", 50),
        "水位预警": tty.get("water_alert", "无明显异动"),
        "诱盘风险": tty.get("trap_risk", 30),
        "盘口": tty.get("handicap", ""),
        "预期进球": {"主": hx, "客": ax, "总": round(hx + ax, 2)},
        "雷达": _stage27_radar_scores(m, prob, tty),
        "模型来源": source,
        "历史摘要": tty.get("history_summary", []),
    }
    return m

def _stage27_load_sporttery():
    rows = []
    for fn in ("_stage25_load_sporttery_matches",):
        f = globals().get(fn)
        if callable(f):
            try:
                r = f()
                if isinstance(r, list):
                    rows.extend(r)
            except Exception:
                pass
    return rows

def _stage27_load_ttyingqiu():
    rows = []
    # 原始天天盈球缓存转成比赛
    f = globals().get("_stage26_load_ttyingqiu_cache")
    conv = globals().get("_stage26_tty_to_ai_match")
    if callable(f) and callable(conv):
        try:
            for i, rec in enumerate(f()):
                rows.append(conv(rec, i))
        except Exception:
            pass
    return rows

def _stage27_load_cache():
    rows = []
    for fn in ("_stage21_load_ai_matches_fixed", "_stage22_load_matches", "_stage23_load_all_matches"):
        f = globals().get(fn)
        if callable(f):
            try:
                r = f()
                if isinstance(r, list):
                    rows.extend(r)
            except Exception:
                pass
    return rows

def _stage27_load_all_matches():
    debug = {
        "time": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
        "sources": {},
        "priority": ["Sporttery主数据源", "天天盈球盘口辅助源", "本地缓存兜底源"],
    }
    all_rows = []

    sporttery = _stage27_load_sporttery()
    debug["sources"]["Sporttery"] = len(sporttery)
    all_rows.extend(sporttery)

    tty = _stage27_load_ttyingqiu()
    debug["sources"]["天天盈球"] = len(tty)
    # 天天盈球辅助源合并：如果同队同赛存在，只挂参考；否则作为独立参考赛
    for t in tty:
        matched = False
        for m in all_rows:
            if _stage27_cn_team(m.get("home","")) == _stage27_cn_team(t.get("home","")) and _stage27_cn_team(m.get("away","")) == _stage27_cn_team(t.get("away","")):
                if t.get("ttyingqiu_ref"):
                    m["ttyingqiu_ref"] = t.get("ttyingqiu_ref")
                matched = True
                break
        if not matched:
            all_rows.append(t)

    cache = _stage27_load_cache()
    debug["sources"]["本地缓存"] = len(cache)
    # 只补充不重复
    seen_keys = set()
    out = []
    for m in all_rows + cache:
        if not isinstance(m, dict):
            continue
        key = (_stage27_cn_team(m.get("home","")), _stage27_cn_team(m.get("away","")), str(m.get("time",""))[:10])
        if key in seen_keys:
            continue
        seen_keys.add(key)
        out.append(m)

    if not out:
        out = [
            {"no": "示例001", "league": "世界杯", "time": "", "home": "Qatar", "away": "Switzerland", "prob": {"home": .18, "draw": .23, "away": .59}},
            {"no": "示例002", "league": "世界杯", "time": "", "home": "Brazil", "away": "Morocco", "prob": {"home": .57, "draw": .25, "away": .18}},
            {"no": "示例003", "league": "芬超", "time": "", "home": "Inter Turku", "away": "AC Oulu", "prob": {"home": .42, "draw": .28, "away": .30}},
        ]
        debug["fallback"] = "启用示例兜底"

    enriched = []
    for m in out:
        try:
            enriched.append(_stage27_enrich_match(m))
        except Exception:
            enriched.append(m)
    debug["final_count"] = len(enriched)
    _stage27_safe_json_save(STAGE27_DEBUG_FILE, debug)
    return enriched

def _stage27_generate_plan(rows):
    items = []
    for i, m in enumerate([_stage27_enrich_match(x) for x in rows][:14], 1):
        ai = _stage28_get_ai(m)
        items.append({
            "序号": i,
            "场次": m.get("no", ""),
            "赛事": m.get("league_cn", ""),
            "主队": m.get("home_cn", ""),
            "客队": m.get("away_cn", ""),
            "胜负彩": ai["胜负彩"],
            "主推": ai["主推"],
            "让球": ai["让球"],
            "让球推荐": ai["让球推荐"],
            "进球彩": ai["进球彩"],
            "比分": ai["比分"],
            "半全场": ai["半全场"],
            "风险": ai["风险"],
            "信心": ai["信心"],
            "冷门指数": ai["冷门指数"],
            "冷门": ai["冷门"],
            "盘口热度": ai["盘口热度"],
            "诱盘风险": ai["诱盘风险"],
            "水位预警": ai["水位预警"],
            "雷达": ai["雷达"],
            "概率": _stage28_prob(ai),
            "模型来源": ai["模型来源"],
        })

    # 任九：优先稳定、低冷门、低诱盘
    ren9 = sorted(items, key=lambda x: (x["风险"] == "低", x["信心"], -x["冷门指数"], -x["诱盘风险"]), reverse=True)[:9]
    dan = [x for x in items if x["风险"] == "低" and x["冷门指数"] < 55 and x["诱盘风险"] < 65 and len(str(x["胜负彩"])) == 1]
    cold_top = sorted(items, key=lambda x: x["冷门指数"], reverse=True)[:10]
    goal_top = sorted(items, key=lambda x: x["信心"], reverse=True)[:4]

    combos = {}
    try:
        import itertools as _it
        candidates = [x for x in items if x["风险"] in ("低", "中") and x["冷门指数"] < 78 and x["诱盘风险"] < 78][:8]
        for n in (2, 3, 4, 6, 8):
            arr = []
            for group in list(_it.combinations(candidates, n))[:20]:
                c = 1.0
                for g in group:
                    c *= max(0.30, g["信心"] / 100)
                risk = "低" if c >= 0.35 else ("中" if c >= 0.18 else "高")
                arr.append({
                    "组合": " × ".join([f"{g['场次']} {g['主队']}VS{g['客队']}[{g['主推']}]" for g in group]),
                    "组合信心": round(c * 100, 1),
                    "风险": risk,
                })
            combos[f"{n}串1"] = arr
    except Exception:
        pass

    plan = {
        "生成时间": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
        "数据架构": {
            "主数据源": "中国竞彩网/Sporttery",
            "盘口辅助源": "天天盈球",
            "兜底源": "本地缓存",
            "权重": {"Sporttery": SPORTTERY_WEIGHT, "天天盈球": TTYINGQIU_WEIGHT, "缓存": CACHE_WEIGHT},
        },
        "胜负彩14场": items,
        "任九": ren9,
        "AI胆码": dan,
        "进球彩": goal_top,
        "冷门预警榜": cold_top,
        "串关": combos,
    }
    _stage27_safe_json_save(STAGE27_PLAN_FILE, plan)
    return plan

def _stage27_format_plan(plan):
    lines = [
        f"🇨🇳 中国竞彩AI专业版 V2.1最新稳定版｜{plan.get('生成时间','')}",
        "",
        "【数据源架构】",
        "主数据源：中国竞彩网/Sporttery",
        "盘口辅助源：天天盈球",
        "兜底源：本地缓存",
        "",
        "【胜负彩14场】",
    ]
    for x in plan.get("胜负彩14场", []):
        lines.append(
            f"{x['场次']} {x['主队']} VS {x['客队']} "
            f"胜负彩:{x['胜负彩']} 主推:{x['主推']} RQ:{x['让球推荐']} "
            f"信心:{x['信心']} 风险:{x['风险']} 冷门:{x['冷门']}({x['冷门指数']}) "
            f"盘口热度:{x['盘口热度']} 诱盘:{x['诱盘风险']}"
        )

    lines += ["", "【任九优化】"]
    for x in plan.get("任九", []):
        lines.append(f"{x['场次']} {x['主队']} VS {x['客队']} 推荐:{x['胜负彩']} 信心:{x['信心']}")

    lines += ["", "【AI胆码】"]
    if plan.get("AI胆码"):
        for x in plan.get("AI胆码", []):
            lines.append(f"{x['场次']} {x['主队']} VS {x['客队']} 胆:{x['主推']} 信心:{x['信心']}")
    else:
        lines.append("本期强胆不足，建议减少串关或使用复式防冷。")

    lines += ["", "【冷门预警榜】"]
    for x in plan.get("冷门预警榜", [])[:10]:
        lines.append(f"{x['场次']} {x['主队']} VS {x['客队']} 冷门:{x['冷门']}({x['冷门指数']}) 水位:{x['水位预警']}")

    lines += ["", "【进球彩 / 比分 / 半全场】"]
    for x in plan.get("进球彩", []):
        lines.append(f"{x['场次']} {x['主队']} VS {x['客队']} 进球:{x['进球彩']} 比分:{x['比分']} 半全场:{x['半全场']}")

    lines += ["", "【串关工厂】"]
    for k, arr in plan.get("串关", {}).items():
        lines.append(k + "：")
        for r in arr[:5]:
            lines.append(f"  {r['组合']} ｜组合信心{r['组合信心']}%｜风险{r['风险']}")

    txt = "\\n".join(lines)
    try:
        STAGE27_LAST_TEXT_FILE.write_text(txt, encoding="utf-8")
    except Exception:
        pass
    return txt

def _stage27_detail_text(match):
    m = _stage27_enrich_match(match)
    ai = _stage28_get_ai(m)
    p=_stage28_prob(ai)
    radar = ai["雷达"]
    hist = ai.get("历史摘要") or []
    return "\\n".join([
        f"{m.get('no','')}｜{m.get('league_cn','')}｜{m.get('time','')}",
        f"{m.get('home_cn','')} VS {m.get('away_cn','')}",
        "",
        f"主胜：{p['home']*100:.1f}%",
        f"平局：{p['draw']*100:.1f}%",
        f"客胜：{p['away']*100:.1f}%",
        "",
        f"胜负彩：{ai['胜负彩']}｜主推：{ai['主推']}",
        f"让球：{ai['让球']}｜让球推荐：{ai['让球推荐']}",
        f"进球彩：{ai['进球彩']}",
        f"比分：{ai['比分']}",
        f"半全场：{ai['半全场']}",
        "",
        f"AI信心：{ai['信心']}｜风险：{ai['风险']}",
        f"冷门：{ai['冷门']}({ai['冷门指数']})",
        f"盘口热度：{ai['盘口热度']}",
        f"诱盘风险：{ai['诱盘风险']}",
        f"水位预警：{ai['水位预警']}",
        f"盘口：{ai['盘口']}",
        "",
        "【AI盘口雷达】",
        f"实力：{radar.get('实力')}",
        f"状态：{radar.get('状态')}",
        f"盘口：{radar.get('盘口')}",
        f"SP：{radar.get('SP')}",
        f"防冷：{radar.get('防冷')}",
        "",
        f"模型来源：{ai['模型来源']}",
        "",
        "【历史/状态摘要】",
        "\\n".join(map(str, hist[:12])) if hist else "暂无可解析历史摘要",
    ])

def _stage27_dialog(self, title, text):
    try:
        if "_stage24_dialog_text" in globals():
            _stage24_dialog_text(self, title, text)
            return
    except Exception:
        pass
    dlg = QDialog(self)
    dlg.setWindowTitle(title)
    dlg.resize(390, 620)
    lay = QVBoxLayout(dlg)
    box = QTextEdit()
    box.setReadOnly(True)
    box.setPlainText(str(text))
    lay.addWidget(box)
    btn = QPushButton("关闭")
    btn.clicked.connect(dlg.accept)
    lay.addWidget(btn)
    dlg.exec()

def _stage27_build_latest_page(self):
    tab = QWidget()
    root = QVBoxLayout(tab)
    root.setContentsMargins(6, 6, 6, 6)

    title = QLabel("🇨🇳 中国竞彩AI V2.1 最新稳定版")
    title.setStyleSheet("font-size:20px;font-weight:bold;color:#B03A2E;padding:9px;background:#FFF3CD;border:2px solid #D4AF37;border-radius:12px;")
    root.addWidget(title)

    tip = QLabel("数据架构：Sporttery主数据源 + 天天盈球盘口辅助源 + 本地缓存兜底源")
    tip.setWordWrap(True)
    tip.setStyleSheet("background:#FEF9E7;border:1px solid #D4AF37;border-radius:8px;padding:7px;color:#7D6608;")
    root.addWidget(tip)

    top = QGridLayout()
    league = QComboBox()
    league.addItems(["全部赛事","世界杯","芬超","美冠联","巴甲","巴乙","美职联","英超","西甲","德甲","意甲","法甲"])
    search = QLineEdit()
    search.setPlaceholderText("搜索中文队名/赛事/场次")

    btn_update = QPushButton("📡 更新数据源")
    btn_gen = QPushButton("🎯 生成方案")
    btn_copy = QPushButton("📋 复制投注")
    btn_debug = QPushButton("🧪 数据诊断")
    for b, c in ((btn_update, "#C0392B"), (btn_gen, "#D4AF37"), (btn_copy, "#117A65"), (btn_debug, "#2471A3")):
        try:
            _stage24_style_button(b, c)
        except Exception:
            b.setStyleSheet(f"background:{c};color:white;font-weight:bold;padding:8px;border-radius:8px;")

    top.addWidget(QLabel("赛事"), 0, 0)
    top.addWidget(league, 0, 1, 1, 2)
    top.addWidget(search, 1, 0, 1, 3)
    top.addWidget(btn_update, 2, 0)
    top.addWidget(btn_gen, 2, 1)
    top.addWidget(btn_copy, 2, 2)
    top.addWidget(btn_debug, 3, 0, 1, 3)
    root.addLayout(top)

    table = QTableWidget()
    table.setColumnCount(9)
    table.setHorizontalHeaderLabels(["场次","赛事","主队","客队","推荐","信心","风险","冷门","盘口"])
    try:
        table.horizontalHeader().setSectionResizeMode(QHeaderView.Stretch)
    except Exception:
        pass
    table.setHorizontalScrollBarPolicy(Qt.ScrollBarAlwaysOff)
    table.setStyleSheet("QHeaderView::section{background:#B03A2E;color:white;font-weight:bold;} QTableWidget{background:#FFFDF5;gridline-color:#E6C76E;font-size:12px;}")
    table.verticalHeader().setDefaultSectionSize(38)
    root.addWidget(table, 3)

    out = QTextEdit()
    out.setReadOnly(True)
    out.setStyleSheet("font-family:Microsoft YaHei;font-size:13px;background:#FFF8E1;border:1px solid #D4AF37;border-radius:8px;")
    root.addWidget(out, 2)

    state = {"rows": [], "plan": {}}

    def load_rows():
        rows = _stage27_load_all_matches()
        lg = league.currentText()
        kw = search.text().strip().lower()
        if lg and lg != "全部赛事":
            rows = [x for x in rows if lg in str(x.get("league_cn","")) or lg in str(x.get("league",""))]
        if kw:
            rows = [x for x in rows if kw in (str(x.get("no","")) + str(x.get("league_cn","")) + str(x.get("home_cn","")) + str(x.get("away_cn","")) + str(x.get("home","")) + str(x.get("away",""))).lower()]
        return rows

    def fill(rows):
        state["rows"] = rows
        table.setRowCount(len(rows))
        for i, m in enumerate(rows):
            ai = m.get("stage27_ai") or _stage27_enrich_match(m).get("stage27_ai", {})
            vals = [
                m.get("no",""),
                m.get("league_cn") or _stage27_cn_league(m.get("league","")),
                m.get("home_cn") or _stage27_cn_team(m.get("home","")),
                m.get("away_cn") or _stage27_cn_team(m.get("away","")),
                ai.get("胜负彩",""),
                ai.get("信心",""),
                ai.get("风险",""),
                f"{ai.get('冷门','')}({ai.get('冷门指数','')})",
                ai.get("盘口",""),
            ]
            for c, v in enumerate(vals):
                table.setItem(i, c, QTableWidgetItem(str(v)))

    def refresh():
        rows = load_rows()
        fill(rows)
        plan = _stage27_generate_plan(rows)
        state["plan"] = plan
        out.setPlainText(_stage27_format_plan(plan))

    def update_sources():
        msgs = []
        # Sporttery
        f = globals().get("_stage25_update_sporttery_cache")
        if callable(f):
            try:
                msgs.append("Sporttery：" + str(f()))
            except Exception as e:
                msgs.append("Sporttery失败：" + str(e))
        else:
            msgs.append("Sporttery：未接入或未找到更新函数")

        # 天天盈球
        f = globals().get("_stage26_update_ttyingqiu_cache")
        if callable(f):
            try:
                msgs.append("天天盈球：" + str(f()))
            except Exception as e:
                msgs.append("天天盈球失败：" + str(e))
        else:
            msgs.append("天天盈球：未接入或未找到更新函数")

        # 盘口历史
        f = globals().get("_stage9_update_handicap_history")
        if callable(f):
            try:
                r = f()
                ok, msg = True, ""
                if "_stage24_check_handicap_update_result" in globals():
                    ok, msg = _stage24_check_handicap_update_result(r)
                if ok:
                    msgs.append("盘口历史：" + str(r))
                else:
                    msgs.append("盘口历史失败：" + msg)
            except Exception as e:
                msgs.append("盘口历史失败：" + str(e))

        refresh()
        out.append("\n\n✅ 数据源更新完成：\n" + "\n".join(msgs))

    def copy_plan():
        plan = state.get("plan") or _stage27_generate_plan(state["rows"])
        lines = ["胜负彩14场："]
        for x in plan.get("胜负彩14场", []):
            lines.append(f"{x['场次']} {x['胜负彩']}")
        lines += ["", "任九："]
        for x in plan.get("任九", []):
            lines.append(f"{x['场次']} {x['胜负彩']}")
        lines += ["", "AI胆码："]
        for x in plan.get("AI胆码", []):
            lines.append(f"{x['场次']} {x['主推']}")
        txt = "\\n".join(lines)
        try:
            QApplication.clipboard().setText(txt)
            QMessageBox.information(self, "已复制", "已复制投注格式")
        except Exception:
            STAGE27_LAST_TEXT_FILE.write_text(txt, encoding="utf-8")
            QMessageBox.information(self, "已保存", f"复制失败，已保存到：{STAGE27_LAST_TEXT_FILE}")
        out.setPlainText(txt)

    def debug():
        data = _stage27_safe_json_load(STAGE27_DEBUG_FILE, {})
        _stage27_dialog(self, "数据源诊断", json.dumps(data, ensure_ascii=False, indent=2))

    def on_click(row, col):
        if 0 <= row < len(state["rows"]):
            _stage27_dialog(self, "竞彩AI详情", _stage27_detail_text(state["rows"][row]))

    btn_update.clicked.connect(update_sources)
    btn_gen.clicked.connect(refresh)
    btn_copy.clicked.connect(copy_plan)
    btn_debug.clicked.connect(debug)
    league.currentTextChanged.connect(lambda *_: refresh())
    search.textChanged.connect(lambda *_: refresh())
    table.cellClicked.connect(on_click)

    refresh()
    return tab

def _stage27_install():
    global _stage23_load_all_matches
    try:
        _stage23_load_all_matches = _stage27_load_all_matches
    except Exception:
        pass

    cls = globals().get("LotteryApp")
    if not isinstance(cls, type):
        return False

    cls.stage27_load_all_matches = staticmethod(_stage27_load_all_matches)
    cls.stage27_generate_plan = staticmethod(_stage27_generate_plan)

    old_init = getattr(cls, "init_ui", None)
    if callable(old_init) and not getattr(cls, "_stage27_latest_installed", False):
        def init_ui_stage27(self, *args, **kwargs):
            ret = old_init(self, *args, **kwargs)
            try:
                if hasattr(self, "tabs") and self.tabs is not None:
                    for i in range(self.tabs.count()-1, -1, -1):
                        name = self.tabs.tabText(i)
                        if name in ("🇨🇳 中国竞彩AI", "⚽ 竞彩") or "中国竞彩AI" in name:
                            self.tabs.removeTab(i)
                    insert_at = min(5, self.tabs.count())
                    self.tabs.insertTab(insert_at, _stage27_build_latest_page(self), "🇨🇳 中国竞彩AI")
            except Exception:
                try:
                    logger.warning("Stage27中国竞彩AI最新稳定版安装失败:\n" + traceback.format_exc())
                except Exception:
                    pass
            return ret
        cls.init_ui = init_ui_stage27
        cls._stage27_latest_installed = True
    return True

try:
    _stage27_install()
except Exception:
    try:
        logger.warning("V111 Clean Stage27 安装失败:\n" + traceback.format_exc())
    except Exception:
        pass

