CURRENT_AI_VERSION = "stage28_stable"

def _stage28_get_ai(match):
    if not isinstance(match, dict):
        return {}
    ai = (match.get("stage28_ai") or match.get("stage27_ai") or match.get("stage26_ai")
          or match.get("stage25_ai") or match.get("stage24_ai") or match.get("stage23_ai")
          or match.get("stage22_ai") or {})
    if ai:
        return ai
    prob = match.get("prob") if isinstance(match.get("prob"), dict) else {"home": 0.38, "draw": 0.30, "away": 0.32}
    try:
        s = sum(float(v) for v in prob.values()) or 1
        prob = {"home": float(prob.get("home", 0))/s, "draw": float(prob.get("draw", 0))/s, "away": float(prob.get("away", 0))/s}
    except Exception:
        prob = {"home": 0.38, "draw": 0.30, "away": 0.32}
    best = max(prob, key=prob.get)
    main = {"home":"3","draw":"1","away":"0"}.get(best, "3")
    conf = int(max(35, min(95, max(prob.values()) * 100)))
    return {"概率": prob, "胜负彩": main, "主推": main, "让球": 0, "让球推荐": main,
            "进球彩": "2/3", "比分": "1:0 / 2:1 / 1:1", "半全场": "平胜 / 平平",
            "风险": "中" if conf < 70 else "低", "信心": conf, "冷门指数": 50,
            "冷门": "正常", "盘口热度": 50, "诱盘风险": 30, "水位预警": "无明显异动",
            "盘口": "", "模型来源": "Stage28兜底AI"}

def _stage28_prob(ai):
    p = ai.get("概率", {}) if isinstance(ai, dict) else {}
    try:
        return {"home": float(p.get("home", 0)), "draw": float(p.get("draw", 0)), "away": float(p.get("away", 0))}
    except Exception:
        return {"home": 0.38, "draw": 0.30, "away": 0.32}

def _stage28_cn_team(name):
    for fn in ("_stage27_cn_team", "_stage23_cn_team", "_stage22_cn_team", "cn_team"):
        f = globals().get(fn)
        if callable(f):
            try: return f(name)
            except Exception: pass
    return str(name or "")

def _stage28_cn_league(name):
    for fn in ("_stage27_cn_league", "_stage23_cn_league", "_stage22_cn_league", "cn_league"):
        f = globals().get(fn)
        if callable(f):
            try: return f(name)
            except Exception: pass
    return str(name or "")

def _stage28_enrich(match):
    m = dict(match or {})
    if "_stage27_enrich_match" in globals():
        try: m = _stage27_enrich_match(m)
        except Exception: pass
    m["stage28_ai"] = _stage28_get_ai(m)
    m["home_cn"] = m.get("home_cn") or _stage28_cn_team(m.get("home", ""))
    m["away_cn"] = m.get("away_cn") or _stage28_cn_team(m.get("away", ""))
    m["league_cn"] = m.get("league_cn") or _stage28_cn_league(m.get("league", ""))
    return m

def _stage28_load_matches():
    rows = []
    for fn in ("_stage26_merge_ttyingqiu_with_matches", "_stage25_merge_with_existing_matches", "_stage21_load_ai_matches_fixed", "_stage22_load_matches"):
        f = globals().get(fn)
        if callable(f):
            try:
                r = f()
                if isinstance(r, list) and r:
                    rows = r
                    break
            except RecursionError:
                continue
            except Exception:
                continue
    if not rows:
        rows = [{"no":"示例001","league":"世界杯","home":"Qatar","away":"Switzerland","prob":{"home":0.18,"draw":0.23,"away":0.59}},
                {"no":"示例002","league":"世界杯","home":"Brazil","away":"Morocco","prob":{"home":0.57,"draw":0.25,"away":0.18}}]
    out, seen = [], set()
    for m in rows:
        if not isinstance(m, dict): continue
        em = _stage28_enrich(m)
        key = (em.get("no",""), em.get("home_cn",""), em.get("away_cn",""), em.get("time",""))
        if key in seen: continue
        seen.add(key); out.append(em)
    return out

