class _Stage30SafeMatch(dict):
    def __getitem__(self, key):
        if key in ("stage23_ai","stage24_ai","stage25_ai","stage26_ai","stage27_ai","stage28_ai","stage30_ai"):
            return _stage30_ai(self)
        return dict.__getitem__(self, key)

def _stage30_ai(match):
    if not isinstance(match, dict):
        return {}
    ai = (dict.get(match,"stage30_ai") or dict.get(match,"stage28_ai") or dict.get(match,"stage27_ai") or
          dict.get(match,"stage26_ai") or dict.get(match,"stage25_ai") or dict.get(match,"stage24_ai") or
          dict.get(match,"stage23_ai") or dict.get(match,"stage22_ai") or {})
    if isinstance(ai, dict) and ai:
        return ai
    if "_stage28_get_ai" in globals():
        try:
            return _stage28_get_ai(match)
        except Exception:
            pass
    prob = dict.get(match, "prob", {"home":0.38,"draw":0.30,"away":0.32})
    try:
        s = sum(float(v) for v in prob.values()) or 1
        prob = {"home":float(prob.get("home",0))/s, "draw":float(prob.get("draw",0))/s, "away":float(prob.get("away",0))/s}
    except Exception:
        prob = {"home":0.38,"draw":0.30,"away":0.32}
    best = max(prob, key=prob.get)
    main = {"home":"3","draw":"1","away":"0"}.get(best, "3")
    return {"概率":prob,"胜负彩":main,"主推":main,"让球":0,"让球推荐":main,"进球彩":"2/3","比分":"1:0 / 2:1 / 1:1","半全场":"平胜 / 平平","风险":"中","信心":int(max(prob.values())*100),"冷门":"正常","冷门指数":50,"模型来源":"Stage30兜底AI"}

def _stage30_prob(match_or_ai):
    ai = match_or_ai if isinstance(match_or_ai, dict) and "概率" in match_or_ai else _stage30_ai(match_or_ai)
    p = ai.get("概率", {})
    try:
        return {"home":float(p.get("home",0)), "draw":float(p.get("draw",0)), "away":float(p.get("away",0))}
    except Exception:
        return {"home":0.38,"draw":0.30,"away":0.32}

def safe_match_ai(match):
    return _stage30_ai(match)

def safe_match_prob(match):
    return _stage30_prob(match)

def _stage30_wrap_match(m):
    if not isinstance(m, dict):
        return m
    sm = _Stage30SafeMatch(m)
    sm["stage30_ai"] = _stage30_ai(sm)
    return sm

def _stage30_load_matches_stable():
    rows = []
    for fn in ("_stage26_merge_ttyingqiu_with_matches", "_stage25_merge_with_existing_matches", "_stage21_load_ai_matches_fixed", "_stage22_load_matches"):
        f = globals().get(fn)
        if callable(f):
            try:
                r = f()
                if isinstance(r, list) and r:
                    rows = r
                    break
            except Exception:
                continue
    if not rows:
        rows = [
            {"no":"示例001","league":"世界杯","home":"Qatar","away":"Switzerland","prob":{"home":0.18,"draw":0.23,"away":0.59}},
            {"no":"示例002","league":"世界杯","home":"Brazil","away":"Morocco","prob":{"home":0.57,"draw":0.25,"away":0.18}},
        ]
    out, seen = [], set()
    for m in rows:
        if not isinstance(m, dict):
            continue
        try:
            em = _stage28_enrich(m) if "_stage28_enrich" in globals() else m
        except Exception:
            em = m
        em = _stage30_wrap_match(em)
        key = (em.get("no",""), em.get("home_cn","") or em.get("home",""), em.get("away_cn","") or em.get("away",""), em.get("time",""))
        if key in seen:
            continue
        seen.add(key)
        out.append(em)
    return out

