# ============================================================
# V112 PATCH — 竞彩/篮球稳定修复与兜底增强
# 目标：不推倒V111，只修复最容易闪退的AI字段、竞彩方案、篮球模拟投注。
# ============================================================

V112_PATCH_VERSION = "v112_jingcai_basketball_fixed"

def _v112_num(v, default=0.0):
    try:
        if v is None or v == "":
            return default
        return float(v)
    except Exception:
        return default

def _v112_norm_prob(prob=None):
    if not isinstance(prob, dict):
        prob = {}
    p = {
        "home": _v112_num(prob.get("home", prob.get("主胜", 0.38)), 0.38),
        "draw": _v112_num(prob.get("draw", prob.get("平", 0.30)), 0.30),
        "away": _v112_num(prob.get("away", prob.get("客胜", 0.32)), 0.32),
    }
    s = sum(max(0.0, x) for x in p.values()) or 1.0
    return {k: round(max(0.0, v) / s, 4) for k, v in p.items()}

def _v112_best_code(prob):
    p = _v112_norm_prob(prob)
    return {"home":"3", "draw":"1", "away":"0"}.get(max(p, key=p.get), "3")

def _v112_risk(prob):
    p = _v112_norm_prob(prob)
    vals = sorted(p.values(), reverse=True)
    diff = vals[0] - vals[1] if len(vals) > 1 else 0
    if diff >= 0.18:
        return "低"
    if diff >= 0.09:
        return "中"
    return "高"

def _v112_multi(prob):
    p = _v112_norm_prob(prob)
    items = sorted(p.items(), key=lambda kv: kv[1], reverse=True)
    code_map = {"home":"3", "draw":"1", "away":"0"}
    risk = _v112_risk(p)
    if risk == "低":
        return code_map[items[0][0]]
    if risk == "中":
        return "".join(dict.fromkeys(code_map[items[0][0]] + code_map[items[1][0]]))
    return "310"

def _v112_goal_score(prob):
    p = _v112_norm_prob(prob)
    h, d, a = p["home"], p["draw"], p["away"]
    total = 1.4 + (h + a) * 1.9 - d * 0.7
    if total < 1.6:
        goals = "0/1"
    elif total < 2.4:
        goals = "1/2"
    elif total < 3.2:
        goals = "2/3"
    else:
        goals = "3/4/5+"
    if h >= max(d, a):
        return goals, "1:0 / 2:1 / 2:0", "平胜 / 胜胜"
    if a >= max(h, d):
        return goals, "0:1 / 1:2 / 0:2", "平负 / 负负"
    return goals, "1:1 / 0:0 / 2:2", "平平 / 胜平"

def _v112_get_ai(match):
    """统一读取足球竞彩AI，彻底避开 stage23_ai / ai_jc KeyError。"""
    if not isinstance(match, dict):
        return {}
    # 兼容多阶段字段
    for k in ("stage31_ai", "stage30_ai", "stage28_ai", "stage27_ai", "stage26_ai", "stage25_ai", "stage24_ai", "stage23_ai", "stage22_ai"):
        ai = dict.get(match, k)
        if isinstance(ai, dict) and ai:
            p = _v112_norm_prob(ai.get("概率") or ai.get("prob"))
            ai.setdefault("概率", p)
            ai.setdefault("胜负彩", ai.get("主推") or _v112_multi(p))
            ai.setdefault("主推", _v112_best_code(p))
            ai.setdefault("让球", 0)
            ai.setdefault("让球推荐", ai.get("主推"))
            g, s, hf = _v112_goal_score(p)
            ai.setdefault("进球彩", g)
            ai.setdefault("比分", s)
            ai.setdefault("半全场", hf)
            ai.setdefault("风险", _v112_risk(p))
            ai.setdefault("信心", int(max(p.values()) * 100))
            return ai
    # 兼容 Stage13 ai_jc 嵌套结构
    jc = dict.get(match, "ai_jc")
    if isinstance(jc, dict) and jc:
        spf = jc.get("胜平负") or {}
        rq = jc.get("让球胜平负") or {}
        p = _v112_norm_prob(spf.get("概率"))
        return {
            "概率": p,
            "胜负彩": spf.get("复式") or _v112_multi(p),
            "主推": spf.get("主推") or _v112_best_code(p),
            "让球": rq.get("让球", 0),
            "让球推荐": rq.get("推荐") or spf.get("主推") or _v112_best_code(p),
            "进球彩": (jc.get("进球彩") or {}).get("推荐") or _v112_goal_score(p)[0],
            "比分": (jc.get("比分") or {}).get("推荐") or _v112_goal_score(p)[1],
            "半全场": (jc.get("半全场") or {}).get("推荐") or _v112_goal_score(p)[2],
            "风险": spf.get("风险") or _v112_risk(p),
            "信心": int(max(p.values()) * 100),
            "模型来源": "V112兼容ai_jc",
        }
    p = _v112_norm_prob(dict.get(match, "prob"))
    g, s, hf = _v112_goal_score(p)
    return {"概率": p, "胜负彩": _v112_multi(p), "主推": _v112_best_code(p), "让球": 0, "让球推荐": _v112_best_code(p),
            "进球彩": g, "比分": s, "半全场": hf, "风险": _v112_risk(p), "信心": int(max(p.values()) * 100), "模型来源": "V112兜底AI"}

def _v112_enrich_match(match):
    m = dict(match or {})
    ai = _v112_get_ai(m)
    m["stage23_ai"] = ai
    m["stage30_ai"] = ai
    p = ai.get("概率", {})
    # 同步生成 Stage13 需要的 ai_jc，防止老页面 m['ai_jc'] 闪退
    m["ai_jc"] = {
        "胜平负": {"主推": ai.get("主推"), "复式": ai.get("胜负彩"), "概率": p, "风险": ai.get("风险")},
        "让球胜平负": {"让球": ai.get("让球", 0), "推荐": ai.get("让球推荐"), "概率": p},
        "进球彩": {"推荐": ai.get("进球彩")},
        "比分": {"推荐": ai.get("比分")},
        "半全场": {"推荐": ai.get("半全场")},
        "模型说明": ai.get("模型来源", "V112统一兼容层"),
    }
    return m

def _v112_generate_football_plan(rows):
    rows = [_v112_enrich_match(x) for x in (rows or []) if isinstance(x, dict)]
    if not rows:
        rows = [_v112_enrich_match(x) for x in [
            {"no":"示例001", "league":"世界杯", "home":"主队A", "away":"客队B", "prob":{"home":0.42,"draw":0.30,"away":0.28}},
            {"no":"示例002", "league":"世界杯", "home":"主队C", "away":"客队D", "prob":{"home":0.31,"draw":0.29,"away":0.40}},
        ]]
    items = []
    for i, m in enumerate(rows[:14], 1):
        ai = _v112_get_ai(m)
        items.append({
            "序号": i,
            "场次": m.get("no", f"{i:03d}"),
            "赛事": m.get("league_cn") or m.get("league", ""),
            "主队": m.get("home_cn") or m.get("home", ""),
            "客队": m.get("away_cn") or m.get("away", ""),
            "胜负彩": ai.get("胜负彩", ""),
            "主推": ai.get("主推", ""),
            "让球": ai.get("让球", 0),
            "让球推荐": ai.get("让球推荐", ""),
            "进球彩": ai.get("进球彩", ""),
            "比分": ai.get("比分", ""),
            "半全场": ai.get("半全场", ""),
            "风险": ai.get("风险", "中"),
            "信心": ai.get("信心", 50),
            "概率": ai.get("概率", {}),
        })
    ren9 = sorted(items, key=lambda x: x.get("信心", 0), reverse=True)[:9]
    combos = {}
    try:
        import itertools
        pool = [x for x in items if x.get("风险") in ("低", "中")][:8]
        for n in (2, 3, 4):
            combos[f"{n}串1"] = [" × ".join([f"{y['场次']} {y['主推']}" for y in g]) for g in list(itertools.combinations(pool, n))[:20]]
    except Exception:
        pass
    return {"生成时间": datetime.now().strftime("%Y-%m-%d %H:%M:%S"), "胜负彩14场": items, "任九": ren9, "进球彩": items[:4], "串关": combos}

def _v112_copy_football_plan(plan):
    lines = ["胜负彩14场："]
    for x in plan.get("胜负彩14场", []):
        lines.append(f"{x.get('场次','')} {x.get('胜负彩','')}")
    lines += ["", "任九："]
    for x in plan.get("任九", []):
        lines.append(f"{x.get('场次','')} {x.get('胜负彩','')}")
    lines += ["", "2串1/3串1参考："]
    for k, arr in (plan.get("串关") or {}).items():
        lines.append(k + "：")
        for s in arr[:6]:
            lines.append("  " + str(s))
    return "\n".join(lines)

def _v112_format_football_plan(plan):
    lines = [f"⚽ 竞彩足球AI中心 V112｜{plan.get('生成时间','')}", "", "【胜负彩14场】"]
    for x in plan.get("胜负彩14场", []):
        lines.append(f"{x.get('场次')} {x.get('主队')} VS {x.get('客队')} 胜负彩:{x.get('胜负彩')} 主推:{x.get('主推')} 让球:{x.get('让球')} RQ:{x.get('让球推荐')} 进球:{x.get('进球彩')} 比分:{x.get('比分')} 风险:{x.get('风险')} 信心:{x.get('信心')}")
    lines += ["", "【任九】"]
    for x in plan.get("任九", []):
        lines.append(f"{x.get('场次')} {x.get('主队')} VS {x.get('客队')} 推荐:{x.get('胜负彩')}")
    lines += ["", "【串关】"]
    for k, arr in (plan.get("串关") or {}).items():
        lines.append(k + "：")
        for s in arr[:8]:
            lines.append("  " + str(s))
    return "\n".join(lines)

