def _v113_placeholder(title: str, tip: str = "首次打开时自动加载"):
    w = QWidget()
    lay = QVBoxLayout(w)
    lay.setContentsMargins(12, 12, 12, 12)
    lab = QLabel(f"{title}\n\n{tip}\n\n为提升手机端打开速度，本页面采用按需加载。")
    lab.setAlignment(Qt.AlignCenter)
    lab.setStyleSheet("font-size:14px;color:#666;padding:20px;")
    lay.addStretch(1); lay.addWidget(lab); lay.addStretch(1)
    return w


def _v113_init_ui_lazy(self):
    """V113：只同步创建首页，其余页面首次点击再创建，避免启动时一次性堆满所有表格/走势图。"""
    self.tabs = QTabWidget()
    self._lazy_tabs_loaded = set()
    self._lazy_tab_specs = {
        1: ("fucai_tab",   "init_fucai_tab",   "🎯 福彩投注"),
        2: ("sport_tab",   "init_sport_tab",   "⚽ 体彩投注"),
        3: ("analysis_tab","init_analysis_tab","📊 数据分析"),
        4: ("records_tab", "init_records_tab", "📝 投注记录"),
        5: ("history_tab", "init_history_tab", "🕒 开奖历史"),
        6: ("network_tab", "init_network_tab", "🌐 开奖记录"),
        7: ("trend_tab",   "init_trend_tab",   "📈 走势图"),
    }
    self.home_tab = QWidget()
    self.init_home_tab()
    self.tabs.addTab(self.home_tab, "🏠 首页")
    self._lazy_tabs_loaded.add(0)
    for idx in range(1, 8):
        attr, _init, title = self._lazy_tab_specs[idx]
        ph = _v113_placeholder(title)
        setattr(self, attr, ph)
        self.tabs.addTab(ph, title)
    self.tabs.currentChanged.connect(self._v113_on_tab_changed)
    self.setCentralWidget(self.tabs)
    self._apply_tab_responsive(self.tabs)


def _v113_on_tab_changed(self, index: int):
    try:
        self._v113_ensure_tab(index)
    except Exception as e:
        logger.error(f"V113懒加载页面失败 index={index}: {e}", exc_info=True)
        try:
            QMessageBox.warning(self, "页面加载失败", f"页面加载失败：{e}")
        except Exception:
            pass


def _v113_ensure_tab(self, index: int):
    if index in getattr(self, "_lazy_tabs_loaded", set()):
        return
    spec = getattr(self, "_lazy_tab_specs", {}).get(index)
    if not spec:
        return
    attr, init_name, title = spec
    old = self.tabs.widget(index)
    page = QWidget()
    setattr(self, attr, page)
    init_fn = getattr(self, init_name)
    init_fn()
    self.tabs.removeTab(index)
    self.tabs.insertTab(index, page, title)
    self.tabs.setCurrentIndex(index)
    self._lazy_tabs_loaded.add(index)
    try:
        old.deleteLater()
    except Exception:
        pass
    # 懒加载记录页后再刷新投注记录表；历史/开奖页加载后刷新对应表格。
    try:
        if attr == "records_tab" and hasattr(self, "update_records_table"):
            self.update_records_table()
        elif attr == "history_tab" and hasattr(self, "update_history_table"):
            self.update_history_table()
        elif attr == "network_tab" and hasattr(self, "display_current_game_results"):
            self.display_current_game_results()
    except Exception as e:
        logger.debug(f"V113页面后刷新失败 {title}: {e}")


def _v113_apply_responsive_tree(self):
    """V113：启动阶段不再遍历全部控件树；全局QSS已完成主要缩放。"""
    try:
        if hasattr(self, "tabs"):
            self._apply_tab_responsive(self.tabs)
    except Exception:
        pass


def _v113_load_betting_history(self):
    try:
        if os.path.exists(_BETTING_HISTORY_FILE):
            with open(_BETTING_HISTORY_FILE, "r", encoding="utf-8") as f:
                raw_data = json.load(f)
            self.betting_history = []
            for record in raw_data:
                if not isinstance(record, dict):
                    continue
                for key, default in _RECORD_DEFAULTS.items():
                    record.setdefault(key, default)
                self.betting_history.append(record)
            # 记录页未打开时不强制刷新表格，避免启动时创建/填充大表。
            if hasattr(self, "records_table"):
                self.update_records_table()
    except Exception as e:
        logger.error(f"加载记录失败: {str(e)}")
        self.betting_history = []


def _v113_deferred_heavy_startup(self):
    """界面出现后再做耗时任务，减少白屏和点击无响应。"""
    try:
        self.calculate_omission()
    except Exception as e:
        logger.warning(f"延迟计算遗漏失败: {e}")
    try:
        self._load_model_data()
    except Exception as e:
        logger.warning(f"延迟加载预测成绩失败: {e}")
    try:
        self.start_auto_update()
    except Exception as e:
        logger.warning(f"启动自动更新失败: {e}")
    try:
        self.start_auto_predict_timer()
    except Exception as e:
        logger.warning(f"启动自动预测失败: {e}")


def _v113_fast_init(self):
    QMainWindow.__init__(self)
    self.setWindowTitle("彩乐荟聚 - V113 竞彩篮球AI加速版")

    sc = QApplication.primaryScreen().availableGeometry()
    self._screen_w = sc.width(); self._screen_h = sc.height()
    self._mobile = self._screen_w < 600 or min(self._screen_w, self._screen_h) < 480
    self._tablet = (not self._mobile) and self._screen_w < 900
    self._scale = max(0.55, min(1.0, self._screen_w / 1400.0)) if not self._mobile else max(0.45, min(0.85, self._screen_w / 700.0))
    if self._mobile or self._tablet:
        self.setGeometry(0, 0, self._screen_w, self._screen_h)
    else:
        self.setGeometry(100, 100, min(1400, self._screen_w - 100), min(900, self._screen_h - 80))

    self.ua = UserAgent(); self.proxies = None
    self.betting_history = []; self.history_data = {}; self.current_game = ""
    self.api_key = ""; self.jisuapi_key = ""
    self.last_omission_data = {}; self.frequency_data = {}; self.cold_hot_data = {}
    self.auto_update_timer = None; self.auto_predict_timer = None; self._auto_predict_worker = None
    self._last_auto_predict_date = ""; self.update_threads = []
    self.coldhot_ratios = {'hot': 0.5, 'warm': 0.3, 'cold': 0.2}
    self.repeat_count = 0; self.last_prediction = None
    self.model_scores = {}; self.full_backtest_scores = {}; self.prediction_log = []
    self._backtest_lock = threading.Lock(); self._backtesting = False

    self.init_cold_hot_data()
    self.init_ui()
    self._apply_responsive_tree()
    self.load_api_key()
    self.load_history_data()
    self.load_betting_history()

    # 耗时任务延迟，先让主页面可操作。
    QTimer.singleShot(800, lambda: self._v113_deferred_heavy_startup())
    QTimer.singleShot(4500, self._startup_auto_fetch)
    QTimer.singleShot(10000, lambda: self._run_auto_predict_daily_if_needed(force=False))


# 安装V113加速补丁
try:
    LotteryApp.init_ui = _v113_init_ui_lazy
    LotteryApp._v113_on_tab_changed = _v113_on_tab_changed
    LotteryApp._v113_ensure_tab = _v113_ensure_tab
    LotteryApp._apply_responsive_tree = _v113_apply_responsive_tree
    LotteryApp.load_betting_history = _v113_load_betting_history
    LotteryApp._v113_deferred_heavy_startup = _v113_deferred_heavy_startup
    LotteryApp.__init__ = _v113_fast_init
    logger.info("V113加速补丁已加载：懒加载页面、延迟遗漏/模型/定时器、记录表按需刷新。")
except Exception as _e:
    logger.warning(f"V113加速补丁安装失败: {_e}")

