V204_PATCH_VERSION = "V204_full_feature_mobile_nav"


def _v204_safe_call(self, method_name, *args, **kwargs):
    try:
        fn = getattr(self, method_name, None)
        if not callable(fn):
            QMessageBox.information(self, "功能提示", f"当前版本暂未绑定：{method_name}\n后续可继续接入该入口。")
            return
        return fn(*args, **kwargs)
    except Exception as e:
        logger.error(f"V204调用功能失败 {method_name}: {e}", exc_info=True)
        try:
            QMessageBox.warning(self, "功能运行失败", f"{method_name} 运行失败：\n{e}")
        except Exception:
            pass


