def _v205_open_function_search(self):
    dlg = QDialog(self)
    dlg.setWindowTitle("🔎 V205 功能搜索中心")
    try:
        _responsive_dlg_size(dlg, 760, 900)
    except Exception:
        dlg.resize(760, 900)
    root = QVBoxLayout(dlg)
    root.setContentsMargins(8,8,8,8)
    title = QLabel("输入关键词快速找功能：比如 竞彩、篮球、任九、套餐、遗漏、回测、更新、密钥。")
    title.setWordWrap(True)
    title.setStyleSheet("color:#555;font-size:12px;")
    root.addWidget(title)
    search = QLineEdit()
    search.setPlaceholderText("🔎 搜索功能，例如：篮球 / 任九 / 大乐透 / 回测")
    search.setMinimumHeight(_sc(36) if '_sc' in globals() else 36)
    root.addWidget(search)
    scroll = QScrollArea(); scroll.setWidgetResizable(True); scroll.setHorizontalScrollBarPolicy(Qt.ScrollBarAlwaysOff)
    page = QWidget(); grid = QGridLayout(page); grid.setSpacing(6); grid.setContentsMargins(4,4,4,4)
    scroll.setWidget(page); root.addWidget(scroll, 1)
    all_items = _v205_build_nav_items(self, dlg)
    buttons = []

    def rebuild(keyword=""):
        while grid.count():
            it = grid.takeAt(0)
            w = it.widget()
            if w:
                w.deleteLater()
        buttons.clear()
        kw = (keyword or "").strip().lower()
        shown = []
        for item in all_items:
            text, keys, color, cb = item
            hay = (text + " " + keys).lower()
            if not kw or kw in hay:
                shown.append(item)
        if not shown:
            lab = QLabel("没有匹配到功能，可以换个关键词。")
            lab.setAlignment(Qt.AlignCenter)
            lab.setStyleSheet("color:#999;padding:20px;")
            grid.addWidget(lab, 0, 0, 1, 2)
            return
        for i, (text, keys, color, cb) in enumerate(shown):
            buttons.append(_v205_add_button(grid, text, color, i//2, i%2, cb))
    search.textChanged.connect(rebuild)
    rebuild("")
    close = QPushButton("关闭")
    close.clicked.connect(dlg.close)
    root.addWidget(close)
    dlg.exec()


