try:
    import statistics as _v207_statistics
except Exception:
    _v207_statistics = None


def _v207_extract_numbers_for_game(game_type, record):
    """从不同玩法的历史记录中提取主号码/副号码，尽量兼容旧数据结构。"""
    try:
        if not record:
            return [], []
        # 兼容已经结构化的记录
        if game_type == "双色球":
            if isinstance(record.get("red"), list):
                return [int(x) for x in record.get("red", [])], [int(x) for x in record.get("blue", [])]
        if game_type == "大乐透":
            if isinstance(record.get("front"), list):
                return [int(x) for x in record.get("front", [])], [int(x) for x in record.get("back", [])]
        # 通用字符串：开奖号码 / numbers / 号码
        raw = str(record.get("开奖号码", record.get("numbers", record.get("号码", ""))))
        nums = parse_draw_numbers(raw) if 'parse_draw_numbers' in globals() else []
        if not nums:
            import re as _re
            nums = [int(x) for x in _re.findall(r"\d+", raw)]
        if game_type == "双色球" and len(nums) >= 7:
            return nums[:6], nums[6:7]
        if game_type == "大乐透" and len(nums) >= 7:
            return nums[:5], nums[5:7]
        return nums, []
    except Exception:
        return [], []


def _v207_game_config(game_type):
    """返回玩法号码范围与选号个数。"""
    cfg = {
        "双色球": (1, 33, 6, 1, 16, 1),
        "大乐透": (1, 35, 5, 1, 12, 2),
        "七乐彩": (1, 30, 7, 0, 0, 0),
        "快乐8": (1, 80, 10, 0, 0, 0),
        "福建36选7": (1, 36, 7, 0, 0, 0),
        "福建31选7": (1, 31, 7, 0, 0, 0),
        "福建22选5": (1, 22, 5, 0, 0, 0),
        "3D": (0, 9, 3, 0, 0, 0),
        "排列三": (0, 9, 3, 0, 0, 0),
        "排列五": (0, 9, 5, 0, 0, 0),
        "七星彩": (0, 14, 7, 0, 0, 0),
    }
    return cfg.get(game_type, (1, 80, 10, 0, 0, 0))


def _v207_make_ai_prediction(app, game_type, window=100, groups=8):
    """轻量AI融合：冷热频率 + 当前遗漏 + 近期开奖趋势 + 原有多算法接口。"""
    from collections import Counter
    import random as _random
    records = list((getattr(app, "history_data", {}) or {}).get(game_type, []) or [])[:max(window, 30)]
    lo, hi, main_need, sub_lo, sub_hi, sub_need = _v207_game_config(game_type)
    if not records:
        return {"ok": False, "message": f"{game_type} 暂无历史开奖数据，请先更新或手动导入。"}
    main_rows, sub_rows = [], []
    for r in records:
        m, s = _v207_extract_numbers_for_game(game_type, r)
        m = [x for x in m if lo <= x <= hi]
        s = [x for x in s if sub_need and sub_lo <= x <= sub_hi]
        if m:
            main_rows.append(m)
        if s:
            sub_rows.append(s)
    if not main_rows:
        return {"ok": False, "message": f"{game_type} 历史数据格式无法解析。"}
    flat = [n for row in main_rows for n in row]
    freq = Counter(flat)
    # 当前遗漏：从最近期往后找首次出现位置
    miss = {n: len(main_rows) for n in range(lo, hi + 1)}
    for idx, row in enumerate(main_rows):
        for n in set(row):
            if miss.get(n, len(main_rows)) == len(main_rows):
                miss[n] = idx
    recent20 = Counter([n for row in main_rows[:20] for n in row])
    # 综合分：长期频率45%，近期趋势25%，遗漏回补20%，随机扰动10%
    max_freq = max(freq.values()) if freq else 1
    max_recent = max(recent20.values()) if recent20 else 1
    max_miss = max(miss.values()) if miss else 1
    scored = []
    for n in range(lo, hi + 1):
        score = 0.45 * (freq.get(n, 0) / max_freq)
        score += 0.25 * (recent20.get(n, 0) / max_recent)
        score += 0.20 * (miss.get(n, 0) / max_miss)
        score += 0.10 * _random.random()
        scored.append((n, score, freq.get(n, 0), recent20.get(n, 0), miss.get(n, 0)))
    scored.sort(key=lambda x: x[1], reverse=True)
    pool = [n for n, *_ in scored[:max(main_need * 4, main_need + 8)]]
    cold_pool = [n for n, *_ in sorted(scored, key=lambda x: x[3])[:max(3, main_need)]]
    groups_out = []
    for i in range(groups):
        # 前几组偏热，后几组加入冷号/遗漏号，提高覆盖
        base = pool[:]
        if i >= groups // 2:
            base = list(dict.fromkeys(pool[:main_need*3] + cold_pool))
        if len(base) < main_need:
            base = list(range(lo, hi + 1))
        nums = sorted(_random.sample(base, main_need))
        sub_nums = []
        if sub_need:
            sub_flat = [n for row in sub_rows for n in row]
            sub_freq = Counter(sub_flat)
            sub_scored = sorted(range(sub_lo, sub_hi + 1), key=lambda x: (sub_freq.get(x, 0), _random.random()), reverse=True)
            sub_pool = sub_scored[:max(sub_need * 4, sub_need + 3)]
            sub_nums = sorted(_random.sample(sub_pool, sub_need))
        groups_out.append({"main": nums, "sub": sub_nums, "score": round(sum(dict((n, s) for n, s, *_ in scored).get(n, 0) for n in nums), 3)})
    hot = [n for n, *_ in sorted(scored, key=lambda x: x[2], reverse=True)[:12]]
    omission = [n for n, *_ in sorted(scored, key=lambda x: x[4], reverse=True)[:12]]
    return {
        "ok": True,
        "game": game_type,
        "records": len(records),
        "hot": hot,
        "omission": omission,
        "ranking": scored[:20],
        "groups": groups_out,
        "note": "V207融合：历史频率45% + 近期趋势25% + 当前遗漏20% + 扰动10%",
    }


def _v207_format_group(game_type, g):
    main = ",".join(f"{int(x):02d}" for x in g.get("main", []))
    sub = g.get("sub", []) or []
    if sub:
        return main + "|" + ",".join(f"{int(x):02d}" for x in sub)
    return main


def _v207_open_ai_prediction_center(self):
    """V207 AI融合预测中心：手机优先布局。"""
    dlg = QDialog(self)
    dlg.setWindowTitle("🤖 V207 AI融合预测中心")
    _responsive_dlg_size(dlg, 760, 920) if '_responsive_dlg_size' in globals() else dlg.resize(760, 920)
    root = QVBoxLayout(dlg)
    top = QHBoxLayout()
    game_combo = QComboBox()
    games = list((getattr(self, "history_data", {}) or {}).keys()) or ["双色球", "大乐透", "快乐8", "七乐彩", "3D", "排列三", "排列五", "七星彩"]
    for g in games:
        game_combo.addItem(g)
    window_spin = QSpinBox(); window_spin.setRange(30, 500); window_spin.setValue(100); window_spin.setSuffix("期")
    groups_spin = QSpinBox(); groups_spin.setRange(1, 30); groups_spin.setValue(8); groups_spin.setSuffix("组")
    run_btn = QPushButton("🔮 生成AI推荐")
    copy_btn = QPushButton("📋 复制结果")
    for w in [QLabel("玩法"), game_combo, QLabel("窗口"), window_spin, QLabel("组数"), groups_spin, run_btn, copy_btn]:
        top.addWidget(w)
    root.addLayout(top)
    result = QTextEdit(); result.setReadOnly(True)
    result.setPlaceholderText("选择玩法后点击生成。建议先把历史开奖更新到最新，再看AI融合推荐。")
    root.addWidget(result, 1)

    def run():
        game = game_combo.currentText()
        data = _v207_make_ai_prediction(self, game, window_spin.value(), groups_spin.value())
        if not data.get("ok"):
            result.setPlainText(data.get("message", "生成失败")); return
        lines = []
        lines.append(f"🤖 {game} V207 AI融合预测中心")
        lines.append("=" * 42)
        lines.append(f"样本：最近 {data['records']} 期")
        lines.append(data.get("note", ""))
        lines.append("")
        lines.append("🔥 热号参考：" + ",".join(f"{x:02d}" for x in data.get("hot", [])))
        lines.append("⏳ 高遗漏参考：" + ",".join(f"{x:02d}" for x in data.get("omission", [])))
        lines.append("")
        lines.append("📊 综合评分前20：")
        for n, score, freq, recent, miss in data.get("ranking", [])[:20]:
            lines.append(f"{n:02d}  评分{score:.3f}  总频{freq}  近20期{recent}  遗漏{miss}")
        lines.append("")
        lines.append("🎯 AI推荐号码：")
        for i, g in enumerate(data.get("groups", []), 1):
            lines.append(f"第{i:02d}组：{_v207_format_group(game, g)}  质量分:{g.get('score', 0)}")
        lines.append("")
        lines.append("说明：彩票/竞彩均有随机性，本功能只做数据分析与选号参考，不保证中奖。")
        result.setPlainText("\n".join(lines))

    def copy():
        QApplication.clipboard().setText(result.toPlainText())
        QMessageBox.information(dlg, "已复制", "AI推荐结果已复制。")

    run_btn.clicked.connect(run)
    copy_btn.clicked.connect(copy)
    run()
    dlg.exec()

