# ============================================================
# V208 JINGCAI FOOTBALL AI CENTER PATCH START
# 目标：补齐竞彩足球AI中心：胜平负、让球、比分、总进球、半全场、混合过关
# 说明：只做增量补丁，不破坏原V111/V207完整体系。
# ============================================================

def _v208_float(x, default=0.0):
    try:
        s = str(x).replace("—", "").replace("--", "").replace("%", "").strip()
        if not s:
            return default
        return float(s)
    except Exception:
        return default


def _v208_odds_probs(win_odds, draw_odds, lose_odds):
    """欧赔转隐含概率，并做返还率归一。"""
    vals = [_v208_float(win_odds, 0), _v208_float(draw_odds, 0), _v208_float(lose_odds, 0)]
    inv = [(1.0 / v if v and v > 1.01 else 0.0) for v in vals]
    if sum(inv) <= 0:
        inv = [0.42, 0.28, 0.30]
    total = sum(inv) or 1.0
    return [x / total for x in inv]


def _v208_confidence(probs):
    ps = sorted(probs, reverse=True)
    gap = ps[0] - ps[1] if len(ps) > 1 else ps[0]
    conf = 50 + gap * 85 + max(0, ps[0] - 0.45) * 60
    return max(45, min(92, int(conf)))


def _v208_recommend_spf(probs):
    labels = ["3", "1", "0"]
    pairs = sorted(zip(probs, labels), reverse=True)
    # 主推 + 防守逻辑：第一概率不够高时带第二选择
    if pairs[0][0] >= 0.56 or (pairs[0][0] - pairs[1][0]) >= 0.16:
        return [pairs[0][1]]
    return [pairs[0][1], pairs[1][1]]


def _v208_score_and_goal(probs):
    pw, pd, pl = probs
    # 简化Poisson风格估计：强势方均值上调，平局倾向低比分
    if pd >= max(pw, pl) * 0.92:
        scores = [("1:1", 16), ("0:0", 12), ("2:2", 9), ("1:0", 8), ("0:1", 8)]
        goals = [("2球", 27), ("0球", 13), ("4球", 11), ("1球", 10), ("3球", 10)]
    elif pw >= pl:
        margin = pw - pl
        if margin > 0.24:
            scores = [("2:0", 15), ("2:1", 13), ("3:1", 10), ("1:0", 9), ("3:0", 7)]
            goals = [("2球", 23), ("3球", 22), ("4球", 13), ("1球", 11)]
        else:
            scores = [("2:1", 14), ("1:0", 12), ("1:1", 11), ("2:0", 9), ("0:0", 6)]
            goals = [("2球", 25), ("3球", 20), ("1球", 16), ("0球", 8)]
    else:
        margin = pl - pw
        if margin > 0.24:
            scores = [("0:2", 15), ("1:2", 13), ("1:3", 10), ("0:1", 9), ("0:3", 7)]
            goals = [("2球", 23), ("3球", 22), ("4球", 13), ("1球", 11)]
        else:
            scores = [("1:2", 14), ("0:1", 12), ("1:1", 11), ("0:2", 9), ("0:0", 6)]
            goals = [("2球", 25), ("3球", 20), ("1球", 16), ("0球", 8)]
    return scores, goals


def _v208_handicap_pick(probs, handicap_text):
    """让球胜平负粗略推断。"""
    h = _v208_float(handicap_text, 0)
    pw, pd, pl = probs
    if h < 0:  # 主队让球，主胜难度降低
        adj_w = max(0.05, pw - abs(h) * 0.11)
        adj_d = min(0.45, pd + abs(h) * 0.05)
        adj_l = min(0.80, pl + abs(h) * 0.06)
    elif h > 0:  # 主队受让
        adj_w = min(0.80, pw + abs(h) * 0.08)
        adj_d = min(0.45, pd + abs(h) * 0.04)
        adj_l = max(0.05, pl - abs(h) * 0.12)
    else:
        adj_w, adj_d, adj_l = pw, pd, pl
    return _v208_recommend_spf([adj_w, adj_d, adj_l])


def _v208_half_full(probs):
    pw, pd, pl = probs
    if pw >= max(pd, pl):
        return ["平/胜", "胜/胜"] if pw < 0.52 else ["胜/胜", "平/胜"]
    if pl >= max(pw, pd):
        return ["平/负", "负/负"] if pl < 0.52 else ["负/负", "平/负"]
    return ["平/平", "胜/平", "负/平"]


def _v208_analyze_match(self, m):
    probs = _v208_odds_probs(m.get("胜赔", ""), m.get("平赔", ""), m.get("负赔", ""))
    # 支持率补偿：若页面抓到了百分比，做少量修正
    sup = [_v208_float(m.get("主支持率", 0), 0), _v208_float(m.get("平支持率", 0), 0), _v208_float(m.get("客支持率", 0), 0)]
    if sum(sup) > 0:
        st = sum(sup) or 1
        sup = [x / st for x in sup]
        probs = [probs[i] * 0.82 + sup[i] * 0.18 for i in range(3)]
        t = sum(probs) or 1
        probs = [x / t for x in probs]
    spf = _v208_recommend_spf(probs)
    rq = _v208_handicap_pick(probs, m.get("让球", "0"))
    scores, goals = _v208_score_and_goal(probs)
    conf = _v208_confidence(probs)
    risk = "低" if conf >= 72 else ("中" if conf >= 60 else "高")
    return {
        "序号": m.get("序号", ""),
        "联赛": m.get("联赛", ""),
        "主队": m.get("主队", ""),
        "客队": m.get("客队", ""),
        "让球": m.get("让球", "0"),
        "胜率": probs[0], "平率": probs[1], "负率": probs[2],
        "胜平负": spf,
        "让球胜平负": rq,
        "比分": scores[:3],
        "总进球": goals[:3],
        "半全场": _v208_half_full(probs),
        "信心": conf,
        "风险": risk,
        "比赛时间": m.get("比赛时间", ""),
        "截止时间": m.get("截止时间", ""),
    }


def _v208_build_mix_pass(analyses, mode="稳健"):
    """生成2串1/3串1/4串1参考。"""
    if not analyses:
        return []
    ordered = sorted(analyses, key=lambda x: x.get("信心", 0), reverse=True)
    if mode == "搏冷":
        ordered = sorted(analyses, key=lambda x: abs(x.get("胜率", 0)-x.get("负率", 0)))
    elif mode == "均衡":
        ordered = sorted(analyses, key=lambda x: x.get("信心", 0), reverse=True)
    groups = []
    for n in (2, 3, 4):
        if len(ordered) >= n:
            picks = []
            for a in ordered[:n]:
                picks.append(f"{a.get('序号','')}{a.get('主队','')}vs{a.get('客队','')}({''.join(a.get('胜平负', []))})")
            groups.append(f"{n}串1：" + " × ".join(picks))
    return groups


