# ============================================================
# V212 FAST INCREMENTAL UPDATE ENGINE PATCH START
# 目标：解决“更新慢 / 更新卡死 / 更新失败后界面无响应”
# - 数字彩只做增量：默认每个玩法拉取最近60期，按期号去重合并
# - 网络请求放入 QThread，UI只接收信号，不直接卡主线程
# - 保存策略：单玩法增量保存到 SQLite；全部完成后再写 JSON
# - 失败不中断全局更新，逐个玩法输出报告
# ============================================================

try:
    class FastIncrementalUpdateThread(QThread):
        progress = Signal(int, int, str)
        game_records = Signal(str, list)
        game_error = Signal(str, str)
        finished_report = Signal(list)

        def __init__(self, app, games=None, count_per_game=60, parent=None):
            super().__init__(parent)
            self.app = app
            self.games = games or []
            self.count_per_game = int(count_per_game or 60)
            self._cancel = False
            self.report = []

        def cancel(self):
            self._cancel = True

        def run(self):
            total = len(self.games)
            for idx, game in enumerate(self.games, 1):
                if self._cancel:
                    self.report.append('用户取消更新')
                    break
                try:
                    self.progress.emit(idx-1, total, f'正在增量更新：{game}')
                    caid = None
                    try:
                        caid = JISUAPI_CONFIG.get('lottery_id_map', {}).get(game)
                    except Exception:
                        caid = None
                    if not caid:
                        msg = f'{game}：未配置极速API彩种ID，已跳过'
                        self.report.append(msg)
                        self.game_error.emit(game, msg)
                        continue
                    records = self.app.fetch_jisuapi_lottery_history(game, count=self.count_per_game)
                    if not isinstance(records, list):
                        records = []
                    self.game_records.emit(game, records)
                    self.report.append(f'{game}：接口返回 {len(records)} 期')
                except Exception as e:
                    msg = f'{game}：{e}'
                    self.report.append(msg)
                    self.game_error.emit(game, str(e))
            self.progress.emit(total, total, '增量更新完成')
            self.finished_report.emit(self.report)

    def _v212_supported_lottery_games(self):
        try:
            unsupported = set(JISUAPI_CONFIG.get('football_lottery_types', []))
            games = []
            for g, caid in JISUAPI_CONFIG.get('lottery_id_map', {}).items():
                if g in unsupported:
                    continue
                if caid:
                    games.append(g)
            return games
        except Exception:
            return ['双色球','3D','七乐彩','快乐8','大乐透','七星彩','排列三','排列五']

    def _v212_merge_update_records(self, game, records):
        """主线程安全合并增量数据，返回新增期数。"""
        try:
            if not isinstance(records, list):
                records = []
            old = list((getattr(self, 'history_data', {}) or {}).get(game, []) or [])
            seen = {str(r.get('期号', r.get('issue', ''))).strip() for r in old if isinstance(r, dict)}
            added = 0
            for rec in records:
                if not isinstance(rec, dict):
                    continue
                issue = str(rec.get('期号', rec.get('issue', ''))).strip()
                if issue and issue not in seen:
                    old.append(rec)
                    seen.add(issue)
                    added += 1
            try:
                old.sort(key=lambda r: str(r.get('期号', r.get('issue', ''))), reverse=True)
            except Exception:
                pass
            self.history_data[game] = old
            try:
                if hasattr(self, 'db_store') and self.db_store:
                    self.db_store.save_one_game(game, old)
            except Exception as e:
                logger.debug(f'V212 SQLite单玩法保存失败 {game}: {e}')
            return added
        except Exception as e:
            try: logger.warning(f'V212合并增量失败 {game}: {e}')
            except Exception: pass
            return 0

    def _v212_open_fast_update_center(self):
        dlg = QDialog(self)
        dlg.setWindowTitle('⚡ 极速增量更新中心 V212')
        try:
            _auto_size_dialog(dlg, 720, 780)
        except Exception:
            dlg.resize(720, 780)
        lay = QVBoxLayout(dlg)
        title = QLabel('⚡ 极速增量更新中心')
        title.setStyleSheet('font-size:18px;font-weight:bold;color:#D35400;padding:6px;')
        lay.addWidget(title)
        tip = QLabel('默认每个玩法只拉取最近60期，按期号去重合并；比全量更新更适合日常使用。')
        tip.setWordWrap(True)
        tip.setStyleSheet('color:#555;padding:4px;')
        lay.addWidget(tip)

        row = QHBoxLayout()
        row.addWidget(QLabel('每个玩法拉取期数：'))
        spin = QSpinBox(); spin.setRange(20, 500); spin.setSingleStep(20); spin.setValue(60)
        row.addWidget(spin)
        lay.addLayout(row)

        games_box = QGroupBox('更新玩法')
        grid = QGridLayout(games_box)
        checks = []
        games = self._v212_supported_lottery_games()
        for i, g in enumerate(games):
            cb = QCheckBox(g); cb.setChecked(True)
            checks.append(cb)
            grid.addWidget(cb, i//2, i%2)
        lay.addWidget(games_box)

        progress = QProgressBar(); progress.setRange(0, max(1, len(games))); progress.setValue(0)
        lay.addWidget(progress)
        log = QTextEdit(); log.setReadOnly(True)
        log.setPlainText('等待开始更新…')
        lay.addWidget(log, 1)

        btn_row = QHBoxLayout()
        start_btn = QPushButton('开始极速增量更新')
        cancel_btn = QPushButton('取消')
        close_btn = QPushButton('关闭')
        for b in (start_btn, cancel_btn, close_btn):
            b.setMinimumHeight(_sc(40) if '_sc' in globals() else 40)
            btn_row.addWidget(b)
        lay.addLayout(btn_row)

        state = {'thread': None, 'added': {}, 'errors': []}

        def append(s):
            log.append(s)
            try: log.moveCursor(log.textCursor().End)
            except Exception: pass

        def start():
            selected = [cb.text() for cb in checks if cb.isChecked()]
            if not selected:
                QMessageBox.warning(dlg, '提示', '请至少选择一个玩法。')
                return
            key = getattr(self, 'jisuapi_key', '') or getattr(self, 'api_key', '')
            if not key:
                QMessageBox.warning(dlg, '缺少API密钥', '请先设置极速API密钥。')
                return
            start_btn.setEnabled(False)
            progress.setRange(0, len(selected)); progress.setValue(0)
            log.setPlainText('开始极速增量更新…')
            state['added'] = {}; state['errors'] = []
            th = FastIncrementalUpdateThread(self, selected, spin.value(), dlg)
            state['thread'] = th

            def on_progress(i, total, text):
                progress.setMaximum(max(1, total)); progress.setValue(i); append(text)

            def on_records(game, records):
                added = self._v212_merge_update_records(game, records)
                state['added'][game] = added
                append(f'✅ {game}：返回{len(records)}期，新增{added}期')

            def on_err(game, msg):
                state['errors'].append((game, msg))
                append(f'⚠ {game}：{msg}')

            def on_finish(report):
                try:
                    self._save_all_history()
                except Exception as e:
                    append(f'⚠ JSON保存失败：{e}')
                try:
                    QTimer.singleShot(300, lambda: self.update_home_results())
                    QTimer.singleShot(800, lambda: self.calculate_omission())
                except Exception:
                    pass
                total_added = sum(state['added'].values())
                append('\n===== 更新完成 =====')
                append(f'本次新增：{total_added}期')
                append('明细：' + '；'.join([f'{g}+{n}' for g, n in state['added'].items()]))
                if state['errors']:
                    append('失败/跳过：' + '；'.join([f'{g}:{m}' for g, m in state['errors']]))
                start_btn.setEnabled(True)

            th.progress.connect(on_progress)
            th.game_records.connect(on_records)
            th.game_error.connect(on_err)
            th.finished_report.connect(on_finish)
            th.start()

        def cancel():
            th = state.get('thread')
            if th and th.isRunning():
                th.cancel(); append('正在取消，等待当前请求结束…')

        start_btn.clicked.connect(start)
        cancel_btn.clicked.connect(cancel)
        close_btn.clicked.connect(dlg.accept)
        dlg.exec()

    LotteryApp._v212_supported_lottery_games = _v212_supported_lottery_games
    LotteryApp._v212_merge_update_records = _v212_merge_update_records
    LotteryApp.open_fast_update_center = _v212_open_fast_update_center

    # 用极速增量更新替换“自动更新全部玩法”的重型路径，减少后台卡顿
    def _v212_auto_update_all_games(self):
        try:
            games = self._v212_supported_lottery_games()
            if not games:
                return
            th = FastIncrementalUpdateThread(self, games, 40, self)
            self._v212_auto_thread = th
            th.game_records.connect(lambda game, records: self._v212_merge_update_records(game, records))
            th.finished_report.connect(lambda report: (self._save_all_history(), self.update_home_info() if hasattr(self, 'update_home_info') else None))
            th.start()
        except Exception as e:
            try: logger.error(f'V212自动增量更新失败: {e}', exc_info=True)
            except Exception: pass
    LotteryApp.auto_update_all_games = _v212_auto_update_all_games

    # 首页插入 V212 更新按钮
    _V212_ORIG_INIT_HOME_TAB = LotteryApp.init_home_tab
    def _v212_init_home_tab(self):
        _V212_ORIG_INIT_HOME_TAB(self)
        try:
            if getattr(self, '_v212_fast_update_btn_added', False):
                return
            scroll = self.home_tab.findChild(QScrollArea)
            page = scroll.widget() if scroll else None
            lay = page.layout() if page else self.home_tab.layout()
            if lay is None:
                return
            btn = QPushButton('⚡ 极速增量更新中心（推荐日常使用）')
            btn.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Fixed)
            btn.setMinimumHeight(_sc(42) if '_sc' in globals() else 42)
            btn.setStyleSheet('background:#D35400;color:white;font-weight:bold;font-size:13px;padding:9px;border-radius:7px;')
            btn.clicked.connect(lambda: self.open_fast_update_center())
            insert_at = 2 if lay.count() >= 2 else lay.count()
            lay.insertWidget(insert_at, btn)
            self._v212_fast_update_btn_added = True
        except Exception as e:
            try: logger.debug(f'V212首页极速更新按钮插入失败:{e}')
            except Exception: pass
    LotteryApp.init_home_tab = _v212_init_home_tab

    # 标题标识
    _V212_ORIG_INIT = LotteryApp.__init__
    def _v212_init(self, *a, **kw):
        _V212_ORIG_INIT(self, *a, **kw)
        try: self.setWindowTitle('彩乐荟聚 - V212 极速增量更新引擎版')
        except Exception: pass
    LotteryApp.__init__ = _v212_init

except Exception as _e:
    try: logger.warning(f'V212极速增量更新引擎安装失败: {_e}')
    except Exception: pass

