# ============================================================
# V213 HEALTH CHECK + DATA REPAIR CENTER PATCH START
# ------------------------------------------------------------
# 目标：给大体量程序增加“体检/修复/备份”中心，方便手机端定位慢、卡、缺数据、旧字段崩溃等问题。
# 不删除旧功能；只做安全猴子补丁。
# ============================================================
try:
    import shutil as _v213_shutil
    import time as _v213_time

    def _v213_count_json_records(self):
        """统计 history_data.json / 内存历史数据体量。"""
        data = getattr(self, 'history_data', None)
        if not isinstance(data, dict):
            try:
                if HISTORY_DATA_FILE.exists():
                    with open(HISTORY_DATA_FILE, 'r', encoding='utf-8') as f:
                        data = json.load(f)
                else:
                    data = {}
            except Exception:
                data = {}
        rows = []
        total = 0
        for game, records in sorted(data.items(), key=lambda x: str(x[0])):
            if isinstance(records, list):
                n = len(records); total += n
                latest = ''
                try:
                    if records:
                        latest = str(records[0].get('期号', records[0].get('issue', '')))
                except Exception:
                    pass
                rows.append((game, n, latest))
        return total, rows

    def _v213_safe_file_size(path):
        try:
            p = Path(path)
            return p.stat().st_size if p.exists() else 0
        except Exception:
            return 0

    def _v213_fmt_size(n):
        try:
            n = float(n)
            for unit in ['B','KB','MB','GB']:
                if n < 1024:
                    return f'{n:.1f}{unit}'
                n /= 1024
            return f'{n:.1f}TB'
        except Exception:
            return '0B'

    def _v213_backup_core_files(self):
        """备份核心数据文件到 CaileBackup 目录。"""
        backup_dir = APP_DIR / 'CaileBackup'
        backup_dir.mkdir(parents=True, exist_ok=True)
        ts = datetime.now().strftime('%Y%m%d_%H%M%S')
        copied = []
        candidates = [
            HISTORY_DATA_FILE,
            BETTING_HISTORY_FILE,
            CONFIG_FILE,
            MODEL_SCORES_FILE,
            FULL_BACKTEST_FILE,
            PREDICTION_LOG_FILE,
            APP_DIR / 'caile_cache.db',
        ]
        for src in candidates:
            try:
                p = Path(src)
                if p.exists():
                    dst = backup_dir / f'{p.stem}_{ts}{p.suffix}'
                    _v213_shutil.copy2(str(p), str(dst))
                    copied.append(dst.name)
            except Exception as e:
                copied.append(f'{Path(src).name}:备份失败({e})')
        return backup_dir, copied

    def _v213_repair_history_basic(self):
        """轻量修复历史数据：去重、剔除空期号、按期号倒序。"""
        data = getattr(self, 'history_data', None)
        if not isinstance(data, dict):
            return '内存 history_data 不存在或格式异常，未修复。'
        fixed_games = 0; removed = 0
        for game, records in list(data.items()):
            if not isinstance(records, list):
                continue
            seen = set(); new = []
            for r in records:
                if not isinstance(r, dict):
                    removed += 1; continue
                issue = str(r.get('期号', r.get('issue', r.get('issueno', '')))).strip()
                if not issue:
                    removed += 1; continue
                if issue in seen:
                    removed += 1; continue
                seen.add(issue)
                if '期号' not in r: r['期号'] = issue
                if '开奖号码' not in r and 'numbers' in r: r['开奖号码'] = r.get('numbers', '')
                new.append(r)
            try:
                new.sort(key=lambda x: str(x.get('期号','')), reverse=True)
            except Exception:
                pass
            if len(new) != len(records):
                fixed_games += 1
            data[game] = new
        try:
            if hasattr(self, '_save_all_history'):
                self._save_all_history()
            else:
                with open(HISTORY_DATA_FILE, 'w', encoding='utf-8') as f:
                    json.dump(data, f, ensure_ascii=False, indent=2)
        except Exception as e:
            return f'修复完成但保存失败：{e}'
        return f'修复完成：处理 {fixed_games} 个玩法，移除/合并 {removed} 条异常或重复记录。'

    def _v213_run_health_report(self):
        total, rows = self._v213_count_json_records()
        files = [
            ('history_data.json', HISTORY_DATA_FILE),
            ('betting_history.json', BETTING_HISTORY_FILE),
            ('config.json', CONFIG_FILE),
            ('model_scores.json', MODEL_SCORES_FILE),
            ('full_backtest_scores.json', FULL_BACKTEST_FILE),
            ('prediction_log.json', PREDICTION_LOG_FILE),
            ('caile_cache.db', APP_DIR / 'caile_cache.db'),
        ]
        lines = []
        lines.append('【彩乐 V213 程序体检报告】')
        lines.append(f'生成时间：{datetime.now().strftime("%Y-%m-%d %H:%M:%S")}')
        lines.append('')
        lines.append('一、核心文件体积')
        for name, path in files:
            lines.append(f'  {name}: {_v213_fmt_size(_v213_safe_file_size(path))}')
        lines.append('')
        lines.append('二、历史数据概况')
        lines.append(f'  总记录：{total} 期')
        if not rows:
            lines.append('  未检测到历史开奖数据。')
        else:
            for game, n, latest in rows:
                lines.append(f'  {game}: {n}期，最新期号 {latest or "未知"}')
        lines.append('')
        lines.append('三、启动/页面慢的建议')
        hist_size = _v213_safe_file_size(HISTORY_DATA_FILE)
        log_size = _v213_safe_file_size(PREDICTION_LOG_FILE)
        if hist_size > 8 * 1024 * 1024:
            lines.append('  - history_data.json 较大，建议使用 V206+ SQLite缓存并减少启动全量刷新。')
        if log_size > 3 * 1024 * 1024:
            lines.append('  - prediction_log.json 较大，建议定期备份后清理旧预测日志。')
        if total > 3000:
            lines.append('  - 历史数据期数较多，历史页建议分页/懒加载。')
        lines.append('  - 日常更新优先使用 V212 极速增量更新中心。')
        lines.append('  - 页面卡顿优先关闭自动全历史回测，改为手动执行。')
        lines.append('')
        lines.append('四、字段兼容状态')
        lines.append('  - stage23_ai / ai_jc / records_table 已做旧数据兜底。')
        lines.append('  - 若旧版本投注记录缺字段，可使用“轻量修复历史数据”。')
        return '\n'.join(lines)

    def _v213_open_health_center(self):
        dlg = QDialog(self)
        dlg.setWindowTitle('🧰 V213 程序体检与数据修复中心')
        try:
            _responsive_dlg_size(dlg, 760, 900)
        except Exception:
            dlg.resize(760, 900)
        lay = QVBoxLayout(dlg)
        title = QLabel('🧰 程序体检与数据修复中心')
        title.setAlignment(Qt.AlignCenter)
        title.setStyleSheet('font-size:18px;font-weight:bold;color:#2C3E50;padding:8px;')
        lay.addWidget(title)
        info = QLabel('用于检查启动慢、数据文件过大、历史数据重复、旧字段兼容等问题。建议升级/测试前先备份。')
        info.setWordWrap(True)
        info.setStyleSheet('color:#555;padding:6px;')
        lay.addWidget(info)
        out = QTextEdit()
        out.setReadOnly(True)
        out.setPlainText(self._v213_run_health_report())
        lay.addWidget(out, 1)
        grid = QGridLayout()
        btn_check = QPushButton('🔍 重新体检')
        btn_backup = QPushButton('💾 备份核心数据')
        btn_repair = QPushButton('🛠 轻量修复历史数据')
        btn_rebuild = QPushButton('🗄 重建SQLite缓存')
        btn_close = QPushButton('关闭')
        for i, b in enumerate([btn_check, btn_backup, btn_repair, btn_rebuild, btn_close]):
            b.setMinimumHeight(_sc(40) if '_sc' in globals() else 40)
            b.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Fixed)
            grid.addWidget(b, i // 2, i % 2)
        lay.addLayout(grid)

        def do_check():
            out.setPlainText(self._v213_run_health_report())
        def do_backup():
            backup_dir, copied = self._v213_backup_core_files()
            out.append('\n【备份结果】')
            out.append(f'备份目录：{backup_dir}')
            out.append('\n'.join(copied) if copied else '没有可备份的核心文件。')
        def do_repair():
            if QMessageBox.question(dlg, '确认修复', '修复前建议先备份。是否继续？') != QMessageBox.Yes:
                return
            out.append('\n【修复结果】')
            out.append(self._v213_repair_history_basic())
            out.append('\n' + self._v213_run_health_report())
        def do_rebuild():
            try:
                if hasattr(self, 'rebuild_sqlite_cache'):
                    self.rebuild_sqlite_cache()
                    out.append('\n【SQLite】缓存重建完成。')
                elif hasattr(self, '_v206_rebuild_sqlite_cache'):
                    self._v206_rebuild_sqlite_cache()
                    out.append('\n【SQLite】缓存重建完成。')
                else:
                    out.append('\n【SQLite】当前版本未发现重建缓存方法。')
            except Exception as e:
                out.append(f'\n【SQLite】重建失败：{e}')
        btn_check.clicked.connect(do_check)
        btn_backup.clicked.connect(do_backup)
        btn_repair.clicked.connect(do_repair)
        btn_rebuild.clicked.connect(do_rebuild)
        btn_close.clicked.connect(dlg.accept)
        dlg.exec()

    LotteryApp._v213_count_json_records = _v213_count_json_records
    LotteryApp._v213_backup_core_files = _v213_backup_core_files
    LotteryApp._v213_repair_history_basic = _v213_repair_history_basic
    LotteryApp._v213_run_health_report = _v213_run_health_report
    LotteryApp.open_health_center = _v213_open_health_center

    _V213_ORIG_INIT_HOME_TAB = LotteryApp.init_home_tab
    def _v213_init_home_tab(self):
        _V213_ORIG_INIT_HOME_TAB(self)
        try:
            if getattr(self, '_v213_health_btn_added', False):
                return
            scroll = self.home_tab.findChild(QScrollArea)
            page = scroll.widget() if scroll else None
            lay = page.layout() if page else self.home_tab.layout()
            if lay is None:
                return
            btn = QPushButton('🧰 程序体检 / 数据备份 / 轻量修复')
            btn.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Fixed)
            btn.setMinimumHeight(_sc(42) if '_sc' in globals() else 42)
            btn.setStyleSheet('background:#16A085;color:white;font-weight:bold;font-size:13px;padding:9px;border-radius:7px;')
            btn.clicked.connect(lambda: self.open_health_center())
            insert_at = 3 if lay.count() >= 3 else lay.count()
            lay.insertWidget(insert_at, btn)
            self._v213_health_btn_added = True
        except Exception as e:
            try: logger.debug(f'V213首页体检按钮插入失败:{e}')
            except Exception: pass
    LotteryApp.init_home_tab = _v213_init_home_tab

    _V213_ORIG_INIT = LotteryApp.__init__
    def _v213_init(self, *a, **kw):
        _V213_ORIG_INIT(self, *a, **kw)
        try: self.setWindowTitle('彩乐荟聚 - V213 体检修复增强版')
        except Exception: pass
    LotteryApp.__init__ = _v213_init

except Exception as _e:
    try: logger.warning(f'V213程序体检与数据修复中心安装失败: {_e}')
    except Exception: pass

# ============================================================
# V213 HEALTH CHECK + DATA REPAIR CENTER PATCH END
