class CaileDB:
    def __init__(self, path: Path = DB_FILE):
        self.path = Path(path)
        self.path.parent.mkdir(parents=True, exist_ok=True)
        self._init_db()

    def conn(self):
        db = sqlite3.connect(str(self.path), timeout=10)
        db.execute("PRAGMA journal_mode=WAL")
        db.execute("PRAGMA synchronous=NORMAL")
        db.execute("PRAGMA temp_store=MEMORY")
        return db

    def _init_db(self):
        with self.conn() as db:
            db.execute("""
                CREATE TABLE IF NOT EXISTS history_records (
                    game TEXT NOT NULL,
                    issue TEXT NOT NULL,
                    draw_date TEXT,
                    numbers TEXT,
                    raw_json TEXT NOT NULL,
                    updated_at TEXT,
                    PRIMARY KEY(game, issue)
                )
            """)
            db.execute("CREATE INDEX IF NOT EXISTS idx_history_game_issue ON history_records(game, issue DESC)")

            db.execute("""
                CREATE TABLE IF NOT EXISTS lottery_train_log (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    game TEXT,
                    status TEXT,
                    history_count INTEGER,
                    duration REAL,
                    message TEXT,
                    created_at TEXT
                )
            """)

            db.execute("""
                CREATE TABLE IF NOT EXISTS lottery_prediction_log (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    game TEXT,
                    target_issue TEXT,
                    numbers TEXT,
                    reason TEXT,
                    model_version TEXT,
                    raw_json TEXT,
                    created_at TEXT
                )
            """)

            db.execute("""
                CREATE TABLE IF NOT EXISTS sports_matches (
                    event_key TEXT PRIMARY KEY,
                    mode TEXT,
                    issue TEXT,
                    match_no TEXT,
                    event_date TEXT,
                    league TEXT,
                    home_team TEXT,
                    away_team TEXT,
                    home_score INTEGER,
                    away_score INTEGER,
                    odds_home REAL,
                    odds_draw REAL,
                    odds_away REAL,
                    status TEXT,
                    source TEXT,
                    raw_json TEXT,
                    updated_at TEXT
                )
            """)
            db.execute("CREATE INDEX IF NOT EXISTS idx_sports_mode_issue ON sports_matches(mode, issue)")
            db.execute("CREATE INDEX IF NOT EXISTS idx_sports_date ON sports_matches(event_date)")

            db.execute("""
                CREATE TABLE IF NOT EXISTS sports_train_log (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    status TEXT,
                    history_count INTEGER,
                    team_count INTEGER,
                    duration REAL,
                    score_json TEXT,
                    message TEXT,
                    created_at TEXT
                )
            """)

            db.execute("""
                CREATE TABLE IF NOT EXISTS sports_recommend_history (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    created_at TEXT,
                    mode TEXT,
                    issue TEXT,
                    match_no TEXT,
                    home_team TEXT,
                    away_team TEXT,
                    pick TEXT,
                    prob REAL,
                    ev REAL,
                    confidence REAL,
                    model_version TEXT,
                    train_time TEXT,
                    raw_json TEXT
                )
            """)

    @staticmethod
    def _issue(rec: dict) -> str:
        return str(rec.get("期号") or rec.get("issue") or rec.get("issueno") or "").strip()

    @staticmethod
    def _numbers(rec: dict) -> str:
        return str(rec.get("开奖号码") or rec.get("numbers") or rec.get("number") or "").strip()

    def upsert_lottery_records(self, game: str, records: list[dict]) -> dict:
        before = self.count_lottery_records(game)
        ok = 0
        damaged = 0
        now = now_str()
        with self.conn() as db:
            for rec in records or []:
                if not isinstance(rec, dict):
                    damaged += 1
                    continue
                issue = self._issue(rec)
                nums = self._numbers(rec)
                if not issue or not nums:
                    damaged += 1
                    continue
                draw_date = str(rec.get("开奖日期") or rec.get("date") or rec.get("opendate") or "")
                db.execute("""
                    INSERT OR REPLACE INTO history_records(game,issue,draw_date,numbers,raw_json,updated_at)
                    VALUES(?,?,?,?,?,?)
                """, (game, issue, draw_date, nums, json.dumps(rec, ensure_ascii=False), now))
                ok += 1
        after = self.count_lottery_records(game)
        return {"before": before, "after": after, "added": max(0, after - before), "ok": ok, "damaged": damaged}

    def load_lottery_records(self, game: str, limit: int = 0) -> list[dict]:
        q = "SELECT raw_json FROM history_records WHERE game=? ORDER BY issue DESC"
        params: tuple = (game,)
        if limit and limit > 0:
            q += " LIMIT ?"
            params = (game, limit)
        out = []
        with self.conn() as db:
            for (raw,) in db.execute(q, params).fetchall():
                try:
                    r = json.loads(raw)
                    if isinstance(r, dict):
                        out.append(r)
                except Exception:
                    pass
        return out

    def count_lottery_records(self, game: str) -> int:
        try:
            with self.conn() as db:
                return int(db.execute("SELECT COUNT(*) FROM history_records WHERE game=?", (game,)).fetchone()[0])
        except Exception:
            return 0

    @staticmethod
    def sports_event_key(ev: dict) -> str:
        base = "%s|%s|%s|%s" % (
            ev.get("event_date", ""), ev_league_name(ev), ev.get("home_team", ""), ev.get("away_team", "")
        )
        return hashlib.md5(base.encode("utf-8")).hexdigest()

    def upsert_sports_matches(self, rows: list[dict], mode: str = "jingcai", issue: str = "") -> int:
        n = 0
        with self.conn() as db:
            for ev in rows or []:
                if not isinstance(ev, dict):
                    continue
                h = str(ev.get("home_team") or "").strip()
                a = str(ev.get("away_team") or "").strip()
                if not h or not a:
                    continue
                sc = ev_score(ev)
                odds = ev_odds(ev) or {}
                key = str(ev.get("event_key") or self.sports_event_key(ev))
                db.execute("""
                    INSERT OR REPLACE INTO sports_matches
                    (event_key,mode,issue,match_no,event_date,league,home_team,away_team,home_score,away_score,
                     odds_home,odds_draw,odds_away,status,source,raw_json,updated_at)
                    VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
                """, (
                    key, mode, str(ev.get("issue") or issue or ""), str(ev.get("match_no") or ""),
                    str(ev.get("event_date") or ""), ev_league_name(ev), h, a,
                    sc[0] if sc else None, sc[1] if sc else None,
                    odds.get("odds_home"), odds.get("odds_draw"), odds.get("odds_away"),
                    str(ev.get("status") or ev.get("event_status") or ""), str(ev.get("source") or "BSD"),
                    json.dumps(ev, ensure_ascii=False), now_str()
                ))
                n += 1
        return n

    def load_sports_matches(self, mode: str = "jingcai", only_future: bool = False, only_finished: bool = False, limit: int = 50000) -> list[dict]:
        wh = ["mode=?"]
        params: list[Any] = [mode]
        if only_finished:
            wh.append("home_score IS NOT NULL AND away_score IS NOT NULL")
        q = "SELECT raw_json FROM sports_matches WHERE " + " AND ".join(wh) + " ORDER BY event_date DESC LIMIT ?"
        params.append(limit)
        out = []
        with self.conn() as db:
            for (raw,) in db.execute(q, tuple(params)).fetchall():
                try:
                    ev = json.loads(raw)
                    if isinstance(ev, dict):
                        out.append(ev)
                except Exception:
                    pass
        if only_future:
            now = datetime.now(timezone.utc)
            out = [x for x in out if (ev_dt(x) and ev_dt(x) >= now)]
        return out

    def log_lottery_train(self, game: str, status: str, history_count: int, duration: float, message: str) -> None:
        with self.conn() as db:
            db.execute("INSERT INTO lottery_train_log(game,status,history_count,duration,message,created_at) VALUES(?,?,?,?,?,?)",
                       (game, status, history_count, duration, message, now_str()))

    def log_lottery_prediction(self, game: str, target_issue: str, numbers: str, reason: str, raw: dict) -> None:
        with self.conn() as db:
            db.execute("""
                INSERT INTO lottery_prediction_log(game,target_issue,numbers,reason,model_version,raw_json,created_at)
                VALUES(?,?,?,?,?,?,?)
            """, (game, target_issue, numbers, reason, APP_VERSION, json.dumps(raw, ensure_ascii=False), now_str()))

DB = CaileDB()

