def parse_lottery_numbers(game: str, rec: dict) -> tuple[list[int], list[int]]:
    text = str(rec.get("开奖号码") or rec.get("numbers") or rec.get("number") or "")
    text = text.replace("，", " ").replace(",", " ").replace("|", "+")
    if "+" in text:
        left, right = text.split("+", 1)
        main = [int(x) for x in re_find_numbers(left)]
        sub = [int(x) for x in re_find_numbers(right)]
    else:
        nums = [int(x) for x in re_find_numbers(text)]
        cfg = LOTTERY_LIMITS.get(game, {})
        if cfg.get("has_sub"):
            main_need = int(cfg.get("main_need", 0))
            main, sub = nums[:main_need], nums[main_need:]
        else:
            main, sub = nums, []
    return main, sub


def re_find_numbers(text: str) -> list[str]:
    import re
    return re.findall(r"\d+", str(text))


class LotteryModelStore:
    def __init__(self, game: str):
        self.game = game
        self.dir = LOTTERY_MODEL_DIR / safe_name(game)
        self.dir.mkdir(parents=True, exist_ok=True)
        self.state_file = self.dir / "model_state.json"
        self.weights_file = self.dir / "model_weights.json"
        self.score_file = self.dir / "model_score.json"
        self.train_file = self.dir / "last_train_info.json"
        self.pred_file = self.dir / "prediction_log.json"
        self.backup_dir = self.dir / "backup"
        self.backup_dir.mkdir(exist_ok=True)

    def load_state(self) -> dict:
        return load_json(self.state_file, {}) or {}

    def load_weights(self) -> dict:
        return load_json(self.weights_file, {}) or {}

    def load_score(self) -> dict:
        return load_json(self.score_file, {}) or {}

    def backup(self) -> None:
        stamp = datetime.now().strftime("%Y%m%d_%H%M%S")
        bdir = self.backup_dir / stamp
        bdir.mkdir(parents=True, exist_ok=True)
        for f in (self.state_file, self.weights_file, self.score_file, self.train_file):
            if f.exists():
                shutil.copy2(f, bdir / f.name)

    def save_all(self, state: dict, weights: dict, score: dict, train_info: dict) -> None:
        atomic_write_json(self.state_file, state)
        atomic_write_json(self.weights_file, weights)
        atomic_write_json(self.score_file, score)
        atomic_write_json(self.train_file, train_info)

    def mark_dirty(self, history_count: int) -> None:
        st = self.load_state()
        old_count = int(st.get("history_count", 0) or 0)
        st.update({
            "game": self.game,
            "model_version": "lottery_v218",
            "history_count": history_count,
            "new_rows_since_train": max(0, history_count - old_count),
            "dirty": True,
            "status": "建议刷新" if old_count else "未训练",
            "updated_at": now_str(),
        })
        atomic_write_json(self.state_file, st)


class LotteryTrainCenter:
    """数字彩/乐透彩训练中心：只在用户点击训练时执行。"""

    def __init__(self, db: CaileDB = DB):
        self.db = db
        self.training = False

    def train_game(self, game: str, progress=None) -> dict:
        if self.training:
            return {"ok": False, "message": "已有训练任务正在运行"}
        self.training = True
        start = time.time()
        store = LotteryModelStore(game)
        try:
            records = self.db.load_lottery_records(game)
            if len(records) < 20:
                msg = "历史数据不足，至少需要20期"
                self.db.log_lottery_train(game, "failed", len(records), time.time() - start, msg)
                return {"ok": False, "message": msg}

            store.backup()
            if progress:
                progress("读取历史：%s %d期" % (game, len(records)))

            score = self._rolling_backtest(game, records)
            weights = self._build_weights_from_score(score)
            state = self._build_model_state(game, records, weights)
            train_info = {
                "game": game,
                "model_version": "lottery_v218",
                "trained_at": now_str(),
                "history_count": len(records),
                "new_rows_since_train": 0,
                "dirty": False,
                "status": "已训练",
                "duration": round(time.time() - start, 3),
                "model_count": len(PREDICTION_MODELS),
            }
            store.save_all(state, weights, score, train_info)
            self.db.log_lottery_train(game, "success", len(records), time.time() - start, "训练完成")
            return {"ok": True, "message": "训练完成", "history_count": len(records), "score": score, "weights": weights}
        except Exception as e:
            msg = traceback.format_exc()
            log_error(msg)
            self.db.log_lottery_train(game, "failed", 0, time.time() - start, str(e))
            return {"ok": False, "message": str(e)}
        finally:
            self.training = False

    def train_all_games(self, games: list[str] = None, progress=None) -> list[dict]:
        games = games or LOTTERY_GAMES
        out = []
        for i, game in enumerate(games, 1):
            if progress:
                progress("正在训练：%s 进度 %d/%d" % (game, i, len(games)))
            res = self.train_game(game, progress=progress)
            out.append({"game": game, **res})
        return out

    def _rolling_backtest(self, game: str, records: list[dict]) -> dict:
        # records 默认倒序，回测需要旧 -> 新
        asc = list(reversed(records))
        windows = [30, 50, 100]
        result = {}
        for w in windows:
            sample = asc[-w:] if len(asc) >= w else asc
            hits = []
            sub_hits = []
            for idx in range(max(10, len(asc) - len(sample)), len(asc)):
                hist = asc[:idx]
                target = asc[idx]
                pred_main, pred_sub = self._predict_by_frequency(game, hist)
                real_main, real_sub = parse_lottery_numbers(game, target)
                hits.append(len(set(pred_main) & set(real_main)))
                if pred_sub or real_sub:
                    sub_hits.append(len(set(pred_sub) & set(real_sub)))
            result["最近%d期" % w] = {
                "平均命中": round(sum(hits) / len(hits), 3) if hits else 0,
                "最高命中": max(hits) if hits else 0,
                "副区平均命中": round(sum(sub_hits) / len(sub_hits), 3) if sub_hits else 0,
                "回测期数": len(hits),
            }
        return result

    def _build_weights_from_score(self, score: dict) -> dict:
        # 保留所有模型；安卓不可用的真实模型后续可失败降级，但权重文件必须有。
        base = 1.0 / max(1, len(PREDICTION_MODELS))
        weights = {v["code"]: base for v in PREDICTION_MODELS.values()}
        # 先给稳健模型轻微加权，不删除任何模型。
        for code in ("random_forest", "extra_trees", "hist_gradient", "markov_chain", "bayesian", "champion_ensemble"):
            if code in weights:
                weights[code] *= 1.25
        s = sum(weights.values())
        return {k: round(v / s, 6) for k, v in weights.items()}

    def _build_model_state(self, game: str, records: list[dict], weights: dict) -> dict:
        freq_main = Counter()
        freq_sub = Counter()
        for r in records:
            main, sub = parse_lottery_numbers(game, r)
            freq_main.update(main)
            freq_sub.update(sub)
        return {
            "game": game,
            "model_version": "lottery_v218",
            "trained_at": now_str(),
            "history_count": len(records),
            "dirty": False,
            "status": "已训练",
            "model_count": len(PREDICTION_MODELS),
            "freq_main": dict(freq_main),
            "freq_sub": dict(freq_sub),
            "weights": weights,
        }

    def _predict_by_frequency(self, game: str, records: list[dict]) -> tuple[list[int], list[int]]:
        cfg = LOTTERY_LIMITS.get(game, LOTTERY_LIMITS["双色球"])
        freq_main = Counter()
        freq_sub = Counter()
        for r in records[-200:]:
            main, sub = parse_lottery_numbers(game, r)
            freq_main.update(main)
            freq_sub.update(sub)
        lo, hi = int(cfg.get("main_min", 1)), int(cfg.get("main_max", 33))
        need = int(cfg.get("main_need", 6))
        main = [n for n, _ in freq_main.most_common() if lo <= n <= hi][:need]
        while len(main) < need:
            n = random.randint(lo, hi)
            if n not in main:
                main.append(n)
        main.sort()
        sub = []
        if cfg.get("has_sub"):
            slo, shi, sneed = int(cfg.get("sub_min", 1)), int(cfg.get("sub_max", 16)), int(cfg.get("sub_need", 1))
            sub = [n for n, _ in freq_sub.most_common() if slo <= n <= shi][:sneed]
            while len(sub) < sneed:
                n = random.randint(slo, shi)
                if n not in sub:
                    sub.append(n)
            sub.sort()
        return main, sub


class LotteryPredictCenter:
    """数字彩/乐透彩预测中心：只读已保存模型，不训练。"""

    def __init__(self, db: CaileDB = DB):
        self.db = db

    def predict_game(self, game: str, target_issue: str = "") -> dict:
        store = LotteryModelStore(game)
        state = store.load_state()
        weights = store.load_weights()
        records = self.db.load_lottery_records(game)
        if not records:
            return {"ok": False, "message": "无历史数据"}

        dirty = bool(state.get("dirty"))
        if not state or state.get("status") in (None, "未训练"):
            # 未训练也能给统计兜底，但明确标注。
            main, sub = LotteryTrainCenter(self.db)._predict_by_frequency(game, list(reversed(records)))
            source = "未训练统计兜底"
        else:
            main, sub = self._predict_from_state(game, state)
            source = "已保存模型"

        text = self.format_numbers(game, main, sub)
        raw = {"game": game, "target_issue": target_issue, "main": main, "sub": sub, "dirty": dirty, "source": source, "weights": weights}
        self.db.log_lottery_prediction(game, target_issue, text, source, raw)
        return {"ok": True, "game": game, "numbers": text, "dirty": dirty, "source": source, "raw": raw}

    def _predict_from_state(self, game: str, state: dict) -> tuple[list[int], list[int]]:
        cfg = LOTTERY_LIMITS.get(game, LOTTERY_LIMITS["双色球"])
        freq_main = {int(k): int(v) for k, v in (state.get("freq_main") or {}).items() if str(k).isdigit()}
        freq_sub = {int(k): int(v) for k, v in (state.get("freq_sub") or {}).items() if str(k).isdigit()}
        lo, hi, need = int(cfg.get("main_min", 1)), int(cfg.get("main_max", 33)), int(cfg.get("main_need", 6))
        candidates = sorted(range(lo, hi + 1), key=lambda n: (freq_main.get(n, 0), random.random()), reverse=True)
        main = sorted(candidates[:need])
        sub = []
        if cfg.get("has_sub"):
            slo, shi, sneed = int(cfg.get("sub_min", 1)), int(cfg.get("sub_max", 16)), int(cfg.get("sub_need", 1))
            scands = sorted(range(slo, shi + 1), key=lambda n: (freq_sub.get(n, 0), random.random()), reverse=True)
            sub = sorted(scands[:sneed])
        return main, sub

    @staticmethod
    def format_numbers(game: str, main: list[int], sub: list[int]) -> str:
        if sub:
            return "%s + %s" % (" ".join("%02d" % n for n in main), " ".join("%02d" % n for n in sub))
        if game in ("福彩3D", "3D", "排列三", "排列五", "七星彩"):
            return " ".join(str(n) for n in main)
        return " ".join("%02d" % n for n in main)

# ============================================================
# 足彩 BSD v5 核心：数据、训练、推荐分离
# ============================================================

BSD_BASE_URL = "https://sports.bzzoiro.com/api/"
DEFAULT_TIMEOUT = 8
DEFAULT_CACHE_TTL = 6 * 3600
OUTCOMES = ("home", "draw", "away")
OUTCOME_CN = {"home": "主胜", "draw": "平", "away": "客胜"}
ABSENT_STATUSES = {"injured", "suspended"}
DEFAULT_WEIGHTS = {"model": 0.55, "market": 0.35, "extra": 0.10}
WEEKDAY_CN = ["周一", "周二", "周三", "周四", "周五", "周六", "周日"]

LEAGUE_CN = [("premier league", "英超"), ("world cup", "世界杯"), ("la liga", "西甲"), ("serie a", "意甲"), ("bundesliga", "德甲"), ("ligue 1", "法甲"), ("champions league", "欧冠"), ("mls", "美职联")]
TEAM_CN = {"Manchester City": "曼城", "Manchester United": "曼联", "Arsenal": "阿森纳", "Liverpool": "利物浦", "Chelsea": "切尔西", "Brazil": "巴西", "Morocco": "摩洛哥", "Qatar": "卡塔尔", "Switzerland": "瑞士", "Australia": "澳大利亚", "Turkey": "土耳其", "Türkiye": "土耳其"}


def cn_league(name: str) -> str:
    low = (name or "").lower()
    for key, cn in LEAGUE_CN:
        if key in low:
            return cn
    return name or ""


def cn_team(name: str) -> str:
    if not name:
        return ""
    return TEAM_CN.get(name, name)


def ev_dt(ev: dict) -> Optional[datetime]:
    s = str(ev.get("event_date") or "")
    if not s:
        return None
    for fmt in ("%Y-%m-%dT%H:%M:%S%z", "%Y-%m-%dT%H:%M:%SZ", "%Y-%m-%d %H:%M:%S", "%Y-%m-%dT%H:%M:%S.%f%z"):
        try:
            val = s.replace("+00:00", "+0000")
            dt = datetime.strptime(val, fmt)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=timezone.utc)
            return dt
        except ValueError:
            continue
    return None


def ev_dt_local(ev: dict) -> Optional[datetime]:
    dt = ev_dt(ev)
    if not dt:
        return None
    try:
        return dt.astimezone()
    except Exception:
        return dt


def ev_league_name(ev: dict) -> str:
    lg = ev.get("league")
    if isinstance(lg, dict):
        return str(lg.get("name") or lg.get("id") or "")
    return str(lg or "")


def ev_odds(ev: dict) -> Optional[dict]:
    out = {}
    for k in ("odds_home", "odds_draw", "odds_away"):
        try:
            v = float(ev.get(k))
        except Exception:
            return None
        if v <= 1.0:
            return None
        out[k] = v
    return out


def _first_number(*vals):
    for v in vals:
        try:
            if v is None or (isinstance(v, str) and not v.strip()):
                continue
            return int(float(v))
        except Exception:
            continue
    return None


def ev_score(ev: dict) -> Optional[tuple[int, int]]:
    hs = _first_number(ev.get("home_score"), ev.get("score_home"), ev.get("home_goals"), ev.get("homeScore"))
    aw = _first_number(ev.get("away_score"), ev.get("score_away"), ev.get("away_goals"), ev.get("awayScore"))
    if hs is not None and aw is not None:
        return hs, aw
    sc = ev.get("score") or ev.get("scores") or ev.get("result")
    if isinstance(sc, dict):
        hs = _first_number(sc.get("home"), sc.get("home_score"), sc.get("homeScore"))
        aw = _first_number(sc.get("away"), sc.get("away_score"), sc.get("awayScore"))
        if hs is not None and aw is not None:
            return hs, aw
    import re
    for key in ("score", "result", "full_time_score", "ft_score"):
        s = ev.get(key)
        if isinstance(s, str):
            m = re.search(r"(\d+)\s*[-:]\s*(\d+)", s)
            if m:
                return int(m.group(1)), int(m.group(2))
    return None


def ev_injuries(ev: dict) -> dict:
    out = {"home": [], "away": []}
    up = ev.get("unavailable_players")
    if not isinstance(up, dict):
        return out
    for side in ("home", "away"):
        rows = up.get(side)
        if not isinstance(rows, list):
            continue
        for p in rows:
            if isinstance(p, dict) and p.get("name"):
                out[side].append((str(p.get("name")), str(p.get("status", "")), str(p.get("reason", "")), str(p.get("expected_return") or "")))
    return out


def implied_from_odds(oh, od, oa) -> Optional[dict]:
    try:
        odds = [float(oh), float(od), float(oa)]
    except Exception:
        return None
    if any(o <= 1.0 for o in odds):
        return None
    inv = [1.0 / o for o in odds]
    s = sum(inv)
    out = {k: v / s for k, v in zip(OUTCOMES, inv)}
    out["overround"] = s - 1.0
    return out


def norm_probs(p: Optional[dict]) -> Optional[dict]:
    if not p:
        return None
    try:
        vals = [float(p[k]) for k in OUTCOMES]
    except Exception:
        return None
    s = sum(vals)
    if s <= 0 or any(v < 0 for v in vals):
        return None
    return {k: v / s for k, v in zip(OUTCOMES, vals)}


class BSDClient:
    def __init__(self, token: str = "", cache_dir: Path = CACHE_DIR / "bsd", cache_ttl: int = DEFAULT_CACHE_TTL, timeout: int = DEFAULT_TIMEOUT):
        self.token = (token or "").strip()
        self.cache_dir = Path(cache_dir)
        self.cache_dir.mkdir(parents=True, exist_ok=True)
        self.cache_ttl = cache_ttl
        self.timeout = timeout
        self.last_error = ""

    def _cache_path(self, url: str) -> Path:
        return self.cache_dir / (hashlib.md5(url.encode("utf-8")).hexdigest() + ".json")

    def _get(self, path: str, params: Optional[dict] = None):
        url = BSD_BASE_URL + path.lstrip("/")
        if params:
            url += "?" + urllib.parse.urlencode(params)
        p = self._cache_path(url)
        try:
            if p.exists() and time.time() - p.stat().st_mtime < self.cache_ttl:
                return load_json(p, None)
        except Exception:
            pass
        if not self.token:
            self.last_error = "未设置 BSD token"
            return None
        req = urllib.request.Request(url, headers={"Authorization": "Token " + self.token, "User-Agent": "caile-v218/1.0"})
        try:
            with urllib.request.urlopen(req, timeout=self.timeout) as resp:
                data = json.loads(resp.read().decode("utf-8"))
            atomic_write_json(p, data)
            return data
        except urllib.error.HTTPError as e:
            self.last_error = "BSD HTTP %s，可能是 token 无效或接口限制" % e.code
        except Exception as e:
            self.last_error = "BSD 请求失败: %s" % e
        return None

    def fetch_events(self, date_from: str, date_to: str, max_pages: int = 5) -> list:
        events, offset = [], 0
        for _ in range(max_pages):
            data = self._get("events/", {"date_from": date_from, "date_to": date_to, "tz": "UTC", "limit": 200, "offset": offset})
            if not isinstance(data, dict):
                return events
            rows = data.get("results")
            if not isinstance(rows, list):
                return events
            events.extend(x for x in rows if isinstance(x, dict))
            if not data.get("next"):
                break
            offset += 200
        return events

    def fetch_history_events(self, days: int = 365, max_pages: int = 80) -> list:
        d1 = datetime.utcnow().strftime("%Y-%m-%d")
        d0 = (datetime.utcnow() - timedelta(days=days)).strftime("%Y-%m-%d")
        events, offset = [], 0
        for _ in range(max_pages):
            data = self._get("events/", {"date_from": d0, "date_to": d1, "tz": "UTC", "limit": 200, "offset": offset})
            if not isinstance(data, dict):
                return events
            rows = data.get("results")
            if not isinstance(rows, list):
                return events
            events.extend(x for x in rows if isinstance(x, dict))
            if not data.get("next"):
                break
            offset += 200
        return events


class TeamHistoryCache:
    def __init__(self):
        self.events: list[dict] = []
        self.by_team: dict[str, list[dict]] = {}

    def build(self, rows: list[dict]) -> None:
        clean = []
        for ev in rows or []:
            if not isinstance(ev, dict) or ev_score(ev) is None:
                continue
            if not ev.get("home_team") or not ev.get("away_team"):
                continue
            clean.append(ev)
        clean.sort(key=lambda x: ev_dt_local(x) or datetime.min.replace(tzinfo=None), reverse=True)
        self.events = clean
        self.by_team = defaultdict(list)
        for ev in clean:
            self.by_team[str(ev.get("home_team"))].append(ev)
            self.by_team[str(ev.get("away_team"))].append(ev)

    def team_matches(self, team: str, limit: int = 10) -> list[dict]:
        return list(self.by_team.get(team, []))[:limit]

    def h2h(self, home: str, away: str, limit: int = 10) -> list[dict]:
        out = []
        for ev in self.events:
            h, a = str(ev.get("home_team")), str(ev.get("away_team"))
            if {h, a} == {home, away}:
                out.append(ev)
                if len(out) >= limit:
                    break
        return out

    @staticmethod
    def team_stats(team: str, matches: list[dict]) -> dict:
        win = draw = loss = gf = ga = valid = 0
        for ev in matches:
            sc = ev_score(ev)
            if not sc:
                continue
            h, a = str(ev.get("home_team")), str(ev.get("away_team"))
            hs, aw = sc
            if team == h:
                f, ag = hs, aw
            elif team == a:
                f, ag = aw, hs
            else:
                continue
            valid += 1; gf += f; ga += ag
            if f > ag: win += 1
            elif f == ag: draw += 1
            else: loss += 1
        return {"n": valid, "win": win, "draw": draw, "loss": loss, "gf": gf / valid if valid else 0.0, "ga": ga / valid if valid else 0.0}

TEAM_HISTORY = TeamHistoryCache()


class EloEngine:
    DEFAULT_RATING = 1500.0
    K = 28.0
    def __init__(self):
        self.ratings: dict[str, float] = {}
    def get(self, team: str) -> float:
        return float(self.ratings.get(team, self.DEFAULT_RATING))
    @staticmethod
    def expected(ra: float, rb: float) -> float:
        return 1.0 / (1.0 + 10 ** ((rb - ra) / 400.0))
    def rebuild_from_events(self, events: list[dict]) -> None:
        self.ratings = {}
        for ev in sorted(events, key=lambda x: ev_dt_local(x) or datetime.min.replace(tzinfo=None)):
            sc = ev_score(ev)
            if not sc: continue
            h, a = str(ev.get("home_team")), str(ev.get("away_team"))
            hs, aw = sc
            rh, ra = self.get(h) + 35.0, self.get(a)
            eh = self.expected(rh, ra)
            sh = 1.0 if hs > aw else 0.5 if hs == aw else 0.0
            margin = abs(hs - aw)
            mult = 1.0 + min(margin, 4) * 0.12
            self.ratings[h] = self.get(h) + self.K * mult * (sh - eh)
            self.ratings[a] = self.get(a) + self.K * mult * ((1 - sh) - (1 - eh))
    def model_probs(self, home: str, away: str) -> Optional[dict]:
        if not home or not away: return None
        eh = self.expected(self.get(home) + 35.0, self.get(away))
        draw = 0.27 + max(0, 0.08 - abs(eh - 0.5) * 0.18)
        remain = 1.0 - draw
        return norm_probs({"home": eh * remain, "draw": draw, "away": (1.0 - eh) * remain})

ELO = EloEngine()


class PoissonModel:
    @staticmethod
    def pmf(k: int, lam: float) -> float:
        lam = max(0.05, min(float(lam), 5.5))
        return math.exp(-lam) * (lam ** k) / math.factorial(k)
    @staticmethod
    def lambdas(home: str, away: str) -> tuple[float, float]:
        hs = TEAM_HISTORY.team_stats(home, TEAM_HISTORY.team_matches(home, 10))
        aw = TEAM_HISTORY.team_stats(away, TEAM_HISTORY.team_matches(away, 10))
        if hs["n"] >= 3 and aw["n"] >= 3:
            return max(0.25, min(0.58 * hs["gf"] + 0.42 * aw["ga"] + 0.18, 4.5)), max(0.20, min(0.58 * aw["gf"] + 0.42 * hs["ga"], 4.2))
        return 1.35, 1.05
    @staticmethod
    def outcome_probs(home: str, away: str) -> dict:
        lh, la = PoissonModel.lambdas(home, away)
        hp = dp = ap = 0.0
        for i in range(8):
            for j in range(8):
                p = PoissonModel.pmf(i, lh) * PoissonModel.pmf(j, la)
                if i > j: hp += p
                elif i == j: dp += p
                else: ap += p
        return norm_probs({"home": hp, "draw": dp, "away": ap}) or {"home": 0.36, "draw": 0.30, "away": 0.34}
    @staticmethod
    def score_tips(home: str, away: str, top: int = 3) -> list[tuple[int, int, float]]:
        lh, la = PoissonModel.lambdas(home, away)
        rows = []
        for i in range(6):
            for j in range(6):
                rows.append((i, j, PoissonModel.pmf(i, lh) * PoissonModel.pmf(j, la)))
        rows.sort(key=lambda x: x[2], reverse=True)
        return rows[:top]


def history_model_adjustment(home: str, away: str) -> Optional[dict]:
    hs = TEAM_HISTORY.team_stats(home, TEAM_HISTORY.team_matches(home, 10))
    aw = TEAM_HISTORY.team_stats(away, TEAM_HISTORY.team_matches(away, 10))
    if hs["n"] < 3 or aw["n"] < 3:
        return None
    hp = (hs["win"] * 3 + hs["draw"]) / max(hs["n"] * 3, 1)
    ap = (aw["win"] * 3 + aw["draw"]) / max(aw["n"] * 3, 1)
    gap = hp - ap
    return norm_probs({"home": 0.36 + gap * 0.22, "draw": 0.30 + (0.04 if abs(gap) < 0.08 else 0), "away": 0.34 - gap * 0.22})


class TeamModelEngine:
    @staticmethod
    def build_model_probs(ev: dict) -> Optional[dict]:
        odds = ev_odds(ev)
        if not odds: return None
        market = implied_from_odds(odds["odds_home"], odds["odds_draw"], odds["odds_away"])
        if not market: return None
        market.pop("overround", None)
        home, draw, away = market["home"] + 0.035, market["draw"], market["away"] - 0.020
        inj = ev_injuries(ev)
        home_abs = sum(1 for _, s, _, _ in inj["home"] if s in ABSENT_STATUSES)
        away_abs = sum(1 for _, s, _, _ in inj["away"] if s in ABSENT_STATUSES)
        home -= home_abs * 0.025; away -= away_abs * 0.025
        home += away_abs * 0.015; away += home_abs * 0.015
        base = norm_probs({"home": max(home, .05), "draw": max(draw, .08), "away": max(away, .05)})
        h, a = str(ev.get("home_team", "")), str(ev.get("away_team", ""))
        hp, ep, pp = history_model_adjustment(h, a), ELO.model_probs(h, a), PoissonModel.outcome_probs(h, a)
        weights = [(base, .45), (hp, .20), (ep, .18), (pp, .17)]
        weights = [(src, w) for src, w in weights if src]
        tw = sum(w for _, w in weights)
        out = {k: 0.0 for k in OUTCOMES}
        for src, w in weights:
            for k in OUTCOMES:
                out[k] += src[k] * w / tw
        return norm_probs(out)
    @staticmethod
    def confidence(adv: "MatchAdvice") -> float:
        if not adv.advices: return 0.0
        b = adv.best
        probs = sorted([a.prob for a in adv.advices], reverse=True)
        gap = probs[0] - probs[1] if len(probs) >= 2 else 0
        ev_part = max(0, min(b.ev, .20)) / .20
        gap_part = max(0, min(gap, .25)) / .25
        p_part = max(0, min(b.prob - .25, .45)) / .45
        return max(0, min((ev_part * .45 + gap_part * .35 + p_part * .20) * 100, 100))


@dataclass
class OutcomeAdvice:
    outcome: str
    prob: float
    odds: float
    ev: float
    level: str
    kelly: float
    @property
    def label(self) -> str: return OUTCOME_CN.get(self.outcome, self.outcome)

@dataclass
class MatchAdvice:
    home: str
    away: str
    match_no: str = ""
    fused: dict = field(default_factory=dict)
    advices: list[OutcomeAdvice] = field(default_factory=list)
    @property
    def best(self) -> Optional[OutcomeAdvice]: return self.advices[0] if self.advices else None


def kelly_fraction(p: float, odds: float, fraction: float = .25, cap: float = .05) -> float:
    b = odds - 1
    if b <= 0: return 0.0
    return max(0, min((p * b - (1 - p)) / b * fraction, cap))


def recommend_match(home: str, away: str, model_probs=None, odds=None, match_no="") -> MatchAdvice:
    adv = MatchAdvice(home=home, away=away, match_no=match_no)
    market = None
    if odds:
        market = implied_from_odds(odds.get("odds_home"), odds.get("odds_draw"), odds.get("odds_away"))
        if market: market.pop("overround", None)
    fused = model_probs or market
    fused = norm_probs(fused)
    if not fused or not odds: return adv
    adv.fused = fused
    for o, key in zip(OUTCOMES, ("odds_home", "odds_draw", "odds_away")):
        oo = float(odds.get(key)) if odds.get(key) else 0
        p = fused[o]
        ev = p * oo - 1 if oo else -1
        level = "推荐" if ev >= .05 and p >= .30 else "观望" if ev >= 0 else "回避"
        adv.advices.append(OutcomeAdvice(o, p, oo, ev, level, kelly_fraction(p, oo) if oo else 0))
    adv.advices.sort(key=lambda x: (x.ev, x.prob), reverse=True)
    return adv


def assign_match_numbers(events: list[dict]) -> list[tuple[str, dict]]:
    dated = [(ev_dt_local(e), e) for e in events]
    dated.sort(key=lambda t: (t[0] is None, t[0] or datetime.max.replace(tzinfo=None)))
    counters, out = {}, []
    for dt, e in dated:
        if dt is None:
            out.append(("", e)); continue
        key = dt.strftime("%Y-%m-%d")
        counters[key] = counters.get(key, 0) + 1
        no = "%s%03d" % (WEEKDAY_CN[dt.weekday()], counters[key])
        e["match_no"] = no
        out.append((no, e))
    return out


class SportsModelStore:
    def __init__(self):
        self.dir = SPORTS_MODEL_DIR
        self.dir.mkdir(parents=True, exist_ok=True)
        self.elo_file = self.dir / "elo_ratings.json"
        self.history_file = self.dir / "team_history_cache.json"
        self.poisson_file = self.dir / "poisson_team_stats.json"
        self.state_file = self.dir / "sports_model_state.json"
        self.score_file = self.dir / "sports_model_score.json"
        self.train_file = self.dir / "last_train_info.json"
        self.backup_dir = self.dir / "backup"
        self.backup_dir.mkdir(exist_ok=True)
    def load_state(self) -> dict: return load_json(self.state_file, {}) or {}
    def backup(self) -> None:
        stamp = datetime.now().strftime("%Y%m%d_%H%M%S")
        b = self.backup_dir / stamp; b.mkdir(parents=True, exist_ok=True)
        for f in (self.elo_file, self.history_file, self.poisson_file, self.state_file, self.score_file, self.train_file):
            if f.exists(): shutil.copy2(f, b / f.name)
    def save(self, state: dict, score: dict) -> None:
        atomic_write_json(self.elo_file, ELO.ratings)
        atomic_write_json(self.history_file, TEAM_HISTORY.events)
        atomic_write_json(self.state_file, state)
        atomic_write_json(self.score_file, score)
        atomic_write_json(self.train_file, state)
    def mark_dirty(self, history_count: int) -> None:
        st = self.load_state()
        old = int(st.get("history_count", 0) or 0)
        st.update({"dirty": True, "status": "建议刷新" if old else "未训练", "history_count": history_count, "new_rows_since_train": max(0, history_count - old), "updated_at": now_str()})
        atomic_write_json(self.state_file, st)

SPORTS_STORE = SportsModelStore()


class SportsUpdateCenter:
    def __init__(self, db: CaileDB = DB):
        self.db = db
    def update_future_matches(self, token: str, days: int = 3, mode: str = "jingcai") -> dict:
        c = BSDClient(token=token)
        d0 = datetime.utcnow().strftime("%Y-%m-%d")
        d1 = (datetime.utcnow() + timedelta(days=days)).strftime("%Y-%m-%d")
        rows = c.fetch_events(d0, d1)
        for no, ev in assign_match_numbers(rows):
            ev["match_no"] = no
        n = self.db.upsert_sports_matches(rows, mode=mode)
        return {"ok": bool(rows), "count": n, "message": "更新赛事%d场" % n if rows else c.last_error}
    def update_history_results(self, token: str, days: int = 365, mode: str = "jingcai") -> dict:
        c = BSDClient(token=token, cache_ttl=24 * 3600)
        rows = c.fetch_history_events(days=days)
        n = self.db.upsert_sports_matches(rows, mode=mode)
        finished = len([x for x in rows if ev_score(x) is not None])
        SPORTS_STORE.mark_dirty(self.count_finished(mode))
        return {"ok": bool(rows), "count": n, "finished": finished, "message": "历史保存%d场，带比分%d场" % (n, finished) if rows else c.last_error}
    def count_finished(self, mode="jingcai") -> int:
        return len(self.db.load_sports_matches(mode=mode, only_finished=True, limit=1000000))


class SportsTrainCenter:
    def __init__(self, db: CaileDB = DB):
        self.db = db
        self.training = False
    def train_sports_model(self, mode="jingcai", progress=None) -> dict:
        if self.training:
            return {"ok": False, "message": "足彩模型正在训练"}
        self.training = True
        start = time.time()
        try:
            rows = self.db.load_sports_matches(mode=mode, only_finished=True, limit=1000000)
            if len(rows) < 50:
                return {"ok": False, "message": "历史赛果不足，至少需要50场"}
            SPORTS_STORE.backup()
            if progress: progress("重建球队历史 %d场" % len(rows))
            TEAM_HISTORY.build(rows)
            ELO.rebuild_from_events(rows)
            score = self.backtest_sports_model(rows)
            state = {"model_version": "sports_v218_bsd_v5", "schema_version": 1, "trained_at": now_str(), "history_count": len(rows), "team_count": len(ELO.ratings), "dirty": False, "status": "已训练", "duration": round(time.time() - start, 3), "score": score}
            SPORTS_STORE.save(state, score)
            with self.db.conn() as db:
                db.execute("INSERT INTO sports_train_log(status,history_count,team_count,duration,score_json,message,created_at) VALUES(?,?,?,?,?,?,?)", ("success", len(rows), len(ELO.ratings), time.time() - start, json.dumps(score, ensure_ascii=False), "训练完成", now_str()))
            return {"ok": True, "message": "足彩训练完成", "state": state, "score": score}
        except Exception as e:
            log_error(traceback.format_exc())
            return {"ok": False, "message": str(e)}
        finally:
            self.training = False
    def backtest_sports_model(self, rows: list[dict]) -> dict:
        asc = sorted(rows, key=lambda x: ev_dt_local(x) or datetime.min.replace(tzinfo=None))
        test = asc[int(len(asc) * 0.8):]
        hit = goal_hit = score_top3_hit = total = 0
        for ev in test:
            sc = ev_score(ev)
            odds = ev_odds(ev)
            if not sc or not odds: continue
            adv = recommend_match(str(ev.get("home_team")), str(ev.get("away_team")), TeamModelEngine.build_model_probs(ev), odds, str(ev.get("match_no") or ""))
            if not adv.best: continue
            real = "home" if sc[0] > sc[1] else "draw" if sc[0] == sc[1] else "away"
            total += 1
            if adv.best.outcome == real: hit += 1
            tips = PoissonModel.score_tips(str(ev.get("home_team")), str(ev.get("away_team")), 3)
            if any(sc[0] == h and sc[1] == a for h, a, _ in tips): score_top3_hit += 1
            goals = sc[0] + sc[1]
            pred_goals = sum(t[0] + t[1] for t in tips) / max(1, len(tips))
            if (goals <= 1 and pred_goals <= 1.8) or (2 <= goals <= 3 and 1.5 <= pred_goals <= 3.6) or (goals >= 4 and pred_goals >= 3): goal_hit += 1
        return {"win_draw_loss_accuracy": round(hit / total, 4) if total else 0, "goal_range_accuracy": round(goal_hit / total, 4) if total else 0, "score_top3_accuracy": round(score_top3_hit / total, 4) if total else 0, "backtest_matches": total}


class SportsRecommendCenter:
    def __init__(self, db: CaileDB = DB):
        self.db = db
        self.load_saved_model()
    def load_saved_model(self):
        ratings = load_json(SPORTS_STORE.elo_file, {}) or {}
        ELO.ratings = {str(k): float(v) for k, v in ratings.items()} if isinstance(ratings, dict) else {}
        hist = load_json(SPORTS_STORE.history_file, []) or []
        if isinstance(hist, list): TEAM_HISTORY.build(hist)
    def generate_sports_recommend(self, mode="jingcai", limit=200) -> list[dict]:
        self.load_saved_model()
        rows = self.db.load_sports_matches(mode=mode, only_future=True, limit=limit)
        out = []
        state = SPORTS_STORE.load_state()
        for no, ev in assign_match_numbers(rows):
            odds = ev_odds(ev)
            adv = recommend_match(str(ev.get("home_team")), str(ev.get("away_team")), TeamModelEngine.build_model_probs(ev), odds, no)
            if not adv.best: continue
            item = {"mode": mode, "match_no": no, "home": cn_team(str(ev.get("home_team"))), "away": cn_team(str(ev.get("away_team"))), "pick": adv.best.label, "code310": {"主胜":"3", "平":"1", "客胜":"0"}.get(adv.best.label, ""), "prob": round(adv.best.prob, 4), "ev": round(adv.best.ev, 4), "confidence": round(TeamModelEngine.confidence(adv), 1), "level": adv.best.level, "dirty": bool(state.get("dirty")), "model_time": state.get("trained_at", "")}
            out.append(item)
            with self.db.conn() as db:
                db.execute("INSERT INTO sports_recommend_history(created_at,mode,issue,match_no,home_team,away_team,pick,prob,ev,confidence,model_version,train_time,raw_json) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)", (now_str(), mode, "", no, item["home"], item["away"], item["pick"], item["prob"], item["ev"], item["confidence"], state.get("model_version", ""), state.get("trained_at", ""), json.dumps(item, ensure_ascii=False)))
        out.sort(key=lambda x: (x["level"] == "推荐", x["ev"], x["confidence"]), reverse=True)
        return out
    def generate_sfc14(self, recs: list[dict]) -> str:
        top = sorted(recs, key=lambda x: x.get("match_no", ""))[:14]
        return "".join(x.get("code310") or "-" for x in top) if len(top) == 14 else "胜负彩需要14场，当前%d场" % len(top)
    def generate_ren9(self, recs: list[dict]) -> str:
        top = sorted(recs, key=lambda x: x.get("confidence", 0), reverse=True)[:9]
        return "\n".join("%s %s vs %s：%s(%s)" % (x["match_no"], x["home"], x["away"], x["pick"], x["code310"]) for x in top)
    def generate_jinqiucai(self, recs: list[dict]) -> str:
        # 框架版：后续用 Poisson 输出每队进球 0/1/2/3+
        top = recs[:4]
        return "\n".join("%s %s vs %s：进球数参考 Poisson" % (x["match_no"], x["home"], x["away"]) for x in top)

