class WorkerThread(QThread):
    progress = Signal(str)
    done = Signal(dict)
    def __init__(self, job: str, payload: dict):
        super().__init__()
        self.job = job
        self.payload = payload
    def run(self):
        try:
            if self.job == "lottery_train":
                res = LotteryTrainCenter(DB).train_game(self.payload["game"], progress=lambda s: self.progress.emit(s))
            elif self.job == "lottery_train_all":
                res = {"ok": True, "results": LotteryTrainCenter(DB).train_all_games(progress=lambda s: self.progress.emit(s))}
            elif self.job == "sports_future":
                res = SportsUpdateCenter(DB).update_future_matches(self.payload.get("token", ""), self.payload.get("days", 3), self.payload.get("mode", "jingcai"))
            elif self.job == "sports_history":
                res = SportsUpdateCenter(DB).update_history_results(self.payload.get("token", ""), self.payload.get("days", 365), self.payload.get("mode", "jingcai"))
            elif self.job == "sports_train":
                res = SportsTrainCenter(DB).train_sports_model(self.payload.get("mode", "jingcai"), progress=lambda s: self.progress.emit(s))
            else:
                res = {"ok": False, "message": "未知任务"}
            self.done.emit(res)
        except Exception as e:
            self.done.emit({"ok": False, "message": str(e), "trace": traceback.format_exc()})

