if QApplication is not None and 'V218MainWindow' in globals():
    _old_v218_build_ui = V218MainWindow._build_ui

    def _phase2_build_ui(self):
        _old_v218_build_ui(self)
        try:
            tabs = self.centralWidget().findChild(QTabWidget)
            if tabs is None:
                return

            # 开奖更新页
            upd = QWidget(); ulay = QVBoxLayout(upd)
            urow = QHBoxLayout()
            self.update_game_cb = QComboBox(); self.update_game_cb.addItems(LOTTERY_GAMES); urow.addWidget(QLabel("彩种")); urow.addWidget(self.update_game_cb)
            b1 = QPushButton("🔄 更新当前彩种开奖"); b1.clicked.connect(self.phase2_update_lottery); urow.addWidget(b1)
            b2 = QPushButton("🔄 更新全部开奖"); b2.clicked.connect(self.phase2_update_all_lottery); urow.addWidget(b2)
            ulay.addLayout(urow)
            self.update_log = QTextEdit(); self.update_log.setReadOnly(True); ulay.addWidget(self.update_log, 1)
            tabs.addTab(upd, "🔄 开奖更新")

            # 在线识别/验票页
            rec = QWidget(); rlay = QVBoxLayout(rec)
            f = QFormLayout()
            self.ocr_url_edit = QLineEdit(str(CONFIG.get("ocr_api_url", ""))); f.addRow("在线OCR接口", self.ocr_url_edit)
            self.ocr_key_edit = QLineEdit(str(CONFIG.get("ocr_api_key", ""))); self.ocr_key_edit.setEchoMode(QLineEdit.Password); f.addRow("OCR Key", self.ocr_key_edit)
            self.qr_url_edit = QLineEdit(str(CONFIG.get("qr_api_url", ""))); f.addRow("在线二维码接口", self.qr_url_edit)
            self.verify_url_edit = QLineEdit(str(CONFIG.get("ticket_verify_api_url", ""))); f.addRow("在线验票接口", self.verify_url_edit)
            rlay.addLayout(f)
            rr = QHBoxLayout()
            self.ticket_game_cb = QComboBox(); self.ticket_game_cb.addItems(["自动识别"] + LOTTERY_GAMES); rr.addWidget(self.ticket_game_cb)
            choose = QPushButton("🖼 选择图片"); choose.clicked.connect(self.phase2_choose_image); rr.addWidget(choose)
            ocrb = QPushButton("🔎 在线OCR识别"); ocrb.clicked.connect(self.phase2_ocr_image); rr.addWidget(ocrb)
            qrb = QPushButton("🎫 扫码验票"); qrb.clicked.connect(self.phase2_qr_verify); rr.addWidget(qrb)
            save = QPushButton("保存接口设置"); save.clicked.connect(self.phase2_save_recognition_config); rr.addWidget(save)
            rlay.addLayout(rr)
            self.ticket_image_path = QLineEdit(); self.ticket_image_path.setPlaceholderText("图片路径"); rlay.addWidget(self.ticket_image_path)
            self.recognition_result = QTextEdit(); self.recognition_result.setReadOnly(True); rlay.addWidget(self.recognition_result, 1)
            tabs.addTab(rec, "🎫 在线识别验票")
        except Exception as e:
            log_error("Phase2 UI安装失败: %s" % e)

    def _phase2_run(self, job, payload, target_box=None):
        if getattr(self, "phase2_worker", None) and self.phase2_worker.isRunning():
            QMessageBox.information(self, "任务进行中", "请等待当前任务完成")
            return
        self.phase2_worker = Phase2WorkerThread(job, payload)
        self.phase2_worker.progress.connect(lambda s: (target_box or self.log_box).append("[%s] %s" % (now_str(), s)))
        def done(res):
            txt = json.dumps(res, ensure_ascii=False, indent=2)
            (target_box or self.log_box).append(txt)
            try: self.refresh_status()
            except Exception: pass
        self.phase2_worker.done.connect(done)
        self.phase2_worker.start()

    def phase2_update_lottery(self):
        self.phase2_run("lottery_update", {"game": self.update_game_cb.currentText()}, self.update_log)

    def phase2_update_all_lottery(self):
        self.phase2_run("lottery_update_all", {}, self.update_log)

    def phase2_save_recognition_config(self):
        CONFIG.set("ocr_api_url", self.ocr_url_edit.text().strip())
        CONFIG.set("ocr_api_key", self.ocr_key_edit.text().strip())
        CONFIG.set("qr_api_url", self.qr_url_edit.text().strip())
        CONFIG.set("ticket_verify_api_url", self.verify_url_edit.text().strip())
        QMessageBox.information(self, "设置", "在线OCR/二维码/验票接口已保存")

    def phase2_choose_image(self):
        path, _ = QFileDialog.getOpenFileName(self, "选择彩票图片", "", "Images (*.png *.jpg *.jpeg *.webp *.bmp);;All Files (*)")
        if path:
            self.ticket_image_path.setText(path)

    def phase2_ocr_image(self):
        self.phase2_save_recognition_config()
        self.phase2_run("ocr_image", {"image_path": self.ticket_image_path.text().strip(), "game": self.ticket_game_cb.currentText()}, self.recognition_result)

    def phase2_qr_verify(self):
        self.phase2_save_recognition_config()
        self.phase2_run("qr_verify", {"image_path": self.ticket_image_path.text().strip(), "game": self.ticket_game_cb.currentText()}, self.recognition_result)

    V218MainWindow._build_ui = _phase2_build_ui
    V218MainWindow.phase2_run = _phase2_run
    V218MainWindow.phase2_update_lottery = phase2_update_lottery
    V218MainWindow.phase2_update_all_lottery = phase2_update_all_lottery
    V218MainWindow.phase2_save_recognition_config = phase2_save_recognition_config
    V218MainWindow.phase2_choose_image = phase2_choose_image
    V218MainWindow.phase2_ocr_image = phase2_ocr_image
    V218MainWindow.phase2_qr_verify = phase2_qr_verify




