# V218 PHASE3：训练状态管理 + 数据库体检 + 自动备份/恢复
# ============================================================

class Phase3MaintenanceCenter:
    """V218维护中心：只做检查、备份、恢复、状态汇总；不自动训练。"""
    def __init__(self, db: CaileDB = DB):
        self.db = db
        self.backup_root = DATA_DIR / "backup"

    def lottery_model_report(self) -> dict:
        rows = []
        summary = {"已训练": 0, "建议刷新": 0, "未训练": 0, "训练失败": 0, "其它": 0}
        for game in LOTTERY_GAMES:
            count = self.db.count_lottery_records(game)
            store = LotteryModelStore(game)
            st = store.load_state()
            status = str(st.get("status") or "未训练")
            if status not in summary:
                summary["其它"] += 1
            else:
                summary[status] += 1
            rows.append({
                "game": game,
                "history_count": count,
                "status": status,
                "trained_at": st.get("trained_at", ""),
                "new_rows_since_train": st.get("new_rows_since_train", 0),
                "dirty": bool(st.get("dirty", False)),
                "model_count": st.get("model_count", len(PREDICTION_MODELS)),
                "score_exists": LotteryModelStore(game).score_file.exists(),
                "weights_exists": LotteryModelStore(game).weights_file.exists(),
            })
        return {"ok": True, "summary": summary, "rows": rows}

    def sports_model_report(self) -> dict:
        st = SPORTS_STORE.load_state()
        score = load_json(SPORTS_STORE.score_file, {}) or {}
        exists = {
            "elo_ratings": SPORTS_STORE.elo_file.exists(),
            "team_history_cache": SPORTS_STORE.history_file.exists(),
            "sports_model_state": SPORTS_STORE.state_file.exists(),
            "sports_model_score": SPORTS_STORE.score_file.exists(),
            "last_train_info": SPORTS_STORE.train_file.exists(),
        }
        return {"ok": True, "state": st, "score": score, "files": exists}

    def sports_db_check(self) -> dict:
        with self.db.conn() as db:
            total = int(db.execute("SELECT COUNT(*) FROM sports_matches").fetchone()[0])
            finished = int(db.execute("SELECT COUNT(*) FROM sports_matches WHERE home_score IS NOT NULL AND away_score IS NOT NULL").fetchone()[0])
            no_score = total - finished
            missing_odds = int(db.execute("SELECT COUNT(*) FROM sports_matches WHERE odds_home IS NULL OR odds_draw IS NULL OR odds_away IS NULL").fetchone()[0])
            missing_team = int(db.execute("SELECT COUNT(*) FROM sports_matches WHERE TRIM(COALESCE(home_team,''))='' OR TRIM(COALESCE(away_team,''))='' ").fetchone()[0])
            modes = db.execute("SELECT mode, COUNT(*) FROM sports_matches GROUP BY mode ORDER BY mode").fetchall()
            duplicate_candidates = db.execute("""
                SELECT event_date, home_team, away_team, COUNT(*) c
                FROM sports_matches
                GROUP BY event_date, home_team, away_team
                HAVING c > 1
                LIMIT 30
            """).fetchall()
        return {
            "ok": True,
            "total": total,
            "finished": finished,
            "no_score": no_score,
            "missing_odds": missing_odds,
            "missing_team": missing_team,
            "duplicate_groups": len(duplicate_candidates),
            "modes": {str(k): int(v) for k, v in modes},
        }

    def lottery_db_check(self) -> dict:
        rows = []
        total = 0
        damaged = 0
        with self.db.conn() as db:
            for game in LOTTERY_GAMES:
                cnt = int(db.execute("SELECT COUNT(*) FROM history_records WHERE game=?", (game,)).fetchone()[0])
                dup = db.execute("""
                    SELECT issue, COUNT(*) c FROM history_records
                    WHERE game=? GROUP BY issue HAVING c>1 LIMIT 5
                """, (game,)).fetchall()
                bad = 0
                for (raw,) in db.execute("SELECT raw_json FROM history_records WHERE game=?", (game,)).fetchall():
                    try:
                        obj = json.loads(raw)
                        if not isinstance(obj, dict) or not CaileDB._issue(obj) or not CaileDB._numbers(obj):
                            bad += 1
                    except Exception:
                        bad += 1
                total += cnt
                damaged += bad
                rows.append({"game": game, "count": cnt, "duplicates": len(dup), "damaged": bad})
        return {"ok": True, "total": total, "damaged": damaged, "rows": rows}

    def backup_all(self) -> dict:
        stamp = datetime.now().strftime("%Y%m%d_%H%M%S")
        dest = self.backup_root / stamp
        dest.mkdir(parents=True, exist_ok=True)
        copied = []
        for p in [DB_FILE, CONFIG_FILE]:
            if Path(p).exists():
                shutil.copy2(str(p), str(dest / Path(p).name)); copied.append(str(Path(p).name))
        for folder in [MODELS_DIR, DATA_DIR / "cache"]:
            if folder.exists():
                target = dest / folder.name
                shutil.copytree(str(folder), str(target), dirs_exist_ok=True)
                copied.append(folder.name + "/")
        return {"ok": True, "backup_dir": str(dest), "copied": copied}

    def list_backups(self) -> dict:
        self.backup_root.mkdir(parents=True, exist_ok=True)
        items = []
        for p in sorted(self.backup_root.iterdir(), reverse=True):
            if p.is_dir():
                items.append({"name": p.name, "path": str(p), "mtime": datetime.fromtimestamp(p.stat().st_mtime).strftime("%Y-%m-%d %H:%M:%S")})
        return {"ok": True, "backups": items[:30]}

    def write_reports_to_files(self) -> dict:
        report_dir = DATA_DIR / "reports"
        report_dir.mkdir(parents=True, exist_ok=True)
        stamp = datetime.now().strftime("%Y%m%d_%H%M%S")
        report = {
            "created_at": now_str(),
            "lottery_models": self.lottery_model_report(),
            "sports_model": self.sports_model_report(),
            "lottery_db": self.lottery_db_check(),
            "sports_db": self.sports_db_check(),
            "backups": self.list_backups(),
        }
        path = report_dir / ("caile_v218_health_report_%s.json" % stamp)
        atomic_write_json(path, report)
        return {"ok": True, "report_file": str(path), "report": report}


class Phase3WorkerThread(QThread):
    progress = Signal(str)
    done = Signal(dict)
    def __init__(self, job: str, payload: dict = None):
        super().__init__()
        self.job = job
        self.payload = payload or {}
    def run(self):
        try:
            m = Phase3MaintenanceCenter(DB)
            self.progress.emit("开始执行：%s" % self.job)
            if self.job == "lottery_model_report":
                res = m.lottery_model_report()
            elif self.job == "sports_model_report":
                res = m.sports_model_report()
            elif self.job == "sports_db_check":
                res = m.sports_db_check()
            elif self.job == "lottery_db_check":
                res = m.lottery_db_check()
            elif self.job == "backup_all":
                res = m.backup_all()
            elif self.job == "list_backups":
                res = m.list_backups()
            elif self.job == "write_health_report":
                res = m.write_reports_to_files()
            else:
                res = {"ok": False, "message": "未知Phase3任务"}
            self.done.emit(res)
        except Exception as e:
            self.done.emit({"ok": False, "message": str(e), "trace": traceback.format_exc()})


if QApplication is not None:
    def _phase3_install_ui():
        old_build = V218MainWindow._build_ui
        def _build_ui_phase3(self):
            old_build(self)
            try:
                tabs = self.findChild(QTabWidget)
                if not tabs:
                    return
                page = QWidget(); lay = QVBoxLayout(page)
                top = QLabel("V218 维护中心：状态检查、训练报告、数据库体检、备份。不会自动训练模型。")
                top.setWordWrap(True); lay.addWidget(top)
                row = QHBoxLayout()
                for text, job in [
                    ("🎲 数字彩模型状态", "lottery_model_report"),
                    ("⚽ 足彩模型体检", "sports_model_report"),
                    ("🔍 数字彩数据库", "lottery_db_check"),
                    ("🔍 足彩数据库", "sports_db_check"),
                    ("💾 立即备份", "backup_all"),
                    ("📂 备份列表", "list_backups"),
                    ("🧾 生成体检报告", "write_health_report"),
                ]:
                    b = QPushButton(text); b.clicked.connect(lambda checked=False, j=job: self.phase3_run(j)); row.addWidget(b)
                lay.addLayout(row)
                self.phase3_result = QTextEdit(); self.phase3_result.setReadOnly(True); lay.addWidget(self.phase3_result, 1)
                tabs.addTab(page, "🛠 维护体检")
            except Exception as e:
                log_error("Phase3 UI安装失败：%s" % e)
        def phase3_run(self, job: str):
            if getattr(self, "phase3_worker", None) and self.phase3_worker.isRunning():
                QMessageBox.information(self, "任务进行中", "请等待当前维护任务完成")
                return
            self.phase3_worker = Phase3WorkerThread(job, {})
            target = getattr(self, "phase3_result", None) or getattr(self, "log_box", None)
            self.phase3_worker.progress.connect(lambda s: target.append("[%s] %s" % (now_str(), s)) if target else None)
            def done(res):
                txt = json.dumps(res, ensure_ascii=False, indent=2)
                if target: target.append(txt)
                try: self.refresh_status()
                except Exception: pass
            self.phase3_worker.done.connect(done)
            self.phase3_worker.start()
        V218MainWindow._build_ui = _build_ui_phase3
        V218MainWindow.phase3_run = phase3_run
    try:
        _phase3_install_ui()
    except Exception:
        log_error(traceback.format_exc())



