# V218 PHASE4：预测命中统计 + 足彩生成中心 + 权重管理框架
# 说明：只读取已保存数据/模型，不自动训练。
# ============================================================

class Phase4StatsCenter:
    """预测命中统计中心：数字彩、足彩统一统计；不触发训练。"""

    def __init__(self, db: CaileDB = DB):
        self.db = db
        self.stats_dir = DATA_DIR / "stats"
        self.stats_dir.mkdir(parents=True, exist_ok=True)

    def _ensure_phase4_tables(self):
        with self.db.conn() as db:
            db.execute("""
                CREATE TABLE IF NOT EXISTS lottery_prediction_result (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    created_at TEXT,
                    game TEXT,
                    target_issue TEXT,
                    prediction_text TEXT,
                    draw_text TEXT,
                    main_hit INTEGER,
                    sub_hit INTEGER,
                    prize_level TEXT,
                    prize_amount REAL,
                    raw_json TEXT
                )
            """)
            db.execute("""
                CREATE TABLE IF NOT EXISTS sports_prediction_result (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    created_at TEXT,
                    mode TEXT,
                    issue TEXT,
                    match_no TEXT,
                    home TEXT,
                    away TEXT,
                    pick TEXT,
                    code310 TEXT,
                    actual_code310 TEXT,
                    hit INTEGER,
                    prob REAL,
                    ev REAL,
                    confidence REAL,
                    model_version TEXT,
                    train_time TEXT,
                    raw_json TEXT
                )
            """)
            db.execute("""
                CREATE TABLE IF NOT EXISTS phase4_update_log (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    created_at TEXT,
                    module TEXT,
                    action TEXT,
                    message TEXT,
                    raw_json TEXT
                )
            """)

    @staticmethod
    def _parse_lottery_nums(text: str) -> tuple[list[int], list[int]]:
        text = str(text or "").replace("＋", "+")
        if "+" in text:
            a, b = text.split("+", 1)
            return [int(x) for x in re.findall(r"\d+", a)], [int(x) for x in re.findall(r"\d+", b)]
        return [int(x) for x in re.findall(r"\d+", text)], []

    def evaluate_lottery_predictions(self, game: str, limit: int = 100) -> dict:
        """用已保存 prediction_log 和历史开奖做命中统计，不重新预测。"""
        self._ensure_phase4_tables()
        store = LotteryModelStore(game)
        log_rows = load_json(store.prediction_log_file, [])
        if not isinstance(log_rows, list):
            log_rows = []
        history = self.db.load_lottery_records(game, limit=5000)
        draw_by_issue = {str(x.get("issue", "")): str(x.get("numbers", "")) for x in history}
        checked = []
        for row in log_rows[-limit:]:
            issue = str(row.get("target_issue") or row.get("issue") or "")
            pred_text = str(row.get("numbers") or row.get("numbers_text") or "")
            draw_text = draw_by_issue.get(issue, "")
            if not issue or not pred_text or not draw_text:
                continue
            pm, ps = self._parse_lottery_nums(pred_text)
            dm, ds = self._parse_lottery_nums(draw_text)
            main_hit = len(set(pm) & set(dm))
            sub_hit = len(set(ps) & set(ds)) if ps or ds else 0
            item = {
                "game": game,
                "issue": issue,
                "prediction": pred_text,
                "draw": draw_text,
                "main_hit": main_hit,
                "sub_hit": sub_hit,
            }
            checked.append(item)
        avg_main = sum(x["main_hit"] for x in checked) / len(checked) if checked else 0.0
        avg_sub = sum(x["sub_hit"] for x in checked) / len(checked) if checked else 0.0
        best_main = max([x["main_hit"] for x in checked], default=0)
        report = {
            "game": game,
            "checked": len(checked),
            "avg_main_hit": round(avg_main, 3),
            "avg_sub_hit": round(avg_sub, 3),
            "best_main_hit": best_main,
            "items": checked[-30:],
            "created_at": now_str(),
        }
        atomic_write_json(self.stats_dir / ("lottery_hit_%s.json" % safe_name(game)), report)
        return report

    def evaluate_all_lottery_predictions(self) -> dict:
        return {g: self.evaluate_lottery_predictions(g, 100) for g in LOTTERY_GAMES}

    def sports_prediction_summary(self, mode: str = "jingcai", recent: int = 100) -> dict:
        """统计已落库的足彩推荐命中。实际赛果字段不足时只返回记录数。"""
        self._ensure_phase4_tables()
        with self.db.conn() as db:
            rows = db.execute("""
                SELECT hit, pick, code310, actual_code310, confidence, ev
                FROM sports_prediction_result
                WHERE mode=?
                ORDER BY id DESC
                LIMIT ?
            """, (mode, recent)).fetchall()
        total = len(rows)
        judged = [r for r in rows if r[0] is not None]
        hit_count = sum(1 for r in judged if int(r[0] or 0) == 1)
        return {
            "mode": mode,
            "records": total,
            "judged": len(judged),
            "hit": hit_count,
            "hit_rate": round(hit_count / len(judged), 4) if judged else None,
            "recent": recent,
            "created_at": now_str(),
        }

    def model_weight_report(self) -> dict:
        """读取现有权重，不增加/删除模型，只做展示。"""
        lottery = {}
        for g in LOTTERY_GAMES:
            lottery[g] = load_json(LotteryModelStore(g).weights_file, {})
        sports_weights = load_json(SPORTS_STORE.model_dir / "sports_model_weights.json", {
            "market": 0.35, "auto_model": 0.45, "elo": 0.10, "poisson": 0.10
        })
        return {"lottery": lottery, "sports": sports_weights, "created_at": now_str()}

    def write_phase4_report(self) -> dict:
        report_dir = DATA_DIR / "reports"
        report_dir.mkdir(parents=True, exist_ok=True)
        report = {
            "created_at": now_str(),
            "lottery_hit": self.evaluate_all_lottery_predictions(),
            "sports_jingcai": self.sports_prediction_summary("jingcai"),
            "sports_sfc14": self.sports_prediction_summary("sfc14"),
            "sports_ren9": self.sports_prediction_summary("ren9"),
            "sports_jinqiucai": self.sports_prediction_summary("jinqiucai"),
            "weights": self.model_weight_report(),
        }
        path = report_dir / ("caile_v218_phase4_stats_%s.json" % datetime.now().strftime("%Y%m%d_%H%M%S"))
        atomic_write_json(path, report)
        return {"ok": True, "report_file": str(path), "report": report}


class Phase4WorkerThread(QThread):
    progress = Signal(str)
    done = Signal(dict)
    def __init__(self, job: str, payload: dict = None):
        super().__init__()
        self.job = job
        self.payload = payload or {}
    def run(self):
        try:
            s = Phase4StatsCenter(DB)
            self.progress.emit("开始执行：%s" % self.job)
            if self.job == "lottery_hit_one":
                res = s.evaluate_lottery_predictions(self.payload.get("game", LOTTERY_GAMES[0]))
            elif self.job == "lottery_hit_all":
                res = s.evaluate_all_lottery_predictions()
            elif self.job == "sports_summary":
                res = s.sports_prediction_summary(self.payload.get("mode", "jingcai"))
            elif self.job == "weight_report":
                res = s.model_weight_report()
            elif self.job == "phase4_report":
                res = s.write_phase4_report()
            else:
                res = {"ok": False, "message": "未知Phase4任务"}
            self.done.emit(res)
        except Exception as e:
            self.done.emit({"ok": False, "message": str(e), "trace": traceback.format_exc()})


