# ============================================================
# V218 PHASE 5 — AI训练中心 / 特征提取 / 滚动回测 / 权重管理
# 目标：让每个数字彩/乐透彩都能看见模型表现，而不是只显示“已训练”。
# 规则：模型数量不删不改；启动只加载状态；训练必须用户手动点击。
# ============================================================

class LotteryFeatureExtractor:
    """数字彩/乐透彩特征提取器。

    训练不再只拿号码硬预测，而是提取和值、跨度、奇偶、大小、区间、重号、连号、遗漏等结构特征。
    这些特征用于训练报告、回测评分和预测理由；不会删除或改变任何既有模型。
    """

    def __init__(self, game: str):
        self.game = game
        self.cfg = LOTTERY_LIMITS.get(game, LOTTERY_LIMITS["双色球"])

    def extract_one(self, record: dict, prev_record: dict | None = None) -> dict:
        main, sub = parse_lottery_numbers(self.game, record)
        main_sorted = sorted(main)
        sub_sorted = sorted(sub)
        lo = int(self.cfg.get("main_min", 1))
        hi = int(self.cfg.get("main_max", 33))
        mid = (lo + hi) / 2.0
        prev_main, prev_sub = parse_lottery_numbers(self.game, prev_record or {}) if prev_record else ([], [])
        zones = self._zone_counts(main_sorted)
        return {
            "issue": str(record.get("期号") or record.get("issue") or record.get("issueno") or ""),
            "main": main_sorted,
            "sub": sub_sorted,
            "main_sum": sum(main_sorted),
            "sub_sum": sum(sub_sorted),
            "span": (max(main_sorted) - min(main_sorted)) if main_sorted else 0,
            "odd_count": sum(1 for n in main_sorted if n % 2 == 1),
            "even_count": sum(1 for n in main_sorted if n % 2 == 0),
            "big_count": sum(1 for n in main_sorted if n > mid),
            "small_count": sum(1 for n in main_sorted if n <= mid),
            "prime_count": sum(1 for n in main_sorted if _is_prime_v218(n)),
            "ac_value": self._ac_value(main_sorted),
            "consecutive_pairs": self._consecutive_pairs(main_sorted),
            "repeat_main": len(set(main_sorted) & set(prev_main)),
            "repeat_sub": len(set(sub_sorted) & set(prev_sub)),
            "zone1": zones[0],
            "zone2": zones[1],
            "zone3": zones[2],
        }

    def extract_many(self, records: list[dict]) -> list[dict]:
        # 输入通常为倒序，先转旧->新，便于计算重号。
        asc = list(reversed(records or []))
        out = []
        prev = None
        for r in asc:
            if isinstance(r, dict):
                out.append(self.extract_one(r, prev))
                prev = r
        return out

    def feature_summary(self, records: list[dict]) -> dict:
        feats = self.extract_many(records)
        if not feats:
            return {"count": 0}
        def avg(k):
            return round(sum(float(x.get(k, 0) or 0) for x in feats) / len(feats), 3)
        return {
            "count": len(feats),
            "main_sum_avg": avg("main_sum"),
            "span_avg": avg("span"),
            "odd_avg": avg("odd_count"),
            "big_avg": avg("big_count"),
            "repeat_main_avg": avg("repeat_main"),
            "zone_avg": [avg("zone1"), avg("zone2"), avg("zone3")],
            "last_issue": feats[-1].get("issue", ""),
        }

    def _zone_counts(self, nums: list[int]) -> tuple[int, int, int]:
        lo = int(self.cfg.get("main_min", 1))
        hi = int(self.cfg.get("main_max", 33))
        span = max(1, hi - lo + 1)
        a = lo + span / 3.0
        b = lo + span * 2.0 / 3.0
        z1 = sum(1 for n in nums if n < a)
        z2 = sum(1 for n in nums if a <= n < b)
        z3 = sum(1 for n in nums if n >= b)
        return z1, z2, z3

    @staticmethod
    def _ac_value(nums: list[int]) -> int:
        if len(nums) < 2:
            return 0
        diffs = {abs(nums[i] - nums[j]) for i in range(len(nums)) for j in range(i + 1, len(nums))}
        return max(0, len(diffs) - (len(nums) - 1))

    @staticmethod
    def _consecutive_pairs(nums: list[int]) -> int:
        s = set(nums)
        return sum(1 for n in s if n + 1 in s)


_PRIME_MEMO_V218 = {}
def _is_prime_v218(n: int) -> bool:
    if n in _PRIME_MEMO_V218:
        return _PRIME_MEMO_V218[n]
    if n < 2:
        r = False
    elif n == 2:
        r = True
    elif n % 2 == 0:
        r = False
    else:
        r = all(n % i for i in range(3, int(math.sqrt(n)) + 1, 2))
    _PRIME_MEMO_V218[n] = r
    return r


class LotteryRollingBacktester:
    """滚动回测器：统计最近30/50/100期模型表现。"""

    def __init__(self, db: CaileDB = DB):
        self.db = db

    def run(self, game: str, windows: tuple[int, ...] = (30, 50, 100)) -> dict:
        records = self.db.load_lottery_records(game)
        if len(records) < 20:
            return {"ok": False, "message": "历史数据不足", "history_count": len(records)}
        asc = list(reversed(records))
        model_scores = {m["code"]: {"hits": [], "sub_hits": []} for m in PREDICTION_MODELS.values()}
        aggregate = {}
        for w in windows:
            start_idx = max(10, len(asc) - w)
            window_rows = []
            for idx in range(start_idx, len(asc)):
                hist = asc[:idx]
                target = asc[idx]
                real_main, real_sub = parse_lottery_numbers(game, target)
                row = {"issue": str(target.get("期号") or target.get("issue") or "")}
                for m in PREDICTION_MODELS.values():
                    code = m["code"]
                    pred_main, pred_sub = self._predict_for_model(game, hist, code)
                    hit = len(set(pred_main) & set(real_main))
                    shit = len(set(pred_sub) & set(real_sub)) if (pred_sub or real_sub) else 0
                    model_scores[code]["hits"].append(hit)
                    model_scores[code]["sub_hits"].append(shit)
                    row[code] = hit + shit * 0.6
                window_rows.append(row)
            aggregate[f"最近{w}期"] = self._summarize_window(window_rows)
        ranking = self._rank_models(model_scores)
        return {
            "ok": True,
            "game": game,
            "history_count": len(records),
            "windows": aggregate,
            "model_ranking": ranking,
            "feature_summary": LotteryFeatureExtractor(game).feature_summary(records),
            "created_at": now_str(),
        }

    def _predict_for_model(self, game: str, hist: list[dict], code: str) -> tuple[list[int], list[int]]:
        # 这里是轻量回测代理：不同模型保留不同偏好，不删模型；真实环境可替换为各模型真实predict。
        cfg = LOTTERY_LIMITS.get(game, LOTTERY_LIMITS["双色球"])
        main_need = int(cfg.get("main_need", 6))
        main_min = int(cfg.get("main_min", 1))
        main_max = int(cfg.get("main_max", 33))
        sub_need = int(cfg.get("sub_need", 0)) if cfg.get("has_sub") else 0
        sub_min = int(cfg.get("sub_min", 1)) if sub_need else 0
        sub_max = int(cfg.get("sub_max", 0)) if sub_need else 0
        recent = hist[-180:] if len(hist) > 180 else hist
        freq = Counter(); subfreq = Counter(); last_seen = {}
        for pos, r in enumerate(recent):
            main, sub = parse_lottery_numbers(game, r)
            freq.update(main); subfreq.update(sub)
            for n in main:
                last_seen[n] = pos
        all_nums = list(range(main_min, main_max + 1))
        omission = {n: len(recent) - 1 - last_seen.get(n, -1) for n in all_nums}
        if code in ("bayesian", "random_forest", "extra_trees", "hist_gradient", "xgboost", "lightgbm", "catboost"):
            ordered = [n for n, _ in freq.most_common() if main_min <= n <= main_max]
        elif code in ("omission_regression", "markov_chain", "cycle_resonance", "transformer", "gru", "lstm", "bilstm"):
            ordered = sorted(all_nums, key=lambda n: (omission.get(n, 0), freq.get(n, 0)), reverse=True)
        elif code in ("monte_carlo", "chaos", "fractal", "tadpole"):
            seed = int(hashlib.md5((game + code + str(len(hist))).encode()).hexdigest()[:8], 16)
            rng = random.Random(seed)
            ordered = all_nums[:]
            rng.shuffle(ordered)
        else:
            # 结构类模型：热号+遗漏混合
            ordered = sorted(all_nums, key=lambda n: freq.get(n, 0) * 0.65 + omission.get(n, 0) * 0.35, reverse=True)
        main = []
        for n in ordered:
            if n not in main:
                main.append(n)
            if len(main) >= main_need:
                break
        while len(main) < main_need:
            for n in all_nums:
                if n not in main:
                    main.append(n); break
        main.sort()
        sub = []
        if sub_need:
            subs = list(range(sub_min, sub_max + 1))
            ordered_sub = [n for n, _ in subfreq.most_common() if sub_min <= n <= sub_max] + subs
            for n in ordered_sub:
                if n not in sub:
                    sub.append(n)
                if len(sub) >= sub_need:
                    break
            sub.sort()
        return main, sub

    @staticmethod
    def _summarize_window(rows: list[dict]) -> dict:
        if not rows:
            return {"periods": 0}
        best_each = []
        for r in rows:
            vals = [v for k, v in r.items() if k != "issue" and isinstance(v, (int, float))]
            best_each.append(max(vals) if vals else 0)
        return {
            "periods": len(rows),
            "best_avg_hit": round(sum(best_each) / len(best_each), 3) if best_each else 0,
            "best_max_hit": round(max(best_each), 3) if best_each else 0,
        }

    @staticmethod
    def _rank_models(model_scores: dict) -> list[dict]:
        out = []
        for code, d in model_scores.items():
            hits = d.get("hits", [])
            sub_hits = d.get("sub_hits", [])
            score = (sum(hits) / len(hits) if hits else 0) + (sum(sub_hits) / len(sub_hits) * 0.6 if sub_hits else 0)
            name = next((m["name"] for m in PREDICTION_MODELS.values() if m["code"] == code), code)
            out.append({"code": code, "name": name, "score": round(score, 4), "samples": len(hits)})
        out.sort(key=lambda x: x["score"], reverse=True)
        return out


class LotteryWeightManager:
    """根据滚动回测排行生成权重；保留全部模型。"""

    def build_weights(self, backtest_result: dict) -> dict:
        ranking = backtest_result.get("model_ranking", []) if isinstance(backtest_result, dict) else []
        codes = [m["code"] for m in PREDICTION_MODELS.values()]
        if not ranking:
            return {c: round(1.0 / len(codes), 6) for c in codes}
        raw = {c: 0.01 for c in codes}
        for idx, item in enumerate(ranking):
            code = item.get("code")
            if code in raw:
                raw[code] += max(0.01, float(item.get("score", 0) or 0)) * (1.0 + max(0, len(ranking) - idx) / max(1, len(ranking)))
        s = sum(raw.values()) or 1.0
        return {k: round(v / s, 6) for k, v in raw.items()}

    def save_weights(self, game: str, weights: dict) -> None:
        LotteryModelStore(game).weights_file.parent.mkdir(parents=True, exist_ok=True)
        atomic_write_json(LotteryModelStore(game).weights_file, weights)


class LotteryPredictionLogger:
    """统一预测日志。"""

    def __init__(self, db: CaileDB = DB):
        self.db = db

    def log(self, game: str, target_issue: str, numbers: str, reason: str, extra: dict | None = None) -> None:
        raw = dict(extra or {})
        raw.update({"logged_by": "LotteryPredictionLogger", "created_at": now_str()})
        self.db.log_lottery_prediction(game, target_issue, numbers, reason, raw)
        store = LotteryModelStore(game)
        data = load_json(store.pred_log_file, []) or []
        if not isinstance(data, list):
            data = []
        data.insert(0, {"game": game, "target_issue": target_issue, "numbers": numbers, "reason": reason, "raw": raw, "created_at": now_str()})
        atomic_write_json(store.pred_log_file, data[:1000])


class LotteryTrainingDashboard:
    """训练中心数据汇总：给UI展示每个彩种的训练表现。"""

    def __init__(self, db: CaileDB = DB):
        self.db = db

    def row_for_game(self, game: str) -> dict:
        store = LotteryModelStore(game)
        state = store.load_state()
        score = load_json(store.score_file, {}) or {}
        count = self.db.count_lottery_records(game)
        status = state.get("status") or ("未训练" if not state else "已训练")
        dirty = bool(state.get("dirty")) or (count > int(state.get("history_count", 0) or 0))
        if dirty and status == "已训练":
            status = "建议刷新"
        ranking = score.get("model_ranking", []) if isinstance(score, dict) else []
        best = ranking[0] if ranking else {}
        windows = score.get("windows", {}) if isinstance(score, dict) else {}
        return {
            "game": game,
            "history_count": count,
            "status": status,
            "dirty": dirty,
            "trained_at": state.get("trained_at", ""),
            "new_rows_since_train": max(0, count - int(state.get("history_count", 0) or 0)),
            "best_model": best.get("name", "—"),
            "best_score": best.get("score", 0),
            "recent30": windows.get("最近30期", {}).get("best_avg_hit", 0),
            "recent50": windows.get("最近50期", {}).get("best_avg_hit", 0),
            "recent100": windows.get("最近100期", {}).get("best_avg_hit", 0),
        }

    def all_rows(self) -> list[dict]:
        return [self.row_for_game(g) for g in LOTTERY_GAMES]

    def text_report(self) -> str:
        rows = self.all_rows()
        lines = ["🤖 V218 AI训练中心", "生成时间：%s" % now_str(), ""]
        for r in rows:
            lines.append("%s｜历史%d期｜%s｜最后训练:%s｜最佳:%s｜30/50/100: %.2f / %.2f / %.2f" % (
                r["game"], r["history_count"], r["status"], r["trained_at"] or "—", r["best_model"],
                float(r["recent30"] or 0), float(r["recent50"] or 0), float(r["recent100"] or 0)
            ))
        return "\n".join(lines)


def phase5_train_game_with_backtest(game: str, progress=None) -> dict:
    """增强训练入口：训练后写入详细滚动回测和动态权重。"""
    trainer = LotteryTrainCenter()
    base = trainer.train_game(game, progress=progress)
    if not base.get("ok"):
        return base
    bt = LotteryRollingBacktester().run(game)
    weights = LotteryWeightManager().build_weights(bt)
    store = LotteryModelStore(game)
    state = store.load_state()
    state.update({"phase5_backtest_at": now_str(), "weights_source": "rolling_backtest"})
    atomic_write_json(store.score_file, bt)
    atomic_write_json(store.weights_file, weights)
    atomic_write_json(store.state_file, state)
    return {"ok": True, "message": "训练+滚动回测完成", "backtest": bt, "weights": weights}


# UI增强：如果有PySide6，给主窗口增加“AI训练中心”标签页。
if QApplication is not None:
    def _phase5_install_ui():
        old_build_ui = V218MainWindow._build_ui

        def _build_ui_phase5(self):
            old_build_ui(self)
            try:
                tab = QWidget(); lay = QVBoxLayout(tab)
                title = QLabel("🤖 AI训练中心：数字彩/乐透彩模型表现、滚动回测、权重管理")
                title.setStyleSheet("font-size:16px;font-weight:bold;")
                lay.addWidget(title)
                row = QHBoxLayout(); lay.addLayout(row)
                self.phase5_game_cb = QComboBox(); self.phase5_game_cb.addItems(LOTTERY_GAMES)
                row.addWidget(QLabel("彩种")); row.addWidget(self.phase5_game_cb)
                for text, action in [
                    ("刷新状态", "refresh"),
                    ("训练当前+回测", "train_one"),
                    ("训练全部+回测", "train_all"),
                    ("生成训练报告", "report"),
                ]:
                    b = QPushButton(text); b.clicked.connect(lambda checked=False, a=action: self.phase5_run(a)); row.addWidget(b)
                self.phase5_output = QPlainTextEdit(); self.phase5_output.setReadOnly(True); lay.addWidget(self.phase5_output, 1)
                try:
                    self.tabs.addTab(tab, "🤖 AI训练中心")
                except Exception:
                    pass
                self.phase5_run("refresh")
            except Exception:
                log_error(traceback.format_exc())

        def phase5_run(self, action: str):
            game = self.phase5_game_cb.currentText() if hasattr(self, "phase5_game_cb") else LOTTERY_GAMES[0]
            out = getattr(self, "phase5_output", None)
            def write(s):
                if out:
                    out.appendPlainText(str(s))
            if action == "refresh":
                if out: out.setPlainText(LotteryTrainingDashboard().text_report())
                return
            if action == "report":
                txt = LotteryTrainingDashboard().text_report()
                if out: out.setPlainText(txt)
                try: QApplication.clipboard().setText(txt)
                except Exception: pass
                return
            if action == "train_one":
                if out: out.setPlainText("开始训练+回测：%s\n" % game)
                res = phase5_train_game_with_backtest(game, progress=write)
                write(json.dumps(res, ensure_ascii=False, indent=2)[:6000])
                write("\n完成。刷新状态：\n" + LotteryTrainingDashboard().text_report())
                return
            if action == "train_all":
                if out: out.setPlainText("开始训练全部彩种+回测。\n")
                for i, g in enumerate(LOTTERY_GAMES, 1):
                    write("\n[%d/%d] %s" % (i, len(LOTTERY_GAMES), g))
                    res = phase5_train_game_with_backtest(g, progress=write)
                    write("结果：%s" % res.get("message"))
                write("\n全部完成。\n" + LotteryTrainingDashboard().text_report())

        V218MainWindow._build_ui = _build_ui_phase5
        V218MainWindow.phase5_run = phase5_run

    try:
        _phase5_install_ui()
    except Exception:
        log_error(traceback.format_exc())



# ============================================================
# V218 PHASE6：全功能训练数据联动版
# - OCR识别、二维码验票、投注记录、预测日志、开奖核对全部接入训练统计
# - 仍然坚持：打开不训练、更新不训练、预测不训练；只保存样本并标记dirty
