PHASE6_VERSION = "phase6_full_training_link"

class Phase6Schema:
    """Phase6 增量表：不破坏旧库，只补训练样本和核对记录。"""

    @staticmethod
    def ensure(db_path: Path = DB_FILE) -> None:
        with sqlite3.connect(str(db_path)) as db:
            db.execute("""
                CREATE TABLE IF NOT EXISTS training_samples (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    source_type TEXT,
                    game TEXT,
                    issue TEXT,
                    numbers TEXT,
                    label_json TEXT,
                    confidence REAL,
                    used_for_training INTEGER DEFAULT 0,
                    raw_json TEXT,
                    created_at TEXT
                )
            """)
            db.execute("CREATE INDEX IF NOT EXISTS idx_training_samples_game_issue ON training_samples(game, issue)")
            db.execute("CREATE INDEX IF NOT EXISTS idx_training_samples_source ON training_samples(source_type)")

            db.execute("""
                CREATE TABLE IF NOT EXISTS ticket_check_records (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    game TEXT,
                    issue TEXT,
                    ticket_no TEXT,
                    numbers TEXT,
                    draw_numbers TEXT,
                    hit_json TEXT,
                    prize_level TEXT,
                    prize_amount REAL,
                    qr_content TEXT,
                    ocr_text TEXT,
                    raw_json TEXT,
                    created_at TEXT
                )
            """)
            db.execute("CREATE INDEX IF NOT EXISTS idx_ticket_check_game_issue ON ticket_check_records(game, issue)")

            db.execute("""
                CREATE TABLE IF NOT EXISTS betting_records_v218 (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    game TEXT,
                    issue TEXT,
                    numbers TEXT,
                    amount REAL,
                    bet_type TEXT,
                    source TEXT,
                    checked INTEGER DEFAULT 0,
                    result_json TEXT,
                    raw_json TEXT,
                    created_at TEXT
                )
            """)
            db.execute("CREATE INDEX IF NOT EXISTS idx_betting_v218_game_issue ON betting_records_v218(game, issue)")

            db.execute("""
                CREATE TABLE IF NOT EXISTS prediction_evaluations (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    game TEXT,
                    issue TEXT,
                    prediction_id INTEGER,
                    predicted_numbers TEXT,
                    draw_numbers TEXT,
                    main_hit INTEGER,
                    sub_hit INTEGER,
                    score REAL,
                    raw_json TEXT,
                    created_at TEXT
                )
            """)
            db.execute("CREATE INDEX IF NOT EXISTS idx_prediction_eval_game_issue ON prediction_evaluations(game, issue)")

            db.execute("""
                CREATE TABLE IF NOT EXISTS sports_prediction_evaluations (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    event_key TEXT,
                    mode TEXT,
                    match_no TEXT,
                    pick TEXT,
                    actual_result TEXT,
                    hit INTEGER,
                    ev REAL,
                    confidence REAL,
                    raw_json TEXT,
                    created_at TEXT
                )
            """)
            db.execute("CREATE INDEX IF NOT EXISTS idx_sports_pred_eval_mode ON sports_prediction_evaluations(mode)")

try:
    Phase6Schema.ensure()
except Exception:
    log_error(traceback.format_exc())


class TrainingDataLinkCenter:
    """所有功能产生的数据，统一沉淀为训练/评分样本。"""

    def __init__(self, db_path: Path = DB_FILE):
        self.db_path = db_path
        Phase6Schema.ensure(db_path)

    def conn(self):
        return sqlite3.connect(str(self.db_path))

    def save_sample(self, source_type: str, game: str, issue: str, numbers: str,
                    label: dict | None = None, confidence: float = 0.0, raw: dict | None = None,
                    mark_dirty: bool = True) -> int:
        label = label or {}
        raw = raw or {}
        with self.conn() as db:
            cur = db.execute("""
                INSERT INTO training_samples(source_type,game,issue,numbers,label_json,confidence,used_for_training,raw_json,created_at)
                VALUES(?,?,?,?,?,?,?,?,?)
            """, (source_type, game, issue, numbers, json.dumps(label, ensure_ascii=False), float(confidence or 0), 0,
                  json.dumps(raw, ensure_ascii=False), now_str()))
            sid = int(cur.lastrowid)
        if mark_dirty and game:
            try:
                LotteryModelStore(game).mark_dirty(DB.count_lottery_records(game))
            except Exception:
                pass
        return sid

    def save_ocr_result(self, game: str, issue: str, numbers: str, ocr_text: str,
                        confidence: float = 0.0, engine: str = "online_ocr") -> int:
        return self.save_sample(
            "ocr_ticket", game, issue, numbers,
            label={"kind": "ocr", "engine": engine},
            confidence=confidence,
            raw={"ocr_text": ocr_text, "engine": engine},
            mark_dirty=False,
        )

    def save_qr_ticket(self, game: str, issue: str, numbers: str, qr_content: str,
                       ocr_text: str = "", ticket_no: str = "", check_result: dict | None = None) -> int:
        check_result = check_result or {}
        with self.conn() as db:
            cur = db.execute("""
                INSERT INTO ticket_check_records(game,issue,ticket_no,numbers,draw_numbers,hit_json,prize_level,prize_amount,qr_content,ocr_text,raw_json,created_at)
                VALUES(?,?,?,?,?,?,?,?,?,?,?,?)
            """, (
                game, issue, ticket_no, numbers, str(check_result.get("draw_numbers", "")),
                json.dumps(check_result.get("hit", {}), ensure_ascii=False),
                str(check_result.get("prize_level", "")), float(check_result.get("prize_amount", 0) or 0),
                qr_content, ocr_text, json.dumps(check_result, ensure_ascii=False), now_str()
            ))
            tid = int(cur.lastrowid)
        self.save_sample("qr_ticket", game, issue, numbers, {"kind": "ticket_check", "ticket_id": tid}, 1.0,
                         {"qr_content": qr_content, "check_result": check_result}, mark_dirty=False)
        return tid

    def save_betting_record(self, game: str, issue: str, numbers: str, amount: float = 0.0,
                            bet_type: str = "", source: str = "manual", raw: dict | None = None) -> int:
        raw = raw or {}
        with self.conn() as db:
            cur = db.execute("""
                INSERT INTO betting_records_v218(game,issue,numbers,amount,bet_type,source,checked,result_json,raw_json,created_at)
                VALUES(?,?,?,?,?,?,?,?,?,?)
            """, (game, issue, numbers, float(amount or 0), bet_type, source, 0, "{}", json.dumps(raw, ensure_ascii=False), now_str()))
            bid = int(cur.lastrowid)
        self.save_sample("betting_record", game, issue, numbers, {"kind": "betting", "bet_id": bid}, 1.0, raw, mark_dirty=False)
        return bid

    @staticmethod
    def _hit_score(game: str, predicted: str, draw: str) -> tuple[int, int, float, dict]:
        pred_rec = {"开奖号码": predicted}
        draw_rec = {"开奖号码": draw}
        pm, ps = parse_lottery_numbers(game, pred_rec)
        dm, ds = parse_lottery_numbers(game, draw_rec)
        main_hit = len(set(pm) & set(dm))
        sub_hit = len(set(ps) & set(ds)) if (ps or ds) else 0
        cfg = LOTTERY_LIMITS.get(game, {})
        denom = max(1, int(cfg.get("main_need", len(dm) or 1)) + int(cfg.get("sub_need", len(ds) or 0)))
        score = round((main_hit + sub_hit) / denom, 6)
        return main_hit, sub_hit, score, {"pred_main": pm, "pred_sub": ps, "draw_main": dm, "draw_sub": ds}

    def evaluate_lottery_prediction(self, game: str, issue: str, prediction_id: int,
                                    predicted_numbers: str, draw_numbers: str) -> dict:
        main_hit, sub_hit, score, detail = self._hit_score(game, predicted_numbers, draw_numbers)
        raw = {"detail": detail, "source": "phase6_auto_eval"}
        with self.conn() as db:
            db.execute("""
                INSERT INTO prediction_evaluations(game,issue,prediction_id,predicted_numbers,draw_numbers,main_hit,sub_hit,score,raw_json,created_at)
                VALUES(?,?,?,?,?,?,?,?,?,?)
            """, (game, issue, prediction_id, predicted_numbers, draw_numbers, main_hit, sub_hit, score,
                  json.dumps(raw, ensure_ascii=False), now_str()))
        return {"game": game, "issue": issue, "main_hit": main_hit, "sub_hit": sub_hit, "score": score}

    def auto_evaluate_lottery_predictions(self, game: str = "") -> dict:
        """用已保存开奖，自动核对尚未核对的预测日志。"""
        done = 0
        skipped = 0
        with self.conn() as db:
            wh = "WHERE target_issue IS NOT NULL AND target_issue!=''"
            params: list[Any] = []
            if game:
                wh += " AND game=?"; params.append(game)
            rows = db.execute(f"SELECT id,game,target_issue,numbers FROM lottery_prediction_log {wh} ORDER BY id DESC LIMIT 1000", tuple(params)).fetchall()
            for pid, g, issue, nums in rows:
                exists = db.execute("SELECT 1 FROM prediction_evaluations WHERE prediction_id=? LIMIT 1", (pid,)).fetchone()
                if exists:
                    skipped += 1; continue
                draw = db.execute("SELECT numbers FROM history_records WHERE game=? AND issue=?", (g, issue)).fetchone()
                if not draw:
                    skipped += 1; continue
                self.evaluate_lottery_prediction(g, issue, int(pid), str(nums), str(draw[0]))
                done += 1
        return {"evaluated": done, "skipped": skipped, "game": game or "全部"}

    def evaluate_sports_recommendations(self, mode: str = "jingcai") -> dict:
        done = 0
        skipped = 0
        with self.conn() as db:
            recs = db.execute("""
                SELECT id,mode,match_no,home_team,away_team,pick,ev,confidence,raw_json
                FROM sports_recommend_history WHERE mode=? ORDER BY id DESC LIMIT 1000
            """, (mode,)).fetchall()
            for rid, m, no, h, a, pick, evv, conf, raw in recs:
                try:
                    payload = json.loads(raw or "{}")
                    event_key = str(payload.get("event_key") or "")
                except Exception:
                    event_key = ""
                exists = db.execute("SELECT 1 FROM sports_prediction_evaluations WHERE event_key=? AND match_no=? AND pick=? LIMIT 1", (event_key, no, pick)).fetchone()
                if exists:
                    skipped += 1; continue
                row = None
                if event_key:
                    row = db.execute("SELECT home_score,away_score FROM sports_matches WHERE event_key=? AND home_score IS NOT NULL AND away_score IS NOT NULL", (event_key,)).fetchone()
                if not row:
                    row = db.execute("""
                        SELECT home_score,away_score FROM sports_matches
                        WHERE mode=? AND match_no=? AND home_team=? AND away_team=? AND home_score IS NOT NULL AND away_score IS NOT NULL
                        LIMIT 1
                    """, (m, no, h, a)).fetchone()
                if not row:
                    skipped += 1; continue
                hs, aw = int(row[0]), int(row[1])
                actual = "主胜" if hs > aw else "平" if hs == aw else "客胜"
                hit = 1 if str(pick) == actual else 0
                db.execute("""
                    INSERT INTO sports_prediction_evaluations(event_key,mode,match_no,pick,actual_result,hit,ev,confidence,raw_json,created_at)
                    VALUES(?,?,?,?,?,?,?,?,?,?)
                """, (event_key, m, no, pick, actual, hit, float(evv or 0), float(conf or 0), raw or "{}", now_str()))
                done += 1
        return {"evaluated": done, "skipped": skipped, "mode": mode}

    def summary(self) -> dict:
        with self.conn() as db:
            def one(sql, args=()):
                try: return int(db.execute(sql, args).fetchone()[0])
                except Exception: return 0
            by_source = {}
            for src, cnt in db.execute("SELECT source_type,COUNT(*) FROM training_samples GROUP BY source_type").fetchall():
                by_source[str(src)] = int(cnt)
            by_game = {}
            for g, cnt in db.execute("SELECT game,COUNT(*) FROM training_samples GROUP BY game").fetchall():
                by_game[str(g)] = int(cnt)
            return {
                "training_samples": one("SELECT COUNT(*) FROM training_samples"),
                "ticket_checks": one("SELECT COUNT(*) FROM ticket_check_records"),
                "betting_records": one("SELECT COUNT(*) FROM betting_records_v218"),
                "lottery_evaluations": one("SELECT COUNT(*) FROM prediction_evaluations"),
                "sports_evaluations": one("SELECT COUNT(*) FROM sports_prediction_evaluations"),
                "samples_by_source": by_source,
                "samples_by_game": by_game,
            }

    def text_report(self) -> str:
        s = self.summary()
        lines = ["🔗 V218 Phase6 全功能训练数据联动报告", "生成时间：" + now_str(), ""]
        lines.append("训练样本总数：%d" % s["training_samples"])
        lines.append("验票记录：%d" % s["ticket_checks"])
        lines.append("投注记录：%d" % s["betting_records"])
        lines.append("数字彩预测核对：%d" % s["lottery_evaluations"])
        lines.append("足彩推荐核对：%d" % s["sports_evaluations"])
        lines.append("\n样本来源：")
        if s["samples_by_source"]:
            for k, v in sorted(s["samples_by_source"].items()):
                lines.append("  %s：%d" % (k, v))
        else:
            lines.append("  暂无")
        lines.append("\n彩种样本：")
        if s["samples_by_game"]:
            for k, v in sorted(s["samples_by_game"].items()):
                lines.append("  %s：%d" % (k, v))
        else:
            lines.append("  暂无")
        lines.append("\n规则：所有功能只保存训练/评分样本；不会自动训练。点击AI训练中心才训练。")
        return "\n".join(lines)


TRAINING_LINK = TrainingDataLinkCenter()

