def phase6_record_qr_ticket(game: str, issue: str, numbers: str, qr_content: str, ocr_text: str = "", ticket_no: str = "", check_result: dict | None = None) -> dict:
    tid = TRAINING_LINK.save_qr_ticket(game, issue, numbers, qr_content, ocr_text, ticket_no, check_result or {})
    return {"ok": True, "ticket_id": tid, "message": "二维码验票记录已保存，不触发训练"}


