# UI 扩展：新增“🔗 训练数据联动”页。
def _phase6_install_ui():
    try:
        cls = V218MainWindow
    except Exception:
        return
    if getattr(cls, "_phase6_ui_installed", False):
        return
    old_build = cls._build_ui

    def _build_ui_phase6(self, *args, **kwargs):
        old_build(self, *args, **kwargs)
        try:
            tab = QWidget(); lay = QVBoxLayout(tab)
            tip = QLabel("🔗 OCR、二维码验票、投注记录、预测核对都会保存为训练/评分样本；不会自动训练。")
            tip.setWordWrap(True); lay.addWidget(tip)
            row = QHBoxLayout(); lay.addLayout(row)
            self.phase6_game_cb = QComboBox(); self.phase6_game_cb.addItems([""] + LOTTERY_GAMES)
            row.addWidget(QLabel("彩种")); row.addWidget(self.phase6_game_cb)
            for text, action in [
                ("刷新报告", "report"),
                ("核对数字彩预测", "check_lottery"),
                ("核对足彩推荐", "check_sports"),
                ("模拟保存OCR样本", "demo_ocr"),
                ("模拟保存投注记录", "demo_bet"),
            ]:
                b = QPushButton(text)
                b.clicked.connect(lambda checked=False, a=action: self.phase6_run(a))
                row.addWidget(b)
            self.phase6_output = QTextEdit(); self.phase6_output.setReadOnly(True); lay.addWidget(self.phase6_output, 1)
            try:
                self.tabs.addTab(tab, "🔗 训练数据联动")
            except Exception:
                pass
            self.phase6_run("report")
        except Exception:
            log_error(traceback.format_exc())

    def phase6_run(self, action: str):
        game = self.phase6_game_cb.currentText() if hasattr(self, "phase6_game_cb") else ""
        out = getattr(self, "phase6_output", None)
        def set_text(s):
            if out: out.setPlainText(str(s))
        def append(s):
            if out: out.append(str(s))
        try:
            if action == "report":
                set_text(TRAINING_LINK.text_report()); return
            if action == "check_lottery":
                set_text("开始核对数字彩预测日志...\n")
                res = TRAINING_LINK.auto_evaluate_lottery_predictions(game)
                append(json.dumps(res, ensure_ascii=False, indent=2))
                append("\n" + TRAINING_LINK.text_report())
                return
            if action == "check_sports":
                set_text("开始核对足彩推荐日志...\n")
                res = TRAINING_LINK.evaluate_sports_recommendations("jingcai")
                append(json.dumps(res, ensure_ascii=False, indent=2))
                append("\n" + TRAINING_LINK.text_report())
                return
            if action == "demo_ocr":
                g = game or "快乐8"
                res = phase6_record_ocr_ticket(g, "", "06 16 20 23 26 33 39 65 71 76", "快乐8·选十·单式 A.06 16 20 23 26 33 39 65 71 76", 0.98)
                set_text(json.dumps(res, ensure_ascii=False, indent=2) + "\n\n" + TRAINING_LINK.text_report())
                return
            if action == "demo_bet":
                g = game or "双色球"
                res = phase6_record_betting(g, "", "01 06 12 18 22 31 + 08", 2.0, "单式", "manual_demo")
                set_text(json.dumps(res, ensure_ascii=False, indent=2) + "\n\n" + TRAINING_LINK.text_report())
                return
        except Exception as e:
            set_text("执行失败：%s\n%s" % (e, traceback.format_exc()))

    cls._build_ui = _build_ui_phase6
    cls.phase6_run = phase6_run
    cls._phase6_ui_installed = True

try:
    _phase6_install_ui()
except Exception:
    log_error(traceback.format_exc())




# ============================================================
# V218 PHASE7 — 稳定任务中心 / 训练任务排队 / 数据质量闸门
# ============================================================
# 本阶段目标：
# 1) 所有更新、训练、预测、核对动作统一进入任务日志；
# 2) 训练任务排队，防重复点击、防并发训练；
# 3) 数据质量不达标时不强行训练，只提示修复；
# 4) 生成可读的问题清单，方便手机端定位。

PHASE7_TASK_DB_READY = False

class Phase7TaskStore:
    def __init__(self, db_file: Path = DB_FILE):
        self.db_file = db_file
        self._ensure()

    def _ensure(self):
        global PHASE7_TASK_DB_READY
        try:
            with sqlite3.connect(str(self.db_file)) as db:
                db.execute("""
                    CREATE TABLE IF NOT EXISTS task_log (
                        id INTEGER PRIMARY KEY AUTOINCREMENT,
                        created_at TEXT,
                        finished_at TEXT,
                        category TEXT,
                        action TEXT,
                        game TEXT,
                        status TEXT,
                        progress INTEGER,
                        message TEXT,
                        raw_json TEXT
                    )
                """)
                db.execute("""
                    CREATE TABLE IF NOT EXISTS data_quality_log (
                        id INTEGER PRIMARY KEY AUTOINCREMENT,
                        created_at TEXT,
                        scope TEXT,
                        game TEXT,
                        level TEXT,
                        issue TEXT,
                        detail TEXT,
                        fixed INTEGER DEFAULT 0
                    )
                """)
            PHASE7_TASK_DB_READY = True
        except Exception:
            PHASE7_TASK_DB_READY = False
            log_error(traceback.format_exc())

    def add_task(self, category: str, action: str, game: str = "", message: str = "") -> int:
        now = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        try:
            with sqlite3.connect(str(self.db_file)) as db:
                cur = db.execute("""
                    INSERT INTO task_log(created_at,finished_at,category,action,game,status,progress,message,raw_json)
                    VALUES (?,?,?,?,?,?,?,?,?)
                """, (now, "", category, action, game, "pending", 0, message, "{}"))
                return int(cur.lastrowid)
        except Exception:
            log_error(traceback.format_exc())
            return 0

    def update_task(self, task_id: int, status: str = "running", progress: int = 0,
                    message: str = "", raw: Optional[dict] = None):
        if not task_id:
            return
        finished = datetime.now().strftime("%Y-%m-%d %H:%M:%S") if status in ("success", "failed", "cancelled") else ""
        try:
            with sqlite3.connect(str(self.db_file)) as db:
                db.execute("""
                    UPDATE task_log SET finished_at=?, status=?, progress=?, message=?, raw_json=? WHERE id=?
                """, (finished, status, int(progress), message, json.dumps(raw or {}, ensure_ascii=False), int(task_id)))
        except Exception:
            log_error(traceback.format_exc())

    def recent_tasks(self, limit: int = 80) -> list[dict]:
        try:
            with sqlite3.connect(str(self.db_file)) as db:
                rows = db.execute("""
                    SELECT id,created_at,finished_at,category,action,game,status,progress,message
                    FROM task_log ORDER BY id DESC LIMIT ?
                """, (int(limit),)).fetchall()
            return [{
                "id": r[0], "created_at": r[1], "finished_at": r[2], "category": r[3],
                "action": r[4], "game": r[5], "status": r[6], "progress": r[7], "message": r[8]
            } for r in rows]
        except Exception:
            return []

    def add_quality_issue(self, scope: str, game: str, level: str, issue: str, detail: str = ""):
        try:
            with sqlite3.connect(str(self.db_file)) as db:
                db.execute("""
                    INSERT INTO data_quality_log(created_at,scope,game,level,issue,detail,fixed)
                    VALUES (?,?,?,?,?,?,0)
                """, (datetime.now().strftime("%Y-%m-%d %H:%M:%S"), scope, game, level, issue, detail))
        except Exception:
            log_error(traceback.format_exc())

    def recent_quality(self, limit: int = 120) -> list[dict]:
        try:
            with sqlite3.connect(str(self.db_file)) as db:
                rows = db.execute("""
                    SELECT created_at,scope,game,level,issue,detail,fixed
                    FROM data_quality_log ORDER BY id DESC LIMIT ?
                """, (int(limit),)).fetchall()
            return [{"created_at": r[0], "scope": r[1], "game": r[2], "level": r[3], "issue": r[4], "detail": r[5], "fixed": r[6]} for r in rows]
        except Exception:
            return []


PHASE7_STORE = Phase7TaskStore()

class Phase7DataQualityGate:
    """训练前质量闸门：数据不够、号码异常、重复过多时，只提示，不强训。"""
    MIN_HISTORY = {
        "双色球": 200, "大乐透": 200, "七乐彩": 150, "快乐8": 200,
        "福彩3D": 300, "3D": 300, "排列三": 300, "排列五": 300, "七星彩": 180,
        "福建36选7": 80, "福建31选7": 80, "福建22选5": 80,
    }

    @staticmethod
    def lottery_history_rows(game: str) -> list[dict]:
        try:
            store = DataStore()
            return store.load_history(game, limit=999999)
        except Exception:
            return []

    @classmethod
    def check_lottery_game(cls, game: str) -> dict:
        rows = cls.lottery_history_rows(game)
        issues = []
        seen = set()
        dup = 0
        empty_nums = 0
        for r in rows:
            issue = str(r.get("issue") or r.get("期号") or "").strip()
            nums = str(r.get("numbers") or r.get("开奖号码") or "").strip()
            if issue in seen:
                dup += 1
            if issue:
                seen.add(issue)
            if not nums:
                empty_nums += 1
        min_need = cls.MIN_HISTORY.get(game, 100)
        status = "ok"
        if len(rows) < min_need:
            status = "blocked"
            issues.append(f"历史期数不足：{len(rows)}/{min_need}")
        if empty_nums:
            status = "warning" if status == "ok" else status
            issues.append(f"存在空开奖号码：{empty_nums}条")
        if dup:
            status = "warning" if status == "ok" else status
            issues.append(f"存在重复期号：{dup}条")
        result = {"game": game, "status": status, "history_count": len(rows), "duplicate": dup, "empty_numbers": empty_nums, "issues": issues}
        if issues:
            for x in issues:
                PHASE7_STORE.add_quality_issue("lottery", game, "error" if status == "blocked" else "warning", x, json.dumps(result, ensure_ascii=False))
        return result

    @staticmethod
    def check_sports_history() -> dict:
        try:
            with sqlite3.connect(str(DB_FILE)) as db:
                total = db.execute("SELECT COUNT(*) FROM sports_matches").fetchone()[0]
                finished = db.execute("SELECT COUNT(*) FROM sports_matches WHERE result IS NOT NULL AND result<>''").fetchone()[0]
                no_odds = db.execute("SELECT COUNT(*) FROM sports_matches WHERE odds_json IS NULL OR odds_json='' OR odds_json='{}'").fetchone()[0]
        except Exception:
            total = finished = no_odds = 0
        issues = []
        status = "ok"
        if finished < 300:
            status = "blocked"
            issues.append(f"带赛果历史不足：{finished}/300")
        if no_odds:
            issues.append(f"缺赔率记录：{no_odds}场")
            if status == "ok": status = "warning"
        result = {"status": status, "total": total, "finished": finished, "no_odds": no_odds, "issues": issues}
        for x in issues:
            PHASE7_STORE.add_quality_issue("sports", "竞彩足球", "error" if status == "blocked" else "warning", x, json.dumps(result, ensure_ascii=False))
        return result

    @classmethod
    def full_report(cls) -> str:
        lines = ["🔍 V218 Phase7 数据质量闸门", ""]
        for g in LOTTERY_GAMES:
            r = cls.check_lottery_game(g)
            mark = "✅" if r["status"] == "ok" else "⛔" if r["status"] == "blocked" else "⚠️"
            lines.append(f"{mark} {g}：历史{r['history_count']}期，重复{r['duplicate']}，空号{r['empty_numbers']}")
            for i in r["issues"][:3]:
                lines.append("   - " + i)
        sp = cls.check_sports_history()
        mark = "✅" if sp["status"] == "ok" else "⛔" if sp["status"] == "blocked" else "⚠️"
        lines.append("")
        lines.append(f"{mark} 足彩：总{sp['total']}场，带赛果{sp['finished']}场，缺赔率{sp['no_odds']}场")
        for i in sp["issues"]:
            lines.append("   - " + i)
        return "\n".join(lines)


class Phase7TrainingQueue:
    """轻量训练任务队列：记录任务、串行执行入口；真正训练仍使用原有中心。"""
    def __init__(self):
        self.running = False
        self.pending: list[dict] = []

    def enqueue_lottery_train(self, game: str) -> int:
        q = Phase7DataQualityGate.check_lottery_game(game)
        task_id = PHASE7_STORE.add_task("lottery", "train", game, "等待训练")
        item = {"task_id": task_id, "type": "lottery_train", "game": game, "quality": q}
        self.pending.append(item)
        return task_id

    def enqueue_sports_train(self) -> int:
        q = Phase7DataQualityGate.check_sports_history()
        task_id = PHASE7_STORE.add_task("sports", "train", "竞彩足球", "等待训练")
        self.pending.append({"task_id": task_id, "type": "sports_train", "game": "竞彩足球", "quality": q})
        return task_id

    def run_next_sync(self) -> dict:
        if self.running:
            return {"ok": False, "message": "已有训练任务进行中"}
        if not self.pending:
            return {"ok": False, "message": "没有待执行任务"}
        item = self.pending.pop(0)
        self.running = True
        tid = item["task_id"]
        try:
            q = item.get("quality") or {}
            if q.get("status") == "blocked":
                PHASE7_STORE.update_task(tid, "failed", 100, "数据质量不足，已阻止训练", q)
                return {"ok": False, "message": "数据质量不足，已阻止训练", "quality": q}
            PHASE7_STORE.update_task(tid, "running", 5, "开始执行", q)
            if item["type"] == "lottery_train":
                center = LotteryTrainCenter()
                res = center.train_game(item["game"])
                PHASE7_STORE.update_task(tid, "success" if res.get("ok", True) else "failed", 100, res.get("message", "训练完成"), res)
                return res
            if item["type"] == "sports_train":
                center = SportsTrainCenter()
                res = center.train_model()
                PHASE7_STORE.update_task(tid, "success" if res.get("ok", True) else "failed", 100, res.get("message", "训练完成"), res)
                return res
            PHASE7_STORE.update_task(tid, "failed", 100, "未知任务类型", item)
            return {"ok": False, "message": "未知任务类型"}
        except Exception as e:
            PHASE7_STORE.update_task(tid, "failed", 100, str(e), {"traceback": traceback.format_exc()})
            return {"ok": False, "message": str(e)}
        finally:
            self.running = False


PHASE7_QUEUE = Phase7TrainingQueue()

class Phase7ReportCenter:
    @staticmethod
    def task_report() -> str:
        rows = PHASE7_STORE.recent_tasks(80)
        lines = ["🧾 最近任务日志", ""]
        if not rows:
            lines.append("暂无任务。")
        for r in rows[:50]:
            lines.append(f"#{r['id']} [{r['status']}] {r['created_at']} {r['category']}/{r['action']} {r['game']} {r['progress']}% {r['message']}")
        return "\n".join(lines)

    @staticmethod
    def quality_report() -> str:
        rows = PHASE7_STORE.recent_quality(120)
        lines = ["🧪 最近质量问题", ""]
        if not rows:
            lines.append("暂无质量问题记录。")
        for r in rows[:80]:
            lines.append(f"[{r['level']}] {r['created_at']} {r['scope']} {r['game']}：{r['issue']}")
        return "\n".join(lines)

    @staticmethod
    def full_report() -> str:
        return Phase7DataQualityGate.full_report() + "\n\n" + Phase7ReportCenter.task_report()


# ---- Phase7 UI 安装 ----
def _phase7_install_ui():
    try:
        cls = V218MainWindow
    except Exception:
        return
    if getattr(cls, "_phase7_ui_installed", False):
        return
    old_build = cls._build_ui

    def _build_ui_phase7(self, *args, **kwargs):
        old_build(self, *args, **kwargs)
        try:
            tab = QWidget(); lay = QVBoxLayout(tab)
            title = QLabel("🧩 Phase7 稳定任务中心：训练排队、数据质量闸门、任务日志")
            lay.addWidget(title)
            row = QHBoxLayout(); lay.addLayout(row)
            self.phase7_game_cb = QComboBox(); self.phase7_game_cb.addItems(LOTTERY_GAMES)
            row.addWidget(QLabel("彩种")); row.addWidget(self.phase7_game_cb)
            btn_check = QPushButton("🔍 数据质量检查")
            btn_task = QPushButton("🧾 任务日志")
            btn_q = QPushButton("🧪 质量问题")
            btn_add_l = QPushButton("➕ 加入当前彩种训练")
            btn_add_s = QPushButton("➕ 加入足彩训练")
            btn_run = QPushButton("▶ 执行下一个任务")
            for b in (btn_check, btn_task, btn_q, btn_add_l, btn_add_s, btn_run):
                row.addWidget(b)
            self.phase7_output = QTextEdit(); self.phase7_output.setReadOnly(True); lay.addWidget(self.phase7_output, 1)
            btn_check.clicked.connect(lambda: self.phase7_run("check"))
            btn_task.clicked.connect(lambda: self.phase7_run("tasks"))
            btn_q.clicked.connect(lambda: self.phase7_run("quality"))
            btn_add_l.clicked.connect(lambda: self.phase7_run("enqueue_lottery"))
            btn_add_s.clicked.connect(lambda: self.phase7_run("enqueue_sports"))
            btn_run.clicked.connect(lambda: self.phase7_run("run_next"))
            try:
                self.tabs.addTab(tab, "🧩 稳定任务")
            except Exception:
                pass
            self.phase7_run("check")
        except Exception:
            log_error(traceback.format_exc())

    def phase7_run(self, action: str):
        out = getattr(self, "phase7_output", None)
        game = self.phase7_game_cb.currentText() if hasattr(self, "phase7_game_cb") else "双色球"
        def set_text(x):
            if out: out.setPlainText(str(x))
        try:
            if action == "check":
                set_text(Phase7DataQualityGate.full_report()); return
            if action == "tasks":
                set_text(Phase7ReportCenter.task_report()); return
            if action == "quality":
                set_text(Phase7ReportCenter.quality_report()); return
            if action == "enqueue_lottery":
                tid = PHASE7_QUEUE.enqueue_lottery_train(game)
                set_text(f"已加入训练队列：{game}，任务ID={tid}\n\n" + Phase7ReportCenter.task_report()); return
            if action == "enqueue_sports":
                tid = PHASE7_QUEUE.enqueue_sports_train()
                set_text(f"已加入足彩训练队列，任务ID={tid}\n\n" + Phase7ReportCenter.task_report()); return
            if action == "run_next":
                res = PHASE7_QUEUE.run_next_sync()
                set_text(json.dumps(res, ensure_ascii=False, indent=2) + "\n\n" + Phase7ReportCenter.task_report()); return
        except Exception as e:
            set_text("执行失败：%s\n%s" % (e, traceback.format_exc()))

    cls._build_ui = _build_ui_phase7
    cls.phase7_run = phase7_run
    cls._phase7_ui_installed = True

try:
    _phase7_install_ui()
except Exception:
    log_error(traceback.format_exc())


# ============================================================
# 自检与启动
# ============================================================

def selftest() -> None:
    assert cn_team("Manchester City") == "曼城"
    assert implied_from_odds(2.1, 3.3, 3.6)
    assert LotteryPredictCenter.format_numbers("双色球", [1,2,3,4,5,6], [8]) == "01 02 03 04 05 06 + 08"
    assert LotteryFeatureExtractor("双色球")._ac_value([1,2,4,8,16,32]) >= 0
    assert isinstance(LotteryWeightManager().build_weights({}), dict)
    assert LotteryTrainingDashboard().row_for_game("双色球")["game"] == "双色球"
    sid = TRAINING_LINK.save_sample("selftest", "双色球", "", "01 02 03 04 05 06 + 07", {"test": True}, 1.0, {}, mark_dirty=False)
    assert isinstance(sid, int) and sid > 0
    assert TRAINING_LINK.summary()["training_samples"] >= 1
    q = Phase7DataQualityGate.check_lottery_game("双色球")
    assert "status" in q and "history_count" in q
    tid = PHASE7_QUEUE.enqueue_lottery_train("双色球")
    assert isinstance(tid, int)
    assert isinstance(Phase7ReportCenter.task_report(), str)
    print("V218 phase7 stability task center selftest passed")


